  -webkit-mask-image: radial-gradient(circle closest-side, rgba(0,0,0,1) 50%, rgba(0,0,0,0) 100%);
  mask-image: radial-gradient(circle closest-side, rgba(0,0,0,1) 50%, rgba(0,0,0,0) 100%);
