/* 🌟 容器基础设定 */
.mz-android-widget {
  width: 100%;
  height: 100%;
  position: relative;
  overflow: hidden;
  box-sizing: border-box;
  border-radius: 18px;
  background: transparent;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: space-between;
  padding: 8px 0;
  font-family: sans-serif;
  -webkit-user-select: none;
  user-select: none;
}

/* 舞台区域 */
.stage-box {
  width: 100%;
  flex: 1;
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  perspective: 700px;
  transform-style: preserve-3d;
}

/* 完美自适应卡片 */
.card-item {
  position: absolute;
  width: clamp(65px, 22%, 95px);
  aspect-ratio: 1 / 1.18;
  background-color: rgba(255, 255, 255, 0.65);

  /* 🌟 卡片毛玻璃特效 */
  -webkit-backdrop-filter: blur(16px);
  backdrop-filter: blur(16px);

  border-radius: 10px;
  border: 1px solid rgba(255, 255, 255, 0.4);
  box-shadow: 0 4px 15px rgba(0,0,0,0.08);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: space-between;
  padding: 6px;
  box-sizing: border-box;
  transition: transform 0.4s cubic-bezier(0.25, 0.8, 0.25, 1), opacity 0.4s ease, z-index 0.4s step-start;
  cursor: pointer;

  /* 🌟 终极防溢出 Hack：切断边缘渲染泄露 */
  overflow: hidden;
  background-clip: padding-box;
  isolation: isolate;

  backface-visibility: hidden;
  -webkit-backface-visibility: hidden;
}

.img-wrap {
  width: 100%;
  aspect-ratio: 1 / 1;
  border-radius: 6px;
  overflow: hidden;
  background: rgba(0,0,0,0.05);
  flex-shrink: 0;
}

.card-item img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.card-item img[src=""], .card-item img:not([src]) {
  display: none !important;
}

/* 歌名锁定底部 */
.song-name {
  width: 100%;
  margin-top: 2px;
  font-size: var(--song-size, 11px);
  color: #ffffff;
  font-weight: 700;
  text-align: center;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  text-shadow: 0 1px 2px rgba(0,0,0,0.4);
}

/* 3D 深度位置 */
.pos-0 { transform: translateX(0) translateZ(25px) scale(1); z-index: 10; opacity: 1; }
.pos-1 { transform: translateX(65%) translateZ(-40px) scale(0.85); z-index: 5; opacity: 0.8; }
.pos--1 { transform: translateX(-65%) translateZ(-40px) scale(0.85); z-index: 5; opacity: 0.8; }
.pos-2 { transform: translateX(115%) translateZ(-80px) scale(0.68); z-index: 1; opacity: 0.4; pointer-events: none; }
.pos--2 { transform: translateX(-115%) translateZ(-80px) scale(0.68); z-index: 1; opacity: 0.4; pointer-events: none; }

/* 底部控制舱毛玻璃特效 */
.bottom-panel {
  width: 88%;
  height: 36px;
  background: var(--panel-bg, rgba(255, 255, 255, 0.25));
  -webkit-backdrop-filter: blur(20px) saturate(150%);
  backdrop-filter: blur(20px) saturate(150%);
  border-radius: 12px;
  border: 1px solid rgba(255, 255, 255, 0.35);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 12px;
  box-sizing: border-box;
  z-index: 30;
  flex-shrink: 0;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.1);

  /* 🌟 防溢出 Hack */
  overflow: hidden;
  background-clip: padding-box;
  isolation: isolate;
}

.panel-left, .panel-right {
  display: flex;
  align-items: center;
  gap: 10px;
}
.panel-right { justify-content: flex-end; }

.panel-center {
  flex: 1;
  text-align: center;
  color: var(--brand-color, #ffffff);
  font-size: var(--brand-size, 11px);
  font-weight: 600;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  background: transparent !important;
}

.ctrl-icon {
  width: 16px;
  height: 16px;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
}
.ctrl-icon svg {
  width: 100%;
  height: 100%;
  fill: var(--icon-color, #ffffff);
}
.ctrl-icon:active {
  transform: scale(0.85);
}

.heart-solid { display: none; fill: #ff2d55 !important; }
.ctrl-icon.liked .heart-hollow { display: none; }
.ctrl-icon.liked .heart-solid { display: block; }

.ctrl-icon[data-mode="0"] .mode-1, .ctrl-icon[data-mode="0"] .mode-2 { display: none; }
.ctrl-icon[data-mode="1"] .mode-0, .ctrl-icon[data-mode="1"] .mode-2 { display: none; }
.ctrl-icon[data-mode="2"] .mode-0, .ctrl-icon[data-mode="2"] .mode-1 { display: none; }

