* { box-sizing: border-box; margin: 0; padding: 0; }

body {
  width: 100%; height: 100%;
  overflow: hidden;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, "PingFang SC", "Microsoft YaHei", sans-serif;
}

/*⁣‌⁠⁠​⁠⁠⁠‌‍‍​​​⁠‍⁠‌‌​‍‍‍‌‌​‌⁠‍⁠⁠‍‌​⁠⁠‍⁠‌‍‌‍⁠​⁠⁠⁠⁠‍​⁠‍‍​​‌‍⁠‌⁠‍​​‌‍⁣⁣‍⁠‌​​​⁠‌⁠⁠‌‌‌‍​‌⁠‍⁠​​‌​‌‍‌‌⁠‌‍‌​⁠‍‌‍‌⁠‌‌⁠​‌‌‍‌⁠‌​‌​⁠‍⁠‌⁠‍‍‍‍​⁠⁠‌⁣ 车票主容器，填满整个 2x2 组件 */
.ticket {
  width: 100%; height: 100%;
  background: #fcfcfc;
  border-radius: 10px;
  padding: 8px 10px; /* 2x2 尺寸适当缩小内边距 */
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  position: relative;
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.05), inset 0 0 0 1px rgba(0,0,0,0.02);

  /* 车票两侧打孔效果 - 尺寸适配缩小打孔半径 */
  mask-image: radial-gradient(circle at 0 50%, transparent 5px, black 6px),
              radial-gradient(circle at 100% 50%, transparent 5px, black 6px);
  mask-composite: intersect;
  -webkit-mask-image: radial-gradient(circle at 0 50%, transparent 5px, black 6px),
                      radial-gradient(circle at 100% 50%, transparent 5px, black 6px);
  -webkit-mask-composite: source-in;
}

/* 顶部信息 */
.row-between { display: flex; justify-content: space-between; align-items: flex-end; }

.airline { font-size: 8px; font-weight: 700; color: #222; letter-spacing: 0.2px; }
.class { font-size: 7px; font-weight: 600; color: #555; }
.time { font-size: 8px; font-weight: 700; color: #111; font-family: monospace, sans-serif; }

/* 起降机场 */
.route { display: flex; justify-content: space-between; align-items: center; margin-top: 1px; }
.station { flex: 1; display: flex; flex-direction: column; }
.station.right { text-align: right; }

.label { 
  font-size: 6px; 
  color: #999; 
  text-transform: uppercase; 
  letter-spacing: 0.3px; 
  margin-bottom: 1px; 
  font-family: monospace, sans-serif;
}

.code { 
  font-size: 16px; 
  font-weight: 800; 
  letter-spacing: 0.3px; 
  color: #111; 
  line-height: 1; 
  font-family: monospace, sans-serif;
}

/* 飞机图标样式 */
.plane { 
  margin: 0 4px; 
  display: flex; 
  align-items: center; 
  justify-content: center;
  color: #c0c0c6; 
}
.plane svg { 
  width: 10px; 
  height: 10px; 
  fill: currentColor; 
  transform: rotate(90deg); 
}

/* 车票虚线分割线 */
.divider { 
  border-bottom: 1px dashed #dcdcdc; 
  margin: 3px 0; 
}

/* 乘客姓名 */
.passenger { display: flex; flex-direction: column; }
.passenger .name { 
  font-size: 12px; 
  font-weight: 700; 
  color: #111; 
  letter-spacing: 0.2px; 
  font-family: monospace, "PingFang SC", "Microsoft YaHei", sans-serif;
}

/* 底部信息 */
.bottom-row { display: flex; justify-content: space-between; }
.bottom-item { flex: 1; display: flex; flex-direction: column; }
.bottom-item:nth-child(2) { align-items: center; }
.bottom-item:nth-child(3) { align-items: flex-end; }
.bottom-item .value { 
  font-size: 11px; 
  font-weight: 700; 
  color: #111; 
  line-height: 1; 
  margin-top: 1px; 
  font-family: monospace, sans-serif;
}

* {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    /*⁣‌⁠⁠​⁠⁠⁠‌‍‍​​​⁠‍⁠‌‌​‍‍‍‌‌​‌⁠‍⁠⁠‍‌​⁠⁠‍⁠‌‍‌‍⁠​⁠⁠⁠⁠‍​⁠‍‍​​‌‍⁠‌⁠‍​​‌‍⁣⁣‍⁠‌​​​⁠‌⁠⁠‌‌‌‍​‌⁠‍⁠​​‌​‌‍‌‌⁠‌‍‌​⁠‍‌‍‌⁠‌‌⁠​‌‌‍‌⁠‌​‌​⁠‍⁠‌⁠‍‍‍‍​⁠⁠‌⁣ 阻止长按选中和菜单 */
    user-select: none;
    -webkit-user-select: none;
    -webkit-touch-callout: none;
}
html, body {
    width: 100%;
    height: 100%;
    background-color: transparent;
    overflow: hidden;
    user-select: none;
    -webkit-user-select: none;
    -webkit-touch-callout: none;
}
/* 4×2 尺寸适配 */
.route-card {
    width: 100%;
    height: 100%;
    background: var(--bg-color, #ffffff);
    border-radius: 20px;
    padding: 14px 12px 12px 12px;
    box-shadow: 0 10px 24px rgba(0, 0, 0, 0.06);
    display: flex;
    flex-direction: column;
    justify-content: space-between;
    transition: background 0.3s ease, color 0.3s ease;
}
.route-body {
    display: flex;
    gap: 12px;
    width: 100%;
    margin-bottom: 6px;
    flex: 1;
}
.route-indicator {
    display: flex;
    flex-direction: column;
    align-items: center;
    padding-top: 16px;
    width: 10px;
    flex-shrink: 0;
}
.dot-from {
    width: 6px;
    height: 6px;
    background-color: var(--text-main, #111);
    border-radius: 50%;
    transition: background 0.3s ease;
}
.line {
    width: 2px;
    background: repeating-linear-gradient(to bottom, var(--line-color, #cbd5e1) 0px, var(--line-color, #cbd5e1) 6px, transparent 6px, transparent 12px);
    flex-grow: 1;
    margin: 2px 0;
    animation: dashMove 1s linear infinite;
}
@keyframes dashMove {
    0% { background-position: 0 0; }
    100% { background-position: 0 12px; }
}
.dot-to {
    width: 8px;
    height: 8px;
    background-color: var(--bg-color, #ffffff);
    border: 2px solid var(--text-main, #111);
    border-radius: 50%;
    transition: background 0.3s ease, border-color 0.3s ease;
}
.route-content {
    flex: 1;
    display: flex;
    flex-direction: column;
    min-width: 0;
}
.route-row {
    display: flex;
    flex-direction: column;
    gap: 4px;
    padding-bottom: 10px;
}
.to-row {
    padding-top: 10px;
    padding-bottom: 0;
}
.divider {
    height: 1px;
    background-color: var(--divider-color, #f0f0f0);
    width: 100%;
    transition: background 0.3s ease;
}
.row-label {
    font-size: 10px;
    color: var(--text-sub, #a0a0a0);
    font-weight: 700;
    letter-spacing: 0.5px;
    transition: color 0.3s ease;
}
.row-main {
    display: flex;
    justify-content: space-between;
    align-items: center;
    gap: 8px;
    width: 100%;
}
.row-text {
    font-size: 13px;
    font-weight: 600;
    color: var(--text-main, #111);
    overflow: hidden;
    white-space: nowrap;
    text-overflow: ellipsis;
    flex: 1;
    transition: color 0.3s ease;
}
.action-btn {
    width: 26px;
    height: 26px;
    background-color: var(--btn-bg, #f4f4f6);
    border-radius: 6px;
    display: flex;
    justify-content: center;
    align-items: center;
    flex-shrink: 0;
    cursor: pointer;
    transition: transform 0.1s, background 0.3s ease;
}
.action-btn:active {
    transform: scale(0.9);
}
.action-btn svg {
    width: 14px;
    height: 14px;
    /* 👇 已修改：将 stroke 绑定到主字体颜色 --text-main */
    stroke: var(--text-main, #4a4a4a);
    fill: none;
    stroke-width: 3.5;
    stroke-linecap: round;
    stroke-linejoin: round;
    transition: stroke 0.3s ease;
}
.saved-routes {
    display: flex;
    align-items: center;
    gap: 4px;
    color: var(--text-sub, #a0a0a0);
    font-size: 10px;
    font-weight: 600;
    cursor: pointer;
    margin-top: 4px;
    transition: color 0.3s ease;
}
.saved-icon {
    font-size: 12px;
    line-height: 1;
}

* {
