}

/*⁣‍⁠‌​​​⁠‌⁠⁠‌‌‌‍​‌⁠‍⁠​​‌​‌‍‌‌⁠‌‍‌​⁠‍‌‍‌⁠‌‌⁠​‌‌‍‌⁠‌​‌​⁠‍⁠‌⁠‍‍‍‍​⁠⁠‌⁣ ⭐ 定义全局变量 */
:root {
  --bg-color: transparent;       /* 整体底色 */
  --theme-color: #111111;        /* 字体颜色 */
  --card-bg-color: #ffffff;      /* 卡片/方框底色 */
}

.widget-container {
  width: 100%;
  height: 100%;
  background: var(--bg-color);   /* 动态背景 */
  transition: background 0.3s ease; 
  border-radius: 16px;
  padding: 8px;
  display: flex;
  flex-direction: column;
  gap: 4px;
  overflow: hidden;
}

/* ================= 顶部标题 ================= */
.widget-title {
  font-size: 14px;
  font-weight: 800;
  color: var(--theme-color);    /* 动态字体颜色 */
  letter-spacing: 1px;
  line-height: 1.2;
}

.widget-content {
  display: flex;
  flex: 1;
  gap: 6px;
  overflow: hidden;
}

.left-panel {
  flex: 1.1;
  background: var(--card-bg-color); /* 动态卡片底色 */
  border-radius: 10px;
  overflow: hidden;
  display: flex;
  justify-content: center;
  align-items: flex-end;
}

.left-panel img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.right-panel {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 4px;
  overflow: hidden;
}

.info-card {
  background: var(--card-bg-color); /* 动态卡片底色 */
  border-radius: 10px;
  padding: 5px;
  flex: 1.2;
  display: flex;
  flex-direction: column;
  justify-content: flex-start;
  overflow: hidden;
}

/* 时间显示 */
.info-card h2 {
  font-size: 9px;
  color: var(--theme-color);   /* 动态字体颜色 */
  font-weight: bold;
  line-height: 1.2;
  margin-bottom: 2px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  display: block;
  width: 100%;
}

/* 文本内容 */
.info-card p {
  font-size: 8px;      
  color: var(--theme-color);   /* 动态字体颜色 */
  line-height: 1.35;   
  word-break: normal;
  word-wrap: break-word;
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.decor-card {
  background: var(--card-bg-color); /* 动态卡片底色 */
  border-radius: 10px;
  flex: 1;
  overflow: hidden;
}

.decor-card img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  opacity: 0.9;
}

/* ========== 动态小溪波浪线 ========== */
.widget-footer {
  width: 100%;
  height: 20px;
  overflow: hidden;
  position: relative;
