  gap: 6px; flex-shrink: 0;
}

/* 🌟 头像稍微缩小一点比例，防止把底下的昵称挤出屏幕 */
.avatar-wrap {
  position: relative; width: 72%; aspect-ratio: 1/1; 
  border-radius: 50%; 
  border: 1.5px solid #ffffff; 
}
.avatar-wrap img { width: 100%; height: 100%; object-fit: cover; border-radius: 50%; display: block; }

/* 符号徽章 */
.plus-badge {
  position: absolute; bottom: -2px; right: -6px;
  width: clamp(18px, 5.5vw, 22px); height: clamp(18px, 5.5vw, 22px);
  background-color: #000000; border-radius: 50%;
  border: 1.5px solid #ffffff; display: flex; align-items: center; justify-content: center;
}
.plus-badge::before, .plus-badge::after {
  content: ''; position: absolute; background-color: #ffffff; border-radius: 1px;
}
.plus-badge::before { width: 10px; height: 2px; }
.plus-badge::after { width: 2px; height: 10px; }

/* 🌟 昵称样式 */
.nickname {
  font-size: clamp(10px, 2.8vw, 13px); font-weight: 600; color: var(--text-color);
  text-align: center; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 100%;
  padding: 0 2px;
}

/* 图片列 (无阴影) */
.img-col {
  flex: 1; height: 100%; border-radius: 10px; overflow: hidden;
  background: rgba(255,255,255,0.3); 
}
.img-col img { width: 100%; height: 100%; object-fit: cover; display: block; }

/* ================= 底部：文案与按钮 ================= */
.bottom-section {
  height: clamp(30px, 8vw, 38px);
  display: flex; align-items: center; justify-content: space-between; gap: clamp(10px, 3vw, 16px);
}

/* 胶囊文案框 (独立毛玻璃) */
.text-pill {
  flex: 1; height: 100%; position: relative;
  border-radius: 999px; display: flex; align-items: center; justify-content: center;
  padding: 0 clamp(10px, 3vw, 16px); box-sizing: border-box; min-width: 0; 
  background: rgba(255, 255, 255, 0.25); 
  backdrop-filter: blur(12px); -webkit-backdrop-filter: blur(12px); 
}

/* 智能变淡跟随边框 */
.text-pill::after {
  content: ''; position: absolute; inset: 0;
  border-radius: 999px; pointer-events: none;
  border: 1.5px solid var(--text-color); 
  opacity: 0.4; 
}

.text-pill span {
  font-size: clamp(10px, 2.5vw, 12px); color: var(--text-color); font-weight: 600;
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
  position: relative; z-index: 2;
}

/* 右侧图标组 */
.icon-group {
  width: 32%; height: 100%; display: flex; align-items: center; justify-content: space-between;
}
.icon-btn {
  width: clamp(20px, 5.5vw, 24px); height: clamp(20px, 5.5vw, 24px);
  background-color: var(--icon-color);
  -webkit-mask-size: contain; mask-size: contain;
  -webkit-mask-repeat: no-repeat; mask-repeat: no-repeat;
  -webkit-mask-position: center; mask-position: center;
}

.i-heart {
  -webkit-mask-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 24 24' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M12 21.35l-1.45-1.32C5.4 15.36 2 12.28 2 8.5 2 5.42 4.42 3 7.5 3c1.74 0 3.41.81 4.5 2.09C13.09 3.81 14.76 3 16.5 3 19.58 3 22 5.42 22 8.5c0 3.78-3.4 6.86-8.55 11.54L12 21.35z'/%3E%3C/svg%3E");
  mask-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 24 24' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M12 21.35l-1.45-1.32C5.4 15.36 2 12.28 2 8.5 2 5.42 4.42 3 7.5 3c1.74 0 3.41.81 4.5 2.09C13.09 3.81 14.76 3 16.5 3 19.58 3 22 5.42 22 8.5c0 3.78-3.4 6.86-8.55 11.54L12 21.35z'/%3E%3C/svg%3E");
}
.i-headphone {
  -webkit-mask-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 24 24' xmlns='http://www.w3.org/2000/svg' fill='none' stroke='black' stroke-width='2' stroke-linecap='round' stroke-linejoin='round'%3E%3Cpath d='M3 18v-6a9 9 0 0 1 18 0v6'/%3E%3Cpath d='M21 19a2 2 0 0 1-2 2h-1v-4h3v2zM3 19a2 2 0 0 0 2 2h1v-4H3v2z'/%3E%3C/svg%3E");
  mask-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 24 24' xmlns='http://www.w3.org/2000/svg' fill='none' stroke='black' stroke-width='2' stroke-linecap='round' stroke-linejoin='round'%3E%3Cpath d='M3 18v-6a9 9 0 0 1 18 0v6'/%3E%3Cpath d='M21 19a2 2 0 0 1-2 2h-1v-4h3v2zM3 19a2 2 0 0 0 2 2h1v-4H3v2z'/%3E%3C/svg%3E");
}
