:root {
--header-btn-gap: -4px;
/* === 全局背景 === */
--chat-bg-color: #ffffff;
/* === 顶栏 === */
--chat-header-height: 65px;
--chat-header-bg: rgba(255, 255, 255, 1);
--chat-header-blur: 20px;
--chat-header-border: 1px #dee2e6; /* 浅紫灰 -> 浅灰 */
--chat-header-title-color: #212529; /* 深紫灰 -> 深黑灰 */
--chat-header-title-size: 15px;
--chat-header-subtitle-size: 12px;
--chat-header-icon-color: #868e96; /* 中紫灰 -> 中灰 */
/* === 顶栏头像 === */
--chat-header-avatar-size: 48px;
--chat-header-avatar-radius: 50%;
--chat-header-avatar-border: none; 

/* === 底栏输入区 === */
--input-area-bg: #ffffff;
--input-area-blur: 20px;
--input-area-border-top: 1px solid #dee2e6;
--input-box-bg: #ffffff;
--input-box-border: 1px solid #dee2e6;
--input-box-color: #212529;
--input-box-radius: 24px;
--send-btn-color: #868e96;
--plus-btn-color: #868e96;
/* === 气泡通用 === */
--bubble-them-padding: 8px 14px;
--bubble-me-padding: 8px 14px;
/* === 对方气泡（左） === */
--bubble-them-bg: #f8f9fa;
--bubble-them-border: 1px solid #dee2e6;
--bubble-them-color: #212529;
--bubble-them-radius: 7px;
/* === 我方气泡（右） === */
--bubble-me-bg: #f1f3f5; /* 极浅紫 -> 浅灰 */
--bubble-me-border: 1px solid #dee2e6;
--bubble-me-color: #212529;
--bubble-me-radius: 7px;
/* === 独立引用条 === */
--reply-detached-bg: #ffffff;
--reply-detached-radius: 6px;
--reply-detached-padding: 6px 12px;
--reply-detached-border-left: none;
--reply-detached-filter: drop-shadow(0 1px 3px #dee2e6);
--reply-detached-name-suffix: "：";
--reply-detached-align-items: baseline;
--reply-detached-name-size: 11px;
--plain-avatar-size: 40px;
}
/* === 顶栏自定义文案 & 名字前加@ === */
.chat-header-title::after {
content: "₊⁺淡淡的就会顺顺的⁺‧₊";
display: block;
font-size: 12px;
color: #868e96;
font-weight: normal;
margin-top: 0px;
transform: translateX(2px);
}
.chat-header-title::before {
content: "@";
margin-right: 2px;
color: #868e96;
font-weight: normal;
}
/* === 顶栏头像整体往左挪 === */
.header-profile-section {
margin-left: -16px !important;
transform: translateY(2px) !important;
}
/* === 顶栏头像：变圆 + 留白缝隙 + 蓝色外框 === */
.header-avatar-container {
border-radius: 50% !important;
background-color: #ffffff !important;
padding: 2px !important;
border: 2px solid #c7c7c7 !important; /* 亮紫 -> 浅灰 */
position: relative !important;
overflow: visible !important;
transform: translateY(-4px) !important;
}
.header-avatar-container img,
.chat-header-avatar {
border-radius: 50% !important;
}
/* === 顶栏头像右下角的打钩圆圈 === */
.header-avatar-container::after {
content: "✓";
position: absolute;
bottom: -1px;
right: -6px;
width: 14px;
height: 14px;
background-color: #dedede; /* 柔紫 -> 浅灰 */
color: #fff;
font-size: 11px;
font-weight: bold;
