bottom: -16px; 
right: 8px;    
}
/* === 聊天区头像加圆框 === */
.msg-avatar-them-inner,
.msg-avatar-me-inner {
border: 1px solid #c7c7c7 !important; /* 亮紫 -> 浅灰 */
padding: 2px !important;
background-color: #ffffff !important;
box-sizing: border-box !important;
border-radius: 50% !important;
}
/* 把里面的图片也强制变圆 */
.msg-avatar-them-inner img,
.msg-avatar-me-inner img {
border-radius: 50% !important;
}

/* === 头像往上挪一点 === */
.msg-avatar-them-container,
.msg-avatar-me-container {
  margin-top: -12px !important; 
}

/* === 保证和上一组消息的距离 === */
.msg-bubble-wrapper.is-first,
.msg-bubble-wrapper.is-single {
  margin-top: 18px !important; 
}
/* === 强行画上顶栏图标 === */
/* 1. 确保按钮全放出来，覆盖掉可能残留的隐藏代码 */
.header-btn-phone, .header-btn-video, .header-btn-info {
  display: flex !important;
  background-size: 18px !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
  width: 36px !important;
  height: 36px !important;
}
/* 2. 把系统自带的图标变透明 */
.header-btn-phone svg, .header-btn-video svg, .header-btn-info svg {
  opacity: 0 !important;
}
/* 3. 画上空心爱心（电话） */
.header-btn-phone {
  background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='%23dee2e6' stroke-width='2' stroke-linecap='round' stroke-linejoin='round'><path d='M20.84 4.61a5.5 5.5 0 0 0-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 0 0-7.78 7.78l1.06 1.06L12 21.23l7.78-7.78 1.06-1.06a5.5 5.5 0 0 0 0-7.78z'/></svg>") !important; /* 柔紫 -> 浅灰 */
transform: translateX(3px) !important;
}
/* 4. 画上实心爱心（视频） */
.header-btn-video {
  background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='%23dee2e6'><path d='M12 21.35l-1.45-1.32C5.4 15.36 2 12.28 2 8.5 2 5.42 4.42 3 7.5 3c1.74 0 3.41.81 4.5 2.09C13.09 3.81 14.76 3 16.5 3 19.58 3 22 5.42 22 8.5c0 3.78-3.4 6.86-8.55 11.54L12 21.35z'/></svg>") !important;
transform: translateX(3px) !important;
}
/* 5. 画上竖排三个点（设置） */
.header-btn-info {
  background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='%23dee2e6'><circle cx='12' cy='4' r='1.8'/><circle cx='12' cy='12' r='1.8'/><circle cx='12' cy='20' r='1.8'/></svg>") !important;
  transform: translateX(4px) !important;
}
/* 强行给顶栏加底边框（单线） */
.chat-header-custom {
border-bottom: 1px solid #dee2e6 !important;
}
/* 1. 加号键自由定位 */
:root {
--btn-plus-translate-y: -50px; 
--btn-plus-translate-x: 0px;  
}
/* 2. 换输入框文案 & 解决重影 */
.input-box-custom::placeholder {
color: transparent !important;
-webkit-text-fill-color: transparent !important;
}
.input-action-bar-custom {
position: relative !important;
background: transparent !important; 
border: none !important; 
}
.input-box-custom {
background: #ffffff !important; 
border: 1px solid #dee2e6 !important; /* 柔紫边框 -> 浅灰 */
border-radius: 24px !important;
}
/* 自定义文案 */
.input-action-bar-custom::before {
content: ">ㅅ<人你有点萌萌呦! ⊹.";
position: absolute;
left: 82px;
top: 50%;
transform: translateY(-50%);
color: rgba(134, 142, 150, 0.6); /* 亮紫半透明 -> 中灰半透明 */
pointer-events: none;
z-index: 10;
font-size: 14px;
}
/* 打字时让新文案消失 */
.input-action-bar-custom:has(.input-box-custom:not(:placeholder-shown))::before {
display: none;
}

/* 单独调左右位置 */
.input-btn-mic {
right: 52px !important; 
}
.input-btn-sticker {
right: 10px !important; 
}/* === 星星魔法核心 === */
/* 1. 屏蔽原生图标 */
.input-btn-plus svg, .input-btn-ai svg, .send-btn-custom svg {
opacity: 0 !important;
}
/* 2. 加号键：永远是实心星星，并暴力向上移 */
.input-btn-plus {
background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='%23dee2e6'><path d='M12 2l3.09 6.26L22 9.27l-5 4.87 1.18 6.88L12 17.77l-6.18 3.25L7 14.14 2 9.27l6.91-1.01L12 2z'/></svg>") !important;
background-size: 26px !important;
background-repeat: no-repeat !important;
background-position: center !important;
}
/* 3. 发送键：实心星星，去底色 */
.send-btn-custom {
background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='%23dee2e6'><path d='M12 2l3.09 6.26L22 9.27l-5 4.87 1.18 6.88L12 17.77l-6.18 3.25L7 14.14 2 9.27l6.91-1.01L12 2z'/></svg>") !important;
background-size: 26px !important;
background-repeat: no-repeat !important;
background-position: center !important;
background-color: transparent !important;
transform: translateX(10px) !important; 
}
/* 4. AI键（默认不打字时）：实心星星，在外面 */
.input-btn-ai {
background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='%23dee2e6'><path d='M12 2l3.09 6.26L22 9.27l-5 4.87 1.18 6.88L12 17.77l-6.18 3.25L7 14.14 2 9.27l6.91-1.01L12 2z'/></svg>") !important;
background-size: 26px !important;
background-repeat: no-repeat !important;
background-position: center !important;
transition: all 0.2s ease !important; 
transform: translateX(10px) !important; 
}
/* 5. AI键（打字时）：变成空心星星，脱离占位，钻进胶囊 */
.input-action-bar-custom:has(.input-box-custom:not(:placeholder-shown)) .input-btn-ai {
position: absolute !important; 
right: 60px !important; 
background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='%23dee2e6' stroke-width='2' stroke-linecap='round' stroke-linejoin='round'><polygon points='12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26 12 2'/></svg>") !important;
background-size: 24px !important; 
z-index: 10 !important;

}
/* === 语音和表情的双拼悬浮小胶囊（终极版） === */
/* 1. 隐藏原生图标 */
.input-btn-mic svg, .input-btn-sticker svg {
display: none !important;
}
/* 2. 语音键（左半边） */
.input-btn-mic {
position: absolute !important;
top: -55px !important; 
right: 60px !important; 
background: rgba(255, 255, 255, 0.6) !important; 
backdrop-filter: blur(10px) !important;
-webkit-backdrop-filter: blur(10px) !important;
border: 1px solid #dee2e6 !important; 
border-radius: 20px 0 0 20px !important;
width: 50px !important;
height: 24px !important;
box-shadow: -2px 2px 6px rgba(0,0,0,0.02) !important;
transform: translateX(10px) !important;
}
.input-btn-mic::after {
content: "Voice";
font-size: 10px;
color: #868e96;
position: absolute;
top: 50%; left: 50%;
transform: translate(-50%, -50%);
}
/* 3. 表情键（右半边） */
.input-btn-sticker {
position: absolute !important;
top: -55px !important;
right: 10px !important;
background: rgba(255, 255, 255, 0.6) !important;
backdrop-filter: blur(10px) !important;
-webkit-backdrop-filter: blur(10px) !important;
border: 1px solid #dee2e6 !important;
border-left: none !important; 
border-radius: 0 20px 20px 0 !important;
width: 50px !important;
height: 24px !important;
box-shadow: 2px 2px 6px rgba(0,0,0,0.02) !important;
transform: translateX(10px) !important;
}
.input-btn-sticker::after {
content: "Memes";
font-size: 10px;
color: #868e96;
position: absolute;
top: 50%; left: 50%;
transform: translate(-50%, -50%);
}

/* 解决打字时字和星星重叠 */
.input-action-bar-custom:has(.input-box-custom:not(:placeholder-shown)) .input-box-custom {
padding-right: 52px !important;
}
/* 1. 左边星星往上提一点，让它视觉居中 */
.input-btn-plus {
transform: translate(2px, -3px) !important; 
}
/* 2. 胶囊整体往左挪，修正偏右的问题 */
.input-action-bar-custom {
transform: translateX(-4px) !important; 
}
/* === 控制台专属配色（作者原味版） === */
.nuo-console-toggle-bar, .nuo-console-toggle-btn {
--console-toggle-bg: #f8f9fa;
--console-toggle-color: #212529;
}
.nuo-console-panel {
--console-panel-bg: rgba(248, 249, 250, 0.96);
--console-panel-color: #212529;
}
/* 层级稍微压低一点，免得打架 */
.nuo-console-shell {
--console-shell-z: 10;
}

/* === 2. 我方最后一条消息智能避让胶囊 === */
/* 只有在输入框为空（胶囊存在）时，才往上顶。打字时胶囊消失，气泡自动掉下来 */
.chat-detail-screen:has(.input-box-custom:placeholder-shown) [data-absolute-last="true"][data-sender="me"] {
margin-bottom: 30px !important; 
}
/* === 2. 胶囊智能躲避：让 CSS 自己做加法（修复重叠bug） === */
.chat-detail-screen {
--offset-reply: 0px;
--offset-sendas-char: 0px;
--offset-sendas-narr: 0px;
--offset-console: 0px;
}
/* 各自独立报身高，绝不混淆 */
.chat-detail-screen:has(.input-reply-preview-bar) { --offset-reply: 50px; }
.chat-detail-screen:has(.input-sendas-char-bar) { --offset-sendas-char: 40px; }
.chat-detail-screen:has(.input-sendas-narration-bar) { --offset-sendas-narr: 40px; }
.chat-detail-screen:has(.nuo-console-shell) { --offset-console: 45px; }
/* 胶囊自动往上飞，高度 = 所有出现的条的高度总和 */
.input-btn-mic, .input-btn-sticker {
margin-top: calc(-1 * (var(--offset-reply) + var(--offset-sendas-char) + var(--offset-sendas-narr) + var(--offset-console))) !important;
/* 胶囊自动往上飞，并强行统一两半边的动画 */
.input-btn-mic, .input-btn-sticker {
margin-top: calc(-1 * (var(--offset-reply) + var(--offset-sendas-char) + var(--offset-sendas-narr) + var(--offset-console))) !important;
transition: all 0.2s cubic-bezier(0.25, 0.8, 0.25, 1) !important;}
}
/* 控制台出现时，保证胶囊在最上层不被盖住 */
.chat-detail-screen:has(.nuo-console-shell) .input-btn-mic,
.chat-detail-screen:has(.nuo-console-shell) .input-btn-sticker {
z-index: 50 !important;
}

/* === 3. 我方气泡避让胶囊 === */
/* 没打字（胶囊在）时，气泡往上躲 30px；一打字（胶囊消失），气泡自动掉下来 */
.chat-detail-screen:has(.input-box-custom:placeholder-shown) [data-absolute-last="true"][data-sender="me"] {
margin-bottom: 30px !important;
transition: margin-bottom 0.2s ease !important; 
}
/* === 气泡底部便签虚线（首尾封边 + 左右分色版） === */
/* 1. 给第一条、最后一条、单条气泡腾出底部空间 */
.msg-bubble-wrapper.is-first .bubble-them-custom,
.msg-bubble-wrapper.is-last .bubble-them-custom,
.msg-bubble-wrapper.is-single .bubble-them-custom,
.msg-bubble-wrapper.is-first .bubble-me-custom,
.msg-bubble-wrapper.is-last .bubble-me-custom,
.msg-bubble-wrapper.is-single .bubble-me-custom {
position: relative !important;
padding-bottom: 10px !important;
}

/* 2. 对方气泡（左边）的虚线：稍微加深一点的灰（用半透明黑） */
.msg-bubble-wrapper.is-first .bubble-them-custom::after,
.msg-bubble-wrapper.is-last .bubble-them-custom::after,
.msg-bubble-wrapper.is-single .bubble-them-custom::after {
content: "";
position: absolute;
left: 12px;
right: 12px;
bottom: 7px;
border-bottom: 1px dashed rgba(0, 0, 0, 0.12) !important; 
pointer-events: none;
}
/* 3. 我方气泡（右边）的虚线：专属紫色加透明度 -> 换成灰 */
.msg-bubble-wrapper.is-first .bubble-me-custom::after,
.msg-bubble-wrapper.is-last .bubble-me-custom::after,
.msg-bubble-wrapper.is-single .bubble-me-custom::after {
content: "";
position: absolute;
left: 12px;
right: 12px;
bottom: 7px;
border-bottom: 1px dashed rgba(134, 142, 150, 0.6) !important; 
pointer-events: none;
}
/* === 独立翻译条（往内缩 + 紫色统一版） === */
:root {
--translation-always-show: 1;
}
.msg-translation-wrapper { display: none !important; }

.msg-translation-detached {
display: block !important;
margin-top: 4px !important;
}

/* 对方的翻译整体往右挪一点 */
.msg-translation-detached-them {
margin-left: 4px !important; 
}

/* 文字变成浅紫色 -> 浅灰 */
.msg-translation-detached-content {
background: transparent !important;
color: #868e96 !important; 
padding: 4px 0 4px 12px !important;
font-size: 13px !important;
position: relative !important;
box-shadow: none !important;
}

/* 竖条也变成一样的浅紫色 -> 浅灰 */
.msg-translation-detached-content::before {
content: "" !important;
position: absolute !important;
left: 0 !important;
top: 6px !important;
bottom: 6px !important;
width: 4px !important;
border-radius: 4px !important;
background-color: #868e96 !important; 
}

/* 把装了图片/表情包的气泡背景和边框变透明（排除引用框里的图片） */
.bubble-me-custom:has(img:not(.msg-reply-block-detached img):not(.msg-reply-block img)),
.bubble-them-custom:has(img:not(.msg-reply-block-detached img):not(.msg-reply-block img)) {
background: transparent !important;
border: none !important;
box-shadow: none !important;
padding: 0 !important;
}
/* 去掉图片/表情包底部的虚线（同样排除） */
.bubble-me-custom:has(img:not(.msg-reply-block-detached img):not(.msg-reply-block img))::after,
.bubble-them-custom:has(img:not(.msg-reply-block-detached img):not(.msg-reply-block img))::after {
display: none !important;
}
/* 控制图片大小 + 修复位置 */
.msg-bubble-container img {
max-width: 110px !important; 
max-height: 170px !important;
width: auto !important;
height: auto !important;
object-fit: contain !important;
border-radius: 8px !important;
}
/* 我发的图片靠右贴头像 */
.msg-me .msg-bubble-container img {
display: block !important;
margin-left: auto !important;
}
/* 对方发的图片靠左贴头像 */
.msg-them .msg-bubble-container img {
display: block !important;
margin-right: auto !important;
}
/* 强制缩小引用框里的图片并裁成正方形 */
.msg-bubble-wrapper .msg-reply-block-detached img,
.msg-reply-detached-text img {
    width: 28px !important;
    height: 28px !important;
    max-width: 28px !important; 
    max-height: 28px !important;
    object-fit: cover !important; 
    aspect-ratio: 1 / 1 !important; 
    border-radius: 3px !important;
    vertical-align: middle !important;
    display: inline-block !important;
    margin: 0 4px !important;
}
/* 引用框内容顶部齐平 */
.msg-reply-block-detached {
    align-items: flex-start !important; 
}
/* 名字稍微往下压一点，和图片视觉边缘对齐 */
.msg-reply-detached-name {
    margin-top: 0px !important; 
}

/* ================================================
   仿QQ主题 · 古早草莓味
   · 文案可自定义
   · 禁二传
   ================================================ */

/* ================= :root 变量层 ================= */
:root {
  /* === 全局背景 === */
  --chat-bg-color: transparent;
  --chat-bg-image: url("https://s1.imagehub.cc/images/2026/07/11/7a2df723e61cb48afcb72a98e4a1b12e.png");

  /* === 顶部导航栏 === */
  --chat-header-bg: #FFF9FB;
  --chat-header-bg-image: url("https://s1.imagehub.cc/images/2026/07/11/4edf75d518136b10e0624b3f51da8f86.png");
  --chat-header-bg-size: 100% auto;
  --chat-header-bg-position: center top;
  --chat-header-blur: 0px;
  --chat-header-border: #FFD8E3;
  --chat-header-height: 80px;
  --chat-header-title-color: #704F5B;
  --chat-header-title-size: 14px;
  --chat-header-title-weight: 800;
  --chat-header-subtitle-color: #A38C94;
  --chat-header-subtitle-size: 9px;
  --chat-header-icon-color: #A38C94;
  --chat-header-avatar-size: 0px;
  --chat-header-avatar-border: none;
  --chat-header-avatar-radius: 0;
  --header-btn-gap: 20px;

  /* === 我方气泡 === */
  --bubble-me-bg: #FFFFFF;
  --bubble-me-color: #704F5B;
  --bubble-me-font-size: 11px;
  --bubble-me-line-height: 1.3;
  --bubble-me-padding: 3px 8px;
  --bubble-me-radius: 20px;
  --bubble-me-radius-first: 20px;
  --bubble-me-radius-mid: 20px;
  --bubble-me-radius-last: 20px;
  --bubble-me-border: 1.6px solid #FFE4F1;
  --bubble-me-shadow: none;
  --bubble-me-link-color: #704F5B;

  /* === 对方气泡 === */
  --bubble-them-bg: #FFFFFF;
  --bubble-them-color: #704F5B;
  --bubble-them-font-size: 11px;
  --bubble-them-line-height: 1.3;
  --bubble-them-padding: 3px 8px;
  --bubble-them-radius: 20px;
  --bubble-them-radius-first: 20px;
  --bubble-them-radius-mid: 20px;
  --bubble-them-radius-last: 20px;
  --bubble-them-border: 1.6px solid #FFE4F1;
  --bubble-them-shadow: none;
  --bubble-them-link-color: #704F5B;

  /* === 时间戳 === */
  --timestamp-color: #FFBBD0;
  --timestamp-size: 10px;
  --timestamp-weight: 400;

  /* === 日期分隔线 === */
  --date-divider-bg: transparent;
  --date-divider-color: #FFBBD0;
  --date-divider-size: 10px;

  /* === 输入区域（不改变输入框位置） === */
  --input-area-bg: #FFF9FB;
  --input-area-bg-image: url("https://s1.imagehub.cc/images/2026/07/11/6ea7f58577d4004326dabd78627250df.png");
  --input-area-bg-size: 100% auto;
  --input-area-bg-position: center bottom;
  --input-area-blur: 0px;
  --input-area-border-top: none;
  --input-area-min-height: 95px;

  /* === 输入框 === */
  --input-box-bg: transparent;
  --input-box-color: #704F5B;
  --input-box-font-size: 16px;
  --input-box-border: none;
  --input-box-placeholder: transparent;
  --input-box-radius: 0;
  --input-box-shadow: none;

  /* === 底栏按钮（隐形但可点击） === */
  --send-btn-bg: transparent;
  --send-btn-color: transparent;
  --send-btn-shadow: none;
  --plus-btn-bg: transparent;
  --plus-btn-color: transparent;
  --input-btn-color: transparent;

  /* === 引用 & 回复 === */
  --reply-block-bg: #FFFFFF;
  --reply-block-radius: 12px;
  --reply-block-padding: 4px 8px;
  --reply-block-border: 1.2px solid #FFD6EA;
  --reply-block-name-color: #704F5B;
  --reply-block-text-color: #704F5B;

  /* === 回复预览栏 === */
  --reply-bar-accent: #FFD8E3;
  --reply-bar-text-color: #FFBBD0;

  /* === 旁白消息（与引用框同色系）=== */
  --narration-color: #704F5B;
  --narration-size: 9px;
  --narration-weight: 400;
  --narration-style: italic;
  --narration-line-height: 1.3;
  --narration-padding: 4px 10px;
  --narration-margin: 6px 32px;
  --narration-bg: #FFFDFE;
  --narration-radius: 20px;
  --narration-border: 1px solid #FFD8E3;
  --narration-shadow: none;
  --narration-text-align: center;
  --narration-opacity: 0.9;
  --narration-max-width: 90%;

  /* === 转账卡片（与气泡同色系）=== */
  --transfer-card-bg: #FFFFFF;
  --transfer-card-radius: 20px;
  --transfer-card-shadow: none;
  --transfer-card-border: 1.6px solid #FFE4F1;
  --transfer-icon-bg: #FFF0F6;
  --transfer-amount-color: #704F5B;
  --transfer-me-card-bg: #FFFFFF;
  --transfer-me-card-border: 1.6px solid #FFE4F1;
  --transfer-me-icon-bg: #FFF0F6;
