/* ====================================================
16. 素净模式 (Plain) 100% 还原 uwu 的排版逻辑
==================================================== */
.msg-bubble-wrapper {
  position: relative !important;
  width: 100% !important;
}

.msg-plain-me, .msg-plain-them {
  display: inline-block !important;
  width: max-content !important;
