  background-size: calc(50% - 75px) 1px, calc(50% - 75px) 1px !important; /* 📱 适配修改：75px 控制两边线留给中间字母的空白距离宽度 */
  background-position: left center, right center !important; background-repeat: no-repeat !important;
}

/* ==========================================
   7. 👑 【底栏微醺层与文字】 
   ========================================== */
.input-area-custom {
  background-image: linear-gradient(rgba(250, 248, 245, 0.35), rgba(250, 248, 245, 0.35)), var(--chat-bg-image) !important; 
  background-size: cover !important; background-position: center bottom !important; 
  backdrop-filter: blur(25px) saturate(190%) !important; -webkit-backdrop-filter: blur(25px) saturate(190%) !important;
  position: relative !important; z-index: 10 !important; display: flex !important; flex-direction: column !important;
  border-top: 1px solid rgba(255, 255, 255, 0.3) !important; box-shadow: 0 -10px 40px rgba(0, 0, 0, 0.03) !important;
}

/* 🌟 底栏文字装饰 */
.input-area-custom::after {
  content: "✦   FILTERS   •   ADJUST   •   EFFECTS   ✦" !important; /* 📱 适配修改：底栏最下方的英文字母 */
  position: absolute !important; 
  top: 92px !important; /* 📱 适配修改：字母距离底栏顶部的距离，如果被按键挡住可以调大 */
  left: 50% !important; transform: translateX(-50%) !important; white-space: nowrap !important; font-family: ui-monospace, SFMono-Regular, monospace !important; font-size: 9.5px !important; font-weight: 800 !important; 
  color: #3a3a3c !important; letter-spacing: 1.5px !important; pointer-events: none !important; z-index: 999 !important;
}

/* ==========================================
   8. 🍎 滤镜小图视觉分布 & 彻底透明化
   ========================================== */
.input-btn-mic, .send-btn-custom, .stop-btn-custom, .input-btn-sticker, .input-btn-ai {
  position: absolute !important; 
  top: 18px !important; /* 📱 适配修改：5张小图的统一高度位置 */
  width: 60px !important; /* 📱 适配修改：小图宽度 */
  height: 60px !important; /* 📱 适配修改：小图高度 */
  opacity: 1 !important; z-index: 1000 !important; cursor: pointer !important; margin: 0 !important; padding: 0 !important; min-height: unset !important; min-width: unset !important; transform: none !important; 
  border-radius: 8px !important; 
  /* 🌟 日间专属纯白高光边框 */
  border: 2px solid #ffffff !important; 
  box-shadow: 0 4px 14px rgba(0, 0, 0, 0.12) !important; 
  transition: transform 0.2s cubic-bezier(0.4, 0, 0.2, 1) !important;
  -webkit-appearance: none !important; appearance: none !important; outline: none !important;
}

.input-btn-mic:hover, .send-btn-custom:hover, .input-btn-sticker:hover, .input-btn-ai:hover { transform: scale(1.04) !important; }

/* 其他三键正常渲染 */
.input-btn-mic { left: calc(50% - 100px) !important; background: var(--filter-2) center/cover no-repeat !important; } 
.input-btn-sticker { left: calc(50% + 40px) !important; background: var(--filter-4) center/cover no-repeat !important; } 
.input-btn-ai { left: calc(50% + 110px) !important; background: var(--filter-5) center/cover no-repeat !important; } 

/* 🚀 宇宙最高优先级：死磕发送键图3！ */
html body .input-area-custom .send-btn-custom, 
html body .input-area-custom .stop-btn-custom,
.send-btn-custom:active,
.send-btn-custom:focus,
.send-btn-custom:not([disabled]) { 
  left: calc(50% - 30px) !important; 
  background: transparent var(--filter-3) center/cover no-repeat !important; 
  background-color: transparent !important; 
  border: 2px solid #ffffff !important; 
  box-shadow: 0 4px 14px rgba(0, 0, 0, 0.12) !important;
  visibility: visible !important; opacity: 1 !important;
} 
/* 把打字时系统塞进来的所有蒙版全部隐藏 */
html body .input-area-custom .send-btn-custom *, 
html body .input-area-custom .stop-btn-custom *, 
.send-btn-custom::before, .send-btn-custom::after { 
  display: none !important; opacity: 0 !important; background-color: transparent !important; background-image: none !important; box-shadow: none !important;
}
.input-btn-mic svg, .input-btn-sticker svg, .input-btn-ai svg, html body .send-btn-custom svg, html body .stop-btn-custom svg { display: none !important; }

/* 🍏 日间恢复苹果滑轨：加深颜色，并提至最高层级！ */
.input-action-bar-custom { display: block !important; visibility: visible !important; opacity: 1 !important; }

.input-action-bar-custom::before {
  content: "" !important; position: absolute !important; 
  bottom: 50px !important; /* 📱 适配修改：底栏小刻度条的上下位置 */
  left: 50% !important; transform: translateX(-50%) !important; 
  width: 260px !important; height: 6px !important; pointer-events: none !important; 
  z-index: 9999 !important; 
  /* 用更深的 rgba(0,0,0,0.25) 来画日间的线，拒绝被白底吞没 */
  background-image: repeating-linear-gradient(90deg, rgba(0, 0, 0, 0.25) 0px, rgba(0, 0, 0, 0.25) 1.5px, transparent 1.5px, transparent 6px) !important;
  background-size: 100% 100% !important; background-position: center !important; background-repeat: no-repeat !important;
  -webkit-mask-image: linear-gradient(90deg, transparent 0%, #000 25%, #000 75%, transparent 100%) !important; mask-image: linear-gradient(90deg, transparent 0%, #000 25%, #000 75%, transparent 100%) !important; transition: opacity 0.18s ease-in-out !important;
}
/* 相册滑轨原点 */
.input-action-bar-custom::after {
  content: "" !important; position: absolute !important; 
  bottom: 44px !important; /* 📱 适配修改：滑轨上圆形小点的上下位置 */
  left: 50% !important; transform: translateX(-50%) !important; 
  width: 18px !important; height: 18px !important; background: #ffffff !important; border-radius: 50% !important; 
  box-shadow: 0 2.5px 6px rgba(0, 0, 0, 0.15), 0 0 1px rgba(0, 0, 0, 0.1) !important;
  z-index: 9999 !important; transition: opacity 0.18s ease-in-out !important;
}
.input-row-wrapper::after { display: none !important; }

/* 打字时优雅隐藏滑轨 */
.input-area-custom:focus-within .input-action-bar-custom::before, 
.input-area-custom:focus-within .input-action-bar-custom::after, 
.input-area-custom:has(.input-box-custom:not(:placeholder-shown)) .input-action-bar-custom::before, 
.input-area-custom:has(.input-box-custom:not(:placeholder-shown)) .input-action-bar-custom::after { 
  opacity: 0 !important; 
}

/* ==========================================
   9. 🚨 【菜单化身图片 & 输入框调整】
   ========================================== */
.input-action-bar-custom, .input-row-wrapper, .input-btns-right { position: static !important; margin: 0 !important; padding: 0 !important; pointer-events: auto !important; }
.input-area-custom { z-index: 99999 !important; }
.input-area-custom::before { display: none !important; }
.input-btn-plus {
  position: absolute !important; top: 18px !important; left: calc(50% - 170px) !important; 
  width: 60px !important; height: 60px !important; opacity: 1 !important; z-index: 1001 !important; cursor: pointer !important; margin: 0 !important; padding: 0 !important; transform: none !important;
  background-image: var(--filter-1) !important; background-size: cover !important; background-position: center !important; background-repeat: no-repeat !important;
  border-radius: 8px !important; border: 2px solid #ffffff !important; box-shadow: 0 4px 14px rgba(0, 0, 0, 0.12) !important; transition: transform 0.2s cubic-bezier(0.4, 0, 0.2, 1) !important;
  display: flex !important; align-items: center !important; justify-content: center !important;
  -webkit-appearance: none !important; appearance: none !important; outline: none !important;
}
.input-btn-plus:hover { transform: scale(1.04) !important; }
.input-btn-plus svg, .input-btn-plus::after { display: none !important; }

/* 🌟 输入框平时状态 */
.input-box-custom {
  position: absolute !important; left: 20px !important; right: 20px !important; 
  bottom: 34px !important; /* 📱 适配修改：平时不打字时，输入框(占位符)的高度 */
  height: 44px !important; background: transparent !important; color: #1c1c1e !important; font-size: 14px !important; font-weight: 600 !important; text-align: center !important; z-index: 101 !important; padding: 10px !important; cursor: text !important; transition: all 0.22s cubic-bezier(0.4, 0, 0.2, 1) !important; --input-caret-color: #ffd60a !important; pointer-events: auto !important; 
}
/* 🌟 输入框打字时状态 */
.input-box-custom:focus, .input-box-custom:not(:placeholder-shown) {
  background: #ffffff !important; color: #1c1c1e !important; text-align: left !important; padding: 12px 16px !important; border-radius: 12px !important; box-shadow: 0 6px 24px rgba(0, 0, 0, 0.08) !important; border: 1px solid rgba(0,0,0,0.05) !important; 
  height: 48px !important; 
  bottom: 32px !important; /* 📱 适配修改：打字时弹出来的输入框所处的高度位置 */          
}

.more-options-popup {
  background: rgba(255, 255, 255, 0.95) !important; backdrop-filter: blur(25px) saturate(180%) !important; -webkit-backdrop-filter: blur(25px) saturate(180%) !important; border-radius: 20px !important; border: 1px solid rgba(0, 0, 0, 0.05) !important; box-shadow: 0 12px 44px rgba(0,0,0,0.08) !important; z-index: 999999 !important; pointer-events: auto !important;
}
.more-options-item-row, .more-options-item-row * { pointer-events: auto !important; cursor: pointer !important; color: #1c1c1e !important; }

/* ==========================================
   10. 🚀 【胶囊引用系统】 
   ========================================== */
.msg-reply-block { display: none !important; }
.msg-reply-block-detached { display: flex !important; }

.chat-detail-screen {
  --reply-detached-flex-direction: row !important; --reply-detached-gap: 6px !important; --reply-detached-align-items: center !important; 
  --reply-detached-max-width: 75% !important; /* 📱 适配修改：引用框能拉长的最大宽度 */
  --reply-detached-margin-top: 6px !important; --reply-detached-margin-bottom: 6px !important; 

  --reply-detached-bg: #ffffff !important; 
  --reply-detached-radius: 14px !important; 
  --reply-detached-padding: 6px 14px !important; 
  --reply-detached-border: 1px solid rgba(0, 0, 0, 0.04) !important; 
  --reply-detached-shadow: 0 4px 14px rgba(0, 0, 0, 0.08) !important; 

  --reply-detached-name-size: 12px !important; --reply-detached-name-weight: 700 !important; --reply-detached-name-suffix: " :" !important; 
  --reply-detached-text-size: 12px !important; --reply-detached-text-font-style: normal !important;

  --reply-detached-me-bg: #ffffff !important; --reply-detached-me-border-left: none !important; --reply-detached-me-name-color: #1c1c1e !important; --reply-detached-me-text-color: #8e8e93 !important; 
  --reply-detached-them-bg: #ffffff !important; --reply-detached-them-border-left: none !important; --reply-detached-them-name-color: #1c1c1e !important; --reply-detached-them-text-color: #8e8e93 !important; 
}
.msg-reply-block-detached { width: fit-content !important; }
.msg-reply-detached-text { white-space: nowrap !important; overflow: hidden !important; text-overflow: ellipsis !important; flex: 1 !important; 
  max-width: 160px !important; /* 📱 适配修改：强制省略号的宽度极限，避免把胶囊撑爆 */
  display: inline-block !important; }
.msg-reply-block-detached::before { display: none !important; }

:root {
    /* ================== 顶部导航 ================== */
    --chat-header-bg: #e0f2fe; 
    --chat-header-border: 1px solid #bae0ff;
    --chat-header-title-color: #69b1ff;
    --header-btn-gap: 36px; 

    /* ================== 输入区基础变量 ================== */
    --input-area-bg: rgba(255, 255, 255, 0.95); 
    --input-area-border-top: none; 
    --input-box-bg: rgba(240, 249, 255, 0.9);
    --input-box-color: #333333;

    /* ================== 图标全面替换 ================== */
    --back-btn-icon: url('https://s1.imagehub.cc/images/2026/07/26/c325cfd08c87df4d8fb8b3c0e980a6d1.png');
    --phone-btn-icon: url('https://s1.imagehub.cc/images/2026/07/26/5c06f700c7b0d4c8b9366fa70e3275d7.png');
    --video-btn-icon: url('https://s1.imagehub.cc/images/2026/07/26/1f03473b8a055bb27a3dacc6fdcf27c3.png');
    --info-btn-icon: url('https://s1.imagehub.cc/images/2026/07/26/dd0063b409f29a7219db7e118f394c5e.png');

    --send-btn-icon: url('https://s1.imagehub.cc/images/2026/07/26/c3210c47ff462a9086ca52efb086a342.png');
    --mic-btn-icon: url('https://s1.imagehub.cc/images/2026/07/26/1f03473b8a055bb27a3dacc6fdcf27c3.png');
    --sticker-btn-icon: url('https://s1.imagehub.cc/images/2026/07/26/13e57525d7d22c48881129c7d7eb36c3.png');
    --ai-btn-icon: url('https://s1.imagehub.cc/images/2026/07/26/5c06f700c7b0d4c8b9366fa70e3275d7.png');

    /* ================== 其他图标放大 ================== */
    --btn-back-scale: 3.0;
    --btn-phone-scale: 3.0;
    --btn-video-scale: 3.0;  
    --btn-info-scale: 3.0;
    --btn-send-scale: 1.8;
    --btn-mic-scale: 1.8;
    --btn-sticker-scale: 1.8;
    --btn-ai-scale: 1.8;

    /* ================== 思维链美化 ================== */
    --thinking-btn-bg: #ffffff;
    --thinking-btn-color: #69b1ff;
    --thinking-btn-border: 1px solid #69b1ff;
    --thinking-btn-shadow: 0 2px 6px rgba(105, 177, 255, 0.15);
    --thinking-arrow-color: #69b1ff;
    --thinking-panel-bg: rgba(255, 255, 255, 0.95);
    --thinking-panel-border-full: 1px solid #69b1ff; 
    --thinking-panel-border-left: none; 
    --thinking-panel-radius: 12px;
    --thinking-panel-shadow: 0 4px 12px rgba(105, 177, 255, 0.15);
    --thinking-text-color: #5c8bba; 

    /* ================== 更多菜单 ================== */
    --more-options-bg: #ffffff;
    --more-options-border: 2px solid #bae0ff;
    --more-options-shadow: 0 8px 24px rgba(105, 177, 255, 0.2);
    --more-options-color: #5c8bba;
    --more-options-divider: rgba(105, 177, 255, 0.15);

    /* ================== 💙 转账/红包基础设定 💙 ================== */
    --transfer-card-bg: #f0f9ff;                
    --transfer-card-border: 2px solid #bae0ff;  
    --transfer-card-radius: 20px;               
    --transfer-card-shadow: 0 4px 12px rgba(105, 177, 255, 0.1); 
    --transfer-card-transform: none;            
    --transfer-card-animation: none;            

    /* 👈 极限压缩内边距：上下只有 8px */
    --transfer-content-padding: 8px 16px !important;      

    --transfer-icon-bg: transparent;                
    --transfer-icon-color: transparent;             

    /* 全部恢复深蓝色文本 */
    --transfer-amount-color: #5c8bba;           
    --transfer-label-color: #5c8bba;
    --transfer-subtitle-color: #5c8bba;
    --transfer-divider-color: rgba(92, 139, 186, 0.2);

    /* 我方、对方转账独立设定 */
    --transfer-me-icon-bg: transparent;
    --transfer-me-amount-color: #5c8bba;
    --transfer-me-label-color: #5c8bba;
    --transfer-me-subtitle-color: #5c8bba;
    --transfer-me-status-color: #5c8bba;

    --transfer-them-icon-bg: transparent;
    --transfer-them-amount-color: #5c8bba;
    --transfer-them-label-color: #5c8bba;
    --transfer-them-subtitle-color: #5c8bba;
    --transfer-them-status-color: #5c8bba;

    /* ================== 旁白模式 萌系美化 ================== */
    --narration-bg: #f0f9ff;
    --narration-color: #5c8bba;
    --narration-border: 2px dotted #bae0ff;
    --narration-radius: 20px;
    --narration-padding: 8px 16px;
    --narration-style: normal;
    --narration-weight: 600;
}

/* ================== 👑 顶栏头像完美包裹 👑 ================== */
.header-avatar-container {
    position: relative !important;
    overflow: visible !important;
    border: none !important; 
}
.header-avatar-container::after {
    content: "";
    position: absolute;
    top: 50%;
    left: 50%;
    width: 60px;  
    height: 60px;
    transform: translate(-50%, -50%);
    background: url('https://s1.imagehub.cc/images/2026/07/26/20b2ff34795221219b25448c4bf81444.png') no-repeat center/contain;
    pointer-events: none;
    z-index: 5;
}
.chat-header-avatar {
    border: none !important; 
}

/* ================== 👑 左右聊天头像精准包裹 👑 ================== */
.msg-avatar-them-container,
.msg-avatar-me-container {
    position: relative !important;
    overflow: visible !important;
}

.msg-avatar-custom,
.msg-avatar-them-inner,
.msg-avatar-me-inner {
    border: none !important;
}

.msg-avatar-them-container::after,
.msg-avatar-me-container::after {
    content: "";
    position: absolute;
    top: 20%;     
    left: 50%;
    width: 70px;  
    height: 70px;
    transform: translate(-50%, -50%);
    background: url('https://s1.imagehub.cc/images/2026/07/26/871662b56aea1443f1f71c0724a45189.png') no-repeat center/contain;
    pointer-events: none; 
    z-index: 5;
}

/* ================== 🌟 转账卡片：究极挤扁修长版 🌟 ================== */
.msg-transfer-card {
    /* 👈 宽度拉长，视觉显扁 */
    width: 260px !important;         
    border-radius: 20px !important;  
    background: #f0f9ff !important;
    border: 2px solid #bae0ff !important;
    overflow: hidden !important; 
    position: relative !important;
}

/* 强制文字变成深蓝色 */
.msg-transfer-card .msg-transfer-label,
.msg-transfer-card .msg-transfer-subtitle,
.msg-transfer-card .msg-transfer-amount,
.msg-transfer-card .msg-transfer-status-text,
.msg-transfer-card .msg-transfer-chevron {
    color: #5c8bba !important;
    -webkit-text-stroke: 0 !important; 
    text-shadow: none !important;      
    line-height: 1.1 !important; /* 强制缩小行高 */
    margin: 0 !important;        /* 强制干掉文字周围的撑开间距 */
}

/* 👈 暴力压缩金额区域，干掉上下留白 */
.msg-transfer-card .msg-transfer-amount {
    margin: 2px 0 2px 0 !important; 
    font-size: 20px !important; 
}

/* 👈 暴力压缩分割线，节省垂直高度 */
.msg-transfer-card .msg-transfer-divider,
.msg-transfer-card hr {
    margin: 4px 0 !important; 
}

/* 隐藏原本的自带SVG图标 */
.msg-transfer-card svg,
.msg-transfer-card [class*="icon"] svg {
    display: none !important;
}

/* 左上角的小海豹：缩小一点，防止它把第一行撑得太高 */
.msg-transfer-card [class*="icon"],
.msg-transfer-card .msg-transfer-icon-wrap {
    background-color: transparent !important; 
    border: none !important;                  
    box-shadow: none !important;              
    background-image: url('https://s1.imagehub.cc/images/2026/07/26/664b19b09e6bf789e06699ef43c8f414.png') !important; 
    background-size: contain !important;
    background-repeat: no-repeat !important;
    background-position: center !important;
    width: 36px !important;   /* 👈 缩小至36px */
    height: 36px !important;
    border-radius: 0 !important; 
}

/* 右侧全身海豹：因为卡片变矮了，它也必须缩小，不然会挡住全部文字 */
.msg-transfer-card::after {
    content: "" !important;
    display: block !important;
    position: absolute !important;
    bottom: 2px !important;       /* 紧贴底部 */
    right: 0px !important;        
    width: 80px !important;       /* 👈 缩小到 80px 适配扁卡片 */
    height: 80px !important;    
    background-image: url('https://s1.imagehub.cc/images/2026/07/26/b4a28a266c4cdc23a58a3f6da2486766.png') !important; 
    background-size: contain !important;
    background-repeat: no-repeat !important;
    background-position: bottom right !important;
    pointer-events: none !important;
    z-index: 999 !important;  
}

/* ================== 🌟 底栏恢复原来 & 顶部横向虚线修饰 🌟 ================== */
.input-area-custom {
    position: relative !important;
    background: rgba(255, 255, 255, 0.95) !important;
    border-top: 3px dashed #bae0ff !important; 
    border-radius: 0 !important;
    margin: 0 !important;
    box-shadow: 0 -4px 15px rgba(105, 177, 255, 0.1) !important;
}

/* ================== ⏱️ 时间戳：完全居中的小糖果 ⏱️ ================== */
.timestamp-custom {
    background: #ffffff !important;
    border: 1.5px solid #bae0ff !important;
    border-radius: 16px !important;
    padding: 4px 14px !important;
    color: #69b1ff !important;
    box-shadow: 0 4px 12px rgba(105, 177, 255, 0.15) !important;
    display: table !important; 
    margin: 12px auto 20px auto !important; 
    font-size: 11px !important;
    font-weight: 600 !important;
    text-align: center !important;
}
.timestamp-custom::before { content: '✧ '; color: #91caff; }
.timestamp-custom::after { content: ' ✧'; color: #91caff; }

/* ================== 蓝莓强制极限放大 & 微调 ================== */
.input-btn-plus svg { display: none !important; }
.input-btn-plus {
    width: 48px !important;   
    height: 48px !important;
    background-image: url('https://s1.imagehub.cc/images/2026/07/26/aa055c05d8465815396a82bd5451f23d.png') !important;
    background-size: contain !important;
    background-repeat: no-repeat !important;
    background-position: center !important;
    background-color: transparent !important;
    border: none !important;
    margin-right: 6px !important;
    transform: translateY(-2px) !important;
}

/* ================== 强制更多菜单的边框和图标颜色 ================== */
