/* ============================================================
   独立引用条 —— 仅文本 + 下划线，无气泡无昵称
   ============================================================ */

/* 1. 隐藏气泡内部的引用块（原版） */
.msg-reply-block {
  display: none !important;
}

/* 2. 启用独立引用条（默认隐藏） */
.msg-reply-block-detached {
  display: flex !important;
  flex-direction: column !important;   /* 让文本上下排列，隐藏名称后更干净 */
  align-items: flex-start !important;  /* 默认左对齐，后续根据 me/them 调整 */
  margin-top: 2px !important;          /* 与上一条气泡的间距 */
  margin-bottom: 2px !important;
  max-width: 85% !important;           /* 稍窄于气泡，避免太长 */
  background: transparent !important;  /* 完全透明，不要任何背景 */
  border: none !important;
  box-shadow: none !important;
  border-radius: 0 !important;
  padding: 0 !important;
}

/* 3. 隐藏昵称（名称） */
.msg-reply-detached-name {
  display: none !important;
}

/* 4. 隐藏媒体图标（图片/贴纸等） */
.msg-reply-detached-media {
  display: none !important;
}

/* ============================================================
   引用文本 —— 自适应宽度 + 单行截断 + 下划线贯穿省略号
   ============================================================ */

.msg-reply-detached-text {
  font-size: 14px !important;
  font-weight: 400 !important;
  line-height: 1.5 !important;
  padding: 0 !important;
  margin: 0 !important;
  background: transparent !important;
  box-shadow: none !important;

  /* ★ 核心修正：宽度自适应内容，短文本不撑满，长文本受限于父容器 ★ */
  display: inline-block !important;     /* 让宽度跟随内容 */
  max-width: 100% !important;           /* 不超过父容器（父级 max-width: 85%） */
  white-space: nowrap !important;       /* 强制单行 */
  overflow: hidden !important;          /* 溢出裁剪 */
  text-overflow: ellipsis !important;   /* 溢出显示 … */
  vertical-align: bottom !important;    /* 修正 inline-block 的基线对齐 */
  min-width: fit-content;     /* 确保至少能容纳自己的内容，不会因父容器压缩而截断 */
  /* 或者 */
  min-width: auto;           /* 默认值，但配合 flex 需额外设置 flex-shrink: 0 */
  flex-shrink: 0;            /* 如果父容器是 flex，阻止收缩 */

  /* ★ 下划线改用 border-bottom，会一直画到元素边缘（包含 … 区域） ★ */
  border-bottom: 1.5px solid currentColor !important;
  padding-bottom: 1px !important;       /* 控制下划线与文字的距离（等同于 text-underline-offset） */
}

/* 6. 对方引用条 —— 左对齐，文字颜色与对方气泡一致（灰色） */
.msg-reply-detached-them .msg-reply-detached-text {
  color: #c1c1c1 !important;            /* 与对方气泡文字颜色一致 */
  text-decoration-color: #c1c1c1 !important;
}

/* 7. 我方引用条 —— 右对齐，文字颜色与我方气泡文字一致（灰色） */
.msg-reply-detached-me {
  align-self: flex-end !important;      /* 右对齐 */
}
.msg-reply-detached-me .msg-reply-detached-text {
  color: #797979 !important;            /* 与当前我方气泡文字颜色一致 */
  text-decoration-color: #797979 !important;
}

/* 8. （可选）如果你想突出引用，改为更深的颜色或不同下划线颜色 */
/* 示例：引用使用稍亮的蓝色下划线 */
