}
/* === 语音和表情的双拼悬浮小胶囊（终极版） === */
/* 1. 隐藏原生图标 */
.input-btn-mic svg, .input-btn-sticker svg {
display: none !important;
}
/* 2. 语音键（左半边） */
.input-btn-mic {
position: absolute !important;
top: -55px !important; 
right: 60px !important; 
background: rgba(255, 255, 255, 0.6) !important; 
