/* 3. 我方气泡（右边）的虚线：专属紫色加透明度 */
.msg-bubble-wrapper.is-first .bubble-me-custom::after,
.msg-bubble-wrapper.is-last .bubble-me-custom::after,
.msg-bubble-wrapper.is-single .bubble-me-custom::after {
content: "";
position: absolute;
left: 12px;
right: 12px;
bottom: 7px;
border-bottom: 1px dashed rgba(187, 161, 217, 0.6) !important; 
pointer-events: none;
}
/* === 独立翻译条（往内缩 + 紫色统一版） === */
