/* 糯叽机淡水 by我厌 禁二传 二改仅自用 */

@import url('https://fonts.googleapis.com/css2?family=DotGothic16&family=Silkscreen&display=swap');

:root {
    /* =====❤️‍🩹 修改区 ❤️‍🩹===== */
    --msg-name-received:     '恶魔用户013';
    --msg-name-sent:         '天使用户009';
    --msg-font:              'DotGothic16', 'Silkscreen', monospace;/*❤️‍🩹不想要自带字体就删掉这行❤️‍🩹*/
    --msg-name-size:         14.5px;
    --msg-text-size:         13px;
    --msg-text-color:        #3a3a3a;
    --msg-time-color:        #aaa;
    --msg-time-size:         10px;

    /* ===== 顶栏 ===== */
    --back-btn-icon: url('https://nos.netease.com/ysf/c86935f0828e267bcaa1347f6ba4117b.png');
    --phone-btn-icon: url('https://nos.netease.com/ysf/4b05e751c9a3c913f6d7b71a50e98dfd.png');
    --video-btn-icon: url('https://nos.netease.com/ysf/fcc931d077865695ce5ad85dd4439342.png');
    --info-btn-icon: url('https://nos.netease.com/ysf/19c7d14b005f0fd75ddc476ba232c97b.png');
    --chat-header-bg: #ffffff;
    --chat-header-border: transparent;
    --chat-header-blur: 0px;

    /* ===== 底栏 ===== */
    --input-area-bg: #ffffff;
    --input-area-border-top: none;
    --input-box-bg: transparent;
    --input-box-color: #3a3a3a;
    --input-box-border: none;
    --input-box-shadow: none;
    --input-box-placeholder: transparent;
    --input-btn-color: transparent;
    --plus-btn-bg: transparent;
    --plus-btn-color: transparent;

    /* ===== 气泡 ===== */
    --bubble-me-bg: transparent;
    --bubble-me-color: #3a3a3a;
    --bubble-me-font-size: 13px;
    --bubble-me-line-height: 1.8;
    --bubble-me-padding: 4px 12px;
    --bubble-me-radius: 0px;
    --bubble-me-radius-first: 0px;
    --bubble-me-radius-mid: 0px;
    --bubble-me-radius-last: 0px;
    --bubble-me-shadow: none;
    --bubble-me-border: none;

    --bubble-them-bg: transparent;
    --bubble-them-color: #3a3a3a;
    --bubble-them-font-size: 13px;
    --bubble-them-line-height: 1.8;
    --bubble-them-padding: 4px 12px;
    --bubble-them-radius: 0px;
    --bubble-them-radius-first: 0px;
    --bubble-them-radius-mid: 0px;
    --bubble-them-radius-last: 0px;
    --bubble-them-shadow: none;
    --bubble-them-border: none;

    /* ===== 其他 ===== */
    --timestamp-color: #aaa;
    --timestamp-size: 10px;
    --avatar-size: 0px;

    --translation-bg: transparent;
    --translation-border: none;
    --translation-radius: 0;
    --translation-text-color: #999;
    --translation-size: 11px;
    --translation-padding: 2px 8px;

    --transfer-card-bg: transparent;
    --transfer-card-border: 1px solid #464845;
    --transfer-card-radius: 0px;
    --transfer-card-shadow: none;
    --transfer-amount-color: #2e302f;

    --voice-transcription-bg: transparent;
    --voice-transcription-border: none;
    --voice-transcription-radius: 0;
    --voice-transcription-padding: 2px 0px;
}

/* ===== 顶栏按键位移 ===== */
.chat-detail-screen {
    --btn-back-scale: 1.1;
    --btn-back-translate-x: 0px;
    --btn-back-translate-y: 0px;
    --btn-phone-scale: 1.2;
    --btn-phone-translate-x: -35px;
    --btn-phone-translate-y: 0px;
    --btn-video-scale: 1.3;
    --btn-video-translate-x: -18px;
    --btn-video-translate-y: 0px;
    --btn-info-scale: 1.2;
    --btn-info-translate-x: 0px;
    --btn-info-translate-y: 0px;

    --reply-detached-bg: transparent;
    --reply-detached-radius: 0;
    --reply-detached-padding: 2px 0px;
    --reply-detached-margin-top: 3px;
    --reply-detached-max-width: 85%;
    --reply-detached-text-color: #888;
    --reply-detached-name-color: #666;
    --reply-detached-name-weight: 600;
    --reply-detached-name-suffix: "：";
    --reply-detached-gap: 4px;
    --reply-detached-flex-direction: row;
    --reply-detached-align-items: center;
}

/* =========================================================
   顶栏
   ========================================================= */

.header-profile-section {
    display: none !important;
}

.chat-header-custom,
.glass-header {
    box-shadow: none !important;
    background: #ffffff !important;
}

.chat-header-custom {
    position: relative !important;
    overflow: visible !important;
    padding-bottom: 25px !important;
}

.header-btn-back {
    position: relative !important;
    overflow: visible !important;
}

.header-btn-back::after {
    content: '' !important;
    position: absolute !important;
    top: 50% !important;
    left: calc(100% + 15px) !important;
    transform: translateY(-50%) !important;
    width: 140px !important;
    height: 140px !important;
    background: url('https://nos.netease.com/ysf/b6268b2fcc74aa4a4124fd57cbee429f.png') center / contain no-repeat !important;
    pointer-events: none !important;
}

.chat-header-custom::after {
    content: '' !important;
    position: absolute !important;
    bottom: 0px !important;
    left: 50% !important;
    transform: translateX(-50%) !important;
    width: calc(100% - 30px) !important;
    height: 1.2px !important;
    background: repeating-linear-gradient(
        90deg,
        #464845 0,
        #464845 16px,
        transparent 16px,
        transparent 26px
    ) !important;
    pointer-events: none !important;
    z-index: 10 !important;
}

/* =========================================================
   底栏
   ========================================================= */

.input-area-custom {
    position: relative !important;
    overflow: visible !important;
    padding-top: 0px !important;
    background: #ffffff !important;
}

.input-area-custom,
.input-row-wrapper,
.input-action-bar-custom {
    transition: none !important;
    transform: none !important;
}

.input-area-custom::after {
    content: '' !important;
    position: absolute !important;
    top: 0px !important;
    left: 50% !important;
    transform: translateX(-50%) !important;
    width: calc(100% - 30px) !important;
    height: 1.2px !important;
    background: repeating-linear-gradient(
        90deg,
        #464845 0,
        #464845 16px,
        transparent 16px,
        transparent 26px
    ) !important;
    pointer-events: none !important;
    z-index: 10 !important;
}

.input-btn-plus {
    transform: none !important;
    transition: none !important;
    width: 85px !important;
    height: 85px !important;
    min-width: 85px !important;
    min-height: 85px !important;
    align-self: center !important;
    margin-left: 2px !important;
    background: url('https://nos.netease.com/ysf/bd772955dc8af8f9842914519b5e40fe.png') center / contain no-repeat !important;
    background-color: transparent !important;
}

.input-btn-plus svg,
.input-btn-plus * {
    display: none !important;
}

.input-btns-right button:last-child {
    width: 85px !important;
    height: 85px !important;
    min-width: 85px !important;
    min-height: 85px !important;
    max-width: 85px !important;
    max-height: 85px !important;
    align-self: center !important;
    background-image: url('https://nos.netease.com/ysf/20a77da97f8934149ead668c76fd84b1.png') !important;
    background-size: contain !important;
    background-repeat: no-repeat !important;
    background-position: center !important;
    background-color: transparent !important;
    transform: none !important;
    transition: none !important;
    animation: none !important;
    flex-shrink: 0 !important;
}

.input-btns-right button:last-child svg {
    display: none !important;
}

.input-btns-right {
    transform: none !important;
    transition: none !important;
    flex-shrink: 0 !important;
}

.input-btn-mic {
    opacity: 0 !important;
    pointer-events: auto !important;
}

.input-btn-sticker {
    opacity: 0 !important;
    pointer-events: auto !important;
}

.input-box-custom {
    transition: none !important;
}

.input-box-custom::placeholder {
    color: transparent !important;
    -webkit-text-fill-color: transparent !important;
}

/* =========================================================
   聊天区域
   ========================================================= */

.chat-message-list-custom {
    padding-left: 15px !important;
    padding-right: 15px !important;
}

.msg-avatar-them-container,
.msg-avatar-me-container {
    display: none !important;
}

/* =========================================================
   气泡
   ========================================================= */

.bubble-me-custom,
.bubble-them-custom,
.bubble-deco-me,
.bubble-deco-them,
.msg-bubble-wrapper,
.msg-content-stack {
    position: relative !important;
    overflow: visible !important;
}

.bubble-me-custom,
.bubble-them-custom,
.msg-plain-me,
.msg-plain-them {
    font-family: var(--msg-font) !important;
}

.bubble-me-custom,
.msg-plain-me {
    text-align: right !important;
}

.msg-bubble-wrapper.msg-them {
    border-left: 1px solid #464845 !important;
    margin-left: 0 !important;
}

.msg-bubble-wrapper.msg-me {
    border-right: 1px solid #464845 !important;
    margin-right: 0 !important;
}

/* ===== 名字标签 ===== */

.msg-bubble-wrapper.msg-them.is-first .bubble-deco-them::before,
.msg-bubble-wrapper.msg-them.is-single .bubble-deco-them::before {
    content: var(--msg-name-received) !important;
    position: absolute !important;
    bottom: calc(100% + 6px) !important;
    left: -1px !important;
    font-family: var(--msg-font) !important;
    font-size: var(--msg-name-size) !important;
    color: #ffffff !important;
    font-weight: 700 !important;
    letter-spacing: 1px !important;
    line-height: 1 !important;
    white-space: nowrap !important;
    pointer-events: none !important;
    z-index: 2 !important;
    background: #464845 !important;
    padding: 3px 6px !important;
}

.msg-bubble-wrapper.msg-me.is-first .bubble-deco-me::before,
.msg-bubble-wrapper.msg-me.is-single .bubble-deco-me::before {
    content: var(--msg-name-sent) !important;
    position: absolute !important;
    bottom: calc(100% + 6px) !important;
    right: -1px !important;
    font-family: var(--msg-font) !important;
    font-size: var(--msg-name-size) !important;
    color: #ffffff !important;
    font-weight: 700 !important;
    letter-spacing: 1px !important;
    line-height: 1 !important;
    white-space: nowrap !important;
    text-align: right !important;
    pointer-events: none !important;
    z-index: 2 !important;
    background: #464845 !important;
    padding: 3px 6px !important;
}

.msg-bubble-wrapper.msg-them.is-first,
.msg-bubble-wrapper.msg-them.is-single,
.msg-bubble-wrapper.msg-me.is-first,
.msg-bubble-wrapper.msg-me.is-single {
    margin-top: 28px !important;
}

.msg-bubble-wrapper.is-mid .bubble-deco-them::before,
.msg-bubble-wrapper.is-last .bubble-deco-them::before,
.msg-bubble-wrapper.is-mid .bubble-deco-me::before,
.msg-bubble-wrapper.is-last .bubble-deco-me::before {
    display: none !important;
}

/* ===== 连续气泡间距 ===== */

.msg-bubble-wrapper.is-mid,
.msg-bubble-wrapper.is-last {
    margin-top: 0px !important;
    margin-bottom: 0px !important;
}

.msg-bubble-wrapper.is-first {
    margin-bottom: 0px !important;
}

/* =========================================================
   引用
   ========================================================= */

.msg-reply-block { display: none !important; }
.msg-reply-block-detached { display: flex !important; }

.msg-reply-detached-them {
    align-self: flex-start !important;
    border: none !important;
    border-radius: 0 !important;
    background: transparent !important;
    font-family: var(--msg-font) !important;
    font-size: 11px !important;
    margin-left: 10px !important;
    position: relative !important;
    padding-left: 12px !important;
}

.msg-reply-detached-them::before {
    content: ">" !important;
    position: absolute !important;
    left: 0 !important;
    top: 2px !important;
    font-family: var(--msg-font) !important;
    font-size: 11px !important;
    color: #888 !important;
}

.msg-reply-detached-me {
    align-self: flex-end !important;
    border: none !important;
    border-radius: 0 !important;
    background: transparent !important;
    font-family: var(--msg-font) !important;
    font-size: 11px !important;
    margin-right: 10px !important;
    position: relative !important;
    padding-right: 12px !important;
    text-align: right !important;
}

.msg-reply-detached-me::after {
    content: "<" !important;
    position: absolute !important;
    right: 0 !important;
    top: 2px !important;
    font-family: var(--msg-font) !important;
    font-size: 11px !important;
    color: #888 !important;
}

/* =========================================================
   翻译
   ========================================================= */

.msg-translation-wrapper {
    display: none !important;
}

.msg-translation-detached {
    display: block !important;
    margin-top: 3px !important;
    width: fit-content !important;
}

.voice-msg ~ .msg-translation-detached,
.voice-msg + .msg-translation-detached {
    display: none !important;
}

.msg-translation-detached-content {
    background: transparent !important;
    color: #888 !important;
    padding: 2px 0px !important;
    border-radius: 0 !important;
    border: none !important;
    box-shadow: none !important;
    font-family: var(--msg-font) !important;
    font-size: 11px !important;
    line-height: 1.5 !important;
}

.msg-translation-detached-them {
    align-self: flex-start !important;
    margin-left: 10px !important;
    position: relative !important;
    padding-left: 12px !important;
}

.msg-translation-detached-them::before {
    content: ">" !important;
    position: absolute !important;
    left: 0 !important;
    top: 5px !important;
    font-family: var(--msg-font) !important;
    font-size: 11px !important;
    color: #888 !important;
}

.msg-translation-detached-me {
    align-self: flex-end !important;
    margin-right: 10px !important;
    position: relative !important;
    padding-right: 12px !important;
    text-align: right !important;
}

.msg-translation-detached-me::after {
    content: "<" !important;
    position: absolute !important;
    right: 0 !important;
    top: 5px !important;
    font-family: var(--msg-font) !important;
    font-size: 11px !important;
    color: #888 !important;
}

.msg-translation-detached-me .msg-translation-detached-content {
    text-align: right !important;
}

/* =========================================================
   语音条
   ========================================================= */

.voice-msg {
    zoom: 0.6 !important;
}

.msg-them .voice-msg .voice-controls-row,
.msg-me .voice-msg .voice-controls-row {
    border: 1px solid #464845 !important;
    border-radius: 0 !important;
    background: transparent !important;
    padding: 4px 10px !important;
}

/* =========================================================
