/* 「愛恨」游离(日间) by点星 禁止二传二改 */
:root {
    /* 加高顶栏 */
    --chat-header-height: 120px;
    /* 大头像尺寸52px */
    --chat-header-avatar-size: 52px;
    /* 移除头像边框 */
    --chat-header-avatar-border: none;
    --chat-header-avatar-shadow: none;
    /* 缩小右侧按钮间距腾出左侧空间 */
    --header-btn-gap: 10px;
}

/* 头像整体左移+轻微上移 */
.header-profile-section {
    transform: translate(-22px, -8px) !important;
}

/* 主备注文字：右移、上抬 */
.chat-header-title {
    position: relative !important;
    transform: translate(5px, 1px) !important;
}

/* 在标题下方生成小字 */
.chat-header-title::after {
    content: "@love^uuu";
    display: block;
    margin-top: 2px;
    font-size: 12px;
    color: #8e8e8e;
    opacity: 0.8;
}

/* 原有副标题同步上移对齐 */
.chat-header-subtitle {
    transform: translate(5px, -10px) !important;
}

/* ===== 左一（返回按钮）：隐藏原生图标，保留点击功能 ===== */
.header-btn-back svg {
    display: none !important;
}

.header-btn-back {
    position: relative !important;
    background: none !important;
    background-color: transparent !important;
    display: flex !important;
    align-items: center !important;
    justify-content: center !important;
    min-width: 32px !important;
    min-height: 32px !important;
    visibility: visible !important;
    opacity: 1 !important;
    /* 保持与右侧按钮同一垂直高度 */
    transform: translateY(-10px) !important;
}

