/* === 我方气泡（用户） === */
.bubble-me-custom,
.bubble-me-custom.first,
.bubble-me-custom.mid,
.bubble-me-custom.last {
  background: rgba(255,255,255,0.44) !important;
  border-radius: 18px !important;
  border: none !important;
  box-shadow: 0 2px 2px rgba(0,0,0,.18) !important;
