/* ----------variables---------- */
:root {
  --plain-gap-within-group: 7px;
  --plain-gap-between-groups: 34px;
  --plain-padding-left-them: calc(var(--rail-band-l) + var(--rail-gap));
  --plain-padding-right-me: calc(var(--rail-band-w) + var(--rail-gap));
  --chat-bg-color: #F4F4F4;
  --chat-header-bg: #FAFAFA;
  --chat-header-height: 158px;
  --chat-header-blur: 0px;
  --chat-header-border: transparent;
  --input-area-min-height: 84px;
  --input-area-padding: 14px 16px 28px 12px;
  --input-area-bg: #FAFAFA;
  --input-area-border-top: 0.8px solid #E4E4E6;
  --input-box-radius: 0;
  --input-box-padding: 4px 0;
  --input-box-font-size: 13px;
  --input-box-bg: #ffffff;
  --input-box-color: #58585A;
  --input-box-placeholder: #BCBCBE;
  --input-caret-color: #BCBCBE;
  --reply-bar-accent: #bcbcbe; 
  --input-btn-color: #A8A8AA;
  --send-btn-color: #A8A8AA;
  --stop-btn-color: #A8A8AA;
  --plus-btn-color: #A8A8AA;
  --plus-btn-size: 28px;
  --plus-btn-icon: url("https://img.icons8.com/?size=100&id=eqFgmmhmKATD&format=png&color=A8A8AA");
  --mic-btn-icon: url("https://img.icons8.com/?size=100&id=6652&format=png&color=A8A8AA");
  --sticker-btn-icon: url("https://img.icons8.com/?size=100&id=56574&format=png&color=A8A8AA");
  --image-msg-max-width: 148px;
  --image-msg-radius: 0;
  --image-msg-border: none;
  --image-msg-shadow: none;
  --image-me-filter: grayscale(0.05) contrast(0.95);
  --image-them-filter: grayscale(0.05) contrast(0.95);
  --card-w: 238px;
  --inv-w: 276px;
  --inv-sq: 15.6px;
  --grid-x: repeating-linear-gradient(90deg, #E8E8EA 0 0.5px, transparent 0.5px 7.8px);
  --grid-y: repeating-linear-gradient(#E8E8EA 0 0.7px, transparent 0.7px 7.8px);
  --grid-fill: linear-gradient(#E6E6E8, #E6E6E8);
  --grid-size: 31.7px 100%, 31.7px calc(round(down, 100%, 7.8px) + 0.7px);
  --grid-size-fill: 31.7px 100%, 31.7px calc(round(down, 100%, 7.8px) + 0.7px), 3px 100%;
  --rail-gap: 12px;
  --rail-band-w: 24px;
  --rail-band-l: 18px;
  --rail-tick-w: 8px;
  --rail-right-x: calc((var(--rail-band-w) - var(--rail-tick-w)) / 2);
  --tab-w: 142px;
  --header-bar-w: 132px;
  --header-bar-h: 7px;
  --addr-band-h: 52px;
  --addr-h: 36px;
  --tail-img: url("https://atnefallhmhz.vercel.app/f/IMG_2291-iiik5y.png");
  --tail-w: 40px;
  --tail-h: 38px;
  --tail-overlap: 22px;
  --tail-y: -14px;
}
.chat-detail-screen {
  --reply-detached-bg: transparent;
  --reply-detached-padding: 0;
  --reply-detached-radius: 0;
  --reply-detached-border: none;
  --reply-detached-border-left: none;
  --reply-detached-shadow: none;
  --reply-detached-gap: 0;
  --reply-detached-align-items: flex-end;
  --reply-detached-margin-top: 0;
  --reply-detached-margin-bottom: 0;
  --reply-detached-width: max-content;
  --reply-detached-max-width: 46vw;
  --reply-detached-text-color: #BCBCBE;
  --reply-detached-before-content: "\300E";
  --reply-detached-after-content: "\300F";
  --voice-me-color: #6C6C6E;
  --voice-me-bar-active: #6C6C6E;
  --voice-me-bar-inactive: #D5D5D7;
  --voice-them-color: #6C6C6E;
  --voice-them-bar-active: #6C6C6E;
  --voice-them-bar-inactive: #D5D5D7;
  --voice-container-gap: 5px;
  --voice-controls-gap: 1px;
  --voice-waveform-height: 16px;
  --voice-download-opacity: 0;
  --voice-toggle-opacity: 0;
  --voice-toggle-padding: 0;
  --voice-transcription-color: #6C6C6E;
  --voice-transcription-size: 13.5px;
  --voice-transcription-bg: rgba(255, 255, 255, 0.7);
  --voice-transcription-margin-top: 1px;
  --voice-transcription-padding: 9px 17px 4px;
  --voice-transcription-radius: 0;
  --voice-transcription-border: 0.8px solid #E4E4E6;
  --voice-transcription-shadow: none;
  --translation-bg: transparent;
  --translation-padding: 0;
  --translation-radius: 0;
  --translation-border: none;
  --translation-shadow: none;
  --translation-separator: none;
  --transfer-card-bg: #ffffff;
  --transfer-card-border: 0.8px solid #E4E4E6;
  --transfer-card-radius: 0;
  --transfer-card-shadow: none;
  --transfer-card-width: var(--card-w);
  --transfer-card-overflow: visible;
  --transfer-card-before-content: "";
  --transfer-card-after-content: "";
  --transfer-header-margin-bottom: 0;
}

/* ----------1. chat area rail---------- */
.chat-message-list-custom {
  background-image:
    linear-gradient(#D5D5D7, #D5D5D7),
    linear-gradient(#D5D5D7, #D5D5D7),
    repeating-linear-gradient(#E4E4E6 0 0.8px, transparent 0.8px 7.8px),
    linear-gradient(#E4E4E6, #E4E4E6),
    linear-gradient(#E4E4E6, #E4E4E6),
    linear-gradient(#E4E4E6, #E4E4E6),
    linear-gradient(#FAFAFA, #FAFAFA),
    linear-gradient(#FAFAFA, #FAFAFA) !important;
  background-size:
    var(--rail-tick-w) var(--rail-tick-w),
    var(--rail-tick-w) var(--rail-tick-w),
    var(--rail-tick-w) 100%,
    0.5px 100%,
    0.8px 100%,
    0.5px 100%,
    var(--rail-band-w) 100%,
    var(--rail-band-l) 100% !important;
  background-position:
    right var(--rail-right-x) top 14px,
    right var(--rail-right-x) bottom 14px,
    right var(--rail-right-x) top,
    left 9px top,
    right var(--rail-band-w) top,
    left var(--rail-band-l) top,
    right top,
    left top !important;
  background-repeat: no-repeat !important;
  background-attachment: scroll !important;
}
.chat-message-list-custom::-webkit-scrollbar {
  width: 5px !important;
}
.chat-message-list-custom::-webkit-scrollbar-track {
  background: transparent !important;
}
.chat-message-list-custom::-webkit-scrollbar-thumb {
  background: #C8C8CA !important;
  border-radius: 0 !important;
}

/* ----------2. bubble---------- */
.msg-plain-me,
.msg-plain-them {
  position: relative;
  padding: 7px 17px;
  color: #58585A;
  background-color: #ffffff;
  background-image: var(--grid-x), var(--grid-y);
  background-size: var(--grid-size);
  background-repeat: no-repeat;
  border: 0.8px solid #E4E4E6;
  border-radius: 20px;
  overflow: visible !important;
}
.msg-plain-me {
  background-position: right top, right center;
}
.msg-plain-them {
  background-position: left top, left center;
}
*:has(+ * .msg-plain-me.plain-last) .msg-plain-me,
.msg-plain-me.plain-single,
*:has(.msg-plain-them.plain-first) + * .msg-plain-them,
.msg-plain-them.plain-single {
  background-image: var(--grid-x), var(--grid-y), var(--grid-fill);
  background-size: var(--grid-size-fill);
}
*:has(+ * .msg-plain-me.plain-last) .msg-plain-me,
.msg-plain-me.plain-single {
  background-position: right top, right center, right 10.45px top;
}
*:has(.msg-plain-them.plain-first) + * .msg-plain-them,
.msg-plain-them.plain-single {
  background-position: left top, left center, left 10.45px top;
}

/* ----------3. avatar name tag---------- */
.msg-bubble-wrapper.msg-them {
  flex-direction: column !important;
  align-items: flex-start !important;
}
.msg-bubble-wrapper.msg-me {
  flex-direction: column !important;
  align-items: flex-end !important;
}
.msg-avatar-them-container {
  display: none;
  order: 2;
  margin: 6px 0 0 4px;
  overflow: visible !important;
}
.msg-avatar-me-container {
  display: none;
  order: -1;
  margin: 0 4px 6px 0;
  pointer-events: none;
  overflow: visible !important;
}
.msg-avatar-them-container.is-last,
.msg-avatar-them-container.is-single,
.msg-avatar-me-container.is-first,
.msg-avatar-me-container.is-single {
  display: flex;
  position: relative;
  align-items: flex-end;
  width: auto !important;
  height: auto !important;
  min-height: 0 !important;
}
.msg-avatar-them-ghost,
.msg-avatar-them-inner,
.msg-avatar-me-inner {
  display: none !important;
}
.msg-avatar-them-container.is-last .msg-avatar-them-inner,
.msg-avatar-them-container.is-single .msg-avatar-them-inner {
  display: block !important;
  position: absolute !important;
  inset: 0 !important;
  width: auto !important;
  height: auto !important;
  min-width: 0 !important;
  max-width: none !important;
  margin: 0 !important;
  opacity: 0 !important;
  z-index: 2 !important;
  cursor: pointer !important;
  pointer-events: auto !important;
}
.msg-avatar-them-container::before,
.msg-avatar-me-container::before {
  content: '';
  order: 0;
  flex: none;
  width: 20px;
  height: 21px;
  margin-bottom: 3px;
  padding: 0 3px 0 7px;
  border-bottom: 4px double #E4E4E6;
  background: url("https://img.icons8.com/?size=100&id=N8DMWI6B4OOp&format=png&color=BCBCBE") left 5px top / 20px 20px no-repeat;
}
.msg-avatar-them-container::after,
.msg-avatar-me-container::after {
  order: 1;
  flex: none;
  margin-bottom: 3px;
  padding: 0 7px 2px 0;
  border-bottom: 4px double #E4E4E6;
  white-space: nowrap;
  font-size: 12px;
  color: #BCBCBE;
}
.msg-avatar-them-container::after {
  content: "@" var(--user-name);
}
.msg-avatar-me-container::after {
  content: "@" var(--user-id);
}

