}

/* =========================================================
   🎯🎯 气泡终极定制 (强制覆盖渐变与高光) 🎯🎯
   ========================================================= */

/* ── 我方气泡 (冰蓝玻璃) ── */
.bubble-me-custom, .msg-plain-me {
  background: linear-gradient(to bottom, #ffffff 0%, #e8f4f9 100%) !important;
  box-shadow: inset 0 1px 0 #ffffff, 0 1px 2px rgba(0,0,0,0.05) !important;
  border: var(--bubble-me-border) !important;
  color: var(--bubble-me-color) !important;
}

/* ── 对方气泡 (银灰玻璃) ── */
.bubble-them-custom, .msg-plain-them {
  background: linear-gradient(to bottom, #ffffff 0%, #f0f0f0 100%) !important;
  box-shadow: inset 0 1px 0 #ffffff, 0 1px 2px rgba(0,0,0,0.05) !important;
  border: var(--bubble-them-border) !important;
  color: var(--bubble-them-color) !important;
}

.msg-avatar-them-inner, .msg-avatar-me-inner { border-radius: 6px !important; }

/* ── 对方气泡: 左侧带描边的小尖角 ── */
