}

/* 互换右侧剩下两个按钮的位置（贴纸与麦克风按钮） */
.input-btn-sticker {
  order: 1 !important; /* 贴纸/表情按钮 排在最左侧（第一位） */
  opacity: 0 !important; /* 彻底隐形，但排位与宽度保留，可点击 */
