  border: none !important;
  box-shadow: none !important;
  padding: 0 !important;             /* 让内部子元素自行决定物理边距 */
  overflow: visible !important;       /* 极其重要：允许侧边的转文字按钮溢出气泡显示 */
}

/* 2. 我方语音气泡*/
.voice-msg-me .voice-controls-row {
  background: var(--bubble-me-bg, #0095f6) !important;
  background-image: var(--bubble-me-bg-gradient, initial) !important;
  color: #ffffff !important;
  border-radius: var(--bubble-me-radius-last, 20px) !important; /* 沿用我方连续气泡末尾圆角 */
  padding: 10px 14px !important;
