}

/* =================================================
   按钮侧移控制（查看语音内容按钮 ➔ 移到气泡外旁边去）
   ================================================= */
/* 4. 对方：容器设为 flex 纵向，保证文字卡片在正下方 */
.voice-msg-them {
  position: relative !important;
