}

/* 5. 我方：容器设为 flex 纵向 */
.voice-msg-me {
  position: relative !important;
  display: flex !important;
  flex-direction: column !important;
  align-items: flex-end !important;   /* 我方靠右对齐 */
}

/* 我方的“查看文字”按钮：绝对定位到左侧 10px 处的空白处 */
.voice-msg-me .voice-transcription-toggle {
  position: absolute !important;
  right: calc(100% + 10px) !important;/* 气泡左侧外 */
  top: 10px !important;               /* 与语音条中心对齐 */
  white-space: nowrap !important;
  background: transparent !important;
  border: none !important;
  color: #8e8e93 !important;
  font-size: 11px !important;
  font-weight: 500 !important;
  cursor: pointer !important;
}

/* =================================================
    仿微信语音转写美化（修正：100% 保持您原有的气泡颜色 + 可锁死宽度）
   ================================================= */

/* 1. 骨架剥离：只要大气泡内装的是语音消息，将外层大容器变透明 */
.bubble-me-custom:has(.voice-msg),
.bubble-them-custom:has(.voice-msg) {
