/* =========================================
   全局根变量 (底栏图标、翻译、语音、思维链基础)
   ========================================= */
:root {
  /* 1. 底栏基础与图标替换 */
  --input-area-bg: #FFFFFF; 
  --plus-btn-icon: url('https://i.postimg.cc/BbsPbRm6/retouch-2026080817404802.png');
  --ai-btn-icon: url('https://i.postimg.cc/Wp0pp7Kr/retouch-2026081203230460.png');
  --send-btn-icon: url('https://i.postimg.cc/Wp0pp7Kr/retouch-2026081203230460.png');
  --stop-btn-icon: url('https://i.postimg.cc/Wp0pp7Kr/retouch-2026081203230460.png');

  /* 2. 清理原生输入框背景 */
  --input-box-bg: transparent;
  --input-box-border: none;
  --emoji-panel-bg: transparent;
  --emoji-panel-shadow: none;

  /* 3. 思维链 (Thinking Chain) 极简透明化 */
  --thinking-btn-bg: transparent;
  --thinking-btn-shadow: none;
  --thinking-btn-border: none;
  --thinking-panel-bg: transparent;
  --thinking-panel-shadow: none;
  --thinking-panel-backdrop: none;
  --thinking-panel-border-left: none;

  /* 4. 语音与翻译基础 */
  /* 针对黑白气泡进行高对比度区分：我方(黑底)用白字/白语音条，对方(白底)用黑字/黑语音条 */
  --voice-me-color: #FFFFFF; 
  --voice-them-color: #111111; 
  --voice-me-bar-active: #FFFFFF; 
  --voice-me-bar-inactive: rgba(255, 255, 255, 0.4); 
  --voice-them-bar-active: #000000; 
  --voice-them-bar-inactive: rgba(0, 0, 0, 0.2); 
  --voice-download-display: none;       
  --voice-toggle-display: none;         
  --voice-waveform-height: 18px;        
  --voice-container-gap: 4px;
  --voice-controls-gap: 6px;
  --translation-bg: transparent;
  --translation-separator: 1px dashed rgba(0, 0, 0, 0.4); 
  --translation-padding: 6px 0 0 0;
  --translation-margin: 6px 0 0 0;
  --translation-radius: 0;
}

