/* nuojiji-bubble-config: {"themeStyle":"qq","bubbleStyle":"premium-gradient","partnerBubbleStyle":"#efefef","bubbleTextColor":"","partnerBubbleTextColor":"","avatarSize":32,"avatarShape":"square"} */

/* =========================================
   第一步：开放接口区 (你只需要在这里用 px 调数值！)
   ========================================= */
:root {
  /* --- 1. 返回键贴图调节 --- */
  --icon-back: url('https://i.imgant.com/v2/driW44e.png');
  --icon-back-w: 22px;     /* 宽度 */
  --icon-back-h: 22px;     /* 高度 */
  --icon-back-x: -1px;     /* 左右位置：正数向右，负数向左 */
  --icon-back-y: 0px;      /* 上下位置：正数向下，负数向上 */

  /* --- 2. 视频键贴图调节 --- */
  --icon-video: url('https://i.imgant.com/v2/Kx2Iu54.png');
  --icon-video-w:40px;
  --icon-video-h:40px;
  --icon-video-x: 0px;
  --icon-video-y: 0px;

  /* --- 3. 设置键贴图调节 --- */
  --icon-info: url('https://i.imgant.com/v2/GW7VPyl.png');
  --icon-info-w: 30px;
  --icon-info-h: 30px;
  --icon-info-x: 0px;
  --icon-info-y: 0px;

  /* 顶栏原生变量清理 (无需修改) */
  --chat-header-bg: transparent;
  --chat-header-blur: 0px;
  --chat-header-border: transparent;
  --header-btn-gap: 0px; /* 强制设为 0，为了让视频和设置能紧紧拼在一起 */
}

/* =========================================
   第二步：顶栏透明化 & 隐藏无关元素
   ========================================= */
/* 砸碎顶栏的毛玻璃和阴影 */
.chat-header-custom, .glass-header {
  background: transparent !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  box-shadow: none !important;
  border: none !important;
}

/* 隐藏头像与在线状态，名字绝对居中 */
.header-avatar-container, .chat-header-subtitle { display: none !important; }
.header-profile-section {
  position: absolute !important;
  left: 50% !important;
  transform: translateX(-50%) !important;
  text-align: center;
}

/* =========================================
   第三步：雕刻毛玻璃底座
   ========================================= */
/* A. 返回键：独立圆形底座 */
.header-btn-back {
  background: rgba(255, 255, 255, 0.65) !important;
  backdrop-filter: blur(20px) saturate(180%) !important;
  -webkit-backdrop-filter: blur(20px) saturate(180%) !important;
  border: 1px solid rgba(255, 255, 255, 0.6) !important;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.04) !important;
  border-radius: 50% !important;
  width: 38px !important;
  height: 38px !important;
  position: relative !important;
  margin-left: 12px !important; /* 距离左边缘的间距 */
}

/* B. 通话键：没有任何底座，但把它往左边推，远离胶囊 */
.header-btn-phone {
  background: transparent !important;
  border: none !important;
  margin-right: 12px !important; /* 把它一脚踢开，远离后面的视频键 */
  position: relative !important;
  opacity: 0 !important; 

  /* 你调好之后，只要在这里加上 opacity: 0 !important; 就能隐身了 */
}

/* C. 视频键：胶囊的【左半边】 */
.header-btn-video {
  background: rgba(255, 255, 255, 0.65) !important;
  backdrop-filter: blur(20px) saturate(180%) !important;
  -webkit-backdrop-filter: blur(20px) saturate(180%) !important;
  border: 1px solid rgba(255, 255, 255, 0.6) !important;
  border-right: none !important; /* 关键：去掉右边框，准备和设置键拼接 */
  border-radius: 20px 0 0 20px !important; /* 只有左边是圆角 */
  width: 40px !important;
  height: 38px !important;
  position: relative !important;
}

/* D. 设置键：胶囊的【右半边】 */
.header-btn-info {
  background: rgba(255, 255, 255, 0.65) !important;
  backdrop-filter: blur(20px) saturate(180%) !important;
  -webkit-backdrop-filter: blur(20px) saturate(180%) !important;
  border: 1px solid rgba(255, 255, 255, 0.6) !important;
  border-left: none !important; /* 关键：去掉左边框，准备和视频键拼接 */
  border-radius: 0 20px 20px 0 !important; /* 只有右边是圆角 */
  width: 40px !important;
  height: 38px !important;
  margin-right: 12px !important; /* 距离右边缘的间距 */
  position: relative !important;
}

/* =========================================
   第四步：挂载并精确定位自定义贴图
   ========================================= */
/* 隐藏这三个按钮原本自带的 SVG 矢量图 */
.header-btn-back svg,
.header-btn-video svg,
.header-btn-info svg {
  display: none !important;
}

/* 统一用 ::after 伪元素来装载图片 */
.header-btn-back::after,
.header-btn-video::after,
.header-btn-info::after {
  content: "";
  position: absolute;
  background-size: contain;
  background-repeat: no-repeat;
  background-position: center;
  top: 50%;
  left: 50%;
  pointer-events: none; /* 让点击穿透给按钮本体 */
}

/* 读取上面定义的 px 变量，实现微操控制 */
.header-btn-back::after {
  background-image: var(--icon-back);
  width: var(--icon-back-w);
  height: var(--icon-back-h);
  /* 这里的 calc 魔法，让中心点定位结合你输入的 XY 偏移值 */
  transform: translate(calc(-50% + var(--icon-back-x)), calc(-50% + var(--icon-back-y)));
}

.header-btn-video::after {
  background-image: var(--icon-video);
  width: var(--icon-video-w);
  height: var(--icon-video-h);
  transform: translate(calc(-50% + var(--icon-video-x)), calc(-50% + var(--icon-video-y)));
}

.header-btn-info::after {
  background-image: var(--icon-info);
  width: var(--icon-info-w);
  height: var(--icon-info-h);
  transform: translate(calc(-50% + var(--icon-info-x)), calc(-50% + var(--icon-info-y)));
}
/* =========================================
   第四步点五：底座强力修正 & 绝对微调
   ========================================= */

/* 1. 在这里调整底座的整体位置 (正数向下/右，负数向上/左) */
:root {
  --base-left-y: 0px;     /* 返回键底座：上下微调 */
  --base-left-x: 0px;     /* 返回键底座：左右微调 */

  --base-right-y: -1px;    /* 右侧胶囊(含视频、设置)：整体上下微调 */
  --base-right-x: 10px;    /* 右侧胶囊：整体左右微调 */

  --base-phone-y: 0px;    /* 通话键：单独上下微调 */
}

/* 2. 强制清空原生内边距，确保它们排成完美直线 */
.header-btn-back, 
.header-btn-video, 
.header-btn-info, 
.header-btn-phone {
  padding: 0 !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
}

/* 3. 挂载返回键底座的偏移器 */
.header-btn-back {
  transform: translate(var(--base-left-x), var(--base-left-y)) !important;
}

/* 4. 挂载右侧整体的偏移器（为了不让视频和设置的胶囊散架，我们移动它们的父容器） */
.chat-header-custom > div:last-child {
  transform: translate(var(--base-right-x), var(--base-right-y)) !important;
}

/* 5. 通话键的独立偏移器（它是在上面的父容器里单独移动） */
.header-btn-phone {
  transform: translateY(var(--base-phone-y)) !important;
}
/* =========================================
   第五步：顶栏备注文字自定义 (颜色、大小)
   ========================================= */
:root {
  --header-text-color: #333333; /* 名字颜色 */
  --header-text-size: 16px;     /* 名字大小 */
  --header-text-weight: 600;    /* 名字粗细 (400正常, 600加粗) */
}
.chat-header-title {
  color: var(--header-text-color) !important;
  font-size: var(--header-text-size) !important;
  font-weight: var(--header-text-weight) !important;
}

/* =========================================
   第五步：顶栏下方的白色装饰卡片 (✅ 已修复缺失的花括号)
   ========================================= */

/* --- 1. 卡片微调控制台 (在这里用 px 和 颜色 改数值) --- */
:root {
  /* 卡片尺寸与位置 */
  --card1-w: 400px;       /* 卡片宽度 */
  --card1-h: 220px;       /* 卡片高度 */
  --card1-y: 120px;       /* 距离顶部的距离 (上下位置) */
  --card1-radius: 24px;   /* 圆角大小 */

  /* 卡片外观 */
  --card1-bg: rgba(255, 255, 255, 0.75);         /* 背景色和透明度 */
  --card1-blur: 15px;                            /* 毛玻璃模糊度 */
  --card1-shadow: 0 8px 32px rgba(0, 0, 0, 0.1); /* 阴影 */
} /* 👈👈👈 就是这里！之前少了这个大括号，导致后面全部崩溃！ */

/* --- 2. 启用并塑造卡片 (底层代码，无需修改) --- */

/* 征用 1 号装饰层作为我们的卡片画布 */
.chat-header-custom::before {
  content: "";
  display: block;
  position: absolute;
  z-index: -1; 

  width: var(--card1-w);
  height: var(--card1-h);
  top: var(--card1-y);
  border-radius: var(--card1-radius);
  background: var(--card1-bg);
  backdrop-filter: blur(var(--card1-blur)) saturate(180%);
  -webkit-backdrop-filter: blur(var(--card1-blur)) saturate(180%);
  box-shadow: var(--card1-shadow);

  left: 50%;
  transform: translateX(-50%);
}

/* =========================================
