    /* 📐 控制各个图层的大小 */
    background-size: 
        32px 32px, /* 图层1: 头像大小 */
        20px 20px, /* 图层2: 更多图标大小 */
        100% 1px,  /* 图层3: 分割线贯穿全宽 */
