/* 🎯🎯 3. 输入框白底：注入立体内阴影 + 边缘厚度感 🎯🎯 */
.input-action-bar-custom > *:not(.input-btns-right) {
    flex: 1 !important;
    background: #ffffff !important;
    background-color: #ffffff !important;
    background-image: none !important;
