.nuo-thinking-icon { display: none !important; }
.nuo-thinking-arrow { display: none !important; } 
.nuo-thinking-label {
    /* 隐藏入口文字，但不删除原按钮，不破坏原点击事件 */
    font-size: 0 !important;
