:root {
  --timestamp-color: #8e8e8e;
  --timestamp-size: 11px;
  --timestamp-weight: 400;
  --timestamp-margin: 4px 0 12px;
}

.timestamp-custom {
  display: block !important;
  width: fit-content !important;
  margin: 4px auto 12px !important;
  background: rgba(0, 0, 0, 0.06) !important;
  padding: 2px 8px !important;
  border-radius: 4px !important;
}

/* ===== 输入框占位文字去掉 ===== */
.input-box-custom::placeholder,
.input-box-custom::-webkit-input-placeholder {
  color: transparent !important;
  opacity: 0 !important;
}

.input-area-custom {
  padding: 8px 16px 12px !important;
}

/* ===== 关键：把胶囊容器"隐身"，让内部元素提升到外层，才能真正统一排序 ===== */
.input-action-bar-custom,
.input-btns-right {
  display: contents !important;
}

/* ===== 外层容器：允许换行，输入框独占一行，图标沉到下一行 ===== */
.input-row-wrapper {
  display: flex !important;  /* 修正：添加 flex 容器属性 */
  flex-wrap: wrap !important;
  align-items: center !important;
  gap: 8px !important;
  width: 100% !important;
  position: relative !important;
}

/* 1. 输入框：排最前，强制独占一整行 */
.input-box-custom {
  order: 1 !important;
  flex: 1 1 100% !important;
  min-height: 60px !important;
  background: transparent !important;
  border: none !important;
  margin-bottom: 4px !important;
}

/* 2. 加号 → 笑脸 */
.input-btn-plus {
  order: 2 !important;
}
.input-btn-plus svg { display: none !important; }
.input-btn-plus::after {
  content: '';
  display: inline-block;
  width: 22px;
  height: 22px;
  background-image: url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="%23595959" stroke-width="1.6"><circle cx="12" cy="12" r="9.5"/><circle cx="8.7" cy="10" r="1" fill="%23595959" stroke="none"/><circle cx="15.3" cy="10" r="1" fill="%23595959" stroke="none"/><path d="M8 14.5c1 1.3 2.4 2 4 2s3-.7 4-2" stroke-linecap="round"/></svg>');
  background-repeat: no-repeat;
  background-size: contain;
}

/* 3. 正方体（挂在 row-wrapper 自身的伪元素上，稳定不消失，排第二） */
.input-row-wrapper::before {
  content: '';
  order: 3 !important;
  display: inline-block;
  width: 22px;
  height: 22px;
  background-image: url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="%23595959" stroke-width="1.6" stroke-linejoin="round"><path d="M12 3l8 4.5v9L12 21l-8-4.5v-9L12 3z"/><path d="M4.5 7.5L12 12l7.5-4.5"/><path d="M12 12v9"/></svg>');
  background-repeat: no-repeat;
  background-size: contain;
  pointer-events: none;
}
/* 4. 文件夹 + 剪刀（剪刀在文件夹右侧） */
.input-btn-sticker {
  order: 4 !important;
  display: inline-flex !important;
  align-items: center !important;
  gap: 3px !important;
}
.input-btn-sticker svg { display: none !important; }

/* 文件夹图标 */
.input-btn-sticker::before {
  content: '';
  display: inline-block;
  width: 24px;
  height: 20px;
  background-image: url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 28 22" fill="none" stroke="%23595959" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><path d="M2 5.5a1.5 1.5 0 0 1 1.5-1.5h4l1.5 2h9a1.5 1.5 0 0 1 1.5 1.5v9a1.5 1.5 0 0 1-1.5 1.5h-14A1.5 1.5 0 0 1 2 16.5v-11z"/></svg>');
  background-repeat: no-repeat;
  background-size: contain;
}

/* 剪刀图标 */
.input-btn-sticker::after {
  content: '';
  display: inline-block;
  width: 20px;
  height: 25px;
  transform: rotate(90deg) !important;
  background-image: url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="%23595959" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><circle cx="6" cy="6" r="2.2"/><circle cx="6" cy="18" r="2.2"/><path d="M7.5 7.5L20 18"/><path d="M7.5 16.5L20 6"/></svg>');
  background-repeat: no-repeat;
  background-size: contain;
}

/* 在剪刀右侧添加向下箭头（使用 background-image 叠加） */
.input-btn-sticker {
  position: relative !important;
}
.input-btn-sticker::after {
  margin-right: 8px !important; /* 给箭头留空间 */
}
.input-btn-sticker {
  background-image: url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="%23595959" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="6 9 12 15 18 9"/></svg>') !important;
  background-repeat: no-repeat !important;
  background-position: right center !important;
  background-size: 13px 13px !important;
  padding-right: 8px !important;
}

/* 5. 麦克风 */
.input-btn-mic {
  order: 5 !important;
}
.input-btn-mic svg { display: none !important; }
.input-btn-mic::after {
  content: '';
  display: inline-block;
  width: 22px;
  height: 22px;
  background-image: url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="%23595959" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><rect x="9" y="2" width="6" height="12" rx="3"/><path d="M5 11a7 7 0 0 0 14 0"/><path d="M12 18v3"/><path d="M9 21h6"/></svg>');
  background-repeat: no-repeat;
  background-size: contain;
}
.input-btn-mic {
  order: 5 !important;
  margin-left: -7px !important;  /* 加这一行，数值越大越靠左 */
}

/* 6. 发送：最右侧灰色块 */
.input-btn-ai {
  order: 6 !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  white-space: nowrap !important;
  background: #ededed !important;
  color: #333333 !important;
  border-radius: 4px !important;
  padding: 5px 16px !important;
  font-size: 13px !important;
  margin-left: auto !important;
}
.input-btn-ai svg { display: none !important; }
.input-btn-ai::after {
  content: '发送';
  white-space: nowrap !important;
}
:root{
