/* =========================================================
   ☀️🌙 全局最高优先级：强制暴力覆盖日夜间变量切换
   ========================================================= */

/* --- ☀️ 日间模式强制指令 --- */
@media (prefers-color-scheme: light) {
  /* 拦截原生所有可能带有主题的标签，强制注入日间变量 */
  :root, html, body, [data-theme="dark"], [data-theme="light"], .dark-theme, .light-theme, #app {
    /* 👇 顶栏日间配色 */
    --chat-header-bg: #ffffff !important;
    --top-name-color: #a0a0a0 !important;
    --top-back-color: #a0a0a0 !important;
    --top-menu-color: #a0a0a0 !important;

    /* 👇 底栏输入框配色 */
    --input-area-bg: #ffffff !important;
    --input-box-bg: #ffffff !important;
    --input-box-color: #000000 !important;
    --input-box-placeholder: #a0a0a0 !important;

    /* 👇 气泡配色  */
    --bubble-me-bg: #a0a0a0 !important;
    --bubble-me-color: #ffffff !important;
    --bubble-them-bg: #f0f0f0 !important;
    --bubble-them-color: #262626 !important;

