}
/* =================================== */
/* 🛠️ 锁定生成状态下输入框文案尺寸 */
/* =================================== */

/* 无论是在正常状态、禁用状态还是生成回复状态，都强制锁死文案大小 */
.input-box-custom:placeholder-shown,
.input-box-custom:disabled:placeholder-shown,
.input-box-custom[disabled]:placeholder-shown {
