/* ==========================================
全局变量与间距控制
========================================== */
:root {
  /* 换人说话时的间距（你和对方气泡之间的距离） */
  --plain-gap-between-groups: 28px;

  /* 把官方的连发间距清零，我们下面自己写 */
  --plain-gap-within-group: 0px;
  /*放开整个消息外壳的最大宽度 */
  --plain-content-max-width: 85%; 
  --input-area-min-height: 80px;
}

/* 1. 自己连发时的间距（除了最后一条，每条下面加空隙） */
.msg-bubble-wrapper.msg-me.is-first,
.msg-bubble-wrapper.msg-me.is-mid {
  margin-bottom: 8px !important; /* 调你这边的连发间距 */
}

/* 2. 对方连发时的间距（除了最后一条，每条下面加空隙） */
.msg-bubble-wrapper.msg-them.is-first,
.msg-bubble-wrapper.msg-them.is-mid {
  margin-bottom: 10px !important; /* 调对方的连发间距 */
}
/* ==========================================
顶栏：好友申请卡片样式
========================================== */

/* 1. 顶栏底座：终极自适应版 (保住底部白色高度) */
.chat-header-custom {
  /* 总高度 = 固定内容高度(140px) + 安全距离。安卓是140，苹果是140+刘海 */
  height: calc(96px + env(safe-area-inset-top)) !important;
  /* 从下往上渐变：底部固定 80px 是白色，80px 以上全透明透出图片 */
  background-image: linear-gradient(to top, #ffffff 58px, transparent 58px), url('https://nos.netease.com/ysf/3670e57fa9cc7134dccfd9e24cfa32a4.jpeg') !important;
  background-size: 100% 100%, cover !important;
  background-position: top center !important;
  background-repeat: no-repeat !important;
  border-bottom-left-radius: 0px !important;
  border-bottom-right-radius: 0px !important;
  box-shadow: 0 4px 16px rgba(0,0,0,0.06) !important;
  align-items: flex-end !important;
  padding-bottom: 14px !important;
}

/* 2. 拍立得头像 */
.header-profile-section {
  align-items: flex-start !important;
  margin-bottom: -5px !important;
  padding-left: 16px !important;
}
.header-avatar-container {
  width: 68px !important;
  height: 68px !important;
  background-color: #fff !important;
  padding: 4px 4px 10px 4px !important;
  border-radius: 2px !important;
  border: 1px solid #eee !important;
  box-shadow: 0 2px 12px rgba(0,0,0,0.1) !important;
  transform: rotate(-3deg) !important;
  margin-top: 22px !important;
  margin-right: 12px !important;
  margin-left: -26px !important; /* 头像往左挪 */
}
.header-avatar-container img {
  border-radius: 0 !important;
}

/* 3. 名字与副标题 */
.chat-header-title {
  position: absolute !important; 
  bottom: 12px !important; /* 关键：改成 bottom，从下往上量。数字你自己微调 */
  top: auto !important; /* 清除之前的 top */
  left: 124px !important; 
  font-size: 16px !important;
  letter-spacing: -0.5px !important;
  white-space: nowrap !important; 
  /* ⬇️ 加上这三行防身 ⬇️ */
