   ================================================================ */

/* 1. 解除原生按钮的尺寸封印，维持隐身即可 */
body, :root {
  --voice-toggle-opacity: 0 !important;
  --voice-toggle-size: 1px !important;  
}

/* 2. 核心：把透明的按钮从最后面抽出来覆在波形图上 */
.msg-voice-card {
  position: relative !important;
}

/* 精准抓取转文字开关，脱离排版 */
[class*="voice-transcription-toggle"],
[class*="voice-toggle"] {
  position: absolute !important;
  inset: 0 0 0 44px !important;  
  width: auto !important;
  height: 100% !important;
  opacity: 0 !important;       
  z-index: 10 !important;     
  margin: 0 !important;
  padding: 0 !important;
  cursor: pointer !important;
}

/* 消除原位置残留占位，防止时间戳被往左挤压 */
.voice-duration {
  margin-right: 0 !important;
}
/* ===== 锁死发送键大小，强制关闭软件自带的缩放/出现动画 =====by烧酒酒 */
.send-btn-custom,
.send-btn-custom:active,
.send-btn-custom:focus {
    transform: scale(1) translateY(0px) !important;
    transition: none !important; /* 彻底关掉自带的过渡动画 */
    animation: none !important;  /* 彻底关掉自带的帧动画 */
}
