/* 1. 紧凑气泡基础变量 */
#chat-detail-screen {
  /* 我方气泡：纯黑空心线框 */
  --bubble-me-bg: transparent;
  --bubble-me-color: #000000;                                       /* 🤍 我方文字颜色 */
  --bubble-me-border: 1.5px solid #000000;                          /* 🤍 我方气泡边框 */
  --bubble-me-radius: 18px;                                         /* 🤍 我方气泡圆角 */
  --bubble-me-padding: 7px 14px;                                    /* 🤍 我方气泡上下/左右内边距 */
  --bubble-me-font-size: 15px;                                      /* 🤍 我方字号 */
  --bubble-me-line-height: 1.4;
  --bubble-me-shadow: none;

  /* 对方气泡：浅灰空心线框 */
  --bubble-them-bg: transparent;
  --bubble-them-color: #18181b;                                     /* 🤍 对方文字颜色 */
  --bubble-them-border: 1px solid #d4d4d8;                          /* 🤍 对方气泡边框 */
  --bubble-them-radius: 15px;                                       /* 🤍 对方气泡圆角 */
  --bubble-them-padding: 7px 13px;                                  /* 🤍 对方气泡上下/左右内边距 */
  --bubble-them-font-size: 15px;                                    /* 🤍 对方字号 */
  --bubble-them-line-height: 1.4;
  --bubble-them-shadow: none;
}

#chat-detail-screen .bubble-me-custom,
#chat-detail-screen .bubble-them-custom {
  background: transparent !important;
}

/* 2. 隐藏我方气泡旁头像 */
