    filter: invert(1) !important;
  }

  /* 4. 底栏药丸与下划线反白 */
  #chat-detail-screen .input-area-custom::before,
  #chat-detail-screen .input-area-custom::after,
  #chat-detail-screen .input-row-wrapper::after {
    border-color: #3f3f46 !important;                               /* 🤍 夜间药丸边框 */
