    --voice-them-bar-inactive: rgba(255, 255, 255, 0.35) !important;/* 未播放：透亮银白 */
  }

  #chat-detail-screen .msg-me .voice-controls-row {
    border-color: #ffffff !important;
  }
  #chat-detail-screen .msg-them .voice-controls-row {
    border-color: #71717a !important;
  }

  /* ⚡ 强制夜间播放按键纯白、波形透白、时间文字提亮 ⚡ */
  #chat-detail-screen .voice-play-btn {
