  font-weight: var(--transfer-amount-weight) !important;
  color: var(--transfer-amount-color) !important;
  z-index: 10 !important;
  margin: 0 !important;
  padding: 0 !important;
  line-height: 1 !important;
}

/* 3. 强制里面所有的字都继承我们设定的颜色和大小 */
.msg-transfer-card:not(.msg-redpacket-card) .msg-transfer-amount * {
  color: inherit !important;
  font-size: inherit !important;
  font-weight: inherit !important;
}

/* 🌙 夜间模式金额变色 */
@media (prefers-color-scheme: dark) {
  :root, html, body, [data-theme="dark"], [data-theme="light"], .dark-theme, .light-theme, #app {
    --transfer-amount-color: #fcfcfc !important; 
  }
}
/* =================================== */
/* 💸 附加：转账仅收款后显示金额 + 收款前后标题位置独立 */
/* =================================== */
:root {
  /* 👇 已收转账时，原生标题的专属上下位置（往上挪给金额腾地方） */
  --transfer-sub-y-done: 5px; 
}

/* 1. 未收转账时，强制隐藏转账金额（防穿模） */
.msg-transfer-card:not(.msg-transfer-success):not(.msg-redpacket-card) .msg-transfer-amount {
  display: none !important;
}

/* 2. 已收转账时（success），原生的“转账给xx”强行替换到专属位置！ */
.msg-transfer-card.msg-transfer-success:not(.msg-redpacket-card) .msg-transfer-subtitle {
