  --chat-header-title-size: 16px;
  --chat-header-title-weight: 700;
  --chat-header-subtitle-color: #D48AA8;        /* 原 #FFD5E3 → 深粉 */
  --chat-header-subtitle-size: 12px;
  --chat-header-icon-color: #1D1B37;
  --chat-header-avatar-size: 34px;
  --chat-header-avatar-border: 2px solid #FFE6F0;
  --chat-header-avatar-radius: 50%;
  --chat-header-avatar-shadow: none;
  --header-btn-gap: 18px;

  /* === 消息区域 === */
  --chat-messages-padding: 12px 16px;
  --chat-messages-gap: 3px;
  --chat-message-max-width: 78%;

  /* === 我方气泡 === */
  --bubble-me-bg: #FFF4FA;
  --bubble-me-bg-gradient: initial;
  --bubble-me-color: #1D1B37;
  --bubble-me-font-size: 15px;
  --bubble-me-line-height: 1.5;
  --bubble-me-padding: 5px 16px;
  --bubble-me-radius: 10px;
  --bubble-me-radius-first: 10px 10px 3px 10px;
  --bubble-me-radius-mid: 10px 3px 3px 10px;
  --bubble-me-radius-last: 10px 3px 10px 10px;
  --bubble-me-shadow: 0 2px 6px rgba(29,27,55,0.06);
  --bubble-me-border: 1.5px solid #1D1B37;
  --bubble-me-link-color: #F5A0B8;
  --bubble-me-text-shadow: none;
  --bubble-me-letter-spacing: normal;
  --bubble-me-backdrop: none;
  --bubble-me-filter: none;
  --bubble-me-opacity: 1;
  --bubble-me-transform: none;

  /* === 对方气泡 === */
  --bubble-them-bg: #ffffff;
  --bubble-them-bg-gradient: initial;
  --bubble-them-color: #1D1B37;
  --bubble-them-font-size: 15px;
  --bubble-them-line-height: 1.5;
  --bubble-them-padding: 5px 16px;
  --bubble-them-radius: 10px;
  --bubble-them-radius-first: 10px 10px 10px 3px;
  --bubble-them-radius-mid: 3px 10px 10px 3px;
  --bubble-them-radius-last: 3px 10px 10px 10px;
  --bubble-them-shadow: 0 2px 6px rgba(29,27,55,0.06);
  --bubble-them-border: 1.5px solid #1D1B37;
  --bubble-them-link-color: #F5A0B8;
  --bubble-them-text-shadow: none;
  --bubble-them-letter-spacing: normal;
  --bubble-them-backdrop: none;
  --bubble-them-filter: none;
  --bubble-them-opacity: 1;
  --bubble-them-transform: none;

  /* === 头像 === */
  --avatar-size: 38px;
  --avatar-radius: 50%;
  --avatar-border: 2px solid #FFE6F0;
  --avatar-margin: 8px;
  --avatar-shadow: none;
  --avatar-placeholder-bg: #FFF6FC;

  /* === 引用 & 回复 === */
  --quote-border-color: #D48AA8;               /* 深粉边框 */
  --quote-text-color: #B07088;                /* 原 #4A6B85 → 深粉 */
  --code-bg: #FFF6FC;
  --code-color: #1D1B37;
  --reply-block-bg: #FFF6FC;
  --reply-block-name-color: #B07088;          /* 原 #1D1B37 → 深粉 */
  --reply-block-text-color: #B07088;          /* 原 #4A6B85 → 深粉 */
  --reply-block-radius: 10px;
  --reply-block-border: none;
  --reply-block-border-left: 3px solid #D48AA8;/* 原 #FFD8E5 → 深粉 */

  /* === 旁白消息 === */
  --narration-color: #D48AA8;                 /* 原 #FFD5E3 → 深粉 */
  --narration-size: 0.87em;
  --narration-style: italic;
  --narration-text-align: center;

  /* === 时间戳 & 日期分隔线 === */
  --timestamp-color: #D48AA8;                 /* 原 #FFD8E5 → 深粉 */
  --timestamp-size: 11px;
  --date-divider-color: #D48AA8;              /* 原 #FFD5E3 → 深粉 */
  --date-divider-size: 12px;
  --date-divider-weight: 600;

  /* === IG/QQ 已读状态 === */
  --status-color: #D48AA8;                    /* 原 #FFD8E5 → 深粉 */
  --status-read-color: #D48AA8;              /* 原 #F5A0B8 → 深粉（统一） */

  /* === 输入区域 === */
  --input-area-bg: #ffffff;
  --input-area-bg-image: none;
  --input-area-blur: 0px;
  --input-area-border-top: 1px solid #FFE6F0;
  --input-area-padding: 12px 16px;
  --input-area-min-height: 56px;

  --input-box-bg: #ffffff;
  --input-box-color: #B07890;                /* 原 #1D1B37 → 深粉（输入文字） */
  --input-box-placeholder: #D48AA8;          /* 原 #FFD8E5 → 深粉 */
  --input-box-radius: 24px;
  --input-box-padding: 10px 18px;
  --input-box-font-size: 15px;
  --input-box-border: 1.5px solid #FFE6F0;
  --input-box-blur: none;
  --input-box-shadow: none;
  --input-caret-color: #B07088;              /* 原 #1D1B37 → 深粉 */

  --input-btn-color: #FFE6F0;
  --plus-btn-bg: transparent;
  --plus-btn-color: #B07088;                 /* 原 #1D1B37 → 深粉 */
  --plus-btn-size: 24px;

  /* === 发送按钮 === */
  --send-btn-bg: #FFE6F0;
  --send-btn-bg-hover: #D48AA8;              /* 原 #FFD8E5 → 深粉 */
  --send-btn-color: #B07088;                 /* 原 #1D1B37 → 深粉 */
  --send-btn-size: 34px;
  --send-btn-radius: 50%;
  --send-btn-shadow: none;

  --stop-btn-bg: #1D1B37;
  --stop-btn-color: #ffffff;
  --stop-btn-radius: 50%;

  /* === 回复预览栏 === */
  --reply-bar-accent: #D48AA8;               /* 原 #F5A0B8 → 深粉 */
  --reply-bar-text-color: #D48AA8;           /* 原 #FFD5E3 → 深粉 */

  /* === 更多选项面板 === */
  --more-options-bg: rgba(255,255,255,0.95);
  --more-options-blur: blur(20px) saturate(160%);
  --more-options-shadow: 0 8px 24px rgba(29,27,55,0.12);
  --more-options-color: #B07088;             /* 原 #1D1B37 → 深粉 */
  --more-options-divider: #FFF6FC;

  /* === 打字指示器 === */
  --typing-dot-color: #D48AA8;               /* 原 #FFD8E5 → 深粉 */
  --typing-bg: #FFF4FA;
  --typing-radius: 18px;

  /* === 滚动条 === */
  --scrollbar-width: 4px;
  --scrollbar-track: transparent;
  --scrollbar-thumb: #FFE6F0;
  --scrollbar-thumb-hover: #D48AA8;          /* 原 #FFD8E5 → 深粉 */

  /* === 图片消息 === */
  --image-msg-radius: 18px;
  --image-msg-shadow: 0 2px 12px rgba(29,27,55,0.1);
  --image-msg-border: 1.5px solid #FFE6F0;

  /* === 系统消息 === */
  --system-msg-bg: #FFF6FC;
  --system-msg-color: #D48AA8;               /* 原 #FFD5E3 → 深粉 */
}

