  box-shadow: none !important;
}

/* 底栏去掉上边框 */
:root {
  --input-area-border-top: none;
}

/* 关键：消息列表顶部留出空间，避开增高后的顶栏 */
.chat-messages-area {
  padding-top: 100px !important; /* 和 --chat-header-height 保持一致 */
}

/* 或者用 calc 自动计算 */
.chat-messages-area {
  padding-top: calc(100px + env(safe-area-inset-top, 0px)) !important;
}

/* 隐藏顶栏头像 */
.header-avatar-container {
  display: none !important;
}

/* ⭐顶栏标题 */
.chat-header-title {
  color: rgba(255, 255, 255, 0.45) !important;      /* 介于 0.35 和 0.5 之间 */
  font-size: 14px !important;                       /* 缩小字号 */
  font-weight: 400 !important;                      /* 加粗一点（300 → 400） */
}

/* 如果顶栏不是透明背景，用纯灰色 */
.chat-header-title {
  color: #b3b3b3 !important;        /* 介于 #999 和 #ccc 之间 */
  font-size: 14px !important;       /* 缩小字号 */
  font-weight: 400 !important;      /* 加粗一点（300 → 400） */
}

/* 在标题前加 @ 并整体左移 */
.chat-header-title::before {
  content: "@" !important;
  color: inherit !important;           /* 继承标题颜色（淡灰色） */
  margin-right: 2px !important;
}

/* ⭐ 标题本体/角色备注：调上下左右 */
.chat-detail-screen .chat-header-title {
  transform: translateX(244px) translateY(40px) !important;
  /* X：数值越大越往右；Y：数值越大越往下 */
  margin: 0 !important;
  padding: 0 !important;

  /* ⭐ 中划线：从中间实色→两端平滑渐变虚化 */
  text-decoration: line-through !important;
  text-decoration-color: #bebebe !important;
  text-decoration-thickness: 0.8px !important;
  text-decoration-style: solid !important;

  /* 遮罩：两端最低透明度 0.35，虚化更淡 */
  -webkit-mask-image: linear-gradient(to right, 
    rgba(0,0,0,0.35) 0%,
    rgba(0,0,0,0.5) 10%,
    rgba(0,0,0,0.65) 20%,
    rgba(0,0,0,0.78) 30%,
    rgba(0,0,0,0.9) 40%,
    black 50%,
    rgba(0,0,0,0.9) 60%,
    rgba(0,0,0,0.78) 70%,
    rgba(0,0,0,0.65) 80%,
    rgba(0,0,0,0.5) 90%,
    rgba(0,0,0,0.35) 100%
  ) !important;
  -webkit-mask-size: 100% 100% !important;
  -webkit-mask-repeat: no-repeat !important;
  mask-image: linear-gradient(to right, 
    rgba(0,0,0,0.35) 0%,
    rgba(0,0,0,0.5) 10%,
    rgba(0,0,0,0.65) 20%,
    rgba(0,0,0,0.78) 30%,
    rgba(0,0,0,0.9) 40%,
    black 50%,
    rgba(0,0,0,0.9) 60%,
    rgba(0,0,0,0.78) 70%,
    rgba(0,0,0,0.65) 80%,
    rgba(0,0,0,0.5) 90%,
    rgba(0,0,0,0.35) 100%
  ) !important;
  mask-size: 100% 100% !important;
  mask-repeat: no-repeat !important;
}

