/* 底栏本体：透明无分层 */
.input-area-custom {
  background: transparent !important;
  border-top: none !important;
  border-bottom: none !important;
  box-shadow: none !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  min-height: 80px !important;
  padding: 10px 16px !important;
  position: relative !important;
  /* 【修改】去掉 z-index: 1，防止整个底栏层级乱套挡住面板 */
  /* z-index: 1 !important;  <- 删除这行 */

  /* 【修改】必须改成 visible！否则弹出的面板会被一刀切隐藏 */
  overflow: visible !important; 
}

/* ⭐底栏背景图 */
.input-area-custom::before {
  content: "" !important;
  position: absolute !important;
  top: 45% !important; 
  left: 50% !important; 
  transform: translate(-50%, -50%) !important;
  width: 90% !important;
  height: 90% !important;
  background-image: url("https://imgbed.heliar.top/i/To1XAqqJNyBAQzN-_retouch_2026090410434686.webp") !important;
  background-size: contain !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
  pointer-events: none !important; /* 背景图不挡点击，正确 */
  z-index: -1 !important; /* 【修改】背景图层级改为负数，绝对不能挡住上面的元素 */

  filter: grayscale(100%) brightness(1.0) !important;
  opacity: 0.25 !important;
}

/* 输入框：去掉边框 + 去掉底色 */
.input-box-custom {
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  outline: none !important;
  color: #999999 !important;
  -webkit-text-fill-color: #666666 !important;
  caret-color: #666666 !important;
}

