/* 隐藏四个按键的原生图标：必须保留原本的空间，只做透明处理！ */
.input-btn-plus svg,
.input-btn-mic svg,
.input-btn-sticker svg,
.input-btn-ai svg {
  /* 【修改】不要用 display: none 和 pointer-events: none！ */
  /* 让它们变成全透明，但是依旧留在原地“接客”，这样前端 JS 才能正确监听到点击事件 */
  opacity: 0 !important; 
  background-color: transparent !important;
}

/* 四个按钮整体往上挪 */
.input-btn-plus,
.input-btn-mic,
.input-btn-sticker,
.input-btn-ai {
