/* ========================================
   第一步：悬浮顶栏 (Header)
======================================== */
:root {
    --chat-header-bg: rgba(255, 255, 255, 0.15); 
    --chat-header-blur: 12px; 
    --chat-header-border: 1px solid rgba(255, 255, 255, 0.3); 
    --chat-header-title-color: #333333; 
    --chat-header-title-size: 16px;
    --chat-header-title-weight: 600;
    --chat-header-subtitle-color: transparent; 
}

.chat-header-custom {
    margin: 45px 15px 10px 15px !important; 
    width: calc(100% - 30px) !important;
    height: 44px !important; 
    min-height: 44px !important;
    border-radius: 25px !important; 
    overflow: visible !important; 
    box-shadow: 0 4px 20px rgba(0, 0, 0, 0.05) !important;
}

.header-avatar-container { display: none !important; }

.header-profile-section {
    position: absolute !important;
    left: 0; top: 0;
    width: 100% !important; height: 100% !important;
    display: flex !important;
    align-items: center !important;
    justify-content: center !important;
    overflow: visible !important; 
    pointer-events: none;
}

.chat-header-title { text-align: center !important; }

.header-btn-back, .header-btn-phone, .header-btn-video, .header-btn-info, .header-action-btn {
    background: transparent !important; 
    position: static !important; 
}
.header-btn-back svg, .header-btn-phone svg, .header-btn-video svg, .header-btn-info svg, .header-action-btn svg {
    opacity: 0 !important; 
}

/* ========================================
   第二步：3个圆形 + 太阳图标
======================================== */
.chat-header-custom::before {
    content: ''; position: absolute; 
    top: 64px; left: 5px;
    width: 44px; height: 44px; border-radius: 50%;
    background: url('https://nos.netease.com/ysf/d7a37564c597fd97ed94f9f8e072dc3c.png') center/cover;
    z-index: 3; pointer-events: none;
}

.chat-header-custom::after {
    content: ''; position: absolute; 
    top: 64px; left: 56px; 
    width: 44px; height: 44px; border-radius: 50%;
    background: url('https://nos.netease.com/ysf/a356d1eb1b6e27775cd7ce9ff8abad53.png') center/cover;
    z-index: 2; pointer-events: none;
}

.header-profile-section::before {
    content: ''; position: absolute; 
    top: 64px; left: 107px; 
    width: 44px; height: 44px; border-radius: 50%;
    background: url('https://nos.netease.com/ysf/14d847d9edc112ed0f870d24f3db93fa.png') center/cover;
    z-index: 1; pointer-events: none;
}

.header-profile-section::after {
    content: ''; position: absolute; 
    top: 70px; right: 5px;
    width: 32px; height: 32px;
    background: url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="%23888888" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="5"/><path d="M12 1v2M12 21v2M4.22 4.22l1.42 1.42M18.36 18.36l1.42 1.42M1 12h2M21 12h2M4.22 19.78l1.42-1.42M18.36 5.64l1.42-1.42"/></svg>') center/contain no-repeat;
    z-index: 1; pointer-events: none;
}

/* ========================================
   第三步：固定横线 + Email 信封 + Send/Cancel 按钮 + 名字
======================================== */
.chat-header-title::before {
    content: ''; position: absolute;
    top: 125px; left: 0;
    width: 100%; height: 1px;
    background: rgba(0, 0, 0, 0.15); 
    box-shadow: 0 58px 0 0 rgba(0, 0, 0, 0.15);
    pointer-events: none;
}

.chat-header-title::after {
    content: 'email'; 
    position: absolute;
    top: 140px; left: 5px;
    height: 28px;
    display: flex; align-items: center;
    font-size: 18px; font-weight: bold; color: #333333;
    padding-left: 36px;
    background: url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="%23333333" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M4 4h16c1.1 0 2 .9 2 2v12c0 1.1-.9 2-2 2H4c-1.1 0-2-.9-2-2V6c0-1.1.9-2 2-2z"/><polyline points="22,6 12,13 2,6"/></svg>') left center / 26px no-repeat;
    pointer-events: none;
}

/* ★★★ Send 按钮 (深灰色) ★★★ */
.header-btn-back::before {
    content: 'Send';
    position: absolute;
    top: 115px; 

    /* 👇👇👇 【调整 Send 按钮左右位置】 👇👇👇 */
    /* 当前是 -270px。因为它是 right 属性： */
    /* 想要往【左】移：把数字变小（比如改成 -200px, -150px） */
    /* 想要往【右】移：把数字变大（比如改成 -300px, -320px） */
    right: -230px; 

    width: 70px; height: 30px; 
    display: flex; align-items: center; justify-content: center;
    background: #333333; color: #ffffff;
    font-size: 14px; font-weight: 600;
    border-radius: 0; border: 1px solid #ffffff; 
    box-sizing: border-box; pointer-events: none;
}

/* ★★★ Cancel 按钮 (浅灰色) ★★★ */
.header-btn-back::after {
    content: 'Cancel';
    position: absolute;
    top: 115px; 

    /* 👇👇👇 【调整 Cancel 按钮左右位置】 👇👇👇 */
    /* 当前是 -350px。规律同上： */
    /* 想要往【左】移：把数字变小（比如改成 -280px, -230px） */
    /* 想要往【右】移：把数字变大（比如改成 -400px, -420px） */
    /* 💡注意：Cancel 的数字最好比 Send 大 80 左右，这样两个按钮才不会重叠！ */
    right: -310px; 

    width: 70px; height: 30px; 
    display: flex; align-items: center; justify-content: center;
    background: #b3b3b3; color: #ffffff;
    font-size: 14px; font-weight: 600;
    border-radius: 0; border: 1px solid #ffffff; 
    box-sizing: border-box; pointer-events: none;
}

/* ★★★ 名字 (XXX の) ★★★ */
.header-btn-phone::after {
    content: var(--char-name) 'の'; 
    position: absolute;
    top: 170px; 

    /* 👇👇👇 【调整名字左右位置】 👇👇👇 */
    /* 当前是 -265px。因为它是 left 属性： */
    /* 想要往【右】移：把数字变小（比如改成 -200px, -150px） */
    /* 想要往【左】移：把数字变大（比如改成 -300px, -350px） */
    left: -225px; 

    font-size: 30px; 
    font-weight: bold; 
    color: #333333;
    white-space: nowrap !important; 
    pointer-events: none;
}

/* ========================================
   第四步：聊天区域的外框
======================================== */
.chat-messages-area { background: transparent !important; }

.chat-message-list-custom {
    border: 1px solid rgba(255, 255, 255, 0.6) !important;
