/* ==========================================================
   二、气泡与头像规则 (限定首条)
========================================================== */
.msg-avatar-them-container,
.msg-avatar-me-container { display: none !important; }

.msg-avatar-them-container.is-first,
.msg-avatar-them-container.is-single,
.msg-avatar-me-container.is-first,
.msg-avatar-me-container.is-single {
  display: block !important;
}

.msg-bubble-wrapper:not(.is-first):not(.is-single).msg-them .msg-content-stack { margin-left: 16px !important; }
.msg-bubble-wrapper:not(.is-first):not(.is-single).msg-me .msg-content-stack { margin-right: 16px !important; }

.bubble-them-custom,
.bubble-me-custom {
  position: relative !important;
  overflow: visible !important;
}

/* 对方气泡贴图 */
.msg-bubble-wrapper.is-first .bubble-them-custom::before,
.msg-bubble-wrapper.is-single .bubble-them-custom::before {
  content: '';
  position: absolute;
  top: -12px;
  left: -8px;
  width: 22px;
  height: 22px;
  background: url('https://i.postimg.cc/cLX99xtd/quality-restoration-20260720221451512.jpg') no-repeat center/contain;
  pointer-events: none;
  z-index: 2;
  mix-blend-mode: multiply;
  opacity: 0.4;
  transform: rotate(-10deg);
}

/* 我方气泡贴图 */
.msg-bubble-wrapper.is-first .bubble-me-custom::after,
.msg-bubble-wrapper.is-single .bubble-me-custom::after {
  content: '';
  position: absolute;
  top: -12px;
  right: -8px;
  width: 24px;
  height: 24px;
  background: url('https://i.postimg.cc/T1VQrfXM/quality-restoration-20260720221440088.jpg') no-repeat center/contain;
  pointer-events: none;
  z-index: 2;
  mix-blend-mode: multiply;
  opacity: 0.4;
  transform: rotate(5deg);
}

/* ==========================================================
   三、旁白消息 (猫爪包裹)
========================================================== */
.msg-narration-custom {
  position: relative !important;
  display: inline-block !important; 
  margin: 12px auto !important;     
}

.msg-narration-custom::before {
  content: '';
  position: absolute;
  top: 50%;
  left: 0;                
  transform: translateY(-50%);
  width: 18px;
  height: 18px;
  background: url('https://i.postimg.cc/bvnSxny6/retouch-2026072113150913.png') no-repeat center/contain;
