}

.msg-narration-custom::after {
  content: '';
  position: absolute;
  top: 50%;
  right: 0;               
  transform: translateY(-50%);
  width: 18px;
  height: 18px;
  background: url('https://i.postimg.cc/k4FVZdt6/retouch-2026072113152414.png') no-repeat center/contain;
  pointer-events: none;
  opacity: 0.8;
  margin-left: 0 !important;
}

/* ==========================================================
   四、翻译气泡 (灰线边框 + 星星猫)
========================================================== */
.msg-translation-content {
  position: relative !important;
  display: block !important; 
  background: #ffffff !important;               
  margin: 6px -4px -4px -4px !important;        
  padding: 8px 12px !important;
