  z-index: 5;
}

/* ==========================================================
   五、特殊消息强制扒皮 (图片/表情包/通话/纯文字便签)
========================================================== */
.bubble-them-custom:has(.msg-sim-card), .bubble-me-custom:has(.msg-sim-card),
.bubble-them-custom:has(.msg-call), .bubble-me-custom:has(.msg-call),
.bubble-them-custom:has(.msg-system), .bubble-me-custom:has(.msg-system),
.bubble-them-custom:has(.msg-image-wrapper), .bubble-me-custom:has(.msg-image-wrapper),
.bubble-them-custom:has(svg), .bubble-me-custom:has(svg),
.msg-plain-me:has(.msg-sim-card), .msg-plain-them:has(.msg-sim-card),
.msg-bubble-container:has(.msg-sim-card) {
  background: none !important;
  border: none !important;
  box-shadow: none !important;
  padding: 0 !important;
}

/* 1. 专属文字图卡片：手绘猫咪边框 (完美内嵌防溢出版) */
.msg-sim-card:not(:has(img)) {
  background-image: url('https://i.postimg.cc/3R93NWK2/retouch-2026072120403080.png') !important;
  background-color: transparent !important;
  background-size: 100% 100% !important; 
  background-repeat: no-repeat !important;
  box-shadow: none !important; 
  border: none !important;

  width: 185px !important;
  height: 140px !important;

  position: relative !important;
  padding: 0 !important;
  overflow: hidden !important; 

  /* ✨ 将整个文字相框变淡 */
  opacity: 0.65 !important; /* 0.65比较清淡，如果觉得太淡可以改成 0.8 */
}

/* 彻底隐藏定位、日期和空行 */
.msg-sim-card:not(:has(img)) > div:has(svg),
.msg-sim-card:not(:has(img)) > div:last-child,
.msg-sim-card:not(:has(img)) > div:empty {
  display: none !important;
  opacity: 0 !important;
  visibility: hidden !important;
}

/* 核心正文：绝对宽度强制换行 */
.msg-sim-card:not(:has(img)) > div:not(:has(svg)):not(:last-child):not(:empty) {
  position: absolute !important;
  top: 32px !important;    
  left: 24px !important;   

  right: auto !important; 
  width: 117px !important; 

  font-size: 10px !important; 
  font-family: "PingFang SC", "Microsoft YaHei", sans-serif !important;
  font-style: normal !important; 
  font-weight: 400 !important;
  color: #555 !important;

  line-height: 1.6 !important; 
  letter-spacing: 0.8px !important; 
  text-align: justify !important; 

  height: 80px !important; 

  display: -webkit-box !important;
  -webkit-box-orient: vertical !important;
  -webkit-line-clamp: 5 !important; 
  overflow: hidden !important;

  word-wrap: break-word !important;
  word-break: break-all !important; 

  background: transparent !important;
  box-shadow: none !important;
  border: none !important;
  margin: 0 !important;
  padding: 0 !important;
}

/* 清理正文内的杂质标签 */
.msg-sim-card:not(:has(img)) > div:not(:has(svg)):not(:last-child):not(:empty) * {
  background: transparent !important;
  font-style: normal !important;
  font-family: inherit !important;
  font-size: inherit !important;
}

/* 1.1 带图的表情包独立尺寸 */
.msg-sim-card:has(img) {
  background: none !important;
  border: none !important;
  box-shadow: none !important;
  padding: 0 !important;
  max-width: 120px !important; 
}

/* 2. 所有电话状态缩小 */
.msg-system, .msg-call, .msg-loc-card {
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  transform: scale(0.65) !important;  
  transform-origin: center right;    
}
.msg-them .msg-system, .msg-them .msg-call {
  transform-origin: center left;     
}

/* 3. 图片消息限制尺寸 */
.msg-image-wrapper {
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  padding: 0 !important;
}
.msg-image-wrapper img { border-radius: 8px !important; max-width: 110px !important; }

/* 4. 语音条独立重构 */
.bubble-them-custom:has(.voice-msg),
.bubble-me-custom:has(.voice-msg) {
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  padding: 0 !important;
}
.voice-msg {
  transform: scale(0.85); 
  border-radius: 14px;
  padding: 8px 12px;
}
.msg-me .voice-msg { 
  transform-origin: center right; 
  background: #f2f2f2 !important;
  border: none !important;
}
.msg-them .voice-msg { 
  transform-origin: center left; 
  background: #ffffff !important;
  border: 1px solid #e0e0e0 !important;
}

/* 绝杀防污机制：防止扒皮后的消息带上角落猫咪装饰 */
.msg-bubble-wrapper.is-first .bubble-them-custom:has(svg)::before,
.msg-bubble-wrapper.is-first .bubble-me-custom:has(svg)::after,
.msg-bubble-wrapper.is-first .bubble-them-custom:has(.msg-image-wrapper)::before,
.msg-bubble-wrapper.is-first .bubble-me-custom:has(.msg-image-wrapper)::after,
.msg-bubble-wrapper.is-first .bubble-them-custom:has(.msg-sim-card)::before,
.msg-bubble-wrapper.is-first .bubble-me-custom:has(.msg-sim-card)::after,
.msg-bubble-wrapper.is-first .bubble-them-custom:has(.voice-msg)::before,
.msg-bubble-wrapper.is-first .bubble-me-custom:has(.voice-msg)::after,
.bubble-them-custom:has(img)::before,
.bubble-me-custom:has(img)::after {
  display: none !important;
}

