/* ==========================================
   三、气泡部分 (Bubbles)
   ========================================== */
:root {
  --bubble-me-bg: #f8e8f0;
  --bubble-me-color: #1C1C1E;
  --bubble-me-border: none;
  --bubble-me-shadow: 0 1px 2px rgba(0, 0, 0, 0.03);
  --bubble-me-padding: 8px 12px; 

  --bubble-them-bg: #F4F4F6;
  --bubble-them-color: #1C1C1E;
  --bubble-them-border: none;
  --bubble-them-shadow: 0 1px 2px rgba(0, 0, 0, 0.03);
  --bubble-them-padding: 8px 12px; 
}

.bubble-me-custom,
.bubble-them-custom {
  position: relative !important;
  overflow: visible !important;
}

