  --btn-mic-x:28px;
  --btn-mic-y:0px;
  --btn-sticker-x:26px;
  --btn-sticker-y:0px;
  --btn-ai-send-x:22px;
  --btn-ai-send-y:0px;

  --fake-sticker-x:26px;
  --fake-sticker-y:0px;
  --real-send-x:22px;
  --real-send-y:0px;

  --gen-plus-x:24px;
  --gen-icon-y:49.5%;
  --gen-sticker-x:-16px;
  --gen-sticker-y:50.5%;
  --gen-mic-x:-77px;
  --gen-mic-y:25.8px;
}

