  --videocall-radius: 0 !important;
  --videocall-padding: 0 !important;
  --videocall-shadow: none !important;
  --videocall-shadow-missed: none !important;
  --videocall-border-connected: none !important;
  --videocall-border-interrupted: none !important;
  --videocall-border-missed: none !important;
  --videocall-icon-bg: transparent !important;
  --videocall-icon-bg-missed: transparent !important;

  display: block !important;
  width: auto !important;
  max-width: calc(100vw - 48px) !important;
  min-width: 0 !important;
  min-height: 0 !important;
  margin: 8px auto !important;
  padding: 2px 0 !important;
  background: transparent !important;
  border: 0 !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  color: #8e8e93 !important;
  -webkit-text-fill-color: #8e8e93 !important;
  font-size: 15px !important;
  font-weight: 620 !important;
  line-height: 1.28 !important;
  text-align: center !important;
  white-space: nowrap !important;
  transform: none !important;
  filter: none !important;
}
.chat-messages-area .msg-videocall-card *,
.msg-videocall-card * {
  color: #8e8e93 !important;
  -webkit-text-fill-color: #8e8e93 !important;
  background: transparent !important;
  border: 0 !important;
  box-shadow: none !important;
  text-shadow: none !important;
}
/* 去图标 */
.chat-messages-area .msg-videocall-icon,
.msg-videocall-icon,
.chat-messages-area .msg-videocall-icon::before,
.msg-videocall-icon::before {
  display: none !important;
  content: none !important;
  width: 0 !important;
  height: 0 !important;
  min-width: 0 !important;
  margin: 0 !important;
  padding: 0 !important;
}
.chat-messages-area .msg-videocall-icon svg,
.chat-messages-area .msg-videocall-icon img,
.msg-videocall-icon svg,
.msg-videocall-icon img {
  display: none !important;
}
/* 尽量隐藏附带时间/次信息，只保留主文字。接通时若主文本自带时长则仍可显示 */
.msg-videocall-card time,
.msg-videocall-card .msg-videocall-time,
.msg-videocall-card .msg-videocall-meta,
.msg-videocall-card .msg-videocall-subtitle,
.msg-videocall-card .msg-time,
.msg-videocall-card .timestamp,
.msg-videocall-card [class*="call-time"],
.msg-videocall-card [class*="CallTime"] {
  display: none !important;
}
.msg-videocall-card br {
  display: none !important;
}

/* 深色模式：转账改石墨黑，保持扁平；通话仍仅灰字 */
@media (prefers-color-scheme: dark) {
  .chat-messages-area .msg-transfer-card:not(.msg-redpacket-card),
  .msg-transfer-card:not(.msg-redpacket-card),
  .chat-messages-area .msg-transfer-card:not(.msg-redpacket-card).msg-transfer-success,
  .chat-messages-area .msg-transfer-card:not(.msg-redpacket-card).msg-transfer-rejected,
  .chat-messages-area .msg-transfer-card:not(.msg-redpacket-card).msg-transfer-expired-card {
