*/
.header-btn-video {
  display: block !important;
  position: absolute !important;
  right: 1px !important;
  width: 18px !important;
  height: 36px !important;
  min-width: 18px !important;
  padding: 0 !important;
  margin: 0 !important;
  opacity: 0.001 !important;
  pointer-events: auto !important;
  z-index: 5 !important;
}

/* Header 右侧整体间距收紧，和参考图更接近 */
.header-action-btn {
  margin: 0 !important;
}
.chat-detail-screen {
  --header-btn-gap: 10px;
}

/* ---------- B. 底部导航：五个中心点严格等距 ---------- */

/* 导航栏高度稍微收紧 */
.input-area-custom {
  padding-bottom: calc(54px + env(safe-area-inset-bottom, 0px)) !important;
}
.input-area-custom::after {
  height: calc(50px + env(safe-area-inset-bottom, 0px)) !important;
}

/*
  前三个纯视觉图标：Home / Search / Grok-like
  中间图标换成更接近参考图的“斜线星环”，不再用原来的小火箭。
  三个中心分别是 10% / 30% / 50%
*/
.input-area-custom::before {
  left: 0 !important;
  width: 60% !important;
  height: 50px !important;
