  bottom: calc(7px + env(safe-area-inset-bottom, 0px)) !important;
  transform: translateX(-50%) !important;
  width: 36px !important;
  height: 36px !important;
}
.input-btn-ai::before {
  width: 24px !important;
  height: 24px !important;
}

/* ---------- C. “已发送”：只留最新一条己方消息，且去掉时间 ---------- */

/* 默认所有状态都隐藏 */
.msg-status-custom {
  display: none !important;
}

/* 当前消息列表最后一行如果是我方，才显示 */
.msg-bubble-wrapper.msg-me:last-of-type .msg-status-custom,
.msg-bubble-wrapper.msg-me:last-child .msg-status-custom {
  display: block !important;
  font-size: 0 !important;
  color: var(--x-muted) !important;
  margin: 5px 3px 0 0 !important;
}

/* 无论 read/sent，都按参考图统一写“已发送” */
.msg-bubble-wrapper.msg-me:last-of-type .msg-status-custom::after,
.msg-bubble-wrapper.msg-me:last-child .msg-status-custom::after {
  content: "已发送" !important;
  font-size: 12px !important;
  font-weight: 500 !important;
  color: var(--x-muted) !important;
}

