}

/* ========================================================
   X APP DARK v1.5
   修复：语音转文字后外层气泡被撑变形
   思路：语音外层透明；只有 controls-row 是圆胶囊；
         转写文字作为下方独立小卡片。
   ======================================================== */

/* 语音最外层不要再承担气泡背景 */
.voice-msg,
.voice-msg-me,
.voice-msg-them {
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  border-radius: 0 !important;
  padding: 0 !important;
  overflow: visible !important;
}

/* 真正的“语音气泡”改由控制行承担 */
.voice-msg-me .voice-controls-row,
.voice-msg-them .voice-controls-row {
  box-sizing: border-box !important;
  border-radius: 999px !important;
  padding: 7px 10px !important;
  min-height: 46px !important;
  overflow: hidden !important;
  border: none !important;
  box-shadow: none !important;
}

.voice-msg-me .voice-controls-row {
  background: var(--x-blue, #1d9bf0) !important;
  color: #fff !important;
}

.voice-msg-them .voice-controls-row {
  background: var(--x-surface, #202327) !important;
  color: var(--x-text, #e7e9ea) !important;
}

/* 播放键仍然保留真实点击功能 */
.voice-play-btn {
  z-index: 6 !important;
}

/* 点击波形主体仍走“查看文字” */
.voice-transcription-toggle {
  z-index: 5 !important;
}

/* 转写文字独立成下方卡片，不参与上方圆胶囊尺寸 */
.voice-transcription {
  position: relative !important;
  display: block !important;
  width: 100% !important;
  box-sizing: border-box !important;
  margin: 6px 0 0 !important;
  padding: 8px 10px !important;

  background: var(--x-surface, #202327) !important;
  color: var(--x-text, #e7e9ea) !important;

  border: 1px solid var(--x-border, #2f3336) !important;
  border-radius: 14px !important;
  box-shadow: none !important;

  font-size: 14px !important;
  line-height: 1.4 !important;

  /* 防止文字把整条语音拉成巨型椭圆 */
  max-width: 100% !important;
  white-space: normal !important;
  overflow-wrap: anywhere !important;
}

/* 转写展开后，外层仍保持普通纵向布局 */
.voice-msg:has(.voice-transcription) {
  display: flex !important;
  flex-direction: column !important;
  align-items: stretch !important;
  border-radius: 0 !important;
}

/* 如果普通消息气泡外层包住 voice，继续保持透明 */
.msg-plain:has(.voice-msg),
.msg-plain-me:has(.voice-msg),
.msg-plain-them:has(.voice-msg),
.bubble-me-custom:has(.voice-msg),
.bubble-them-custom:has(.voice-msg) {
  background: transparent !important;
  padding: 0 !important;
  border: none !important;
  box-shadow: none !important;
  border-radius: 0 !important;
  overflow: visible !important;
}

/* ========================================================
   X APP DARK v1.6
   对方头像稍微放大
   ======================================================== */

.msg-avatar-custom,
.msg-avatar-them-inner,
.msg-avatar-them-inner img,
.msg-avatar-them-container .msg-avatar-custom {
  width: 36px !important;
  height: 36px !important;
  min-width: 36px !important;
  min-height: 36px !important;
}

/* 头像容器同步放大，避免图片被裁掉 */
.msg-avatar-them-container,
.msg-avatar-them-inner {
  width: 36px !important;
  height: 36px !important;
  flex: 0 0 36px !important;
}

/* 保持圆形 */
.msg-avatar-custom,
.msg-avatar-them-inner,
.msg-avatar-them-inner img {
  border-radius: 50% !important;
  object-fit: cover !important;
}

/* 放大后和气泡之间仍保持紧凑 */
.msg-avatar-them-container {
  margin-right: 7px !important;
}

/* ========================================================
   X APP DARK v1.7
   角色外文消息：翻译显示在原气泡正下方
   ======================================================== */

/* 强制自动展开翻译；不再显示“查看翻译”按钮 */
.chat-detail-screen {
  --translation-btn-display: none;
}

/* 隐藏气泡内部旧版翻译区域，避免原文气泡被撑高 */
.msg-translation-wrapper {
  display: none !important;
}

/* 开启气泡外 detached 翻译 */
.msg-translation-detached {
  display: block !important;
  width: fit-content !important;
  min-width: 0 !important;
  max-width: 100% !important;
  box-sizing: border-box !important;

  /* 紧贴原气泡底部 */
  margin-top: 2px !important;
  margin-bottom: 0 !important;
  padding: 0 !important;

  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
}

/* 角色消息：翻译和角色气泡左边缘对齐 */
.msg-translation-detached-them {
  align-self: flex-start !important;
  text-align: left !important;
}

/* 自己若触发翻译，则靠右；平时不会影响 */
.msg-translation-detached-me {
  align-self: flex-end !important;
  text-align: right !important;
}

/* 翻译本体：没有第二层气泡，只留一行/多行文字 */
.msg-translation-detached-content {
  display: block !important;
  width: fit-content !important;
  min-width: 0 !important;
  max-width: min(72vw, 420px) !important;

  padding: 0 !important;
  margin: 0 !important;

  background: transparent !important;
  border: none !important;
  border-radius: 0 !important;
  box-shadow: none !important;

  color: #f2f2f2 !important;
  font-size: 14px !important;
  font-weight: 500 !important;
  line-height: 1.35 !important;
  letter-spacing: -0.05px !important;

  white-space: normal !important;
  word-break: break-word !important;
}

/* 去掉文档默认配方可能加上的“对勾/由微信提供翻译支持” */
.msg-translation-detached-content::before,
.msg-translation-detached-content::after {
  content: none !important;
  display: none !important;
}

/* 如果翻译块和消息状态同处 content-stack，确保顺序：
   回复引用 -> 原气泡 -> 翻译 -> 已发送/已读 */
.msg-reply-block-detached {
  order: -10 !important;
}
.msg-plain,
.bubble-me-custom,
.bubble-them-custom,
.msg-bubble-container {
  order: 0;
}
.msg-translation-detached {
  order: 2 !important;
}
.msg-status-custom {
  order: 3 !important;
}

/* 对方连续消息有翻译时，下一条仍保持紧凑 */
.msg-them:has(.msg-translation-detached) {
  margin-bottom: 8px !important;
}

/* ========================================================
   X APP DARK v1.8
   修正：
   1) Header 点击区域重新排布，避免设置被隐藏电话热区盖住
   2) 翻译逻辑按指南要求：CSS 只负责展开/美化，真正产生译文需开启自动翻译
   ======================================================== */

/* ---------- Header 正确点击区 ---------- */
.chat-header-custom,
.glass-header {
  position: relative !important;
}

/* 视频按钮 = 可见“电话” */
.header-btn-video {
  position: relative !important;
  right: auto !important;
  z-index: 6 !important;
