.chat-messages-area .voice-msg:not(:has(.voice-transcription)),
.chat-messages-area .voice-msg-me:not(:has(.voice-transcription)),
.chat-messages-area .voice-msg-them:not(:has(.voice-transcription)),
.voice-msg:not(:has(.voice-transcription)),
.voice-msg-me:not(:has(.voice-transcription)),
.voice-msg-them:not(:has(.voice-transcription)) {
  border-radius: 999px !important;
  overflow: hidden !important;
}

.chat-messages-area .voice-msg > .voice-controls-row,
.chat-messages-area .voice-msg-me > .voice-controls-row,
.chat-messages-area .voice-msg-them > .voice-controls-row,
.voice-msg > .voice-controls-row,
.voice-msg-me > .voice-controls-row,
.voice-msg-them > .voice-controls-row {
  border-radius: 999px !important;
  overflow: hidden !important;
  clip-path: inset(0 round 999px) !important;
}

.voice-msg-me:not(:has(.voice-transcription)) {
  background: #1d9bf0 !important;
}

.voice-msg-them:not(:has(.voice-transcription)) {
  background: #eff3f4 !important;
}

/* 日间展开转文字：照夜间版拆成上下两个独立圆角块 */
.chat-messages-area .voice-msg:has(.voice-transcription),
.chat-messages-area .voice-msg-me:has(.voice-transcription),
.chat-messages-area .voice-msg-them:has(.voice-transcription),
.voice-msg:has(.voice-transcription),
.voice-msg-me:has(.voice-transcription),
.voice-msg-them:has(.voice-transcription) {
  display: flex !important;
  flex-direction: column !important;
  align-items: stretch !important;
  gap: 7px !important;
  background: transparent !important;
  border: none !important;
  border-radius: 0 !important;
  padding: 0 !important;
  box-shadow: none !important;
  overflow: visible !important;
}

.voice-msg-them:has(.voice-transcription) > .voice-controls-row {
  background: #eff3f4 !important;
}

.voice-msg-me:has(.voice-transcription) > .voice-controls-row {
  background: #1d9bf0 !important;
}

.voice-msg:has(.voice-transcription) > .voice-transcription,
.voice-msg-me:has(.voice-transcription) > .voice-transcription,
.voice-msg-them:has(.voice-transcription) > .voice-transcription {
  display: block !important;
  position: relative !important;
  width: 100% !important;
  max-width: 100% !important;
  margin: 0 !important;
  box-sizing: border-box !important;
  background: #eff3f4 !important;
  color: #0f1419 !important;
  border: 1px solid #dfe3e6 !important;
  border-radius: 14px !important;
  padding: 9px 12px !important;
  box-shadow: none !important;
  overflow: visible !important;
}

