  --plain-padding-left-me: 50px;
  --plain-padding-right-me: 0px;
  --plain-padding-left-them: 0px;
  --plain-padding-right-them: 42px;
  --plain-avatar-size: 32px;
  --plain-avatar-radius: 50%;
  --plain-avatar-gap: 8px;

  /* ---------- Header ---------- */
  --chat-header-bg: #000000;
  --chat-header-blur: 0px;
  --chat-header-border: #2f3336;
