  --bubble-them-color: var(--x-text);
  --bubble-them-font-size: 16px;
  --bubble-them-line-height: 1.34;
  --bubble-them-padding: 9px 13px;
  --bubble-them-radius: 20px;
  --bubble-them-radius-first: 20px 20px 20px 6px;
