  --date-divider-color: var(--x-muted);
  --date-divider-size: 13px;
  --date-divider-weight: 600;
  --date-divider-padding: 12px 0;

  --status-color: var(--x-muted);
  --status-size: 12px;
  --status-weight: 500;
  --status-margin: 3px 2px 0 0;
  --status-read-color: var(--x-muted);
