  --input-box-bg: var(--x-surface);
  --input-box-color: var(--x-text);
  --input-box-placeholder: var(--x-muted);
  --input-box-radius: 999px;
  --input-box-padding: 9px 46px 9px 15px;
  --input-box-font-size: 16px;
  --input-box-border: 1px solid transparent;
  --input-box-shadow: none;
  --input-caret-color: var(--x-blue);

  --plus-btn-bg: var(--x-surface);
