  /* ---------- 回复预览 ---------- */
  --reply-bar-accent: var(--x-blue);
  --reply-bar-text-color: var(--x-muted);

  /* ---------- 独立引用 ---------- */
  --reply-detached-bg: transparent;
  --reply-detached-radius: 0;
  --reply-detached-padding: 0 2px 4px 2px;
  --reply-detached-border: none;
  --reply-detached-border-left: none;
  --reply-detached-shadow: none;
  --reply-detached-max-width: 100%;
  --reply-detached-flex-direction: column;
  --reply-detached-gap: 1px;
  --reply-detached-align-items: flex-start;
  --reply-detached-name-color: var(--x-muted);
  --reply-detached-name-suffix: "";
  --reply-detached-text-color: var(--x-muted);
  --reply-detached-text-whitespace: nowrap;

  /* ---------- 更多菜单 ---------- */
  --more-options-bg: rgba(32, 35, 39, .98);
  --more-options-blur: blur(18px) saturate(120%);
  --more-options-shadow: 0 8px 28px rgba(0,0,0,.48);
  --more-options-border: 1px solid var(--x-border);
  --more-options-color: var(--x-text);
