  /* ---------- Emoji ---------- */
  --emoji-panel-bg: #000000;
  --emoji-panel-blur: 0px;
  --emoji-panel-shadow: 0 -1px 0 var(--x-border);
  --emoji-panel-radius: 0;

  /* ---------- 打字指示 ---------- */
  --typing-dot-color: var(--x-muted);
  --typing-dot-size: 7px;
  --typing-bg: var(--x-surface);
  --typing-radius: 18px;
}

/* ========================================================
   1. 页面与消息区
   ======================================================== */
.chat-detail-screen,
.chat-messages-area {
  background: #000 !important;
  color: var(--x-text) !important;
}

.chat-messages-area[data-theme-style="plain"] {
