  --chat-header-deco-1-height: 1px;
  --chat-header-deco-1-bottom: 13px; 
  --chat-header-deco-1-left: 20px;
  --chat-header-deco-1-top: auto;

  --chat-header-deco-2-image: radial-gradient(circle, #BEBFBE 100%, transparent 100%);
  --chat-header-deco-2-width: 5px;
  --chat-header-deco-2-height: 5px;
  --chat-header-deco-2-bottom: 11px; 
  --chat-header-deco-2-left: calc(20px + 35% - 2.5px);
  --chat-header-deco-2-top: auto;

  --chat-header-deco-3-image: none;
  --chat-header-deco-4-image: none;
  --chat-header-deco-6-image: none;

  --chat-header-deco-5-image: radial-gradient(circle, transparent 68%, rgba(190,191,190,0.15) 69%, rgba(190,191,190,0.15) 70%, transparent 71%);
  --chat-header-deco-5-width: 140px;
  --chat-header-deco-5-height: 140px;
  --chat-header-deco-5-top: -30px;
  --chat-header-deco-5-right: -20px;
  --chat-header-deco-5-left: auto;
  --chat-header-deco-5-bottom: auto;

  /* === 气泡 === */
  --bubble-me-bg: #F2F2F2; 
  --bubble-me-color: #8A8B8A; 
  --bubble-me-padding: 4px 14px; 
  --bubble-me-radius: 2px; 

  --bubble-them-bg: #ffffff;
  --bubble-them-color: #8a8b8a; 
  --bubble-them-padding: 4px 14px; 
  /* 🌟 在这里将边框变得更细(0.5px)且颜色变浅(透明度0.5) 🌟 */
  --bubble-them-border: 0.5px solid rgba(190, 191, 190, 0.5);
  --bubble-them-radius: 2px;

  /* 自适应边距 */
  --plain-gap-within-group: 4px;   
  --plain-gap-between-groups: 18px; 
  --plain-padding-left-them: 12px; 
  --plain-padding-right-me: 12px;  
  --plain-padding-left-me: 45px;   
  --plain-padding-right-them: 45px; 
  --plain-avatar-size: 30px; 
  --plain-avatar-radius: 2px;
  --plain-avatar-gap: 4px;

  /* === 底栏 === */
  --input-area-bg: #ffffff; 
  --input-area-border-top: none;
  --input-box-bg: transparent;
  --input-box-color: #555555;
  --input-box-border: none;
  --input-box-radius: 0px;
  --send-btn-bg: transparent;
  --stop-btn-bg: transparent;

  /* === 语音 === */
  --voice-me-color: #8A8B8A; 
  --voice-them-color: #8A8B8A; 
  --voice-me-bar-active: #8A8B8A; 
  --voice-me-bar-inactive: rgba(138, 139, 138, 0.3); 
  --voice-them-bar-active: #8A8B8A; 
  --voice-them-bar-inactive: rgba(138, 139, 138, 0.3); 
  --voice-download-display: none;       
  --voice-toggle-display: none;         
  --voice-waveform-height: 12px;        
  --voice-container-gap: 2px;
  --voice-controls-gap: 4px;

  /* === 特殊卡片强制色 === */
  --transfer-them-amount-color: #8A8B8A;
  --transfer-me-amount-color: #8A8B8A;
}

