/* =========================================
   4. 🌟 头像智能对齐 & 听歌小挂件 🌟
   ========================================= */
.msg-bubble-wrapper { align-items: flex-end !important; }

/* 必须允许内容溢出，否则挂件被切掉 */
.msg-avatar-them-container, .msg-avatar-me-container { 
   display: none !important; 
   overflow: visible !important;
}

/* --- 基础状态：关闭已读时，缩小间距使头像贴近气泡 --- */
.msg-avatar-them-container.is-last,
.msg-avatar-them-container.is-single {
  display: block !important; 
  align-self: flex-end !important; 
  margin-bottom: 0 !important; 
  transform: translateX(-2px) !important; /* 使对方头像更靠近气泡 */
  position: relative; 
  z-index: 10;
}

.msg-avatar-me-container.is-last,
.msg-avatar-me-container.is-single {
  display: block !important; 
  align-self: flex-end !important; 
  margin-bottom: 0 !important; 
  transform: translateX(2px) !important; /* 使我方头像更靠近气泡 */
  position: relative; 
  z-index: 10;
}

/* --- 智能判断：开启已读状态时（存在状态文字），Y 轴再往上提 -14px --- */
.msg-bubble-wrapper:has(.msg-status-custom) .msg-avatar-me-container.is-last,
.msg-bubble-wrapper:has(.msg-status-custom) .msg-avatar-me-container.is-single {
  transform: translate(2px, -14px) !important;
}

.msg-bubble-wrapper:has(.msg-status-custom) .msg-avatar-them-container.is-last,
.msg-bubble-wrapper:has(.msg-status-custom) .msg-avatar-them-container.is-single {
  transform: translate(-2px, -14px) !important;
}

/* --- 独立翻译底距兼容 --- */
.msg-bubble-wrapper:has(.msg-translation-detached) .msg-avatar-them-container.is-last,
.msg-bubble-wrapper:has(.msg-translation-detached) .msg-avatar-them-container.is-single,
.msg-bubble-wrapper:has(.msg-translation-detached) .msg-avatar-me-container.is-last,
.msg-bubble-wrapper:has(.msg-translation-detached) .msg-avatar-me-container.is-single { margin-bottom: 22px !important; }

