  --chat-header-height: 50px;
}
/* ── 顶栏底色 ── */
:root {
  --chat-header-bg: 0 !important;
}

/* ── 顶栏头像进一步下移 ── */
.chat-header-avatar,
.user-head-avatar,
.header-avatar-container {
  position: absolute !important;
  left: 5px !important;

  /* 👈 控制头像上下位置：
     数值越小（甚至改用负数如 -5px、-10px），头像位置越靠下；
     原本是 bottom: 8px，这里调成了 -4px 深入顶栏底部边缘 */
  bottom: -5px !important; 

  width: 35px !important;
  height: 35px !important;
  border-radius: 50% !important;
  z-index: 10 !important;
}

/* ── 备注名字往下偏移 ── */
.chat-header-title {
  color: #000000 !important;
  font-size: 16px !important;
  margin-top: 30px !important;
  margin-left: 49px !important;
}

/* ── 顶栏高度，别设太大 ── */
:root {
  --chat-header-height: 56px;
}

/* ── profile 区域定位微调 ── */
.header-profile-section {
  position: absolute !important;
  left: 52px !important;
  top: 60% !important;
  transform: translateY(-50%) !important;
  display: flex !important;
  flex-direction: column !important;
  align-items: flex-start !important;
}

/* ── 顶栏最左侧返回按钮（替换图片 + 保留点击返回功能） ── */
.header-btn-back,
.chat-header-back-btn,
.chat-header-left {
  position: absolute !important;
  left: -23px !important;
  top: 38px !important;
  transform: translateY(-50%) !important;
  width: 70px !important;                   /* 👈 可调图片显示宽度 */
  height: 70px !important;                  /* 👈 可调图片显示高度 */

  /* 替换为你指定的新图片 */
  background-image: url('https://s3.bmp.ovh/2026/08/15/Ph9WSaR5.png') !important;
  background-size: contain !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
  background-color: transparent !important;
  border: none !important;
  box-shadow: none !important;

  /* 确保按钮可见并可以正常点击 */
  opacity: 1 !important;
  visibility: visible !important;
  pointer-events: auto !important;
  z-index: 20 !important;
}

/* 彻底清空原生自带的返回箭头 SVG 图标及文本 */
.header-btn-back svg,
.chat-header-back-btn svg,
.header-btn-back::before,
.header-btn-back::after,
.chat-header-back-btn::before,
.chat-header-back-btn::after {
  display: none !important;
  opacity: 0 !important;
  content: "" !important;
}

/* ── 通话按钮隐形但可点击 ── */
.header-btn-phone svg,
.header-btn-video svg {
  opacity: 0 !important;
  visibility: visible !important;
}
/* ── 顶栏最右侧功能按钮（更换图片 + 保留点击功能） ── */
.header-btn-info {
  position: absolute !important;
  right: -10px !important;
  top: 65% !important;
  transform: translateY(-50%) !important;
  width: 107px !important;                   /* 👈 可调图片显示宽度 */
  height: 107px !important;                  /* 👈 可调图片显示高度 */

  /* 替换为你指定的新图片 */
  background-image: url('https://s3.bmp.ovh/2026/08/15/0k9iLESQ.png') !important;
  background-size: contain !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
  background-color: transparent !important;
  border: none !important;
  box-shadow: none !important;

  /* 确保按钮可见并可以正常点击 */
  opacity: 1 !important;
  visibility: visible !important;
  pointer-events: auto !important;
  z-index: 20 !important;
}

/* 彻底清空原生自带的 SVG 图标及文本伪元素 */
.header-btn-info svg,
.header-btn-info::before,
.header-btn-info::after {
  display: none !important;
  opacity: 0 !important;
  content: "" !important;
}

/* ── 对方第一条头像旁文字 ── */
.msg-avatar-them-container:not(.is-mid):not(.is-last){
    position: relative !important;
}

.msg-avatar-them-container:not(.is-mid):not(.is-last)::after{
    content: "Puppy";
    position: absolute;
    left: 42px;      /* 左右位置 */
    top: 50%;        /* 上下位置 */
    transform: translateY(-50%);

    color: #2E3033;
    font-size: 12px;
    font-weight: 600;
    line-height: 1;
    white-space: nowrap;

    pointer-events: none;
}
/* ── 对方半胶囊气泡 ── */
:root {
  --bubble-them-bg: #FFFFFF !important;
  --bubble-them-color: #000000 !important;
  --bubble-them-font-size: 12.5px !important;
  --bubble-them-padding: 6px 14px !important;
}

.bubble-them-custom {
  position: relative !important;
  overflow: visible !important;

  /* 半胶囊形态：左上角较尖(3px)，其余三角为大圆角(16px) */
  border-radius: 3px 16px 16px 16px !important;

  padding: var(--bubble-them-padding) !important;
  font-size: var(--bubble-them-font-size) !important;
  color: var(--bubble-them-color) !important;
  line-height: 1.4 !important;
  font-weight: 500 !important;

  /* 中粗黑描边 */
  border: 1.5px solid #000000 !important;

/* ── #878787 向上渐变顶白（底中深灰，顶纯白） ── */
background: linear-gradient(0deg, #878787 0%, #C3C3C3 50%, #FFFFFF 100%) !important;

  transform: scale(0.97) !important;
  transform-origin: left center !important;
}

/* ── 我方半胶囊气泡（纯白底色 + 中粗黑描边） ── */
:root {
  --bubble-me-bg: #FFFFFF !important;
  --bubble-me-color: #000000 !important;
  --bubble-me-font-size: 12.5px !important;
  --bubble-me-padding: 6px 14px !important;
}

.bubble-me-custom {
  position: relative !important;
  overflow: visible !important;

  /* 半胶囊形态：右上角较尖(3px)，其余三角为大圆角(16px) */
  border-radius: 16px 3px 16px 16px !important;

  padding: var(--bubble-me-padding) !important;
  font-size: var(--bubble-me-font-size) !important;
  color: var(--bubble-me-color) !important;
  line-height: 1.4 !important;
  font-weight: 500 !important;

  /* 中粗黑描边 */
  border: 1.5px solid #000000 !important;

  /* 我方纯白底色 */
  background: #FFFFFF !important;

  transform: scale(0.97) !important;
  transform-origin: right center !important;
}

/* ---- 1. 切换引用显示 ---- */
.msg-reply-block {
  display: none !important;
}

.msg-reply-block-detached {
  display: flex !important;
}

/* ---- 2. 父容器允许换行，但只让引用条换行 ---- */
.msg-bubble-wrapper {
  display: flex !important;
  flex-wrap: wrap !important;
  align-items: flex-start !important;
}

/* ---- 3. 引用条独占第一行，宽度由内容决定 ---- */
.msg-reply-block-detached {
  order: -1 !important;
  width: auto !important;
  max-width: 85% !important;
  flex-shrink: 0 !important;
  margin-bottom: 6px !important;
  position: relative !important;
  justify-content: flex-start !important;
  align-items: center !important;
  gap: 6px;
  background:rgba(245, 245, 245, 0.55) !important;
  color: #000!important;
  border-radius: 8px !important;
  border: none !important;
  padding: 5px 7px 5px 7px;
  box-sizing: border-box;
}

/* ---- ★ 新增：我方引用气泡移到气泡下方 ---- */
.msg-me .msg-reply-block-detached {
  order: 3 !important;                    /* 移到气泡下方 */
  margin-top: 6px !important;             /* 与气泡保持间距 */
  margin-bottom: 0 !important;            /* 取消底部间距 */
  align-self: flex-end !important;        /* 右对齐，与消息一致 */
}

/* ---- 4. 隐藏引用人名 + 去掉冒号 ---- */
.msg-reply-detached-name {
  display: none !important;
}
.chat-detail-screen {
  --reply-detached-name-suffix: "";   /* 去掉冒号 */
}

/* ---- 5. 对方：内容靠左，图标在左侧外部 ---- */
.msg-them .msg-reply-block-detached {
  justify-content: flex-start !important;
  background: rgba(245, 245, 245, 0.55)!important;
  color: #000!important;
  border: none !important;
}
.msg-them .msg-reply-block-detached::before {
  content: '';
  display: block;
  width: 35px;
  height: 35px;
  background-image: url('https://s3.bmp.ovh/2026/08/16/p4qCMdiL.png') !important;
  background-size: contain;
  background-repeat: no-repeat;
  position: absolute;
  top: 50%;
  transform: translateY(-55%);
  left: -30px;
  pointer-events: none;
}

/* ---- 6. 我方：内容靠右，图标在右侧外部 ---- */
.msg-me .msg-reply-block-detached {
  justify-content: flex-end !important;
  background: rgba(245, 245, 245, 0.55) !important;
  color: #000!important;
  border: none !important;
}
.msg-me .msg-reply-block-detached::before {
  content: '';
  display: block;
  width: 35px;
  height: 35px;
  background-image: url('https://s3.bmp.ovh/2026/08/16/njh5Pk7x.png') !important;
  background-size: contain;
  background-repeat: no-repeat;
  position: absolute;
  top: 50%;
  transform: translateY(-55%);
  left: auto;
  right: -25px;
  pointer-events: none;
}

/* ---- 7. 引用文字样式（单行省略，黑色） ---- */
.msg-reply-detached-text {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  min-width: 0;
  flex: 1;
  color: #000!important;
}

/* ---- 8. 头像和内容栈保持原样（不干涉） ---- */
.msg-avatar-container,
.msg-content-stack {
  order: 0 !important;
  flex: 0 1 auto !important;
}

/* ====== 引用气泡贴纸（对方右侧，我方左侧） ====== */

/* 对方引用气泡：贴纸在右侧 */
.msg-them .msg-reply-block-detached::after {
  content: '';
  display: block;
  width: 62px;
  height:62px;
  background-image: url('https://s3.bmp.ovh/2026/08/16/shNDDa07.png') !important;
  background-size: contain;
  background-repeat: no-repeat;
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  right: -39px;
  pointer-events: none;
}

/* 我方引用气泡：贴纸在左侧（跟随引用条移到下方） */
.msg-me .msg-reply-block-detached::after {
  content: '';
  display: block;
  width: 62px;
  height: 62px;
  background-image: url('https://s3.bmp.ovh/2026/08/16/shNDDa07.png') !important;
  background-size: contain;
  background-repeat: no-repeat;
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  left: -39px;           /* 在气泡左侧外部（因为引用条右对齐，左侧是外侧） */
  pointer-events: none;
}
/* 感谢咪咪🍚么么✅ 只改聊天表情包 · 绝对不碰头像 ✅ */
/* 核心：只选中【不包含头像】的气泡，彻底排除头像区域 */

/* 只清除表情包的气泡边框、背景、内边距、阴影 */
div[class*="message"] div[class*="bubble"]:has(img):not(:has([class*="avatar"])) {
 background: transparent !important; /* 清除气泡背景色 */
 border: none !important; /* 彻底去掉边框线 */
 box-shadow: none !important; /* 清除气泡的立体阴影 */
 padding: 0 !important; /* 消除图片和气泡之间的空隙 */
 border-radius: 0 !important; /* 去掉气泡圆角，如需保留可删除此行 */
 outline: none !important; /* 清除可能的外轮廓线 */
}

/* 只控制表情包的尺寸，完全不影响头像 */
div[class*="message"] div[class*="bubble"]:not(:has([class*="avatar"])) img {
 width: 100px !important;
 height: 100px !important;
 max-width: 100px !important;
 max-height: 100px !important;
 transform: scale(1.0) !important;
 /* 可选补充：去掉图片自带的圆角/边框，不需要可删除 */
 border-radius: 0 !important;
 border: none !important;
}

