/* =======================================
   1. 全局颜色与变量配置
   ======================================= */
:root {
  /* 顶栏底栏颜色：第一阶 (最浅，极浅灰) */
  --chat-header-bg: #f8f8f8;
  --chat-header-blur: 0px;
  --input-area-bg: #f8f8f8;
  --input-area-blur: 0px;

  /* 胶囊颜色 */
  --capsule-bg: #eeeeee;
  --capsule-border: 1px solid #e4e4e4;

  /* 输入框颜色 */
  --input-box-bg: #e0e0e0; 
  --input-box-border: 1px solid #d5d5d5;
  --input-box-radius: 6px; 

  /* 顶栏图标替换 */
  --back-btn-icon: url('https://i.postimg.cc/J0YfsVcD/x-64px.png');
  --info-btn-icon: url('https://i.postimg.cc/FzCMY5gR/three-dots-64px.png');

  /* 发送/AI图标统一替换为纸飞机 */
  --send-btn-icon: url('https://i.postimg.cc/h4CWyTF0/send-fill-64px.png');
  --ai-btn-icon: url('https://i.postimg.cc/h4CWyTF0/send-fill-64px.png');

  /* 引用消息变量 (Detached Reply Block) */
  --reply-detached-bg: #f2f2f2;         
  --reply-detached-border-left: none;   
  --reply-detached-radius: 12px;        
  --reply-detached-padding: 6px 12px;   
  --reply-detached-text-whitespace: pre-wrap; 
}

/* 修复作用域：底栏展开(加号)图标替换为当前角色头像 */
.chat-detail-screen {
  --plus-btn-icon: var(--char-avatar);
}

