/* ========================================= */
/* 1. 气泡基础设置 (颜色与圆角、文字颜色) */
/* ========================================= */

/* 我方气泡 (推特蓝) */
.msg-me .msg-bubble-container,
.bubble-me-custom {
  background-color: #1D9BF0 !important;
  border-radius: 20px !important; 

  /* 🌟 强制剥离我方气泡可能自带的边框 */
  border: none !important;
  box-shadow: none !important;
}

/* 对方气泡 (深色黑，文字纯白) */
.msg-them .msg-bubble-container,
.bubble-them-custom {
  background-color: #141618 !important;
  border-radius: 20px !important; 
  color: #FFFFFF !important; /* 🌟 强制文字颜色为纯白色 */

  /* 🌟 强制剥离对方气泡自带的亮色边框 */
  border: none !important;
  box-shadow: none !important;
}

/* 🌟 双重保险：防止对方气泡内部的子标签导致文字颜色失效 */
.msg-them .msg-bubble-container *,
.bubble-them-custom * {
  color: #FFFFFF !important;
}

/* ========================================= */
/* 2. 气泡扩宽：保证文字完全居中，仅扩展右侧 */
/* ========================================= */
.bubble-me-custom.last,
.msg-me.is-last .msg-bubble-container,
.msg-me.is-single .msg-bubble-container {
  position: relative !important;

  /* 保证文字完美居中，精准设定右侧安全宽度为 26.5px */
  padding-right: 26.5px !important; 
}

/* ========================================= */
/* 3. 仿推特已读符号 (缩进摆放、远离边框) */
/* ========================================= */
.bubble-me-custom.last::after,
.msg-me.is-last .msg-bubble-container::after,
.msg-me.is-single .msg-bubble-container::after {
  content: "" !important;
  position: absolute !important;

  /* 远离边框：向内缩进，不紧贴右侧和底部 */
  bottom: 8px !important;   /* 离底部 8px 的安全距离 */
  right: 10px !important;   /* 离右边框 10px 的安全距离 */

  /* 保持精致的 11px 小尺寸 */
  width: 11px !important;
  height: 11px !important;

  /* 清晰版空心对号 SVG 蒙版 */
  background-color: #FFFFFF !important;
  -webkit-mask-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 24 24' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath fill-rule='evenodd' clip-rule='evenodd' d='M12 0c6.627 0 12 5.373 12 12s-5.373 12-12 12S0 18.627 0 12 5.373 0 12 0zm-1 17l-5-5 1.5-1.5 3.5 3.5 8-8 1.5 1.5-9.5 9.5z' fill='black'/%3E%3C/svg%3E") !important;
  mask-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 24 24' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath fill-rule='evenodd' clip-rule='evenodd' d='M12 0c6.627 0 12 5.373 12 12s-5.373 12-12 12S0 18.627 0 12 5.373 0 12 0zm-1 17l-5-5 1.5-1.5 3.5 3.5 8-8 1.5 1.5-9.5 9.5z' fill='black'/%3E%3C/svg%3E") !important;
  -webkit-mask-size: contain !important;
  mask-size: contain !important;
  -webkit-mask-repeat: no-repeat !important;
  mask-repeat: no-repeat !important;
  -webkit-mask-position: center !important;
  mask-position: center !important;

  z-index: 2 !important;
  pointer-events: none !important;
}

