:root {
  /* 间距 */
  --plain-gap-between-groups: 22px; /* 不同发送者之间的间距 */
  --plain-gap-within-group: 2px; /* 同一发送者连续气泡间距 */
  --plain-reaction-extra-gap: 16px; /* 有 reaction 时额外间距 */

  /* 宽度 & 留白 */
  --plain-content-max-width: 85%; /* 气泡内容最大宽度 */
  --plain-padding-left-me: 48px; /* 我方消息行左留白 */
  --plain-padding-right-me: 0px; /* 我方消息行右留白 */
  --plain-padding-left-them: 0px; /* 对方消息行左留白 */
  --plain-padding-right-them: 48px; /* 对方消息行右留白 */

/* ==================================================
   气泡样式
   ================================================== */

/* ==================================================
   ⭐ 我方气泡 · 白色 + 细黑边
   ================================================== */

.msg-plain-me {
  background: #ffffff !important;
  color: #262626 !important;

  /* ⭐ 气泡厚度 */
  padding: 7px 14px !important;

  /* ⭐⭐⭐ 气泡圆角 ⭐⭐⭐ */
  border-radius: 14px !important;

  /* ⭐⭐⭐ 细黑色外框 ⭐⭐⭐ */
  border: 1.2px solid #ebebeb !important;

  /* 不要阴影 */
  box-shadow: none !important;
}

/* ==================================================
   @天使が送信中
   永远只显示在「我方最新的一条消息」
   前面的全部隐藏
   ================================================== */

/* 我方所有消息先隐藏文字 */
.msg-plain-me::after {
  content: none !important;
}

/* 只让整个我方消息列表中的最后一条显示 */
.msg-plain-me:last-of-type::after {
  content: "@天使が送信中" !important;

  color: #686a67 !important;
  font-size: 9px !important;
  font-weight: 400 !important;

  position: absolute !important;
  right: 8px !important;
  bottom: -15px !important;

  white-space: nowrap !important;
}

/* ==================================================
   ⭐ 对方气泡 —— a3a2a2
   ================================================== */

.msg-plain-them {
  background: #ebebeb !important;
  color: #686a67 !important;

  /* ⭐ 气泡上下厚度 */
  padding: 7px 14px !important;

  /* ⭐⭐⭐ 对方气泡圆角：自己调这里 ⭐⭐⭐ */
  border-radius: 14px !important;
}

/* ==================================================
   ⭐ 对方合并气泡
   ================================================== */

/* 单条消息 */
.msg-plain-them.plain-single {
  border-radius: 14px !important;
}

/* 第一条 */
.msg-plain-them.plain-first {
  border-radius: 14px 14px 14px 4px !important;
}

/* 中间 */
.msg-plain-them.plain-mid {
  border-radius: 4px 14px 14px 4px !important;
}

/* 最后一条 */
.msg-plain-them.plain-last {
  border-radius: 4px 14px 14px 14px !important;
}

/* ==================================================
   ⭐ 对方头像 —— a3a2a2 + 无阴影
   ================================================== */

.msg-avatar-them {
  background: #a3a2a2 !important;

  /* ⭐⭐⭐ 对方头像圆角：这里自己调 ⭐⭐⭐ */
  border-radius: 8px !important;

  /* ⭐ 不要阴影 */
  box-shadow: none !important;

  overflow: hidden !important;
}

/* ==================================================
   ⭐ 我方头像隐藏
   ================================================== */

.msg-avatar-me-container {
  display: none !important;
}

/* ==================================================
   ⭐ 对方头像合并
   后续头像全部隐藏，只显示第一条 / 单条
   ================================================== */

/* 默认全部隐藏 */
.msg-avatar-them-container {
  visibility: hidden !important;
}

/* 只有第一条 / 单条显示 */
.msg-avatar-them-container.is-first,
.msg-avatar-them-container.is-single {
  visibility: visible !important;
}

/* 防止头像容器被压缩 */
.msg-avatar-them-container {
  flex-shrink: 0 !important;
}

  /* ---- 紧凑语音条 ---- */
  --voice-toggle-display: flex;
  --voice-transcription-margin-top: 6px;
  --voice-container-gap: 0px;
  --voice-controls-gap: 6px;
  --voice-play-btn-size: 22px;
  --voice-waveform-height: 20px;
  --voice-len-base: 80px;
  --voice-len-range: 100px;
}

/* ---- 气泡下方单行引用：灰字、细竖线、超长省略 ---- */
.chat-detail-screen .msg-reply-block {
  display: none !important;
}
.chat-detail-screen .msg-reply-block-detached {
  display: flex !important;
  flex-direction: row !important;
  flex-wrap: nowrap !important;
  align-items: center !important;
  gap: 2px !important;
  box-sizing: border-box !important;
