  min-width: 0 !important;
  max-width: min(100%, 210px) !important;
  margin: 6px 0 0 !important;
  padding: 0 0 0 6px !important;
  background: transparent !important;
  border: none !important;
  border-left: 2px solid #c5c5c8 !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  color: #8e8e93 !important;
  font-size: 12px !important;
  line-height: 16px !important;
  white-space: nowrap !important;
  overflow: hidden !important;
  --reply-detached-name-suffix: "：";
}
.chat-detail-screen .msg-reply-detached-them {
  align-self: flex-start !important;
}
.chat-detail-screen .msg-reply-detached-me {
  align-self: flex-end !important;
  border-left: none !important;
  border-right: 2px solid #c5c5c8 !important;
  padding: 0 6px 0 0 !important;
}
.chat-detail-screen .msg-reply-detached-name,
.chat-detail-screen .msg-reply-detached-text,
.chat-detail-screen .msg-reply-detached-media {
  display: block !important;
  flex: 0 1 auto !important;
  min-width: 0 !important;
  color: #8e8e93 !important;
  font: inherit !important;
  white-space: nowrap !important;
  overflow: hidden !important;
  text-overflow: ellipsis !important;
}
.chat-detail-screen .msg-reply-detached-name {
  max-width: 4em !important;
}
.chat-detail-screen .msg-reply-detached-text,
.chat-detail-screen .msg-reply-detached-media {
  /* 纯 CSS 限制约 14 个汉字的显示宽度，不是逐字符计数。 */
  max-width: 14em !important;
}
/* 引用较长时，正文气泡仍按自身内容定宽。 */
.chat-detail-screen .msg-content-stack:has(.msg-reply-block-detached) .msg-plain {
  width: fit-content !important;
  max-width: 100% !important;
}
.chat-detail-screen .msg-content-stack:has(.msg-reply-block-detached) .msg-plain-me {
  align-self: flex-end !important;
}
.chat-detail-screen .msg-content-stack:has(.msg-reply-block-detached) .msg-plain-them {
  align-self: flex-start !important;
}

/* ---- 默认只显示紧凑语音条，点击波形区域展开/收起文字 ---- */
.chat-detail-screen .voice-msg {
  position: relative !important;
}
/* 把原生“查看语音内容”按钮移到波形上，保留原来的点击功能。
   按钮不再占下面一行；文字区的显隐由程序原有状态控制。 */
.chat-detail-screen .voice-transcription-toggle {
  position: absolute !important;
  top: 0 !important;
  left: 28px !important;
  right: 0 !important;
  width: auto !important;
  min-width: 0 !important;
  height: 22px !important;
  margin: 0 !important;
  padding: 0 !important;
  opacity: 0 !important;
  z-index: 2 !important;
}
/* 语音容器与气泡同层时，计入气泡原有内边距。 */
.chat-detail-screen .voice-msg.msg-plain .voice-transcription-toggle {
  top: 8px !important;
  left: 40px !important;
  right: 12px !important;
}
/* 播放和下载按钮保持可点击。 */
.chat-detail-screen .voice-play-btn,
.chat-detail-screen .voice-download-btn {
  position: relative !important;
  z-index: 3 !important;
}
.chat-detail-screen .voice-msg:not(.msg-plain) {
  padding: 0 !important;
  margin: 0 !important;
  min-height: 0 !important;
  gap: 0 !important;
}
.chat-detail-screen .voice-controls-row {
  padding: 0 !important;
  margin: 0 !important;
  min-height: 22px !important;
  line-height: 22px !important;
  align-items: center !important;
  gap: 6px !important;
}
.chat-detail-screen .voice-play-btn,
.chat-detail-screen .voice-download-btn {
  width: 22px !important;
  height: 22px !important;
  padding: 0 !important;
}
.chat-detail-screen .voice-play-btn svg,
.chat-detail-screen .voice-download-btn svg {
  width: 18px !important;
  height: 18px !important;
}

/* =========================================
   🌟 独立翻译文字版
   白字 + 黑色描边｜透明背景
   ========================================= */

/* 隐藏原翻译 */
.msg-translation-wrapper{
    display:none !important;
}

/* 外层 */
