}

/* ==================================================
   ⭐ 1. 加号按钮 —— 移到胶囊左上角
   ================================================== */
.input-btn-plus {
  position: absolute !important;
  left: 16px !important;      /* ← 左右位置：往左调小，往右调大 */
  top: 8px !important;        /* ← 上下位置：往上调小，往下调大 */
  z-index: 10 !important;

  /* 保留功能 */
  pointer-events: auto !important;
  opacity: 1 !important;
}

/* ==================================================
   ⭐ 2. 语音按钮 —— 加号右边
   ================================================== */
.input-btn-mic {
  position: absolute !important;
  left: 96px !important;      /* ← 左右位置 */
  top: 8px !important;        /* ← 上下位置（跟加号对齐） */
  z-index: 10 !important;

  pointer-events: auto !important;
  opacity: 1 !important;
}

/* ==================================================
   ⭐ 3. 表情包按钮 —— 语音右边
   ================================================== */
.input-btn-sticker {
  position: absolute !important;
  left: 176px !important;      /* ← 左右位置 */
  top: 8px !important;        /* ← 上下位置 */
  z-index: 10 !important;

  pointer-events: auto !important;
  opacity: 1 !important;
}

/* ==================================================
   ⭐ 4. AI 按钮 —— 表情包右边
   ================================================== */
.input-btn-ai {
  position: absolute !important;
  left: 256px !important;     /* ← 左右位置 */
  top: 8px !important;        /* ← 上下位置 */
  z-index: 10 !important;

  pointer-events: auto !important;
  opacity: 1 !important;
}

/* ==================================================
   低栏按钮：ebebeb 椭圆 + 日文文字
   加号 / 语音 / 表情包 / AI
   ================================================== */

/* 隐藏所有原图标 */
.input-btn-plus > svg,
.input-btn-plus > img,
.input-btn-plus > i,
.input-btn-mic > svg,
.input-btn-mic > img,
.input-btn-mic > i,
.input-btn-sticker > svg,
.input-btn-sticker > img,
.input-btn-sticker > i,
.input-btn-ai > svg,
.input-btn-ai > img,
.input-btn-ai > i {
  display: none !important;
}

/* ==================================================
   四个按钮：统一尺寸 + 样式
   ================================================== */

.input-btn-plus,
.input-btn-mic,
.input-btn-sticker,
.input-btn-ai {
  /* 定位参照 */
  position: absolute !important;
  top: 8px !important;         /* ← 上下位置，四个一起调 */
  z-index: 10 !important;
  pointer-events: auto !important;

  /* 椭圆尺寸（锁死，不让别的地方撑） */
  width: 70px !important;
  height: 26px !important;
  min-width: 70px !important;
  min-height: 26px !important;
  max-width: 70px !important;
  max-height: 26px !important;

  /* 清掉内外边距 */
  padding: 0 !important;
  margin: 0 !important;
  box-sizing: border-box !important;

  /* 椭圆底 */
  background-color: #ebebeb !important;
  background-image: none !important;
  border-radius: 13px !important;   /* 高度的一半 = 椭圆 */

  border: none !important;
  box-shadow: none !important;

  /* 文字居中 */
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;

  font-size: 0 !important;
}

/* ==================================================
   ⭐ 左右位置（单独控制）
   ================================================== */

.input-btn-plus    { left: 16px !important; }    /* 加号 */
.input-btn-mic     { left: 96px !important; }   /* 语音 */
.input-btn-sticker { left: 176px !important; }   /* 表情包 */
.input-btn-ai      { left: 256px !important; }   /* AI */

/* ==================================================
   ⭐ 文字（四个按钮统一字体样式）
   ================================================== */

.input-btn-plus::after,
.input-btn-mic::after,
.input-btn-sticker::after,
.input-btn-ai::after {
  font-size: 11px !important;
  font-weight: 500 !important;
  color: #777777 !important;
  line-height: 1 !important;
  white-space: nowrap !important;
  letter-spacing: 0.5px !important;
}

/* 各自文字内容 */
.input-btn-plus::after    { content: "メニュー" !important; }
.input-btn-mic::after     { content: "ボイス" !important; }
.input-btn-sticker::after { content: "スタンプ" !important; }
.input-btn-ai::after      { content: "じゅしん" !important; }

