/* 旧旧信息  糯叽机 by 小真 */
/* 用素净模式，用壁纸删✅二改自用随意，勿二传，翻译来自小雨，感谢！*/

/* ==========================================================================
   全局设计令牌（Design Tokens）
   ========================================================================== */

:root {
    /* —— 色彩（顶部/底栏通过 .chat-detail-screen 作用域覆盖） —— */
    --bg-header:   #f2f2f2;  /* 顶栏背景 */
    --bg-input:    #f2f2f2;  /* 底栏背景 */
    --bg-chat:     #f0f2f5;  /* 聊天区背景 */
    --bg-bubble-in:#e3e5e8;  /* 对方气泡 */
    --text-main:   #1f1f21;  /* 主文字 */
    --text-input:  #a8a8a8;  /* 占位文字 */
    --text-deco:   #8e8e93;  /* 装饰文字 */
    --text-icon:   #9e9ea2;  /* 框内图标 */
    --text-bubble-in:#222222;/* 对方气泡文字 */
    --blue:        #4A9EFF;  /* 主色：雾蓝 */

    /* —— 字体 —— */
    --font-serif: "Georgia", "Songti SC", "STSong", serif;

    /* —— 聊天区气泡变量 —— */
    --bubble-me-bg:     var(--blue);
    --bubble-me-color:  #ffffff;
    --bubble-me-pad:    6px 10px;
    --bubble-me-size:   13px;
    --bubble-me-radius: 14px;

    --bubble-in-bg:     var(--bg-bubble-in);
    --bubble-in-color:  var(--text-bubble-in);
    --bubble-in-pad:    6px 10px;
    --bubble-in-size:   13px;
    --bubble-in-radius: 14px;

    /* 间距 */
    --gap-group:   14px;  /* 换人说话 */
    --gap-inline:  3px;   /* 同人连发 */
    --content-max: 80%;   /* 气泡最大宽度 */
}

/* ==========================================================================
   第一部分：顶部导航（Header）
   ========================================================================== */

/* 1. 顶栏主容器 */
.chat-detail-screen {
    /* ⭐ 核心主题色板（改这里换全局配色） */
    --bg-header: #f2f2f2;       /* 顶栏背景 */
    --bg-input: #f2f2f2;        /* 底栏背景 */
    --bg-chat: #f0f2f5;         /* 聊天区背景 */
    --bg-bubble-in: #e3e5e8;    /* 对方气泡 */
    --text-main: #1f1f21;       /* 主文字 */
    --text-input: #a8a8a8;      /* 占位文字 */
    --text-deco: #8e8e93;       /* 装饰文字 */
    --text-icon: #9e9ea2;       /* 框内图标 */
    --text-bubble-in: #222222;  /* 对方气泡文字 */
    --blue: #4A9EFF;            /* 主色：雾蓝 */
}

.glass-header:has(.header-profile-section) {
    background: var(--bg-header) !important;
    backdrop-filter: none !important;
