/* ==========================================================================
   第三部分：聊天区域
   ========================================================================== */

/* ✅ 1. 聊天区背景（想用壁纸时删掉这整段） */
.chat-messages-area,
.chat-message-list-custom {
    background-color: var(--bg-chat) !important;
    background-image: none !important;
}

/* 3. 隐藏头像 */
.msg-avatar-them-container,
.msg-avatar-me-container,
.msg-avatar-custom {
    display: none !important;
}

/* 4. 气泡本体 */
.msg-plain-me,
.msg-plain-them {
    position: relative !important;
    overflow: visible !important;
    box-shadow: none !important;
    backdrop-filter: none !important;
    -webkit-backdrop-filter: none !important;
}

.msg-plain-me {
    background-color: var(--bubble-me-bg) !important;
    color: var(--bubble-me-color) !important;
    border-radius: var(--bubble-me-radius) !important;
    padding: var(--bubble-me-pad) !important;
    font-size: var(--bubble-me-size) !important;
    line-height: 1.4 !important;
}

.msg-plain-them {
    background-color: var(--bubble-in-bg) !important;
    color: var(--bubble-in-color) !important;
    border-radius: var(--bubble-in-radius) !important;
    padding: var(--bubble-in-pad) !important;
    font-size: var(--bubble-in-size) !important;
    line-height: 1.4 !important;
}

/* 5. 气泡小尾巴 */
.msg-plain-me::after,
.msg-plain-them::after {
    display: none;
    content: "" !important;
    position: absolute !important;
    width: 12px !important;
    height: 12px !important;
    bottom: -7px !important;
    -webkit-mask: url("data:image/svg+xml,%3Csvg width='1207' height='960' viewBox='0 0 1207 960' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M 42 48 C 86 82, 142 156, 166 244 C 184 312, 190 398, 182 486 C 172 574, 146 648, 94 720 C 46 786, 30 854, 62 906 C 90 950, 158 946, 234 912 C 354 858, 486 784, 618 706 C 750 628, 874 550, 986 474 C 1070 418, 1138 376, 1174 362 C 1190 356, 1202 366, 1196 382 C 1190 396, 1174 394, 1160 384' fill='%23000000' stroke='none' stroke-width='42' stroke-linecap='round' stroke-linejoin='round'/%3E%3C/svg%3E") center/contain no-repeat !important;
    mask: url("data:image/svg+xml,%3Csvg width='1207' height='960' viewBox='0 0 1207 960' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M 42 48 C 86 82, 142 156, 166 244 C 184 312, 190 398, 182 486 C 172 574, 146 648, 94 720 C 46 786, 30 854, 62 906 C 90 950, 158 946, 234 912 C 354 858, 486 784, 618 706 C 750 628, 874 550, 986 474 C 1070 418, 1138 376, 1174 362 C 1190 356, 1202 366, 1196 382 C 1190 396, 1174 394, 1160 384' fill='%23000000' stroke='none' stroke-width='42' stroke-linecap='round' stroke-linejoin='round'/%3E%3C/svg%3E") center/contain no-repeat !important;
    z-index: 1 !important;
    pointer-events: none !important;
}

/* 单条或连发最后一条显示尾巴 */
.msg-plain-me.plain-single::after,
.msg-plain-me.plain-last::after,
.msg-plain-them.plain-single::after,
.msg-plain-them.plain-last::after {
    display: block !important;
}

.msg-plain-them.plain-single::after,
.msg-plain-them.plain-last::after {
    left: 7px !important;
    background-color: var(--bubble-in-bg) !important;
    transform: rotate(-3deg) !important;
}

.msg-plain-me.plain-single::after,
.msg-plain-me.plain-last::after {
    right: 7px !important;
    background-color: var(--bubble-me-bg) !important;
    transform: scaleX(-1) rotate(-3deg) !important;
}

/* 6. 引用框 */
.msg-bubble-wrapper:has(.msg-reply-block) {
    margin-top: 32px !important; /* ⭐ 与上一条拉开距离 */
}

.msg-reply-block {
    position: absolute !important;
    bottom: calc(100% + 4px) !important;
    margin: 0 !important;
    background: transparent !important;
    border: none !important;
    border-radius: 0 !important;
    padding: 0 !important;
    opacity: 1 !important;
    font-size: 11px !important;
    line-height: 1.3 !important;
    max-width: 14em !important;
    white-space: nowrap !important;
    overflow: hidden !important;
    text-overflow: ellipsis !important;
    display: flex !important;
    align-items: baseline !important;
    gap: 0 !important;
    color: rgba(100, 100, 100, 0.8) !important;
}

.msg-reply-block::before {
    content: "" !important;
    display: inline-block !important;
    width: 12px !important;
    height: 12px !important;
    flex-shrink: 0 !important;
    background-color: currentColor !important;
    margin-right: 4px !important;
    -webkit-mask: url("data:image/svg+xml,%3Csvg width='24' height='24' viewBox='0 0 48 48' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M26 4L44 22L26 39V28C12 28 6 43 6 43C6 26 11 15 26 15V4Z' fill='none' stroke='%23000' stroke-width='4' stroke-linecap='round' stroke-linejoin='round'/%3E%3C/svg%3E") center/contain no-repeat !important;
    mask: url("data:image/svg+xml,%3Csvg width='24' height='24' viewBox='0 0 48 48' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M26 4L44 22L26 39V28C12 28 6 43 6 43C6 26 11 15 26 15V4Z' fill='none' stroke='%23000' stroke-width='4' stroke-linecap='round' stroke-linejoin='round'/%3E%3C/svg%3E") center/contain no-repeat !important;
}

.msg-reply-block-name::before {
    content: "回复 " !important;
    font-weight: normal !important;
    color: inherit !important;
}

.msg-reply-block-name::after {
    content: "：" !important;
    font-weight: normal !important;
    color: inherit !important;
}

/* 对方引用框靠左 */
.msg-them .msg-reply-block {
    left: 0 !important;
    flex-direction: row !important;
}

/* 我方引用框靠右，图标翻转 */
.msg-me .msg-reply-block {
    right: 0 !important;
    flex-direction: row !important;
}

.msg-me .msg-reply-block::before {
    order: 2 !important;
    margin-left: 4px !important;
    margin-right: 0 !important;
    transform: scaleX(-1) !important;
}

.msg-reply-block-name {
    display: inline !important;
    font-weight: 500 !important;
    flex-shrink: 0 !important;
    color: inherit !important;
}

.msg-reply-block-text {
    display: inline !important;
    white-space: nowrap !important;
    overflow: hidden !important;
    text-overflow: ellipsis !important;
    color: inherit !important;
    margin-left: 2px !important;
}

/* 7. 特殊媒体脱壳（图片/贴纸/卡片等去掉气泡包裹） */
.msg-bubble-wrapper:has(.chat-image) .msg-plain-me,
.msg-bubble-wrapper:has(.chat-image) .msg-plain-them,
.msg-bubble-wrapper:has(.sticker-image) .msg-plain-me,
.msg-bubble-wrapper:has(.sticker-image) .msg-plain-them,
.msg-bubble-wrapper:has(.msg-transfer-card) .msg-plain-me,
.msg-bubble-wrapper:has(.msg-transfer-card) .msg-plain-them,
.msg-bubble-wrapper:has(.gift-ig-container) .msg-plain-me,
.msg-bubble-wrapper:has(.gift-ig-container) .msg-plain-them {
    background-color: transparent !important;
    border: none !important;
    padding: 0 !important;
    border-radius: 0 !important;
    box-shadow: none !important;
    display: block !important;
}

/* 隐藏这些消息的尾巴 */
.msg-bubble-wrapper:has(.chat-image) .msg-plain-me::after,
.msg-bubble-wrapper:has(.chat-image) .msg-plain-them::after,
.msg-bubble-wrapper:has(.sticker-image) .msg-plain-me::after,
.msg-bubble-wrapper:has(.sticker-image) .msg-plain-them::after,
.msg-bubble-wrapper:has(.msg-transfer-card) .msg-plain-me::after,
.msg-bubble-wrapper:has(.msg-transfer-card) .msg-plain-them::after,
.msg-bubble-wrapper:has(.gift-ig-container) .msg-plain-me::after,
.msg-bubble-wrapper:has(.gift-ig-container) .msg-plain-them::after {
    display: none !important;
    content: none !important;
}

/* 8. 表情包 / 贴纸尺寸 */
img[alt="sticker"],
.msg-bubble-container.no-padding:not(:has(.msg-image-wrapper)):not(:has([class*="card"])) img {
    width: 100px !important;
    height: 100px !important;
    max-width: 100px !important;
    object-fit: contain !important;
    background: transparent !important;
    border: none !important;
    box-shadow: none !important;
    border-radius: 0 !important;
}

/* 9. 普通图片消息 */
.msg-image-wrapper,
.msg-image-img {
    max-width: 170px !important;
    height: auto !important;
    object-fit: contain !important;
}

/* =========================================
   🌟 独立翻译文字版
   白字 + 黑色描边｜透明背景
   ========================================= */

/* 隐藏原翻译 */
.msg-translation-wrapper{
    display:none !important;
}

/* 外层 */
.msg-translation-detached{
    display:inline-flex !important;

    width:auto !important;
    min-width:0 !important;
    max-width:none !important;

    position:relative !important;
    z-index:20 !important;

    margin-top:-7px !important;
    margin-bottom:4px !important;

    flex:none !important;
}

/* 对方 */
.msg-translation-detached-them{
    align-self:flex-start !important;
    margin-left:12px !important;
}

/* 自己 */
.msg-translation-detached-me{
    align-self:flex-end !important;
    margin-right:12px !important;
}

/* =========================================
   ⭐ 只修改这里：翻译变成白字黑边
   ========================================= */

.msg-translation-detached-content{

    display:inline-block !important;

    width:auto !important;
    min-width:0 !important;
    max-width:260px !important;

    /* ❌ 删除白色横条 */
    background:none !important;
    background-color:transparent !important;

    /* 🤍 白色文字 */
    color:#ffffff !important;

    /* ❌ 删除原来的白条空间 */
    padding:0 !important;

    /* 🔤 字体：12px 字号更舒服，italic 斜体 */
