:root {
  /* 我方气泡 */
  --my-bubble-color: #d4e0e8;
  --my-bubble-text: #ffffff;

  /* 我方气泡大小 */
  --my-bubble-padding: 7px 13px;

  /* 我方第一条：右下角微圆，左边更圆 */
  --my-bubble-first-radius: 22px 18px 3px 22px;

  /* 其他我方气泡 */
  --my-bubble-mid-radius: 22px 4px 4px 22px;
  --my-bubble-last-radius: 22px 4px 18px 22px;
  --my-bubble-single-radius: 22px;

  /* 对方气泡 */
  --them-bubble-color: #E9E9E9;
  --them-bubble-text: #000000;

  /* 对方气泡大小 */
  --them-bubble-padding: 7px 13px;

  /* 对方第一条：镜像我方弧度 */
  --them-bubble-first-radius: 18px 22px 22px 3px;

  /* 其他对方气泡 */
  --them-bubble-mid-radius: 4px 22px 22px 4px;
  --them-bubble-last-radius: 4px 22px 18px 22px;
  --them-bubble-single-radius: 22px;
}

/* 整个消息气泡在聊天窗口中的左右外边距 */
.msg-container,
.chat-message,
.message-container {
  margin-left: 4px !important;
  margin-right: 4px !important;
}

/* 我方气泡统一颜色和大小 */
.msg-plain-me {
  background: var(--my-bubble-color) !important;
  color: var(--my-bubble-text) !important;
  padding: var(--my-bubble-padding) !important;
}

/* 第一条我方消息 */
.msg-plain-me.plain-first {
  background: var(--my-bubble-color) !important;
  color: var(--my-bubble-text) !important;
  padding: var(--my-bubble-padding) !important;
  border-radius: var(--my-bubble-first-radius) !important;
}

/* 中间的我方消息 */
.msg-plain-me.plain-mid {
  background: var(--my-bubble-color) !important;
  color: var(--my-bubble-text) !important;
  padding: var(--my-bubble-padding) !important;
  border-radius: var(--my-bubble-mid-radius) !important;
}

/* 最后一条我方消息 */
.msg-plain-me.plain-last {
  background: var(--my-bubble-color) !important;
  color: var(--my-bubble-text) !important;
  padding: 7px 28px 7px 13px !important;
  border-radius: var(--my-bubble-last-radius) !important;
}

/* 单独一条我方消息 */
.msg-plain-me.plain-single {
  background: var(--my-bubble-color) !important;
  color: var(--my-bubble-text) !important;
  padding: 7px 28px 7px 13px !important;
  border-radius: var(--my-bubble-single-radius) !important;
}

/* 对方气泡统一颜色和大小 */
.msg-plain-them {
  background: var(--them-bubble-color) !important;
  color: var(--them-bubble-text) !important;
  padding: var(--them-bubble-padding) !important;
}

/* 第一条对方消息 */
.msg-plain-them.plain-first {
  background: var(--them-bubble-color) !important;
  color: var(--them-bubble-text) !important;
  padding: var(--them-bubble-padding) !important;
  border-radius: var(--them-bubble-first-radius) !important;
}

/* 中间的对方消息 */
.msg-plain-them.plain-mid {
  background: var(--them-bubble-color) !important;
  color: var(--them-bubble-text) !important;
  padding: var(--them-bubble-padding) !important;
  border-radius: var(--them-bubble-mid-radius) !important;
}

/* 最后一条对方消息 */
.msg-plain-them.plain-last {
  background: var(--them-bubble-color) !important;
  color: var(--them-bubble-text) !important;
  padding: var(--them-bubble-padding) !important;
  border-radius: var(--them-bubble-last-radius) !important;
}

/* 单独一条对方消息 */
.msg-plain-them.plain-single {
  background: var(--them-bubble-color) !important;
  color: var(--them-bubble-text) !important;
  padding: var(--them-bubble-padding) !important;
  border-radius: var(--them-bubble-single-radius) !important;
}

/* 隐藏双方头像 */
.msg-avatar-me-container,
.msg-avatar-them-container {
  display: none !important;
  width: 0 !important;
  min-width: 0 !important;
  margin: 0 !important;
  padding: 0 !important;
}

/* 我方最后一条和单独一条：定位 */
.msg-plain-me.plain-last,
.msg-plain-me.plain-single {
  position: relative !important;
}

/* 两个叠起来的磨砂圆 */
.msg-plain-me.plain-last::before,
.msg-plain-me.plain-last::after,
.msg-plain-me.plain-single::before,
.msg-plain-me.plain-single::after {
  content: "✓";
  position: absolute;
  bottom: 7px;
  width: 10px;
  height: 10px;
  background: rgba(255, 255, 255, 0.78);
  border-radius: 50%;
  color: #d4e0e8;
  font-size: 6.5px;
  font-weight: 700;
  line-height: 10px;
  text-align: center;
  box-sizing: border-box;
  backdrop-filter: blur(2px);
  -webkit-backdrop-filter: blur(2px);
}

/* 后面的圆 */
.msg-plain-me.plain-last::before,
.msg-plain-me.plain-single::before {
  right: 13.5px;
  z-index: 1;
}

/* 前面的圆 */
.msg-plain-me.plain-last::after,
.msg-plain-me.plain-single::after {
  right: 8.5px;
  z-index: 2;
  box-shadow: 0 0 0 1px var(--my-bubble-color);
}

/* 我方引用 */
.msg-me .msg-reply-block {
  position: relative !important;
  box-sizing: border-box !important;
  background: linear-gradient(
    to right,
    #FFFFFF 0,
    #FFFFFF 4px,
    #D9E5EC 4px,
    #D9E5EC 100%
  ) !important;
  border: none !important;
  border-radius: 9px 9px 5px 5px !important;
  padding: 1px 0 1px 4px !important;
  margin: -2px -10px 4px -2px !important;
  box-shadow: none !important;
  overflow: hidden !important;
}

/* 对方引用 */
.msg-them .msg-reply-block {
  position: relative !important;
  box-sizing: border-box !important;
  background: linear-gradient(
    to right,
    #FFFFFF 0,
    #FFFFFF 4px,
    #F2F2F4 4px,
    #F2F2F4 100%
  ) !important;
  border: none !important;
  border-radius: 9px 9px 5px 5px !important;
  padding: 1px 0 1px 4px !important;
  margin: -2px -2px 4px -2px !important;
  box-shadow: none !important;
  overflow: hidden !important;
}

/* 引用内容 */
.msg-reply-block-name,
.msg-reply-block-text,
.msg-reply-block-media {
  position: relative !important;
  z-index: 1 !important;
}

/* 引用名字 */
.msg-reply-block-name {
  color: #111111 !important;
  font-size: 10.5px !important;
  font-weight: 700 !important;
  line-height: 1.25 !important;
  padding: 6px 11px 2px 11px !important;
  margin: 0 !important;
}

/* 引用正文 */
.msg-reply-block-text {
  color: #111111 !important;
  font-size: 11.5px !important;
  font-weight: 500 !important;
  line-height: 1.3 !important;
  padding: 2px 11px 6px 11px !important;
  margin: 0 !important;
}

/* 去掉原来的竖线 */
.msg-reply-block-name::before,
.msg-reply-detached-name::before {
  display: none !important;
  content: none !important;
}

/* 引用图片 */
.msg-reply-block-media {
  display: block !important;
  margin: 4px 9px 6px 9px !important;
  border-radius: 4px !important;
  overflow: hidden !important;
  opacity: 1 !important;
  visibility: visible !important;
}

/* 引用图片本体 */
.msg-reply-block-media img {
  display: block !important;
  opacity: 1 !important;
  visibility: visible !important;
  max-width: 100% !important;
  height: auto !important;
}

/* 我方引用图片区域 */
.msg-me .msg-reply-block-media {
  background-color: #F8F8F8 !important;
}

/* 对方引用图片区域 */
.msg-them .msg-reply-block-media {
  background-color: #FFFFFF !important;
}

/* =====翻译美化===== */

:root {
