/* Messenger 原版风 · 聊天转账卡 */

:root {
  --transfer-card-width: 235px;
  --transfer-card-height: 104px;

  --transfer-card-bg: #ffffff;
  --transfer-card-border: 1px solid #dedede;
  --transfer-card-radius: 15px;

  --transfer-blue: #d4e0e8;

  --transfer-amount-size: 27px;
  --transfer-amount-weight: 200;

  --transfer-label-size: 9px;
  --transfer-value-size: 11px;

  --transfer-label-color: #8a8a8a;
  --transfer-value-color: #171717;

  --transfer-divider-color: #dedede;
}

/* 转账卡 */

html body .msg-transfer-card,
html body .msg-transfer-card.msg-transfer-success {
  position: relative !important;

  width: var(--transfer-card-width) !important;
  min-width: var(--transfer-card-width) !important;
  max-width: var(--transfer-card-width) !important;

  height: var(--transfer-card-height) !important;
  min-height: var(--transfer-card-height) !important;
  max-height: var(--transfer-card-height) !important;

  box-sizing: border-box !important;

  margin: 0 !important;
  padding: 0 !important;

  background: var(--transfer-card-bg) !important;
  background-image: none !important;

  border: var(--transfer-card-border) !important;
  border-radius: var(--transfer-card-radius) !important;

  box-shadow: none !important;

  overflow: hidden !important;
}

/* 清掉旧伪元素 */

html body .msg-transfer-card::before,
html body .msg-transfer-card::after {
  content: none !important;
  display: none !important;
}

/* 内容区 */

html body .msg-transfer-card .msg-transfer-content {
  position: relative !important;

  width: 100% !important;
  height: 100% !important;

  display: block !important;

  box-sizing: border-box !important;

  margin: 0 !important;
