:root {
  --input-area-bg: transparent;
  --input-area-blur: 0px;
  --input-area-border-top: none;
  --input-box-bg: rgba(255, 255, 255, 0.58);
  --input-box-width: 320px;
  --input-box-height: 38px;
}

.input-area-custom {
  background: transparent !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  border-top: none !important;
  position: relative !important;
  top: -15px !important;
  margin-top: -15px !important;
}

.input-action-bar-custom {
  background: rgba(255, 255, 255, 0.58) !important;
  width: var(--input-box-width) !important;
  flex: none !important;
  height: var(--input-box-height) !important;
  min-height: var(--input-box-height) !important;
  box-sizing: border-box !important;
  position: relative !important;
  left: 10px !important;
  top: -10px !important;
  backdrop-filter: blur(18px) saturate(180%) !important;
  -webkit-backdrop-filter: blur(18px) saturate(180%) !important;
  border: 1px solid rgba(255, 255, 255, 0.48) !important;
  box-shadow:
    inset 0 1px 1px rgba(255, 255, 255, 0.72),
    inset 0 -1px 2px rgba(255, 255, 255, 0.18),
    0 3px 12px rgba(0, 0, 0, 0.07) !important;
  border-radius: 20px !important;
}

/* === 彻底隐藏原有的 "消息..." === */
.input-action-bar-custom input::-webkit-input-placeholder,
.input-action-bar-custom textarea::-webkit-input-placeholder {
  color: transparent !important;
  opacity: 0 !important;
}

.input-action-bar-custom input::placeholder,
.input-action-bar-custom textarea::placeholder {
  color: transparent !important;
  opacity: 0 !important;
}

/* === 覆盖自定义文字 "发消息"（字色变深、字号放大） === */
.input-action-bar-custom::before {
  content: "发消息" !important;
  position: absolute !important;
  left: 15px !important;
  top: 50% !important;
  transform: translateY(-50%) !important;
  color: rgba(0, 0, 0, 0.6) !important;
  font-size: 15px !important;
  pointer-events: none !important;
  z-index: 2 !important;
}

/* 当点击输入框或开始打字时，自动隐藏 "发消息" */
.input-action-bar-custom:has(input:focus)::before,
.input-action-bar-custom:has(textarea:focus)::before,
.input-action-bar-custom:has(input:not(:placeholder-shown))::before,
.input-action-bar-custom:has(textarea:not(:placeholder-shown))::before {
  display: none !important;
}

/* 右侧按钮保持显示，去掉默认边框和背景 */
.send-btn-custom,
.stop-btn-custom,
.input-btns-right {
  opacity: 1 !important;
  border: none !important;
  outline: none !important;
  box-shadow: none !important;
}

/* 左侧加号：无边框磨砂圆 */
.input-btn-plus {
  width: 40px !important;
  height: 40px !important;
  border-radius: 50% !important;
  background: rgba(255, 255, 255, 0.72) !important;
  backdrop-filter: blur(10px) !important;
  -webkit-backdrop-filter: blur(10px) !important;
  border: none !important;
  outline: none !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  box-shadow:
    0 2px 8px rgba(0, 0, 0, 0.08),
    inset 0 0 5px rgba(255, 255, 255, 0.55) !important;
  padding: 0 !important;
  opacity: 1 !important;
  margin-top: -15px !important;
  transform: translateY(-10px) !important;
}

/* 右侧图标组容器排版 */
.input-btns-right {
  display: flex !important;
  align-items: center !important;
  gap: 12px !important;
  padding-right: 2px !important;
  transform: translateX(8px) !important;
}

/* 隐藏原有自带 SVG */
.input-btns-right > * {
  width: 28px !important;
  height: 28px !important;
  min-width: 28px !important;
  min-height: 28px !important;
  background-size: contain !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
  border: none !important;
  outline: none !important;
