   --input-area-bg: rgba(248, 248, 248, 0.9); /* 降低透明度 */
   --input-area-border-top: 0.5px solid rgba(0, 0, 0, 0.08); /* ✅ 极细边框 */
   --input-area-padding: 6px 7px 10px 7px;

