/* ============================================================
   月光白 · 方形气泡主题（完整最终版 v19）
   白底 / 去边框留横线 / 灰字
   顶栏灰蓝文字 / 底栏上浮+图标放大 / 语音条点击转移
   仅对方第一条带斜体文字 / 气泡紧贴文字下方 / 首条气泡加横线
   引用框去边框 + 拐弯箭头
   ============================================================ */

:root {
  /* ================= 全局背景：纯白 ================= */
  --chat-bg-color: #ffffff;
  --chat-bg-image: none;
  --chat-bg-blur: 0px;
  --chat-bg-overlay: rgba(0, 0, 0, 0);

  /* ================= 顶部导航 ================= */
