  --chat-header-title-weight: 400;
  --chat-header-subtitle-color: #a8b0c0;
  --chat-header-icon-color: #7a8296;
  --chat-header-avatar-size: 32px;
  --chat-header-avatar-border: 1px solid rgba(160, 175, 200, 0.5);
  --chat-header-avatar-radius: 50%;
  --chat-header-avatar-shadow: none;
  --header-btn-gap: 16px;

  --chat-header-unread-bg: #ff5a7a;
  --chat-header-unread-num-bg: #ff5a7a;

  /* ================= 消息区域 ================= */
  --chat-messages-padding: 12px 14px;
  --chat-messages-gap: 2px;
  --chat-message-max-width: 78%;

  /* ================= 我方气泡：无边框无阴影 ================= */
  --bubble-me-bg: transparent;
  --bubble-me-bg-gradient: initial;
  --bubble-me-color: #7a8296;
  --bubble-me-font-size: 14px;
  --bubble-me-line-height: 1.45;
  --bubble-me-padding: 6px 10px;
  --bubble-me-border: none;
  --bubble-me-shadow: none;
  --bubble-me-radius: 0px;
  --bubble-me-radius-first: 0px;
  --bubble-me-radius-mid: 0px;
  --bubble-me-radius-last: 0px;
  --bubble-me-link-color: #5a6a8a;
  --bubble-me-text-shadow: none;
  --bubble-me-letter-spacing: normal;
  --bubble-me-backdrop: none;
  --bubble-me-filter: none;
  --bubble-me-opacity: 1;
  --bubble-me-transform: none;

  /* ================= 对方气泡：无边框无阴影 ================= */
  --bubble-them-bg: transparent;
  --bubble-them-bg-gradient: initial;
  --bubble-them-color: #7a8296;
  --bubble-them-font-size: 14px;
  --bubble-them-line-height: 1.45;
  --bubble-them-padding: 6px 10px;
  --bubble-them-border: none;
  --bubble-them-shadow: none;
  --bubble-them-radius: 0px;
  --bubble-them-radius-first: 0px;
  --bubble-them-radius-mid: 0px;
  --bubble-them-radius-last: 0px;
  --bubble-them-link-color: #5a6a8a;
  --bubble-them-text-shadow: none;
  --bubble-them-letter-spacing: normal;
  --bubble-them-backdrop: none;
  --bubble-them-filter: none;
  --bubble-them-opacity: 1;
  --bubble-them-transform: none;

  /* ================= 头像：缩小 + 方形（保留细框） ================= */
  --avatar-size: 32px;
  --avatar-radius: 0px;
  --avatar-border: 0.5px solid rgba(150, 165, 195, 0.55);
  --avatar-margin: 6px;
  --avatar-shadow: none;
  --avatar-placeholder-bg: #f2f5fa;

