  /* ================= 输入区域 ================= */
  --input-area-bg: #ffffff;
  --input-area-bg-image: none;
  --input-area-blur: 0px;
  --input-area-border-top: 0.5px solid rgba(190, 200, 220, 0.4);
  --input-area-padding: 12px 14px 20px 14px;
  --input-area-min-height: 56px;

  /* 输入框本体：方形 + 月光细边 */
  --input-box-bg: #ffffff;
  --input-box-color: #4a5266;
  --input-box-placeholder: #b8c0d0;
