  /* ================= WhatsApp 气泡内时间戳 ================= */
  --wa-me-meta-color: rgba(122, 130, 150, 0.75);
  --wa-me-meta-size: 11px;
  --wa-me-check-color: rgba(122, 130, 150, 0.75);
  --wa-me-check-read-color: #8a92a6;
  --wa-them-meta-color: rgba(122, 130, 150, 0.75);
  --wa-them-meta-size: 11px;

  /* ================= IG/QQ 已读状态 ================= */
  --status-color: #aab2c4;
  --status-size: 10px;
  --status-weight: 400;
  --status-font-family: inherit;
  --status-margin: 2px 2px 0 0;
  --status-read-color: #7a8296;
  --status-sent-color: #c8d0de;
  --status-opacity: 1;

  /* ================= 输入区域 ================= */
  --input-area-bg: #ffffff;
  --input-area-bg-image: none;
  --input-area-blur: 0px;
  --input-area-border-top: 0.5px solid rgba(190, 200, 220, 0.4);
  --input-area-padding: 12px 14px 20px 14px;
  --input-area-min-height: 56px;

  /* 输入框本体：方形 + 月光细边 */
  --input-box-bg: #ffffff;
  --input-box-color: #4a5266;
  --input-box-placeholder: #b8c0d0;
  --input-box-radius: 0px;
  --input-box-padding: 8px 12px;
  --input-box-font-size: 14px;
  --input-box-border: 0.5px solid rgba(150, 165, 195, 0.55);
  --input-box-blur: none;
  --input-box-shadow: 0 0 10px rgba(180, 195, 225, 0.10);
  --input-caret-color: #7a8296;

  /* 回复预览栏 */
  --reply-bar-accent: #8a92a6;
  --reply-bar-text-color: #a8b0c0;

  /* 更多选项面板 */
  --more-options-bg: rgba(255, 255, 255, 0.96);
  --more-options-blur: blur(30px) saturate(180%);
  --more-options-bg-solid: rgba(255, 255, 255, 0.985);
  --more-options-shadow: 0 10px 40px rgba(170, 185, 215, 0.18);
  --more-options-border: 0.5px solid rgba(190, 200, 220, 0.4);
  --more-options-color: #4a5266;
  --more-options-divider: rgba(180, 195, 220, 0.3);

  /* ================= 发送 / 停止 / 加号 / 输入区按钮 ================= */
  --send-btn-bg: transparent;
  --send-btn-bg-hover: transparent;
  --send-btn-color: #7a8296;
  --send-btn-size: 24px;
  --send-btn-radius: 0;
  --send-btn-shadow: none;

  --stop-btn-bg: transparent;
  --stop-btn-bg-hover: transparent;
  --stop-btn-color: #c08a9a;
  --stop-btn-size: 24px;
  --stop-btn-radius: 0;
  --stop-btn-shadow: none;

  --plus-btn-bg: transparent;
  --plus-btn-color: #7a8296;
  --plus-btn-size: 22px;
  --input-btn-color: #7a8296;

  /* ================= 表情面板 ================= */
  --emoji-panel-bg: #ffffff;
  --emoji-panel-blur: 0px;
  --emoji-panel-shadow: 0 -1px 0 rgba(190, 200, 220, 0.3);
  --emoji-panel-radius: 0;

  /* ================= 图片消息 ================= */
  --image-msg-radius: 0px;
  --image-msg-shadow: 0 0 12px rgba(180, 195, 225, 0.12);
  --image-msg-max-width: 240px;
  --image-msg-border: 0.5px solid rgba(150, 165, 195, 0.55);
  --image-me-radius: 0px;
  --image-me-shadow: 0 0 12px rgba(180, 195, 225, 0.12);
  --image-me-border: 0.5px solid rgba(150, 165, 195, 0.55);
  --image-them-radius: 0px;
  --image-them-shadow: 0 0 12px rgba(180, 195, 225, 0.12);
  --image-them-border: 0.5px solid rgba(150, 165, 195, 0.55);

  /* ================= 转账卡 ================= */
  --transfer-card-bg: #ffffff;
  --transfer-card-radius: 0px;
  --transfer-card-shadow: 0 0 12px rgba(180, 195, 225, 0.10);
  --transfer-card-border: 0.5px solid rgba(150, 165, 195, 0.55);
  --transfer-icon-bg: #eef2fa;
  --transfer-amount-color: #4a5266;

  /* ================= 位置卡 ================= */
  --location-card-bg: #ffffff;
  --location-card-radius: 0px;
  --location-card-shadow: 0 0 12px rgba(180, 195, 225, 0.10);
  --location-card-border: 0.5px solid rgba(150, 165, 195, 0.55);
  --location-map-bg: #e8edf6;
  --location-pin-color: #8a92a6;

  /* ================= 礼物盒 ================= */
  --gift-box-light: #ffffff;
  --gift-box-dark: #f2f5fa;
  --gift-ribbon-color: #b8c0d0;
  --gift-ribbon-dark: #9aa4b8;
  --gift-shadow-color: rgba(180, 195, 225, 0.2);

  /* ================= 表情反应徽章 ================= */
  --reaction-badge-bg: #ffffff;
  --reaction-badge-color: inherit;
  --reaction-badge-border: 0.5px solid rgba(150, 165, 195, 0.55);
  --reaction-badge-radius: 0px;
  --reaction-badge-padding: 2px 4px;
  --reaction-badge-shadow: 0 0 6px rgba(180, 195, 225, 0.18);
  --reaction-badge-size: 12px;
  --reaction-badge-gap: 2px;
  --reaction-badge-line-height: normal;
  --reaction-badge-bottom: -12px;
  --reaction-badge-offset: -4px;

  /* ================= 上下文菜单 / 表情反应栏 ================= */
  --context-menu-bg: rgba(255, 255, 255, 0.96);
  --context-menu-blur: 20px;
  --context-menu-shadow: 0 8px 24px rgba(170, 185, 215, 0.18);
  --context-menu-radius: 0px;
  --context-menu-item-hover: rgba(180, 195, 220, 0.12);

  --reaction-bar-bg: rgba(255, 255, 255, 0.96);
  --reaction-bar-shadow: 0 4px 12px rgba(170, 185, 215, 0.15);
  --reaction-bar-radius: 0px;

  /* ================= 打字指示器 ================= */
  --typing-dot-color: #b0b8cc;
  --typing-dot-size: 7px;
  --typing-bg: #ffffff;
  --typing-radius: 0px;

  /* ================= 滚动条：隐藏 ================= */
  --scrollbar-width: 0px;
  --scrollbar-track: transparent;
  --scrollbar-thumb: rgba(150, 165, 195, 0.3);
  --scrollbar-thumb-hover: rgba(150, 165, 195, 0.5);
}

/* ============================================================
   顶栏：去掉头像 & 状态，加高栏位，标题换成斜体灰蓝文字
   ============================================================ */

.header-avatar-container {
  display: none !important;
}

.chat-header-subtitle {
  display: none !important;
}

.chat-header-title {
  font-size: 0 !important;
  background: transparent !important;
  padding: 0 !important;
  border: none !important;
  backdrop-filter: none !important;
}

.chat-header-title::after {
  content: "一样的月光.....";
  font-size: 14px;
  font-weight: 400;
  font-style: italic;
  letter-spacing: 0.12em;
  color: #8a92a6;
  text-shadow: 0 0 6px rgba(180, 195, 225, 0.7),
               0 0 16px rgba(180, 195, 225, 0.35);
  white-space: nowrap;
}

.header-profile-section {
  justify-content: flex-start !important;
}

/* 顶栏底边渐隐银线 */
.chat-header-custom {
