  box-shadow: 0 1px 0 rgba(180, 195, 225, 0.25),
              0 6px 16px rgba(180, 195, 225, 0.08);
}

/* ============================================================
   聊天页顶部「月光洒落」冷蓝光晕
   ============================================================ */

.chat-detail-screen {
  position: relative;
}

.chat-detail-screen::before {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: radial-gradient(
    ellipse 130% 55% at 50% 0%,
    rgba(205, 218, 245, 0.28) 0%,
    rgba(255, 255, 255, 0) 65%
  );
  z-index: 0;
}

.chat-messages-area {
  position: relative;
  z-index: 1;
}

