.bubble-me-custom, .bubble-them-custom {
  position: relative !important;
  overflow: visible !important;
  padding: 9px 16px !important;
  border-radius: 22px !important;
  box-shadow: none !important;
  border: none !important;
  min-width: 64px;
}
.bubble-me-custom   { background: var(--b-me) !important;   color: var(--t-me) !important;   --tail: var(--b-me); }
.bubble-them-custom { background: var(--b-them) !important; color: var(--t-them) !important; --tail: var(--b-them); }

:is(.is-last, .is-single) :is(.bubble-me-custom, .bubble-them-custom)::before,
:is(.is-last, .is-single) :is(.bubble-me-custom, .bubble-them-custom)::after {
  content: ""; position: absolute; background: var(--tail); pointer-events: none;
}
:is(.is-last, .is-single) :is(.bubble-me-custom, .bubble-them-custom)::after {
  width: 30px; height: 10px; top: calc(100% - 3px);
  border-radius: 0 0 50% 50% / 0 0 100% 100%;
}
:is(.is-last, .is-single) :is(.bubble-me-custom, .bubble-them-custom)::before {
  width: 8px; height: 8px; border-radius: 50%; top: calc(100% + 6px);
}
:is(.is-last, .is-single) .bubble-me-custom::after    { right: 15px; }
:is(.is-last, .is-single) .bubble-me-custom::before   { right: 44px; }
:is(.is-last, .is-single) .bubble-them-custom::after  { left: 15px; }
:is(.is-last, .is-single) .bubble-them-custom::before { left: 44px; }

