/* ================= 日间版(雾蓝灰白 · 只改颜色) =================
   结构跟你原来的完全一样(圆角、尾巴、头像、布局都没动),只换颜色。
   改颜色只改下面这组 --sq- 变量 */
:root:root {
  --sq-bg:   #ffffff;   /* 页面 / 顶栏 / 底栏底色 */
  --sq-me:   #e1e9f2;   /* 我方气泡 */
  --sq-them: #f2f5f9;   /* 对方气泡(原图是纯白+描边,纯白在白底上会看不见,所以用极浅蓝灰) */
  --sq-text: #2b2b2b;   /* 正文字色 */
  --sq-line: #cdd7e2;   /* 线条 / 描边 */
  --sq-soft: #eef2f7;   /* 浅色块 */
  --sq-ink:  #222222;   /* 顶栏文字 / 图标 */
  --sq-sub:  #9aa7b5;   /* 淡色小字 */

  --b-me: var(--sq-me);     --t-me: var(--sq-text);
  --b-them: var(--sq-them); --t-them: var(--sq-text);

  --chat-bg-color: var(--sq-bg);
  --chat-header-bg: var(--sq-bg);
  --chat-header-title-color: var(--sq-ink);
  --chat-header-icon-color: var(--sq-ink);
  --input-area-bg: var(--sq-bg);

  --handle-color: var(--sq-sub);
  --tx-color: var(--sq-sub);
  --think-color: var(--sq-sub);
  --ph-color: #b3bcc6;
  --timestamp-color: var(--sq-sub);
  --date-divider-color: var(--sq-sub);

  --tip-bg: rgba(255,255,255,0.9);
  --tip-border: 1px solid var(--sq-line);
  --tip-color: #8693a1;
  --tip-shadow: none;
}
.chat-detail-screen {
  --sendas-char-border: var(--sq-line);
  --sendas-narration-border: var(--sq-line);
  --reply-bar-accent: var(--sq-line);
}

/* 页面 / 顶栏 / 底栏 */
