  --sim-rot-1: 1deg;
  --sim-rot-2: -10deg;
  --sim-rot-3: 10deg;
  --sim-rot-4: -6deg;

  /* 文件卡 */
  /* 🐕 */ --file-w: 230px;
  /* 🐕 */ --file-h: 76px;
  /* 🐕 */ --file-radius: 10px;
  /* 🐕 */ --file-icon-img: url("https://i.postimg.cc/Kzs9dz2w/IMG-6037.png");
  /* 🐕 */ --file-icon-w: 39px;
  /* 🐕 */ --file-icon-h: 45px;
  /* 🐕 */ --file-name-color: #1A1A1A;
  /* 🐕 */ --file-meta-color: #9A9A9A;
  /* 🐕 */ --file-status-me: " / 已发送";
  /* 🐕 */ --file-status-them: " / 已接收";
}

/* --- 00e. 顶栏未读徽章变量（必须挂在这个 class 上，写在 :root 里不生效） --- */
div.chat-detail-screen .nuo-chat-header-unread-num {
  --chat-header-unread-num-bg: #EDEDED;
  --chat-header-unread-num-color: #555555;
  --chat-header-unread-num-size: 11px;
  --chat-header-unread-num-weight: 600;
  --chat-header-unread-num-height: 17px;
  --chat-header-unread-num-min-width: 17px;
  --chat-header-unread-num-padding: 0 5px;
  --chat-header-unread-num-radius: 999px;
  --chat-header-unread-num-top: 50%;
  --chat-header-unread-num-left: 28px;
  --chat-header-unread-num-transform: translateY(-50%);
}

/* --- 00f. 红包变量（卡内文字默认 inherit，这里统一改灰） --- */
div.chat-detail-screen .msg-redpacket-card {
  --redpacket-bg: #FFFFFF;
  --redpacket-color: #6E6E73;
  --redpacket-opened-bg: #FFFFFF;
  --redpacket-opened-color: #6E6E73;
  --rp-footer: "待领取";                      /* ← 底部左侧文字，可改成固定日期 */
}
div.chat-detail-screen .msg-redpacket-card.is-opened {
  --rp-footer: "已领取";
}

/* ◆◆◆◆◆◆◆◆◆◆◆◆ 【01 聊天背景】 ◆◆◆◆◆◆◆◆◆◆◆◆ */

/* 兜底：App 设置里上传的墙纸可能走内联样式，变量压不住，这里直接覆盖 */
div.chat-detail-screen,
div.chat-detail-screen .chat-messages-area {
  background: #FDFDFD !important;
  background-image: none !important;
}

/* ◆◆◆◆◆◆◆◆◆◆◆◆ 【02 气泡】 ◆◆◆◆◆◆◆◆◆◆◆◆ */
/* ═══════════════════════════════════════════════
   粘连圆角气泡 · iMessage/KakaoTalk 风格
   我方：#f4f4f4 描边 #f1f1f1 文字 #222222
   对方：#ffffff 描边 #efefef 文字 #333333
   用 is-first/is-mid/is-last/is-single 做粘连圆角
   ═══════════════════════════════════════════════ */

/* --- 1. 气泡本体（公共） --- */
div.chat-detail-screen .bubble-them-custom,
div.chat-detail-screen .msg-plain-them,
div.chat-detail-screen .bubble-me-custom,
div.chat-detail-screen .msg-plain-me {
  font-size: 13px !important;
  line-height: 1.4 !important;
  padding: 8px 12px !important;
  position: relative !important;
  overflow: visible !important;
  z-index: 1 !important;
  margin-bottom: 0 !important;
  text-shadow: none !important;
  box-shadow: none !important;
}

div.chat-detail-screen .bubble-them-custom *,
div.chat-detail-screen .msg-plain-them *,
div.chat-detail-screen .bubble-me-custom *,
div.chat-detail-screen .msg-plain-me * {
  font-size: 13px !important;
  line-height: 1.4 !important;
  text-shadow: none !important;
}

/* --- 1a. 对方气泡：白色 --- */
div.chat-detail-screen .bubble-them-custom,
div.chat-detail-screen .msg-plain-them {
  color: #333333 !important;
  border: 1px solid #efefef !important;
  background: #ffffff !important;
}
div.chat-detail-screen .bubble-them-custom *,
div.chat-detail-screen .msg-plain-them * {
  color: #333333 !important;
}

/* --- 1b. 我方气泡：浅灰 --- */
div.chat-detail-screen .bubble-me-custom,
div.chat-detail-screen .msg-plain-me {
  color: #222222 !important;
  border: 1px solid #f1f1f1 !important;
  background: #f4f4f4 !important;
}
div.chat-detail-screen .bubble-me-custom *,
div.chat-detail-screen .msg-plain-me * {
  color: #222222 !important;
}

/* --- 2. 去掉高光、尾巴、装饰 --- */
div.chat-detail-screen .bubble-them-custom::before,
div.chat-detail-screen .msg-plain-them::before,
div.chat-detail-screen .bubble-me-custom::before,
div.chat-detail-screen .msg-plain-me::before,
div.chat-detail-screen .bubble-them-custom::after,
div.chat-detail-screen .msg-plain-them::after,
div.chat-detail-screen .bubble-me-custom::after,
div.chat-detail-screen .msg-plain-me::after {
  content: none !important;
  display: none !important;
}

.bubble-deco-me::before,
.bubble-deco-me::after,
.bubble-deco-them::before,
.bubble-deco-them::after {
  display: none !important;
}

/* --- 3. 粘连圆角 --- */

/* 对方 - 单条 */
div.chat-detail-screen .msg-them.is-single .bubble-them-custom,
div.chat-detail-screen .msg-them.is-single .msg-plain-them {
  border-radius: 16px 16px 16px 16px !important;
}

/* 对方 - 第一条：左下角小 */
div.chat-detail-screen .msg-them.is-first .bubble-them-custom,
div.chat-detail-screen .msg-them.is-first .msg-plain-them {
  border-radius: 16px 16px 16px 2px !important;
}

/* 对方 - 中间条：左上左下都小 */
div.chat-detail-screen .msg-them.is-mid .bubble-them-custom,
div.chat-detail-screen .msg-them.is-mid .msg-plain-them {
  border-radius: 2px 16px 16px 2px !important;
}

/* 对方 - 最后一条：左上角小 */
div.chat-detail-screen .msg-them.is-last .bubble-them-custom,
div.chat-detail-screen .msg-them.is-last .msg-plain-them {
  border-radius: 2px 16px 16px 16px !important;
}

/* 我方 - 单条 */
div.chat-detail-screen .msg-me.is-single .bubble-me-custom,
div.chat-detail-screen .msg-me.is-single .msg-plain-me {
  border-radius: 16px 16px 16px 16px !important;
}

/* 我方 - 第一条：右下角小 */
div.chat-detail-screen .msg-me.is-first .bubble-me-custom,
div.chat-detail-screen .msg-me.is-first .msg-plain-me {
  border-radius: 16px 16px 2px 16px !important;
}

/* 我方 - 中间条：右上右下都小 */
div.chat-detail-screen .msg-me.is-mid .bubble-me-custom,
div.chat-detail-screen .msg-me.is-mid .msg-plain-me {
  border-radius: 16px 2px 2px 16px !important;
}

/* 我方 - 最后一条：右上角小 */
div.chat-detail-screen .msg-me.is-last .bubble-me-custom,
div.chat-detail-screen .msg-me.is-last .msg-plain-me {
  border-radius: 16px 2px 16px 16px !important;
}

/* --- 4. 间距（兜底：如果不切素淨，用 !important 压过 inline 间距） --- */
div.chat-detail-screen .msg-bubble-wrapper {
  margin-top: 0 !important;
  margin-bottom: 2px !important;
}

div.chat-detail-screen .msg-bubble-wrapper.is-last,
div.chat-detail-screen .msg-bubble-wrapper.is-single {
  margin-bottom: 16px !important;
}

/* --- 5. 头像：只在最后一条/单条显示 --- */

/* 对方头像 */
div.chat-detail-screen .msg-avatar-them-container {
  visibility: hidden !important;
}

div.chat-detail-screen .msg-avatar-them-container.is-last,
div.chat-detail-screen .msg-avatar-them-container.is-single {
  visibility: visible !important;
}

/* 我方头像 */
div.chat-detail-screen .msg-avatar-me-container {
  visibility: hidden !important;
}

div.chat-detail-screen .msg-avatar-me-container.is-last,
div.chat-detail-screen .msg-avatar-me-container.is-single {
  visibility: visible !important;
}

/* --- 5b. 隐藏的头像不占高度，只占宽度 --- */
div.chat-detail-screen .msg-avatar-them-container:not(.is-last):not(.is-single),
div.chat-detail-screen .msg-avatar-me-container:not(.is-last):not(.is-single) {
  height: 0 !important;
  min-height: 0 !important;
  overflow: visible !important;
  align-self: flex-end !important;
}

div.chat-detail-screen .msg-avatar-them-container:not(.is-last):not(.is-single) *,
div.chat-detail-screen .msg-avatar-me-container:not(.is-last):not(.is-single) * {
  height: 0 !important;
  min-height: 0 !important;
}

/* 头像尺寸：36px */
div.chat-detail-screen .msg-avatar-them-container,
div.chat-detail-screen .msg-avatar-me-container {
  width: 36px !important;
  height: 36px !important;
  min-width: 36px !important;
  min-height: 36px !important;
  flex: 0 0 36px !important;
}

/* 头像方圆形 + 填满容器 */
div.chat-detail-screen .msg-avatar-custom,
div.chat-detail-screen .msg-avatar-them-inner,
div.chat-detail-screen .msg-avatar-me-inner,
div.chat-detail-screen .msg-avatar-them-container img,
div.chat-detail-screen .msg-avatar-me-container img {
  width: 36px !important;
  height: 36px !important;
  border-radius: 22% !important;
  overflow: hidden !important;
  object-fit: cover !important;
}

/* --- 5c. 头像灰色描边 --- */
/* 只给显示出来的头像（is-last / is-single）加；用 box-shadow 不占布局，不叠层 */
div.chat-detail-screen .msg-avatar-them-container.is-last,
div.chat-detail-screen .msg-avatar-them-container.is-single,
div.chat-detail-screen .msg-avatar-me-container.is-last,
div.chat-detail-screen .msg-avatar-me-container.is-single {
  border-radius: 22% !important;
  box-shadow: 0 0 0 1px #e0e0e0 !important;
}

/* --- 7. 对方气泡上方用户名（只在第一条/单条显示） --- */
div.chat-detail-screen .msg-them.is-first .bubble-them-custom,
div.chat-detail-screen .msg-them.is-first .msg-plain-them,
div.chat-detail-screen .msg-them.is-single .bubble-them-custom,
div.chat-detail-screen .msg-them.is-single .msg-plain-them {
  margin-top: 20px !important;
}

div.chat-detail-screen .msg-them.is-first .bubble-them-custom::before,
div.chat-detail-screen .msg-them.is-first .msg-plain-them::before,
div.chat-detail-screen .msg-them.is-single .bubble-them-custom::before,
div.chat-detail-screen .msg-them.is-single .msg-plain-them::before {
  content: "구온우" !important;
  display: block !important;
  position: absolute !important;
  top: -18px !important;
  left: 8px !important;
  font-size: 11px !important;
  color: #8C8C8C !important;
  white-space: nowrap !important;
  pointer-events: none !important;
}

/* --- 7b. 非文字消息（表情包 / 图片 / 卡片）不显示用户名 --- */
/* 和【非文字消息去气泡】用同一套判断条件，保证去壳的消息都不带名字 */
div.chat-detail-screen .msg-them:is(.is-first, .is-single) :is(.bubble-them-custom, .msg-plain-them):has(img, video, [class*="card"], [class*="sticker"]):not(:has(.msg-sim-card, .msg-reply-block, .msg-videocall-card))::before {
  content: none !important;
  display: none !important;
}

/* 去掉给名字留的 20px 上边距 */
div.chat-detail-screen .msg-them:is(.is-first, .is-single) :is(.bubble-them-custom, .msg-plain-them):has(img, video, [class*="card"], [class*="sticker"]):not(:has(.msg-sim-card, .msg-reply-block, .msg-videocall-card)) {
  margin-top: 0 !important;
}

/* --- 8. 已读标记：后面出现对方消息时才显示（只在每组最后一条） --- */

/* 结构 A：.msg-me 和 .msg-them 是直接兄弟 */
div.chat-detail-screen .msg-me:is(.is-last, .is-single):has(~ .msg-them, ~ * .msg-them) .bubble-me-custom::after,
div.chat-detail-screen .msg-me:is(.is-last, .is-single):has(~ .msg-them, ~ * .msg-them) .msg-plain-me::after,
/* 结构 B：消息外面包了一层行容器 */
div.chat-detail-screen *:has(~ .msg-them, ~ * .msg-them) .msg-me:is(.is-last, .is-single) .bubble-me-custom::after,
div.chat-detail-screen *:has(~ .msg-them, ~ * .msg-them) .msg-me:is(.is-last, .is-single) .msg-plain-me::after {
  content: "已读" !important;
  display: block !important;
  position: absolute !important;
  bottom: -16px !important;
  right: 8px !important;
  font-size: 10px !important;
  color: #B0B0B0 !important;
  white-space: nowrap !important;
  pointer-events: none !important;
}

/* --- 9. 引用条：挂在气泡上方的灰色胶囊 --- */

/* 9a. 胶囊本体（从气泡里抽出来，绝对定位到气泡上方） */
div.chat-detail-screen :is(.bubble-me-custom, .msg-plain-me, .bubble-them-custom, .msg-plain-them) .msg-reply-block {
  position: absolute !important;
  top: -30px !important;
  bottom: auto !important;
  display: flex !important;
  flex-direction: row !important;
  align-items: center !important;
  gap: 4px !important;
  width: max-content !important;
  max-width: 200px !important;
  height: 26px !important;
  margin: 0 !important;
  padding: 0 10px !important;
  background: #F5F5F5 !important;
  border: none !important;
  border-left: none !important;
  border-radius: 16px !important;
  box-shadow: none !important;
  transform: none !important;
  clip-path: none !important;
  opacity: 1 !important;
  overflow: visible !important;
  box-sizing: border-box !important;
  z-index: 2 !important;
}

/* 我方靠右，对方靠左 */
div.chat-detail-screen :is(.bubble-me-custom, .msg-plain-me) .msg-reply-block {
  right: 10px !important;
  left: auto !important;
}
div.chat-detail-screen :is(.bubble-them-custom, .msg-plain-them) .msg-reply-block {
  left: 12px !important;
  right: auto !important;
}

/* 9b. 隐藏被引用者名字 */
div.chat-detail-screen :is(.bubble-me-custom, .msg-plain-me, .bubble-them-custom, .msg-plain-them) .msg-reply-block-name {
  display: none !important;
}

/* 9c. 引用文字：11px 灰色单行省略（优先级高于气泡的 * 通配规则） */
div.chat-detail-screen :is(.bubble-me-custom, .msg-plain-me, .bubble-them-custom, .msg-plain-them) .msg-reply-block-text,
div.chat-detail-screen :is(.bubble-me-custom, .msg-plain-me, .bubble-them-custom, .msg-plain-them) .msg-reply-block-text *,
div.chat-detail-screen :is(.bubble-me-custom, .msg-plain-me, .bubble-them-custom, .msg-plain-them) .msg-reply-block-media,
div.chat-detail-screen :is(.bubble-me-custom, .msg-plain-me, .bubble-them-custom, .msg-plain-them) .msg-reply-block-media * {
  font-size: 11px !important;
  line-height: 1.2 !important;
  color: #8C8C8C !important;
  border: none !important;
  padding: 0 !important;
  margin: 0 !important;
  background: transparent !important;
}
div.chat-detail-screen :is(.bubble-me-custom, .msg-plain-me, .bubble-them-custom, .msg-plain-them) .msg-reply-block-text {
  display: block !important;
  max-width: 180px !important;
  white-space: nowrap !important;
  overflow: hidden !important;
  text-overflow: ellipsis !important;
}
div.chat-detail-screen :is(.bubble-me-custom, .msg-plain-me) .msg-reply-block-text {
  text-align: right !important;
}
div.chat-detail-screen :is(.bubble-them-custom, .msg-plain-them) .msg-reply-block-text {
  text-align: left !important;
}

/* 9d. 胶囊外侧竖线 */
div.chat-detail-screen :is(.bubble-me-custom, .msg-plain-me, .bubble-them-custom, .msg-plain-them) .msg-reply-block::before {
  content: "" !important;
  display: block !important;
  position: absolute !important;
  top: 50% !important;
  transform: translateY(-50%) !important;
  width: 2px !important;
  height: 20px !important;
  background: #D0D0D0 !important;
  border-radius: 2px !important;
}
div.chat-detail-screen :is(.bubble-me-custom, .msg-plain-me) .msg-reply-block::before {
  right: -7px !important;
  left: auto !important;
}
div.chat-detail-screen :is(.bubble-them-custom, .msg-plain-them) .msg-reply-block::before {
  left: -7px !important;
  right: auto !important;
}

/* 9e. 胶囊上方小字「你回复了 / 回复了你」 */
div.chat-detail-screen :is(.bubble-me-custom, .msg-plain-me, .bubble-them-custom, .msg-plain-them) .msg-reply-block::after {
  display: block !important;
  position: absolute !important;
  top: -17px !important;
  font-size: 11px !important;
  color: #999999 !important;
  white-space: nowrap !important;
  pointer-events: none !important;
}
div.chat-detail-screen :is(.bubble-me-custom, .msg-plain-me) .msg-reply-block::after {
  content: "你回复了" !important;
  right: 2px !important;
  left: auto !important;
}
div.chat-detail-screen :is(.bubble-them-custom, .msg-plain-them) .msg-reply-block::after {
  content: "回复了你" !important;
  left: 2px !important;
  right: auto !important;
}

/* 9f. 带引用的行：上方留出胶囊 + 小字的空间 */
div.chat-detail-screen .msg-bubble-wrapper:has(.msg-reply-block) {
  margin-top: 48px !important;
}

/* 9g. 对方带引用时：隐藏「구온우」名字，取消名字占的上边距 */
div.chat-detail-screen .msg-them:is(.is-first, .is-single) :is(.bubble-them-custom, .msg-plain-them):has(.msg-reply-block)::before {
  content: none !important;
  display: none !important;
}
div.chat-detail-screen .msg-them:is(.is-first, .is-single) :is(.bubble-them-custom, .msg-plain-them):has(.msg-reply-block) {
  margin-top: 0 !important;
}

/* ◆◆◆◆◆◆◆◆◆◆◆◆ 【03 顶栏】 ◆◆◆◆◆◆◆◆◆◆◆◆ */

/* --- 容器：毛玻璃 + 底部细线 --- */
div.chat-detail-screen .chat-header-custom {
  background: rgba(255, 255, 255, 0.72) !important;
  background-color: rgba(255, 255, 255, 0.72) !important;
  backdrop-filter: blur(20px) saturate(180%) !important;
  -webkit-backdrop-filter: blur(20px) saturate(180%) !important;
  box-shadow: none !important;
  border-bottom: 0.5px solid rgba(0, 0, 0, 0.08) !important;
  position: relative !important;
}

/* 内层实体透明，避免叠两层底色 */
div.chat-detail-screen .chat-header-custom .glass-header {
  background: transparent !important;
  background-color: transparent !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  box-shadow: none !important;
  border: none !important;
}

/* --- 隐藏顶栏头像 --- */
div.chat-detail-screen .header-avatar-container {
  display: none !important;
}

/* --- 标题区：绝对居中，不受左右按钮影响 --- */
div.chat-detail-screen .header-profile-section {
  position: absolute !important;
  left: 50% !important;
  transform: translateX(-50%) !important;
  top: auto !important;
  bottom: 8px !important;
  display: flex !important;
  flex-direction: column !important;
