  pointer-events: none !important;
}

/* ◆◆◆◆◆◆◆◆◆◆◆◆ 【04 底栏】 ◆◆◆◆◆◆◆◆◆◆◆◆ */

/* --- 隐藏原 placeholder，注入自定义 --- */
div.chat-detail-screen .input-box-custom::placeholder {
