}

/* ◆◆◆◆◆◆◆◆◆◆◆◆ 【05 撤回提示】 ◆◆◆◆◆◆◆◆◆◆◆◆ */

/* 行容器：居中，上下留白 */
div.chat-detail-screen .msg-recalled {
  display: flex !important;
  justify-content: center !important;
  margin: 12px 0 !important;
  background: transparent !important;
}

/* 去掉原胶囊样式，隐藏原文字 */
div.chat-detail-screen .msg-recalled .msg-system {
  font-size: 0 !important;
  color: transparent !important;
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  padding: 0 !important;
  margin: 0 !important;
}
div.chat-detail-screen .msg-recalled .msg-system * {
  display: none !important;
}
div.chat-detail-screen .msg-recalled .msg-system::before {
  content: none !important;
  display: none !important;
}

/* 统一文字：双方一样 */
div.chat-detail-screen .msg-recalled .msg-system::after {
  content: "撤回了一条消息" !important;
  display: block !important;
  font-size: 12px !important;
  font-style: normal !important;
  font-weight: 400 !important;
  line-height: 1.4 !important;
  color: #9A9A9A !important;
  text-align: center !important;
  white-space: nowrap !important;
}

/* ◆◆◆◆◆◆◆◆◆◆◆◆ 【06 翻译 · 字幕条】 ◆◆◆◆◆◆◆◆◆◆◆◆ */
/* ═══════════════════════════════════════════════
   深灰底白字字幕条，压在气泡底边
   - 用气泡外独立翻译块 .msg-translation-detached（占位，长句会推开下一条）
   - 宽度跟文字走，上限 240px，超过才换行
   - 多行时每行各自一段底色
   - 永远展开的开关见 00b
   ═══════════════════════════════════════════════ */

/* 1. 藏掉气泡内的原翻译块和按钮 */
div.chat-detail-screen .msg-translation-wrapper {
  display: none !important;
}

/* 2. 气泡外独立翻译块：往上提，压在气泡底边 */
div.chat-detail-screen .msg-translation-detached {
  display: block !important;
  position: relative !important;
  z-index: 3 !important;              /* 盖在气泡（z-index:1）上面 */
  width: max-content !important;      /* 按文字长度，不被气泡宽度压缩 */
  min-width: 0 !important;
  max-width: 240px !important;        /* 固定上限，超过才换行 */
  margin-top: -11px !important;       /* 上提高度，越大压得越多 */
  margin-bottom: 0 !important;
  padding: 0 !important;
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  font-size: 11px !important;
  line-height: 1.65 !important;       /* 多行时两行深灰条的间距 */
  box-sizing: border-box !important;
}
div.chat-detail-screen .msg-translation-detached::before,
div.chat-detail-screen .msg-translation-detached::after {
  content: none !important;
  display: none !important;
}

/* 对方：靠左，用 transform 平移（不受 App 的 margin 规则影响） */
div.chat-detail-screen .msg-translation-detached-them {
  align-self: flex-start !important;
  transform: translateX(10px) !important;  /* 负数往左，正数往右 */
}

/* 我方：靠右，往里缩 */
div.chat-detail-screen .msg-translation-detached-me {
  align-self: flex-end !important;
  margin-right: 18px !important;      /* 越大越靠左 */
  margin-left: 0 !important;
}

/* 3. 字幕条本体：深灰底白字，按行断开 */
div.chat-detail-screen .msg-translation-detached-content {
  display: inline !important;         /* inline + clone = 每行各自一段底色 */
  -webkit-box-decoration-break: clone !important;
  box-decoration-break: clone !important;
  background: #333333 !important;
  color: #FFFFFF !important;
  font-size: 11px !important;
  font-weight: 500 !important;
  line-height: 1.65 !important;
  padding: 1px 5px !important;
  margin: 0 !important;
  border: none !important;
  border-radius: 2px !important;
  box-shadow: none !important;
  min-width: 0 !important;
  white-space: normal !important;
  word-break: break-word !important;
  text-shadow: none !important;
}
div.chat-detail-screen .msg-translation-detached-content * {
  display: inline !important;
  color: #FFFFFF !important;
  font-size: 11px !important;
  background: transparent !important;
  margin: 0 !important;
  padding: 0 !important;
  text-shadow: none !important;
}

/* 去掉对勾、小字、图标等装饰 */
div.chat-detail-screen .msg-translation-detached-content::before,
div.chat-detail-screen .msg-translation-detached-content::after,
div.chat-detail-screen .msg-translation-detached :is(svg, img) {
  content: none !important;
  display: none !important;
}

/* 4. 带翻译的气泡：底部多留一点，字幕条不挡原文 */
div.chat-detail-screen .msg-bubble-wrapper:has(.msg-translation-detached) :is(.bubble-me-custom, .msg-plain-me, .bubble-them-custom, .msg-plain-them) {
  padding-bottom: 9px !important;
}

/* 5. 同组内，带翻译的这条和下一条拉开距离（组末尾本来有 16px，不动） */
div.chat-detail-screen .msg-bubble-wrapper:has(.msg-translation-detached):not(.is-last):not(.is-single) {
  margin-bottom: 8px !important;
}

/* ◆◆◆◆◆◆◆◆◆◆◆◆ 【07 非文字消息去气泡】 ◆◆◆◆◆◆◆◆◆◆◆◆ */
/* ═══════════════════════════════════════════════
   气泡里有图片、视频、任何 *card* / *sticker* 元素 → 去掉气泡壳
   覆盖：表情包、真实图片、视频、转账、红包、名片、歌曲、闹钟、
         外卖、订单、文件、地图、明信片、分享卡、MCP 工具卡等
   排除：
     - 文字长图卡 .msg-sim-card
     - 带引用的消息 .msg-reply-block（引用胶囊挂在气泡上，去壳会错位）
     - 通话记录卡 .msg-videocall-card（保留气泡）
   不动伪元素：对方首条的「구온우」名字靠气泡 ::before
   尺寸变量见 00a
   ═══════════════════════════════════════════════ */

/* --- 1. 去掉气泡壳（底色、描边、内边距） --- */
div.chat-detail-screen :is(.bubble-me-custom, .msg-plain-me, .bubble-them-custom, .msg-plain-them):has(img, video, [class*="card"], [class*="sticker"]):not(:has(.msg-sim-card, .msg-reply-block, .msg-videocall-card)) {
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  padding: 0 !important;
  overflow: visible !important;
}

/* --- 2. 表情包缩小 --- */
div.chat-detail-screen [class*="sticker"] img,
div.chat-detail-screen img[class*="sticker"] {
  width: var(--sticker-size) !important;
  height: var(--sticker-size) !important;
  max-width: var(--sticker-size) !important;
  max-height: var(--sticker-size) !important;
