  max-height: 20px !important;
  margin: 0 !important;
  padding: 0 !important;
  object-fit: cover !important;
  border-radius: 4px !important;
  box-shadow: none !important;
  transform: none !important;
}

/* 缩略图里的其他层（卡片外框、播放图标等）不再撑大 */
div.chat-detail-screen .msg-bubble-wrapper .msg-reply-block.msg-reply-block .msg-reply-block-media * {
  max-width: 20px !important;
  max-height: 20px !important;
  margin: 0 !important;
  padding: 0 !important;
}

/* ◆◆◆◆◆◆◆◆◆◆◆◆ 【09 语音气泡】 ◆◆◆◆◆◆◆◆◆◆◆◆ */
/* 只留：播放键 + 波形 + 时长；气泡同文字气泡色；变量见 00c */

/* --- 1. 气泡壳：和文字气泡同色 --- */
div.chat-detail-screen .msg-bubble-wrapper :is(.bubble-me-custom, .msg-plain-me):has(.voice-msg.voice-msg) {
