}

/* ◆◆◆◆◆◆◆◆◆◆◆◆ 【11 转账卡】 ◆◆◆◆◆◆◆◆◆◆◆◆ */
/* 左：标题 + 金额 + 备注；右下：状态按钮；直角；排除红包 */

/* --- 1. 卡片本体 --- */
div.chat-detail-screen .msg-transfer-card:not(.msg-redpacket-card) {
  display: flex !important;
  flex-direction: column !important;
  align-items: flex-start !important;
  justify-content: center !important;
  gap: 2px !important;
  position: relative !important;
  width: min(236px, 66vw) !important;      /* ← 卡片宽度，窄屏自动收 */
  min-width: 0 !important;
  max-width: min(236px, 66vw) !important;
  height: auto !important;
  min-height: 0 !important;
  margin: 0 !important;
  padding: 10px 14px !important;
  background: #FFFFFF !important;
  background-image: none !important;
  border: 1px solid #E5E5E5 !important;
  border-radius: 0 !important;            /* 直角；想略圆改 4px */
  box-shadow: none !important;
  -webkit-backdrop-filter: none !important;
  backdrop-filter: none !important;
  box-sizing: border-box !important;
  overflow: visible !important;
}

/* 内部容器：去底色，竖排靠左 */
div.chat-detail-screen .msg-transfer-card:not(.msg-redpacket-card) * {
  background: transparent !important;
  box-shadow: none !important;
  text-shadow: none !important;
}
div.chat-detail-screen .msg-transfer-card:not(.msg-redpacket-card) > * {
  display: flex !important;
  flex-direction: column !important;
  align-items: flex-start !important;
  gap: 2px !important;
  width: 100% !important;
  min-width: 0 !important;
  margin: 0 !important;
  padding: 0 !important;
  border: none !important;
}

/* --- 2. 小标题 --- */
div.chat-detail-screen .msg-transfer-card:not(.msg-redpacket-card)::before {
  content: "已申请付款" !important;
  display: block !important;
  position: static !important;
  width: auto !important;
  height: auto !important;
  margin: 0 0 2px !important;
  font-size: 12px !important;
  font-weight: 500 !important;
  line-height: 1.3 !important;
  color: #8E8E93 !important;
  background: none !important;
  transform: none !important;
}

/* --- 3. 隐藏原图标、原标题、状态文字、分隔线、对勾、箭头 --- */
div.chat-detail-screen .msg-transfer-card:not(.msg-redpacket-card) :is(
  .msg-transfer-icon,
  .msg-transfer-label,
  .msg-transfer-status-text,
  .msg-transfer-divider,
  .msg-transfer-check,
  .msg-transfer-chevron,
