  font-size: 12px !important;
  color: #8E8E93 !important;
  -webkit-text-fill-color: #8E8E93 !important;
}

/* 没单独写样式的文字（比如「23小时后过期」）：灰色小字，行高和按钮一样，方便对齐 */
div.chat-detail-screen .msg-transfer-card:not(.msg-redpacket-card) *:not(.msg-transfer-amount):not(.msg-transfer-amount *) {
