/* ═══════════════════════════════════════════════
   4 张牌扇形展开（以底边中点为轴）：
   L1 卡片 ::before        最前，接近正
   L2 卡片 ::after         往左倒（最大）
   L3 外层气泡 ::before    往右倒（不依赖 .msg-sim-divider）
   L4 .msg-sim-date::before 往左倒一点
   左下角浅灰胶囊「点击查看」
   图片、尺寸、角度变量见 00d
   ═══════════════════════════════════════════════ */

/* --- 1. 外层气泡去壳 --- */
div.chat-detail-screen :is(.bubble-me-custom, .msg-plain-me, .bubble-them-custom, .msg-plain-them):has(.msg-sim-card) {
  position: relative !important;
  z-index: 1 !important;
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  padding: 0 !important;
  overflow: visible !important;
  border-radius: 0 !important;
}

/* --- 2. 左下角浅灰胶囊「点击查看」 --- */
div.chat-detail-screen :is(.bubble-me-custom, .msg-plain-me, .bubble-them-custom, .msg-plain-them):has(.msg-sim-card)::after {
  content: "点击查看" !important;
  display: block !important;
  position: absolute !important;
  top: auto !important;
  right: auto !important;
  left: 30px !important;
  bottom: 4px !important;
  height: 24px !important;
  padding: 0 12px !important;
  margin: 0 !important;
  background: #EFEFEF !important;
  border: none !important;
  border-radius: 999px !important;
  box-shadow: none !important;
  font-size: 11px !important;
  font-weight: 400 !important;
  line-height: 24px !important;
  color: #8C8C8C !important;
  white-space: nowrap !important;
  transform: none !important;
  pointer-events: none !important;
  z-index: 5 !important;
}

/* 已读时：「已读」并进胶囊，不再撑长 */
/* 选择器沿用气泡第 8 段的已读结构，再加 :has(.msg-sim-card)，优先级更高 */
/* 结构 A */
div.chat-detail-screen .msg-me:is(.is-last, .is-single):has(~ .msg-them, ~ * .msg-them) .bubble-me-custom:has(.msg-sim-card)::after,
div.chat-detail-screen .msg-me:is(.is-last, .is-single):has(~ .msg-them, ~ * .msg-them) .msg-plain-me:has(.msg-sim-card)::after,
/* 结构 B */
div.chat-detail-screen *:has(~ .msg-them, ~ * .msg-them) .msg-me:is(.is-last, .is-single) .bubble-me-custom:has(.msg-sim-card)::after,
div.chat-detail-screen *:has(~ .msg-them, ~ * .msg-them) .msg-me:is(.is-last, .is-single) .msg-plain-me:has(.msg-sim-card)::after {
  content: "点击查看 · 已读" !important;
  top: auto !important;
  right: auto !important;          /* 取消已读规则的 right，胶囊不再被拉长 */
  left: 12px !important;
  bottom: 4px !important;
  height: 24px !important;
  padding: 0 12px !important;
  background: #EFEFEF !important;
  border-radius: 999px !important;
  font-size: 11px !important;
  line-height: 24px !important;
  color: #8C8C8C !important;
}

/* --- 3. 牌堆容器：加宽，给扇形留位 --- */
div.chat-detail-screen .msg-sim-card {
  position: relative !important;
  isolation: isolate !important;
  width: 236px !important;
  height: 210px !important;
  margin: 10px 10px 36px !important;   /* 底部 36px 给胶囊 */
  padding: 0 !important;
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  overflow: visible !important;
}

/* 子元素：保留元素本身（L4 挂在上面），只藏文字；不换行、不溢出，不再撑高滚动区 */
div.chat-detail-screen .msg-sim-card > * {
  display: block !important;
  position: static !important;
  width: 0 !important;
  height: 0 !important;
  min-height: 0 !important;
  max-height: 0 !important;
  margin: 0 !important;
  padding: 0 !important;
  border: none !important;
  background: transparent !important;
  box-shadow: none !important;
  font-size: 0 !important;
  line-height: 0 !important;
  color: transparent !important;
  -webkit-text-fill-color: transparent !important;
  opacity: 1 !important;
  transform: none !important;
  filter: none !important;
  z-index: auto !important;
  white-space: nowrap !important;
  overflow: hidden !important;     /* 不影响挂在上面的牌：牌是相对卡片定位的 */
}

/* 孙级元素（原文、日期文字等）直接不渲染 */
div.chat-detail-screen .msg-sim-card > * > * {
  visibility: hidden !important;
  display: none !important;
}

/* 除 L4 外，子元素的伪元素全部清掉（包括 divider，避免重复出牌） */
div.chat-detail-screen .msg-sim-card > .msg-sim-date::after,
div.chat-detail-screen .msg-sim-card > :not(.msg-sim-date)::before,
div.chat-detail-screen .msg-sim-card > :not(.msg-sim-date)::after {
  content: none !important;
  display: none !important;
}

/* --- 4. 4 张牌的公共样式 --- */
div.chat-detail-screen .msg-sim-card::before,
div.chat-detail-screen .msg-sim-card::after,
div.chat-detail-screen .msg-sim-card > .msg-sim-date::before,
div.chat-detail-screen .msg-bubble-wrapper.msg-bubble-wrapper :is(.bubble-me-custom, .msg-plain-me, .bubble-them-custom, .msg-plain-them):has(.msg-sim-card)::before {
  content: "" !important;
  display: block !important;
  position: absolute !important;
  right: auto !important;
  bottom: auto !important;
  width: var(--sim-w) !important;
  height: var(--sim-h) !important;
  margin: 0 !important;
  padding: 0 !important;
  border: var(--sim-border) !important;
  border-radius: var(--sim-radius) !important;
  box-shadow: var(--sim-shadow) !important;
  background-color: #FFFFFF !important;
  background-position: center !important;
  background-size: cover !important;
  background-repeat: no-repeat !important;
  transform-origin: center bottom !important;   /* 以底边中点为轴展开 */
  opacity: 1 !important;
  visibility: visible !important;
  pointer-events: none !important;
  font-size: 0 !important;
}

/* L1：最前，接近正 */
div.chat-detail-screen .msg-sim-card::before {
  top: 12px !important;
  left: 62px !important;
  z-index: 4 !important;
  background-image: var(--sim-l1) !important;
  transform: rotate(var(--sim-rot-1)) !important;
}

/* L2：往左倒（最大） */
div.chat-detail-screen .msg-sim-card::after {
  top: 14px !important;
  left: 48px !important;
  z-index: 3 !important;
  background-image: var(--sim-l2) !important;
  transform: rotate(var(--sim-rot-2)) !important;
}

/* L4：往左倒一点 */
div.chat-detail-screen .msg-sim-card > .msg-sim-date::before {
  top: 8px !important;
  left: 54px !important;
  z-index: 2 !important;
  background-image: var(--sim-l4) !important;
  transform: rotate(var(--sim-rot-4)) !important;
}

/* L3：往右倒，挂在外层气泡上（坐标 = 卡片 margin 10px + 牌位） */
div.chat-detail-screen .msg-bubble-wrapper.msg-bubble-wrapper :is(.bubble-me-custom, .msg-plain-me, .bubble-them-custom, .msg-plain-them):has(.msg-sim-card)::before {
  top: 22px !important;    /* 10 + 12 */
  left: 82px !important;   /* 10 + 72 */
  z-index: -1 !important;  /* 压在整个牌堆最底下，只露出右侧 */
  background-image: var(--sim-l3) !important;
  transform: rotate(var(--sim-rot-3)) !important;
}

/* ◆◆◆◆◆◆◆◆◆◆◆◆ 【16 文件卡】 ◆◆◆◆◆◆◆◆◆◆◆◆ */
/* ===== 文件卡：微信风；变量见 00d ===== */

/* 1. 外层气泡去壳 */
div.chat-detail-screen :is(.bubble-me-custom, .msg-plain-me, .bubble-them-custom, .msg-plain-them):has(.msg-file-card) {
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  padding: 0 !important;
  overflow: visible !important;
}
div.chat-detail-screen :is(.bubble-me-custom, .msg-plain-me, .bubble-them-custom, .msg-plain-them):has(.msg-file-card)::before,
div.chat-detail-screen :is(.bubble-me-custom, .msg-plain-me, .bubble-them-custom, .msg-plain-them):has(.msg-file-card)::after {
  display: none !important;
}

/* 2. 卡片本体：左文字、右图标 */
div.chat-detail-screen .msg-file-card {
  display: flex !important;
  flex-direction: row !important;
  align-items: center !important;
  gap: 10px !important;
  box-sizing: border-box !important;
  width: var(--file-w) !important;
  min-width: var(--file-w) !important;
  max-width: var(--file-w) !important;
  height: var(--file-h) !important;
  min-height: 0 !important;
  margin: 0 !important;
  padding: 0 17px 0 14px !important;
  border: none !important;
  border-radius: var(--file-radius) !important;
  background: #FFFFFF !important;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.08) !important;
  overflow: hidden !important;
  -webkit-backdrop-filter: none !important;
  backdrop-filter: none !important;
  transform: none !important;
  animation: none !important;
  cursor: pointer;
}
div.chat-detail-screen .msg-file-card::before,
div.chat-detail-screen .msg-file-card::after {
  display: none !important;
}

/* 3. 文字区：在左边 */
div.chat-detail-screen .msg-file-card .msg-file-body {
  order: 1 !important;
  flex: 1 1 auto !important;
  min-width: 0 !important;
  display: flex !important;
  flex-direction: column !important;
  justify-content: center !important;
  gap: 5px !important;
  margin: 0 !important;
  padding: 0 !important;
  background: none !important;
  border: none !important;
}

/* 文件名：粗体单行 */
div.chat-detail-screen .msg-file-card .msg-file-name {
  display: flex !important;
  min-width: 0 !important;
  max-width: 100% !important;
  margin: 0 !important;
  padding: 0 !important;
  overflow: hidden !important;
  white-space: nowrap !important;
}
div.chat-detail-screen .msg-file-card .msg-file-name,
div.chat-detail-screen .msg-file-card .msg-file-name * {
  color: var(--file-name-color) !important;
  font-size: 15px !important;
  font-weight: 600 !important;
  line-height: 1.3 !important;
  text-shadow: none !important;
  -webkit-font-smoothing: antialiased !important;
}
div.chat-detail-screen .msg-file-card .msg-file-name-stem {
  min-width: 0 !important;
  overflow: hidden !important;
  text-overflow: ellipsis !important;
  white-space: nowrap !important;
}
div.chat-detail-screen .msg-file-card .msg-file-name-tail {
  flex: none !important;
  white-space: nowrap !important;
}

/* 大小一行 */
div.chat-detail-screen .msg-file-card .msg-file-meta {
  display: flex !important;
  flex-direction: row-reverse !important;
  flex-wrap: wrap !important;
  justify-content: flex-end !important;
  align-items: center !important;
  height: 15px !important;
  overflow: hidden !important;
  margin: 0 !important;
  padding: 0 !important;
  white-space: nowrap !important;
}
div.chat-detail-screen .msg-file-card .msg-file-meta,
div.chat-detail-screen .msg-file-card .msg-file-meta * {
  color: var(--file-meta-color) !important;
  font-size: 11px !important;
  font-weight: 600 !important;
  line-height: 15px !important;
  text-shadow: none !important;
  -webkit-font-smoothing: antialiased !important;
}
div.chat-detail-screen .msg-file-card .msg-file-meta .msg-file-dot {
  flex: 0 0 100% !important;
  height: 15px !important;
  visibility: hidden !important;
}
div.chat-detail-screen .msg-file-card .msg-file-meta::after {
  content: var(--file-status-them) !important;
  order: -1 !important;
  display: block !important;
  white-space: pre !important;
  color: var(--file-meta-color) !important;
  font-size: 11px !important;
  font-weight: 600 !important;
  line-height: 15px !important;
}
div.chat-detail-screen .msg-file-card.is-me .msg-file-meta::after {
  content: var(--file-status-me) !important;
}

/* 「AI 生成」标签和内容预览隐藏 */
div.chat-detail-screen .msg-file-card :is(.msg-file-tag, .msg-file-preview) {
  display: none !important;
}

/* 4. 图标：原生换成图片 */
div.chat-detail-screen .msg-file-card .msg-file-icon {
  order: 2 !important;
  flex: none !important;
  position: relative !important;
  display: block !important;
  width: var(--file-icon-w) !important;
  height: var(--file-icon-h) !important;
  min-width: 0 !important;
  margin: 0 !important;
  padding: 0 !important;
  border: none !important;
  border-radius: 0 !important;
  background: var(--file-icon-img) center / contain no-repeat !important;
  -webkit-mask: none !important;
  mask: none !important;
  box-shadow: none !important;
  color: transparent !important;
  font-size: 0 !important;
  overflow: hidden !important;
}
div.chat-detail-screen .msg-file-card .msg-file-icon > *,
div.chat-detail-screen .msg-file-card .msg-file-icon::before,
div.chat-detail-screen .msg-file-card .msg-file-icon::after,
div.chat-detail-screen .msg-file-card .msg-file-ext {
  display: none !important;
}

/* ◆◆◆◆◆◆◆◆◆◆◆◆ 【夜间块】 ◆◆◆◆◆◆◆◆◆◆◆◆ */
/* ═══════════════════════════════════════════════
   夜间版：直接贴在主体 CSS 末尾
   自动版：包进 @media (prefers-color-scheme: dark) { } 再贴
   背景 #080D11
   对方：#000000 描边 #2F2F2F 文字 #FEFEFE
   我方：#373737 无描边   文字 #FEFEFE
   卡片：#111417 描边 #2F2F2F
   顶栏 / 底栏图标：#F9F9F9
