  --input-caret-color: #FEFEFE;
}

:root,
div.chat-detail-screen {
  --bubble-me-color: #FEFEFE !important;
  --bubble-them-color: #FEFEFE !important;
}

:root,
div.chat-detail-screen,
div.chat-detail-screen .voice-msg {
  --voice-me-color: #FEFEFE;
  --voice-them-color: #FEFEFE;
}

div.chat-detail-screen {
  /* 正在回复胶囊 */
  --reply-bar-bg: #1C1F22;
