  --contact-card-border: 1px solid #2F2F2F;
  --contact-card-shadow: none;
  --contact-card-foot: #8A8A8A;

  /* 文字长图 */
  --sim-border: 1px solid rgba(255, 255, 255, 0.08);
  --sim-shadow: 0 2px 8px rgba(0, 0, 0, 0.5);

  /* 文件卡 */
  --file-name-color: #FEFEFE;
  --file-meta-color: #8A8A8A;
}

div.chat-detail-screen .nuo-chat-header-unread-num {
  --chat-header-unread-num-bg: #2A2D30;
  --chat-header-unread-num-color: #CFCFCF;
}

div.chat-detail-screen .msg-redpacket-card {
  --redpacket-bg: #111417;
  --redpacket-color: #CFCFCF;
  --redpacket-opened-bg: #111417;
  --redpacket-opened-color: #CFCFCF;
}

/* --- N1. 聊天背景 --- */
div.chat-detail-screen,
div.chat-detail-screen .chat-messages-area {
  background: #080D11 !important;
  background-image: none !important;
}

/* --- N2. 气泡 --- */
div.chat-detail-screen .bubble-them-custom,
