/* 已读 */
div.chat-detail-screen .msg-me:is(.is-last, .is-single):has(~ .msg-them, ~ * .msg-them) .bubble-me-custom::after,
div.chat-detail-screen .msg-me:is(.is-last, .is-single):has(~ .msg-them, ~ * .msg-them) .msg-plain-me::after,
