  -webkit-mask-image: linear-gradient(
    to top,
    rgba(0, 0, 0, 0.85) 0%,
    rgba(0, 0, 0, 0.60) 35%,
    rgba(0, 0, 0, 0.20) 65%,
    transparent 90%
  ) !important;
  mask-image: linear-gradient(
    to top,
    rgba(0, 0, 0, 0.85) 0%,
