}

/* ---------- 引用回复 ---------- */
.msg-reply-block-detached { color: var(--light-ink) !important; }
.msg-them .msg-reply-block-detached { color: #fff !important; }   /* 蓝色引用条保持白字 */
.msg-reply-detached-name { filter: invert(1); opacity: 0.55; }    /* 弧线：白色反成深色 */
.msg-bubble-wrapper:has(.msg-reply-block-detached)::after { filter: invert(1); opacity: 0.55; }

/* ---------- 图片 ---------- */
.chat-detail-screen .msg-bubble-wrapper .msg-image-wrapper {
  box-shadow: 0 0 0 1px rgba(0, 0, 0, 0.10) !important;
}

/* ---------- 打字气泡 ---------- */
.nuo-typing-indicator { --typing-dot-color: rgba(60, 60, 67, 0.55); }
.nuo-typing-bubble::after { filter: invert(1); opacity: 0.45; }

/* ---------- 转账卡片：对方那张改成偏深的灰，保证白字看得清 ---------- */
.msg-them .msg-transfer-card {
  background: linear-gradient(180deg,
    rgba(110, 110, 118, 0.62) 0%, rgba(90, 90, 98, 0.52) 50%, rgba(70, 70, 78, 0.46) 100%) !important;
}

/* ---------- 长按菜单 ---------- */
.chat-detail-screen .ig-context-menu,
.chat-detail-screen .reaction-bar {
  background: rgba(255, 255, 255, 0.72) !important;
  border: 0.5px solid rgba(0, 0, 0, 0.08) !important;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.9), 0 12px 36px rgba(0, 0, 0, 0.16) !important;
}
.chat-detail-screen .ig-menu-item {
  color: var(--light-ink) !important;
  border-bottom-color: rgba(0, 0, 0, 0.08) !important;
}
.chat-detail-screen .ig-menu-item svg {
  color: var(--light-ink) !important;
  stroke: var(--light-ink) !important;
}
.chat-detail-screen .ig-menu-item:hover,
.chat-detail-screen .ig-menu-item:active { background: rgba(0, 0, 0, 0.06) !important; }

/* == 文字图 == */

/* 1. 文字长图 / 模拟截图卡片外壳尺寸约束 */
.chat-detail-screen .msg-sim-card {
  max-width: 120px !important;         /* 最大宽度限制，避免撑爆横向屏幕 */
  max-height: 200px !important;        /* 最大高度限制，超长图不占满屏 */
  width: auto !important;
  border-radius: 18px !important;      /* 对齐 iMessage 气泡 18px 圆角 */
  overflow: hidden !important;         /* 超出范围平滑裁切 */
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.25) !important;
  box-sizing: border-box !important;
}

/* 2. 文字图内部渲染的图片 (img)：比例自适应与自洽填充 */
.chat-detail-screen .msg-sim-card img {
  max-width: 100% !important;
  max-height: 200px !important;
  width: 100% !important;
  height: auto !important;
  object-fit: cover !important;        /* 顶部对齐裁剪展示精华部分 */
  object-position: top center !important;
  border-radius: inherit !important;
  display: block !important;
}

/* 3. 如果文字图是由 HTML 文本/代码块生成的模拟长图，允许其内部优雅截断 */
.chat-detail-screen .msg-sim-card [class*="content"],
.chat-detail-screen .msg-sim-card [class*="body"] {
  max-height: 200px !important;
  overflow: hidden !important;
}

/* 文字图背景 */
.msg-sim-card {
  background-color: #1c1c1e !important;   /* 图没加载出来时的底色 */
  background-image: url("https://i.ibb.co/0yxF8yL8/IMG-3819.jpg") !important;
  background-size: cover !important;       /* 铺满，不拉伸 */
  background-position: center !important;
  background-repeat: no-repeat !important;
}

/* 文字图：平时只显示背景图，点击才显示里面的内容 */
.msg-sim-card {
  cursor: pointer !important;                 /* 让苹果的浏览器把轻点当成「悬停」 */
  -webkit-tap-highlight-color: transparent;
  transition: box-shadow 0.25s ease;
}

/* 卡片里所有内容默认隐藏（只是变透明，卡片大小不变） */
.msg-sim-card > * {
  opacity: 0 !important;
  transition: opacity 0.25s ease !important;
}

/* 点击 / 按住 / 内部获得焦点时显示 */
.msg-sim-card:hover > *,
.msg-sim-card:active > *,
.msg-sim-card:focus-within > * {
  opacity: 1 !important;
}

/* 显示内容时给背景图盖一层暗色，保证字看得清；不想要就删掉这段，或把 0.35 调小 */
.msg-sim-card:hover,
.msg-sim-card:active,
.msg-sim-card:focus-within {
  box-shadow: inset 0 0 0 100vmax rgba(0, 0, 0, 0.35) !important;
}

/* 底栏内容整体上移，背景层不动 */
:root { --bar-lift: 14px; }   /* 上移多少，越大越高 */

.chat-detail-screen:not(:has([class*="checkbox"])) .input-row-wrapper {
  position: relative !important;
  top: calc(var(--bar-lift) * -1) !important;
}

/* 内容抬高了，消息区底部留白同步加上，最后一条消息不会被挡住 */
.chat-detail-screen .chat-messages-area {
  padding-bottom: calc(var(--input-area-min-height, 56px) + env(safe-area-inset-bottom, 44px) + 79px + var(--bar-lift)) !important;
}

/*⁣‌⁠⁠​⁠⁠⁠‌‍‍​​​⁠‍⁠‌‌​‍‍‍‌‌​‌⁠‍⁠⁠‍‌​⁠⁠‍⁠‌‍‌‍⁠​⁠⁠⁠⁠‍​⁠‍‍​​‌‍⁠‌⁠‍​​‌‍⁣ ==  顶栏 == */

/* 1. 消息区域留出顶部空间 */
.chat-detail-screen > .chat-messages-area {
  padding-top: calc(var(--chat-header-height, 56px) + env(safe-area-inset-top, 20px) + 24px) !important;
}

/* 2. 主界面 Header 容器保持通透 */
.chat-detail-screen > .chat-header-custom,
.chat-detail-screen > .glass-header {
  position: absolute !important;
  top: 0 !important;
  left: 0 !important;
  right: 0 !important;
  z-index: 20 !important;
  background: transparent !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  border: none !important;
  box-shadow: none !important;
}

/* 3. 核心：10 级 Smoothstep 缓动渐变（彻底抹平分界线，如空气般无缝过渡） */
.chat-detail-screen > .chat-header-custom::before {
  content: "" !important;
  position: absolute !important;
  top: 0 !important;
  left: 0 !important;
  right: 0 !important;
  height: calc(100% + 14px) !important;
  z-index: -1 !important;
  pointer-events: none !important;

  /* 黑色底色：高阶平滑自然光衰减 */
  background: linear-gradient(
    to bottom,
    rgba(0, 0, 0, 0.86) 0%,
    rgba(0, 0, 0, 0.86) 28%,
    rgba(0, 0, 0, 0.82) 36%,
    rgba(0, 0, 0, 0.75) 44%,
    rgba(0, 0, 0, 0.65) 52%,
    rgba(0, 0, 0, 0.52) 60%,
    rgba(0, 0, 0, 0.38) 68%,
    rgba(0, 0, 0, 0.24) 76%,
    rgba(0, 0, 0, 0.12) 84%,
    rgba(0, 0, 0, 0.03) 92%,
    transparent 100%
  ) !important;

  /* 深色高透光学磨砂 */
  backdrop-filter: blur(25px) saturate(150%) !important;
  -webkit-backdrop-filter: blur(25px) saturate(150%) !important;

  /* 遮罩：与背景完全同步的 10 级无痕柔化遮罩 */
  -webkit-mask-image: linear-gradient(
    to bottom,
    rgba(0, 0, 0, 1) 0%,
    rgba(0, 0, 0, 1) 28%,
    rgba(0, 0, 0, 0.96) 36%,
    rgba(0, 0, 0, 0.88) 44%,
    rgba(0, 0, 0, 0.76) 52%,
    rgba(0, 0, 0, 0.60) 60%,
    rgba(0, 0, 0, 0.44) 68%,
    rgba(0, 0, 0, 0.28) 76%,
    rgba(0, 0, 0, 0.14) 84%,
    rgba(0, 0, 0, 0.04) 92%,
    transparent 100%
  ) !important;
  mask-image: linear-gradient(
    to bottom,
    rgba(0, 0, 0, 1) 0%,
    rgba(0, 0, 0, 1) 28%,
    rgba(0, 0, 0, 0.96) 36%,
    rgba(0, 0, 0, 0.88) 44%,
    rgba(0, 0, 0, 0.76) 52%,
    rgba(0, 0, 0, 0.60) 60%,
    rgba(0, 0, 0, 0.44) 68%,
    rgba(0, 0, 0, 0.28) 76%,
    rgba(0, 0, 0, 0.14) 84%,
    rgba(0, 0, 0, 0.04) 92%,
    transparent 100%
  ) !important;
}

/* 4. 安全保护设置界面 */
[class*="setting"] .chat-header-custom,
[class*="modal"] .chat-header-custom,
[class*="drawer"] .chat-header-custom,
.chat-detail-screen [class*="setting"] .chat-header-custom {
  position: relative !important;
  background: var(--chat-header-bg, #1c1c1e) !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
}
[class*="setting"] .chat-header-custom::before,
[class*="modal"] .chat-header-custom::before,
[class*="drawer"] .chat-header-custom::before {
  display: none !important;
}

/* == 大头像 + 头像与按钮平行 + 灵动岛安全区避让 == */

/* 1. 避让灵动岛与刘海屏：顶栏预留真实安全高度 */
.chat-detail-screen > .chat-header-custom,
.chat-detail-screen > .glass-header {
  position: absolute !important;
  top: 0 !important;
  left: 0 !important;
  right: 0 !important;
  z-index: 20 !important;
  background: transparent !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  border: none !important;
  box-shadow: none !important;

  padding-top: max(env(safe-area-inset-top, 0px), 48px) !important;
  padding-left: 12px !important;
  padding-right: 12px !important;
  padding-bottom: 30px !important;

  display: flex !important;
  align-items: center !important;
  justify-content: space-between !important;
  box-sizing: border-box !important;
}

/* 2. 中间大头像容器：水平绝对居中，垂直基准与按钮平行 */
.chat-detail-screen .header-profile-section {
  position: absolute !important;
  left: 50% !important;
  top: calc(max(env(safe-area-inset-top, 0px), 48px) + 2px) !important;
  transform: translateX(-50%) !important;
  display: flex !important;
  flex-direction: column !important;
  align-items: center !important;
  margin: 0 !important;
  z-index: 2 !important;
}

/* 3. 头像大幅放大 + 精致光泽（58px 大尺寸） */
.chat-detail-screen .header-avatar-container {
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  margin: 0 !important;
  width: 58px !important;
  height: 58px !important;
}

.chat-detail-screen .chat-header-avatar {
  width: 58px !important;
  height: 58px !important;
  border-radius: 50% !important;
  object-fit: cover !important;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.4) !important;
}

/* 4. 左右两侧功能按钮基准对齐（剔除冲突，统一高度） */
.chat-detail-screen .header-action-btn,
.chat-detail-screen .header-btn-video,
.chat-detail-screen .header-btn-phone,
.chat-detail-screen .header-btn-info {
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  height: 40px !important;
  margin: 0 !important;
  z-index: 3 !important;
}

/* 5. 同步调整消息列表顶部高度，防止新消息一出来就撞到大头像 */
.chat-detail-screen > .chat-messages-area {
  padding-top: calc(max(env(safe-area-inset-top, 0px), 48px) + 90px) !important;
}

/* == 标题胶囊 == */
.chat-detail-screen .chat-header-title {
  position: absolute !important;
  top: calc(100% - 15px) !important;
  left: 50% !important;
  transform: translateX(-50%) translateZ(1px) !important;
  z-index: 10 !important;
  white-space: nowrap !important;

  color: #ffffff !important;
  font-size: 16px !important;
  font-weight: 700 !important;
  letter-spacing: -0.3px !important;
  line-height: 1.1 !important;
  margin: 0 !important;

  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
