  box-shadow: 
    inset 0 1px 0 rgba(255, 255, 255, 0.35),
    inset 0 -0.8px 0 rgba(255, 255, 255, 0.18),
    0 4px 14px rgba(0, 0, 0, 0.25) !important;

  cursor: pointer !important;
}

.chat-detail-screen .chat-header-title::before {
  content: "" !important;
  position: absolute !important;
  inset: 0 !important;
  border-radius: inherit !important;
  padding: 0.8px !important;
  pointer-events: none !important;
  display: block !important;
  z-index: 0 !important;

  background: conic-gradient(
    from 0deg,
    rgba(255, 255, 255, 0.70) 0deg,
    rgba(255, 255, 255, 0.45) 40deg,
    rgba(255, 255, 255, 0.20) 75deg,
    rgba(255, 255, 255, 0.18) 90deg,
    rgba(255, 255, 255, 0.20) 105deg,
    rgba(255, 255, 255, 0.40) 140deg,
    rgba(255, 255, 255, 0.60) 180deg,
    rgba(255, 255, 255, 0.40) 220deg,
    rgba(255, 255, 255, 0.20) 255deg,
    rgba(255, 255, 255, 0.18) 270deg,
    rgba(255, 255, 255, 0.20) 285deg,
    rgba(255, 255, 255, 0.45) 320deg,
    rgba(255, 255, 255, 0.70) 360deg
  ) !important;

  -webkit-mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0) !important;
  -webkit-mask-composite: xor !important;
  mask-composite: exclude !important;
}

.chat-detail-screen .chat-header-title::after {
  content: "" !important;
  display: inline-block !important;
  width: 6px !important;
  height: 6px !important;
  margin-left: 7px !important;
  border-top: 2.2px solid rgba(255, 255, 255, 0.6) !important;
  border-right: 2.2px solid rgba(255, 255, 255, 0.6) !important;
  transform: rotate(45deg) translateY(-0.5px) !important;
  border-radius: 0.6px !important;
  position: relative !important;
  z-index: 1 !important;
}

/* == 修复版返回键与未读数字== */
.chat-detail-screen .nuo-chat-header-unread-dot {
  display: none !important;
}

/* 状态 A：默认无未读时，死死锁定 40px 正圆 */
.chat-detail-screen .header-btn-back {
  width: 40px !important;
  height: 40px !important;
  min-width: 40px !important;
  min-height: 40px !important;
  max-width: 40px !important;
  max-height: 40px !important;
  border-radius: 50% !important;
  padding: 0 !important;
  margin: 0 !important;
