/* == 翻译 == */
:root {
  /* 0 = 随系统/点击触发；1 = 永远显示 */
  --translation-always-show: 1;
  /* 官方规范：从根源隐藏自带的「查看翻译」按钮 */
  --translation-btn-display: none;

  --tr-overlap: -9px;             /* 翻译压进气泡的距离 */
  --tr-indent: 14px;              /* 翻译文字离气泡左边的距离 */
  --tr-size: 12px;                /* 翻译字号 */

  /* 黑色描边：36 个方向的高精度平滑阴影 */
  --tr-outline:
    0.115em 0.000em 0 #000, 0.111em 0.030em 0 #000, 0.100em 0.057em 0 #000, 0.081em 0.081em 0 #000,
    0.058em 0.100em 0 #000, 0.030em 0.111em 0 #000, 0.000em 0.115em 0 #000, -0.030em 0.111em 0 #000,
    -0.057em 0.100em 0 #000, -0.081em 0.081em 0 #000, -0.100em 0.057em 0 #000, -0.111em 0.030em 0 #000,
    -0.115em 0.000em 0 #000, -0.111em -0.030em 0 #000, -0.100em -0.057em 0 #000, -0.081em -0.081em 0 #000,
    -0.058em -0.100em 0 #000, -0.030em -0.111em 0 #000, 0.000em -0.115em 0 #000, 0.030em -0.111em 0 #000,
    0.058em -0.100em 0 #000, 0.081em -0.081em 0 #000, 0.100em -0.058em 0 #000, 0.111em -0.030em 0 #000,
    0.059em 0.008em 0 #000, 0.048em 0.036em 0 #000, 0.023em 0.055em 0 #000, -0.008em 0.059em 0 #000,
    -0.036em 0.048em 0 #000, -0.055em 0.023em 0 #000, -0.059em -0.008em 0 #000, -0.048em -0.036em 0 #000,
    -0.023em -0.055em 0 #000, 0.008em -0.059em 0 #000, 0.036em -0.048em 0 #000, 0.055em -0.023em 0 #000;
}

/* 1. 气泡内部彻底清空：不放任何按钮、不垫任何透明层，选字复制完全自由 */
.msg-translation-wrapper {
  display: none !important;
}

/* 2. 气泡外部独立翻译块（白字黑描边，完全悬浮在气泡外下沿） */
.msg-translation-detached {
  display: block !important;
  position: relative !important;
  z-index: 6 !important;                 /* 悬浮层级，绝不穿透影响气泡内部 */
  margin: var(--tr-overlap) 0 0 0 !important;
  width: fit-content !important;
  max-width: 188% !important;
  min-width: 0 !important;
  box-sizing: border-box !important;
  pointer-events: none;                  /* 不拦截任何点击 */
}

.msg-translation-detached-content {
  position: relative !important;
  min-width: 0 !important;
  padding: 0 0 0 var(--tr-indent) !important;
  background: transparent !important;
  border: none !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  color: #fff !important;
  font-size: var(--tr-size) !important;
  font-weight: 800 !important;
  line-height: 1.3 !important;
  letter-spacing: 0.2px;
  text-shadow: var(--tr-outline) !important;
  word-break: break-word !important;
}

/* 清除对勾和小字 */
.msg-translation-detached-content::before,
.msg-translation-detached-content::after {
  content: none !important;
}

/* 对方靠左，我方靠右 */
.msg-translation-detached-them { align-self: flex-start !important; }
.msg-translation-detached-me   { align-self: flex-end !important; }
.msg-translation-detached-me .msg-translation-detached-content {
  padding: 0 var(--tr-indent) 0 0 !important;
  text-align: right;
}

/* == 长按消息上下文菜单 == */

/* 1. 全局变量重置为深色磨砂 */
:root {
  --context-menu-bg: rgba(40, 40, 45, 0.75);
  --context-menu-blur: 25px;
  --context-menu-radius: 16px;
  --context-menu-shadow: 0 12px 36px rgba(0, 0, 0, 0.45);
  --context-menu-item-hover: rgba(255, 255, 255, 0.12);

  --reaction-bar-bg: rgba(40, 40, 45, 0.75);
  --reaction-bar-radius: 999px;
  --reaction-bar-shadow: 0 8px 24px rgba(0, 0, 0, 0.35);
}

/* 2. 长按操作菜单面板本体（彻底斩灭白底，注入深色毛玻璃） */
.chat-detail-screen .ig-context-menu {
  background: rgba(40, 40, 45, 0.75) !important;
  backdrop-filter: blur(25px) saturate(180%) !important;
  -webkit-backdrop-filter: blur(25px) saturate(180%) !important;

  border-radius: 16px !important;
  border: 0.5px solid rgba(255, 255, 255, 0.16) !important;
  box-shadow: 
    inset 0 1px 0 rgba(255, 255, 255, 0.22),
    0 12px 36px rgba(0, 0, 0, 0.45) !important;

  overflow: hidden !important;
}

/* 3. 菜单每一项：白字、白图标、细腻半透明分隔线 */
.chat-detail-screen .ig-menu-item {
  color: #ffffff !important;
  font-size: 14.5px !important;
  font-weight: 500 !important;
  padding: 10px 16px !important;
  border-bottom: 0.5px solid rgba(255, 255, 255, 0.08) !important;
  transition: background 0.12s ease !important;
}

.chat-detail-screen .ig-menu-item:last-child {
  border-bottom: none !important;
}

/* 菜单项图标保持纯白 */
.chat-detail-screen .ig-menu-item svg {
  color: #ffffff !important;
  stroke: #ffffff !important;
  opacity: 0.9 !important;
}

/* 按压/悬停高亮反馈 */
.chat-detail-screen .ig-menu-item:hover,
.chat-detail-screen .ig-menu-item:active {
  background: rgba(255, 255, 255, 0.12) !important;
}

/* 危险操作项（如删除/撤回）保留优雅的红字警示 */
.chat-detail-screen .ig-menu-item[class*="danger"],
.chat-detail-screen .ig-menu-item[class*="delete"] {
  color: #ff453a !important;
}
.chat-detail-screen .ig-menu-item[class*="danger"] svg,
.chat-detail-screen .ig-menu-item[class*="delete"] svg {
  color: #ff453a !important;
  stroke: #ff453a !important;
}

/* 4. 同步升级长按时浮现的顶部表情反应条（一并杜绝白底） */
.chat-detail-screen .reaction-bar {
  background: rgba(40, 40, 45, 0.75) !important;
  backdrop-filter: blur(25px) saturate(180%) !important;
  -webkit-backdrop-filter: blur(25px) saturate(180%) !important;
  border-radius: 999px !important;
  border: 0.5px solid rgba(255, 255, 255, 0.16) !important;
  box-shadow: 
    inset 0 1px 0 rgba(255, 255, 255, 0.22),
    0 8px 24px rgba(0, 0, 0, 0.35) !important;
}

/* == 正在回复气泡上移 == */

/* 1. 彻底上顶：垫高 95px，保证打字气泡与小水泡完整悬浮在底栏上方 */
.chat-detail-screen .nuo-typing-indicator {
  position: relative !important;
  z-index: 10 !important;
  margin-bottom: 95px !important;     /* 彻底上顶，绝不被底栏挡住半截 */
  margin-top: 10px !important;
  padding-left: 28px !important;      /* 留出左下角向外伸出的思绪水泡空间 */
  overflow: visible !important;
  display: flex !important;
  align-items: center !important;
}

/* ===== 对方正在回复：iOS 思考气泡 ===== */
.nuo-typing-indicator {
  --typing-dot-size: 8px;
  --typing-dot-color: rgba(255, 255, 255, 0.6);
  padding-left: 16px !important;      /* 气泡左边离屏幕的距离（头像已隐藏，不需要 48px） */
  padding-bottom: 10px !important;    /* 给下面的小圆留位置 */
  overflow: visible !important;
}

.nuo-typing-bubble {
  position: relative !important;
  isolation: isolate;
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  gap: 4.5px !important;
  width: 64px !important;
  min-width: 64px !important;
  height: 32px !important;
  padding: 0 !important;
  box-sizing: border-box !important;
  background: transparent !important;
  border: none !important;
  border-radius: 16px !important;
  box-shadow: none !important;
  -webkit-backdrop-filter: none !important;
  backdrop-filter: none !important;
  overflow: visible !important;
}

/* 毛玻璃底：气泡主体 + 并进去的凸起圆 */
.nuo-typing-bubble::before {
  content: "";
  position: absolute;
  left: -10px;
  top: -2px;
  width: 76px;
  height: 44px;
  z-index: -1;
  pointer-events: none;
  background: var(--bubble-them-bg);
