.chat-detail-screen > .glass-header {
  position: absolute !important;
  top: 0 !important;
  left: 0 !important;
  right: 0 !important;
  z-index: 20 !important;
  background: transparent !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  border: none !important;
  box-shadow: none !important;
}

/* 3. 核心：10 级 Smoothstep 缓动渐变（彻底抹平分界线，如空气般无缝过渡） */
.chat-detail-screen > .chat-header-custom::before {
  content: "" !important;
  position: absolute !important;
  top: 0 !important;
  left: 0 !important;
  right: 0 !important;
  height: calc(100% + 14px) !important;
  z-index: -1 !important;
  pointer-events: none !important;

  /* 黑色底色：高阶平滑自然光衰减 */
  background: linear-gradient(
    to bottom,
    rgba(0, 0, 0, 0.86) 0%,
    rgba(0, 0, 0, 0.86) 28%,
    rgba(0, 0, 0, 0.82) 36%,
    rgba(0, 0, 0, 0.75) 44%,
    rgba(0, 0, 0, 0.65) 52%,
    rgba(0, 0, 0, 0.52) 60%,
    rgba(0, 0, 0, 0.38) 68%,
    rgba(0, 0, 0, 0.24) 76%,
    rgba(0, 0, 0, 0.12) 84%,
    rgba(0, 0, 0, 0.03) 92%,
    transparent 100%
  ) !important;

  /* 深色高透光学磨砂 */
  backdrop-filter: blur(25px) saturate(150%) !important;
  -webkit-backdrop-filter: blur(25px) saturate(150%) !important;

  /* 遮罩：与背景完全同步的 10 级无痕柔化遮罩 */
  -webkit-mask-image: linear-gradient(
    to bottom,
    rgba(0, 0, 0, 1) 0%,
    rgba(0, 0, 0, 1) 28%,
    rgba(0, 0, 0, 0.96) 36%,
    rgba(0, 0, 0, 0.88) 44%,
    rgba(0, 0, 0, 0.76) 52%,
    rgba(0, 0, 0, 0.60) 60%,
    rgba(0, 0, 0, 0.44) 68%,
    rgba(0, 0, 0, 0.28) 76%,
    rgba(0, 0, 0, 0.14) 84%,
    rgba(0, 0, 0, 0.04) 92%,
    transparent 100%
  ) !important;
  mask-image: linear-gradient(
    to bottom,
    rgba(0, 0, 0, 1) 0%,
    rgba(0, 0, 0, 1) 28%,
    rgba(0, 0, 0, 0.96) 36%,
    rgba(0, 0, 0, 0.88) 44%,
    rgba(0, 0, 0, 0.76) 52%,
    rgba(0, 0, 0, 0.60) 60%,
    rgba(0, 0, 0, 0.44) 68%,
    rgba(0, 0, 0, 0.28) 76%,
    rgba(0, 0, 0, 0.14) 84%,
    rgba(0, 0, 0, 0.04) 92%,
    transparent 100%
  ) !important;
}

