.msg-reply-block { display: none !important; }
.msg-bubble-wrapper { position: relative !important; }
.msg-bubble-wrapper:has(.msg-reply-block-detached) { margin-top: var(--q-top) !important; }

.msg-reply-block-detached {
  --reply-detached-name-suffix: "";
  display: flex !important;
  align-items: center !important;
  position: absolute !important;
  top: auto !important;
  bottom: 100% !important;
