}
.msg-me .msg-reply-block-detached::after {
  content: "";
  position: absolute;
  inset: 0;
  z-index: -1;
  pointer-events: none;
  box-sizing: border-box;
  border: 1px solid transparent;
  border-radius: inherit;
  background: var(--them-rim) border-box;
  -webkit-mask: linear-gradient(#000 0 0) border-box, linear-gradient(#000 0 0) padding-box;
  -webkit-mask-composite: source-out;
  mask: linear-gradient(#000 0 0) border-box, linear-gradient(#000 0 0) padding-box;
  mask-composite: subtract;
  clip-path: polygon(0 0, 100% 0, 100% 100%, 22px 100%, 22px calc(100% - 6px), 7px calc(100% - 6px), 7px 100%, 0 100%);
}

.msg-them .msg-reply-block-detached {
  left: calc(100vw - var(--q-edge)) !important;
