    var(--pay-bear) right var(--pay-bear-right) top calc(var(--pay-head-h) + var(--pay-bear-drop) - var(--pay-bear-h)) / auto var(--pay-bear-h) no-repeat,
    linear-gradient(var(--pay-yellow) 0, var(--pay-yellow) var(--pay-head-h), #2A2A2A var(--pay-head-h)) !important;
  border: none !important;
  border-radius: 14px !important;
  box-shadow: none !important;
  -webkit-backdrop-filter: none !important;
