  padding: 0 !important;
  text-shadow: none !important;
}
div.chat-detail-screen:not(#_k) .msg-translation-detached-content::before,
div.chat-detail-screen:not(#_k) .msg-translation-detached-content::after,
div.chat-detail-screen:not(#_k) .msg-translation-detached :is(svg, img) {
  content: none !important;
