/* 6b. 行里面不再分层：字幕条（10）在同一行里稳稳压住自己的气泡（1） */
div.chat-detail-screen:not(#_k) .chat-message-list-custom > div > div,
div.chat-detail-screen:not(#_k) .msg-bubble-wrapper {
