  --loc-name-color: #FFFFFF;
  --loc-addr-color: #8C8C8C;
  --loc-dist-display: none;            /* 想显示「距你 xx km」改成 block */

  /* 个人名片 */
  --cc-w: 230px;
  --cc-radius: 10px;
  --cc-avatar-size: 46px;
  --cc-name-color: #FFFFFF;
  --cc-desc-color: #8C8C8C;
  /* 同时覆盖 App 自带变量 */
  --contact-card-bg: #2A2A2A;
  --contact-card-radius: 10px;
  --contact-card-avatar-radius: 50%;
  --contact-card-divider: transparent;
  --contact-card-border: none;
  --contact-card-shadow: 0 1px 2px rgba(0, 0, 0, 0.08);
  --contact-card-foot: #9A9A9A;

  /* 文件卡 */
  --file-w: 230px;
  --file-h: 76px;
  --file-radius: 10px;
  --file-icon-img: url("https://i.postimg.cc/Kzs9dz2w/IMG-6037.png");
  --file-icon-w: 39px;
  --file-icon-h: 45px;
  --file-name-color: #FFFFFF;
  --file-meta-color: #9A9A9A;
  --file-status-me: " / 已发送";
  --file-status-them: " / 已接收";
}

/* ◆◆◆ 【01 礼物卡 · Kakao 선물하기】 ◆◆◆ */
/* ═══════════════════════════════════════════════
   卡片 270×463，所有图层叠在卡片自己的背景里（::before 实测不显示）
   绿卡位置：x 12~258，y 18~236（横幅 165 + 商品条 53）
   图层从上到下：
   ⓪ 浅灰遮条（盖住插画伸出绿卡上边、右边的部分）
