    21px 189px,                        /* ③ */
    12px 18px,                         /* ④ */
    68px 3px,                          /* ⑤ 插画：x 贴右边，y 比绿卡顶边高 15px */
    12px 18px,                         /* ⑥ */
    12px 183px,                        /* ⑦ */
    10px 436px,                        /* ⑧ 图标 */
    0 254px,                           /* ⑨ */
