}
div.chat-detail-screen:not(#_k) .msg-loc-card :is(.msg-loc-dist, .msg-loc-approx)::before {
  content: none !important;
}

/* 4. 地图区：排在下面，原生地图隐藏，换成图片 */
div.chat-detail-screen:not(#_k) .msg-loc-card .msg-loc-map {
