}
div.chat-detail-screen:not(#_k) .msg-loc-card .msg-loc-map::before,
div.chat-detail-screen:not(#_k) .msg-loc-card .msg-loc-map::after {
  display: none !important;
}

/* 5. 底栏隐藏 */
div.chat-detail-screen:not(#_k) .msg-loc-card :is(.msg-loc-footer, .msg-loc-footer-text) {
  display: none !important;
}

/* ◆◆◆ 【03 个人名片】 ◆◆◆ */
/* 结构（指南）：.cc-card > .cc-top（.cc-avatar + .cc-name / .cc-sign）+ .cc-foot */

/* 1. 外层气泡去壳 */
div.chat-detail-screen:not(#_k) :is(.bubble-me-custom, .msg-plain-me, .bubble-them-custom, .msg-plain-them):has(.cc-card) {
  background: transparent !important;
  border: none !important;
