/* 3. 上半部：头像 + 名字横排，上下居中 */
div.chat-detail-screen:not(#_k) .cc-card .cc-top {
  position: relative !important;
  display: flex !important;
  flex-direction: row !important;
  align-items: center !important;        /* 名字和头像垂直居中 */
