/* ◆◆◆◆◆◆◆◆◆◆◆◆ 【18 日夜切换：跟 App 的深色模式走】 ◆◆◆◆◆◆◆◆◆◆◆◆ */
/* App 开深色模式时会在 body 上加 .dark-mode（美化指南：羁绊卡 / MCP 卡的暗色就是靠它）
   之前用的 @media (prefers-color-scheme) 在 App 里不可靠，改成认这个 class
   App 外观设成「跟随系统」= 跟随手机系统切换
   改日间颜色 → 18a；改夜间颜色 → 18b；18c 里不要写死颜色
   这一节必须放在文件最后（配置行之前） */

/* --- 18a. 日间（默认） --- */
:root {
  /* 原来就有的变量 */
  --chat-bg-color: #C6D3DF;
  --hdr-bg: rgba(198, 211, 223, 0.78);
  --bar-gray: #EFEFEF;
  --stamp-bg: #92A4B1;
  --stamp-color: #FFFFFF;
  --rp-bg: #FFFFFF;
  --rp-name-color: #111111;
  --rp-text-color: #6B6B6B;
  --share-bg: rgba(110, 125, 140, 0.35);
  --pay-bear: url("https://i.postimg.cc/3R6Csy3f/quality-restoration-20261019162735736.png");
  --pay-logo: url("https://i.postimg.cc/nrDYpHzv/quality-restoration-20261019162914874.png");
  --card-dim: 1;                       /* 日间卡片不压暗 */

  --t-bar-bg: #FFFFFF;                 /* 底栏 */
  --t-placeholder: #A6A6A6;            /* 메시지 입력 */
  --t-input-text: #111111;             /* 输入的文字 */
  --t-title: #111111;                  /* 顶栏标题 */
  --t-unread-bg: #111111;              /* 返回旁未读数 */
  --t-unread-text: #FFFFFF;
  --t-them-bg: #FFFFFF;                /* 对方气泡 */
  --t-them-text: #111111;
  --t-them-name: #4A5560;              /* 对方备注名 */
  --t-them-quote-name: #111111;        /* 对方气泡里的引用 */
  --t-them-quote-text: #6B6B6B;
  --t-them-quote-line: rgba(0, 0, 0, 0.12);
  --t-tr-bg: #333333;                  /* 翻译字幕条 */
  --t-tr-text: #FFFFFF;
  --t-recall: #6B7685;                 /* 撤回提示 */
  --t-card-bg: #FFFFFF;                /* 位置 / 名片 / 文件卡 */
  --t-card-title: #1A1A1A;
  --t-card-line: #E5E5E5;
