/* --- 18c. 规则：全部读变量（选择器和原规则一致，靠写在后面覆盖） --- */

/* 1. 变量类 */
:root,
div.chat-detail-screen {
  --bubble-them-color: var(--t-them-text) !important;
}
div.chat-detail-screen:not(#_k) {
  --loc-name-color: var(--t-card-title);
  --cc-name-color: var(--t-card-title);
  --file-name-color: var(--t-card-title);
  --contact-card-bg: var(--t-card-bg);
}

/* 2. 对方气泡 + 尾巴 + 备注名 + 引用 */
div.chat-detail-screen .bubble-them-custom,
div.chat-detail-screen .msg-plain-them {
  color: var(--t-them-text) !important;
  background: var(--t-them-bg) !important;
}
div.chat-detail-screen .bubble-them-custom *,
div.chat-detail-screen .msg-plain-them * {
  color: var(--t-them-text) !important;
}
div.chat-detail-screen .bubble-them-custom[class*="msg-rad-wa"],
div.chat-detail-screen .msg-plain-them[class*="msg-rad-wa"] {
  background: var(--t-them-bg) !important;
  background-image: none !important;
}
div.chat-detail-screen:not(#_k) .msg-bubble-wrapper:is(.is-first, .is-single) :is(.bubble-them-custom, .msg-plain-them)::after {
  background: var(--ic-them-tail) no-repeat 0 0 / 24px 22px !important;
}
div.chat-detail-screen .msg-bubble-wrapper.msg-them.is-first .bubble-them-custom::before,
div.chat-detail-screen .msg-bubble-wrapper.msg-them.is-first .msg-plain-them::before,
div.chat-detail-screen .msg-bubble-wrapper.msg-them.is-single .bubble-them-custom::before,
div.chat-detail-screen .msg-bubble-wrapper.msg-them.is-single .msg-plain-them::before {
  color: var(--t-them-name) !important;
}
div.chat-detail-screen .msg-bubble-wrapper.msg-them .msg-reply-block {
  --quote-name-color: var(--t-them-quote-name);
  --quote-text-color: var(--t-them-quote-text);
  --quote-line: var(--t-them-quote-line);
}

/* 3. 顶栏 */
div.chat-detail-screen .chat-header-custom .chat-header-title {
  color: var(--t-title) !important;
}
div.chat-detail-screen:not(#_k):has(.nuo-typing-indicator) .chat-header-custom .chat-header-title::before {
  color: var(--t-title) !important;
}
div.chat-detail-screen .chat-header-custom .header-btn-back {
  background-image: var(--ic-back) !important;
}
div.chat-detail-screen .chat-header-custom .header-btn-video {
  background-image: var(--ic-search) !important;
}
div.chat-detail-screen .chat-header-custom .header-btn-info {
  background-image: var(--ic-menu) !important;
}
div.chat-detail-screen .chat-header-custom .nuo-chat-header-unread-num {
  background: var(--t-unread-bg) !important;
  color: var(--t-unread-text) !important;
}
div.chat-detail-screen .chat-header-custom .nuo-chat-header-unread-dot {
  background: var(--t-unread-bg) !important;
}

/* 4. 底栏 */
div.chat-detail-screen .input-area-custom {
  background: var(--t-bar-bg) !important;
}
div.chat-detail-screen .input-area-custom::before {
  color: var(--t-placeholder) !important;
}
div.chat-detail-screen .input-box-custom,
div.chat-detail-screen:not(#_k) .input-area-custom .input-box-custom.input-box-custom {
  color: var(--t-input-text) !important;
  -webkit-text-fill-color: var(--t-input-text) !important;   /* App 自带样式用它压住了 color，不写这行字会是深色 */
  caret-color: var(--t-input-text) !important;
  --input-box-color: var(--t-input-text) !important;   /* App 自带的输入文字变量也同步（写在元素上，夜间才取得到夜间值） */
}
div.chat-detail-screen .input-btn-plus {
  background: var(--bar-gray) var(--ic-plus) center / 18px 18px no-repeat !important;
}
div.chat-detail-screen .input-btn-ai {
  background: var(--bar-gray) var(--ic-hash) center / 20px 20px no-repeat !important;
}
div.chat-detail-screen:not(#_k) .input-reply-preview-bar::after {
  background: var(--ic-rp-arrow) center / contain no-repeat !important;
}

/* 5. 通话卡（对方） */
div.chat-detail-screen:not(#_k):not(#_k):not(#_k) .msg-bubble-wrapper.msg-them :is(.bubble-them-custom, .msg-plain-them):has(.msg-videocall-card) {
  background: var(--t-them-bg) !important;
}
div.chat-detail-screen:not(#_k):not(#_k):not(#_k) .msg-bubble-wrapper:is(.is-first, .is-single) :is(.bubble-them-custom, .msg-plain-them):has(.msg-videocall-card)::after {
  background: var(--ic-them-tail) no-repeat 0 0 / 24px 22px !important;
}
div.chat-detail-screen:not(#_k) .msg-bubble-wrapper.msg-them .msg-videocall-card .msg-videocall-icon {
  background-image: var(--ic-call) !important;
}
div.chat-detail-screen:not(#_k) .msg-bubble-wrapper.msg-them .msg-videocall-card > :nth-child(2),
div.chat-detail-screen:not(#_k) .msg-bubble-wrapper.msg-them .msg-videocall-card > :nth-child(2) * {
  color: var(--t-them-text) !important;
  -webkit-text-fill-color: var(--t-them-text) !important;
}
/* AI 方转账 / 红包 / 通话上面的备注名 */
div.chat-detail-screen:not(#_k):not(#_k):not(#_k) .msg-bubble-wrapper.msg-them:is(.is-first, .is-single) :is(.bubble-them-custom, .msg-plain-them):has(:is(.msg-transfer-card, .msg-redpacket-card, .msg-videocall-card))::before {
  color: var(--t-them-name) !important;
  -webkit-text-fill-color: var(--t-them-name) !important;
}

/* 6. 语音 */
div.chat-detail-screen:not(#_k) .msg-bubble-wrapper.msg-them .voice-msg :is(*:has(> .voice-play-btn), .voice-transcription) {
  background: var(--t-voice-bg) !important;
}
div.chat-detail-screen:not(#_k) .msg-bubble-wrapper.msg-bubble-wrapper.msg-bubble-wrapper :is(.msg-me, .msg-them) .voice-msg :is(.voice-controls-row, .voice-transcription),
div.chat-detail-screen:not(#_k) .msg-bubble-wrapper.msg-bubble-wrapper.msg-bubble-wrapper:is(.msg-me, .msg-them) .voice-msg :is(.voice-controls-row, .voice-transcription) {
  background: var(--t-voice-bg) !important;
}
div.chat-detail-screen:not(#_k) .msg-bubble-wrapper.msg-bubble-wrapper.msg-bubble-wrapper.msg-bubble-wrapper .voice-msg .voice-transcription::before {
  border-bottom-color: var(--t-voice-line) !important;
  background-image: var(--ic-voice-label) !important;
}
div.chat-detail-screen:not(#_k) .msg-bubble-wrapper.msg-bubble-wrapper.msg-bubble-wrapper .voice-msg .voice-play-btn {
  background-image: var(--ic-play) !important;
}
div.chat-detail-screen:not(#_k) .msg-bubble-wrapper.msg-bubble-wrapper.msg-bubble-wrapper.msg-bubble-wrapper.msg-bubble-wrapper .voice-msg .voice-play-btn:has(:is(rect, svg > :nth-child(2))) {
  background-image: var(--ic-pause) !important;
}
div.chat-detail-screen:not(#_k) .msg-bubble-wrapper.msg-bubble-wrapper.msg-bubble-wrapper .voice-msg .voice-duration {
  color: var(--t-voice-text) !important;
  -webkit-text-fill-color: var(--t-voice-text) !important;
}
div.chat-detail-screen:not(#_k) .voice-msg.voice-msg-them,
div.chat-detail-screen:not(#_k) .voice-msg.voice-msg-them *,
div.chat-detail-screen:not(#_k) .voice-msg.voice-msg-me,
div.chat-detail-screen:not(#_k) .voice-msg.voice-msg-me * {
  --voice-them-color: var(--t-voice-text) !important;
  --voice-me-color: var(--t-voice-text) !important;
}

/* 7. 转账 / 红包下半 */
div.chat-detail-screen .msg-redpacket-card {
  --redpacket-bg: var(--t-pay-body) !important;
  --redpacket-color: var(--t-pay-text) !important;
  --redpacket-opened-bg: var(--t-pay-body) !important;
  --redpacket-opened-color: var(--t-pay-text) !important;
