  background:var(--nj-them-bg);
}

/* 我方：右下角（镜像） */
:is(.msg-bubble-wrapper,.msg-me):is(.is-first,.is-single) .bubble-me-custom::after,
.bubble-me-custom:is(.first,.single,.plain-first,.plain-single)::after{
  right:-4.18px; left:auto;
  background:var(--nj-me-bg);
  transform:scaleX(-1);
}

/* ===== 头像：我方隐藏；对方只留连发第一条 ===== */

/* 我方头像整个不显示 */
.msg-avatar-me-container{
  display:none !important;
}

/* 对方头像：先全部隐藏（visibility 会保留占位，气泡不会跑位） */
.msg-avatar-them-container{
  visibility:hidden !important;
}
/* 只在「连发第一条 / 单独一条」显示 */
.msg-avatar-them-container.is-first,
.msg-avatar-them-container.is-single{
  visibility:visible !important;
}

/* ===== 对方头像 ===== */
:root{
  --nj-avatar-radius:40%;   /* 圆角：越大越圆，50% 就是正圆 */
}
.msg-avatar-them-container,
.msg-avatar-them-inner,
.msg-avatar-custom{
  border-radius:var(--nj-avatar-radius) !important;
}
.msg-avatar-them-inner{ overflow:hidden; }

/* == 限制图片与表情包大小 == */

/* 1. 变量层限制图片宽度 */
:root {
  --image-msg-max-width: 220px;
  --image-me-max-width: 220px;
  --image-them-max-width: 220px;
}

/* 2. 普通图片消息尺寸限制 */
.msg-image-wrapper,
.msg-image-wrapper img {
  max-width: 220px !important;       /* 图片最大宽度（默认 220px） */
  max-height: 260px !important;      /* 图片最大高度（防止长图占满屏幕） */
  width: auto !important;
  height: auto !important;
  object-fit: cover !important;       /* 保证图片不变形 */
  border-radius: 14px !important;     /* 柔和圆角 */
  display: block !important;
}

/* 3. 表情包 / 贴纸尺寸限制 */
.msg-bubble-wrapper .sticker-img,
.msg-bubble-wrapper [class*="sticker"] img,
.msg-bubble-wrapper img[class*="sticker"],
.msg-bubble-wrapper [class*="sticker"] {
  max-width: 120px !important;       /* 表情包最大宽度 */
  max-height: 120px !important;      /* 表情包最大高度 */
  width: auto !important;
  height: auto !important;
  object-fit: contain !important;     /* 完整展示表情包不裁切 */
  background: transparent !important;
}

/* =================  特殊卡片、图片脱壳 ================= */
#chat-detail-screen .bubble-them-custom:has(.msg-image-wrapper),
#chat-detail-screen .bubble-me-custom:has(.msg-image-wrapper),
/* 【核心免死金牌】：只有不是引用里的图片才脱壳，引用表情包绝对不误杀！ */
#chat-detail-screen .bubble-them-custom:has(img:not(.msg-reply-block img):not(.voice-waveform img)),
#chat-detail-screen .bubble-me-custom:has(img:not(.msg-reply-block img):not(.voice-waveform img)),
#chat-detail-screen .bubble-them-custom:has(.msg-transfer-card),
#chat-detail-screen .bubble-me-custom:has(.msg-transfer-card),
#chat-detail-screen .bubble-them-custom:has(.msg-loc-card),
#chat-detail-screen .bubble-me-custom:has(.msg-loc-card),
#chat-detail-screen .bubble-them-custom:has(.msg-sim-card),
#chat-detail-screen .bubble-me-custom:has(.msg-sim-card),
#chat-detail-screen .bubble-them-custom:has(.gift-ig-container),
#chat-detail-screen .bubble-me-custom:has(.gift-ig-container),
#chat-detail-screen .bubble-them-custom:has(.msg-theater-card),
#chat-detail-screen .bubble-me-custom:has(.msg-theater-card),
#chat-detail-screen .bubble-them-custom:has(.msg-offline-invite-card),
#chat-detail-screen .bubble-me-custom:has(.msg-offline-invite-card),
#chat-detail-screen .bubble-them-custom:has(.msg-couples-invite-card),
#chat-detail-screen .bubble-me-custom:has(.msg-couples-invite-card),
#chat-detail-screen .bubble-them-custom:has(.msg-couples-response-card),
#chat-detail-screen .bubble-me-custom:has(.msg-couples-response-card),
#chat-detail-screen .bubble-them-custom:has([class*="-card"]),
#chat-detail-screen .bubble-me-custom:has([class*="-card"]) {
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  padding: 0 !important;
}

/* ================= 排他规则：卡片、图片绝不显示贴纸与尾巴（已保护引用） ================= */
.bubble-me-custom:has(.msg-image-wrapper)::after,
.bubble-them-custom:has(.msg-image-wrapper)::after,
.bubble-me-custom:has(img:not(.msg-reply-block img):not(.voice-waveform img))::after,
.bubble-them-custom:has(img:not(.msg-reply-block img):not(.voice-waveform img))::after,
.bubble-me-custom:has([class*="card"])::after,
.bubble-them-custom:has([class*="card"])::after,
.bubble-me-custom:has([class*="transfer"])::after,
.bubble-them-custom:has([class*="transfer"])::after,
.bubble-me-custom:has(.gift-ig-container)::after,
.bubble-them-custom:has(.gift-ig-container)::after,
.bubble-me-custom:has(.msg-image-wrapper)::before,
.bubble-them-custom:has(.msg-image-wrapper)::before,
.bubble-me-custom:has(img:not(.msg-reply-block img):not(.voice-waveform img))::before,
.bubble-them-custom:has(img:not(.msg-reply-block img):not(.voice-waveform img))::before,
.bubble-me-custom:has([class*="card"])::before,
.bubble-them-custom:has([class*="card"])::before,
.bubble-me-custom:has([class*="transfer"])::before,
.bubble-them-custom:has([class*="transfer"])::before,
.bubble-me-custom:has(.gift-ig-container)::before,
.bubble-them-custom:has(.gift-ig-container)::before {
  display: none !important;
  content: none !important;
}

/*  卡片容器本体绝不单独生成尾巴 */
.msg-image-wrapper::after,
.msg-transfer-card::after,
.msg-loc-card::after,
.gift-ig-container::after,
.msg-theater-card::after,
.msg-offline-invite-card::after,
.msg-couples-invite-card::after,
.msg-couples-response-card::after,
.msg-werewolf-card::after,
.msg-mahjong-card::after,
.msg-test-invite-card::after,
.msg-test-result-card::after,
.msg-sim-card::after {
  display: none !important;
  content: none !important;
}

/* ===== 引用 ===== */
:root{
  --nj-q-name:#776d69;    /* 「回复 我」颜色 */
  --nj-q-text:#847b77;    /* 被引用的文字颜色 */
  --nj-q-line:#dbdbdb;    /* 分隔线颜色 */
}

/* 我方气泡里的引用颜色（跟着配色走） */
:root{
  --nj-q-me-name:rgba(255,255,255,.78);
  --nj-q-me-text:rgba(255,255,255,.58);
  --nj-q-me-line:rgba(255,255,255,.2);
}
:is(.msg-me,.bubble-me-custom) .msg-reply-block{
  --nj-q-name:var(--nj-q-me-name);
  --nj-q-text:var(--nj-q-me-text);
  --nj-q-line:var(--nj-q-me-line);
}

/* 整块：去底色，上下排列，下面一条细线 */
.msg-reply-block{
  display:flex !important;
  flex-direction:column !important;
  align-items:flex-start !important;
  gap:0 !important;
  width:100%;
  background:none !important;
  border:none !important;
  border-bottom:1px solid var(--nj-q-line) !important;
  border-radius:0 !important;
  box-shadow:none !important;
  padding:0 0 8px !important;
  margin:0 0 8px !important;
  max-width:none !important;
}

/* 名字：加粗，前面补「回复」两个字 */
.msg-reply-block-name{
  font-size:13px !important;
  font-weight:700 !important;
  line-height:18px !important;
  color:var(--nj-q-name) !important;
}
.msg-reply-block-name::before{
  content:"回复\00a0";
}

/* 被引用的文字 */
.msg-reply-block-text{
  font-size:13px !important;
  line-height:18px !important;
  color:var(--nj-q-text) !important;
  opacity:1 !important;
}

/* ===== 思维链 → 名字===== */
:root{
  .nuo-thinking-label::before{
  content: var(--char-name);   /* 当前角色名，自动跟着聊天对象走 */
  font-size:13px;
  font-weight:700;
  color:var(--nj-q-name);
}

  --thinking-btn-bg:transparent;
  --thinking-btn-border:none;
  --thinking-btn-shadow:none;
  --thinking-btn-padding:0;
}

.nuo-thinking-btn{
  background:none !important;
  border:none !important;
  box-shadow:none !important;
  padding:0 !important;
}

/* 藏掉 ▶ 和 💭 */
.nuo-thinking-arrow,
.nuo-thinking-icon{
  display:none !important;
}

/* 原文字"思维链"藏掉，换成名字 */
.nuo-thinking-label{
  font-size:0 !important;
}
.nuo-thinking-label::before{
  content:var(--char-name);
  font-size:13px;
  font-weight:700;
}

/* ===== 转账卡 · KakaoPay 风格（移植自旧版，已去掉备注） ===== */
:root{
  --nj-tf-indent:0em;   /* 金额前面有货币符号想藏掉，就改成 -0.95em */
}

/* 卡片：纯黑上半区 + 白色下半区。.msg-redpacket-card 排除，红包不受影响 */
.msg-transfer-card:not(.msg-redpacket-card){
  width:225px !important;
  aspect-ratio:3 / 4 !important;
  display:flex !important;
  flex-direction:column !important;
  box-sizing:border-box !important;
  padding:0 0 12px !important;
  position:relative !important;
  overflow:visible !important;
  border-radius:16px !important;
