     ========================================= */

  /* --- 1. 🌟 顶栏整体上下调整（整个顶栏包含的所有气泡、文字、大头像、数据、按钮等整体所有内容一起上下移动） --- */
  --header-all-top-offset: 0px;       /* 🌟 顶栏整体所有内容上下移动调整：填 10px 整体全部下移，填 -10px 整体全部上移（自动带动里面所有文字、气泡、头像、卡片、按钮整体上下移动） */
  --header-bg-height: 244px;          /* 顶栏背景总高度基准值（一般无需修改，会自动随着上方整体上下调整自动增减） */

  /* 不动 */
  --header-shift: calc(var(--header-all-top-offset, 0px) + var(--header-bg-height, 244px) - 244px);

  /* --- 2. 顶栏按键与中间昵称单独高度调整（微调顶部图标行） --- */
  --header-nav-top: 52px;             /* 顶栏左侧返回键图标、中间昵称、右侧按键的单独垂直高度调整（仅单独微调顶行按钮与昵称时使用） */

  /* --- 3. 顶栏大头像尺寸与位置设置 --- */
  --ig-avatar-size: 76px;             /* 顶栏大头像大小尺寸调整（若头像显得过大或过小可在此调整） */
  --ig-avatar-top: 98px;              /* 顶栏大头像上下垂直位置 */
  --ig-avatar-left: 18px;             /* 顶栏大头像左右水平位置 */

  /* --- 4. 顶栏小头像图片链接（如需更换小头像请在此直接替换图片 URL） --- */
  --header-small-avatar-1: url('https://imgbed.heliar.top/i/ABhgsNPDZQrs9Xvo_IMG_2565.jpeg'); /* 小头像 1（底图） */
  --header-small-avatar-2: url('https://imgbed.heliar.top/i/c0_1R7SKyTTAz0Zv_IMG_2566.jpeg'); /* 小头像 2（中图） */
  --header-small-avatar-3: url('https://imgbed.heliar.top/i/q4gWsr1SG0p3jq9J_IMG_2567.jpeg'); /* 小头像 3（顶图） */

  /* --- 5. 顶栏简介文字颜色与系统原生图标拦截 --- */
  --header-bio-text-color: #1a1a1a;   
  --header-bio-id-color: #1877f2;     

  /* 解决图标重复：关闭系统原生变量注入 */
  --back-btn-icon: none;
  --video-btn-icon: none;
  --info-btn-icon: none;

  /* --- 6. 聊天消息区：双方头像大小与间距设置 --- */
  --msg-avatar-them-size: 45px;       /* 聊天消息区对方头像大小尺寸调整 */
  --msg-avatar-me-size: 45px;         /* 聊天消息区我方头像大小尺寸调整 */
  --msg-avatar-radius: 50%;           /* 聊天消息区头像圆角（50%为正圆，也可调为如8px圆角方形） */
  --msg-avatar-bubble-gap: 6px;       /* 聊天消息区头像与气泡之间的横向间距 */

  /* --- 7. 低栏 (Footer) 整体高度与贴底留白（不同机型防误触适配） --- */
  --input-bar-height: 38px;           /* 一般不动（输入框与操作按键主体高度） */
  --bottom-area-padding-bottom: 24px; /* 低栏贴底留白调整（全面屏底部手势条防误触留白，非全面屏/下巴机型可调小） */

  /* --- 8. 气泡与头像对齐微调 & 双方独立自适应间距 --- */
  --first-msg-top-offset: 6px;        /* 普通单条/首条气泡向下微调距离，确保不超头像 */
  --first-msg-bottom-gap-fix: 2px;    /* 🌟 改为正向 2px（原为 -4px 负补偿导致首条与次条粘连），消除粘连 */
  --msg-them-first-bottom-gap: 2px;   /* 对方无思维链时的底部间距，消除粘连 */
  --first-msg-reply-bottom-gap: 6px;  /* 带有引用/思维链/翻译时的正向呼吸间距 */
  --reply-to-bubble-gap: 8px;         /* 引用卡片与下方主气泡的垂直间距 */
  --sticker-size: 85px;               /* 表情包适中紧凑尺寸 */

  /* --- 9. 紧贴式独立翻译方块设置 --- */
  --translation-always-show: 1;
  --translation-bg: #efefef;
  --translation-text-color: #000000;
  --translation-radius: 6px;
  --translation-margin-top: -15px;
  --translation-offset-them: 25px;

  /* --- 10. --- */
  --bubble-them-text-dimmed: #666666;
  --bubble-me-text-dimmed: #666666;

  /* ================= 全局与布局 ================= */
  --chat-bg-color: #ffffff;
  --plain-gap-between-groups: 16px;   
  --plain-gap-within-group: 4px;      
  --plain-content-max-width: 78%;     
  --plain-avatar-size: var(--msg-avatar-them-size);          
  --plain-avatar-radius: var(--msg-avatar-radius);         
  --plain-avatar-gap: var(--msg-avatar-bubble-gap);           
  --plain-padding-left-me: 32px;      
  --plain-padding-right-them: 32px;   

  /* ================= 🌟 气泡默认颜色：统一白底黑字 ================= */
  --bubble-me-bg: #ffffff;            /* 我方白底（同对方） */
  --bubble-them-bg: #ffffff;          /* 对方白底 */
  --bubble-me-text-color: #000000;    /* 我方黑字（同对方） */
  --bubble-them-text-color: #000000;  /* 对方黑字（未开翻译时） */
  --bubble-me-color: #000000;        
  --bubble-them-color: #000000;      
  --bubble-radius: 20px;             
  --bubble-me-radius: 20px;
  --bubble-them-radius: 20px;

  /* ================= 思维链变量重置 ================= */
  --thinking-btn-bg: transparent;
  --thinking-btn-color: #00BFFF;      
  --thinking-btn-padding: 0;
  --thinking-btn-shadow: none;
  --thinking-btn-border: none;
  --thinking-arrow-color: transparent;

  /* ================= 转账卡片 ================= */
  --transfer-bg-top: #000000;        
  --transfer-bg-bottom: #ffffff;     
  --transfer-text-bottom: #000000;   
  --transfer-icon-border: #ffffff;   
  --transfer-icon-fill: #ffffff;     
  --transfer-text-main: #ffffff;     
}

