/* =========================================
   模块 C: 聊天区 气泡与头像控制 (极简全白 IG 连续气泡)
========================================= */

/* 消息行外层容器：统一顶端对齐 */
div.chat-detail-screen .msg-bubble-wrapper {
  align-items: flex-start !important;
}

/* 纵向弹性排列以支持独立引用在上方、独立翻译在下方 */
div.chat-detail-screen .msg-content-stack {
  display: flex !important;
  flex-direction: column !important;
  position: relative !important;
}

/* --- 🌟 核心自适应逻辑：首条消息与第二条距离精细解耦控制 --- */

/* 1. 普通首条消息（无引用、无思维链、无独立翻译）：堆叠区下沉 6px 避免超出头像 */
div.chat-detail-screen .msg-bubble-wrapper.is-first:not(:has(.msg-reply-block-detached)):not(:has(.msg-reply-block)):not(:has(.nuo-thinking-wrap)):not(:has(.msg-translation-detached)) .msg-content-stack,
div.chat-detail-screen .msg-bubble-wrapper.is-single:not(:has(.msg-reply-block-detached)):not(:has(.msg-reply-block)):not(:has(.nuo-thinking-wrap)):not(:has(.msg-translation-detached)) .msg-content-stack {
  margin-top: var(--first-msg-top-offset, 6px) !important;
}

/* 2. 🌟 我方普通连发首条：放开底部间距至 2px，彻底消除首条与次条粘连（与对方逻辑保持一致） */
div.chat-detail-screen .msg-bubble-wrapper.msg-me.is-first:not(.is-single):not(:has(.msg-reply-block-detached)):not(:has(.msg-reply-block)):not(:has(.nuo-thinking-wrap)):not(:has(.msg-translation-detached)) {
  margin-bottom: var(--first-msg-bottom-gap-fix, 2px) !important;
}

/* 3. 对方普通连发首条（无思维链、无引用、无翻译）：放开底部间距至 2px，消除粘连 */
div.chat-detail-screen .msg-bubble-wrapper.msg-them.is-first:not(.is-single):not(:has(.msg-reply-block-detached)):not(:has(.msg-reply-block)):not(:has(.nuo-thinking-wrap)):not(:has(.msg-translation-detached)) {
  margin-bottom: var(--msg-them-first-bottom-gap, 2px) !important;
}

/* 4. 双方通用：当首条存在独立引用、思维链或独立翻译卡片时，自动使用宽裕呼吸间距 */
div.chat-detail-screen .msg-bubble-wrapper.is-first:has(.msg-reply-block-detached),
div.chat-detail-screen .msg-bubble-wrapper.is-first:has(.msg-reply-block),
div.chat-detail-screen .msg-bubble-wrapper.is-first:has(.nuo-thinking-wrap),
div.chat-detail-screen .msg-bubble-wrapper.is-first:has(.msg-translation-detached) {
  margin-bottom: var(--first-msg-reply-bottom-gap, 6px) !important;
}

/* 5. 带有上方扩展部件（引用/思维链）时，内容堆叠区顶端自然对齐 */
div.chat-detail-screen .msg-bubble-wrapper.is-first:has(.msg-reply-block-detached) .msg-content-stack,
div.chat-detail-screen .msg-bubble-wrapper.is-first:has(.msg-reply-block) .msg-content-stack,
div.chat-detail-screen .msg-bubble-wrapper.is-first:has(.nuo-thinking-wrap) .msg-content-stack {
  margin-top: 4px !important;
}

div.chat-detail-screen .msg-plain-me, 
div.chat-detail-screen .msg-plain-them {
  padding: 6px 12px !important;
  font-size: 14.5px !important;
  line-height: 1.35 !important;
  min-height: auto !important;
}

/* 🌟 我方气泡改色：白底黑字 + 1.5px 浅灰边框（与对方完全一致） */
