}

/* 🌟 对方白底黑字（未开翻译时默认纯黑） */
div.chat-detail-screen .msg-plain-them { 
  background: #ffffff !important; 
  color: var(--bubble-them-text-color, #000000) !important; 
  border: 1.5px solid #d5d5d5 !important;
