/* 2. 真实相册图片本体：按原图真实比例完整展开 */
div.chat-detail-screen .msg-content-stack .msg-image-wrapper img,
div.chat-detail-screen .msg-content-stack .msg-image-card img,
div.chat-detail-screen .msg-image-wrapper img,
