#chat-message-list-root[data-chat-kind="group"] .grp-title-text { display: block; }
#chat-message-list-root[data-chat-kind="group"] .grp-title-level,
#chat-message-list-root[data-chat-kind="group"] .title-badge-shimmer::after { display: none !important; }
