  gap: 3px !important;
  box-sizing: border-box !important;
  width: 100% !important;
  min-height: 51px;
  padding: 6px !important;
  background: var(--dc-input) !important;
  border: 1px solid var(--dc-line) !important;
  border-radius: 19px !important;
  box-shadow: none !important;
}
.chat-detail-screen .input-btn-plus {
  flex: 0 0 var(--dc-button) !important;
