  margin: 0 !important;
  padding: 4px !important;
  order: -1 !important;
  background: transparent !important;
  color: var(--dc-icon) !important;
  box-shadow: none !important;
  border: none !important;
  transform: none !important;
}
.chat-detail-screen .input-action-bar-custom {
  display: grid !important;
  grid-template-columns: minmax(0,1fr) auto !important;
  align-items: center !important;
  gap: 3px !important;
  flex: 1 1 0 !important;
  min-width: 0 !important;
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  padding: 0 !important;
  margin: 0 !important;
  border-radius: 0 !important;
  backdrop-filter: none !important;
}
.chat-detail-screen .input-box-custom {
  grid-area: 1 / 1;
  box-sizing: border-box !important;
  width: 100% !important;
  min-width: 0 !important;
  min-height: 36px !important;
  max-height: 132px !important;
  height: auto;
  margin: 0 !important;
  padding: 7px 3px !important;
  font-size: 16px !important;
  line-height: 22px !important;
  color: var(--dc-text) !important;
  caret-color: var(--dc-accent) !important;
  background: transparent !important;
  border: none !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  resize: none;
  overflow-y: auto !important;
}
.chat-detail-screen .input-box-custom::placeholder { color: var(--dc-muted) !important; opacity: 1; }
/* 真机截图确认宿主已有动态“消息@名字”提示，保留原生提示。
   不叠加第二份伪元素，不改变 textarea 的真实 placeholder。 */
.chat-detail-screen .input-action-bar-custom::before { content: none !important; }
.chat-detail-screen .input-box-custom::placeholder {
  color: var(--dc-muted) !important;
