  font-weight: 400 !important;
}
.chat-detail-screen .input-btns-right {
  grid-area: 1 / 2;
  display: flex !important;
  flex-direction: row !important;
  flex-wrap: nowrap !important;
  align-items: center !important;
  justify-content: flex-end !important;
  gap: 2px !important;
  flex-shrink: 0 !important;
  padding: 0 !important;
  margin: 0 !important;
}
/* 不给单独按钮强加 display，保留原来的隐藏、卸载和禁用状态 */
.chat-detail-screen .input-btn-mic { order: 10 !important; }
.chat-detail-screen .input-btn-sticker { order: 20 !important; }
.chat-detail-screen .input-btn-ai { order: 25 !important; }
.chat-detail-screen :is(.send-btn-custom,.stop-btn-custom) { order: 30 !important; }
.chat-detail-screen .input-btns-right > :is(.input-btn-mic,.input-btn-sticker,.input-btn-ai,.send-btn-custom,.stop-btn-custom) {
  box-sizing: border-box !important;
  flex: 0 0 var(--dc-button) !important;
  width: var(--dc-button) !important;
  min-width: var(--dc-button) !important;
  height: 36px !important;
  padding: 5px !important;
  margin: 0 !important;
  transform: none !important;
  border: none !important;
  box-shadow: none !important;
