/* 时间线自适应：文字块按真实内容收缩，两侧边线从文字块外缘开始。
   不使用固定中间空白，长日期/短时间均不会被横线穿过。 */
.chat-detail-screen .chat-messages-area { overflow-x: hidden !important; }
.chat-detail-screen #chat-message-list-root { overflow-x: clip; }
.chat-detail-screen #chat-message-list-root .timestamp-custom {
  position: relative !important;
  display: block !important;
  box-sizing: border-box !important;
  width: fit-content !important;
  max-width: calc(100% - 24px) !important;
  margin: 8px auto !important;
  padding: 0 9px !important;
  background: transparent !important;
  color: var(--dc-red) !important;
  -webkit-text-fill-color: var(--dc-red) !important;
  text-align: center !important;
  white-space: normal !important;
  overflow-wrap: anywhere;
  isolation: auto !important;
}
.chat-detail-screen #chat-message-list-root .timestamp-custom::before {
  content: "" !important;
  position: absolute !important;
  top: 50% !important;
  bottom: auto !important;
  right: auto !important;
  left: -100vw !important;
  width: 100% !important;
  height: 0 !important;
  box-sizing: content-box !important;
  margin: 0 !important;
  padding: 0 !important;
  background: transparent !important;
  border: none !important;
  border-left: 100vw solid var(--dc-red) !important;
  border-right: 100vw solid var(--dc-red) !important;
  border-top-width: 0 !important;
  /* 1px content height makes side borders horizontal 1px segments. */
  height: 1px !important;
  transform: none !important;
  pointer-events: none;
  z-index: 0 !important;
}
.chat-detail-screen #chat-message-list-root .timestamp-custom::after {
  content: " · 新消息" !important;
  display: inline !important;
  position: static !important;
  width: auto !important;
  padding: 0 !important;
  margin: 0 !important;
  background: transparent !important;
  color: var(--dc-red) !important;
  -webkit-text-fill-color: var(--dc-red) !important;
  font-weight: 700 !important;
  white-space: pre-wrap !important;
}

