.chat-detail-screen:has(#chat-message-list-root[data-chat-kind="group"]) :is(.header-btn-phone,.header-btn-video) { opacity: 0 !important; visibility: visible !important; pointer-events: auto !important; }

/* ===== 图片引用修正：在引用条上生成摘要，隐藏整个原缩略图 ===== */
