}

.voice-msg-me {
  display: flex !important;
  flex-direction: column !important;
  align-items: flex-end !important;
}

.voice-msg-them {
  display: flex !important;
  flex-direction: column !important;
  align-items: flex-start !important;
}

/* 点击语音播放条触发展开文字 */
.voice-transcription-toggle {
  position: absolute !important;
  top: 0 !important;
  left: 0 !important;
  width: 100% !important;
  height: 100% !important;
  opacity: 0 !important;
  font-size: 0 !important;
  z-index: 1 !important;
  cursor: pointer !important;
}

/* ================= 修复对方播放键：左侧净空避让，恢复 100% 灵敏点击 ================= */

/* 1. 播放键本体：赋予最高点击特权与顶层层级（对方与我方通用） */
.voice-play-btn {
  width: 22px !important;
  height: 22px !important;
  flex-shrink: 0 !important;
  border-radius: 50% !important;
  background: rgba(255, 255, 255, 0.65) !important;
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  margin: 0 !important;

  /* 【核心恢复点击】：最高层级 + 强制接收点击，绝不被任何图层拦截！ */
  position: relative !important;
  z-index: 10 !important;
  pointer-events: auto !important;
  cursor: pointer !important;
}

.voice-play-btn svg {
  width: 11px !important;
  height: 11px !important;
  fill: #73505d !important;
  color: #73505d !important;
  transform: translateX(0.5px) !important;
  pointer-events: none !important;
}

/* 2. 【核心避让】：透明展开文字层只覆盖右侧波浪与秒数区域，左侧 32px 彻底让开给播放键！ */
.voice-transcription-toggle {
  position: absolute !important;
  top: 0 !important;
  left: 32px !important;                        /* 【关键避让】：从 32px 开始，绝不遮挡左侧播放键！ */
  right: 0 !important;
  height: 33px !important;
  opacity: 0 !important;
  font-size: 0 !important;
  z-index: 2 !important;
  cursor: pointer !important;
}

/* ================= 1. 气泡本体开启相对定位 ================= */
.bubble-them-custom,
.bubble-me-custom {
  position: relative !important;
}

/* ================= 2. 气泡内部翻译层：绝对定位铺满，内部占用高度彻底为 0 ================= */
.bubble-them-custom .msg-translation-wrapper,
.bubble-me-custom .msg-translation-wrapper {
  position: absolute !important;
  inset: -10 !important;
  width: 100% !important;
  height: 100% !important;
  margin: 0 !important;
  padding: 0 !important;
  border: none !important;
  background: transparent !important;
  box-shadow: none !important;
  pointer-events: none !important;       /* 避免遮挡 */
  display: block !important;
}

/* 隐藏气泡内部的旧翻译文字，保证内部只有纯原文 */
.bubble-them-custom .msg-translation-content,
.bubble-me-custom .msg-translation-content {
  display: none !important;
}

/* 翻译按钮透明铺满整颗气泡，点气泡 100% 触发翻译 */
.msg-translation-btn {
  position: absolute !important;
  inset: 0 !important;
  width: 100% !important;
  height: 100% !important;
  opacity: 0 !important;
  font-size: 0 !important;
  margin: 0 !important;
  padding: 0 !important;
  background: transparent !important;
  border: none !important;
  cursor: pointer !important;
  pointer-events: auto !important;       /* 接收全域点击 */
  z-index: 5 !important;
  display: block !important;
}

.msg-translation-btn svg {
  display: none !important;
}

/* ================= 3. 气泡外独立译文：完全脱离气泡，浮在右下角（我方左下角） ================= */
.msg-translation-detached {
  display: flex !important;
  position: relative !important;
  margin-top: -6px !important;           /* 向上微提，视觉上重叠在气泡底边上 */
  margin-bottom: 6px !important;        /* 底部留出空间，长译文自动把下一条消息推开 */
  padding: 0 !important;
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  width: max-content !important;
  max-width: 210px !important;           /* 严格约 17 个汉字自动换行 */
  z-index: 10 !important;
  pointer-events: none !important;
}

/* 对方译文：重叠在对方气泡【右下角】 */
.msg-translation-detached-them {
  align-self: flex-end !important;
  margin-right: -8px !important;
}

/* 我方译文：重叠在我方气泡【左下角】 */
.msg-translation-detached-me {
  align-self: flex-start !important;
  margin-left: -8px !important;
}

/* ================= 4. 纯净译文排版：细字 + 换行靠左 + 日式「」 ================= */
.msg-translation-detached-content {
  background: transparent !important;
  background-color: transparent !important;
  border: none !important;
  box-shadow: none !important;
  text-shadow: none !important;
  padding: 0 !important;
  margin: 0 !important;

  color: #111111 !important;             /* 纤细深黑字 */
  font-size: 13px !important;
  font-weight: 400 !important;          /* 细体 */
  line-height: 1.35 !important;

  white-space: normal !important;
  word-break: break-all !important;
  text-align: left !important;           /* 换行后多行全部从左对齐 */
  display: inline-block !important;
}

/* 译文前置「 */
.msg-translation-detached-content::before {
  content: "「" !important;
  font-weight: 400 !important;
}

/* 译文后置 」 */
.msg-translation-detached-content::after {
  content: "」" !important;
  font-weight: 400 !important;
}

/* ================= 1. 清除图片消息多余的居中与留白 ================= */
.msg-bubble-wrapper:has(.msg-image-wrapper) .msg-content-stack,
.msg-bubble-wrapper:has(.msg-image-wrapper) .msg-bubble-container,
.msg-bubble-wrapper:has(.msg-image-wrapper) .bubble-them-custom,
.msg-bubble-wrapper:has(.msg-image-wrapper) .bubble-me-custom {
  width: auto !important;
  min-width: 0 !important;
  padding: 0 !important;
  background: transparent !important;
}

/* ================= 2. 对方图片：死死靠左贴紧头像 ================= */
.msg-them .msg-image-wrapper,
.msg-them:has(.msg-image-wrapper) .msg-content-stack {
  display: flex !important;
  align-items: flex-start !important;
  justify-content: flex-start !important;
  align-self: flex-start !important;
  margin-left: 0 !important;             /* 靠左紧贴，不留任何空隙 */
  margin-right: auto !important;
}

/* 确保对方头像和图片之间的间距精致小巧（8px） */
.msg-them .msg-avatar-them-container,
.msg-them .msg-avatar-container {
  margin-right: 8px !important;
}

/* ================= 3. 我方图片：死死靠右对齐 ================= */
.msg-me .msg-image-wrapper,
.msg-me:has(.msg-image-wrapper) .msg-content-stack {
  display: flex !important;
  align-items: flex-end !important;
  justify-content: flex-end !important;
  align-self: flex-end !important;
  margin-right: 0 !important;
  margin-left: auto !important;
}

/* ================= 4. 图片尺寸与圆角 ================= */
.msg-image-wrapper {
  max-width: 200px !important;          /* 限制最大宽度 */
  width: fit-content !important;
  overflow: hidden !important;
}

.msg-image-wrapper img,
.msg-image-custom {
  max-width: 200px !important;
  max-height: 240px !important;
  width: auto !important;
  height: auto !important;
  object-fit: cover !important;
  border-radius: 14px !important;
  display: block !important;
}

/* ====== 转账卡片======== */
/* 1. 变量层阴影彻底清零 */
:root {
  --transfer-card-bg: linear-gradient(to bottom, #03b5FF 80%, #ffffff 80%) !important;
  --transfer-success-card-bg: linear-gradient(to bottom, #03b5FF 80%, #ffffff 80%) !important;
  --transfer-card-border: none !important;
  --transfer-success-card-border: none !important;
  --transfer-card-shadow: none !important;
  --transfer-success-card-shadow: none !important;
  --transfer-me-card-shadow: none !important;
  --transfer-them-card-shadow: none !important;
}

/* 2. 卡片外壳：彻底抹除所有阴影与边框 */
.msg-transfer-card,
.msg-transfer-card.msg-transfer-success,
.msg-transfer-card.msg-transfer-rejected,
.msg-transfer-card.msg-transfer-expired-card,
#chat-detail-screen .msg-transfer-card {
  width: 200px !important;
  aspect-ratio: 2 / 1 !important;
  height: auto !important;
  box-sizing: border-box !important;

  background: linear-gradient(to bottom, #03b5FF 80%, #ffffff 80%) !important;
  background-color: transparent !important;

  /* 【彻底无边框、无阴影、无滤镜光晕】 */
  border: none !important;
  box-shadow: none !important;
  filter: none !important;
  -webkit-filter: none !important;
  border-radius: 14px !important;

  display: flex !important;
  flex-direction: column !important;
  justify-content: center !important;
  align-items: flex-start !important;
  text-align: left !important;

  padding: 14px 12px 14px 5px !important;
}

/* 3. 【除掉所有明确的图标与标签】（保持不动） */
.msg-transfer-card svg,
.msg-transfer-card img,
.msg-transfer-card .msg-transfer-icon,
.msg-transfer-card .msg-transfer-label,
.msg-transfer-card .msg-transfer-subtitle,
.msg-transfer-card .msg-transfer-status-text,
.msg-transfer-card .msg-transfer-check,
.msg-transfer-card .msg-transfer-divider,
.msg-transfer-card .msg-transfer-chevron,
.msg-transfer-card [class*="dot"],
.msg-transfer-card [class*="badge"] {
  display: none !important;
  content: none !important;
}

/* 4. 【已成功的核平大招】：继续保持 23小时后过期处于 0 像素蒸发状态！（保持不动） */
#chat-detail-screen .msg-transfer-card *:not(.msg-transfer-amount):not(.msg-transfer-amount *) {
  font-size: 0 !important;
  line-height: 0 !important;
  color: transparent !important;
  -webkit-text-fill-color: transparent !important;
  text-shadow: none !important;
}

/* 5. 【核心金额】：全状态纯白 + 300 细体强力穿透 + 统一上移 5px */
#chat-detail-screen .msg-transfer-card .msg-transfer-amount,
#chat-detail-screen .msg-transfer-card [class*="amount"],
.msg-transfer-card .msg-transfer-amount {
  display: block !important;
  visibility: visible !important;
  text-align: left !important;

  /* 15px 大小 */
  font-size: 15px !important;
  font-weight: 300 !important;

  /* 全状态纯白 */
  color: #ffffff !important;
  -webkit-text-fill-color: #ffffff !important;
  background: transparent !important;
  background-image: none !important;
  text-shadow: none !important;

  line-height: 1.2 !important;
  margin: 0 !important;

  /* 上移 5px */
  transform: translateY(-5px) !important;
}

/* 【关键修复】：强制金额内部所有数字与符号子标签也是 300 细体！ */
#chat-detail-screen .msg-transfer-card .msg-transfer-amount *,
#chat-detail-screen .msg-transfer-card [class*="amount"] * {
  font-weight: 300 !important;                  /* 强制数字恢复 300 细体 */
  font-size: 25px !important;
  color: #ffffff !important;
  -webkit-text-fill-color: #ffffff !important;
}

/* ================= 转账卡片：三态文案彻底分离（未收 / 已收 / 过期） ================= */

/* -------------------------------------------------------------
   【区域一：金额正下方的状态字】
-------------------------------------------------------------- */

/* 1. 未收款时：固定显示“转账给宝宝” */
#chat-detail-screen .msg-transfer-card .msg-transfer-amount::after,
.msg-transfer-card .msg-transfer-amount::after {
  content: "转账给宝宝" !important;             
  display: block !important;
  visibility: visible !important;
  text-align: left !important;
  font-size: 11px !important;
  font-weight: 300 !important;
  color: #ffffff !important;
  -webkit-text-fill-color: #ffffff !important;
  opacity: 0.9 !important;
  margin-top: 5px !important;
  line-height: 1.2 !important;
}

/* 2. 已收款时：切换为已存入 */
#chat-detail-screen .msg-transfer-card.msg-transfer-success .msg-transfer-amount::after,
.msg-transfer-card.msg-transfer-success .msg-transfer-amount::after {
  content: "已转入你的余额" !important;
}

/* 3. 过期时：切换为已退还 */
#chat-detail-screen .msg-transfer-card.msg-transfer-expired-card .msg-transfer-amount::after,
.msg-transfer-card.msg-transfer-expired-card .msg-transfer-amount::after {
  content: "逾期未领已退还" !important;
}

/* -------------------------------------------------------------
   【区域二：底部 20% 纯白条里的灰色备注】
-------------------------------------------------------------- */

/* 基础结构定位（保持不动：靠左对齐，垂直居中，10.5px 灰色细体） */
#chat-detail-screen .msg-transfer-card::after,
.msg-transfer-card::after {
  display: flex !important;
  visibility: visible !important;
  position: absolute !important;
  bottom: 0 !important;
  left: 8px !important;
  right: 8px !important;
  height: 20px !important;
  align-items: center !important;
  justify-content: flex-start !important;
  text-align: left !important;
  font-size: 10.5px !important;
  font-weight: 300 !important;
  color: #8e8e93 !important;
  -webkit-text-fill-color: #8e8e93 !important;
  line-height: 20px !important;
  white-space: nowrap !important;
  pointer-events: none !important;
  z-index: 4 !important;
}

/* 1. 【未收款备注】：小金库到达，等待签收 */
#chat-detail-screen .msg-transfer-card:not(.msg-transfer-success):not(.msg-transfer-expired-card)::after,
.msg-transfer-card:not(.msg-transfer-success):not(.msg-transfer-expired-card)::after {
  content: "【提示】您的爱心投喂已到账！请查收" !important;
}

/* 2. 【已收款备注】：已成功签收入账 */
#chat-detail-screen .msg-transfer-card.msg-transfer-success::after,
.msg-transfer-card.msg-transfer-success::after {
  content: "叮！投喂签收成功～≽^•༚• ྀི≼。" !important;
}

/* 3. 【过期备注】：超时过期退回 */
#chat-detail-screen .msg-transfer-card.msg-transfer-expired-card::after,
.msg-transfer-card.msg-transfer-expired-card::after {
  content: "糟糕!超时未领，已退回咯ㅠ" !important;
}

/* ================= 转账卡片：加入 QQ 转账经典双向箭头图标 ================= */

/* 1. 确保卡片开启相对定位 */
.msg-transfer-card {
  position: relative !important;
}

/* ================= 转账卡片：右上角「透底双弯箭头环抱 ¥」纯净版 ================= */

/* 1. 确保卡片允许图标浮动显示 */
.msg-transfer-card,
#chat-detail-screen .msg-transfer-card {
  position: relative !important;
  overflow: visible !important;
}

/* ================= 转账卡片：右上角「纯矢量 100% 极清透底」图标 ================= */

#chat-detail-screen .msg-transfer-card::before,
.msg-transfer-card::before {
  content: "" !important;
  display: block !important;
  visibility: visible !important;
  position: absolute !important;

  /* 位置：卡片右上角 */
  top: 14px !important;
  right: 14px !important;
  width: 38px !important;
  height: 38px !important;

