   ============================================================ */

.input-area-custom {
  background: var(--input-area-bg) !important;
  border-top: var(--input-area-border-top) !important;
  border-radius: 15px 15px 0 0 !important;
  padding-top: 8px !important;
  padding-bottom: 32px !important;
  padding-left: 14px !important;
  padding-right: 14px !important;
}

.input-row-wrapper {
  display: flex !important;
  align-items: center !important;
  gap: 8px !important;
  padding: 0 !important;
}

.input-action-bar-custom {
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  display: flex !important;
  align-items: center !important;
  flex: 1 !important;
  min-width: 0 !important;
  padding: 0 !important;
  margin: 0 !important;
  position: relative !important;
}

.input-btns-right {
  display: flex !important;
  align-items: center !important;
  gap: 6px !important;
  margin: 0 !important;
  padding: 0 !important;
}

/* 电话按钮 */
.input-btn-plus svg {
  display: none !important;
}
.input-btn-plus {
  width: 28px !important;
  height: 28px !important;
  min-width: 28px !important;
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  background-image: var(--icon-phone) !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
  background-size: 20px 20px !important;
  margin: 0 !important;
  padding: 0 !important;
}

/* 输入框胶囊 */
.input-box-custom {
  flex: 1 !important;
  min-width: 0 !important;
  background: var(--input-box-bg) !important;
  border: var(--input-box-border) !important;
  border-radius: 20px !important;
  height: 36px !important;
  line-height: 22px !important;
  padding: 7px 32px 7px 12px !important;
  box-sizing: border-box !important;
  color: var(--input-box-color) !important;
  margin: 0 !important;
  resize: none !important;
}

/* 提示词注入：Type a message... */
.input-box-custom::placeholder {
  color: transparent !important;
  -webkit-text-fill-color: transparent !important;
  opacity: 0 !important;
}

.input-action-bar-custom:has(.input-box-custom:placeholder-shown)::before {
  content: "Type a message..." !important;
  position: absolute !important;
  left: 14px !important;
  top: 50% !important;
  transform: translateY(-50%) !important;
  color: var(--input-box-placeholder) !important;
  font-size: 14px !important;
  line-height: 1 !important;
  pointer-events: none !important;
  z-index: 5 !important;
  white-space: nowrap !important;
