}
body .chat-detail-screen .msg-reply-block-detached:has(img, video, canvas).msg-reply-detached-them::before {
  left: calc(100% - var(--q-hook-in) + 8px) !important;
  right: auto !important;
}

/* 缩略图本体:固定小方块,盖过「表情包 110px」那条规则 */
body .chat-detail-screen .msg-reply-block-detached img,
body .chat-detail-screen .msg-reply-block-detached video,
body .chat-detail-screen .msg-reply-block-detached canvas,
body .chat-detail-screen .bubble-me-custom:has(.msg-reply-block-detached) [class*="msg-reply-detached"] img,
body .chat-detail-screen .bubble-them-custom:has(.msg-reply-block-detached) [class*="msg-reply-detached"] img {
  display: block !important;
