/* ========================================================
   🎛️ 控制台、输入框、回复条的黄金位置与防遮挡机制
   ======================================================== */

/* 1. 控制台永远排在最上方（原本的位置） */
.nuo-console-shell {
    order: 1 !important;
    width: 100% !important;
}

/* 2. 输入框排在中间 */
.input-row-wrapper,
.input-action-bar-custom {
    order: 2 !important;
}

/* 3. 回复预览条排在输入框下方 */
.input-reply-preview-bar {
    order: 3 !important;
    position: relative !important;
    margin-left: 45px !important;
    margin-right: 77px !important;
    margin-top: 6px !important;
    margin-bottom: 2px !important;
    width: auto !important;
    height: 32px !important;
    min-height: 32px !important;
    background: #EAEAEA !important;
    border-radius: 6px !important;
    padding: 0 10px !important;
    border: none !important;
    box-shadow: none !important;
    display: flex !important;
    flex-direction: row !important;
    align-items: center !important;
    justify-content: space-between !important;
    z-index: 10 !important;
}

/* 4. 防遮挡：彻底覆盖 控制台未展开、控制台展开、回复条 各种场景 */
/* ① 只要开启了控制台按钮条（哪怕没展开），消息列表就垫高 */
.chat-detail-screen:has(.nuo-console-shell) .chat-message-list-custom {
    padding-bottom: 135px !important;
}

/* ② 回复预览条弹出时垫高 */
.chat-detail-screen:has(.input-reply-preview-bar) .chat-message-list-custom {
    padding-bottom: 130px !important;
}

/* ③ 同时有控制台按钮 + 回复条时，进一步垫高 */
.chat-detail-screen:has(.nuo-console-shell):has(.input-reply-preview-bar) .chat-message-list-custom {
    padding-bottom: 180px !important;
}

/* ④ 点击展开控制台日志大面板时，留出大空间 */
.chat-detail-screen:has(.nuo-console-panel) .chat-message-list-custom {
    padding-bottom: 310px !important;
}

/* ✅ “可按住转文字”：死死锁定在白色胶囊输入框正中心，有回复条时自动隐藏 */
.input-action-bar-custom:has(.input-box-custom:placeholder-shown)::before {
    content: "可按住 转文字";
    position: absolute;
    left: 185px;
    top: 25px;
    transform: translate(-50%, -50%);
    font-size: 13px;
    color: rgba(0, 0, 0, 0.35);
    pointer-events: none;
    letter-spacing: 0.5px;
    white-space: nowrap;
    z-index: 5;
}

.input-area-custom:has(.input-reply-preview-bar) .input-action-bar-custom::before {
    display: none !important;
}

@media (prefers-color-scheme: dark) {
    .input-action-bar-custom:has(.input-box-custom:placeholder-shown)::before {
        color: rgba(255, 255, 255, 0.35);
    }
}

/* 胶囊外壳结构 */
.input-action-bar-custom {
    display: block;
    align-items: flex-end !important;
    padding: 0 7px !important;
