  .msg-transfer-icon {
      opacity: 1 !important;
  } 
  .msg-transfer-amount,
  .msg-transfer-card::after {
      opacity: 0.9 !important;
  }

  /* 夜间红包略微调暗橙色防刺眼 */
  .msg-redpacket-card {
      background: #C67B30 !important;
  }
  .msg-redpacket-card.is-opened {
      background: #4A3A2D !important;
  }
  .msg-redpacket-card .msg-transfer-label::after {
      color: rgba(255, 255, 255, 0.65) !important; 
  }
} /* 夜间模式结束 */

