/* 我方：右下，往气泡里压 2px，伸出去 6px */
div.chat-detail-screen:not(#_b):not(#_b) .msg-bubble-wrapper:is(.is-last, .is-single) :is(.bubble-me-custom, .msg-plain-me):not(:has(img, video, .voice-msg, [class*="card"], .msg-image-wrapper))::after {
