  display: none !important;
}

/* --- 2. 气泡外的独立翻译块：以气泡底边定位，往上压进气泡 --- */
div.chat-detail-screen:not(#_t):not(#_t) .msg-bubble-wrapper:has(.msg-translation-detached) {
