  max-width: var(--tr-max-w) !important;
  margin: 0 !important;
  padding: 0 0 3px !important;          /* 底部给字幕条行内 padding 留位置 */
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  font-size: var(--tr-size) !important;
  line-height: 1.6 !important;
  box-sizing: border-box !important;
}
div.chat-detail-screen:not(#_t):not(#_t) .msg-translation-detached::before,
div.chat-detail-screen:not(#_t):not(#_t) .msg-translation-detached::after {
