}
div.chat-detail-screen:not(#_t):not(#_t) .msg-translation-detached-content::before,
div.chat-detail-screen:not(#_t):not(#_t) .msg-translation-detached-content::after,
div.chat-detail-screen:not(#_t):not(#_t) .msg-translation-detached :is(svg, img) {
