   金额和文字之间空得很开，是因为 App 里装它们的两层容器会平分卡片高度，
   这里让每一层都按内容高度来，不再被拉长
   写在补丁 5 后面，:not(#_m) 叠得更多，覆盖前面
   ═══════════════════════════════════════════════ */

/* --- 1. 卡片宽度 --- */
div.chat-detail-screen:not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m) .msg-bubble-wrapper :is(.msg-transfer-card, .msg-redpacket-card) {
  width: var(--pm-w) !important;
  min-width: var(--pm-w) !important;
  max-width: var(--pm-w) !important;
  justify-content: center !important;
  gap: 0 !important;
}

/* --- 2. 里面每一层都按内容高度，不平分卡片 → 金额和文字挨在一起 --- */
div.chat-detail-screen:not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m) .msg-bubble-wrapper :is(.msg-transfer-card, .msg-redpacket-card) > *,
div.chat-detail-screen:not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m) .msg-bubble-wrapper :is(.msg-transfer-card, .msg-redpacket-card) > * > * {
  flex: 0 0 auto !important;
  height: auto !important;
  min-height: 0 !important;
  max-height: none !important;
  margin-top: 0 !important;
  margin-bottom: 0 !important;
  padding-top: 0 !important;
  padding-bottom: 0 !important;
  gap: 0 !important;
  justify-content: flex-start !important;
}
/* 金额 */
div.chat-detail-screen:not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m) .msg-bubble-wrapper :is(.msg-transfer-card, .msg-redpacket-card) .msg-transfer-amount {
  flex: 0 0 auto !important;
  margin: 0 !important;
  padding: 0 !important;
  line-height: 1.1 !important;
}
/* 下面那行字：紧跟金额 */
div.chat-detail-screen:not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m) .msg-bubble-wrapper :is(.msg-transfer-card, .msg-redpacket-card) .msg-transfer-status-text {
  flex: 0 0 auto !important;
  margin: var(--pm-sub-gap) 0 0 !important;
  padding: 0 !important;
}

/* --- 3. 下面那行字分双方 --- */
div.chat-detail-screen:not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m) .msg-bubble-wrapper.msg-them :is(.msg-transfer-card, .msg-redpacket-card) .msg-transfer-status-text::before {
  content: var(--pm-sub-them) !important;
}
div.chat-detail-screen:not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m) .msg-bubble-wrapper.msg-me :is(.msg-transfer-card, .msg-redpacket-card) .msg-transfer-status-text::before {
  content: var(--pm-sub-me) !important;
}
/* 句子太长时省略，不撑破卡片 */
div.chat-detail-screen:not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m) .msg-bubble-wrapper :is(.msg-transfer-card, .msg-redpacket-card) .msg-transfer-status-text::before {
  max-width: calc(var(--pm-w) - var(--pm-divider-inset) - var(--pm-img-size) - var(--pm-img-text-gap) - var(--pm-pad)) !important;
  overflow: hidden !important;
  text-overflow: ellipsis !important;
  white-space: nowrap !important;
}

/* --- 4. 图片放大：尺寸跟着变量走，卡片高度也跟着变 --- */
div.chat-detail-screen:not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m) .msg-bubble-wrapper :is(.msg-transfer-card, .msg-redpacket-card) {
  min-height: calc(var(--pm-img-gap) * 2 + var(--pm-img-size) + var(--pm-tag-zone)) !important;
  padding-top: var(--pm-img-gap) !important;
  padding-bottom: calc(var(--pm-tag-zone) + var(--pm-img-gap)) !important;
  padding-left: calc(var(--pm-divider-inset) + var(--pm-img-size) + var(--pm-img-text-gap)) !important;
}
div.chat-detail-screen:not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m):not(#_m) .msg-bubble-wrapper :is(.msg-transfer-card, .msg-redpacket-card)::after {
  width: var(--pm-img-size) !important;
  height: var(--pm-img-size) !important;
}

/* ═══════════════════════════════════════════════
   语音 · QQ 排版 + 毛玻璃气泡 + 播放进度滑过（参考 kkt 16c / 16g）
   ┌──────────────────────┐
   │ (▶)  ılı 3"          │ ← 语音条：颜色、描边、尾巴和文字气泡一样
   └──────────────────────┘
   ┌──────────────────────┐
   │ 转写文字…             │ ← 点语音条（播放键以外）展开 / 收起
   └──────────────────────┘
   播放时：浅灰色从左往右滑过整条语音
     我方：用 App 自己的波形进度，跟真实播放同步
     AI：App 不给 AI 语音更新进度，只能按 --vf-fake-dur 写死的时长滑
   秒数本身没法跟着跳：CSS 读不到语音有几秒，也拿不到播放到第几秒
   :not(#_v) 只是提权重，压过气泡 / 图片规则，不要删
   ═══════════════════════════════════════════════ */

/* --- 1. 外层气泡去壳：外观挪到语音条和转写上 --- */
div.chat-detail-screen:not(#_v):not(#_v):not(#_v):not(#_v):not(#_v) .msg-bubble-wrapper :is(.bubble-me-custom, .msg-plain-me, .bubble-them-custom, .msg-plain-them):has(.voice-msg) {
  background: transparent !important;
  background-image: none !important;
  border: none !important;
  box-shadow: none !important;
  padding: 0 !important;
  border-radius: 0 !important;
  overflow: visible !important;
}
div.chat-detail-screen:not(#_v):not(#_v):not(#_v):not(#_v):not(#_v) .msg-bubble-wrapper :is(.bubble-me-custom, .msg-plain-me, .bubble-them-custom, .msg-plain-them):has(.voice-msg)::after {
  content: none !important;
  display: none !important;
}

/* 中间容器：竖排，语音条在上、转写在下 */
div.chat-detail-screen:not(#_v):not(#_v):not(#_v):not(#_v):not(#_v) .voice-msg {
  position: relative !important;
  display: flex !important;
  flex-direction: column !important;
  gap: var(--vf-gap) !important;
  width: auto !important;
  min-width: 0 !important;
  margin: 0 !important;
  padding: 0 !important;
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
}
div.chat-detail-screen:not(#_v):not(#_v):not(#_v):not(#_v):not(#_v) .voice-msg.voice-msg-me { align-items: flex-end !important; }
div.chat-detail-screen:not(#_v):not(#_v):not(#_v):not(#_v):not(#_v) .voice-msg.voice-msg-them { align-items: flex-start !important; }

/* --- 2. 语音条：毛玻璃气泡外观 --- */
div.chat-detail-screen:not(#_v):not(#_v):not(#_v):not(#_v):not(#_v) .voice-msg .voice-controls-row {
  position: relative !important;
  display: flex !important;
  flex-direction: row !important;
  align-items: center !important;
  justify-content: flex-start !important;
  gap: 8px !important;
  box-sizing: border-box !important;
  width: fit-content !important;
  min-width: var(--vf-min-w) !important;
  height: var(--vf-h) !important;
  min-height: var(--vf-h) !important;
  margin: 0 !important;
  padding: 0 14px 0 12px !important;
  border-radius: var(--bb-radius, 10px) !important;
  box-shadow: none !important;
  overflow: visible !important;         /* 尾巴要露出去；进度在波形层里裁 */
  isolation: isolate !important;
}
div.chat-detail-screen:not(#_v):not(#_v):not(#_v):not(#_v):not(#_v) .voice-msg-me .voice-controls-row {
  background: var(--bb-me-bg, #EBEBEB) !important;
  border: none !important;
}
div.chat-detail-screen:not(#_v):not(#_v):not(#_v):not(#_v):not(#_v) .voice-msg-them .voice-controls-row {
  background: var(--bb-them-bg, #FFFFFF) !important;
  border: 1px solid var(--bb-them-line, #C7C7CC) !important;
}
div.chat-detail-screen:not(#_v):not(#_v):not(#_v):not(#_v):not(#_v) .voice-msg .voice-controls-row::before {
  content: none !important;
  display: none !important;
}

/* 尾巴：只在每组最后一条 / 单条，和文字气泡同一套 */
div.chat-detail-screen:not(#_v):not(#_v):not(#_v):not(#_v):not(#_v) .voice-msg .voice-controls-row::after {
  content: none !important;
  display: none !important;
}
div.chat-detail-screen:not(#_v):not(#_v):not(#_v):not(#_v):not(#_v) .msg-bubble-wrapper:is(.is-last, .is-single) .voice-msg-me .voice-controls-row {
  border-bottom-right-radius: 0 !important;
}
div.chat-detail-screen:not(#_v):not(#_v):not(#_v):not(#_v):not(#_v) .msg-bubble-wrapper:is(.is-last, .is-single) .voice-msg-them .voice-controls-row {
  border-bottom-left-radius: 0 !important;
}
div.chat-detail-screen:not(#_v):not(#_v):not(#_v):not(#_v):not(#_v) .msg-bubble-wrapper:is(.is-last, .is-single) .voice-msg .voice-controls-row::after {
  content: "" !important;
  display: block !important;
  position: absolute !important;
  top: auto !important;
  width: 8px !important;
  height: 10px !important;
  margin: 0 !important;
  padding: 0 !important;
  border: none !important;
  border-radius: 0 !important;
  transform: none !important;
  pointer-events: none !important;
  z-index: 1 !important;
}
div.chat-detail-screen:not(#_v):not(#_v):not(#_v):not(#_v):not(#_v) .msg-bubble-wrapper:is(.is-last, .is-single) .voice-msg-me .voice-controls-row::after {
  bottom: 0 !important;
  right: -6px !important;
  left: auto !important;
  background: var(--bb-me-bg, #EBEBEB) !important;
  -webkit-mask: var(--bb-tail-me) center / 100% 100% no-repeat !important;
  mask: var(--bb-tail-me) center / 100% 100% no-repeat !important;
}
div.chat-detail-screen:not(#_v):not(#_v):not(#_v):not(#_v):not(#_v) .msg-bubble-wrapper:is(.is-last, .is-single) .voice-msg-them .voice-controls-row::after {
  bottom: -1px !important;
  left: -8px !important;
  right: auto !important;
  background: var(--bb-tail-them) no-repeat 0 0 / 8px 10px !important;
  -webkit-mask: none !important;
  mask: none !important;
}

/* --- 3. 播放键：圆底 + 三角，播放中换成 ⏸ --- */
div.chat-detail-screen:not(#_v):not(#_v):not(#_v):not(#_v):not(#_v) .voice-msg .voice-play-btn {
  position: relative !important;
  z-index: 3 !important;                /* 高过转写点击层，点它是播放 */
  flex: none !important;
  width: var(--vf-btn) !important;
  height: var(--vf-btn) !important;
  min-width: var(--vf-btn) !important;
  margin: 0 !important;
  padding: 0 !important;
  border: none !important;
  border-radius: 50% !important;
  box-shadow: none !important;
  opacity: 1 !important;
  background: var(--vf-btn-me-bg) !important;
  background-image: none !important;
  -webkit-mask: none !important;
  mask: none !important;
}
div.chat-detail-screen:not(#_v):not(#_v):not(#_v):not(#_v):not(#_v) .voice-msg-them .voice-play-btn {
  background: var(--vf-btn-them-bg) !important;
}
div.chat-detail-screen:not(#_v):not(#_v):not(#_v):not(#_v):not(#_v) .voice-msg .voice-play-btn > *,
div.chat-detail-screen:not(#_v):not(#_v):not(#_v):not(#_v):not(#_v) .voice-msg .voice-play-btn svg {
  opacity: 0 !important;                /* 藏原图标，点击照常 */
}
div.chat-detail-screen:not(#_v):not(#_v):not(#_v):not(#_v):not(#_v) .voice-msg .voice-play-btn::before {
  content: "" !important;
  display: block !important;
  position: absolute !important;
  inset: 0 !important;
  margin: 0 !important;
  background: var(--bb-me-text, #8E8E90) !important;
  -webkit-mask: var(--vf-ic-play) center / 100% 100% no-repeat !important;
  mask: var(--vf-ic-play) center / 100% 100% no-repeat !important;
  pointer-events: none !important;
}
div.chat-detail-screen:not(#_v):not(#_v):not(#_v):not(#_v):not(#_v) .voice-msg-them .voice-play-btn::before {
  background: var(--bb-them-text, #111111) !important;
}
div.chat-detail-screen:not(#_v):not(#_v):not(#_v):not(#_v):not(#_v) .voice-msg .voice-play-btn::after {
  content: none !important;
  display: none !important;
}
/* 播放中（App 把图标换成 ⏸ 时） */
div.chat-detail-screen:not(#_v):not(#_v):not(#_v):not(#_v):not(#_v):not(#_v) .voice-msg .voice-play-btn:has(:is(rect, svg > :nth-child(2)))::before {
  -webkit-mask-image: var(--vf-ic-pause) !important;
  mask-image: var(--vf-ic-pause) !important;
}

/* --- 4. 波形：不显示条，改成垫在底下的进度层（我方真实进度） --- */
div.chat-detail-screen:not(#_v):not(#_v):not(#_v):not(#_v):not(#_v) .voice-msg .voice-waveform {
  display: flex !important;
  position: absolute !important;
  inset: 0 !important;
  width: auto !important;
  height: auto !important;
  min-width: 0 !important;
  max-width: none !important;
  margin: 0 !important;
  padding: 0 !important;
  gap: 0 !important;
  align-items: stretch !important;
  border-radius: inherit !important;    /* 进度跟着圆角裁 */
  overflow: hidden !important;
  background: none !important;
  pointer-events: none !important;
  z-index: 0 !important;
}
div.chat-detail-screen:not(#_v):not(#_v):not(#_v):not(#_v):not(#_v) .voice-msg .voice-waveform .voice-waveform-bar {
  display: block !important;
  flex: 1 1 0 !important;
  width: auto !important;
  min-width: 0 !important;
  max-width: none !important;
  height: 100% !important;
  margin: 0 !important;
  border-radius: 0 !important;
  opacity: 1 !important;
  transform: scaleX(var(--vf-bar-stretch)) !important;
  transform-origin: center !important;
  transition: background-color 0.15s linear !important;
}

/* --- 5. 时长：前面带 QQ 那种小声波 --- */
div.chat-detail-screen:not(#_v):not(#_v):not(#_v):not(#_v):not(#_v) .voice-msg .voice-duration {
  position: relative !important;
  z-index: 1 !important;
  display: inline-flex !important;
  align-items: center !important;
  gap: 5px !important;
  flex: 0 0 auto !important;
  margin: 0 !important;
  padding: 0 !important;
  font-size: 14px !important;
  font-weight: 500 !important;
  line-height: 1 !important;
  white-space: nowrap !important;
  font-variant-numeric: tabular-nums !important;
  pointer-events: none !important;
}
div.chat-detail-screen:not(#_v):not(#_v):not(#_v):not(#_v):not(#_v) .voice-msg-me .voice-duration,
div.chat-detail-screen:not(#_v):not(#_v):not(#_v):not(#_v):not(#_v) .voice-msg-me .voice-duration * {
  color: var(--bb-me-text, #8E8E90) !important;
  -webkit-text-fill-color: var(--bb-me-text, #8E8E90) !important;
}
div.chat-detail-screen:not(#_v):not(#_v):not(#_v):not(#_v):not(#_v) .voice-msg-them .voice-duration,
div.chat-detail-screen:not(#_v):not(#_v):not(#_v):not(#_v):not(#_v) .voice-msg-them .voice-duration * {
  color: var(--bb-them-text, #111111) !important;
  -webkit-text-fill-color: var(--bb-them-text, #111111) !important;
}
div.chat-detail-screen:not(#_v):not(#_v):not(#_v):not(#_v):not(#_v) .voice-msg .voice-duration::before {
  content: "" !important;
  display: block !important;
  flex: none !important;
  width: 18px !important;
  height: 18px !important;
  background: currentColor !important;
  -webkit-mask: var(--vf-ic-wave) center / contain no-repeat !important;
  mask: var(--vf-ic-wave) center / contain no-repeat !important;
  opacity: 0.6 !important;
}

/* --- 6. AI 语音：播放中浅灰色从左滑到右（假进度） --- */
@keyframes vf-fake-fill {
  from { width: 0; }
  to   { width: 100%; }
}
div.chat-detail-screen:not(#_v):not(#_v):not(#_v):not(#_v):not(#_v) .voice-msg .voice-waveform::before {
  content: none !important;
  display: none !important;
}
div.chat-detail-screen:not(#_v):not(#_v):not(#_v):not(#_v):not(#_v):not(#_v) .voice-msg-them .voice-controls-row:has(.voice-play-btn :is(rect, svg > :nth-child(2))) .voice-waveform::before {
  content: "" !important;
  display: block !important;
  position: absolute !important;
  top: 0 !important;
  bottom: 0 !important;
  left: 0 !important;
  width: 0;
  background: var(--vf-fill) !important;
  animation: vf-fake-fill var(--vf-fake-dur) linear forwards !important;
  pointer-events: none !important;
}

/* --- 7. 点语音条（播放键以外）展开 / 收起转写 --- */
div.chat-detail-screen:not(#_v):not(#_v):not(#_v):not(#_v):not(#_v) .voice-msg .voice-transcription-toggle {
  display: block !important;
  position: absolute !important;
  top: 0 !important;
  bottom: auto !important;
  width: auto !important;
  height: var(--vf-h) !important;
  margin: 0 !important;
  padding: 0 !important;
  border: none !important;
  background: transparent !important;
  font-size: 0 !important;
  color: transparent !important;
  -webkit-text-fill-color: transparent !important;
  opacity: 0.01 !important;             /* 0 在部分 WebView 点不到 */
  z-index: 2 !important;
}
div.chat-detail-screen:not(#_v):not(#_v):not(#_v):not(#_v):not(#_v) .voice-msg .voice-transcription-toggle * {
  opacity: 0 !important;
}
/* 我方语音条靠右、AI 靠左，点击层只盖住语音条那一块（让开播放键） */
div.chat-detail-screen:not(#_v):not(#_v):not(#_v):not(#_v):not(#_v) .voice-msg-me .voice-transcription-toggle {
  right: 0 !important;
  left: auto !important;
  width: calc(var(--vf-min-w) - var(--vf-btn-zone)) !important;
}
div.chat-detail-screen:not(#_v):not(#_v):not(#_v):not(#_v):not(#_v) .voice-msg-them .voice-transcription-toggle {
  left: var(--vf-btn-zone) !important;
  right: 0 !important;
}

/* --- 8. 转写：语音条下面一块独立气泡，同色 --- */
div.chat-detail-screen:not(#_v):not(#_v):not(#_v):not(#_v):not(#_v) .voice-msg .voice-transcription {
  display: block !important;
  position: relative !important;
  inset: auto !important;
  box-sizing: border-box !important;
  width: fit-content !important;
  min-width: 0 !important;
  max-width: 240px !important;
  margin: 0 !important;
  padding: 8px 12px !important;
  border-radius: var(--bb-radius, 10px) !important;
  box-shadow: none !important;
  font-size: 14px !important;
  line-height: 1.4 !important;
  text-align: left !important;
  white-space: pre-wrap !important;
  word-break: break-word !important;
  animation: none !important;
  z-index: 1 !important;
}
div.chat-detail-screen:not(#_v):not(#_v):not(#_v):not(#_v):not(#_v) .voice-msg .voice-transcription::before,
div.chat-detail-screen:not(#_v):not(#_v):not(#_v):not(#_v):not(#_v) .voice-msg .voice-transcription::after {
  content: none !important;
  display: none !important;
}
div.chat-detail-screen:not(#_v):not(#_v):not(#_v):not(#_v):not(#_v) .voice-msg-me .voice-transcription {
  background: var(--bb-me-bg, #EBEBEB) !important;
  border: none !important;
}
div.chat-detail-screen:not(#_v):not(#_v):not(#_v):not(#_v):not(#_v) .voice-msg-me .voice-transcription,
