div.chat-detail-screen:not(#_f):not(#_f):not(#_f):not(#_f) .msg-file-card .msg-file-meta::after {
  content: var(--file-status-them) !important;
  order: -1 !important;
  display: block !important;
  white-space: pre !important;
  color: var(--file-meta-color) !important;
  -webkit-text-fill-color: var(--file-meta-color) !important;
  font-size: 11px !important;
  font-weight: 600 !important;
  line-height: 15px !important;
}
div.chat-detail-screen:not(#_f):not(#_f):not(#_f):not(#_f) .msg-file-card.is-me .msg-file-meta::after {
  content: var(--file-status-me) !important;
}

/* 「AI 生成」标签和内容预览隐藏 */
div.chat-detail-screen:not(#_f):not(#_f):not(#_f):not(#_f) .msg-file-card :is(.msg-file-tag, .msg-file-preview) {
  display: none !important;
}

/* 图标：原生换成图片 */
div.chat-detail-screen:not(#_f):not(#_f):not(#_f):not(#_f) .msg-file-card .msg-file-icon {
  order: 2 !important;
  flex: none !important;
  position: relative !important;
  display: block !important;
  width: var(--file-icon-w) !important;
  height: var(--file-icon-h) !important;
  min-width: 0 !important;
  margin: 0 !important;
  padding: 0 !important;
  border: none !important;
  border-radius: 0 !important;
  background: var(--file-icon-img) center / contain no-repeat !important;
  -webkit-mask: none !important;
  mask: none !important;
  box-shadow: none !important;
  color: transparent !important;
  font-size: 0 !important;
  overflow: hidden !important;
}
div.chat-detail-screen:not(#_f):not(#_f):not(#_f):not(#_f) .msg-file-card .msg-file-icon > *,
div.chat-detail-screen:not(#_f):not(#_f):not(#_f):not(#_f) .msg-file-card .msg-file-icon::before,
div.chat-detail-screen:not(#_f):not(#_f):not(#_f):not(#_f) .msg-file-card .msg-file-icon::after,
div.chat-detail-screen:not(#_f):not(#_f):not(#_f):not(#_f) .msg-file-card .msg-file-ext {
  display: none !important;
}

/* ◆◆◆ 3. 真实位置：上文字 + 下地图 ◆◆◆ */

/* 卡片本体：白底，竖排 */
div.chat-detail-screen:not(#_f):not(#_f):not(#_f):not(#_f) .msg-loc-card {
  display: flex !important;
  flex-direction: column !important;
  align-items: stretch !important;
  width: var(--loc-w) !important;
  max-width: none !important;
  height: auto !important;
  margin: 0 !important;
  padding: 0 !important;
  background: var(--loc-bg) !important;
  border: none !important;
  border-radius: var(--loc-radius) !important;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.08) !important;
  overflow: hidden !important;
}
div.chat-detail-screen:not(#_f):not(#_f):not(#_f):not(#_f) .msg-loc-card::before,
div.chat-detail-screen:not(#_f):not(#_f):not(#_f):not(#_f) .msg-loc-card::after {
  content: none !important;
  display: none !important;
}

/* 文字区：排在上面 */
div.chat-detail-screen:not(#_f):not(#_f):not(#_f):not(#_f) .msg-loc-card .msg-loc-info {
  order: 1 !important;
  position: relative !important;
  display: flex !important;
  flex-direction: column !important;
  align-items: flex-start !important;
  justify-content: center !important;
  padding: 8px 12px !important;
  background: transparent !important;
  border: none !important;
}
/* 地点名 */
div.chat-detail-screen:not(#_f):not(#_f):not(#_f):not(#_f) .msg-loc-card .msg-loc-name,
div.chat-detail-screen:not(#_f):not(#_f):not(#_f):not(#_f) .msg-loc-card .msg-loc-name * {
  margin: 0 !important;
  color: var(--loc-name-color) !important;
  -webkit-text-fill-color: var(--loc-name-color) !important;
  font-size: 16px !important;
  font-weight: 500 !important;
  line-height: 1.3 !important;
  white-space: nowrap !important;
  overflow: hidden !important;
  text-overflow: ellipsis !important;
  -webkit-font-smoothing: antialiased !important;
}
div.chat-detail-screen:not(#_f):not(#_f):not(#_f):not(#_f) .msg-loc-card .msg-loc-name {
  width: 100% !important;
}
/* 详细地址（App 实际类名是 .msg-loc-address，.msg-loc-addr 一起写上） */
div.chat-detail-screen:not(#_f):not(#_f):not(#_f):not(#_f) .msg-loc-card :is(.msg-loc-address, .msg-loc-addr),
div.chat-detail-screen:not(#_f):not(#_f):not(#_f):not(#_f) .msg-loc-card :is(.msg-loc-address, .msg-loc-addr) * {
  color: var(--loc-addr-color) !important;
  -webkit-text-fill-color: var(--loc-addr-color) !important;
  font-size: 12px !important;
  font-weight: 400 !important;
  line-height: 1.2 !important;
  white-space: nowrap !important;
  overflow: hidden !important;
  text-overflow: ellipsis !important;
  -webkit-font-smoothing: antialiased !important;
}
div.chat-detail-screen:not(#_f):not(#_f):not(#_f):not(#_f) .msg-loc-card :is(.msg-loc-address, .msg-loc-addr) {
  margin: 3px 0 0 !important;
  width: 100% !important;
}
/* 距离 / 大概位置提示 */
div.chat-detail-screen:not(#_f):not(#_f):not(#_f):not(#_f) .msg-loc-card :is(.msg-loc-dist, .msg-loc-approx) {
  display: var(--loc-dist-display) !important;
  margin: 2px 0 0 !important;
  color: var(--loc-addr-color) !important;
  -webkit-text-fill-color: var(--loc-addr-color) !important;
  font-size: 10px !important;
  font-weight: 400 !important;
}
div.chat-detail-screen:not(#_f):not(#_f):not(#_f):not(#_f) .msg-loc-card :is(.msg-loc-dist, .msg-loc-approx)::before {
  content: none !important;
}

/* 地图区：排在下面，原生地图藏掉，换成图片 */
div.chat-detail-screen:not(#_f):not(#_f):not(#_f):not(#_f) .msg-loc-card .msg-loc-map {
  order: 2 !important;
  position: relative !important;
  display: block !important;
  flex: none !important;
  width: 100% !important;
  height: var(--loc-map-h) !important;
  min-height: 0 !important;
  margin: 0 !important;
  padding: 0 !important;
  border: none !important;
  border-radius: 0 !important;
  background: #EEEEEE var(--loc-map-img) center / cover no-repeat !important;
  filter: none !important;
  overflow: hidden !important;
}
div.chat-detail-screen:not(#_f):not(#_f):not(#_f):not(#_f) .msg-loc-card .msg-loc-map > * {
  display: none !important;
}
div.chat-detail-screen:not(#_f):not(#_f):not(#_f):not(#_f) .msg-loc-card .msg-loc-map::before,
div.chat-detail-screen:not(#_f):not(#_f):not(#_f):not(#_f) .msg-loc-card .msg-loc-map::after {
  display: none !important;
}

/* 底栏隐藏 */
div.chat-detail-screen:not(#_f):not(#_f):not(#_f):not(#_f) .msg-loc-card :is(.msg-loc-footer, .msg-loc-footer-text) {
  display: none !important;
}

/* ═══════════════════════════════════════════════
   引用预览条（输入框上面那条「正在回复 zu」）
   上面一行：「正在回复 zu」换成深灰色「文字で返信」
   下面一行：被引用的文字，保持原样
   左边竖线：蓝色改灰色
   :not(#_rp) 只是提权重，不要删
   ═══════════════════════════════════════════════ */

/* --- 1. 上面一行：原文字压掉，换成「文字で返信」 --- */
div.chat-detail-screen:not(#_rp):not(#_rp):not(#_rp) .input-reply-preview-name,
div.chat-detail-screen:not(#_rp):not(#_rp):not(#_rp) .input-reply-preview-name * {
  font-size: 0 !important;
  line-height: 0 !important;
  color: transparent !important;
  -webkit-text-fill-color: transparent !important;
}
div.chat-detail-screen:not(#_rp):not(#_rp):not(#_rp) .input-reply-preview-name {
  display: block !important;
  text-indent: 0 !important;            /* kkt 裁「正在回复」用的缩进不要 */
  overflow: visible !important;
}
div.chat-detail-screen:not(#_rp):not(#_rp):not(#_rp) .input-reply-preview-name::after {
  content: none !important;
  display: none !important;
}
div.chat-detail-screen:not(#_rp):not(#_rp):not(#_rp) .input-reply-preview-name::before {
  content: var(--rpv-title) !important;
  display: block !important;
  position: static !important;
  margin: 0 !important;
  padding: 0 !important;
  background: none !important;
  border: none !important;
  text-indent: 0 !important;
  font-size: 12px !important;
  font-weight: 600 !important;
  line-height: 1.4 !important;
  white-space: nowrap !important;
  color: var(--rpv-title-color) !important;
  -webkit-text-fill-color: var(--rpv-title-color) !important;
}

/* --- 2. 左边竖线：改灰色 --- */
/* App 的竖线可能画在外层或内容层的左边框上，两层都改 */
div.chat-detail-screen:not(#_rp):not(#_rp):not(#_rp) :is(.input-reply-preview-bar, .input-reply-preview-content) {
  border-left-color: var(--rpv-line) !important;
}
/* 也可能画在内容层的 ::before 上 */
div.chat-detail-screen:not(#_rp):not(#_rp):not(#_rp) .input-reply-preview-content::before {
  background-color: var(--rpv-line) !important;
  border-color: var(--rpv-line) !important;
}
/* ═══════════════════════════════════════════════
   语音 · 已读状态加时间 + 往上挪
   [ ▶ ılı 0:02 ]
            18:30 既読   ← 和文字消息同一套，整行比文字消息高 --rd-voice-lift
   时间来自 App 的 .msg-wa-meta（WhatsApp 样式）或 .msg-status-custom（QQ 样式）
   App 没给语音生成时间元素时只会显示 既読，CSS 没办法自己造出时间
   :not(#_r) 叠得比前面已读规则多，覆盖它们，不要删
   ═══════════════════════════════════════════════ */

/* --- 1. 时间（WhatsApp 样式）：语音里有时间元素就显示，贴语音条右下 --- */
div.chat-detail-screen:not(#_r):not(#_r):not(#_r):not(#_r):not(#_r):not(#_r) .msg-bubble-wrapper.msg-me:is(.is-last, .is-single):has(.voice-msg) .msg-wa-meta {
  display: block !important;
  position: absolute !important;
  top: calc(100% + var(--rd-drop) - var(--rd-voice-lift)) !important;
  bottom: auto !important;
  right: var(--rd-right) !important;
  left: auto !important;
  visibility: visible !important;
  opacity: 1 !important;
}
/* 语音里时间 + 未読 / 既読 排一行（同文字消息 v4） */
div.chat-detail-screen:not(#_r):not(#_r):not(#_r):not(#_r):not(#_r):not(#_r) .msg-bubble-wrapper.msg-me:is(.is-last, .is-single):has(.voice-msg) .msg-wa-meta .msg-wa-time {
  display: flex !important;
  flex-direction: row !important;
  align-items: center !important;
  gap: var(--rd-time-gap) !important;
  visibility: visible !important;
  opacity: 1 !important;
}

/* --- 2. 没有时间元素时：气泡下面单独的 未読 / 既読 也往上挪 --- */
div.chat-detail-screen:not(#_r):not(#_r):not(#_r):not(#_r):not(#_r):not(#_r) .msg-bubble-wrapper.msg-me:is(.is-last, .is-single) :is(.bubble-me-custom, .msg-plain-me):has(.voice-msg)::before {
  top: calc(100% + var(--rd-drop) - var(--rd-voice-lift)) !important;
}

/* --- 3. QQ 样式的状态条（18:30 既読）：语音那一行往上挪 --- */
div.chat-detail-screen:not(#_r):not(#_r):not(#_r):not(#_r):not(#_r):not(#_r) .chat-message-list-custom > *:has(.msg-bubble-wrapper.msg-me:is(.is-last, .is-single)):has(.voice-msg) .msg-status-custom {
  margin-top: calc(var(--rd-drop) - var(--rd-voice-lift)) !important;
}

/* ═══════════════════════════════════════════════
   全局背景 · 日间强制白色，夜间强制 #121212
   颜色在开头的 --app-bg（日间）和「夜间模式」段（夜间）
   :not(#_w) 只是提权重，不要删
   ═══════════════════════════════════════════════ */

/* App 读的背景变量：body 上也写一遍，压过 kkt 夜间在 body 上设的颜色 */
:root,
body,
body.dark-mode,
div.chat-detail-screen {
  --chat-bg-color: var(--app-bg) !important;
  --chat-bg-image: none !important;
  --chat-bg-overlay: transparent !important;
}
/* 直接给页面和聊天区刷白，背景图也去掉 */
html,
body,
div.chat-detail-screen:not(#_w),
div.chat-detail-screen:not(#_w) .chat-message-list-custom {
  background: var(--app-bg) !important;
  background-image: none !important;
}
/* ═══════════════════════════════════════════════
   系统时间（聊天中间的 19:53 / 今天 / 昨天）
   日夜都调大：字号在开头的 --ts-size
   夜间改白色：颜色在「夜间模式」段的 --ts-color；日间颜色不动
   :not(#_ts) 只是提权重，不要删
   ═══════════════════════════════════════════════ */

/* --- 1. 日夜共用：字号调大 --- */
div.chat-detail-screen:not(#_ts):not(#_ts) :is(.timestamp-custom, .date-divider-custom),
div.chat-detail-screen:not(#_ts):not(#_ts) :is(.timestamp-custom, .date-divider-custom) * {
  font-size: var(--ts-size) !important;
  line-height: 1.4 !important;
}

/* --- 2. 夜间：白色（iOS） --- */
body.dark-mode div.chat-detail-screen:not(#_ts):not(#_ts) :is(.timestamp-custom, .date-divider-custom),
body.dark-mode div.chat-detail-screen:not(#_ts):not(#_ts) :is(.timestamp-custom, .date-divider-custom) * {
  color: var(--ts-color) !important;
  -webkit-text-fill-color: var(--ts-color) !important;
  opacity: 1 !important;
}

/* --- 3. 夜间：白色（安卓系统深色） --- */
@media (prefers-color-scheme: dark) {
  @supports not (-webkit-touch-callout: none) {
    div.chat-detail-screen:not(#_ts):not(#_ts) :is(.timestamp-custom, .date-divider-custom),
    div.chat-detail-screen:not(#_ts):not(#_ts) :is(.timestamp-custom, .date-divider-custom) * {
      color: var(--ts-color) !important;
      -webkit-text-fill-color: var(--ts-color) !important;
      opacity: 1 !important;
    }
  }
}

/* ═══════════════════════════════════════════════
   已读状态 · 图片 / 表情包 / 卡片往上挪（日夜都生效）
   范围：转账、红包、文件、位置、通话记录、图片、表情包、文字图这些
   不动：文字消息、语音（语音单独用 --rd-voice-lift）
   用 translateY 整体上提，带翻译 / 引用时原来的位置照样叠加
   距离在开头的 --rd-card-lift
   :not(#_r) 叠得比前面已读规则多，覆盖它们，不要删
   ═══════════════════════════════════════════════ */

/* --- 1. 时间 + 未読 / 既読（WhatsApp 样式） --- */
div.chat-detail-screen:not(#_r):not(#_r):not(#_r):not(#_r):not(#_r):not(#_r):not(#_r):not(#_r) .msg-bubble-wrapper.msg-me:is(.is-last, .is-single):has(:is(img, video, [class*="card"], [class*="sticker"], .msg-image-wrapper):not(.msg-reply-block *)):not(:has(.voice-msg)) .msg-wa-meta {
  transform: translateY(calc(-1 * var(--rd-card-lift))) !important;
}

/* --- 2. 没有时间元素时：气泡下面单独的 未読 / 既読 --- */
div.chat-detail-screen:not(#_r):not(#_r):not(#_r):not(#_r):not(#_r):not(#_r):not(#_r):not(#_r) .msg-bubble-wrapper.msg-me:is(.is-last, .is-single):has(:is(img, video, [class*="card"], [class*="sticker"], .msg-image-wrapper):not(.msg-reply-block *)):not(:has(.voice-msg)) :is(.bubble-me-custom, .msg-plain-me)::before {
  transform: translateY(calc(-1 * var(--rd-card-lift))) !important;
}

/* --- 3. QQ 样式的状态条（18:30 既読） --- */
div.chat-detail-screen:not(#_r):not(#_r):not(#_r):not(#_r):not(#_r):not(#_r):not(#_r):not(#_r) .chat-message-list-custom > *:has(.msg-bubble-wrapper.msg-me:is(.is-last, .is-single):has(:is(img, video, [class*="card"], [class*="sticker"], .msg-image-wrapper):not(.msg-reply-block *)):not(:has(.voice-msg))) .msg-status-custom {
  transform: translateY(calc(-1 * var(--rd-card-lift))) !important;
}

/*⁣‌⁠⁠​⁠⁠⁠‌‍‍​​​⁠‍⁠‌‌​‍‍‍‌‌​‌⁠‍⁠⁠‍‌​⁠⁠‍⁠‌‍‌‍⁠​⁠⁠⁠⁠‍​⁠‍‍​​‌‍⁠‌⁠‍​​‌‍⁣
 * 糯叽机 · iMessage 参考主题
 * 直接复制本文件到自定义 CSS；仅改变当前聊天页样式。
 *
 * 发送气泡以 #34C759 为底色、86%不透明度；接收以 #E9E9EB 为底色、82%不透明度。
 * 主体与独立尾巴先实色绘制，再在同一装饰层统一透明；正文保持不透明。
 * 文字气泡不使用模糊、高光描边或阴影，避免边缘发虚。
 * 双方连续消息按原站分组：仅 is-last / is-single 保留尾巴。
 * ::before 用独立 border 绘制实色圆弧，只在尾巴自身设置透明蒙版形成内凹口，
 * 凹口直接透出原生壁纸；主体与圆弧共用 --im-bubble-fill。
 * 不使用背景色遮挡、clip-path、SVG 或图片尾巴。
 * 双方的照片、表情包、转账及其他原生独立卡片不套文字气泡；原事件保留。
 *
 * 不删除 DOM，不用 display:none；隐藏的消息头像及开场资料卡不再占位。
 * 原顶部按钮仍有透明命中区；消息头像的命中区随占位一起收起，避免遮挡正文。
 * 底部按 P2 绘制加号、胶囊和最右侧麦克风图标。
 * 麦克风图标画在原生最右发送/AI按钮上；只换外观，不换原事件。
 * 原麦克风及其余按钮隐藏图标，透明本体仍在原顺序中接收原操作。
 * 纯 CSS 不创建聊天记录、截图附件或真正的新控件；完整样图见配套 HTML。
 */

/* 01. 颜色、尺寸及站点已有主题变量。实际根节点是 ID，不能只写同名 class。 */
#chat-detail-screen {
  --im-send: #34C759;
  --im-receive: #E9E9EB;
  --im-send-alpha: .86;
  --im-receive-alpha: .82;
  --im-reaction-blue: #008CFF;
  --im-ink: #080808;
  /* PDF 的低 tint / 低 blur 方向；纯 CSS 近似，不冒充 WebGL 折射。
   * 左上高光强、右下弱；不用整圈实白描边，也不让整组文字透明。 */
  --im-glass: rgba(255, 255, 255, .12);
  --im-glass-filter: blur(2px) saturate(110%);
  --im-glass-shadow: 0 6px 18px rgba(15, 23, 42, .08),
    inset 1px 1px 1px rgba(255, 255, 255, .6),
    inset -1px -1px 1px rgba(255, 255, 255, .16);
  --im-header-overlap: calc(max(var(--nuo-safe-top, 36px), 8px) + 52px);
  --im-composer-overlap: calc(47.5px + max(27.5px, var(--nuo-safe-bottom, 0px)));
  --im-font: -apple-system, BlinkMacSystemFont, "SF Pro Text", "Helvetica Neue",
    Helvetica, Arial, "PingFang SC", sans-serif;

  /* 不覆盖 --chat-bg-color / --chat-bg-image 或根背景：由原生壁纸设置接管。 */
  --chat-header-bg: transparent;
  --chat-header-border: transparent;
  --chat-header-title-color: #080808;
  --chat-header-icon-color: #080808;
  --chat-message-max-width: 75%;
  --bubble-me-bg: var(--im-send);
  --bubble-me-bg-gradient: none;
  --bubble-me-color: #fff;
  --bubble-me-border: 0;
  --bubble-me-shadow: none;
  --bubble-them-bg: var(--im-receive);
  --bubble-them-color: #111;
  --bubble-them-border: 0;
  --bubble-them-shadow: none;
  --input-area-bg: transparent;
  --input-box-bg: transparent;
  --plus-btn-color: #080808;

  color: var(--im-ink);
  font-family: var(--im-font) !important;
  -webkit-font-smoothing: antialiased;
}

#chat-detail-screen #chat-message-list-root {
  /* 扩展原滚动视口到玻璃后面，同时补回首末消息的避让距离。
   * 保持原 flex 流：输入框/引用增高时底栏仍自然向上扩展，
   * 列表随之缩短，末条消息始终留在底栏上方。 */
  flex: 1 1 0% !important;
  min-height: 0 !important;
  height: auto !important;
  box-sizing: border-box !important;
  margin-top: calc(0px - var(--im-header-overlap)) !important;
  margin-bottom: calc(0px - var(--im-composer-overlap)) !important;
  /* 原生壁纸画在聊天根节点；消息列表透明，连续透出同一张壁纸。 */
  background: transparent !important;
  font-family: var(--im-font) !important;
  padding-top: calc(var(--im-header-overlap) + 48px) !important;
  padding-bottom: calc(var(--im-composer-overlap) + 16px) !important;
  scroll-padding-top: calc(var(--im-header-overlap) + 48px);
  scroll-padding-bottom: calc(var(--im-composer-overlap) + 16px);
  overflow-x: hidden;
  scrollbar-width: thin;
  scrollbar-color: #aaa transparent;
}

/* 02. 保留原节点并隐藏绘制；按最新要求收起消息头像及开场资料卡的占位。 */
#chat-detail-screen #chat-message-list-root > div:first-child:not([data-sender]),
#chat-detail-screen #chat-message-list-root > div:first-child:not([data-sender]) *,
#chat-detail-screen :is(.msg-avatar-me-container, .msg-avatar-them-container,
  .msg-avatar-container, .msg-avatar-me-ghost, .msg-avatar-them-ghost,
  .msg-status-custom, .chat-header-subtitle),
#chat-detail-screen :is(.msg-avatar-me-container, .msg-avatar-them-container,
  .msg-avatar-container, .msg-avatar-me-ghost, .msg-avatar-them-ghost,
  .msg-status-custom, .chat-header-subtitle) * {
  visibility: hidden !important;
}

/* width/height、flex、margin 一起归零，避免头像或动画替身仍挤占消息行。
 * 裁住内部原尺寸的头像，原元素及事件处理器仍保留在 DOM 中。 */
#chat-detail-screen #chat-message-list-root > div:first-child:not([data-sender]),
#chat-detail-screen :is(.msg-avatar-me-container, .msg-avatar-them-container,
  .msg-avatar-container, .msg-avatar-me-ghost, .msg-avatar-them-ghost) {
  width: 0 !important;
  height: 0 !important;
  min-width: 0 !important;
  min-height: 0 !important;
  max-width: 0 !important;
  max-height: 0 !important;
  flex: 0 0 0 !important;
  padding: 0 !important;
  margin: 0 !important;
  border: 0 !important;
  overflow: hidden !important;
  pointer-events: none !important;
}

/* 取消隐藏头像/资料卡的透明点击层，不让它们覆盖已经扩展的消息正文。 */
#chat-detail-screen #chat-message-list-root > div:first-child:not([data-sender]) *,
#chat-detail-screen :is(.msg-avatar-me-container, .msg-avatar-them-container,
  .msg-avatar-container, .msg-avatar-me-ghost, .msg-avatar-them-ghost) * {
  pointer-events: none !important;
}
#chat-detail-screen :is(.msg-avatar-me-container, .msg-avatar-them-container,
  .msg-avatar-container, .msg-avatar-me-inner, .msg-avatar-them-inner,
  .msg-avatar-me-ghost, .msg-avatar-them-ghost)::after,
#chat-detail-screen #chat-message-list-root > div:first-child:not([data-sender]) > div:last-child::after,
#chat-detail-screen #chat-message-list-root > div:first-child:not([data-sender]) button::after {
  content: none !important;
  visibility: hidden !important;
  pointer-events: none !important;
}

/* 03. 消息排版。75% 只限制实际主体，祖先不再次乘算 75%。
 * 消息行不再留头像栏或头像间距，stack 使用完整可用宽度。
 */
#chat-detail-screen .msg-bubble-wrapper {
  /* 每行独立判断尾巴；initial 让 var 回退到原有透明/实色绘制规则。 */
  --im-group-tail: initial;
  box-sizing: border-box;
  gap: 0 !important;
  margin-block: 5px !important;
  overflow: visible !important;
}

/* 使用原站分组标记，不猜相邻 DOM：首条/中间条不画尾巴。
 * 末条与独立一条保留现有尾巴；消息新增/删除时由原站更新分组。
 * 只控制尾巴伪元素，主体、透明度、布局、媒体类型与事件均不改。 */
#chat-detail-screen .msg-bubble-wrapper:is(.is-first, .is-mid) {
  --im-group-tail: none;
}

#chat-detail-screen .msg-bubble-wrapper.msg-me {
  justify-content: flex-end !important;
}

#chat-detail-screen .msg-bubble-wrapper.msg-them {
  justify-content: flex-start !important;
}

#chat-detail-screen .msg-content-stack {
  box-sizing: border-box;
  flex: 1 1 0% !important;
  width: 100% !important;
  min-width: 0 !important;
  max-width: 100% !important;
  overflow: visible !important;
}

#chat-detail-screen .msg-me .msg-content-stack {
  align-items: flex-end !important;
}

#chat-detail-screen .msg-them .msg-content-stack {
  align-items: flex-start !important;
}

/* 04. 外层传递颜色并铺满可用宽度，主体保持独立 div。 */
#chat-detail-screen .bubble-deco-me {
  --im-bubble-fill: var(--im-send);
  --im-bubble-ink: #fff;
  --im-tail-notch-x: 23px;
}

#chat-detail-screen .bubble-deco-them {
  --im-bubble-fill: var(--im-receive);
  --im-bubble-ink: #111;
  --im-tail-notch-x: -4px;
}

#chat-detail-screen :is(.bubble-deco-me, .bubble-deco-them):has(> div:is(
  .msg-bubble-container, .bubble-me-custom, .bubble-them-custom)) {
  position: relative !important;
  display: block !important;
  isolation: isolate;
  box-sizing: border-box;
  width: 100% !important;
  min-width: 0 !important;
  max-width: 100% !important;
  overflow: visible !important;
  background: transparent !important;
  border: 0 !important;
  outline: none !important;
  box-shadow: none !important;
}

/* 主体：系统无衬线字体；最长占可用行宽 75%，长文本自动换行。 */
#chat-detail-screen :is(.bubble-deco-me, .bubble-deco-them) > div:is(
  .msg-bubble-container, .bubble-me-custom, .bubble-them-custom) {
  position: relative !important;
  display: block !important;
  z-index: 1;
  box-sizing: border-box;
  width: fit-content !important;
  /* P2 单字主体略宽于高度，避免窄圆主体把右下弧尾挤成粗长挂钩。 */
  min-width: 52px !important;
  max-width: 75% !important;
  padding: 12px 16px !important;
  border: 0 !important;
  outline: none !important;
  background: var(--im-body-fill, var(--im-bubble-fill)) !important;
  background-image: none !important;
  color: var(--im-bubble-ink) !important;
  box-shadow: none !important;
  font-family: var(--im-font) !important;
  font-size: 16.5px !important;
  font-weight: 400 !important;
  line-height: 19.5px !important;
  letter-spacing: 0;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
  word-break: normal;
  overflow: visible !important;
  filter: none !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  /* 主体不设置蒙版，避免浏览器把向外延伸的尾巴一起裁掉。 */
  -webkit-mask: none !important;
  mask: none !important;
}

/* 原生正文已有一层 div：短文字居于新增宽度中央，长句仍从左边排版。
 * 原生 no-padding 独立卡不参与文字宽度计算；引用里的缩略图不受影响。
 * :where 不增加选择器权重，避免压过后面的转账卡宽度。
 * 只调整现有正文层的布局，不增加、删除或替换消息节点。 */
#chat-detail-screen :is(.bubble-deco-me, .bubble-deco-them) > div:is(
  .msg-bubble-container, .bubble-me-custom, .bubble-them-custom):where(:not(.no-padding)) > div:where(:not(
  .msg-image-wrapper, .msg-sim-card, .msg-video-card, .msg-videocall-card)) {
  width: fit-content !important;
  max-width: 100% !important;
  margin-inline: auto !important;
  text-align: start;
}

#chat-detail-screen .bubble-deco-me > div:is(
  .msg-bubble-container, .bubble-me-custom, .bubble-them-custom) {
  background-color: var(--im-body-fill, #34C759) !important;
  color: #fff !important;
  border-radius: 20px 20px 22px 20px !important;
  margin-left: auto !important;
  margin-right: 0 !important;
}

/* 接收侧几何镜像，左下圆弧与左侧尾巴衔接。 */
#chat-detail-screen .bubble-deco-them > div:is(
  .msg-bubble-container, .bubble-me-custom, .bubble-them-custom) {
  background-color: var(--im-body-fill, #E9E9EB) !important;
  color: #111 !important;
  border-radius: 20px 20px 20px 22px !important;
  margin-left: 0 !important;
  margin-right: auto !important;
}

/* 禁用外壳旧装饰与白色遮罩；主体 ::before 保留独立曲线尾巴。 */
#chat-detail-screen :is(.bubble-deco-me, .bubble-deco-them):has(> div:is(
  .msg-bubble-container, .bubble-me-custom, .bubble-them-custom))::before,
#chat-detail-screen :is(.bubble-deco-me, .bubble-deco-them):has(> div:is(
  .msg-bubble-container, .bubble-me-custom, .bubble-them-custom))::after,
#chat-detail-screen :is(.bubble-deco-me, .bubble-deco-them) > div:is(
  .msg-bubble-container, .bubble-me-custom, .bubble-them-custom)::after {
  content: none !important;
}

/* 独立伪元素仍用 border 绘制实色圆弧。
 * bottom:0 是主体底边锚点，translateY 使尾尖向下延伸约 6px。
 */
#chat-detail-screen :is(.bubble-deco-me, .bubble-deco-them) > div:is(
  .msg-bubble-container, .bubble-me-custom, .bubble-them-custom)::before {
  content: var(--im-body-tail, var(--im-group-tail, "")) !important;
  display: block !important;
  visibility: visible !important;
  opacity: 1 !important;
  position: absolute !important;
  z-index: auto !important;
  inset: auto !important;
  bottom: 0 !important;
  box-sizing: border-box !important;
  padding: 0 !important;
  margin: 0 !important;
  outline: none !important;
  background-image: none !important;
  box-shadow: none !important;
  transform: translateY(6.5px) !important;
  filter: none !important;
  pointer-events: none;
  /* 只在19×20px尾巴自身挖出透明凹口；使用普通border-box，
   * 不依赖父元素蒙版是否允许溢出，凹口直接透出壁纸。 */
  -webkit-mask-image: radial-gradient(circle at var(--im-tail-notch-x) 13.25px, transparent 6.5px, #000 7px) !important;
  mask-image: radial-gradient(circle at var(--im-tail-notch-x) 13.25px, transparent 6.5px, #000 7px) !important;
  -webkit-mask-size: 100% 100% !important;
  mask-size: 100% 100% !important;
  -webkit-mask-position: 0 0 !important;
  mask-position: 0 0 !important;
  -webkit-mask-repeat: no-repeat !important;
  mask-repeat: no-repeat !important;
  -webkit-mask-origin: border-box !important;
  mask-origin: border-box !important;
  -webkit-mask-clip: border-box !important;
  mask-clip: border-box !important;
}

/* 实色圆弧：由 border 构成；向主体内部多重叠 2px，缓和尾根转折。 */
#chat-detail-screen :is(.bubble-deco-me, .bubble-deco-them) > div:is(
  .msg-bubble-container, .bubble-me-custom, .bubble-them-custom)::before {
  width: 19px !important;
  height: 20px !important;
  background: transparent !important;
  border: 0 solid var(--im-bubble-fill) !important;
}

#chat-detail-screen .bubble-deco-me > div:is(
  .msg-bubble-container, .bubble-me-custom, .bubble-them-custom)::before {
  right: 8px !important;
  border-left-width: 19px !important;
  border-radius: 0 100% 2px 100% !important;
}

#chat-detail-screen .bubble-deco-them > div:is(
  .msg-bubble-container, .bubble-me-custom, .bubble-them-custom)::before {
  left: 8px !important;
  border-right-width: 19px !important;
  border-left-width: 0 !important;
  border-radius: 100% 0 100% 2px !important;
}

/* 共享透明绘制层：复用原本隐藏的头像容器，原头像及其子节点仍隐藏。
 * 容器绝对定位，不恢复头像占位；仅两个 pointer-events:none 伪元素可见。
 * 两个实色形状先重叠，再对容器统一设置 opacity，接缝不会重复叠色。
 * anchor-scope 将每行限制在自己的正文；无容器/无锚点支持时沿用上方实色气泡。
 * 不添加、删除或移动任何站点 DOM，不接管输入和发送事件。 */
@supports (anchor-name: --im-body) and (position-anchor: --im-body) and
  (anchor-scope: --im-body) and (width: anchor-size(width)) {
  #chat-detail-screen .msg-bubble-wrapper {
    position: relative !important;
    anchor-scope: --im-body;
    isolation: isolate;
  }

  /* 只给完整的普通文字链设锚点。引用中的小图不影响文字气泡。 */
  #chat-detail-screen .msg-bubble-wrapper > .msg-content-stack >
  :is(.bubble-deco-me, .bubble-deco-them) >
  div:is(.msg-bubble-container, .bubble-me-custom, .bubble-them-custom):not(
    .no-padding, .nuo-bare-msg):not(:has(> :is(
    .msg-image-wrapper, .msg-sim-card, .msg-video-card, .msg-videocall-card))) {
    anchor-name: --im-body;
  }

  #chat-detail-screen .msg-bubble-wrapper:has(>
    :is(.msg-avatar-me-container, .msg-avatar-them-container)):has(>
    .msg-content-stack > :is(.bubble-deco-me, .bubble-deco-them) >
    div:is(.msg-bubble-container, .bubble-me-custom, .bubble-them-custom):not(
      .no-padding, .nuo-bare-msg)):not(:has(>
    .msg-content-stack > :is(.bubble-deco-me, .bubble-deco-them) >
    div:is(.msg-bubble-container, .bubble-me-custom, .bubble-them-custom) > :is(
      .msg-image-wrapper, .msg-sim-card, .msg-video-card, .msg-videocall-card))) {
    --im-body-fill: transparent;
    --im-body-tail: none;
    --im-surface-content: "";
  }

  #chat-detail-screen .msg-bubble-wrapper.msg-me {
    --im-surface-fill: var(--im-send);
    --im-surface-alpha: var(--im-send-alpha);
    --im-surface-radii: 20px 20px 22px 20px;
    --im-surface-notch: 23px;
  }
  #chat-detail-screen .msg-bubble-wrapper.msg-them {
    --im-surface-fill: var(--im-receive);
    --im-surface-alpha: var(--im-receive-alpha);
    --im-surface-radii: 20px 20px 20px 22px;
    --im-surface-notch: -4px;
  }

  #chat-detail-screen .msg-bubble-wrapper:has(>
    :is(.msg-avatar-me-container, .msg-avatar-them-container)):has(>
    .msg-content-stack > :is(.bubble-deco-me, .bubble-deco-them) >
    div:is(.msg-bubble-container, .bubble-me-custom, .bubble-them-custom):not(
      .no-padding, .nuo-bare-msg)):not(:has(>
    .msg-content-stack > :is(.bubble-deco-me, .bubble-deco-them) >
    div:is(.msg-bubble-container, .bubble-me-custom, .bubble-them-custom) > :is(
      .msg-image-wrapper, .msg-sim-card, .msg-video-card, .msg-videocall-card))) >
  :is(.msg-avatar-me-container, .msg-avatar-them-container) {
    display: block !important;
    position: absolute !important;
    position-anchor: --im-body;
    inset: auto !important;
    left: anchor(left, 0px) !important;
    top: anchor(top, 0px) !important;
    width: anchor-size(width, 0px) !important;
    height: anchor-size(height, 0px) !important;
    min-width: 0 !important;
    min-height: 0 !important;
    max-width: none !important;
    max-height: none !important;
    padding: 0 !important;
    margin: 0 !important;
    border: 0 !important;
    overflow: visible !important;
    z-index: -1 !important;
    opacity: var(--im-surface-alpha, 1) !important;
    visibility: hidden !important;
    pointer-events: none !important;
    background: transparent !important;
    box-shadow: none !important;
    filter: none !important;
    backdrop-filter: none !important;
    -webkit-backdrop-filter: none !important;
  }

  #chat-detail-screen .msg-bubble-wrapper:has(>
    :is(.msg-avatar-me-container, .msg-avatar-them-container)):has(>
    .msg-content-stack > :is(.bubble-deco-me, .bubble-deco-them) >
    div:is(.msg-bubble-container, .bubble-me-custom, .bubble-them-custom):not(
      .no-padding, .nuo-bare-msg)):not(:has(>
    .msg-content-stack > :is(.bubble-deco-me, .bubble-deco-them) >
    div:is(.msg-bubble-container, .bubble-me-custom, .bubble-them-custom) > :is(
      .msg-image-wrapper, .msg-sim-card, .msg-video-card, .msg-videocall-card))) >
  :is(.msg-avatar-me-container, .msg-avatar-them-container)::after {
    content: var(--im-surface-content, none) !important;
    position: absolute !important;
    inset: 0 !important;
    visibility: visible !important;
    pointer-events: none !important;
    background: var(--im-surface-fill) !important;
    border-radius: var(--im-surface-radii) !important;
    border: 0 !important;
    box-shadow: none !important;
  }

  #chat-detail-screen .msg-bubble-wrapper:has(>
    :is(.msg-avatar-me-container, .msg-avatar-them-container)):has(>
    .msg-content-stack > :is(.bubble-deco-me, .bubble-deco-them) >
    div:is(.msg-bubble-container, .bubble-me-custom, .bubble-them-custom):not(
      .no-padding, .nuo-bare-msg)):not(:has(>
    .msg-content-stack > :is(.bubble-deco-me, .bubble-deco-them) >
    div:is(.msg-bubble-container, .bubble-me-custom, .bubble-them-custom) > :is(
      .msg-image-wrapper, .msg-sim-card, .msg-video-card, .msg-videocall-card))) >
  :is(.msg-avatar-me-container, .msg-avatar-them-container)::before {
    content: var(--im-group-tail, var(--im-surface-content, none)) !important;
    display: block !important;
    opacity: 1 !important;
    z-index: auto !important;
    position: absolute !important;
    inset: auto !important;
    bottom: 0 !important;
    transform: translateY(6.5px) !important;
    visibility: visible !important;
    pointer-events: none !important;
    box-sizing: border-box !important;
    width: 19px !important;
    height: 20px !important;
    padding: 0 !important;
    margin: 0 !important;
    outline: none !important;
    background: transparent !important;
    border: 0 solid var(--im-surface-fill) !important;
    box-shadow: none !important;
    -webkit-mask: radial-gradient(circle at var(--im-surface-notch) 13.25px,
      transparent 6.5px, #000 7px) !important;
    mask: radial-gradient(circle at var(--im-surface-notch) 13.25px,
      transparent 6.5px, #000 7px) !important;
    -webkit-mask-size: 100% 100% !important;
    mask-size: 100% 100% !important;
    -webkit-mask-position: 0 0 !important;
    mask-position: 0 0 !important;
    -webkit-mask-repeat: no-repeat !important;
    mask-repeat: no-repeat !important;
    -webkit-mask-origin: border-box !important;
    mask-origin: border-box !important;
    -webkit-mask-clip: border-box !important;
    mask-clip: border-box !important;
  }
  #chat-detail-screen .msg-bubble-wrapper:has(>
    :is(.msg-avatar-me-container, .msg-avatar-them-container)):has(>
    .msg-content-stack > :is(.bubble-deco-me, .bubble-deco-them) >
    div:is(.msg-bubble-container, .bubble-me-custom, .bubble-them-custom):not(
      .no-padding, .nuo-bare-msg)):not(:has(>
    .msg-content-stack > :is(.bubble-deco-me, .bubble-deco-them) >
    div:is(.msg-bubble-container, .bubble-me-custom, .bubble-them-custom) > :is(
      .msg-image-wrapper, .msg-sim-card, .msg-video-card, .msg-videocall-card))) > .msg-avatar-me-container::before {
    right: 8px !important;
    border-left-width: 19px !important;
    border-radius: 0 100% 2px 100% !important;
  }
  #chat-detail-screen .msg-bubble-wrapper:has(>
    :is(.msg-avatar-me-container, .msg-avatar-them-container)):has(>
    .msg-content-stack > :is(.bubble-deco-me, .bubble-deco-them) >
    div:is(.msg-bubble-container, .bubble-me-custom, .bubble-them-custom):not(
      .no-padding, .nuo-bare-msg)):not(:has(>
    .msg-content-stack > :is(.bubble-deco-me, .bubble-deco-them) >
    div:is(.msg-bubble-container, .bubble-me-custom, .bubble-them-custom) > :is(
      .msg-image-wrapper, .msg-sim-card, .msg-video-card, .msg-videocall-card))) > .msg-avatar-them-container::before {
    left: 8px !important;
    border-right-width: 19px !important;
    border-radius: 100% 0 100% 2px !important;
  }
}

/* 04a. 双方的照片、表情包与原生独立卡统一去掉文字气泡外壳。
 * no-padding 是网站给照片、描述照片、贴图、涂鸦、转账、通话等的标记；
 * 贴图加载失败时没有 img，也必须继续保持无外壳，不能只判断有没有图片。
 * 另以直属媒体/描述照片根节点兜底。不能写泛 :has(img)：
 * 普通文字引用图片/贴图时没有 no-padding，仍应保留文字气泡。
 * .bubble-deco-me 与 .bubble-deco-them 共用规则，只保留各自左右对齐。 */
#chat-detail-screen :is(.bubble-deco-me, .bubble-deco-them) > div:is(
  .msg-bubble-container, .bubble-me-custom, .bubble-them-custom):is(.no-padding, :has(> :is(
  .msg-image-wrapper, .msg-sim-card, .msg-video-card, .msg-videocall-card))) {
