#chat-detail-screen .msg-bubble-wrapper :is(
  .msg-bubble-container, .bubble-me-custom, .bubble-them-custom) > .msg-reply-block {
  visibility: hidden !important;
  position: absolute !important;
  inset: 0 auto auto 0 !important;
  width: 0 !important;
  height: 0 !important;
  min-width: 0 !important;
  min-height: 0 !important;
  max-width: 0 !important;
  max-height: 0 !important;
  margin: 0 !important;
  padding: 0 !important;
  border: 0 !important;
  overflow: hidden !important;
  pointer-events: none !important;
}
#chat-detail-screen .msg-reply-block *,
#chat-detail-screen .msg-reply-block::before,
#chat-detail-screen .msg-reply-block::after {
  visibility: hidden !important;
  pointer-events: none !important;
}

#chat-detail-screen :is(.bubble-deco-me, .bubble-deco-them) > .msg-reply-block-detached {
  position: relative !important;
  display: flex !important;
  flex-direction: column !important;
  align-items: stretch !important;
  align-self: flex-start !important;
  order: -1 !important;
  isolation: isolate;
  box-sizing: border-box !important;
  width: fit-content !important;
  min-width: 52px !important;
  max-width: 75% !important;
  margin: 0 auto 10px 0 !important;
  padding: 8px 10px !important;
  gap: 0 !important;
  border: 0 !important;
  border-radius: 17px !important;
  background: transparent !important;
  color: #fff !important;
  font: 400 11px/13px var(--im-font) !important;
  text-align: start !important;
  white-space: normal !important;
  overflow: visible !important;
  opacity: 1 !important;
  box-shadow: none !important;
  filter: none !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  transform: none !important;
  animation: none !important;
  clip-path: none !important;
  cursor: pointer;
  pointer-events: auto !important;
}
#chat-detail-screen :is(.bubble-deco-me, .bubble-deco-them) >
.msg-reply-block-detached[data-reply-from="user"] {
  align-self: flex-end !important;
  margin-left: auto !important;
  margin-right: 0 !important;
}
/* 引用和回复在同一侧时，给连接线留完整高度，避免压到正文。
 * 不同角色发来的消息也同属左侧，因此按实际左右而非self/other判断。 */
#chat-detail-screen :is(.bubble-deco-me, .bubble-deco-them) >
:is(.msg-reply-detached-me[data-reply-from="user"],
  .msg-reply-detached-them[data-reply-from="char"]) {
  margin-bottom: 38px !important;
}
#chat-detail-screen .msg-bubble-wrapper.has-reactions :is(.bubble-deco-me, .bubble-deco-them) >
.msg-reply-block-detached {
  margin-bottom: 44px !important;
}

/* 名称节点保留且隐藏，复用其绝对定位区域作为统一透明的底色层。
 * 主体与独立尾巴先实色绘制，再一起透明，不出现半透明叠色接缝。 */
#chat-detail-screen .msg-reply-block-detached > .msg-reply-detached-name {
  position: absolute !important;
  inset: 0 !important;
  display: block !important;
  width: 100% !important;
  height: 100% !important;
  max-width: none !important;
  max-height: none !important;
  margin: 0 !important;
  padding: 0 !important;
  border: 0 !important;
  border-radius: inherit !important;
  background: transparent !important;
  font-size: 0 !important;
  line-height: 0 !important;
  visibility: hidden !important;
  overflow: visible !important;
  opacity: var(--im-reply-alpha) !important;
  pointer-events: none !important;
  z-index: -1 !important;
}
#chat-detail-screen .msg-reply-detached-name::before {
  content: "" !important;
  position: absolute !important;
  inset: 0 !important;
  background: var(--im-reply-fill) !important;
  border: 0 !important;
  border-radius: inherit !important;
  visibility: visible !important;
  pointer-events: none !important;
}
#chat-detail-screen .msg-reply-detached-name::after {
  /* 沿用正文已确认的圆弧尾根；凹口真正透明，允许原生壁纸透出。 */
  --im-reply-notch-x: -4px;
  content: "" !important;
  position: absolute !important;
  inset: auto !important;
  left: 8px !important;
  bottom: 0 !important;
  box-sizing: border-box !important;
  width: 19px !important;
  height: 20px !important;
  padding: 0 !important;
  margin: 0 !important;
  background: transparent !important;
  border: 0 solid var(--im-reply-fill) !important;
  border-right-width: 19px !important;
  border-radius: 100% 0 100% 2px !important;
  transform: translateY(6.5px) !important;
  -webkit-mask-image: radial-gradient(circle at var(--im-reply-notch-x) 13.25px, transparent 6.5px, #000 7px) !important;
  mask-image: radial-gradient(circle at var(--im-reply-notch-x) 13.25px, transparent 6.5px, #000 7px) !important;
  -webkit-mask-size: 100% 100% !important;
  mask-size: 100% 100% !important;
  -webkit-mask-position: 0 0 !important;
  mask-position: 0 0 !important;
  -webkit-mask-repeat: no-repeat !important;
  mask-repeat: no-repeat !important;
  -webkit-mask-origin: border-box !important;
  mask-origin: border-box !important;
  -webkit-mask-clip: border-box !important;
  mask-clip: border-box !important;
  visibility: visible !important;
  pointer-events: none !important;
}
#chat-detail-screen .msg-reply-block-detached[data-reply-from="user"] > .msg-reply-detached-name::after {
  --im-reply-notch-x: 23px;
  left: auto !important;
  right: 8px !important;
  border-right-width: 0 !important;
  border-left-width: 19px !important;
  border-radius: 0 100% 2px 100% !important;
}

/* 约32×26px、4px粗的弧线，左右根据引用原作者镜像；装饰不拦截点击。 */
#chat-detail-screen .msg-reply-block-detached::after {
  content: "" !important;
  position: absolute !important;
  inset: auto !important;
  top: calc(100% + 9px) !important;
  left: 15px !important;
  box-sizing: border-box !important;
  width: 36px !important;
  height: 26px !important;
  margin: 0 !important;
  padding: 0 !important;
  border: solid var(--im-reply-line) !important;
  border-width: 0 0 4px 4px !important;
  border-radius: 0 0 0 24px !important;
  background: transparent !important;
  box-shadow: none !important;
  filter: none !important;
  transform: none !important;
  pointer-events: none !important;
}
#chat-detail-screen .msg-reply-block-detached[data-reply-from="user"]::after {
  left: auto !important;
  right: 15px !important;
  transform: scaleX(-1) !important;
}
#chat-detail-screen .msg-reply-block-detached::before {
  content: none !important;
}
#chat-detail-screen .msg-reply-block-detached > .msg-reply-detached-text {
  display: -webkit-box !important;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 3;
  line-clamp: 3;
  max-width: 100% !important;
  min-width: 0 !important;
  margin: 0 !important;
  padding: 0 !important;
  color: #fff !important;
  font: inherit !important;
  white-space: normal !important;
  overflow: hidden !important;
  text-overflow: ellipsis !important;
  overflow-wrap: anywhere;
  opacity: 1 !important;
}
/* 引用照片/贴图保持真实缩略图与点击跳转，不影响正文媒体的独立样式。 */
#chat-detail-screen .msg-reply-block-detached > .msg-reply-detached-thumb {
  display: block !important;
  width: 120px !important;
  height: auto !important;
  max-width: 100% !important;
  max-height: 120px !important;
  margin: 0 !important;
  border-radius: 10px !important;
  object-fit: contain !important;
}
#chat-detail-screen .msg-reply-block-detached > .msg-reply-detached-media {
  display: flex !important;
  align-items: center !important;
  gap: 5px !important;
  color: inherit !important;
  font: inherit !important;
}

/* 05. 顶部浮动玻璃按钮。原标题及头像仍占用其原始空间。 */
#chat-detail-screen .glass-header {
  position: relative !important;
  z-index: 30 !important;
  overflow: visible !important;
  background: transparent !important;
  border: 0 !important;
  box-shadow: none !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  pointer-events: none;
  font-family: var(--im-font) !important;
}

/* 全宽层只做很轻的渐隐过渡；玻璃质感集中在独立控件上。
 * 装饰永不拦点击，标题越出 header 的部分也保留可见。 */
#chat-detail-screen .glass-header::before {
  content: "";
  position: absolute;
  inset: 0 0 -48px;
  z-index: -1;
  background: rgba(255, 255, 255, .06);
  backdrop-filter: blur(2px);
  -webkit-backdrop-filter: blur(2px);
  mask-image: linear-gradient(#000 0 55%, transparent 100%);
  -webkit-mask-image: linear-gradient(#000 0 55%, transparent 100%);
  pointer-events: none;
}

#chat-detail-screen :is(.header-btn-back, .header-btn-phone, .header-btn-video, .header-btn-info) {
  pointer-events: auto;
}

#chat-detail-screen .header-btn-back {
  position: relative !important;
  width: 85px !important;
  height: 44px !important;
  flex-shrink: 0;
  border: 1px solid transparent !important;
  border-radius: 999px !important;
  background: var(--im-glass) !important;
  box-shadow: var(--im-glass-shadow) !important;
  backdrop-filter: var(--im-glass-filter) !important;
  -webkit-backdrop-filter: var(--im-glass-filter) !important;
}

#chat-detail-screen .header-btn-back * {
  visibility: hidden !important;
}

#chat-detail-screen .header-btn-back::before {
  content: "";
  position: absolute;
  left: 16px;
  top: 14px;
  width: 12px;
  height: 12px;
  border-left: 2.5px solid #101010;
  border-bottom: 2.5px solid #101010;
  transform: rotate(45deg);
  pointer-events: none;
}

#chat-detail-screen .header-btn-back::after {
  content: "186";
  position: absolute;
  top: 12px;
  left: 34px;
  min-width: 33px;
  height: 20px;
  padding-inline: 4px;
  box-sizing: border-box;
  border-radius: 999px;
  background: #191919;
  color: #fff;
  font: 500 13px/20px var(--im-font);
  text-align: center;
  pointer-events: none;
}

#chat-detail-screen .header-profile-section {
  position: absolute !important;
  top: calc(max(var(--nuo-safe-top, 36px), 8px) + 12px) !important;
  left: 50% !important;
  right: auto !important;
  bottom: auto !important;
  transform: translateX(-50%) !important;
  display: flex !important;
  flex-direction: column !important;
  align-items: center !important;
  justify-content: flex-start !important;
  gap: 0 !important;
  width: max-content !important;
  max-width: calc(100% - 180px) !important;
  height: auto !important;
  visibility: visible !important;
  opacity: 1 !important;
  pointer-events: auto;
}

#chat-detail-screen .header-profile-section * {
  visibility: visible !important;
}

/* 移除固定头像与固定备注；保留原生资料节点和点击事件。 */
#chat-detail-screen .header-profile-section::before,
#chat-detail-screen .header-profile-section::after {
  content: none !important;
  pointer-events: none !important;
}

#chat-detail-screen .header-profile-section img {
  display: block !important;
  width: 60px !important;
  height: 60px !important;
  min-width: 60px !important;
  max-width: 60px !important;
  border-radius: 50% !important;
  object-fit: cover !important;
  opacity: 1 !important;
  box-shadow: inset 0 1px 1px rgba(255, 255, 255, .7);
}

/* 头像及外壳统一为圆形；头像与备注继续使用原生会话资料。 */
#chat-detail-screen .header-profile-section :has(> img) {
  width: 60px !important;
  height: 60px !important;
  min-width: 60px !important;
  min-height: 60px !important;
  flex: 0 0 60px !important;
  padding: 0 !important;
  margin: 0 !important;
  border-radius: 50% !important;
  overflow: hidden !important;
  clip-path: none !important;
  mask: none !important;
  -webkit-mask: none !important;
}

#chat-detail-screen .header-profile-section :is(
  .chat-header-title, .header-title, .header-name, h1, h2, h3) {
  /* 对齐原固定备注：相对头像顶端下移 56px，中心位置不变。 */
  position: absolute !important;
  top: 56px !important;
  bottom: auto !important;
  left: 50% !important;
  right: auto !important;
  transform: translateX(-50%) !important;
  width: max-content !important;
  max-width: calc(100vw - 180px) !important;
  margin: 0 !important;
  padding: 2px 13px 4px !important;
  box-sizing: border-box;
  border: 1px solid transparent !important;
  border-radius: 22px !important;
  background: var(--im-glass) !important;
  box-shadow: var(--im-glass-shadow) !important;
  color: #080808 !important;
  font: 600 17px/23px var(--im-font) !important;
  white-space: nowrap !important;
  overflow: hidden !important;
  text-overflow: ellipsis !important;
  backdrop-filter: var(--im-glass-filter) !important;
  -webkit-backdrop-filter: var(--im-glass-filter) !important;
}

#chat-detail-screen .header-profile-section .chat-header-subtitle,
#chat-detail-screen .header-profile-section .chat-header-subtitle * {
  visibility: hidden !important;
}

#chat-detail-screen :is(.header-btn-phone, .header-btn-video, .header-btn-info) {
  position: relative !important;
  visibility: hidden !important;
}
#chat-detail-screen :is(.header-btn-phone, .header-btn-video, .header-btn-info) * {
  visibility: hidden !important;
}

#chat-detail-screen :is(.header-btn-phone, .header-btn-video, .header-btn-info)::after {
  content: "";
  position: absolute;
  inset: 0;
  visibility: visible !important;
  background: transparent;
  pointer-events: auto;
}

/* 06. 系统状态栏位于聊天根节点外，用 :has 限制只在聊天页激活时生效。
 * 时间、电量进度沿用真实 DOM 数据；5G 是参考图的装饰标签。
 */
#nuo-os-root:has(#chat-detail-screen.active) #system-top-bar {
  z-index: 3000 !important;
  color: #080808 !important;
  background: transparent !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  font-family: -apple-system, BlinkMacSystemFont, "Helvetica Neue", Arial, sans-serif;
}

#nuo-os-root:has(#chat-detail-screen.active) #system-top-bar .system-left,
#nuo-os-root:has(#chat-detail-screen.active) #system-top-bar .system-left * {
  visibility: hidden !important;
}

#nuo-os-root:has(#chat-detail-screen.active) #system-top-bar .system-center {
  position: absolute !important;
  left: 28px !important;
  transform: none !important;
}

#nuo-os-root:has(#chat-detail-screen.active) #system-time-display {
  color: #080808 !important;
  background: transparent !important;
  font-size: 17px !important;
  font-weight: 600 !important;
}

#nuo-os-root:has(#chat-detail-screen.active) #system-top-bar .system-right {
  display: flex;
  align-items: center;
  gap: 6px !important;
}

#nuo-os-root:has(#chat-detail-screen.active) #system-top-bar .system-right::before {
  content: "5G";
  order: 2;
  color: #080808;
  font-size: 14px;
  line-height: 1;
}

#nuo-os-root:has(#chat-detail-screen.active) #system-top-bar .signal-dots {
  order: 1;
  display: flex;
  align-items: flex-end;
  gap: 2px !important;
  height: 14px;
}

#nuo-os-root:has(#chat-detail-screen.active) #system-top-bar .signal-dots .dot {
  width: 3px !important;
  border-radius: 1px !important;
  background: #080808 !important;
}

#nuo-os-root:has(#chat-detail-screen.active) .signal-dots .dot:nth-child(1) { height: 5px !important; }
#nuo-os-root:has(#chat-detail-screen.active) .signal-dots .dot:nth-child(2) { height: 8px !important; }
#nuo-os-root:has(#chat-detail-screen.active) .signal-dots .dot:nth-child(3) { height: 11px !important; }
#nuo-os-root:has(#chat-detail-screen.active) .signal-dots .dot:nth-child(4) { height: 14px !important; }

#nuo-os-root:has(#chat-detail-screen.active) #system-top-bar .sys-battery-pill {
  order: 3;
  border: 0 !important;
  border-radius: 4px !important;
  background: #c6c6c8 !important;
}

#nuo-os-root:has(#chat-detail-screen.active) #system-top-bar .pill-fill {
  background: #38c85b !important;
}

/* 07. 商务底栏：外观按 P2，操作沿用真实控件。
 * 384px 画布：加号 x27.5/宽39.5，胶囊 x78.5/右边356，间隔11.5。
 * 原生按钮顺序仍为麦克风 → 贴纸 → AI，36px点击区域及4px间隔不改。
 * 只把最右原按钮的图标画成麦克风，点击仍触发原按钮；发送/停止同理。
 * 没有移动麦克风按钮到末尾，没有交换事件，没有缩小透明按钮。 */
#chat-detail-screen .chat-input-area-root {
  padding: 8px 7.2917% max(27.5px, var(--nuo-safe-bottom, 0px)) 7.1615% !important;
  border: 0 !important;
  border-color: transparent !important;
  background: transparent !important;
  box-shadow: none !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  transform: none !important;
  will-change: auto !important;
  pointer-events: none;
}

#chat-detail-screen .chat-input-area-root::before {
  content: "";
  position: absolute;
  inset: -12px 0 0;
  z-index: -1;
  background: rgba(255, 255, 255, .06);
  backdrop-filter: blur(2px);
  -webkit-backdrop-filter: blur(2px);
  mask-image: linear-gradient(transparent, #000 40%);
  -webkit-mask-image: linear-gradient(transparent, #000 40%);
  pointer-events: none;
}

/* 胶囊外留白可穿透到消息列表；原生输入、按钮、菜单仍正常命中。 */
#chat-detail-screen .chat-input-area-root :is(button, textarea, input, [role="button"],
  .input-btn-plus, .input-action-bar-custom, .more-options-popup) {
  pointer-events: auto;
}

#chat-detail-screen .input-row-wrapper {
  gap: 11.5px !important;
  align-items: center !important;
  padding: 0 !important;
  border: 0 !important;
  overflow: visible !important;
  border-color: transparent !important;
  background: transparent !important;
  box-shadow: none !important;
}

#chat-detail-screen .input-btn-plus {
  position: relative;
  width: 39.5px !important;
  height: 39.5px !important;
  flex: 0 0 39.5px !important;
  margin: 0 !important;
  padding: 0 !important;
  border: 0 !important;
  border-color: transparent !important;
  border-radius: 50% !important;
  background: var(--im-glass) !important;
  box-shadow: var(--im-glass-shadow) !important;
  color: #080808 !important;
  backdrop-filter: var(--im-glass-filter) !important;
  -webkit-backdrop-filter: var(--im-glass-filter) !important;
}

#chat-detail-screen .input-btn-plus * {
  visibility: hidden !important;
}

#chat-detail-screen .input-btn-plus::before {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(#080808, #080808) center / 2px 15px no-repeat,
    linear-gradient(#080808, #080808) center / 15px 2px no-repeat;
  pointer-events: none;
}

#chat-detail-screen .input-action-bar-custom {
  position: relative !important;
  flex: 1 1 0% !important;
  min-width: 0 !important;
  min-height: 39.5px !important;
  padding: 0 2.5px 0 0 !important;
  border: 0 !important;
  border-color: transparent !important;
  border-radius: 20px !important;
  background: var(--im-glass) !important;
  /* 方向性内高光不增加边框厚度，输入及右侧按钮坐标不变。 */
  box-shadow: var(--im-glass-shadow) !important;
  backdrop-filter: var(--im-glass-filter) !important;
  -webkit-backdrop-filter: var(--im-glass-filter) !important;
}

#chat-detail-screen textarea#chat-message-input {
  visibility: visible !important;
  opacity: 1 !important;
  outline: none;
  background: transparent !important;
  box-shadow: none !important;
  color: #111 !important;
  -webkit-text-fill-color: #111 !important;
  caret-color: #111;
  font: 400 17px/22px var(--im-font) !important;
  min-width: 0 !important;
  min-height: 39.5px !important;
  padding: 8.75px 0 8.75px 17px !important;
  box-sizing: border-box;
  resize: none;
  cursor: text;
  user-select: text;
  -webkit-user-select: text;
}

#chat-detail-screen textarea#chat-message-input:placeholder-shown {
  height: 39.5px !important;
}

/* 提示层直接锚定真实 textarea 的边界，不猜测右侧按钮数量或尺寸。
 * 不支持 anchor 定位的浏览器保留原生提示文字，输入与按钮照常使用。 */
#chat-detail-screen textarea#chat-message-input::placeholder {
  color: transparent !important;
  -webkit-text-fill-color: transparent !important;
}
#chat-detail-screen .input-action-bar-custom::before,
#chat-detail-screen .input-action-bar-custom::after {
  content: none !important;
  pointer-events: none;
}
@supports (anchor-name: --im-native-input) and (left: anchor(left)) and (width: anchor-size(width)) {
  #chat-detail-screen textarea#chat-message-input {
    anchor-name: --im-native-input;
  }
  #chat-detail-screen textarea#chat-message-input::placeholder {
    color: transparent !important;
    -webkit-text-fill-color: transparent !important;
  }
  #chat-detail-screen .input-action-bar-custom:has(> textarea#chat-message-input:placeholder-shown)::after {
    content: none !important;
    position: absolute;
    position-anchor: --im-native-input;
    left: calc(anchor(left) + 17px);
    top: anchor(center);
    width: max(0px, calc(anchor-size(width) - 17px));
    transform: translateY(-50%);
    overflow: hidden;
    white-space: nowrap;
    text-overflow: ellipsis;
    color: #b9bbbd;
    font: 400 17px/22px var(--im-font);
    pointer-events: none;
