/* ============================================================
   引用块（.msg-reply-block-detached）跟随「被引用方」的气泡色
   ------------------------------------------------------------
   · 我引用对方 → 引用块/线 = 对方气泡色（浅灰 .82），文字深色
   · 对方引用我 → 引用块/线 = 我的气泡色（深灰蓝 .86），白色文字
   · --im-reply-alpha 控制引用块整体透明度
   · 连接线没有单独透明度变量，所以用 color-mix 把 alpha 混进颜色
   ============================================================ */

/* —— 我引用对方 —— */
#chat-detail-screen .msg-bubble-wrapper.msg-me
  :is(.bubble-deco-me, .bubble-deco-them):has(> .msg-reply-block-detached) {
  --im-reply-fill: var(--im-receive);
  --im-reply-alpha: var(--im-receive-alpha);   /* .82 */
  --im-reply-line: color-mix(in srgb,
    var(--im-receive) calc(var(--im-receive-alpha) * 100%),
    transparent);
}

#chat-detail-screen .msg-bubble-wrapper.msg-me
  .msg-reply-block-detached {
  color: #111 !important;
}

#chat-detail-screen .msg-bubble-wrapper.msg-me
  .msg-reply-block-detached > .msg-reply-detached-text {
  color: #111 !important;
}

/* —— 对方引用我 —— */
#chat-detail-screen .msg-bubble-wrapper.msg-them
  :is(.bubble-deco-me, .bubble-deco-them):has(> .msg-reply-block-detached) {
  --im-reply-fill: var(--im-send);
  --im-reply-alpha: var(--im-send-alpha);      /* .86 */
  --im-reply-line: color-mix(in srgb,
    var(--im-send) calc(var(--im-send-alpha) * 100%),
    transparent);
}

/* 输入框文字改灰色（只影响底部输入框，不影响气泡） */
#chat-detail-screen textarea#chat-message-input {
  color: #808080 !important;
  -webkit-text-fill-color: #808080 !important;
  caret-color: #fff !important;
}

/* placeholder：不支持 anchor 定位的浏览器走这条 */
#chat-detail-screen textarea#chat-message-input::placeholder {
  color: transparent !important;
  -webkit-text-fill-color: transparent !important;
}

/* 支持 anchor 时 placeholder 是伪元素画的，改伪元素颜色 */
#chat-detail-screen .input-action-bar-custom:has(> textarea#chat-message-input:placeholder-shown)::after {
  color: rgba(255, 255, 255, .55) !important;
}

