/* 对方气泡 */
.bubble-them-custom {
    background: rgba(255, 255, 255, 0.38) !important;

    backdrop-filter: blur(10px) saturate(160%) !important;
    -webkit-backdrop-filter: blur(10px) saturate(160%) !important;

    border: 1px solid rgba(255, 255, 255, 0.65) !important;

    /* 扁平水滴形状 */
    border-radius: 999px !important;

    /* 降低气泡高度 */
    padding: 5px 14px !important;
    line-height: 1.3 !important;

    box-shadow:
        0 2px 5px rgba(0, 0, 0, 0.045),
        inset 0 1px 2px rgba(255, 255, 255, 0.9),
        inset 0 -1px 2px rgba(220, 225, 230, 0.18) !important;

    color: #222 !important;
}

/* 我方气泡 */
.bubble-me-custom {
    background: rgba(255, 255, 255, 0.42) !important;

    backdrop-filter: blur(12px) saturate(170%) !important;
    -webkit-backdrop-filter: blur(12px) saturate(170%) !important;

    border: 1px solid rgba(255, 255, 255, 0.75) !important;

    /* 与对方保持相同的水滴形状 */
    border-radius: 999px !important;

    /* 降低气泡高度 */
    padding: 5px 14px !important;
    line-height: 1.3 !important;

    box-shadow:
        0 2px 6px rgba(0, 0, 0, 0.05),
        inset 0 1px 2px rgba(255, 255, 255, 0.95),
        inset 0 -1px 2px rgba(220, 225, 230, 0.2) !important;

    color: #222 !important;
}
