  --transfer-icon-color:var(--im-blue);
  --transfer-amount-color:var(--im-ink);
  --transfer-me-card-bg:var(--im-glass-cap);
  --transfer-me-card-border:none;
  --transfer-me-icon-bg:var(--im-glass);
