  --transfer-me-label-color:var(--im-ink-2);
  --transfer-me-subtitle-color:var(--im-ink-2);
  --transfer-me-status-color:var(--im-ink-2);
  --transfer-me-divider-color:var(--im-divider);
  --transfer-them-card-bg:var(--im-glass-cap);
  --transfer-them-card-border:none;
  --transfer-them-icon-bg:var(--im-glass);
  --transfer-them-amount-color:var(--im-ink);
  --transfer-them-label-color:var(--im-ink-2);
  --transfer-them-subtitle-color:var(--im-ink-2);
  --transfer-them-status-color:var(--im-ink-2);
  --transfer-them-divider-color:var(--im-divider);
  --transfer-success-card-bg:var(--im-glass-cap);
  --transfer-success-card-border:none;
  --transfer-success-icon-bg:var(--im-glass);
  --transfer-success-icon-color:var(--im-blue);
  --transfer-success-label-color:var(--im-blue);
  --videocall-bg-connected:var(--im-glass-cap);
  --videocall-bg-interrupted:var(--im-glass-cap);
  --videocall-bg-missed:var(--im-glass-cap);
  --videocall-border-connected:none;
  --videocall-border-interrupted:none;
  --videocall-border-missed:none;
  --videocall-shadow:none;
  --videocall-shadow-missed:none;
  --videocall-icon-bg:var(--im-glass);
  --videocall-icon-bg-missed:var(--im-glass);
  --gift-box-light:var(--im-gift-light);
  --gift-box-dark:var(--im-gift-dark);
  --gift-ribbon-color:var(--im-blue);
  --gift-ribbon-dark:#0060c0;
  --gift-shadow-color:rgba(10,132,255,0.18);
  --location-card-bg:var(--im-glass-cap);
  --location-card-border:none;
  --location-card-shadow:none;
}

/* ==========================================================
   1. 顶栏  背景透明+脱离文档流 · 图标悬空 · 头像昵称居中
   ========================================================== */
.chat-detail-screen .chat-header-custom{
  position:absolute !important; top:0 !important; left:0 !important; right:0 !important;
  z-index:50 !important;
}
.chat-detail-screen .chat-header-custom .glass-header{
  position:relative !important; top:auto !important; left:auto !important; right:auto !important;
}
.chat-detail-screen .chat-header-custom,
.chat-detail-screen .glass-header{
  background:transparent !important; background-image:none !important;
  backdrop-filter:none !important; -webkit-backdrop-filter:none !important;
  border:0 !important; border-bottom:0 !important; box-shadow:none !important;
  overflow:visible !important; pointer-events:none !important;
}
.chat-detail-screen .chat-header-custom::before,
.chat-detail-screen .chat-header-custom::after,
.chat-detail-screen .glass-header::before,
.chat-detail-screen .glass-header::after{ display:none !important; }

.chat-detail-screen .header-btn-back,
.chat-detail-screen .header-action-btn,
.chat-detail-screen .header-btn-phone,
.chat-detail-screen .header-btn-video,
.chat-detail-screen .header-btn-info,
.chat-detail-screen .header-profile-section{ pointer-events:auto !important; }

.chat-detail-screen .chat-message-list-custom{
  padding-top:calc(var(--im-top) + 142px) !important;
}

/* 退出键 */
.chat-detail-screen .header-btn-back{
  position:relative !important;
  width:34px !important; height:34px !important; min-width:34px !important;
  padding:0 !important; border-radius:9999px !important;
  display:flex !important; align-items:center !important; justify-content:center !important;
  background:var(--im-glass) !important; background-image:none !important;
  backdrop-filter:var(--im-glass-blur) !important; -webkit-backdrop-filter:var(--im-glass-blur) !important;
  border:0 !important; box-shadow:none !important; overflow:visible !important;
}
.chat-detail-screen .header-btn-back > *:not(.nuo-chat-header-unread-dot):not(.nuo-chat-header-unread-num){ opacity:0 !important; }
.chat-detail-screen .header-btn-back::before{
  content:"" !important; position:absolute; top:50%; left:50%; transform:translate(-50%,-50%);
  width:18px; height:18px; background-color:var(--im-blue); pointer-events:none;
  -webkit-mask:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='black' stroke-width='2.6' stroke-linecap='round' stroke-linejoin='round'><polyline points='15 5 8 12 15 19'/></svg>") no-repeat center/contain;
          mask:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='black' stroke-width='2.6' stroke-linecap='round' stroke-linejoin='round'><polyline points='15 5 8 12 15 19'/></svg>") no-repeat center/contain;
}

/* 通话 / 视频:隐藏原位可点 */
.chat-detail-screen .header-btn-phone,
.chat-detail-screen .header-btn-video{
  background:transparent !important; background-image:none !important;
  backdrop-filter:none !important; -webkit-backdrop-filter:none !important;
  border:0 !important; box-shadow:none !important;
}
.chat-detail-screen .header-btn-phone > *,
.chat-detail-screen .header-btn-video > *{ opacity:0 !important; }
.chat-detail-screen .header-btn-phone::before,
.chat-detail-screen .header-btn-phone::after,
.chat-detail-screen .header-btn-video::before,
.chat-detail-screen .header-btn-video::after{ content:none !important; }

/* 设置键 → 玻璃圆底+蓝色视频通话 */
.chat-detail-screen .header-btn-info{
  position:relative !important;
  width:34px !important; height:34px !important; min-width:34px !important;
  padding:0 !important; border-radius:9999px !important;
  display:flex !important; align-items:center !important; justify-content:center !important;
  background:var(--im-glass) !important; background-image:none !important;
  backdrop-filter:var(--im-glass-blur) !important; -webkit-backdrop-filter:var(--im-glass-blur) !important;
  border:0 !important; box-shadow:none !important; overflow:visible !important;
}
.chat-detail-screen .header-btn-info > *{ opacity:0 !important; }
.chat-detail-screen .header-btn-info::before{
  content:"" !important; position:absolute; top:50%; left:50%; transform:translate(-50%,-50%);
  width:19px; height:19px; background-color:var(--im-blue); pointer-events:none;
  -webkit-mask:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24'><path d='M3 7a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v10a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V7zm15 2.5l3.2-2.1c.5-.3 1.1 .05 1.1 .64v7.92c0 .59-.6 .94-1.1 .64L18 14.5v-5z'/></svg>") no-repeat center/contain;
          mask:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24'><path d='M3 7a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v10a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V7zm15 2.5l3.2-2.1c.5-.3 1.1 .05 1.1 .64v7.92c0 .59-.6 .94-1.1 .64L18 14.5v-5z'/></svg>") no-repeat center/contain;
}

/* 头像 + 昵称 + 两行小字 */
.chat-detail-screen .header-profile-section{
  position:absolute !important; left:50% !important; top:calc(var(--im-top) - 2px) !important;
  transform:translateX(-50%) !important; margin:0 !important; padding:0 !important;
  width:max-content !important; max-width:70vw !important;
  display:flex !important; flex-direction:column !important; align-items:center !important;
  gap:5px !important; background:transparent !important; z-index:2 !important;
}
.chat-detail-screen .header-profile-section > *{
  display:flex; flex-direction:column; align-items:center !important;
  margin:0 !important; text-align:center !important;
}
.chat-detail-screen .header-avatar-container,
.chat-detail-screen .chat-header-avatar{
  width:54px !important; height:54px !important; min-width:54px !important;
  border-radius:9999px !important; border:0 !important; box-shadow:none !important;
  margin:0 !important; overflow:hidden !important;
  background-size:cover !important; background-position:center !important;
}
.chat-detail-screen .header-avatar-container .chat-header-avatar{
  width:100% !important; height:100% !important; min-width:0 !important;
}
.chat-detail-screen .chat-header-title{
  display:inline-flex !important; align-items:center !important; gap:5px !important;
  margin:0 !important; padding:3px 14px !important; border-radius:9999px !important;
  background:var(--im-glass-cap) !important;
  backdrop-filter:var(--im-glass-blur) !important; -webkit-backdrop-filter:var(--im-glass-blur) !important;
  border:0 !important;
  color:#fff !important; font-size:15px !important; font-weight:600 !important; line-height:18px !important;
  white-space:nowrap !important; max-width:60vw !important; text-align:center !important;
  text-shadow:0 1px 3px rgba(0,0,0,.35) !important;
}
.chat-detail-screen .chat-header-title::after{
  content:"" !important; flex:0 0 13px; width:13px; height:13px; display:inline-block; background-color:#fff;
  -webkit-mask:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24'><path d='M9 6l6 6-6 6' fill='none' stroke='black' stroke-width='2.6' stroke-linecap='round' stroke-linejoin='round'/></svg>") no-repeat center/contain;
          mask:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24'><path d='M9 6l6 6-6 6' fill='none' stroke='black' stroke-width='2.6' stroke-linecap='round' stroke-linejoin='round'/></svg>") no-repeat center/contain;
}
.chat-detail-screen .chat-header-subtitle{ display:none !important; }
.chat-detail-screen .header-profile-section::before{
  content:"iMessage訊息" !important; order:10; display:block;
  margin-top:-1px; font-size:11px; font-weight:500; color:#fff; line-height:15px;
  white-space:nowrap; text-shadow:0 1px 3px rgba(0,0,0,.4); pointer-events:none;
}
.chat-detail-screen .header-profile-section::after{
  content:"已加密" !important; order:11; display:block;
  margin-top:-5px; padding-left:13px; font-size:10px; font-weight:600; color:#fff; line-height:15px;
  white-space:nowrap; text-shadow:0 1px 3px rgba(0,0,0,.4); pointer-events:none;
  background:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24'><path fill='white' d='M12 2a5 5 0 0 0-5 5v3H6a2 2 0 0 0-2 2v7a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2v-7a2 2 0 0 0-2-2h-1V7a5 5 0 0 0-5-5zm-3 8V7a3 3 0 0 1 6 0v3H9z'/></svg>") no-repeat left center/10px 10px;
}

/* ==========================================================
   2. 气泡  对方玻璃(同引用框)+白字 / 我方蓝+白字
            间距收紧 · 双方高度统一 · 末条文字气泡带 SVG 小尾巴
   ========================================================== */
.msg-bubble-wrapper{
  position:relative !important;
  margin-top:0 !important; margin-bottom:0 !important;
  padding-top:0 !important; padding-bottom:var(--im-bubble-gap) !important;
  gap:0 !important; min-height:0 !important;
}
.msg-bubble-wrapper.is-last,
.msg-bubble-wrapper.is-single{ padding-bottom:var(--im-group-gap) !important; }
.msg-bubble-wrapper.has-reactions{ padding-bottom:calc(var(--im-group-gap) + 14px) !important; }
.msg-content-stack{ margin:0 !important; gap:0 !important; }
.msg-me .msg-content-stack{ margin-left:auto !important; }

.bubble-me-custom, .bubble-them-custom,
.bubble-deco-me, .bubble-deco-them,
.msg-bubble-container, .msg-content-stack{ overflow:visible !important; }

.bubble-them-custom,
.bubble-me-custom{
  position:relative !important;
  border:0 !important; border-radius:var(--im-radius) !important;
  padding:6px 13px !important; margin:0 !important; box-shadow:none !important;
  min-height:0 !important; height:auto !important;
  line-height:1.4 !important; color:#fff !important;
}
.bubble-them-custom{
  background:var(--im-glass-cap) !important; background-image:none !important;
  backdrop-filter:var(--im-glass-blur) !important; -webkit-backdrop-filter:var(--im-glass-blur) !important;
  text-shadow:0 1px 2px rgba(0,0,0,.18) !important;
}
.bubble-me-custom{
  background:var(--im-blue) !important; background-image:none !important;
}
.bubble-them-custom > *,
.bubble-me-custom > *{ margin-top:0 !important; margin-bottom:0 !important; }

/* 对方尾巴 */
.msg-bubble-wrapper:is(.is-last,.is-single):not(:has([class*="card"])) .bubble-them-custom:not([class*="card"]):not(:has(img,video))::after,
.msg-bubble-wrapper:not(:has([class*="card"])) .bubble-them-custom:is(.last,.single):not([class*="card"]):not(:has(img,video))::after{
  content:"" !important; position:absolute !important;
  left:-4px; bottom:-2px; width:16px; height:16px;
  background:var(--im-glass-cap) !important; pointer-events:none; z-index:0;
  -webkit-mask:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 16 16'><path d='M16 0 C16 9 9 16 0 16 C4 14 4.5 10 4.5 0 Z'/></svg>") no-repeat 0 0/16px 16px,
               radial-gradient(circle 17px at 21px -3px, #000 16.6px, transparent 17px) no-repeat 0 0/16px 16px;
  -webkit-mask-composite:source-out;
          mask:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 16 16'><path d='M16 0 C16 9 9 16 0 16 C4 14 4.5 10 4.5 0 Z'/></svg>") no-repeat 0 0/16px 16px,
               radial-gradient(circle 17px at 21px -3px, #000 16.6px, transparent 17px) no-repeat 0 0/16px 16px;
          mask-composite:subtract;
}
/* 我方尾巴 */
.msg-bubble-wrapper:is(.is-last,.is-single):not(:has([class*="card"])) .bubble-me-custom:not([class*="card"]):not(:has(img,video))::after,
.msg-bubble-wrapper:not(:has([class*="card"])) .bubble-me-custom:is(.last,.single):not([class*="card"]):not(:has(img,video))::after{
  content:"" !important; position:absolute !important;
  right:-4px; bottom:-2px; width:16px; height:16px;
  background:var(--im-blue) !important; pointer-events:none; z-index:0;
  -webkit-mask:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 16 16'><path d='M0 0 C0 9 7 16 16 16 C12 14 11.5 10 11.5 0 Z'/></svg>") no-repeat center/100% 100%;
          mask:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 16 16'><path d='M0 0 C0 9 7 16 16 16 C12 14 11.5 10 11.5 0 Z'/></svg>") no-repeat center/100% 100%;
}

/* ==========================================================
   2b. 头像  视觉隐藏 · 对方末条头像变成贴在尾巴上的隐形心声点击区
   ========================================================== */
.msg-avatar-me-container{ display:none !important; }
.msg-bubble-wrapper .nuo-avatar-frame{ display:none !important; }

.msg-bubble-wrapper.msg-them:not(.is-last):not(.is-single) .msg-avatar-them-container,
.msg-bubble-wrapper.msg-them:not(.is-last):not(.is-single) .msg-avatar-container,
.msg-bubble-wrapper.msg-them:not(.is-last):not(.is-single) .msg-avatar-them-ghost{ display:none !important; }

.msg-bubble-wrapper.msg-them.is-last .msg-avatar-them-container,
.msg-bubble-wrapper.msg-them.is-single .msg-avatar-them-container,
.msg-bubble-wrapper.msg-them.is-last .msg-avatar-container,
.msg-bubble-wrapper.msg-them.is-single .msg-avatar-container,
.msg-bubble-wrapper.msg-them.is-last .msg-avatar-them-ghost,
.msg-bubble-wrapper.msg-them.is-single .msg-avatar-them-ghost{
  display:block !important; position:absolute !important;
  left:-10px !important; bottom:calc(var(--im-group-gap) - 12px) !important;
  top:auto !important; right:auto !important;
  width:26px !important; height:26px !important; min-width:0 !important;
  margin:0 !important; padding:0 !important; transform:none !important;
  opacity:0 !important; z-index:10 !important;
  pointer-events:auto !important; cursor:pointer !important;
  -webkit-tap-highlight-color:transparent !important;
}
.msg-bubble-wrapper.msg-them .msg-avatar-them-container > *,
.msg-bubble-wrapper.msg-them .msg-avatar-container > *,
.msg-avatar-them-inner,
.msg-bubble-wrapper.msg-them .msg-avatar-custom{
  width:100% !important; height:100% !important; min-width:0 !important;
  margin:0 !important; pointer-events:auto !important;
}

/* ==========================================================
   3. 时间戳 / 旁白 / 撤回提示  白色小字
   ========================================================== */
.timestamp-custom,
.date-divider-custom,
.msg-status-custom{
  color:#fff !important; font-weight:600 !important;
  text-shadow:0 1px 3px rgba(0,0,0,.4) !important;
}
.date-divider-custom{ background:transparent !important; }
.msg-narration-custom,
.msg-narration-custom *{
  color:#fff !important; opacity:1 !important;
  text-shadow:0 1px 3px rgba(0,0,0,.4) !important;
}
.msg-recalled,
.msg-recalled .msg-system,
.msg-recalled *{
  color:#fff !important; -webkit-text-fill-color:#fff !important; opacity:1 !important;
  text-shadow:0 1px 3px rgba(0,0,0,.4) !important;
}

/* ==========================================================
   4. 引用  独立玻璃框 · 气泡上方 · 边缘与气泡对齐不出屏
   ========================================================== */
.msg-reply-block{ display:none !important; }
.msg-reply-block-detached{
  display:flex !important; order:-1 !important;
  position:relative !important; box-sizing:border-box !important;
  flex-flow:row nowrap !important; align-items:center !important; gap:6px !important;
  width:fit-content !important; min-width:0 !important;
  max-width:min(70vw, calc(100vw - 40px)) !important;
  margin:0 0 22px 0 !important; padding:7px 42px 7px 14px !important;
  background:var(--im-glass-cap) !important;
  backdrop-filter:var(--im-glass-blur) !important; -webkit-backdrop-filter:var(--im-glass-blur) !important;
  border:0 !important; border-left:0 !important; border-radius:16px !important;
  box-shadow:none !important; transform:none !important; clip-path:none !important;
  opacity:1 !important; overflow:visible !important;
}
.msg-reply-detached-me{ align-self:flex-end !important; margin-left:0 !important; margin-right:0 !important; }
.msg-reply-detached-them{ align-self:flex-start !important; margin-left:0 !important; margin-right:0 !important; }
.msg-reply-block-detached::before{
  content:"" !important; position:absolute; right:12px; top:50%; transform:translateY(-50%);
  width:18px; height:18px; box-sizing:border-box; border-radius:9999px;
  background:transparent; border:3px solid var(--im-ring); pointer-events:none;
}
.msg-reply-block-detached::after{
  content:"添加选项 ›" !important; position:absolute; bottom:-18px; right:4px; left:auto;
  font-size:11px; font-weight:600; color:#fff; white-space:nowrap;
  text-shadow:0 1px 3px rgba(0,0,0,.4); pointer-events:none;
}
.msg-reply-detached-them::after{ right:auto !important; left:4px !important; }
.msg-reply-detached-name{
  flex:0 0 auto !important; white-space:nowrap !important;
  color:var(--im-blue) !important; font-size:13px !important; font-weight:700 !important; font-style:normal !important;
}
.msg-reply-detached-name::after{ content:"" !important; }
.msg-reply-detached-text,
.msg-reply-detached-media{
  flex:1 1 auto !important; min-width:0 !important;
  white-space:nowrap !important; overflow:hidden !important; text-overflow:ellipsis !important;
  color:var(--im-ink) !important; font-size:13px !important; font-weight:400 !important; font-style:normal !important;
  text-shadow:none !important;
}
.msg-reply-detached-media svg{ color:var(--im-ink) !important; }

/* ==========================================================
   5. 翻译  黑底白粗体浮在气泡上 · 透明展开键铺满气泡
   ========================================================== */
.msg-translation-detached{ display:none !important; }
.msg-translation-wrapper{
  position:static !important; height:0 !important; min-height:0 !important;
  margin:0 !important; padding:0 !important; line-height:0 !important;
  background:transparent !important; border:0 !important; overflow:visible !important;
}
.msg-translation-content{
  position:absolute !important; left:0 !important; right:auto !important;
  top:50% !important; bottom:auto !important; transform:translateY(-50%) !important;
  width:max-content !important; max-width:60vw !important; min-width:0 !important; margin:0 !important;
  padding:5px 12px !important; background:#000 !important;
  border:var(--im-translate-border) !important; border-radius:6px !important;
  color:#fff !important; font-size:14px !important; font-weight:700 !important; font-style:normal !important;
  line-height:1.4 !important; white-space:normal !important; word-break:break-word !important;
  opacity:1 !important; animation:none !important; text-shadow:none !important;
  box-shadow:0 4px 14px rgba(0,0,0,.35) !important; z-index:6 !important;
  pointer-events:none !important;
}
.bubble-me-custom .msg-translation-content{ left:auto !important; right:0 !important; }
.msg-translation-content *{ color:#fff !important; font-weight:700 !important; }
.msg-translation-content del,
.msg-translation-content s{ text-decoration:none !important; }

.msg-translation-btn{
  position:absolute !important; inset:0 !important;
  top:0 !important; left:0 !important; right:0 !important; bottom:0 !important;
  width:100% !important; height:100% !important; transform:none !important;
  display:block !important; margin:0 !important; padding:0 !important;
  background:transparent !important; border:0 !important; box-shadow:none !important;
  border-radius:inherit !important; outline:none !important;
  font-size:0 !important; line-height:0 !important; color:transparent !important; opacity:1 !important;
  overflow:hidden !important; z-index:5 !important; cursor:pointer !important;
  -webkit-tap-highlight-color:transparent !important;
}
.msg-translation-btn > *{ opacity:0 !important; }
.msg-translation-btn::before,
.msg-translation-btn::after{ content:none !important; }

/* ==========================================================
   6. 卡片  液态玻璃无描边 · 图标蓝
   ========================================================== */
.msg-transfer-card,
.msg-videocall-card,
.msg-loc-card,
.msg-shopask-card,
.msg-file-card{
  backdrop-filter:var(--im-glass-blur) !important; -webkit-backdrop-filter:var(--im-glass-blur) !important;
  border:0 !important; box-shadow:none !important;
}
.msg-videocall-card,
.msg-videocall-card *{ color:var(--im-ink) !important; }
.msg-videocall-icon{
  background:var(--im-glass) !important; background-image:none !important; border:0 !important;
}
.msg-videocall-icon,
.msg-videocall-icon *,
.msg-transfer-card svg{ color:var(--im-blue) !important; }

/* ==========================================================
   7. 底栏  透明 · 上移 10px · 加号玻璃圆 · 细长玻璃输入条(30px)
            语音/表情 隐形原位可点 · 回复键蓝声波 · 发送键蓝色箭头
   ========================================================== */
.input-area-custom{
  background:transparent !important; background-image:none !important;
  backdrop-filter:none !important; -webkit-backdrop-filter:none !important;
  border-top:0 !important; box-shadow:none !important;
}
.input-area-custom::before,
.input-area-custom::after{ content:none !important; }
.input-row-wrapper{
  align-items:flex-end !important; gap:8px !important;
  margin-bottom:var(--im-bar-lift) !important;
}

.input-btn-plus{
  position:relative !important; flex:0 0 32px !important;
  width:32px !important; height:32px !important; min-width:32px !important;
  padding:0 !important; margin:0 !important; border-radius:9999px !important;
  background:var(--im-glass) !important; background-image:none !important;
  backdrop-filter:var(--im-glass-blur) !important; -webkit-backdrop-filter:var(--im-glass-blur) !important;
  border:0 !important; box-shadow:none !important; color:transparent !important;
}
.input-btn-plus > *{ opacity:0 !important; }
.input-btn-plus::after{
  content:"" !important; position:absolute; inset:0; background-color:var(--im-blue); pointer-events:none;
  -webkit-mask:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24'><path d='M12 5v14M5 12h14' fill='none' stroke='black' stroke-width='2.4' stroke-linecap='round'/></svg>") no-repeat center/15px 15px;
          mask:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24'><path d='M12 5v14M5 12h14' fill='none' stroke='black' stroke-width='2.4' stroke-linecap='round'/></svg>") no-repeat center/15px 15px;
}

.input-action-bar-custom{
  position:relative !important; flex:1 1 auto !important;
  min-height:var(--im-input-h) !important; padding:0 4px 0 0 !important;
  display:flex !important; align-items:center !important;
  background:var(--im-glass-cap) !important; background-image:none !important;
  backdrop-filter:var(--im-glass-blur) !important; -webkit-backdrop-filter:var(--im-glass-blur) !important;
  border:0 !important; border-radius:18px !important; box-shadow:none !important;
}
.input-box-custom{
  background:transparent !important; border:0 !important; outline:none !important; box-shadow:none !important;
  border-radius:18px !important; min-height:0 !important;
  padding:5px 4px 5px 14px !important; line-height:20px !important; font-size:15px !important;
  color:var(--im-ink) !important; -webkit-text-fill-color:var(--im-ink) !important; caret-color:var(--im-blue) !important;
}
.input-box-custom::placeholder{ color:transparent !important; -webkit-text-fill-color:transparent !important; }
.input-action-bar-custom:has(.input-box-custom:placeholder-shown)::before{
  content:"iMessage"; position:absolute; left:14px; top:50%; transform:translateY(-50%);
  color:var(--im-placeholder); font-size:15px; font-family:-apple-system,system-ui,sans-serif;
  pointer-events:none; z-index:1;
}

/* 语音 / 表情包:隐形,原位保留点击 */
.input-btn-mic,
.input-btn-sticker{
  display:flex !important; opacity:0 !important;
  pointer-events:auto !important; cursor:pointer !important;
  background:transparent !important; box-shadow:none !important;
  -webkit-tap-highlight-color:transparent !important;
}

.input-btns-right{ align-items:center !important; gap:4px !important; }

/* 回复键(AI键):蓝色声波 */
.input-btn-ai{
  position:relative !important; flex:0 0 28px !important;
  width:28px !important; height:28px !important; min-width:28px !important;
  padding:0 !important; margin:0 !important;
  background:transparent !important; background-image:none !important;
  border:0 !important; box-shadow:none !important; color:transparent !important;
}
.input-btn-ai > *{ opacity:0 !important; }
.input-btn-ai::after{
  content:"" !important; position:absolute; inset:0; background-color:var(--im-blue); pointer-events:none;
  -webkit-mask:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24'><g fill='none' stroke='black' stroke-width='1.9' stroke-linecap='round'><path d='M4 11v2M8 8v8M12 5v14M16 8v8M20 11v2'/></g></svg>") no-repeat center/22px 22px;
          mask:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24'><g fill='none' stroke='black' stroke-width='1.9' stroke-linecap='round'><path d='M4 11v2M8 8v8M12 5v14M16 8v8M20 11v2'/></g></svg>") no-repeat center/22px 22px;
}

/* 发送键:蓝色向上箭头 */
.send-btn-custom{
  position:relative !important; flex:0 0 28px !important;
  width:28px !important; height:28px !important; min-width:28px !important;
  padding:0 !important; margin:0 !important; border-radius:0 !important;
  background:transparent !important; background-image:none !important;
  border:0 !important; box-shadow:none !important; color:transparent !important;
}
.send-btn-custom > *{ opacity:0 !important; }
.send-btn-custom::after{
  content:"" !important; position:absolute; inset:0; background-color:var(--im-blue); pointer-events:none;
  -webkit-mask:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='black' stroke-width='2.6' stroke-linecap='round' stroke-linejoin='round'><path d='M12 20V4M5 11l7-7 7 7'/></svg>") no-repeat center/20px 20px;
          mask:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='black' stroke-width='2.6' stroke-linecap='round' stroke-linejoin='round'><path d='M12 20V4M5 11l7-7 7 7'/></svg>") no-repeat center/20px 20px;
}

/* ==========================================================
   8. 思维链  「◎ Live ⌄」胶囊 · 展开时箭头翻转
   ========================================================== */
.nuo-thinking-btn{
  display:inline-flex !important; align-items:center !important; gap:4px !important;
  width:auto !important; height:auto !important;
  padding:3px 9px 3px 7px !important; border-radius:9999px !important;
  background:var(--im-thinking-bg) !important; background-image:none !important;
  backdrop-filter:var(--im-glass-blur) !important; -webkit-backdrop-filter:var(--im-glass-blur) !important;
  border:1px solid var(--im-thinking-border) !important; box-shadow:none !important;
  color:var(--im-live-color) !important; overflow:visible !important;
}
.nuo-thinking-btn .nuo-thinking-arrow,
.nuo-thinking-btn .nuo-thinking-icon{ display:none !important; }
.nuo-thinking-btn .nuo-thinking-label{
  font-size:0 !important; line-height:0 !important; color:transparent !important;
  display:inline-flex !important; align-items:center !important;
}
.nuo-thinking-btn .nuo-thinking-label::after{
  content:"Live" !important;
  font-size:14px; font-weight:600; line-height:18px; letter-spacing:.2px;
  color:var(--im-live-color); font-family:-apple-system,system-ui,sans-serif;
}
.nuo-thinking-btn::before{
  content:"" !important; position:static !important; inset:auto !important; opacity:1 !important;
  flex:0 0 16px; width:16px; height:16px; order:-1;
  background:var(--im-live-color) !important;
  -webkit-mask:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='black'><circle cx='12' cy='12' r='2.6' fill='black' stroke='none'/><circle cx='12' cy='12' r='5.6' stroke-width='1.8'/><circle cx='12' cy='12' r='9.4' stroke-width='1.6' stroke-dasharray='1.2 2.1' stroke-linecap='round'/></svg>") no-repeat center/contain;
          mask:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='black'><circle cx='12' cy='12' r='2.6' fill='black' stroke='none'/><circle cx='12' cy='12' r='5.6' stroke-width='1.8'/><circle cx='12' cy='12' r='9.4' stroke-width='1.6' stroke-dasharray='1.2 2.1' stroke-linecap='round'/></svg>") no-repeat center/contain;
}
.nuo-thinking-btn::after{
  content:"" !important; position:static !important; inset:auto !important; opacity:1 !important;
  flex:0 0 13px; width:13px; height:13px; order:99; margin-left:2px;
  background:var(--im-live-color) !important;
  transition:transform .2s ease;
  -webkit-mask:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='black' stroke-width='2.8' stroke-linecap='round' stroke-linejoin='round'><path d='M6 9l6 6 6-6'/></svg>") no-repeat center/contain;
          mask:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='black' stroke-width='2.8' stroke-linecap='round' stroke-linejoin='round'><path d='M6 9l6 6 6-6'/></svg>") no-repeat center/contain;
}
.nuo-thinking-btn.is-open::after{ transform:rotate(180deg); }

/* ==========================================================
   9. 夜间模式  跟随系统深色自动切换(只换颜色变量)
   ========================================================== */
@media (prefers-color-scheme: dark){
  :root, .chat-detail-screen{
    --im-glass:rgba(118,118,128,0.26);
    --im-glass-strong:rgba(70,70,76,0.45);
    --im-glass-cap:rgba(58,58,62,0.58);
    --im-ink:#f2f2f7;
    --im-ink-2:#c7c7cc;
    --im-placeholder:#8e8e93;
    --im-ring:rgba(235,235,245,0.45);
    --im-divider:rgba(255,255,255,0.10);
    --im-live-color:#aeaeb2;
    --im-thinking-bg:rgba(44,44,46,0.62);
    --im-thinking-border:rgba(235,235,245,0.18);
    --im-translate-border:1px solid rgba(255,255,255,0.14);
    --im-gift-light:#3a3a3c;
    --im-gift-dark:#2c2c2e;

    /* 想让夜间换一张壁纸,取消下面这行注释并填链接 */
    /* --chat-bg-image:url('https://你的夜间壁纸.jpg'); */
  }
}

/*⁣‌⁠⁠​⁠⁠⁠‌‍‍​​​⁠‍⁠‌‌​‍‍‍‌‌​‌⁠‍⁠⁠‍‌​⁠⁠‍⁠‌‍‌‍⁠​⁠⁠⁠⁠‍​⁠‍‍​​‌‍⁠‌⁠‍​​‌‍⁣ ============================================================
   0. 全局变量
   ============================================================ */
:root {
  /* 顶栏 */
  --chat-header-bg: #f5f5f5;
  --chat-header-blur: 0px;
  --chat-header-border: #e5e5e5;

  /* 底栏 + 输入框 */
  --input-area-bg: #f5f5f5;
  --input-box-bg: #ffffff;
  --input-box-border: 1px solid rgba(0, 0, 0, 0.08);
  --input-box-radius: 10px;
  --input-box-color: #1f2329;
  --input-box-placeholder: #aaa;
  --input-box-shadow: 0 1px 2px rgba(0, 0, 0, 0.03);

  /* 消息宽度 */
  --chat-message-max-width: 78%;
  --plain-content-max-width: 78%;

  /* 顶栏图标 */
  --video-btn-icon: url('https://imgbed.heliar.top/i/kC9glas-HURhTZJh_retouch_2026092915185482.png');
  --info-btn-icon: url('https://imgbed.heliar.top/i/cfvt-_qsF6P04iPc_retouch_2026092915191360.png');
}

/* ============================================================
   1. 顶栏（拉高 + 整体下移 + 名字红色）
   ============================================================ */
.chat-header-custom,
.glass-header {
  height: 96px !important; /* 拉高 */
  min-height: 96px !important;
  padding-top: 36px !important; /* 整体下移 */
}

.header-avatar-container {
  display: none !important;
}

/* 名字下移 */
.header-profile-section {
  margin-left: -8px !important;
  transform: translateY(8px) !important; 
}

.chat-header-title {
  color: #ff334b !important; /* 名字红色 */
  position: relative !important;
  overflow: visible !important;
  width: fit-content !important;
  max-width: fit-content !important;
  min-width: 0 !important;
  padding: 0 !important;
  margin: 0 !important;
  flex: 0 0 auto !important;
}

.chat-header-title::after {
  content: "" !important;
  position: absolute !important;
  left: 100% !important;
  top: 50% !important;
  transform: translateY(-50%) !important;
  margin-left: 0 !important;
  width: 160px !important;
  height: 160px !important;
  background: url('https://imgbed.heliar.top/i/zFSDepEMIWFjvrN9_%E6%97%A0%E6%A0%87%E9%A2%9825_20260920193516.png') no-repeat center / contain !important;
  pointer-events: none !important;
}

.header-btn-phone svg {
  display: none !important;
}

/* 返回键下移 */
.header-btn-back {
  transform: translateY(8px) !important; 
}

/* 右侧图标下移 */
.header-action-btn,
.header-btn-video,
.header-btn-info {
  transform: translateY(8px) !important; 
}

/* ============================================================
   2. 气泡本体（文字整体往左微调）
   ============================================================ */
.msg-me .bubble-me-custom,
.msg-them .bubble-them-custom {
  position: relative !important;
  color: #000000 !important;
  font-size: 14px !important;
  line-height: 1.38 !important;
  box-shadow: none !important;
  overflow: visible !important;
  background: transparent !important;
  border: 1px solid transparent !important;
  border-radius: 0 !important;
  box-sizing: border-box !important;

  /* 核心换行黄金搭档 */
  width: max-content !important;
  max-width: 260px !important;
  word-break: break-all !important;
  white-space: normal !important;
}

/* 对方气泡（左 24->20，右 10->14，文字往左） */
.msg-them .bubble-them-custom {
  border-image-source: url("https://imgbed.heliar.top/i/lePXSYKX37e2HGAt_IMG_20261004_232036.png") !important;
  border-image-slice: 800 728 800 998 fill !important;
  border-image-width: 20px 18px 20px 25px !important;
  border-image-outset: 0 !important;
  border-image-repeat: stretch !important;
