  min-width: 43px !important;
  min-height: 40px !important;
}

/* 我方气泡（左 21->17，右 13->17，文字往左） */
.msg-me .bubble-me-custom {
  border-image-source: url("https://imgbed.heliar.top/i/_VB58QgSEYuSkwM4_retouch_2026100423114146.png") !important;
  border-image-slice: 735 963 735 881 fill !important;
  border-image-width: 20px 27px 20px 24px !important;
