}

.msg-content-stack { max-width: 100% !important; }
.msg-me .msg-content-stack { max-width: 100% !important; }
.msg-bubble-wrapper { width: 100% !important; }

.msg-me .bubble-me-custom::after,
.msg-them .bubble-them-custom::before {
  display: none !important;
}

/* ============================================================
   3. 底栏（完全保留 A 基础原样）
   ============================================================ */
.input-area-custom {
  position: relative !important;
  min-height: 95px !important;
  padding: 4px 0px 60px 0px !important;
  box-sizing: border-box !important;
}

.input-area-custom::after {
  content: "" !important;
  position: absolute !important;
  left: 50% !important;
  bottom: -8px !important;
  transform: translateX(-50%) !important;
  width: 360px !important;
  height: 86px !important;
  background: url('https://imgbed.heliar.top/i/NRpPzzXAZtvxEz1t_retouch_2026092916173517.png') no-repeat center / contain !important;
  pointer-events: none !important;
}

.input-row-wrapper {
  justify-content: flex-start !important;
  padding-left: 0 !important;
  margin-left: -12px !important;
}

.input-action-bar-custom {
  margin-left: -12px !important;
  margin-right: auto !important;
  transform: translateX(-12px) !important;
  border-radius: 14px !important;
  padding-top: 0px !important;
  padding-bottom: 0px !important;
  min-height: 0 !important;
  flex: 1 1 auto !important;
  max-width: 75% !important;
  align-items: center !important;
}

.input-box-custom {
  border-radius: 0 !important;
  padding-top: 3px !important;
  padding-bottom: 3px !important;
  min-height: 0 !important;
  line-height: 1.2 !important;
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  font-size: 15px !important;
  color: #262626 !important;
  flex: 1 1 auto !important;
}

.input-box-custom::placeholder {
  color: transparent !important;
  -webkit-text-fill-color: transparent !important;
  opacity: 0 !important;
}
.input-box-custom::before {
  content: none !important;
  display: none !important;
}

.input-btns-right {
  gap: 6px !important;
  flex-shrink: 0 !important;
}

.input-btn-plus {
  transform: translate(353px, 43px) !important;
}
.input-btn-plus svg {
  display: none !important;
}

/* ============================================================
   4. 发送键 + AI 键（灰色系）
   ============================================================ */
.input-btn-ai svg,
.input-btn-ai > *,
.send-btn-custom svg,
.send-btn-custom > * {
  display: none !important;
}

.input-btn-ai,
.send-btn-custom {
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  min-width: 54px !important;
  height: 32px !important;
  padding: 0 12px !important;
  border-radius: 8px !important;
  font-size: 13px !important;
  font-weight: 500 !important;
  border: none !important;
