    --chat-header-bg: transparent;
    --chat-header-blur: 0px;
    --chat-header-border: transparent;
    --chat-header-title-color: #ffffff;
    --chat-header-title-size: 13px;
    --chat-header-title-weight: 600;
    --chat-header-subtitle-color: transparent;
    --chat-header-icon-color: #ffffff;

    --bubble-me-bg: rgba(11, 132, 255, 0.7);
    --bubble-me-bg-gradient: initial;
    --bubble-me-color: #ffffff;
    --bubble-me-border: 1px solid rgba(255, 255, 255, 0.25);
    --bubble-me-shadow: 0 2px 12px rgba(11, 132, 255, 0.2), inset 0 1px 0 rgba(255,255,255,0.2);
    --bubble-me-radius: 20px;
    --bubble-me-radius-first: 20px 20px 4px 20px;
    --bubble-me-radius-mid: 20px 4px 4px 20px;
    --bubble-me-radius-last: 20px 4px 20px 20px;

    --bubble-them-bg: rgba(120, 120, 128, 0.35);
    --bubble-them-color: #ffffff;
    --bubble-them-border: 1px solid rgba(255, 255, 255, 0.2);
    --bubble-them-shadow: 0 2px 12px rgba(0, 0, 0, 0.08), inset 0 1px 0 rgba(255,255,255,0.15);
    --bubble-them-radius: 20px;
    --bubble-them-radius-first: 20px 20px 20px 4px;
    --bubble-them-radius-mid: 4px 20px 20px 4px;
    --bubble-them-radius-last: 4px 20px 20px 20px;

    --input-area-bg: transparent;
    --input-area-blur: 0px;
    --input-area-border-top: transparent;

    --input-box-bg: rgba(120, 120, 128, 0.28);
    --input-box-color: #ffffff;
    --input-box-placeholder: rgba(255, 255, 255, 0.5);
    --input-box-radius: 22px;
    --input-box-padding: 8px 12px;
    --input-box-border: 1px solid rgba(255, 255, 255, 0.2);
    --input-box-blur: blur(24px) saturate(180%);
    --input-box-shadow: 0 4px 20px rgba(0, 0, 0, 0.12), inset 0 1px 0 rgba(255, 255, 255, 0.18);

    --send-btn-bg: #0B84FF;
