    --plus-btn-color: #ffffff;

    --timestamp-color: rgba(255, 255, 255, 0.55);
    --date-divider-bg: rgba(255, 255, 255, 0.12);
    --date-divider-color: rgba(255, 255, 255, 0.6);
}

/* ===== Header - 浮动透明，液态玻璃按钮 ===== */

