}

/* =================================== */
/* 1. 名字位置与颜色 */
.chat-header-title {
  color: var(--top-name-color) !important;
  margin-left: -4px !important;
  transform: translate(var(--top-name-x, 0px), var(--top-name-y, 0px)) !important;
}

/* =================================== */
/* 2. 返回键位置与颜色 */
