/* =================================== */
/* 伪造双层底栏：底部六个装饰图标（自由排版版） */

:root {
  /* 👇 第二行装饰图标的左右位置魔法开关 (0%是最左边，100%是最右边) */
  --icon-1-pos: 3%;    /* 麦克风 */
  --icon-2-pos: 21%;   /* 相册 */
  --icon-3-pos: 41%;   /* 相机 */
  --icon-4-pos: 61%;   /* 红包 */
  --icon-5-pos: 80%;   /* 表情 */
  --icon-6-pos: 98%;   /* 加号 */

