:root {
  /* === 我方气泡 === */
  --bubble-me-bg: #9eea6a;
  --bubble-me-bg-gradient: initial;
  --bubble-me-color: #191919;
  --bubble-me-font-size: 15px;
  --bubble-me-line-height: 1.4;
  --bubble-me-padding: 8px 10px;
  --bubble-me-radius: 3px;
  --bubble-me-radius-first: 3px 3px 3px 3px;
  --bubble-me-radius-mid: 3px 3px 3px 3px;
  --bubble-me-radius-last: 3px 3px 3px 3px;
  --bubble-me-shadow: none;
  --bubble-me-border: none;
  --bubble-me-link-color: #576b95;

  /* === 对方气泡 === */
  --bubble-them-bg: #f5f5f5;
  --bubble-them-bg-gradient: initial;
  --bubble-them-color: #191919;
  --bubble-them-font-size: 15px;
  --bubble-them-line-height: 1.4;
  --bubble-them-padding: 8px 10px;
  --bubble-them-radius: 3px;
  --bubble-them-radius-first: 3px 3px 3px 3px;
  --bubble-them-radius-mid: 3px 3px 3px 3px;
  --bubble-them-radius-last: 3px 3px 3px 3px;
  --bubble-them-shadow: none;
  --bubble-them-border: none;
  --bubble-them-link-color: #576b95;
}

/* === 我方气泡本体 + 尾巴 === */
.bubble-me-custom {
  position: relative !important;
}
.bubble-me-custom::after {
  content: "" !important;
  position: absolute !important;
  top: 11px !important;
  right: -5px !important;
  width: 0 !important;
  height: 0 !important;
  border-style: solid !important;
  border-width: 6px 0 6px 6px !important;
  border-color: transparent transparent transparent var(--bubble-me-bg) !important;
  z-index: 1 !important;
}

/* === 对方气泡本体 + 尾巴 === */
.bubble-them-custom {
  position: relative !important;
}
.bubble-them-custom::after {
  content: "" !important;
  position: absolute !important;
  top: 11px !important;
  left: -5px !important;
  width: 0 !important;
  height: 0 !important;
  border-style: solid !important;
  border-width: 6px 6px 6px 0 !important;
  border-color: transparent var(--bubble-them-bg) transparent transparent !important;
  z-index: 1 !important;
}

/* 修正：将 ::before 改为 ::after，并统一隐藏条件 */
.bubble-me-custom.mid::after,
.bubble-me-custom.last::after,
.bubble-them-custom.mid::after,
.bubble-them-custom.last::after {
  display: none !important;
}

/* === 启用气泡外独立引用条 === */
.msg-reply-block-detached {
  display: flex !important;
  background: #e8e8e8 !important;
  backdrop-filter: none !important;
  border-radius: 4px !important;
  padding: 6px 10px !important;
  margin-top: 4px !important;
  border: none !important;
  color: #888888 !important;
}

/* 我方独立引用条 */
.msg-reply-detached-me {
  background: #e8e8e8 !important;
}

/* 对方独立引用条 */
.msg-reply-detached-them {
  background: #e8e8e8 !important;
}

/* === 关掉气泡内原本的引用块，避免和独立引用条重复显示 === */
.msg-reply-block {
  display: none !important;
}

/* 移除图片/转账卡片三角尾巴 */
.bubble-me-custom:has(img)::before,
.bubble-me-custom:has(img)::after,
.bubble-them-custom:has(img)::before,
.bubble-them-custom:has(img)::after,
.bubble-me-custom:has(.msg-transfer-card)::before,
.bubble-me-custom:has(.msg-transfer-card)::after,
.bubble-them-custom:has(.msg-transfer-card)::before,
.bubble-them-custom:has(.msg-transfer-card)::after,
.bubble-me-custom:has(.msg-image-wrapper)::before,
.bubble-me-custom:has(.msg-image-wrapper)::after,
.bubble-them-custom:has(.msg-image-wrapper)::before,
.bubble-them-custom:has(.msg-image-wrapper)::after,
.msg-image-wrapper::before,
.msg-image-wrapper::after,
.msg-transfer-card::before,
.msg-transfer-card::after {
  display: none !important;
  content: none !important;
}

.msg-image-wrapper,
.msg-transfer-card,
.bubble-me-custom:has(img),
.bubble-them-custom:has(img),
.bubble-me-custom:has(.msg-transfer-card),
.bubble-them-custom:has(.msg-transfer-card) {
  clip-path: none !important;
