/* 仿qq2.0(黑白，黑气泡) by点星 禁止二传 */
/* ============================================
   全局配色说明
   ⚠️ 顶栏底色：白色 | 底栏底色：白色
   ⚠️ 顶栏备注：金色（不变）
   ⚠️ 顶栏图标：黑色
   ⚠️ 我方气泡：黑色底 + 白色字
   ⚠️ 对方气泡：黑色底 + 白色字
   ⚠️ 底栏背景图：浅灰色
   ============================================ */

:root {
  /* ==========================================
     顶栏底色：白色
     ⚠️ 调色：#ffffff 纯白
     ========================================== */
  --chat-header-bg: #ffffff !important;

  /* ==========================================
     底栏底色：白色
     ========================================== */
  --input-area-bg: #ffffff !important;

  /* ==========================================
     备注标题颜色：金色（不变）
     ⚠️ 请勿改色
     ========================================== */
  --chat-header-title-color: #d4af37 !important;

  /* ==========================================
     顶栏高度（请勿改动）
     ========================================== */
  --chat-header-height: 66px !important;

  /* ==========================================
     我方气泡：黑色底，白色字
     ⚠️ 调色：#1a1a1a 黑底 | #ffffff 白色字
     ========================================== */
  --bubble-me-bg: #1a1a1a;
  --bubble-me-color: #ffffff;
  --bubble-me-padding: 6px 10px;
  --bubble-me-font-size: 13px;
  --bubble-me-line-height: 1.3;
  --bubble-me-radius: 14px;
  --bubble-me-radius-first: 14px 14px 4px 14px;
  --bubble-me-radius-mid: 14px 4px 4px 14px;
  --bubble-me-radius-last: 14px 4px 14px 14px;
  --bubble-me-shadow: none;
  --bubble-me-border: none;

  /* ==========================================
     对方气泡：黑色底，白色字
     ⚠️ 调色：#1a1a1a 黑底 | #ffffff 白色字
     ========================================== */
  --bubble-them-bg: #1a1a1a;
  --bubble-them-color: #ffffff;
  --bubble-them-padding: 6px 10px;
  --bubble-them-font-size: 13px;
  --bubble-them-line-height: 1.3;
  --bubble-them-radius: 14px;
  --bubble-them-radius-first: 14px 14px 14px 4px;
  --bubble-them-radius-mid: 4px 14px 14px 4px;
  --bubble-them-radius-last: 4px 14px 14px 14px;
  --bubble-them-shadow: none;
  --bubble-them-border: none;

  --chat-message-max-width: 65%;

  /* ==========================================
     转账卡片
     ========================================== */
  --transfer-card-bg: #ffffff;
  --transfer-me-card-bg: #1a1a1a;
  --transfer-me-card-border: none;
  --transfer-me-card-shadow: none;
  --transfer-them-card-bg: #1a1a1a;
  --transfer-them-card-border: none;
  --transfer-them-card-shadow: none;
  --transfer-success-card-bg: #1a1a1a;
  --transfer-rejected-card-bg: #1a1a1a;
  --transfer-expired-card-bg: #1a1a1a;
  --transfer-card-radius: 14px;
  --transfer-card-shadow: none;
  --transfer-card-border: none;

  /* ==========================================
     语音消息
     ========================================== */
  --voice-me-color: #ffffff;
  --voice-them-color: #ffffff;

  /* ==========================================
     翻译内容
     ========================================== */
  --translation-btn-color: #ffffff;
  --translation-text-color: #ffffff;
  --translation-bg: rgba(255,255,255,0.02);

  /* ==========================================
     引用 & 回复
     ========================================== */
  --reply-block-name-color: #ffffff;
  --reply-block-text-color: #ffffff;
  --quote-text-color: #ffffff;
  --quote-border-color: rgba(255, 255, 255, 0.3);
  --code-color: #ffffff;
  --code-bg: rgba(255, 255, 255, 0.08);
  --reply-me-name-color: #ffffff;
  --reply-me-text-color: #ffffff;
  --reply-me-bg: rgba(255, 255, 255, 0.06);
