margin-left: auto !important;
}
/* 对方发的图片靠左贴头像 */
.msg-them .msg-bubble-container img {
display: block !important;
margin-right: auto !important;
}
/* 强制缩小引用框里的图片并裁成正方形 */
.msg-bubble-wrapper .msg-reply-block-detached img,
.msg-reply-detached-text img {
    width: 28px !important;
    height: 28px !important;
    max-width: 28px !important; 
    max-height: 28px !important;
    object-fit: cover !important; /* 👈 关键：填满并裁剪 */
    aspect-ratio: 1 / 1 !important; /* 👈 强制正方形 */
    border-radius: 3px !important;
    vertical-align: middle !important;
    display: inline-block !important;
    margin: 0 4px !important;
}
/* 引用框内容顶部齐平 */
.msg-reply-block-detached {
    align-items: flex-start !important; 
}
/* 名字稍微往下压一点，和图片视觉边缘对齐 */
.msg-reply-detached-name {
    margin-top: 0px !important; 
}

/* =================================== */
/* 🛠️ 顶栏整体高度与内容上下调节 */
/* =================================== */
:root {
  /* 👇 1. 控制“顶栏背景”整体的高度/厚度 */
  /* 数值越大，顶栏的背景色块就越向下延伸，显得越厚。 */
  /* 如果你想避开手机顶部的刘海或状态栏，可以把这个数值改大。 */
  --new-top-bar-height: 95px;

  /* 👇 2. 控制顶栏里“所有东西（名字、返回键、设置）”的整体上下移动 */
  /* 如果你把上面的顶栏调厚了，里面的字可能会偏上。把这个数值改大（比如 45px），就能把它们整体往下推居中。 */
  --new-top-content-y: 45px;
}

/* --- 自动执行区（小白不用管下面） --- */
/* 强制覆盖顶栏容器的高度和内部顶部留白 */
.chat-header,
.chat-header-custom {
  height: var(--new-top-bar-height) !important;
  padding-top: var(--new-top-content-y) !important;
  box-sizing: border-box !important;
}

:root {
  /* 👇 顶栏改色魔法开关 */
  --top-back-color: #a0a0a0;   /* 返回键颜色 */
  --top-name-color: #a0a0a0;   /* 名字备注颜色 */
  --top-menu-color: #a0a0a0;   /* 三条杠颜色 */

  /* 👇 顶栏位置调节魔法开关 */
  --top-back-x: 0px;   /* 返回键左右挪：正数往右，负数往左 */
  --top-back-y: 5px;   /* 返回键上下挪：正数往下，负数往上 */
  --top-name-x: 0px;   /* 名字备注左右挪 */
  --top-name-y: 5px;   /* 名字备注上下挪 */
  --top-menu-x: 0px;   /* 三条杠左右挪 */
  --top-menu-y: 5px;   /* 三条杠上下挪 */

  /* 顶栏纯白底色，去掉模糊和边框 */
  --chat-header-bg: #ffffff;
  --chat-header-blur: 0px;
  --chat-header-border: none;
}

/* =================================== */
/* 强制隐藏原本的视频、设置图标、头像和电话图标 */
.header-btn-video svg,
.header-btn-info svg {
  display: none !important;
}
.header-avatar-container {
  display: none !important;
}
.header-btn-phone {
  opacity: 0 !important;
}

/* =================================== */
/* 1. 名字位置与颜色 */
.chat-header-title {
  color: var(--top-name-color) !important;
  margin-left: -4px !important;
  transform: translate(var(--top-name-x, 0px), var(--top-name-y, 0px)) !important;
}

/* =================================== */
/* 2. 返回键位置与颜色 */
.header-btn-back {
  color: var(--top-back-color) !important;
  transform: translate(var(--top-back-x, 0px), var(--top-back-y, 0px)) !important;
}
.header-btn-back svg {
  stroke: var(--top-back-color) !important;
}

/* =================================== */
/* 3. 三条杠 (设置) 蒙版改色与位置 */
.header-btn-info {
