/* =================================== */
/* 🛠️ 顶栏整体高度与内容上下调节 */
/* =================================== */
:root {
  /* 👇 1. 控制“顶栏背景”整体的高度/厚度 */
  /* 数值越大，顶栏的背景色块就越向下延伸，显得越厚。 */
  /* 如果你想避开手机顶部的刘海或状态栏，可以把这个数值改大。 */
  --new-top-bar-height: 95px;

  /* 👇 2. 控制顶栏里“所有东西（名字、返回键、设置）”的整体上下移动 */
  /* 如果你把上面的顶栏调厚了，里面的字可能会偏上。把这个数值改大（比如 45px），就能把它们整体往下推居中。 */
  --new-top-content-y: 45px;
}

/* --- 自动执行区（小白不用管下面） --- */
/* 强制覆盖顶栏容器的高度和内部顶部留白 */
.chat-header,
.chat-header-custom {
  height: var(--new-top-bar-height) !important;
  padding-top: var(--new-top-content-y) !important;
  box-sizing: border-box !important;
}

:root {
  /* 👇 顶栏改色魔法开关 */
  --top-back-color: #a0a0a0;   /* 返回键颜色 */
  --top-name-color: #a0a0a0;   /* 名字备注颜色 */
  --top-menu-color: #a0a0a0;   /* 三条杠颜色 */

  /* 👇 顶栏位置调节魔法开关 */
  --top-back-x: 0px;   /* 返回键左右挪：正数往右，负数往左 */
  --top-back-y: 5px;   /* 返回键上下挪：正数往下，负数往上 */

  /* 👇 视频键（打勾框）位置调节 */
  --top-video-x: 0px;      /* 视频键左右挪 */
  --top-video-y: 5px;      /* 视频键上下挪 */
  --top-menu-x: 0px;   /* 设置左右挪 */
  --top-menu-y: 5px;   /* 设置上下挪 */

  /* 顶栏纯白底色，去掉模糊和边框 */
  --chat-header-bg: #ffffff;
  --chat-header-blur: 0px;
  --chat-header-border: none;
}

/* =================================== */
/* 强制隐藏原本的视频、设置图标、头像和电话图标 */
.header-btn-video svg,
.header-btn-info svg {
  display: none !important;
}
.header-avatar-container {
  display: none !important;
}
.header-btn-phone {
  opacity: 0 !important;
}
.header-btn-video svg {
  display: none !important;
}

.header-btn-video svg {
  display: none !important;
}

.header-btn-video {
