:root {
  /* 👇 气泡魔法开关 */
  /* 我方气泡 */
  --bubble-me-bg: #a0a0a0;
  --bubble-me-color: #ffffff;
  --bubble-me-radius: 20px;
  --bubble-me-radius-first: 10px;
  --bubble-me-radius-mid: 10px;
  --bubble-me-radius-last: 10px;

  /* 对方气泡 */
  --bubble-them-bg: #f0f0f0;
  --bubble-them-color: #262626;
  --bubble-them-radius: 20px;
  --bubble-them-radius-first: 10px;
  --bubble-them-radius-mid: 10px;
  --bubble-them-radius-last: 10px;

/* 👇 气泡内边距（胖瘦）魔法开关 */
  --me-pad-top: 8px;
  --me-pad-bottom: 8px;
  --me-pad-left: 10px;
  --me-pad-right: 10px;

  --them-pad-top: 8px;
  --them-pad-bottom: 8px;
  --them-pad-left: 10px;
  --them-pad-right: 10px;

  --bubble-me-border: none;
  --bubble-me-shadow: none;
  --bubble-them-border: none;
  --bubble-them-shadow: none;

  --bubble-me-padding: var(--me-pad-top) var(--me-pad-right) var(--me-pad-bottom) var(--me-pad-left);
  --bubble-them-padding: var(--them-pad-top) var(--them-pad-right) var(--them-pad-bottom) var(--them-pad-left);

/* 👇 独立引用条魔法开关 (在气泡下方显示) */
--reply-detached-bg: transparent;
--reply-detached-text-color: #000000;
--reply-detached-name-color: #000000;
--reply-detached-padding: 4px 8px;
--reply-detached-margin-top: 4px;
--reply-detached-radius: 4px;
--reply-detached-border-none: 2px solid #a0a0a0;
--reply-detached-border-left: none !important;
--reply-detached-border: none !important;
--reply-detached-shadow: none !important;
--reply-detached-bg: transparent !important;

/* 👇 引用框对齐气泡的魔法开关 (专治强迫症) */
  --reply-me-move-right: -8px;
  --reply-me-move-left: 0px;
  --them-reply-move-left: -3px;
  --them-reply-move-right: 0px;

/* 👇 时间戳和系统提示的改色魔法开关 */
  --timestamp-color: #000000;
  --date-divider-color: #000000;
  --system-msg-color: #000000;
}

/* =================================== */
/* 引用框大改造 */
.msg-reply-block {
display: none !important;
}
.msg-reply-block-detached {
display: flex !important;
}
.msg-me .msg-reply-block-detached {
  margin-right: var(--reply-me-move-right) !important;
  margin-left: var(--reply-me-move-left) !important;
}

.msg-them .msg-reply-block-detached {
  margin-left: var(--them-reply-move-left) !important;
  margin-right: var(--them-reply-move-right) !important;
}

/* =================================== */
/* 时间戳改造（去除方框 + 顶部新增“消息”字样） */
.timestamp-custom {
  background: transparent !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  border-radius: 0 !important;
  padding: 0 !important;
  color: var(--timestamp-color, #f0f0f0) !important;
  font-size: 11px !important;
  margin: 14px auto 10px !important;
  width: fit-content !important;
  box-shadow: none !important;
  display: flex !important;
  flex-direction: column !important;
  align-items: center !important;
  text-align: center !important;
}

.timestamp-custom::before {
  content: "消息" !important;
  display: block !important;      /* 👈 强制变块级元素，margin 才能生效 */
  line-height: 0.4 !important;     /* 👈 消除字体默认多余行高 */
  font-size: 11px !important;
  color: var(--timestamp-color, #f0f0f0) !important;
  margin-bottom: 4px !important;  /* 👈 此时调这个就会明显变化了 */
  opacity: 0.8 !important;
letter-spacing: 0px !important;  /* 👈 加这行：控制“消”和“息”之间的字间距 */
  padding-left: 0 !important; 
}
/* =================================== */
/* 连发仅首条显示头像与尾巴，严格对齐 */
/* =================================== */

/* 1. 头像处理：默认隐身（保留占位空间，让气泡永远对齐） */
.msg-avatar-them-container,
.msg-avatar-me-container {
    visibility: hidden !important;
}

/* 只有单条和连发第一条，才解除隐身 */
.msg-bubble-wrapper.is-single .msg-avatar-them-container,
.msg-bubble-wrapper.is-first .msg-avatar-them-container,
.msg-bubble-wrapper.is-single .msg-avatar-me-container,
.msg-bubble-wrapper.is-first .msg-avatar-me-container {
    visibility: visible !important;
}

/* 2. 尾巴处理：遇到中间条和最后一条，强制拔掉尾巴！ */
.msg-bubble-wrapper.is-mid .bubble-me-custom::before,
.msg-bubble-wrapper.is-last .bubble-me-custom::before,
.msg-bubble-wrapper.is-mid .bubble-them-custom::before,
.msg-bubble-wrapper.is-last .bubble-them-custom::before {
    display: none !important;
    content: none !important;
    background-image: none !important;
}
/* =========================================================
   🛠️ 引用框纯净版防溢出补丁
   ========================================================= */
.msg-reply-block-detached {
    display: flex !important;
    align-items: center !important;
    flex-direction: row !important;
    flex-wrap: nowrap !important;
    width: fit-content !important;
    max-width: calc(100vw - 180px) !important;
    min-width: 0 !important;
    box-sizing: border-box !important;
    overflow: hidden !important;
}

.msg-me .msg-reply-block-detached img,
.msg-them .msg-reply-block-detached img,
.msg-reply-block-detached img {
    width: 30px !important;
    height: 30px !important;
    min-width: 30px !important;
    min-height: 30px !important;
    max-width: 30px !important;
    max-height: 30px !important;
    object-fit: cover !important;
    border-radius: 4px !important;
    flex-shrink: 0 !important;
    margin: 0 !important;
    padding: 0 !important;
    display: block !important;
    position: static !important;
    transform: none !important;
}

.msg-reply-detached-text,
.msg-reply-detached-content,
.msg-reply-block-detached span:not(.msg-reply-detached-name) {
    flex: 1 1 auto !important;
    min-width: 0 !important;
    overflow: hidden !important;
    text-overflow: ellipsis !important;
    white-space: nowrap !important;
    word-break: break-all !important;
}

/* =======================================
   📏 8️⃣ 限制常规气泡最大宽度
   ======================================= */
.bubble-me-custom,
.bubble-them-custom {
    max-width: 72vw !important;
    box-sizing: border-box !important;
    word-wrap: break-word !important;
    word-break: break-word !important;
}

/* ========== 表情包单独缩小 ========== */
.bubble-me-custom img,
.bubble-them-custom img,
.msg-plain-me img,
.msg-plain-them img {
    max-width: 110px !important;
    max-height: 110px !important;
    width: auto !important;
    height: auto !important;
    object-fit: contain !important;
    border-radius: 5px !important;
}

/* ========== 普通图片单独缩小 ========== */
.msg-image-wrapper img,
.msg-bubble-wrapper .msg-image-wrapper img {
    max-width: 170px !important;
    max-height: 170px !important;
    width: auto !important;
    height: auto !important;
    object-fit: cover !important;
    border-radius: 5px !important;
}

/* 去除非文字独立消息气泡 */
:is(.msg-plain-me, .msg-plain-them, .bubble-me-custom, .bubble-them-custom,
    .msg-bubble-container, [class*="bubble"]):has(
    [class*="image"], [class*="picture"], [class*="sticker"], [class*="emoji"],
    [class*="face"], [class*="card"], [class*="transfer"], [class*="gift"],
    [class*="location"], [class*="file"], [class*="videocall"],
    [class*="voice-call"], [class*="voicecall"], [class*="call-card"], img
):not(:has(
    .msg-reply-block,
    .msg-reply-block-detached,
    [class*="reply"],
    [class*="quote"],
    [class*="avatar"],
    p,
    .msg-text,
    .text-content,
    [class*="voice"]:not([class*="videocall"], [class*="voice-call"],
        [class*="voicecall"], [class*="call-card"])
)) {
    background: transparent none !important;
    border: 0 none !important;
    border-image: none !important;
    border-radius: 0 !important;
    box-shadow: none !important;
    padding: 0 !important;
    outline: none !important;
    backdrop-filter: none !important;
    -webkit-backdrop-filter: none !important;
    filter: none !important;
    mix-blend-mode: normal !important;
}

:is(.msg-plain-me, .msg-plain-them, .bubble-me-custom, .bubble-them-custom,
    .msg-bubble-container, [class*="bubble"]):has(
    [class*="image"], [class*="picture"], [class*="sticker"], [class*="emoji"],
    [class*="face"], [class*="card"], [class*="transfer"], [class*="gift"],
    [class*="location"], [class*="file"], [class*="videocall"],
    [class*="voice-call"], [class*="voicecall"], [class*="call-card"], img
):not(:has(
    .msg-reply-block,
    .msg-reply-block-detached,
    [class*="reply"],
    [class*="quote"],
    [class*="avatar"],
    p,
    .msg-text,
    .text-content,
    [class*="voice"]:not([class*="videocall"], [class*="voice-call"],
        [class*="voicecall"], [class*="call-card"])
))::before,
:is(.msg-plain-me, .msg-plain-them, .bubble-me-custom, .bubble-them-custom,
    .msg-bubble-container, [class*="bubble"]):has(
    [class*="image"], [class*="picture"], [class*="sticker"], [class*="emoji"],
    [class*="face"], [class*="card"], [class*="transfer"], [class*="gift"],
    [class*="location"], [class*="file"], [class*="videocall"],
    [class*="voice-call"], [class*="voicecall"], [class*="call-card"], img
):not(:has(
    .msg-reply-block,
    .msg-reply-block-detached,
    [class*="reply"],
    [class*="quote"],
    [class*="avatar"],
    p,
    .msg-text,
    .text-content,
    [class*="voice"]:not([class*="videocall"], [class*="voice-call"],
        [class*="voicecall"], [class*="call-card"])
))::after {
    display: none !important;
    content: none !important;
    background: transparent none !important;
    border: 0 none !important;
    box-shadow: none !important;
    backdrop-filter: none !important;
    -webkit-backdrop-filter: none !important;
    filter: none !important;
    opacity: 0 !important;
}

/* =========================================================
   ☀️🌙 全局最高优先级：强制暴力覆盖日夜间变量切换
   ========================================================= */

