    --top-menu-color: #262626 !important;

    /* 👇 底栏输入框配色 */
    --input-area-bg: #ffffff !important;
    --input-box-color: #222222 !important;

    /* 👇 气泡配色  */
    --bubble-me-bg: #000000 !important;
    --bubble-me-color: #ffffff !important;
    --bubble-them-bg: #ffffff !important;
