}

/* 5. 透明贴膜魔法：把原本的翻译按钮变透明，盖满整个气泡 */
.msg-translation-btn {
    position: absolute !important;
    inset: 0 !important;
    width: 100% !important;
    height: 100% !important;
    opacity: 0 !important;
