  padding-bottom: max(10px, env(safe-area-inset-bottom)) !important;
}
/* ============================================================
   语音消息美化（透明水滴 + 纯播放键 + 去波形 + 展开自适应）
   ============================================================ */

/* 1. 外层气泡：改为 min-height，让它能随转文字内容自动撑高 */
.msg-voice-wrapper,
.voice-bubble-custom,
.msg-bubble-wrapper .bubble-me-custom:has(.voice-play-btn),
.msg-bubble-wrapper .bubble-them-custom:has(.voice-play-btn) {
  width: fit-content !important;
  min-width: 120px !important; 
  max-width: 65% !important;   
  padding: 0 14px !important; 
  min-height: 42px !important; /* 关键修改：把固定高度改为最小高度 */
  height: auto !important;     /* 关键修改：允许高度自适应 */
  display: inline-flex !important;
  flex-direction: column !important;
  justify-content: center !important; 
  align-items: center !important;
  gap: 0 !important;
  box-sizing: border-box !important;
}

/* 2. 内部布局：整体往上移 + 往左移 */
.voice-controls-row {
  display: flex !important;
  align-items: center !important;
  justify-content: flex-start !important; 
  width: 100% !important;
  min-height: 42px !important; /* 保证播放键这一行本身有足够高度 */
  height: auto !important;
  margin: 0 !important;
  padding: 0 0 0 8px !important; 
  transform: translateY(-2px) !important; 
}

/* 3. 播放键（透明水滴质感） */
.voice-play-btn, [class*="voice-play"] {
  width: 26px !important;
  height: 26px !important;
  min-width: 26px !important;
  min-height: 26px !important;
  flex-shrink: 0 !important;
  margin: 0 10px 0 0 !important; 
  border: 1px solid rgba(255,255,255,0.9) !important;
  border-radius: 50% !important;
  background: linear-gradient(
    180deg,
    rgba(255,255,255,0.85) 0%,
    rgba(255,255,255,0.55) 55%,
    rgba(255,255,255,0.45) 100%
  ) !important;
  -webkit-backdrop-filter: blur(10px) saturate(160%) !important;
  backdrop-filter: blur(10px) saturate(160%) !important;
  box-shadow:
    inset 0 1px 1px rgba(255,255,255,0.95),
    inset 0 -2px 3px rgba(255,255,255,0.25),
    0 2px 6px rgba(255,255,255,0.2) !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  position: relative !important;
  filter: none !important;
}

/* 隐藏原图标 */
.voice-play-btn svg, [class*="voice-play"] svg { display: none !important; }

/* 播放三角形（纯 CSS） */
.voice-play-btn::before,
[class*="voice-play"]::before {
  content: "" !important;
  display: block !important;
  width: 0 !important;
  height: 0 !important;
  border-style: solid !important;
  border-width: 5px 0 5px 8px !important;
  border-color: transparent transparent transparent #333 !important;
  margin-left: 2px !important;
  z-index: 2 !important;
}

/* 暂停态：两根竖条 */
.voice-play-btn.is-playing::before,
[class*="voice-play"].is-playing::before,
.voice-play-btn[data-playing="true"]::before,
[class*="voice-play"][data-playing="true"]::before {
  content: "" !important;
  width: 7px !important;
  height: 9px !important;
  border: none !important;
  margin-left: 0 !important;
  background:
    linear-gradient(#333, #333) left / 2.5px 100% no-repeat,
    linear-gradient(#333, #333) right / 2.5px 100% no-repeat !important;
}

/* 4. 数字时间 */
.voice-duration {
  flex-shrink: 0 !important;
  margin: 0 !important; 
  font-size: 14px !important;
  font-weight: 900 !important;
  color: #333 !important;
  white-space: nowrap !important; 
}

/* 5. 波形（已彻底隐藏） */
.voice-waveform-container,
[class*="waveform-container"],
[class*="voice-wave"],
.voice-waveform-bar {
  display: none !important;
}

/* 6. 转写按钮：限制高度，不占用展开后的空间 */
.voice-transcription-toggle {
  font-size: 0 !important;
  line-height: 0 !important;
  color: transparent !important;
  margin: 0 !important;
  padding: 0 !important;
  display: block !important;
  position: absolute !important; 
  top: 0 !important;
  left: 0 !important;
  width: 100% !important;
  height: 42px !important; /* 关键修改：限制点击热区高度为气泡初始高度，不覆盖下面展开的文字 */
  z-index: 10 !important;
  cursor: pointer !important;
  overflow: hidden !important;
}
.voice-transcription-toggle svg { display: none !important; }
.voice-transcription-toggle::before { content: none !important; }

/* 7. 下载按钮隐藏 */
.voice-download-btn,
[class*="voice-download"] {
  display: none !important;
}

/* 8. 转写框：撑开显示，不再被挡住 */
.voice-transcription {
  display: block !important;
  position: relative !important;
  z-index: 1 !important; /* 保证在点击层下面正常显示 */
  padding: 8px 10px !important;
  margin: 4px 0 6px 0 !important; /* 底部留一点边距 */
  background: rgba(255,255,255,0.45) !important;
  -webkit-backdrop-filter: blur(10px) saturate(160%) !important;
  backdrop-filter: blur(10px) saturate(160%) !important;
  border: 1px solid rgba(255,255,255,0.85) !important;
  border-radius: 10px !important;
  box-shadow:
    inset 0 1px 1px rgba(255,255,255,0.95),
    0 1px 4px rgba(255,255,255,0.15) !important;
  color: #444 !important;
  font-size: 13px !important;
  line-height: 1.5 !important;
}

/* 适配我方 / 对方语音 */
.msg-me .voice-duration { color: #333 !important; }
.msg-me .voice-play-btn,
.msg-me [class*="voice-play"] {
  filter: none !important;
}
.msg-me .voice-transcription {
  background: rgba(255,255,255,0.5) !important;
  border: 1px solid rgba(255,255,255,0.9) !important;
  color: #444 !important;
}
/* ============================================================
   转账卡片 —— 创意A：极简纯水珠 (自然流排版修复版)
   ============================================================ */

/* 1. 卡片外壳：定死尺寸、水珠质感、留出左侧图标空间 */
.msg-transfer-card {
  width: 250px !important;        
  height: 74px !important;        
  min-height: 74px !important;
  max-height: 74px !important;

  background: rgba(255, 255, 255, 0.05) !important; 
  -webkit-backdrop-filter: blur(15px) saturate(160%) !important;
  backdrop-filter: blur(15px) saturate(160%) !important;
  border: 1px solid rgba(255, 255, 255, 0.8) !important;
  border-radius: 14px !important;
  box-shadow: inset 0 1px 3px rgba(255, 255, 255, 0.9), 0 4px 12px rgba(0, 0, 0, 0.05) !important; 

  /* 关键：左侧留出 64px 给图标，上下留一点空间，彻底打乱原本的绝对定位 */
  padding: 10px 14px 10px 64px !important;
  box-sizing: border-box !important;
  position: relative !important;

  /* 让内部元素垂直居中排布 */
  display: flex !important;
  flex-direction: column !important;
  justify-content: center !important;
}

/* 2. 清理掉多余的、不想要的元素 */
.msg-transfer-card [class*="transfer-label"],
.msg-transfer-card [class*="transfer-divider"],
.msg-transfer-card [class*="transfer-status-text"],
.msg-transfer-card [class*="transfer-chevron"],
.msg-transfer-card [class*="transfer-icon"], /* 隐藏自带的破图标，我们不用它了 */
.msg-transfer-card [class*="dot"],
.msg-transfer-card [class*="badge"],
.msg-transfer-card [class*="unread"],
.msg-transfer-card [class*="red-dot"],
.msg-transfer-card [class*="notify"],
.msg-transfer-card [class*="indicator"] {
  display: none !important;
}

/* 3. 左侧画一个新的完美水滴图标（绝对不会跑位置） */
.msg-transfer-card::before {
  content: "¥" !important;
  position: absolute !important;
  left: 16px !important;
  top: 50% !important;
  transform: translateY(-50%) !important;

  width: 36px !important;
  height: 36px !important;
  border-radius: 50% !important;
  background: rgba(255, 255, 255, 0.6) !important;
  border: 1px solid rgba(255, 255, 255, 0.9) !important;
  box-shadow: inset 0 1px 2px rgba(255,255,255,1) !important;

  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  font-size: 18px !important;
  font-weight: bold !important;
  color: #333 !important;
  z-index: 2 !important;
}

/* 4. 把内部内容容器变成一个正常的块，强制覆盖内联样式 */
.msg-transfer-card [class*="transfer-content"],
.msg-transfer-card [class*="transfer-header"] {
  display: flex !important;
  flex-direction: column !important;
  justify-content: center !important;
  align-items: flex-start !important;
  position: static !important; /* 消灭绝对定位 */
  width: 100% !important;
  height: 100% !important;
  padding: 0 !important;
  margin: 0 !important;
  gap: 4px !important; /* 三行文字之间的间距 */
}

/* 5. 强制所有文字：取消绝对定位，按顺序排好，绝不重叠 */
.msg-transfer-card [class*="transfer-subtitle"],
.msg-transfer-card [class*="transfer-amount"],
.msg-transfer-card [class*="transfer-expire"],
.msg-transfer-card [class*="transfer-time"] {
  position: static !important; /* 关键：取消原来的乱跑定位 */
  transform: none !important;
  top: auto !important;
  left: auto !important;
  bottom: auto !important;

  display: block !important;
  margin: 0 !important;
  padding: 0 !important;
  line-height: 1 !important;
  white-space: nowrap !important;
}

/* 单独微调文字大小和颜色 */
.msg-transfer-card [class*="transfer-subtitle"] {
  font-size: 11px !important;
  color: #666 !important;
  font-weight: 500 !important;
  order: 1 !important; /* 排第一 */
}

.msg-transfer-card [class*="transfer-amount"] {
  font-size: 22px !important;
  font-weight: 900 !important;
  color: #111 !important;
  order: 2 !important; /* 排第二 */
}

.msg-transfer-card [class*="transfer-expire"],
.msg-transfer-card [class*="transfer-time"] {
  font-size: 10px !important;
  color: #999 !important;
  order: 3 !important; /* 排第三 */
}
/* ============================================================
   精准去壳：仅针对图片/表情/卡片去气泡包裹（保护文字气泡）
   ============================================================ */

/* 1. 针对框架自带的“无内边距/媒体圆角”气泡，强制透明脱壳 */
.bubble-me-custom.no-padding,
.bubble-them-custom.no-padding,
.bubble-me-custom.msg-radius-media,
.bubble-them-custom.msg-radius-media {
  background: transparent !important;
  background-color: transparent !important;
  background-image: none !important;
  border: none !important;
  box-shadow: none !important;
  padding: 0 !important;
  border-radius: 0 !important;
  -webkit-backdrop-filter: none !important;
  backdrop-filter: none !important;
  min-width: 0 !important;
}

/* 干掉这类气泡的尾巴 */
.bubble-me-custom.no-padding::before, 
.bubble-me-custom.no-padding::after,
.bubble-them-custom.no-padding::before, 
.bubble-them-custom.no-padding::after,
.bubble-me-custom.msg-radius-media::before, 
.bubble-me-custom.msg-radius-media::after,
.bubble-them-custom.msg-radius-media::before, 
.bubble-them-custom.msg-radius-media::after {
  display: none !important;
}

/* 2. 专门针对图片容器去壳 */
.msg-image-wrapper,
.msg-image-card {
  background: none !important;
  border: none !important;
  box-shadow: none !important;
  padding: 0 !important;
  border-radius: 0 !important;
}
/* 如果图片包裹在气泡里，也把外层气泡脱掉 */
.msg-me .msg-image-wrapper,
.msg-them .msg-image-wrapper {
  background: transparent !important;
  border: none !important;
}

/* 3. 图片本体：水滴高光边框（这个只作用在图片和表情上，不影响文字） */
.msg-image-wrapper img,
.msg-image-card img {
  border-radius: 12px !important;
  border: 1.5px solid rgba(255, 255, 255, 0.8) !important; /* 水滴高光边 */
  box-shadow: 
    inset 0 1px 3px rgba(255,255,255,0.9),
    0 4px 12px rgba(0, 0, 0, 0.08) !important; 
  max-width: 100% !important;
  object-fit: cover !important;
  display: block !important;
}

/* 4. 专门针对表情包去壳 */
.msg-me [class*="sticker"],
.msg-them [class*="sticker"],
.msg-sticker {
  background: none !important;
  border: none !important;
  box-shadow: none !important;
  padding: 0 !important;
  border-radius: 0 !important;
}

/* 表情包本体不需要高光边，保留纯正贴纸感 */
.msg-me [class*="sticker"] img,
.msg-them [class*="sticker"] img,
.msg-sticker img {
  border: none !important;
  box-shadow: none !important;
  border-radius: 0 !important;
}
/* ============================================================
   模块 E：礼物盒卡片 —— 冰晶玻璃水滴质感
   ============================================================ */

/* 1. 通用/对方的礼物盒：冰蓝玻璃质感 */
:root {
  /* 盒身亮面：透亮的白玻璃 */
  --gift-them-box-light: rgba(255, 255, 255, 0.85);
  /* 盒身暗面：带一点点冰蓝色的半透明玻璃 */
  --gift-them-box-dark: rgba(220, 235, 255, 0.45);

  /* 丝带：银白色 */
  --gift-them-ribbon-color: rgba(255, 255, 255, 0.95);
  --gift-them-ribbon-dark: rgba(200, 220, 255, 0.8);

  /* 阴影和文字 */
  --gift-them-shadow-color: rgba(180, 200, 255, 0.3);
  --gift-them-label-color: #7a8a9e;
}

/* 2. 我方的礼物盒：纯白水珠质感（稍微带点暖调区分） */
:root {
  --gift-me-box-light: rgba(255, 255, 255, 0.95);
  --gift-me-box-dark: rgba(240, 240, 255, 0.5);

  --gift-me-ribbon-color: rgba(255, 255, 255, 1);
  --gift-me-ribbon-dark: rgba(230, 230, 255, 0.9);

  --gift-me-shadow-color: rgba(200, 200, 255, 0.35);
  --gift-me-label-color: #8e8e93;
}

/* 3. 给礼物盒容器加一层“反光” */
.gift-ig-container {
  /* 防止底色干扰 */
  background: transparent !important;
  border: none !important;
  /* 如果它有默认的沉重阴影，去掉，换成玻璃阴影 */
  box-shadow: 0 8px 24px rgba(200, 220, 255, 0.2) !important;
  /* 轻微缩放，看起来更精致 */
  transform: scale(0.95);
  transition: transform 0.2s ease;
}

.gift-ig-container:active {
  transform: scale(0.92); /* 点击时有个按下去的反馈 */
}

/* 4. 文本“点击拆开”等文字的微调 */
.gift-ig-container [class*="label"],
.gift-ig-container [class*="text"] {
  text-shadow: 0 1px 2px rgba(255, 255, 255, 0.8);
  letter-spacing: 1px;
  font-weight: 500 !important;
}
/* ============================================================
   引用回复 —— 创意B：磨砂玻璃小卡片（独立气泡外）
   ============================================================ */

/* 1. 彻底隐藏原本在气泡内部的引用块 */
.msg-reply-block {
  display: none !important;
}

/* 2. 强制启用气泡外部的独立引用条 */
.msg-reply-block-detached {
  display: flex !important;
  position: relative !important;

  /* 磨砂玻璃卡片质感 */
  background: rgba(255, 255, 255, 0.45) !important;
  -webkit-backdrop-filter: blur(12px) saturate(160%) !important;
  backdrop-filter: blur(12px) saturate(160%) !important;

  /* 边框和圆角 */
  border: 1px solid rgba(255, 255, 255, 0.75) !important;
  border-radius: 10px !important;

  /* 阴影让它像浮在背景上 */
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.04), inset 0 1px 2px rgba(255,255,255,0.8) !important;

  /* 尺寸与排版 */
  padding: 6px 12px !important;
  margin-top: 6px !important;
  margin-bottom: 2px !important;
  max-width: 80% !important;
  width: fit-content !important;
  box-sizing: border-box !important;

  flex-direction: row !important;
  align-items: center !important;
  gap: 6px !important;
}

/* 3. 给卡片左上角加一个小小的装饰符号（比如引号或小方块） */
.msg-reply-block-detached::before {
  content: "❞" !important; 
  font-size: 12px !important;
  color: #999 !important;
  opacity: 0.7 !important;
  position: absolute !important;
  top: 2px !important;
  left: 4px !important;
  pointer-events: none !important;
}

/* 4. 引用的名字（谁说的话） */
.msg-reply-block-detached [class*="name"] {
  font-size: 11px !important;
  font-weight: 600 !important;
  color: #555 !important;
  white-space: nowrap !important;
  flex-shrink: 0 !important;
}

/* 默认名字后面的冒号修饰 */
.msg-reply-block-detached [class*="name"]::after {
  content: "：" !important;
  font-weight: normal !important;
  opacity: 0.6 !important;
}

/* 5. 引用的文字内容 */
.msg-reply-block-detached [class*="text"] {
  font-size: 11px !important;
  color: #777 !important;
  white-space: nowrap !important;
  overflow: hidden !important;
  text-overflow: ellipsis !important; /* 文字太长自动省略 */
  line-height: 1.2 !important;
}

/* 6. 适配我方/对方（因为卡片在气泡外面，默认是左对齐的，我们根据是谁的消息稍微调整下位置） */
.msg-reply-detached-me {
  align-self: flex-end !important; /* 我方引用靠右 */
  margin-right: 12px !important;
}

.msg-reply-detached-them {
  align-self: flex-start !important; /* 对方引用靠左 */
  margin-left: 12px !important;
}
/* ============================================================
   翻译专属美化（隐形热区 + 独立卡片 + 往右微调版）
   ============================================================ */

/* 1. 隐形按钮：拉满整个气泡，点气泡任何地方都能触发翻译 */
.msg-translation-wrapper {
  position: absolute !important;
  top: 0 !important;
  left: 0 !important;
  right: 0 !important;
  bottom: 0 !important;
  z-index: 10 !important; 
  margin: 0 !important;
  padding: 0 !important;
}

.msg-translation-btn {
  width: 100% !important;
  height: 100% !important;
  opacity: 0 !important; /* 完全隐形 */
  cursor: pointer !important;
  pointer-events: auto !important;
  border: none !important;
  background: transparent !important;
}

.msg-translation-btn svg,
.msg-translation-btn span,
.msg-translation-btn * {
  display: none !important; /* 隐藏原本按钮自带的图标和文字 */
}

/* 2. 隐藏原本挤在气泡内部的翻译文字 */
.msg-translation-content {
  display: none !important;
}

/* 3. 启用气泡外的独立翻译块（位置与宽度微调） */
.msg-translation-detached {
  display: block !important;
  position: relative !important; 
  z-index: 999 !important;       
  width: fit-content !important;
  max-width: 100% !important;
  box-sizing: border-box !important;

  /* ⬇️ 往右移一点，留出呼吸感（原来是 0，现在改成 10px） */
  margin-left: 10px !important; 
  padding-left: 0 !important;

  /* 往上提一丢丢 */
  margin-top: -12px !important; 
}

/* 4. 翻译块文字样式（左对齐 + 纯黑） */
.msg-translation-detached-content {
  background: transparent !important;
  color: #000000 !important; 
  border: none !important;
  box-shadow: none !important;
  font-size: 14px !important;
  line-height: 1.5 !important;
  word-break: break-word !important;
  min-width: 0 !important;
  max-width: 320px !important;

  /* 清除内边距 */
  padding: 0 !important;
  margin: 0 !important;

  /* 强制块级显示 + 左对齐 */
  display: block !important;
  text-align: left !important; 
}

/* 5. 区分我方与对方位置 */
.msg-translation-detached-them { 
  align-self: flex-start !important; 
  margin-left: 10px !important; /* 同步增加一点左边距 */
}
.msg-translation-detached-me { 
  align-self: flex-end !important; 
}

/* 6. 多重保险：防止内部任何子元素居中或带缩进 */
.msg-translation-detached-content *,
.msg-translation-detached-content span,
.msg-translation-detached-content div {
  text-align: left !important;
  justify-content: flex-start !important;
  padding-left: 0 !important;
  margin-left: 0 !important;
}
/* ============================================================
   模块 E2：特色气泡卡片 —— 透明水滴极简版
   ============================================================ */

/* =================================
   1. 小剧场拍立得 (玻璃相纸版)
   ================================= */
.msg-theater-card {
  /* 磨砂玻璃底 + 微弱透明度 */
  background: rgba(255, 255, 255, 0.45) !important;
  -webkit-backdrop-filter: blur(16px) saturate(160%) !important;
  backdrop-filter: blur(16px) saturate(160%) !important;

  /* 水滴高光边框 */
  border: 1px solid rgba(255, 255, 255, 0.8) !important;
  border-radius: 16px !important;

