    /* 👇 同理，精准覆盖右边的长方形 */
    bottom: calc(100% + var(--rect-gap-bottom)) !important;
    right: var(--rect-right-x) !important;
    width: var(--rect-right-width) !important;
    height: var(--rect-right-height) !important;

    opacity: 0 !important;       /* 保持隐身 */
    z-index: 99 !important;      /* 冲到最高层 */
    cursor: pointer !important;
    margin: 0 !important;
    padding: 0 !important;
}

/* =================================== */
/* 💸 转账 & 红包卡片：统一终极样式（包含虚线与尾巴） */
/* =================================== */
:root {
  /* 👇 外壳魔法 */
  --transfer-card-width: 200px;
  --transfer-card-height: 80px;
  --transfer-card-bg: #ffffff;
  --transfer-card-radius: 12px;

  /* 👇 图标的魔法开关 (空心圆 + 箭头) */
  --transfer-circle-thickness: 2px;
  --transfer-arrow-weight: 600;
  --transfer-arrow-size: 20px;
  --transfer-icon-size: 32px;
  --transfer-icon-x: 20px;
  --transfer-icon-y: -90%;

  /* 👇 原生文字魔法开关 (转账给xxx / 微信红包) */
  --transfer-sub-x: 60px;
  --transfer-sub-y: 11px;
  --transfer-sub-size: 16px;
  --transfer-sub-color: #333333;

  /* 👇 自定义喵喵文案魔法开关 */
  --transfer-text-x: 22px;
  --transfer-text-y: 55px;
  --transfer-text-size: 14px;
  --transfer-text-color: #888888;
  --transfer-text-done: #aaaaaa;

  /* 👇 图片尾巴魔法开关 */
  --transfer-img-width: 20px;
  --transfer-img-height: 20px;
  --transfer-img-gap: 3px;
  --transfer-img-y: -2px;

  /* 👇 虚线魔法开关 */
  --transfer-line-width: 210px;
  --transfer-line-thickness: 1px;
  --transfer-line-color: #cccccc;
  --transfer-line-x: 1px;
  --transfer-line-y: 50px;
}

/* 1. 暴力隐藏所有原生零件（红包和转账的原生图标、金额全干掉） */
.msg-transfer-card * {
  visibility: hidden !important;
}

/* 2. 定型外壳 + 铺上虚线背景 */
.msg-transfer-card {
  width: var(--transfer-card-width) !important;
  height: var(--transfer-card-height) !important;
  padding: 0 !important;
  display: block !important;
  position: relative !important;
  border: none !important;
  background-color: var(--transfer-card-bg) !important;
  border-radius: var(--transfer-card-radius) !important;
  /* 虚线背景 */
  background-image: repeating-linear-gradient(to right, var(--transfer-line-color) 0, var(--transfer-line-color) 4px, transparent 4px, transparent 8px) !important;
  background-size: var(--transfer-line-width) var(--transfer-line-thickness) !important;
  background-position: var(--transfer-line-x) var(--transfer-line-y) !important;
  background-repeat: no-repeat !important;
}

:root {
  /* 👇 限制文字的最长宽度，超出的部分会自动变成省略号 */
  --transfer-sub-max: 130px;  /* 宽度你随意调，比如觉得太短可以改 140px */
}

/* 3. 抢救原生文字（转账给xx / 微信红包）+ 截断魔法 */
.msg-transfer-card .msg-transfer-subtitle {
  visibility: visible !important;
  display: block !important;
  position: absolute !important;
  left: var(--transfer-sub-x) !important;
  top: var(--transfer-sub-y) !important;
  font-size: var(--transfer-sub-size) !important;
  color: var(--transfer-sub-color) !important;
  z-index: 10 !important;
  white-space: nowrap !important;
  margin: 0 !important;
  font-weight: 500 !important;

  /* 👇 防截断黑魔法核心 */
  max-width: var(--transfer-sub-max) !important;
  overflow: hidden !important;
  text-overflow: ellipsis !important;
  padding: 0 !important;
  padding-right: calc(var(--transfer-img-width) + var(--transfer-img-gap)) !important; 
  box-sizing: border-box !important;

  /* 👇 救命魔法：把这行的“天花板”顶高，防猫爪被削头！ */
  line-height: 30px !important; 
}

/* 4. 给原生文字加上图片小尾巴（绝对保护版） */
.msg-transfer-card .msg-transfer-subtitle::after {
  content: "" !important;
  visibility: visible !important;
  position: absolute !important; /* 👈 改成绝对定位，死死钉在安全区 */
  right: 0 !important;           /* 👈 钉在最右侧 */
  top: 50% !important;
  transform: translateY(calc(-50% + var(--transfer-img-y))) !important;
  width: var(--transfer-img-width) !important;
  height: var(--transfer-img-height) !important;
  background-image: url("https://nos.netease.com/ysf/202b8643f9954bc24c2408cf346660f2.png") !important;
  background-size: contain !important;
  background-repeat: no-repeat !important;
  background-position: center right !important; 
}

/* 5. 画出空心圆和箭头 */
.msg-transfer-card::after {
  visibility: visible !important;
  content: "⇌" !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  position: absolute !important;
  left: var(--transfer-icon-x) !important;
  top: 50% !important;
  transform: translateY(var(--transfer-icon-y)) !important;
  width: var(--transfer-icon-size) !important;
  height: var(--transfer-icon-size) !important;
  border: var(--transfer-circle-thickness) solid #000000 !important;
  border-radius: 50% !important;
  font-size: var(--transfer-arrow-size) !important;    
  font-weight: var(--transfer-arrow-weight) !important;
  color: #000000 !important;
  pointer-events: none !important;
  z-index: 10 !important;
}

/* 6. 转账喵喵文案 */
.msg-transfer-card::before {
  visibility: visible !important;
  content: "♪自动收款中 谢谢喵♡" !important;
  position: absolute !important;
  left: var(--transfer-text-x) !important;
  top: var(--transfer-text-y) !important;
  font-size: var(--transfer-text-size) !important;
  font-weight: 500 !important;
  color: var(--transfer-text-color) !important;
  white-space: nowrap !important;
  pointer-events: none !important;
  z-index: 10 !important;
  letter-spacing: 0.5px !important;
}
.msg-transfer-card.msg-transfer-success::before {
  content: "小猫已收款成功=^_^=" !important;
  color: var(--transfer-text-done) !important;
}

/* 7. 🎁 红包专属喵喵文案（覆盖上面的转账文案） */
.msg-redpacket-card::before {
  content: "♪红包未拆 谢谢喵♡" !important;
}
.msg-redpacket-card.msg-transfer-success::before {
  content: "小猫已拆开红包=^_^=" !important;
}
/* =================================== */
/* 🎁 附加：红包“恭喜发财”独立位置魔法（修复猫爪重叠版） */
/* =================================== */
:root {
  /* 👇 红包文字专属位置开关，和转账互不干扰！ */
  --redpacket-sub-x: 60px;   /* 左右挪 */
