  /* 👇 修复猫爪重叠的核心：强制收紧宽度，并把猫爪的安全区重新掏出来！ */
  width: max-content !important;
  padding: 0 !important;
  padding-right: calc(var(--transfer-img-width) + var(--transfer-img-gap)) !important;
  box-sizing: border-box !important;
}

/* 2. 伪元素重新打上“恭喜发财”，自动跟随上面的专属坐标 */
.msg-redpacket-card .msg-transfer-subtitle::before {
  content: "恭喜发财" !important;
