/* =================================== */
/* 伪造双层底栏：底部六个装饰图标（自由排版版） */

:root {
  /* 👇 第二行装饰图标的左右位置魔法开关 (0%是最左边，100%是最右边) */
  --icon-1-pos: 3%;    /* 麦克风 */
  --icon-2-pos: 21%;   /* 相册 */
  --icon-3-pos: 41%;   /* 相机 */
  --icon-4-pos: 61%;   /* 红包 */
  --icon-5-pos: 80%;   /* 表情 */
  --icon-6-pos: 98%;   /* 加号 */

  /* 👇 整排图标的整体缩放和高度 */
  --icon-row-bottom: 12px; /* 距离底部的距离 */
  --icon-row-left: 20px;   /* 整体距离屏幕左边缘 */
  --icon-row-right: 20px;  /* 整体距离屏幕右边缘 */
  --icon-size: 24px;       /* 图标的统一大小 */

  /* 🆕 新增：最后两个图标（表情 & 加号）单独放大 1px */
  --icon-size-last: calc(var(--icon-size) + 0.75px);
}

/* 1. 把底栏整体抬高，给第二行腾出空间 */
.input-area-custom {
    padding-bottom: 50px !important;
    position: relative !important;
}

/* 2. 印上6个图标，接入魔法开关 */
.input-area-custom::after {
    content: "";
    position: absolute;
    bottom: var(--icon-row-bottom) !important;
    left: var(--icon-row-left) !important;
    right: var(--icon-row-right) !important;
