}

.msg-reply-detached-name::after {
    content: "：" !important;
    font-size: 13px !important;
    color: var(--reply-detached-name-color) !important;
}
/* nuojiji-bubble-config: {"themeStyle":"qq","bubbleStyle":"premium-gradient","partnerBubbleStyle":"#efefef","bubbleTextColor":"","partnerBubbleTextColor":"","avatarSize":34,"avatarShape":"square"} */

/* ============================================================                 🈲二改二传
   仿kkt气泡 原主题名称：엔젤 통통 토끼 블루 v1（天使胖胖兔 · 蓝） by 你靠我太近啦
   ============================================================ */

:root {

  /* === 顶部导航栏 ===
     原主题 HeaderStyle-Main / MainViewStyle-Primary 配色 */
  --chat-header-bg: rgba(255,255,255,0.95);
  --chat-header-blur: 12px;
  --chat-header-border: #E2F3FF;
  --chat-header-height: 56px;
  --chat-header-title-color: #1D1B37;
  --chat-header-title-size: 16px;
  --chat-header-title-weight: 700;
  --chat-header-subtitle-color: #86B9DC;
  --chat-header-subtitle-size: 12px;
  --chat-header-icon-color: #1D1B37;
  --chat-header-avatar-size: 34px;
  --chat-header-avatar-border: 2px solid #E2F3FF;
  --chat-header-avatar-radius: 50%;
  --chat-header-avatar-shadow: none;
  --header-btn-gap: 18px;

  /* === 消息区域 === */
  --chat-messages-padding: 12px 16px;
  --chat-messages-gap: 3px;
  --chat-message-max-width: 78%;

  /* === 我方气泡（对应原主题「Send」气泡：冰蓝底 + 藏青描边） === */
  --bubble-me-bg: #F4FBFF;
  --bubble-me-bg-gradient: initial;
  --bubble-me-color: #1D1B37;
  --bubble-me-font-size: 15px;
  --bubble-me-line-height: 1.5;
  --bubble-me-padding: 5px 16px;
  --bubble-me-radius: 10px;
  --bubble-me-radius-first: 10px 10px 3px 10px;
  --bubble-me-radius-mid: 10px 3px 3px 10px;
  --bubble-me-radius-last: 10px 3px 10px 10px;
  --bubble-me-shadow: 0 2px 6px rgba(29,27,55,0.06);
  --bubble-me-border: 1.5px solid #1D1B37;
  --bubble-me-link-color: #4A90D9;
  --bubble-me-text-shadow: none;
  --bubble-me-letter-spacing: normal;
  --bubble-me-backdrop: none;
  --bubble-me-filter: none;
  --bubble-me-opacity: 1;
  --bubble-me-transform: none;

  /* === 对方气泡（对应原主题「Receive」气泡：纯白底 + 藏青描边） === */
  --bubble-them-bg: #ffffff;
  --bubble-them-bg-gradient: initial;
  --bubble-them-color: #1D1B37;
  --bubble-them-font-size: 15px;
  --bubble-them-line-height: 1.5;
  --bubble-them-padding: 5px 16px;
  --bubble-them-radius: 10px;
  --bubble-them-radius-first: 10px 10px 10px 3px;
  --bubble-them-radius-mid: 3px 10px 10px 3px;
  --bubble-them-radius-last: 3px 10px 10px 10px;
  --bubble-them-shadow: 0 2px 6px rgba(29,27,55,0.06);
  --bubble-them-border: 1.5px solid #1D1B37;
  --bubble-them-link-color: #4A90D9;
  --bubble-them-text-shadow: none;
  --bubble-them-letter-spacing: normal;
  --bubble-them-backdrop: none;
  --bubble-them-filter: none;
  --bubble-them-opacity: 1;
  --bubble-them-transform: none;

  /* === 头像（已隐藏，变量保留不影响） === */
  --avatar-size: 38px;
  --avatar-radius: 50%;
  --avatar-border: 2px solid #E2F3FF;
  --avatar-margin: 8px;
  --avatar-shadow: none;
  --avatar-placeholder-bg: #EBF7FF;

  /* === 引用 & 回复 === */
  --quote-border-color: #A3D3F5;
  --quote-text-color: #4A6B85;
  --code-bg: #EBF7FF;
  --code-color: #1D1B37;
  --reply-block-bg: #EBF7FF;
  --reply-block-name-color: #1D1B37;
  --reply-block-text-color: #4A6B85;
  --reply-block-radius: 10px;
  --reply-block-padding: 8px 10px;
  --reply-block-border: none;
  --reply-block-border-left: 3px solid #A3D3F5;

  /* === 旁白消息 === */
  --narration-color: #86B9DC;
  --narration-size: 0.87em;
  --narration-style: italic;
  --narration-text-align: center;

  /* === 时间戳 & 日期分隔线 === */
  --timestamp-color: #A3D3F5;
  --timestamp-size: 11px;
  --date-divider-color: #86B9DC;
  --date-divider-size: 12px;
  --date-divider-weight: 600;

  /* === IG/QQ 已读状态 === */
  --status-color: #A3D3F5;
  --status-read-color: #4A90D9;

  /* === 输入区域（原主题 InputBarStyle-Chat 配色） === */
  --input-area-bg: #ffffff;
  --input-area-bg-image: none;
  --input-area-blur: 0px;
  --input-area-border-top: 1px solid #E2F3FF;
  --input-area-padding: 12px 16px;
  --input-area-min-height: 56px;

  --input-box-bg: #ffffff;
  --input-box-color: #1D1B37;
  --input-box-placeholder: #A3D3F5;
  --input-box-radius: 24px;
  --input-box-padding: 10px 18px;
  --input-box-font-size: 15px;
  --input-box-border: 1.5px solid #C5E7FF;
  --input-box-blur: none;
  --input-box-shadow: none;
  --input-caret-color: #1D1B37;

  --input-btn-color: #C5E7FF;
  --plus-btn-bg: transparent;
  --plus-btn-color: #1D1B37;
  --plus-btn-size: 24px;

  /* === 发送按钮（原主题送出按钮：冰蓝底 + 白色图标） === */
  --send-btn-bg: #E2F3FF;
  --send-btn-bg-hover: #C5E7FF;
  --send-btn-color: #1D1B37;
  --send-btn-size: 34px;
  --send-btn-radius: 50%;
  --send-btn-shadow: none;

  --stop-btn-bg: #1D1B37;
  --stop-btn-color: #ffffff;
  --stop-btn-radius: 50%;

  /* === 回复预览栏 === */
  --reply-bar-accent: #4A90D9;
  --reply-bar-text-color: #86B9DC;

  /* === 更多选项面板（拟液态玻璃风格，可选） === */
  --more-options-bg: rgba(255,255,255,0.95);
  --more-options-blur: blur(20px) saturate(160%);
  --more-options-shadow: 0 8px 24px rgba(29,27,55,0.12);
  --more-options-color: #1D1B37;
  --more-options-divider: #EBF7FF;

  /* === 打字指示器 === */
  --typing-dot-color: #A3D3F5;
  --typing-bg: #F4FBFF;
  --typing-radius: 18px;

  /* === 滚动条 === */
  --scrollbar-width: 4px;
  --scrollbar-track: transparent;
  --scrollbar-thumb: #C5E7FF;
  --scrollbar-thumb-hover: #A3D3F5;

  /* === 图片消息 === */
  --image-msg-radius: 18px;
  --image-msg-shadow: 0 2px 12px rgba(29,27,55,0.1);
  --image-msg-border: 1.5px solid #E2F3FF;

  /* === 系统消息 === */
  --system-msg-bg: #EBF7FF;
  --system-msg-color: #86B9DC;
}

/* ============================================================
   头像：恢复正常显示 + 可点击
   ============================================================ */

.msg-avatar-them-container,
.msg-avatar-me-container {
  visibility: visible !important;
}

/* ============================================================
   气泡装饰：胖胖兔探头   ============================================================ */

.bubble-me-custom,
.bubble-them-custom {
  position: relative !important;
  overflow: visible !important;
}
.bubble-deco-me,
.bubble-deco-them {
  overflow: visible !important;
}

/* 默认不显示装饰 —— 我方（右上角） */
.bubble-me-custom::before {
  content: "";
  position: absolute;
  top: -40px;
  right: -35px;
  width: 76px;
  height: 52px;
  pointer-events: none;
  z-index: 2;
  display: none;
}

/* 默认不显示装饰 —— 对方（左上角） */
.bubble-them-custom::before {
  content: "";
  position: absolute;
  top: -40px;
  left: -35px;
  width: 76px;
  height: 52px;
  pointer-events: none;
  z-index: 2;
  display: none;
}

/* 只在分组第一条 / 单条消息上显示兔子 —— 我方（Send 图案） */
[data-first="true"] .bubble-me-custom::before {
  display: block;
  background: url(https://imgbed.heliar.top/i/m5qyas9t3f3lRFiK.webp) no-repeat center/contain;
}

/* 只在分组第一条 / 单条消息上显示兔子 —— 对方（Receive 图案） */
[data-first="true"] .bubble-them-custom::before {
  display: block;
  background: url(https://imgbed.heliar.top/i/kEamh5SkNYXR52ux.webp) no-repeat center/contain;
}
/* =======================================
   只显示第一条/单条消息头像 + 下方气泡对齐第一条顶部
======================================= */

/* 默认隐藏双方头像 */
.msg-avatar-me-container,
.msg-avatar-them-container {
  visibility: hidden !important;
}

/* 只在第一条和单条显示 */
.msg-avatar-me-container.is-first,
.msg-avatar-me-container.is-single,
.msg-avatar-them-container.is-first,
.msg-avatar-them-container.is-single {
  visibility: visible !important;
}

/* 气泡头像相框 */
.msg-avatar-me-container,
.msg-avatar-them-container {
  position: relative !important;
}
/* 仅视觉上移首条/单条头像，不占位、不挤压 */
.msg-avatar-me-container.is-first,
.msg-avatar-me-container.is-single,
.msg-avatar-them-container.is-first,
.msg-avatar-them-container.is-single {
  transform: translateY(-46px) !important; /* 负值向上，数值按需调整 */
}
/* 给每个分组的最后一条消息增加底部间距（组间分隔） */
.msg-bubble-wrapper[data-last="true"] {
  margin-bottom: 50px !important;
}

/* 同时确保组内其他消息底部间距为0（如果有的话） */
.msg-bubble-wrapper:not([data-last="true"]) {
  margin-bottom: 2 !important;
}
/* 完全隐藏我方头像（所有情况，包括首条和单条） */
.msg-avatar-me-container {
  display: none !important;
}
/* 让我方消息整体左移（离右边缘更远），增加右侧空白 */
.msg-me {
  padding-right: 28px !important; /* 数值越大，气泡离右边缘越远 */
}
/* 让思维链整体右移（按钮 + 展开面板一起移） */
.nuo-thinking-wrap {
  margin-left: 30px !important; /* 正值越大越靠右 */
}
/* 旁白文字整体上移（纯视觉，不占位） */
.msg-narration-custom {
  transform: translateY(-10px) !important;
}
/* ====== 特殊消息去气泡外壳 ====== */
.bubble-me-custom.no-padding,
.bubble-them-custom.no-padding,
.bubble-me-custom.msg-radius-media,
