}

/* ③ 药丸 3：[ 사랑해 ✕ ]（带防下落对齐） */
#chat-detail-screen .input-row-wrapper::after {
  content: "사랑해 ✕" !important;                                    /* 🤍 药丸 3 文案 */
  position: absolute !important;
  left: 120px !important;                                           /* 🤍 药丸 3 左间距 */
  top: -26px !important;
