  #chat-detail-screen .send-btn-custom::before {
    color: #ffffff !important;
  }
  #chat-detail-screen .input-btn-plus::before,
  #chat-detail-screen .input-btn-mic::before,
  #chat-detail-screen .input-btn-sticker::before {
    filter: invert(1) !important;
  }
  #chat-detail-screen .input-action-bar-custom {
    border-bottom-color: #52525b !important;
  }
  #chat-detail-screen .input-box-custom {
    color: #ffffff !important;
  }

 /* 5. 气泡空线反白 + ⚡ 修复夜间波形发亮可见 ⚡ */
