    --bubble-them-color: #f4f4f5 !important;
    --bubble-them-border: 1px solid #71717a !important;             /* 🤍 夜间对方亮灰线框 */

    /* ⚡ 核心修复：夜间波形变量反白 ⚡ */
    --voice-me-color: #ffffff !important;
    --voice-me-bar-active: #ffffff !important;                      /* 已播放：纯白发亮 */
    --voice-me-bar-inactive: rgba(255, 255, 255, 0.35) !important;  /* 未播放：透亮银白 */
