/* =========================================================
   📸 思维链终极美化：Instagram 帖子风格 (夜间深色版)
   ========================================================= */

/* ── 1. 改造折叠按钮 (极简透明底，无三角) ── */
.chat-detail-screen {
  --thinking-btn-bg: transparent;
  --thinking-btn-color: #888888; 
  --thinking-btn-border: none;
  --thinking-btn-shadow: none;
  --thinking-btn-padding: 4px 0px; 
}

/* ── 2. 隐藏默认图标、小三角，修改按钮文字 ── */
.nuo-thinking-icon { display: none !important; }
.nuo-thinking-arrow { display: none !important; } 
.nuo-thinking-label {
    /* 隐藏入口文字，但不删除原按钮，不破坏原点击事件 */
    font-size: 0 !important;
    color: transparent !important;
    -webkit-text-fill-color: transparent !important;
    text-indent: -9999px !important;
    overflow: hidden !important;
    position: absolute !important;
    z-index: 20 !important;
    /* 透明热区：不参与布局，但保留点击能力 */
    width: 42px !important;
    height: 42px !important;
    padding: 0 !important;
    margin: 0 !important;
    pointer-events: auto !important;
}
.nuo-thinking-label::after {
    content: none !important;
    display: none !important;
}
/* 原生入口可能存在的图标/箭头也完全隐藏 */
.nuo-thinking-label .nuo-thinking-icon,
.nuo-thinking-label .nuo-thinking-arrow {
    display: none !important;
    visibility: hidden !important;
}

/* ── 3. 改造面板基础样式 (Ins 夜间深黑卡片) ── */
.chat-detail-screen {
  --thinking-panel-bg: #1a1a1a; /* 深黑底色 */
