  --sendas-narration-bg: #ffffff;
  --sendas-narration-color: #262626;
  --sendas-narration-border: 1px solid #E9E9E9;

  /* 3. 通用设置：右侧关闭按钮 (X) 和圆角 */
  --sendas-close-color: #888888;             /* 关闭按钮 (X) 改为中灰色 */
