}
/* ================================================
   新增：翻译气泡分离 + 透明底 + 下划线效果
   ================================================ */

/* 1. 隐藏气泡内部默认的翻译区域 */
.msg-translation-wrapper {
  display: none !important;
}

/* 2. 启用气泡下方独立的翻译块 */
.msg-translation-detached {
  display: block !important;
  margin-top: 6px !important;              /* 紧贴在原气泡下方 */
  max-width: var(--chat-message-max-width, 72%) !important;
  width: fit-content !important;
}

/* 3. 区分左右：我方翻译靠右，对方翻译靠左 */
.msg-translation-detached-me {
  align-self: flex-end !important;
}
.msg-translation-detached-them {
  align-self: flex-start !important;
}

/* 4. 核心：透明背景、文字下方加下划线 */
.msg-translation-detached-content {
  background: transparent !important;       /* 文字背景完全透明 */
  box-shadow: none !important;              /* 移除阴影 */
  border: none !important;                  /* 移除原本的气泡边框 */
  border-radius: 0 !important;              /* 移除气泡圆角 */

  /* ────────────────【 实现下划线效果 】──────────────── */
  border-bottom: 1px solid #CCCCCC !important; /* 划线颜色（可改为 #262626 或其他色系） */
  padding: 2px 4px !important;              /* 左右稍微扩宽一点，让下划线超出文字边缘更美观 */

  /* 文字样式（在横线上方显示） */
  color: #262626 !important;                /* 文字颜色，同步深灰 */
  font-size: 13.5px !important;             /* 翻译字体微调 */
  line-height: 1.4 !important;
  display: inline-block !important;
}

/* 5. 抹除之前可能残留的微信/系统自带的水印、对勾和多余伪元素 */
.msg-translation-detached-content::before,
.msg-translation-detached-content::after {
  display: none !important;
}
/* ================================================
   修改：分离翻译文字颜色改为灰色
   ================================================ */
.msg-translation-detached-content {
  color: #888888 !important;                /* 文字颜色改为灰色 */
  -webkit-text-fill-color: #888888 !important;
  border-bottom: 1px solid #DDDDDD !important; /* 下划线也同步调整为更柔和的浅灰色 */
}
/* ================================================
   修改：调整翻译文字的行距与换行宽度
   ================================================ */

.msg-translation-detached {
  /* ────────────────【 调整换行的长度（宽度限制） 】──────────────── */
  /* 数值越大，每行能装的字越多，越不容易换行。
     可以设为百分比（如 80%）或固定像素（如 260px）。 */
  max-width: 90% !important;                /* 【换行最大宽度】：默认从 72% 放宽到 80% */
}
/* ================================================
   修改：调整翻译文字距离上方消息气泡的间距
   ================================================ */

.msg-translation-detached {
  /* ────────────────【 调整距离气泡的垂直间距 】──────────────── */
  /* 数值越大，翻译文字距离上方聊天气泡就越远。
     您可以根据喜好自由微调该数值（如 8px, 12px, 16px）。 */
  margin-top: 2px !important;              /* 【间距大小】：从默认 6px 调大至 12px */
}
/* ================================================
   新增：气泡发送渐显入场动画 (Bubble Fade-In)
   ================================================ */
@keyframes bubbleFadeIn {
  from {
    opacity: 0;
    transform: translateY(10px);  /* 【渐显起点位置】：从下方10px处升起 */
  }
  to {
    opacity: 1;
    transform: translateY(0);     /* 回归正常位置 */
  }
}

/* 应用动画到所有的消息行 */
.msg-bubble-wrapper,
.msg-plain,
.msg-translation-detached,
.msg-reply-block-detached {
  animation: bubbleFadeIn 0.35s cubic-bezier(0.1, 0.8, 0.25, 1) forwards !important;
  /* 0.35s 是动画持续时间，数值越小速度越快 */
}
/* ================================================
  AI 等待气泡
   ================================================ */

/* 1. 物理清场：隐藏气泡内部的【所有】默认结构，防止多余的容器捣乱排版 */
.nuo-typing-bubble * {
  display: none !important;
}

/* 2. 气泡本体：同步对方气泡色系，并强制开启 flex 居中 */
.nuo-typing-bubble {
  /* ────────────────【 同步对方气泡样式 】──────────────── */
  background: #ffffff !important;             /* 同步：纯白底色 */
  border: 1px solid #E9E9E9 !important;       /* 同步：1px 浅灰边框 */
  border-radius: var(--bubble-them-radius, 16px) !important; /* 同步圆角 */
  padding: 8px 14px !important;               /* 与普通气泡一致的内边距 */

  /* ────────────────【 防塌陷安全锁 】───────────────── */
  display: flex !important;                   /* 启用 Flex 布局 */
  align-items: center !important;             /* 确保内部文字绝对垂直居中 */
  justify-content: center !important;         /* 确保内部文字绝对水平居中 */
  min-width: 52px !important;                 /* 【安全锁】：确保气泡绝不缩成迷你点 */
  min-height: 32px !important;                /* 【安全锁】：确保高度正常 */
  width: auto !important;
  height: auto !important;
  box-shadow: none !important;
}

/* 3. 在干净的气泡内部注入 "o.O" 文本，并加入呼吸微颤动画 */
.nuo-typing-bubble::after {
  content: "o.O" !important;                  /* 注入颜表情 */
  display: block !important;

  /* ────────────────【 同步对方文字样式 】───────────────── */
  font-family: "Courier New", monospace !important; /* 等宽字体更可爱 */
  font-size: 14px !important;                 /* 同步对方：字号 14px */
  color: #262626 !important;                  /* 同步对方：文字颜色深灰 */
  font-weight: 600 !important;                 /* 略微加粗更加明显 */
  line-height: 1 !important;
  letter-spacing: 1px !important;             /* 稍微拉开字母间距 */

  /* 专属动画 */
  animation: oOSimpleBounce 1.4s ease-in-out infinite !important; 
}

/* 4. 专属微幅呼吸弹跳动画 */
@keyframes oOSimpleBounce {
  0%, 100% {
    transform: translateY(0);
    opacity: 0.8;
  }
  50% {
    transform: translateY(-2px) scale(1.05);  /* 向上微跳 2px，并轻微放大 */
    opacity: 1;
  }
}
