    --top-menu-color: #e0e0e0 !important;

    /* 👇 底栏输入框夜间配色 */
    --input-area-bg: #1c1c1e !important;
    --input-box-color: #e0e0e0 !important;

    /* 👇 气泡夜间配色 */
    --bubble-me-bg: #000000 !important;
