/* 🎮 终极互动魔法：长方形附身（左语音，右表情） */
/* =================================== */
/* 1. 把真实的语音键拉出来，盖在左边长方形上 */
.input-row-wrapper .input-btn-mic,
.input-row-wrapper .input-btn-voice {
    display: block !important;
    position: absolute !important;
    /* 👇 直接读取你上面长方形的坐标变量，做到严丝合缝的覆盖！ */
    bottom: calc(100% + var(--rect-gap-bottom)) !important;
    left: var(--rect-left-x) !important;
    width: var(--rect-left-width) !important;
    height: var(--rect-left-height) !important;

    opacity: 0 !important;       /* 保持隐身 */
    z-index: 99 !important;      /* 冲到最高层，准备挨点 */
    cursor: pointer !important;  /* 鼠标放上去变小手 */
    margin: 0 !important;
    padding: 0 !important;
}

/* 2. 把真实的表情键拉出来，盖在右边长方形上 */
.input-row-wrapper .input-btn-sticker,
.input-row-wrapper .input-btn-emoji {
    display: block !important;
    position: absolute !important;
    /* 👇 同理，精准覆盖右边的长方形 */
    bottom: calc(100% + var(--rect-gap-bottom)) !important;
    right: var(--rect-right-x) !important;
    width: var(--rect-right-width) !important;
    height: var(--rect-right-height) !important;

    opacity: 0 !important;       /* 保持隐身 */
    z-index: 99 !important;      /* 冲到最高层 */
    cursor: pointer !important;
    margin: 0 !important;
    padding: 0 !important;
}

/* =================================== */
/* 💸 转账 & 红包卡片：统一终极样式（包含虚线与尾巴） */
/* =================================== */
:root {
  /* 👇 外壳魔法 */
  --transfer-card-width: 200px;
  --transfer-card-height: 80px;
  --transfer-card-bg: #ffffff;
  --transfer-card-radius: 12px;

  /* 👇 图标的魔法开关 (空心圆 + 箭头) */
  --transfer-circle-thickness: 2px;
  --transfer-arrow-weight: 600;
  --transfer-arrow-size: 20px;
  --transfer-icon-size: 32px;
  --transfer-icon-x: 20px;
  --transfer-icon-y: -90%;

  /* 👇 原生文字魔法开关 (转账给xxx / 微信红包) */
  --transfer-sub-x: 60px;
  --transfer-sub-y: 11px;
  --transfer-sub-size: 16px;
  --transfer-sub-color: #333333;

  /* 👇 自定义喵喵文案魔法开关 */
  --transfer-text-x: 22px;
  --transfer-text-y: 55px;
  --transfer-text-size: 14px;
  --transfer-text-color: #888888;
  --transfer-text-done: #aaaaaa;

  /* 👇 图片尾巴魔法开关 */
  --transfer-img-width: 20px;
  --transfer-img-height: 20px;
  --transfer-img-gap: 3px;
  --transfer-img-y: -2px;

  /* 👇 虚线魔法开关 */
  --transfer-line-width: 210px;
  --transfer-line-thickness: 1px;
  --transfer-line-color: #cccccc;
  --transfer-line-x: 1px;
  --transfer-line-y: 50px;
}

/* 1. 暴力隐藏所有原生零件（红包和转账的原生图标、金额全干掉） */
.msg-transfer-card * {
  visibility: hidden !important;
}

/* 2. 定型外壳 + 铺上虚线背景 */
.msg-transfer-card {
  width: var(--transfer-card-width) !important;
  height: var(--transfer-card-height) !important;
  padding: 0 !important;
  display: block !important;
  position: relative !important;
  border: none !important;
  background-color: var(--transfer-card-bg) !important;
  border-radius: var(--transfer-card-radius) !important;
  /* 虚线背景 */
  background-image: repeating-linear-gradient(to right, var(--transfer-line-color) 0, var(--transfer-line-color) 4px, transparent 4px, transparent 8px) !important;
  background-size: var(--transfer-line-width) var(--transfer-line-thickness) !important;
  background-position: var(--transfer-line-x) var(--transfer-line-y) !important;
  background-repeat: no-repeat !important;
}

:root {
  /* 👇 限制文字的最长宽度，超出的部分会自动变成省略号 */
  --transfer-sub-max: 130px;  /* 宽度你随意调，比如觉得太短可以改 140px */
}

/* 3. 抢救原生文字（转账给xx / 微信红包）+ 截断魔法 */
.msg-transfer-card .msg-transfer-subtitle {
  visibility: visible !important;
  display: block !important;
  position: absolute !important;
  left: var(--transfer-sub-x) !important;
  top: var(--transfer-sub-y) !important;
  font-size: var(--transfer-sub-size) !important;
  color: var(--transfer-sub-color) !important;
  z-index: 10 !important;
  white-space: nowrap !important;
  margin: 0 !important;
  font-weight: 500 !important;

  /* 👇 防截断黑魔法核心 */
  max-width: var(--transfer-sub-max) !important;
  overflow: hidden !important;
  text-overflow: ellipsis !important;
  padding: 0 !important;
  padding-right: calc(var(--transfer-img-width) + var(--transfer-img-gap)) !important; 
  box-sizing: border-box !important;

  /* 👇 救命魔法：把这行的“天花板”顶高，防猫爪被削头！ */
  line-height: 30px !important; 
}

/* 4. 给原生文字加上图片小尾巴（绝对保护版） */
.msg-transfer-card .msg-transfer-subtitle::after {
  content: "" !important;
  visibility: visible !important;
  position: absolute !important; /* 👈 改成绝对定位，死死钉在安全区 */
  right: 0 !important;           /* 👈 钉在最右侧 */
  top: 50% !important;
  transform: translateY(calc(-50% + var(--transfer-img-y))) !important;
  width: var(--transfer-img-width) !important;
  height: var(--transfer-img-height) !important;
  background-image: url("https://nos.netease.com/ysf/202b8643f9954bc24c2408cf346660f2.png") !important;
  background-size: contain !important;
  background-repeat: no-repeat !important;
  background-position: center right !important; 
}

/* 5. 画出空心圆和箭头 */
.msg-transfer-card::after {
  visibility: visible !important;
  content: "⇌" !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  position: absolute !important;
  left: var(--transfer-icon-x) !important;
  top: 50% !important;
  transform: translateY(var(--transfer-icon-y)) !important;
  width: var(--transfer-icon-size) !important;
  height: var(--transfer-icon-size) !important;
  border: var(--transfer-circle-thickness) solid #000000 !important;
  border-radius: 50% !important;
  font-size: var(--transfer-arrow-size) !important;    
  font-weight: var(--transfer-arrow-weight) !important;
  color: #000000 !important;
  pointer-events: none !important;
  z-index: 10 !important;
}

/* 6. 转账喵喵文案 */
.msg-transfer-card::before {
  visibility: visible !important;
  content: "♪自动收款中 谢谢喵♡" !important;
  position: absolute !important;
  left: var(--transfer-text-x) !important;
  top: var(--transfer-text-y) !important;
  font-size: var(--transfer-text-size) !important;
  font-weight: 500 !important;
  color: var(--transfer-text-color) !important;
  white-space: nowrap !important;
  pointer-events: none !important;
  z-index: 10 !important;
  letter-spacing: 0.5px !important;
}
.msg-transfer-card.msg-transfer-success::before {
  content: "小猫已收款成功=^_^=" !important;
  color: var(--transfer-text-done) !important;
}

/* 7. 🎁 红包专属喵喵文案（覆盖上面的转账文案） */
.msg-redpacket-card::before {
  content: "♪红包未拆 谢谢喵♡" !important;
}
.msg-redpacket-card.msg-transfer-success::before {
  content: "小猫已拆开红包=^_^=" !important;
}
/* =================================== */
/* 🎁 附加：红包“恭喜发财”独立位置魔法（修复猫爪重叠版） */
/* =================================== */
:root {
  /* 👇 红包文字专属位置开关，和转账互不干扰！ */
  --redpacket-sub-x: 60px;   /* 左右挪 */
  --redpacket-sub-y: 11px;   /* 上下挪 */
}

/* 1. 给红包文字单独开启绝对定位，脱离转账的控制 */
.msg-redpacket-card .msg-transfer-subtitle {
  position: absolute !important;
  left: var(--redpacket-sub-x) !important;
  top: var(--redpacket-sub-y) !important;
  font-size: 0 !important; /* 字号缩成0，隐藏原生长句 */
  margin: 0 !important;
  z-index: 10 !important;
  display: block !important;

  /* 👇 修复猫爪重叠的核心：强制收紧宽度，并把猫爪的安全区重新掏出来！ */
  width: max-content !important;
  padding: 0 !important;
  padding-right: calc(var(--transfer-img-width) + var(--transfer-img-gap)) !important;
  box-sizing: border-box !important;
}

/* 2. 伪元素重新打上“恭喜发财”，自动跟随上面的专属坐标 */
.msg-redpacket-card .msg-transfer-subtitle::before {
  content: "恭喜发财" !important;
  font-size: var(--transfer-sub-size) !important;
  color: var(--transfer-sub-color) !important;
  display: inline-block !important;
  vertical-align: middle !important;
  letter-spacing: 1px !important; 
}
/* 🌙 8. 夜间模式适配 */
@media (prefers-color-scheme: dark) {
  :root, html, body, [data-theme="dark"], [data-theme="light"], .dark-theme, .light-theme, #app {
    --transfer-card-bg: #000000 !important; 
    --transfer-sub-color: #fcfcfc !important; 
    --transfer-text-color: #fcfcfc !important;  
    --transfer-text-done: #fcfcfc !important;   
    --transfer-line-color: #fcfcfc !important; 
  }
  .msg-transfer-card::after {
    color: #fcfcfc !important;
    border-color: #fcfcfc !important;
  }
/* 🌙 夜间模式：猫爪图片变色魔法 */
  .msg-transfer-card .msg-transfer-subtitle::after {
    /* 通过滤镜把原本的颜色洗掉，变成类似 f0f0f0 的亮灰色 */
    filter: brightness(0) invert(1) opacity(0.9) !important;
  }
}
/* =================================== */
/* 💸 抢救转账金额：悬浮在虚线上方（修复穿透版） */
/* =================================== */
:root {
  /* 👇 金额的魔法开关 */
  --transfer-amount-x: 60px;          /* 左右挪：对齐文字和虚线起点 */
  --transfer-amount-y: 33px;          /* 上下挪：正好卡在虚线（50px）的上方 */
  --transfer-amount-size: 13px;       /* 金额大小 */
  --transfer-amount-weight: 600;      /* 金额粗细 */
  --transfer-amount-color: #000000;   /* 日间金额颜色 */
}

/* 1. 抢救金额本体，以及它里面的所有符号和数字！ */
.msg-transfer-card:not(.msg-redpacket-card) .msg-transfer-amount,
.msg-transfer-card:not(.msg-redpacket-card) .msg-transfer-amount * {
  visibility: visible !important;
  display: inline-block !important; /* 让符号和数字乖乖排在一行 */
}

/* 2. 给金额外壳绝对定位并上色 */
.msg-transfer-card:not(.msg-redpacket-card) .msg-transfer-amount {
  position: absolute !important;
  left: var(--transfer-amount-x) !important;
  top: var(--transfer-amount-y) !important;
  font-size: var(--transfer-amount-size) !important;
  font-weight: var(--transfer-amount-weight) !important;
  color: var(--transfer-amount-color) !important;
  z-index: 10 !important;
  margin: 0 !important;
  padding: 0 !important;
  line-height: 1 !important;
}

/* 3. 强制里面所有的字都继承我们设定的颜色和大小 */
.msg-transfer-card:not(.msg-redpacket-card) .msg-transfer-amount * {
  color: inherit !important;
  font-size: inherit !important;
  font-weight: inherit !important;
}

/* 🌙 夜间模式金额变色 */
@media (prefers-color-scheme: dark) {
  :root, html, body, [data-theme="dark"], [data-theme="light"], .dark-theme, .light-theme, #app {
    --transfer-amount-color: #fcfcfc !important; 
  }
}
/* =================================== */
/* 💸 附加：转账仅收款后显示金额 + 收款前后标题位置独立 */
/* =================================== */
:root {
  /* 👇 已收转账时，原生标题的专属上下位置（往上挪给金额腾地方） */
  --transfer-sub-y-done: 5px; 
}

/* 1. 未收转账时，强制隐藏转账金额（防穿模） */
.msg-transfer-card:not(.msg-transfer-success):not(.msg-redpacket-card) .msg-transfer-amount {
  display: none !important;
}

/* 2. 已收转账时（success），原生的“转账给xx”强行替换到专属位置！ */
.msg-transfer-card.msg-transfer-success:not(.msg-redpacket-card) .msg-transfer-subtitle {
  top: var(--transfer-sub-y-done) !important;
}
/* =================================== */
/* 🎁 附加：红包已拆开后独立显示金额 */
/* =================================== */
:root {
  /* 👇 红包专属金额魔法开关（和转账金额互不干扰） */
  --redpacket-amount-x: 60px;          /* 左右挪：比如和你的“恭喜发财”对齐 */
  --redpacket-amount-y: 33px;          /* 上下挪：比如卡在虚线上方 */
  --redpacket-amount-size: 13px;       /* 金额大小 */
  --redpacket-amount-color: #000000;   /* 日间金额颜色 */
}

/* 1. 未拆开时，强制隐藏金额（防穿模） */
.msg-redpacket-card:not(.msg-transfer-success) .msg-transfer-amount {
  display: none !important;
}

/* 2. 已拆开（success）时，抢救金额本体和里面的符号！ */
.msg-redpacket-card.msg-transfer-success .msg-transfer-amount,
.msg-redpacket-card.msg-transfer-success .msg-transfer-amount * {
  visibility: visible !important;
  display: inline-block !important; /* 让符号和数字排在一行 */
}

/* 3. 给红包金额外壳开启绝对定位并上色 */
.msg-redpacket-card.msg-transfer-success .msg-transfer-amount {
  position: absolute !important;
  left: var(--redpacket-amount-x) !important;
  top: var(--redpacket-amount-y) !important;
  font-size: var(--redpacket-amount-size) !important;
  font-weight: 600 !important;
  color: var(--redpacket-amount-color) !important;
  z-index: 10 !important;
  margin: 0 !important;
  padding: 0 !important;
  line-height: 1 !important;
}

/* 4. 强制里面所有的字（￥和数字）继承属性 */
.msg-redpacket-card.msg-transfer-success .msg-transfer-amount * {
  color: inherit !important;
  font-size: inherit !important;
  font-weight: inherit !important;
}

/* 🌙 5. 夜间模式红包金额变色 */
@media (prefers-color-scheme: dark) {
  :root, html, body, [data-theme="dark"], [data-theme="light"], .dark-theme, .light-theme, #app {
    --redpacket-amount-color: #fcfcfc !important; 
  }
}
/* =================================== */
/* 🎁 附加：红包拆开后“恭喜发财”独立位移 */
/* =================================== */
:root {
  /* 👇 已拆开时的专属上下位置（数字越小越往上，给下方的金额腾空间） */
  --redpacket-sub-y-done: 5px; 
}

/* 当红包处于已拆开（success）状态时，强行替换掉 Y 轴的坐标！ */
.msg-redpacket-card.msg-transfer-success .msg-transfer-subtitle {
  top: var(--redpacket-sub-y-done) !important;
}
/* =================================== */
/* 🏷️ 彻底隐藏引用名字与冒号 */
/* =================================== */
.msg-reply-detached-name {
  display: none !important;
}
/* =================================== */
/* 🛠️ 底栏底部“增高垫”防误触（双端统一固定版） */
/* =================================== */
:root {
  /* 👇 直接把高度写死！安卓和 iOS 都会完全一样高 */
  /* 我先给你设了 24px，如果觉得挤就改成 28px，觉得空就改回 20px */
  --bottom-lift-space: 20px; 
}

/* 暴力干掉苹果自带的安全区加成，只认我们设定的高度！ */
.input-area-custom {
  padding-bottom: var(--bottom-lift-space) !important;
}
