    --forum-post-bg: var(--tw-bg);
    --forum-chrome-bg: var(--tw-bg);
    --forum-chrome-nav-bg: var(--tw-bg);
    --forum-tabs-bg: var(--tw-bg);
    --forum-board-card-bg: var(--tw-bg);
    --forum-board-hero-bg: var(--tw-bg);
    --forum-profile-bg: var(--tw-bg);
    --forum-profile-header-bg: var(--tw-bg);
    --forum-profile-stats-bg: var(--tw-bg);
    --forum-message-item-bg: var(--tw-bg);
    --forum-comment-input-bar-bg: var(--tw-bg);

    --forum-text: var(--tw-text);
    --forum-chrome-title-color: var(--tw-text);
    --forum-chrome-icon-color: var(--tw-text);
    --forum-comment-input-color: var(--tw-text);

    --forum-text-muted: var(--tw-muted);

    --forum-divider: var(--tw-border);
    --forum-chrome-nav-border: 1px solid var(--tw-border);
    --forum-tabs-border: 1px solid var(--tw-border);
    --forum-comment-input-bar-border: 1px solid var(--tw-border);
    --forum-board-card-border: 1px solid var(--tw-border);

    --forum-comment-input-bg: var(--tw-input);
    --forum-board-icon-bg: var(--tw-icon-bg);

    --forum-accent: #1d9bf0;
    --forum-post-radius: 0px;
    --forum-post-border: none;
    --forum-post-shadow: none;
    --forum-comment-input-radius: 9999px;
    --forum-font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
}

