/* ==========================================
   PART 2: 全局排版与颜色应用 (自动跟随变量)
   ========================================== */
/* 1. 强制清理与隐藏 */
.nuo-forum-root .nuo-forum-feed > div:not(:has(.nuo-forum-post)):not(:has(.nuo-forum-tabs)):not(.nuo-forum-tabs),
.nuo-forum-root [class*="tag"], .nuo-forum-root [class*="badge"], .nuo-forum-root [class*="level"],
.nuo-forum-root .nuo-forum-post-metrics, .nuo-forum-root .nuo-forum-post-stats, .nuo-forum-root .nuo-forum-post-actions {
    display: none !important;
}

/* 2. 顶栏与全局文字清晰化 */
.nuo-forum-root .nuo-forum-chrome-header, .nuo-forum-root .nuo-forum-chrome-title, .nuo-forum-root .nuo-forum-chrome-header * { color: var(--tw-text) !important; fill: var(--tw-text) !important; stroke: var(--tw-text) !important; opacity: 1 !important; }
.nuo-forum-root .nuo-forum-post-detail-view *, .nuo-forum-root .nuo-forum-comment-content, .nuo-forum-root .nuo-forum-comment-author, .nuo-forum-root .nuo-forum-comments-header { color: var(--tw-text) !important; opacity: 1 !important; text-shadow: none !important; }
.nuo-forum-root .nuo-forum-me *, .nuo-forum-root .nuo-forum-profile *, .nuo-forum-root .nuo-forum-messages-list *, .nuo-forum-root [class*="message"] *, .nuo-forum-root .nuo-forum-board-hero * { color: var(--tw-text) !important; opacity: 1 !important; text-shadow: none !important; }
.nuo-forum-root .nuo-forum-boards-list * { color: var(--tw-text) !important; opacity: 1 !important; }
.nuo-forum-root .nuo-forum-board-card svg, .nuo-forum-root .nuo-forum-board-card [class*="stat"], .nuo-forum-root .nuo-forum-board-card [class*="meta"], .nuo-forum-root .nuo-forum-boards-list [class*="desc"], .nuo-forum-root .nuo-forum-message-preview, .nuo-forum-root .nuo-forum-board-desc, .nuo-forum-root .nuo-forum-board-hero [class*="desc"] { color: var(--tw-muted) !important; fill: var(--tw-muted) !important; }

/* 3. 页面背景与容器黑化 */
.nuo-forum-root .nuo-forum-comments, .nuo-forum-root .nuo-forum-comment { background-color: var(--tw-bg) !important; }
.nuo-forum-root .nuo-forum-boards-list, .nuo-forum-root .nuo-forum-board-detail, .nuo-forum-root .nuo-forum-messages-list, .nuo-forum-root .nuo-forum-profile, .nuo-forum-root .nuo-forum-me, .nuo-forum-root [class*="message"], .nuo-forum-root [class*="chat"] { background-color: var(--tw-bg) !important; background: var(--tw-bg) !important; }
.nuo-forum-root [class*="chat"][class*="bar"], .nuo-forum-root [class*="message"][class*="bar"], .nuo-forum-root [class*="footer"] { background-color: var(--tw-bg) !important; border-top: 1px solid var(--tw-border) !important; }
.nuo-forum-root .nuo-forum-boards-list > div:first-child, .nuo-forum-root [class*="search"] { background-color: var(--tw-bg) !important; }
.nuo-forum-root .nuo-forum-me div, .nuo-forum-root .nuo-forum-profile div, .nuo-forum-root .nuo-forum-board-card { background-color: var(--tw-bg) !important; border-color: var(--tw-border) !important; }
.nuo-forum-root .nuo-forum-chrome-nav { background-color: var(--tw-bg) !important; background-image: none !important; border-top: 1px solid var(--tw-border) !important; }

/* 4. 输入框胶囊化 */
.nuo-forum-root [class*="chat"] input, .nuo-forum-root [class*="chat"] textarea, .nuo-forum-root [class*="message"] input, .nuo-forum-root [class*="message"] textarea, .nuo-forum-root .nuo-forum-boards-list input { background-color: var(--tw-input) !important; color: var(--tw-text) !important; border: none !important; border-radius: 9999px !important; padding-left: 16px !important; padding-right: 16px !important; }
.nuo-forum-root .nuo-forum-comment-input::-webkit-input-placeholder, .nuo-forum-root .nuo-forum-comment-input::placeholder { color: transparent !important; }
.nuo-forum-root .nuo-forum-comment-input:placeholder-shown { background-image: var(--tw-reply-placeholder) !important; background-repeat: no-repeat !important; background-position: 12px center !important; }

/* 5. 评论区骨架 */
.nuo-forum-root .nuo-forum-comments { padding-left: 0 !important; padding-right: 0 !important; }
.nuo-forum-root .nuo-forum-comments-header { padding-left: 16px !important; padding-right: 16px !important; border-bottom: 1px solid var(--tw-border) !important; }
.nuo-forum-root .nuo-forum-comment { margin: 0 !important; border-radius: 0 !important; padding: 12px 16px !important; border-bottom: 1px solid var(--tw-border) !important; }

/* ⚠️ 6. 全局所有头像强制正方切圆 */
.nuo-forum-root [class*="avatar"],
.nuo-forum-root [class*="avatar"] img { 
    width: 40px !important; 
    height: 40px !important; 
    border-radius: 50% !important; 
    overflow: hidden !important; 
    object-fit: cover !important;
    flex-shrink: 0 !important;
}

/* ⚠️ 针对性排除：仅恢复板块头部（版主）的小头像尺寸 */
.nuo-forum-root .nuo-forum-board-card [class*="avatar"],
.nuo-forum-root .nuo-forum-board-card [class*="avatar"] img,
.nuo-forum-root .nuo-forum-board-hero [class*="avatar"],
.nuo-forum-root .nuo-forum-board-hero [class*="avatar"] img {
    width: 20px !important;
    height: 20px !important;
}

/* 7. 帖子紧凑排版与文字 */
.nuo-forum-root .nuo-forum-post {
    position: relative !important; display: block !important;
    padding: 12px 16px 34px 68px !important; margin: 0 !important; border-radius: 0 !important;
    border-bottom: 1px solid var(--tw-border) !important; background-color: var(--tw-bg) !important; color: var(--tw-text) !important;
}
.nuo-forum-root .nuo-forum-post:active, .nuo-forum-root .nuo-forum-post:hover { background-color: var(--tw-hover) !important; }

.nuo-forum-root .nuo-forum-post-author-name {
    position: absolute !important; top: 12px !important; left: 68px !important;
    font-size: 15px !important; font-weight: 700 !important; line-height: 1.2 !important;
    white-space: nowrap !important; overflow: visible !important; opacity: 1 !important; color: var(--tw-text) !important;
}
.nuo-forum-root .nuo-forum-post-author-name span { font-weight: 400 !important; margin-left: 4px !important; color: var(--tw-muted) !important; }
.nuo-forum-root .nuo-forum-post-time {
    position: absolute !important; top: 12px !important; right: 16px !important;
    font-size: 14px !important; line-height: 1.2 !important; color: var(--tw-muted) !important;
}
.nuo-forum-root .nuo-forum-post-title, .nuo-forum-root .nuo-forum-post-title *, .nuo-forum-root .nuo-forum-post-excerpt, .nuo-forum-root .nuo-forum-post-excerpt * {
    margin-top: 18px !important; margin-bottom: 0 !important;
    font-size: 15px !important; font-weight: 400 !important; line-height: 1.4 !important; display: block !important;
    color: var(--tw-text) !important; opacity: 1 !important;
}

/* 8. 强制空间转移：无论原论坛把头像生成在哪，帖子内的头像全钉在左上角 */
.nuo-forum-root .nuo-forum-post [class*="avatar"] {
    position: absolute !important; 
    top: 12px !important; 
    left: 16px !important;
    margin: 0 !important;
    z-index: 2 !important; 
}

/* 9. 终极匿名推特人影覆盖 */
/* 针对完全没有头像的帖子补全 */
.nuo-forum-root .nuo-forum-post:not(:has([class*="avatar"]))::before,
.nuo-forum-root .nuo-forum-comment:not(:has([class*="avatar"]))::before {
    content: ''; position: absolute !important; top: 12px !important; left: 16px !important;
    width: 40px !important; height: 40px !important; border-radius: 50% !important; overflow: hidden !important;
    background-image: var(--tw-anon-avatar) !important; background-size: cover !important; z-index: 1 !important;
}
/* 针对虽然有头像元素，但是没有 img 标签的（比如匿名）强制覆盖 */
.nuo-forum-root [class*="avatar"]:not(:has(img)):not([style*="background"]) {
    background-image: var(--tw-anon-avatar) !important; 
    background-size: cover !important; 
    color: transparent !important; 
}

/* 10. 底部数据栏 */
.nuo-forum-root .nuo-forum-post {
    background-image: var(--tw-data-a) !important;
    background-position: 68px calc(100% - 8px) !important; background-size: 290px 20px !important; background-repeat: no-repeat !important;
}
.nuo-forum-root .nuo-forum-post:nth-of-type(even) {
    background-image: var(--tw-data-b) !important;
}

/* ==========================================
   PART 3: 终极防御 (保护图片文字)
   ========================================== */
.nuo-forum-root .nuo-forum-post-media,
.nuo-forum-root .nuo-forum-post-media * {
    color: #1a1a1a !important;
    text-shadow: 0 0 4px rgba(255, 255, 255, 0.9) !important;
    opacity: 1 !important;
}

:root {
    --me-cover: url("https://nos.netease.com/ysf/72da4f895e178bc08be049495e2b6a36.jpeg");    /* 你自己背景 */
