.photo {
  width: 100%;
  height: 100%;
  object-fit: cover; 
  border-radius: 8px;
  display: block;
}

.overlay-text {
  position: absolute;
  top: 10px;
  left: 10px;
  color: #ffffff;
  text-shadow: 0 1px 4px rgba(0, 0, 0, 0.6);
  font-size: 8px;
  line-height: 1.4;
  pointer-events: none;
}

.stickers {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
}

.star {
