.main-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  width: 100%;
  padding: 0 10px;
  box-sizing: border-box;
}

.user-column {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  width: 100px; 
}

.username {
  font-size: 15px;
  font-weight: 600;
  color: #222;
}

.avatar-group {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 4px;
  width: 100%;
}

.wings {
  font-size: 14px;
  color: #999;
  font-weight: bold;
  flex-shrink: 0; 
}

.avatar-box {
  width: 70px;
  height: 70px;
  flex: 0 0 70px; 
  aspect-ratio: 1 / 1;
  border-radius: 50%;
  overflow: hidden;
  display: flex;
  justify-content: center;
  align-items: center;
