  flex-direction: column;
  align-items: center;
  gap: 4px;
  flex: 1; 
}

.heart-icon {
  font-size: 24px;
  font-weight: bold;
  line-height: 1;
  color: #222;
  margin-bottom: 4px;
}

.days {
  font-size: 32px;
  font-weight: 800;
  color: #000;
  line-height: 1.1;
}

.date-display {
  font-size: 13px;
  color: #555;
  margin-top: 2px;
}

.footer-text {
  font-size: 16px;
  font-weight: 600;
  color: #000;
  margin-top: 16px;
  letter-spacing: 0.5px;
}

.mz-2x2-collage, .mz-2x2-collage * {
  -webkit-tap-highlight-color: transparent !important;
  box-sizing: border-box;
}

.mz-2x2-collage {
  width: 100%; height: 100%; 
  position: relative;
  border-radius: 24px; 
  overflow: hidden;
  container-type: inline-size;
  font-family: -apple-system, BlinkMacSystemFont, "Helvetica Neue", "PingFang SC", sans-serif;
}

/*⁣‌⁠⁠​⁠⁠⁠‌‍‍​​​⁠‍⁠‌‌​‍‍‍‌‌​‌⁠‍⁠⁠‍‌​⁠⁠‍⁠‌‍‌‍⁠​⁠⁠⁠⁠‍​⁠‍‍​​‌‍⁠‌⁠‍​​‌‍⁣ 🌟 背景层：填满整个组件底层 */
.bg-layer {
  position: absolute; 
  inset: 0; 
  z-index: 0;
  width: 100%;
  height: 100%;
}
.bg-layer.is-glass {
  backdrop-filter: blur(24px) saturate(180%);
  -webkit-backdrop-filter: blur(24px) saturate(180%);
}

.content-layer {
  position: absolute; 
  inset: 0; 
  z-index: 1;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  padding: 8%;
  width: 100%;
  height: 100%;
}

.header-row {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 6px;
  height: 15%;
}

.css-calendar-icon {
  width: 13px;
  height: 13px;
  border: 1px solid var(--icon-color);
  border-radius: 2px;
  position: relative;
  background-color: transparent;
  flex-shrink: 0;
  margin-top: 1px; 
  background-image: linear-gradient(var(--icon-color), var(--icon-color));
  background-size: 100% 1px;
  background-position: 0 2px;
  background-repeat: no-repeat;
}

.css-calendar-icon::before {
  content: '';
  position: absolute;
  top: -2px;
  left: 3px;
  width: 1px;
  height: 3px;
  background-color: var(--icon-color);
  box-shadow: 4px 0 0 var(--icon-color);
}

.css-calendar-icon::after {
  content: '';
  position: absolute;
  top: 5px;
  left: 2px;
  width: 1px;
  height: 1px;
  background-color: var(--icon-color);
  border-radius: 50%;
  box-shadow: 
    3px 0 0 var(--icon-color),
    6px 0 0 var(--icon-color),
    0 3px 0 var(--icon-color),
    3px 3px 0 var(--icon-color),
    6px 3px 0 var(--icon-color);
}

.day-text {
  font-size: clamp(10px, 4cqw, 14px);
  font-weight: 500;
  color: var(--sub-text-color);
  letter-spacing: 0.5px;
}

.quote-row {
  display: flex;
  align-items: center;
  height: 20%;
  padding-left: 2%;
}

.main-quote {
  font-size: clamp(12px, 6.5cqw, 20px);
  font-weight: 500;
  color: var(--main-text-color);
  letter-spacing: 1px;
}

.image-gallery {
  display: flex;
  flex-direction: row;
  align-items: center;
  justify-content: space-between;
  height: 40%;
  gap: 4%;
}

.gallery-img {
  width: 30%;
  aspect-ratio: 1 / 1; 
  object-fit: cover;
  border-radius: 0px; 
  box-shadow: 0 2px 8px rgba(0,0,0,0.04); 
}

.img-center {
  transform: translateY(-8px); 
}

.footer-row {
  display: flex;
  align-items: flex-end;
  justify-content: center;
  height: 15%;
}

.datetime-text {
  font-size: clamp(10px, 3.5cqw, 13px);
  font-weight: 400;
  color: var(--sub-text-color);
  opacity: 0.8;
  letter-spacing: 0.5px;
}

.mz-music-widget {
  width: 100%; height: 100%; position: relative;
  font-family: -apple-system, BlinkMacSystemFont, "Helvetica Neue", "PingFang SC", sans-serif;
  box-sizing: border-box; overflow: hidden;
  border-radius: 36px; 
  background-color: transparent; 
}

.glass-bg {
  position: absolute; top: 0; left: 0; 
  width: 100%; height: 100%; z-index: 1;
  backdrop-filter: blur(25px) saturate(180%);
  -webkit-backdrop-filter: blur(25px) saturate(180%);
  box-shadow: 
    inset 0 1px 0px var(--highlight-top), 
    inset 1px 1px 0px rgba(255, 255, 255, 0.04), 
    inset -1px 1px 0px rgba(255, 255, 255, 0.04),
    inset 1px 0px 0px rgba(255, 255, 255, 0.02),
    inset -1px 0px 0px rgba(255, 255, 255, 0.02),
    inset 0 -1px 0px var(--highlight-bottom);
}

.content-layer {
  position: relative; z-index: 3;
  display: flex; flex-direction: column; 
  height: 100%;
  padding: 12px 14px 12px 14px; 
  box-sizing: border-box;
}

/*⁣‌⁠⁠​⁠⁠⁠‌‍‍​​​⁠‍⁠‌‌​‍‍‍‌‌​‌⁠‍⁠⁠‍‌​⁠⁠‍⁠‌‍‌‍⁠​⁠⁠⁠⁠‍​⁠‍‍​​‌‍⁠‌⁠‍​​‌‍⁣ --- 1. 顶部栏 --- */
.top-row {
  display: flex; justify-content: space-between; align-items: flex-start;
}
.album-cover {
  width: 72px; height: 72px; 
  border-radius: 22px; 
  overflow: hidden;
  background-color: transparent;
  box-shadow: 0 6px 14px rgba(0,0,0,0.04); 
  margin-left: 6px; 
}
.album-cover img {
  width: 100%; height: 100%; object-fit: cover; display: block;
}

.cover-placeholder {
  width: 100%; height: 100%; 
  position: relative;
  display: none; align-items: center; justify-content: center;
  color: var(--icon-color);
  z-index: 1;
}
.cover-placeholder::before {
  content: ''; position: absolute; top: 0; left: 0; right: 0; bottom: 0;
  background-color: var(--placeholder-bg-color);
  backdrop-filter: blur(20px) brightness(1.1) saturate(120%);
  -webkit-backdrop-filter: blur(20px) brightness(1.1) saturate(120%);
  z-index: -1;
}
.cover-placeholder svg { 
  width: 32px; height: 32px; 
  opacity: 0.9;
}

.cast-btn {
  width: 46px; height: 46px;
  display: flex; align-items: center; justify-content: center;
  color: var(--cast-icon-color);
  margin-top: 4px; 
  position: relative;
  z-index: 1;
}
.cast-btn::before {
  content: ''; position: absolute; top: 0; left: 0; right: 0; bottom: 0;
  border-radius: 50%;
  background-color: var(--cast-bg-color);
  backdrop-filter: blur(25px) brightness(1.06) saturate(120%);
  -webkit-backdrop-filter: blur(25px) brightness(1.06) saturate(120%);
  box-shadow: 
    inset 0 1px 0px rgba(255, 255, 255, 0.2),
    inset 0 0 0 1px rgba(255, 255, 255, 0.08);
  z-index: -1;
}
.cast-btn svg { 
  width: 26px; height: 26px; 
}

/* 🌟 === 中等/小尺寸适配 === 🌟 */
.mz-music-widget.size-medium .album-cover { width: 67px; height: 67px; border-radius: 20px; }
.mz-music-widget.size-medium .cover-placeholder svg { width: 30px; height: 30px; }
.mz-music-widget.size-medium .cast-btn { width: 42px; height: 42px; }
.mz-music-widget.size-medium .cast-btn svg { width: 24px; height: 24px; }

.mz-music-widget.size-small .album-cover { width: 62px; height: 62px; border-radius: 18px; }
.mz-music-widget.size-small .cover-placeholder svg { width: 28px; height: 28px; }
.mz-music-widget.size-small .cast-btn { width: 38px; height: 38px; }
.mz-music-widget.size-small .cast-btn svg { width: 22px; height: 22px; }

/* --- 2. 文本信息区 --- */
.text-row {
  display: flex; flex-direction: column; 
  gap: 0px; 
  margin-top: auto; 
  margin-bottom: 12px; 
  align-items: flex-start; 
  margin-left: 6px; 
}
.song-title {
  color: var(--song-color); font-size: var(--song-size); 
  font-weight: 500; 
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
  max-width: 100%; 
  line-height: 1.15; 
}
.artist-name {
  color: var(--artist-color); font-size: var(--artist-size); 
  font-weight: 400;
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
  max-width: 100%;
  line-height: 1.15;
}

/* --- 3. 底部播放控制区 --- */
.controls-row {
  display: flex; justify-content: center; align-items: center; 
  gap: 8px; 
  margin-bottom: -4px; 
}
.ctrl-icon {
  color: var(--icon-color);
  display: flex; align-items: center; justify-content: center;
}

/* 🌟 去除了 prev-next 的独立透明度和混合模式，彻底与 play-btn 保持一致纯色 */

.play-btn svg { width: 36px; height: 30px; }
.prev-next svg { width: 52px; height: 30px; }

custom.css:
.page {
  position: absolute;
  inset: 0;
  color: {{ink}};
  font-family: -apple-system, BlinkMacSystemFont, "SF Pro Rounded", "SF Pro Display", "PingFang SC", sans-serif;
  overflow: hidden;
  user-select: none;
}

.bg {
  position: absolute;
  inset: 0;
  background: {{accent}} url("{{portrait}}") center / cover no-repeat;
}

.bg::after {
  content: "";
  position: absolute;
  inset: 0;
}

/*⁣‌⁠⁠​⁠⁠⁠‌‍‍​​​⁠‍⁠‌‌​‍‍‍‌‌​‌⁠‍⁠⁠‍‌​⁠⁠‍⁠‌‍‌‍⁠​⁠⁠⁠⁠‍​⁠‍‍​​‌‍⁠‌⁠‍​​‌‍⁣ 顶部整体容器：整体下移 32px 避免贴顶 */
.top-container {
  position: absolute;
  top: calc(var(--safe-top, 44px) + 32px);
  left: 0;
  right: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  z-index: 5;
  text-shadow: 0 2px 10px rgba(255, 255, 255, 0);
}

/* 1. 日期与副标题：字号大小统一为 15px */
.date-sub-row {
  display: flex;
  align-items: center;
  gap: 12px;
  color: rgba(48, 51, 56, 0.9);
}

.date-text,
.subtitle-text {
  font-size: 15px;
  font-weight: 600;
  letter-spacing: 0.5px;
}

/* 2. 主标题与相伴天数小组件并排同一行 */
.title-widget-row {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 14px;
  margin-top: 20px;
}

.main-title {
  font-size: 25px;
  font-weight: 800;
  color: #303338;
  letter-spacing: -0.5px;
  line-height: 1;
}

/* 相伴天数半透明小组件 */
.days-card {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  padding: 6px 14px;
  border-radius: 16px;
  background: rgba(0, 0, 0, 0.1);
  backdrop-filter: blur(20px) saturate(180%);
  -webkit-backdrop-filter: blur(20px) saturate(180%);
  border: 1px solid rgba(0, 0, 0, 0);
  box-shadow: 0 8px 24px rgba(255, 255, 255, 0);
}

/* 日历爱心图案往宽拉伸 */
.days-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  color: #303338;
  transform: scaleX(1.15);
}

.days-content {
  display: flex;
  align-items: center;
  gap: 6px;
}

.days-num {
  font-size: 26px;
  font-weight: 700;
  color: #303338;
  line-height: 1;
  font-family: -apple-system, BlinkMacSystemFont, "SF Pro Rounded", sans-serif;
}

.days-badge {
  font-size: 11px;
  font-weight: 600;
  color: #303338;
  padding: 2px 7px;
  border-radius: 10px;
  background: rgba(255, 255, 255, 0.35);
  border: 1px solid rgba(0, 0, 0, 0);
  line-height: 1.2;
}

/* 底部通知中心 */
.notification-center {
  position: absolute;
  left: 18px;
  right: 18px;
  bottom: 95px;
  z-index: 5;
}

.nc-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 8px;
  padding: 0 4px;
}

.nc-title {
  font-size: 18px;
  font-weight: 700;
  color: #303338;
  letter-spacing: -0.3px;
  text-shadow: 0 2px 8px rgba(255, 255, 255, 0);
}

.nc-close {
  width: 25px;
  height: 25px;
  border-radius: 50%;
  box-sizing: border-box; /* 核心：锁定尺寸，加内边距绝不变形 */

  background: rgba(0, 0, 0, 0.1);
  backdrop-filter: blur(15px);
  -webkit-backdrop-filter: blur(15px);
  border: 1px solid rgba(0, 0, 0, 0);

  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 18px;
  color: rgba(48, 51, 56, 0.85);

  /* 内部 ✕ 偏下时：用底部内边距向上顶（数值越大越往上） */
  padding-bottom: 2px; 
}


.nc-card {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 14px;
  border-radius: 20px;
  background: rgba(0, 0, 0, 0.1);
  backdrop-filter: blur(25px) saturate(190%);
  -webkit-backdrop-filter: blur(25px) saturate(190%);
  border: 1px solid rgba(0, 0, 0, 0);
  box-shadow: 0 10px 30px rgba(255, 255, 255, 0);
}

.nc-avatar {
  width: 42px;
  height: 42px;
  border-radius: 10px;
  background: rgba(0, 0, 0, 0.2) url("{{img2}}") center / cover no-repeat;
  flex-shrink: 0;
  box-shadow: 0 2px 8px rgba(255, 255, 255, 0);
}

.nc-content {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 3px;
  min-width: 0;
}

.nc-top-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.nc-name {
  font-size: 15px;
  font-weight: 600;
  color: #303338;
  text-shadow: 0 1px 2px rgba(255, 255, 255, 0);
}

.nc-time {
  font-size: 12px;
  color: rgba(48, 51, 56, 0.7);
}

.nc-message {
  font-size: 14px;
  color: rgba(48, 51, 56, 0.95);
  line-height: 1.35;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  text-shadow: 0 1px 2px rgba(255, 255, 255, 0);
}

/* 底部快捷按键容器 */
.bottom-bar {
  position: absolute;
  left: 46px;
  right: 46px;
  bottom: 30px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  z-index: 10;
}

/* 1. 外层玻璃圆盘底座 */
.action-btn {
  width: 55px;
  height: 55px;
  border-radius: 50%;
  background: rgba(0, 0, 0, 0.1);
  backdrop-filter: blur(25px);
  -webkit-backdrop-filter: blur(25px);
  border: 1px solid rgba(0, 0, 0, 0);
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  color: #303338;
  box-shadow: 0 4px 12px rgba(255, 255, 255, 0);
  box-sizing: border-box;
}

/* 2. 内部网络图片图标基础设置 */
.btn-icon {
  width: 28px;  /* 图标全局大小 */
  height: 28px;
  display: block;
  background-position: center;
  background-size: contain;
  background-repeat: no-repeat;
  margin: 0;
}

/* 3. 单独微调偏移量（根据视觉感觉修改数值） */

/* 手电筒图标 */
.action-btn[data-app="1"] .btn-icon {
  transform: translate(1px, 1px); /* (左右, 上下) 负数往左/上，正数往右/下 */
}

/* 相机图标 */
.action-btn[data-app="2"] .btn-icon {
  transform: translate(0px, -1px); /* (左右, 上下) 负数往左/上，正数往右/下 */
}

