/* ------------------------------------------------------------
   四、底栏图标替换：首页/热点/游戏库/我 → 消息/朋友圈/收藏/个人主页
   仅替换图标图案，不添加任何文字标签
   ------------------------------------------------------------ */

.nj-tab-bottom-icon {
  position: relative !important;
}
/* 隐藏系统自带的图标图形，只保留容器占位——但排除未读红点/数字角标，不然角标也被一起隐藏了 */
.nj-tab-bottom-icon > *:not(.nj-tab-bottom-total-unread):not(.nj-tab-bottom-moments-dot) {
  opacity: 0 !important;
}
.nj-tab-bottom-icon::before {
  content: '';
  position: absolute;
  inset: 0;
  background-size: contain;
  background-position: center;
  background-repeat: no-repeat;
  z-index: 1;
}

