/* ios6消息列表·灰by白咪饭 — nuojiji messaging app theme */

/* QQ_消息列表 古早iOS6拟物复刻版 by白咪饭 (浅灰色版) */

:root {
    --nj-msg-chat-bg: #f2f2f4; 
    --nj-msg-bg: #f2f2f4;
    --nj-msg-text: #000000;
    --nj-msg-text-muted: #999999;
    --nj-msg-text-time: #aaaaaa;
    --nj-msg-unread-bg: #ff3b30; 
    --nj-msg-card-bg-pinned: #eaeaec; 
    --nj-msg-avatar-radius: 50%; 
    --nj-msg-tabbar-bg: #d6d6d8;
    --nj-msg-tabbar-active: #6e6e73;
    --nj-msg-tabbar-inactive: #8a8a8f;
    --nj-msg-tabbar-border: 1px solid #b0b0b3;
}

/* 🌟 核心防抖修复 + iOS6经典拉丝底纹 🌟 */
#messaging-chat-tab {
    overflow-x: hidden !important;
    width: 100% !important;
    max-width: 100vw !important;
    background-color: #e4e4e6 !important;
    background-image: 
        repeating-linear-gradient(90deg, rgba(255,255,255,0.35) 0px, rgba(255,255,255,0.35) 1px, transparent 1px, transparent 3px),
        linear-gradient(180deg, rgba(255,255,255,0.5), rgba(255,255,255,0) 40%) !important;
}

/* ==========================================
   1. 顶栏复刻 (iOS6玻璃光泽渐变 - 柔和无截断)
========================================== */
.nj-chat-tab-header {
    /* 🌟 果冻光泽改用多级平滑过渡，从上到下高光缓缓消退，绝不生硬截断 🌟 */
    background: 
        linear-gradient(180deg, 
            rgba(255,255,255,0.62) 0%, 
            rgba(255,255,255,0.38) 18%, 
            rgba(255,255,255,0.18) 34%, 
            rgba(255,255,255,0.06) 48%, 
            rgba(255,255,255,0) 60%, 
            rgba(0,0,0,0.02) 80%, 
