    --nj-msg-avatar-radius: 50%; 
    --nj-msg-tabbar-bg: #2a2c30;
    --nj-msg-tabbar-active: #7fa0d6;
    --nj-msg-tabbar-inactive: #8a919c;
    --nj-msg-tabbar-border: 1px solid #3a3d44;
}

/* 🌟 核心防抖修复 + iOS6经典拉丝底纹 🌟 */
#messaging-chat-tab {
    overflow-x: hidden !important;
    width: 100% !important;
    max-width: 100vw !important;
    background-color: #161618 !important;
    background-image: 
        repeating-linear-gradient(90deg, rgba(255,255,255,0.03) 0px, rgba(255,255,255,0.03) 1px, transparent 1px, transparent 3px),
        linear-gradient(180deg, rgba(255,255,255,0.05), rgba(255,255,255,0) 40%) !important;
}

/* ==========================================
