    background: 
        linear-gradient(180deg, 
            rgba(255,255,255,0.12) 0%, 
            rgba(255,255,255,0.07) 18%, 
            rgba(255,255,255,0.035) 34%, 
            rgba(255,255,255,0.012) 48%, 
            rgba(255,255,255,0) 60%, 
            rgba(0,0,0,0.12) 80%, 
