}

/* 💥 第一层：涂改液战术！用同色方块把右边彻底糊死！ 💥 */
.nj-chat-item-pinned::before {
    content: '' !important;
    display: block !important;
    position: absolute !important;
    right: 0 !important;
    top: 0 !important;
    bottom: 0 !important;
