#messaging-profile-tab::before,
#messaging-favorites-tab::before {
  content: '' !important;
  position: fixed !important;
  inset: 0 !important;
  background: #ffffff !important;
  z-index: -999 !important;
  pointer-events: none !important;
}

/* 3. 深色模式：所有背景变量与底层遮罩自动切为纯黑 */
[data-color-scheme="dark"] html,
[data-color-scheme="dark"] body,
[data-color-scheme="dark"] #messaging-chat-tab,
[data-color-scheme="dark"] #messaging-moments-tab,
[data-color-scheme="dark"] #messaging-profile-tab,
[data-color-scheme="dark"] #messaging-favorites-tab {
  background: #000000 !important;
  --nj-msg-bg: #000000 !important;
  --nj-msg-card-bg: #000000 !important;
}

/* 深色模式 */
[data-color-scheme="dark"] #messaging-chat-tab::before,
[data-color-scheme="dark"] #messaging-moments-tab::before,
[data-color-scheme="dark"] #messaging-profile-tab::before,
[data-color-scheme="dark"] #messaging-favorites-tab::before {
  background: #000000 !important;
}

/* ============================================================
   一、顶部 Header
   ============================================================ */

.nj-chat-tab-header {
  display: flex !important;
  align-items: center !important;
  justify-content: space-between !important;
  padding: calc(14px + var(--header-safe-top)) 18px 10px !important;
  background: transparent !important;
  border-bottom: none !important;
}

.nj-chat-tab-header-back {
  position: relative !important;
  width: auto !important;
  min-width: 80px !important;
  color: transparent !important;
  background: none !important;
}
.nj-chat-tab-header-back svg,
.nj-chat-tab-header-back img {
  display: none !important;
}
.nj-chat-tab-header-back::before {
  content: '消息';
  position: absolute;
  left: 0;
  top: 50%;
  transform: translateY(-50%);
  color: #1a1a1a;
  font-size: 30px;
  font-weight: 800;
  white-space: nowrap;
}

.nj-chat-tab-header-title-btn {
  opacity: 0 !important;
  pointer-events: auto !important;
}

.nj-chat-tab-header-edit {
  position: relative !important;
  width: 26px !important;
  height: 26px !important;
  color: transparent !important;
  background: none !important;
}
.nj-chat-tab-header-edit svg,
.nj-chat-tab-header-edit img {
  display: none !important;
}
.nj-chat-tab-header-edit::before {
  content: '';
  position: absolute;
  inset: 0;
  background-image: url('data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A//www.w3.org/2000/svg%22%20viewBox%3D%220%200%2024%2024%22%3E%3Cpath%20d%3D%22M12%203H5a2%202%200%200%200-2%202v14a2%202%200%200%200%202%202h14a2%202%200%200%200%202-2v-7%22%20fill%3D%22none%22%20stroke%3D%22%231a1a1a%22%20stroke-width%3D%222%22%20stroke-linecap%3D%22round%22%20stroke-linejoin%3D%22round%22/%3E%3Cpath%20d%3D%22M18.375%202.625a1%201%200%200%201%203%203l-9.013%209.014a2%202%200%200%201-.853.505l-2.873.84a.5.5%200%200%201-.62-.62l.84-2.873a2%202%200%200%201%20.506-.852z%22%20fill%3D%22%231a1a1a%22/%3E%3C/svg%3E');
  background-size: contain;
  background-repeat: no-repeat;
  background-position: center;
}

/* ============================================================
   二、搜索栏
   ============================================================ */

.nj-chat-tab-search {
  display: flex !important;
  align-items: center !important;
  gap: 8px !important;
  background: #f2f2f4 !important;
  border: none !important;
  outline: none !important;
  box-shadow: none !important;
  border-radius: 20px !important;
  margin: 4px 16px 10px !important;
  padding: 10px 16px !important;
  box-sizing: border-box !important;
}
.nj-chat-tab-search::before {
  content: '';
  order: -1;
  flex: 0 0 auto;
  width: 17px;
  height: 17px;
  background-image: url('data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A//www.w3.org/2000/svg%22%20viewBox%3D%220%200%2024%2024%22%3E%3Ccircle%20cx%3D%2210.5%22%20cy%3D%2210.5%22%20r%3D%227%22%20fill%3D%22none%22%20stroke%3D%22%231a1a1a%22%20stroke-width%3D%221.8%22/%3E%3Cline%20x1%3D%2220%22%20y1%3D%2220%22%20x2%3D%2215.5%22%20y2%3D%2215.5%22%20stroke%3D%22%231a1a1a%22%20stroke-width%3D%221.8%22%20stroke-linecap%3D%22round%22/%3E%3C/svg%3E');
  background-size: contain;
  background-repeat: no-repeat;
}
.nj-chat-tab-search input {
  flex: 1 1 auto !important;
  min-width: 0 !important;
  color: #1a1a1a !important;
  font-size: 15px !important;
  background: transparent !important;
  padding: 0 !important;
  margin: 0 !important;
  border: none !important;
  outline: none !important;
}
.nj-chat-tab-search input::placeholder {
  color: #9a9a9a !important;
}
.nj-chat-tab-search svg,
.nj-chat-tab-search > img,
.nj-chat-tab-search *:not(input) {
  display: none !important;
}

/* ============================================================
   三、胶囊装饰栏（重构：强制生成 陌生消息 胶囊）
   ============================================================ */

.nj-chat-tab-section-title {
  display: none !important;
}

.nj-chat-tab-notes {
  display: flex !important;
  align-items: center !important;
  gap: 12px !important;
  position: relative !important;
  height: 44px !important;
  margin: 6px 16px 8px !important;
  padding: 0 0 0 32px !important;
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
}

.nj-chat-tab-notes::before {
  content: '';
  position: absolute;
  left: 0;
  top: 50%;
  transform: translateY(-50%);
  width: 20px;
  height: 20px;
  background-image: url('data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A//www.w3.org/2000/svg%22%20viewBox%3D%220%200%2024%2024%22%3E%3Cline%20x1%3D%224%22%20y1%3D%227%22%20x2%3D%2220%22%20y2%3D%227%22%20stroke%3D%22%234a4a4a%22%20stroke-width%3D%221.7%22%20stroke-linecap%3D%22round%22/%3E%3Cline%20x1%3D%227%22%20y1%3D%2212%22%20x2%3D%2217%22%20y2%3D%2212%22%20stroke%3D%22%234a4a4a%22%20stroke-width%3D%221.7%22%20stroke-linecap%3D%22round%22/%3E%3Cline%20x1%3D%2210%22%20y1%3D%2217%22%20x2%3D%2214%22%20y2%3D%2217%22%20stroke%3D%22%234a4a4a%22%20stroke-width%3D%221.7%22%20stroke-linecap%3D%22round%22/%3E%3C/svg%3E');
  background-size: contain;
  background-repeat: no-repeat;
}

.nj-chat-tab-notes > *:first-child {
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  position: relative !important;
  width: auto !important;
  height: 32px !important;
  padding: 0 18px !important;
  border-radius: 16px !important;
  background: #f0f0f2 !important;
  color: transparent !important;
  font-size: 0 !important;
  margin: 0 !important;
}
.nj-chat-tab-notes > *:first-child * {
  display: none !important;
}
.nj-chat-tab-notes > *:first-child::before {
  content: '测试服';
  color: #1a1a1a;
  font-size: 14px;
  font-weight: 700;
  white-space: nowrap;
}

.nj-chat-tab-notes > *:nth-child(n+2) {
  display: none !important;
}

.nj-chat-tab-notes::after {
  content: '只是vc';
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  height: 30px !important;
  padding: 0 18px !important;
  border-radius: 16px !important;
  background: transparent !important;
  border: 1.3px solid #d8d8da !important;
  color: #8e8e93 !important;
  font-size: 14px !important;
  font-weight: 500 !important;
  white-space: nowrap !important;
  box-sizing: border-box !important;
}

/* ============================================================
   四、聊天列表
   ============================================================ */

.nj-chat-item {
  position: relative !important;
  padding: 10px 16px !important;
  background: transparent !important;
}
.nj-chat-item-avatar {
  width: 58px !important;
  height: 58px !important;
}
.nj-chat-item-avatar img {
  width: 100% !important;
  height: 100% !important;
}
.nj-chat-item-name {
  font-size: 15px !important;
  font-weight: 700 !important;
}
.nj-chat-item-preview {
  font-size: 13px !important;
  margin-top: -2px !important;
  color: #9a9a9a !important;

  /* 核心截断逻辑 */
  overflow: hidden !important;
  text-overflow: ellipsis !important;
  white-space: nowrap !important;

  /* 强制固定最大宽度，留出右侧时间与置顶图标的空间 */
  max-width: 92% !important; 
  display: block !important;
}

.nj-chat-item-pinned [class*="pin" i] {
  display: none !important;
}

.nj-chat-item-pinned::after {
  content: '';
  position: absolute;
  right: 23px;/* 数字越大越靠左 */
  top: 46px;      /* 从行顶往下量，不再用 bottom 猜行高，数字越大越靠下*/
  width: 18px;
  height: 18px;
  background-image: url('data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A//www.w3.org/2000/svg%22%20viewBox%3D%220%200%2024%2024%22%3E%3Cg%20transform%3D%22rotate%2835%2012%2012%29%22%3E%3Cpath%20d%3D%22M12%2017v5%20M9%2010.76a2%202%200%200%201-1.11%201.79l-1.78.9A2%202%200%200%200%205%2015.24V16a1%201%200%200%200%201%201h12a1%201%200%200%200%201-1v-.76a2%202%200%200%200-1.11-1.79l-1.78-.9A2%202%200%200%201%2015%2010.76V7a1%201%200%200%201%201-1%202%202%200%200%200%200-4H8a2%202%200%200%200%200%204%201%201%200%200%201%201%201z%22%20fill%3D%22none%22%20stroke%3D%22%239e9e9e%22%20stroke-width%3D%221.7%22%20stroke-linecap%3D%22round%22%20stroke-linejoin%3D%22round%22/%3E%3C/g%3E%3C/svg%3E');
  background-size: contain;
  background-repeat: no-repeat;
  background-position: center;
  /* 关键：提升层级，确保显示在最上层 */
  z-index: 5 !important;
  pointer-events: none !important;
}

/* ============================================================
   五、底栏：iOS 液态玻璃透明悬浮胶囊
   ============================================================ */

.nj-tab-bottom-bar {
  position: fixed !important;
  left: 14px !important;
  right: 14px !important;
  bottom: calc(6px + env(safe-area-inset-bottom, 0px)) !important;
  width: auto !important;
  height: 64px !important;
  display: flex !important;
  align-items: center !important;
  justify-content: space-around !important;
  margin: 0 !important;
  padding: 0 6px !important;
  border-radius: 34px !important;
  overflow: hidden !important;
  isolation: isolate !important;
  z-index: 999 !important;

  background: linear-gradient(180deg, rgba(255,255,255,0.7) 0%, rgba(255,255,255,0.45) 100%) !important;
  backdrop-filter: blur(28px) saturate(200%) brightness(1.06) !important;
  -webkit-backdrop-filter: blur(28px) saturate(200%) brightness(1.06) !important;
  border: 1px solid rgba(255,255,255,0.6) !important;
  box-shadow:
    0 10px 32px rgba(0,0,0,0.12),
    inset 0 1px 0 rgba(255,255,255,0.8),
    inset 0 -1px 0 rgba(0,0,0,0.03) !important;
}

.nj-tab-bottom-bar > * {
  flex: 1 1 0 !important;
  min-width: 0 !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  height: 100% !important;
}

.nj-tab-bottom-icon {
  position: relative !important;
  width: 50px !important;
  height: 42px !important;
  margin: 0 auto !important;
  border-radius: 21px !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  flex-shrink: 0 !important;
  transition: background-color 0.15s ease;
}
.nj-tab-bottom-icon > *:not(.nj-tab-bottom-total-unread):not(.nj-tab-bottom-moments-dot) {
  opacity: 0 !important;
}
.nj-tab-bottom-icon::before {
  content: '';
  position: absolute;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
  width: 25px;
  height: 25px;
  background-size: 25px 25px;
  background-position: center;
  background-repeat: no-repeat;
  z-index: 1;
}

.nj-tab-bottom-item-active .nj-tab-bottom-icon {
  background: rgba(0, 0, 0, 0.08) !important;
  box-shadow: inset 0 1px 1px rgba(255,255,255,0.5) !important;
}

