/* ============================================================
   六、深色模式适配
   ============================================================ */

[data-color-scheme="dark"] .nj-chat-tab-header {
  background: #000000 !important;
}

[data-color-scheme="dark"] .nj-chat-tab-header-back::before {
  color: #ffffff !important;
}
[data-color-scheme="dark"] .nj-chat-tab-header-edit::before {
  background-image: url('data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A//www.w3.org/2000/svg%22%20viewBox%3D%220%200%2024%2024%22%3E%3Cpath%20d%3D%22M12%203H5a2%202%200%200%200-2%202v14a2%202%200%200%200%202%202h14a2%202%200%200%200%202-2v-7%22%20fill%3D%22none%22%20stroke%3D%22%23ffffff%22%20stroke-width%3D%222%22%20stroke-linecap%3D%22round%22%20stroke-linejoin%3D%22round%22/%3E%3Cpath%20d%3D%22M18.375%202.625a1%201%200%200%201%203%203l-9.013%209.014a2%202%200%200%201-.853.505l-2.873.84a.5.5%200%200%201-.62-.62l.84-2.873a2%202%200%200%201%20.506-.852z%22%20fill%3D%22%23ffffff%22/%3E%3C/svg%3E') !important;
}

[data-color-scheme="dark"] .nj-chat-tab-search {
  background: #1c1c1e !important;
}
[data-color-scheme="dark"] .nj-chat-tab-search input {
  color: #ffffff !important;
}
[data-color-scheme="dark"] .nj-chat-tab-search input::placeholder {
  color: rgba(255,255,255,0.5) !important;
}
[data-color-scheme="dark"] .nj-chat-tab-search::before {
  background-image: url('data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A//www.w3.org/2000/svg%22%20viewBox%3D%220%200%2024%2024%22%3E%3Ccircle%20cx%3D%2210.5%22%20cy%3D%2210.5%22%20r%3D%227%22%20fill%3D%22none%22%20stroke%3D%22%23ffffff%22%20stroke-width%3D%221.8%22/%3E%3Cline%20x1%3D%2220%22%20y1%3D%2220%22%20x2%3D%2215.5%22%20y2%3D%2215.5%22%20stroke%3D%22%23ffffff%22%20stroke-width%3D%221.8%22%20stroke-linecap%3D%22round%22/%3E%3C/svg%3E') !important;
