/* 仿 Telegram 消息主页主题 */

/* 浅色模式颜色变量 */
:root,
[data-color-scheme="light"] {
  --tg-bg: #ffffff;
  --tg-surface: #f3f5f7;
  --tg-surface-2: #eef2f5;
  --tg-line: rgba(15, 23, 42, 0.05);
  --tg-text: #1c2733;
  --tg-muted: #8795a2;
  --tg-faint: #acb6bf;
  --tg-blue: #2aabee;
  --tg-blue-deep: #2496d1;
  --tg-blue-soft: #dff3ff;
  --tg-badge: #29a9e8;
  --tg-tabbar-bg: rgba(255, 255, 255, 0.96);
  --tg-tabbar-inactive: #8997a5;
  --tg-header-bg: rgba(255, 255, 255, 0.96);
  --tg-story-ring: rgba(42, 171, 238, 0.22);
  --tg-story-plus: #29a9e8;
  --tg-highlight: var(--tg-blue);
  --tg-decor-opacity: 0.16;
  --tg-flash-color: var(--tg-blue-soft);
}

/* 深色模式颜色变量 */
[data-color-scheme="dark"] {
  --tg-bg: #17212b;
  --tg-surface: #1f2a36;
  --tg-surface-2: #2b3a47;
  --tg-line: rgba(255, 255, 255, 0.08);
  --tg-text: #eef4fa;
  --tg-muted: #8fa0ae;
  --tg-faint: #70808d;
  --tg-blue: #58bdf6;
  --tg-blue-deep: #49afe8;
  --tg-blue-soft: rgba(88, 189, 246, 0.18);
  --tg-badge: #48b7f2;
  --tg-tabbar-bg: rgba(23, 33, 43, 0.94);
  --tg-tabbar-inactive: #7c8b98;
  --tg-header-bg: rgba(23, 33, 43, 0.94);
  --tg-story-ring: rgba(88, 189, 246, 0.28);
  --tg-story-plus: #52baf3;
  --tg-highlight: var(--tg-blue);
  --tg-decor-opacity: 0.16;
  --tg-flash-color: var(--tg-blue-soft);
}

/* 将主题变量应用到四个页面与底栏 */
#messaging-chat-tab,
#messaging-moments-tab,
#messaging-profile-tab,
#messaging-favorites-tab,
.nj-tab-bottom-bar {
  --nj-msg-bg: var(--tg-bg);
  --nj-msg-chat-bg: var(--tg-bg);
  --nj-msg-text: var(--tg-text);
  --nj-msg-text-muted: var(--tg-muted);
  --nj-msg-text-time: var(--tg-faint);
  --nj-msg-accent: var(--tg-blue);
  --nj-msg-card-bg: transparent;
  --nj-msg-card-bg-pinned: transparent;
  --nj-msg-card-radius: 0px;
  --nj-msg-card-border: none;
  --nj-msg-card-padding: 0px;
  --nj-msg-card-gap: 0px;
  --nj-msg-avatar-radius: 50%;
  --nj-msg-avatar-shadow: none;
  --nj-msg-unread-bg: var(--tg-badge);
  --nj-msg-unread-color: #ffffff;
  --nj-msg-tabbar-bg: var(--tg-tabbar-bg);
  --nj-msg-tabbar-active: var(--tg-blue);
  --nj-msg-tabbar-inactive: var(--tg-tabbar-inactive);
  --nj-msg-tabbar-overlay: transparent;
  --nj-msg-tabbar-radius: 0;
  --nj-msg-tabbar-padding: 0 0 calc(6px + var(--nuo-safe-bottom, 0px)) 0;
  --nj-msg-tabbar-border: 1px solid var(--tg-line);
  --nj-msg-tabbar-shadow: none;
  --nj-msg-chat-search-bg: var(--tg-surface);
  --nj-msg-chat-search-radius: 18px;
  --nj-msg-chat-note-bubble-bg: transparent;
  --nj-msg-chat-note-bubble-color: var(--tg-text);
  --nj-msg-chat-section-title-color: var(--tg-muted);
  --nj-msg-chat-header-title-color: inherit;
  --nj-msg-card-transition: all 0.2s ease;
  --nj-msg-card-active-transform: scale(0.985);
  --nj-msg-card-hover-transform: none;
  --nj-msg-fade-in-duration: 0.18s;
  --nj-msg-font-family: "PingFang SC", "Microsoft YaHei", "Noto Sans CJK SC", sans-serif;
  --nj-msg-font-family-heading: "PingFang SC", "Microsoft YaHei", "Noto Sans CJK SC", sans-serif;
}

/* 聊天页面根背景 */
#messaging-chat-tab {
  position: relative !important;
  background: var(--tg-bg) !important;
  color: var(--tg-text) !important;
}

/* 修复聊天列表最底部的原生白缝 */
#messaging-chat-tab::after {
  content: "";
  position: absolute !important;
  left: 0 !important;
  right: 0 !important;
  bottom: calc(-1 * (68px + var(--nuo-safe-bottom, 0px) / 2)) !important;
  height: calc(68px + var(--nuo-safe-bottom, 0px) / 2) !important;
  background: var(--tg-bg) !important;
  z-index: 0 !important;
  pointer-events: none !important;
}

/* 其他页面使用统一背景 */
#messaging-moments-tab,
#messaging-profile-tab,
#messaging-favorites-tab {
  background: var(--tg-bg) !important;
  color: var(--tg-text) !important;
}

/* 聊天页顶部栏 */
.nj-chat-tab-header {
  position: sticky !important;
  top: 0 !important;
  z-index: 50 !important;
  min-height: 54px !important;
  padding: calc(10px + var(--nuo-safe-top, 0px)) 14px 8px 14px !important;
  background: var(--tg-header-bg) !important;
  backdrop-filter: blur(18px) !important;
  -webkit-backdrop-filter: blur(18px) !important;
  border-bottom: none !important;
  box-shadow: none !important;
  display: flex !important;
  align-items: center !important;
  justify-content: space-between !important;
}

/* 顶部左侧 Telegram 标识 */
.nj-chat-tab-header-back {
  display: inline-flex !important;
  align-items: center !important;
  justify-content: flex-start !important;
  min-width: 70px !important;
  padding: 0 !important;
  margin: 0 !important;
  color: var(--tg-blue) !important;
  font-size: 0 !important;
  line-height: 1 !important;
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
}

/* 隐藏顶部左侧原图标 */
.nj-chat-tab-header-back::before {
  content: none !important;
  display: none !important;
}

/* 显示 Telegram 文字 */
.nj-chat-tab-header-back::after {
  content: "Telegram";
  display: inline-block;
  font-size: 22px;
  line-height: 1.1;
  font-weight: 700;
  color: var(--tg-blue);
}

/* 隐藏顶部左侧系统图标 */
.nj-chat-tab-header-back svg,
.nj-chat-tab-header-back i,
.nj-chat-tab-header-back .icon {
  display: none !important;
}

/* 顶部中间标题 */
.nj-chat-tab-header-title-btn {
  flex: 1 !important;
  text-align: center !important;
  color: var(--tg-text) !important;
  font-size: 18px !important;
  font-weight: 500 !important;
  letter-spacing: 0 !important;
}

/* 顶部右侧编辑按钮 */
.nj-chat-tab-header-edit {
  min-width: 70px !important;
  text-align: right !important;
  color: var(--tg-muted) !important;
  font-size: 18px !important;
}

/* 清理顶部栏额外伪元素 */
.nj-chat-tab-header::after,
.nj-chat-tab-header-title-btn::before,
.nj-chat-tab-header-title-btn::after {
  content: none !important;
  display: none !important;
}

/* 便签头像横向区域 */
.nj-chat-tab-notes {
  background: transparent !important;
  padding-top: 6px !important;
}

/* 单个便签项目 */
.nj-chat-tab-note-item {
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
}

/* 便签圆形头像 */
.nj-chat-tab-note-avatar {
  position: relative !important;
  width: 54px !important;
  height: 54px !important;
  border-radius: 50% !important;
  overflow: visible !important;
