/* 仿图书消息列表_vicc — nuojiji messaging app theme */

/* ============================================================
   仿图书 - vicc/vc- 请勿二传
============================================================ */

:root {
  --header-safe-top: var(--nuo-safe-top, 0px);

  /* 底栏专属变量：清空原生底栏背景/蒙层/边框/阴影/圆角，
     真正的按钮外观由下面 .nj-tab-bottom-icon 单独画 */
  --nj-msg-tabbar-bg: transparent !important;
  --nj-msg-tabbar-overlay: transparent !important;
  --nj-msg-tabbar-border: none !important;
  --nj-msg-tabbar-shadow: none !important;
  --nj-msg-tabbar-radius: 0px !important;
  --nj-msg-tabbar-padding: 0px !important;
}

/* ============================================================
   全局背景（沿用原逻辑，纯白 + 全屏遮罩）
   ============================================================ */

html,
body,
#messaging-chat-tab,
#messaging-moments-tab,
#messaging-profile-tab,
#messaging-favorites-tab {
  background: #ffffff !important;
  --nj-msg-bg: #ffffff !important;
  --nj-msg-card-bg: #ffffff !important;
  position: relative !important;
  padding-bottom: calc(64px + 24px + env(safe-area-inset-bottom, 0px)) !important;
}

#messaging-chat-tab::before,
#messaging-moments-tab::before,
#messaging-profile-tab::before,
#messaging-favorites-tab::before {
  content: '' !important;
  position: fixed !important;
  inset: 0 !important;
  background: #ffffff !important;
  z-index: -999 !important;
  pointer-events: none !important;
}

/* ============================================================
   一、顶栏：精准限定在“消息Tab”，解决错位与污染其他页面问题
   ============================================================ */


/* 1. 顶栏容器：开启 Flex 弹性布局，取消写死高度，由 Padding 动态撑高 */
#messaging-chat-tab .nj-chat-tab-header {
  position: relative !important;
  display: flex !important;
  align-items: center !important;
  gap: 8px !important; /* 掌控右侧按钮之间的间距 */

  /* 动态安全区内边距 */
  padding-top: calc(8px + var(--nuo-safe-top, env(safe-area-inset-top, 0px))) !important;
  padding-bottom: 8px !important;
  padding-left: 16px !important;
  padding-right: 16px !important;

  height: auto !important; /* 取消固定高度 */
  background: #ffffff !important;
  box-shadow: none !important;
  border-bottom: none !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  box-sizing: border-box !important;
}

/* 2. 隐藏原生中间标题 */
#messaging-chat-tab .nj-chat-tab-header-title {
  display: none !important;
}

/* 3. 左侧 Library 标题：利用 margin-right: auto 将右侧按钮推至最右端 */
#messaging-chat-tab .nj-chat-tab-header-back {
