}

/* 4. 右侧两个按钮：移除绝对定位，接入 Flex 流并跟随垂直居中 */
#messaging-chat-tab .nj-chat-tab-header-title-btn,
#messaging-chat-tab .nj-chat-tab-header-edit {
  position: relative !important; /* 清除 absolute，靠 flex 自动布局 */
  left: auto !important;
  right: auto !important;
