  color: transparent !important;
  border: none !important;
  padding: 0 !important;
  margin: 0 !important;
  z-index: 10 !important;
}

/* 5. 原生图标隐藏与点击反馈机制 */
#messaging-chat-tab .nj-chat-tab-header-title-btn > *,
#messaging-chat-tab .nj-chat-tab-header-edit > * {
  display: none !important;
}

#messaging-chat-tab .nj-chat-tab-header-title-btn:active,
#messaging-chat-tab .nj-chat-tab-header-edit:active {
