  transform: translate(-50%, -50%) !important;
  width: 22px !important;
  height: 22px !important;
  background-size: contain !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
  z-index: 2 !important;
}

#messaging-chat-tab .nj-chat-tab-header-title-btn::before {
  background-image: url('data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A//www.w3.org/2000/svg%22%20viewBox%3D%220%200%2024%2024%22%3E%3Cpath%20d%3D%22M3%206.5h18M3%2012h18M3%2017.5h13%22%20stroke%3D%22%231a1a1a%22%20stroke-width%3D%222.8%22%20stroke-linecap%3D%22round%22/%3E%3C/svg%3E') !important;
}

#messaging-chat-tab .nj-chat-tab-header-edit::before {
  background-image: url('data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A//www.w3.org/2000/svg%22%20viewBox%3D%220%200%2024%2024%22%3E%3Ccircle%20cx%3D%224.5%22%20cy%3D%2212%22%20r%3D%222.6%22%20fill%3D%22%231a1a1a%22/%3E%3Ccircle%20cx%3D%2212%22%20cy%3D%2212%22%20r%3D%222.6%22%20fill%3D%22%231a1a1a%22/%3E%3Ccircle%20cx%3D%2219.5%22%20cy%3D%2212%22%20r%3D%222.6%22%20fill%3D%22%231a1a1a%22/%3E%3C/svg%3E') !important;
}

/* 7. 未读消息角标：仅显示圆点（隐藏数字） */

.nj-chat-tab-header-edit > *:not(svg):not(img) {
  /* 精准定位 */
  position: absolute !important;
  top: 10px !important;                  /* ⬅️ 调小圆点后可微调位置 */
  right: 6px !important;
  left: auto !important;
  z-index: 99 !important;

  /* 彻底清除原生干扰 */
  transform: none !important;
  min-width: 0 !important;
  min-height: 0 !important;
  padding: 0 !important;
  margin: 0 !important;

  /* 外观尺寸（纯圆点建议 8px~10px，如需大圆点改回 14px 即可） */
  width: 5px !important;                /* ⬅️ 圆点宽度 */
  height: 5px !important;               /* ⬅️ 圆点高度 */
  background: #ff3b30 !important;        /* 背景色 */
  border-radius: 50% !important;         /* 正圆 */

  /* 核心：隐藏数字 */
  font-size: 0 !important;             /* ⬅️ 字号归零 */
  color: transparent !important;        /* ⬅️ 文字透明 */
  display: block !important;
  box-sizing: border-box !important;
}

/* 1. 强制顶栏宽度与盒模型计算 */
#messaging-chat-tab .nj-chat-tab-header {
  width: 100% !important;
  max-width: 100vw !important;
  box-sizing: border-box !important;
}

/* 2. 左侧标题区：允许在空间不足时自动收缩，防止把右侧按钮挤出屏幕 */
#messaging-chat-tab .nj-chat-tab-header-back {
  min-width: 0 !important; /* 关键：允许 Flex 子项缩小到内容以下 */
  flex-shrink: 1 !important; /* 空间不足时优先缩小自身 */
  margin-right: auto !important; /* 继续保持将右侧按钮推向最右 */
}

/* 3. 右侧按钮群：禁止任何形式的压缩 */
#messaging-chat-tab .nj-chat-tab-header-title-btn,
#messaging-chat-tab .nj-chat-tab-header-edit {
  flex-shrink: 0 !important; /* 关键：绝对不允许被挤压变形或推隐 */
}

/* ============================================================
   二、搜索栏 —— 按你的要求，保持原样，不改
   ============================================================ */

.nj-chat-tab-search {
  display: flex !important;
  align-items: center !important;
  gap: 5px !important;
  background: #f2f2f4 !important;
  border: none !important;
  outline: none !important;
  box-shadow: none !important;
  border-radius: 20px !important;
  margin: 4px 16px 10px !important;
  padding: 10px 16px !important;
  box-sizing: border-box !important;
}
.nj-chat-tab-search::before {
  content: '';
  order: -1;
  flex: 0 0 auto;
  width: 17px;
  height: 17px;
  background-image: url('data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A//www.w3.org/2000/svg%22%20viewBox%3D%220%200%2024%2024%22%3E%3Ccircle%20cx%3D%2210.5%22%20cy%3D%2210.5%22%20r%3D%227%22%20fill%3D%22none%22%20stroke%3D%22%231a1a1a%22%20stroke-width%3D%221.8%22/%3E%3Cline%20x1%3D%2220%22%20y1%3D%2220%22%20x2%3D%2215.5%22%20y2%3D%2215.5%22%20stroke%3D%22%231a1a1a%22%20stroke-width%3D%221.8%22%20stroke-linecap%3D%22round%22/%3E%3C/svg%3E');
  background-size: contain;
  background-repeat: no-repeat;
}
.nj-chat-tab-search input {
  flex: 1 1 auto !important;
  min-width: 0 !important;
  color: #1a1a1a !important;
  font-size: 15px !important;
  background: transparent !important;
  padding: 0 !important;
  margin: 0 !important;
  border: none !important;
  outline: none !important;
}
.nj-chat-tab-search input::placeholder {
  color: #9a9a9a !important;
}
.nj-chat-tab-search svg,
.nj-chat-tab-search > img,
.nj-chat-tab-search *:not(input) {
  display: none !important;
}

/* ============================================================
   三、隐藏 便签横滚栏 + 筛选/分组胶囊栏（含"陌生消息"分组按钮）
   ============================================================ */

.nj-chat-tab-notes,
.nj-chat-tab-section-title {
  display: none !important;
}

/* ============================================================
   聊天列表：头像（正方形 + 柔和圆角 + 图5同款底部阴影）
   ============================================================ */

.nj-chat-item {
  position: relative !important;
  padding: 8px 16px !important;
  background: transparent !important;
  display: flex !important;
  align-items: center !important;
  overflow: visible!important;
}

 /* ============================================================
   头像自定义变量配置
   ============================================================ */
:root {
  --my-avatar-size: 50px;   /* ⬅️ 统一修改尺寸 */
  --my-avatar-radius: 10px; /* ⬅️ 统一修改圆角 */
}

/* 1.1 精准限定：仅修改【聊天列表】头像尺寸 */
.nj-chat-item-avatar,
.nj-chat-item-avatar * {
  width: var(--my-avatar-size, 48px) !important;
  height: var(--my-avatar-size, 48px) !important;
  flex-basis: var(--my-avatar-size, 48px) !important;
}

/* 1.2 专属恢复：【朋友圈封面】大头像尺寸与位置 */
[class*="moments" i] [class*="header" i] [class*="avatar" i],
.nj-moments-header-avatar {
  width: 68px !important;
  height: 68px !important;
  flex-basis: 68px !important;
  border-radius: 12px !important;
  filter: drop-shadow(0 2px 6px rgba(0, 0, 0, 0.2)) !important;
}

/* 2. 样式细节与圆角阴影微调 */
.nj-chat-item-avatar {
  border-radius: var(--my-avatar-radius) !important;
  position: relative !important;
  flex-shrink: 0 !important;
  background-color: #f2f2f7 !important;
  margin-right: auto !important;
  overflow: visible !important;
  box-shadow: none !important;
  filter: drop-shadow(0 4px 4px rgba(0, 0, 0, 0.15)) !important;
}

/* 3. 清除内部遮罩与圆角同步 */
.nj-chat-item-avatar,
.nj-chat-item-avatar *,
.nj-chat-item-avatar img {
  border-radius: var(--my-avatar-radius) !important;
  clip-path: none !important;
  -webkit-clip-path: none !important;
  mask-image: none !important;
  -webkit-mask-image: none !important;
  object-fit: cover !important;
}

.nj-chat-item-avatar img {
  display: block !important;
}


/* 名字 */
.nj-chat-item-name {
  font-size: 13px !important;
  font-weight: 700 !important;
  color: #1a1a1a !important;
  white-space: nowrap !important;
  flex-shrink: 0 !important;
}

/* 预览：与名字同行，超出省略 */
.nj-chat-item-name,
.nj-chat-item-preview {
  display: inline-flex !important;
  align-items: center !important;
}


.nj-chat-item-preview {
  font-size: 13px !important;
  display: block !important;
  width: 100% !important;
  padding-right: 65px !important; /* 强制留出安全距离 */
  box-sizing: border-box !important;
  overflow: hidden !important;
  text-overflow: ellipsis !important;
  white-space: nowrap !important;
}


/* 时间戳：右上角小字 */
.nj-chat-item-time {
  position: absolute !important;
  top: 26px !important;
  right: 16px !important;
  font-size: 12px !important;
  color: #b0b0b3 !important;
  font-weight: 400 !important;
}

/* 每个聊天列表右侧添加 “•••” 装饰图标 */
.nj-chat-item {
  --nj-item-deco-1-content: "•••";
  --nj-item-deco-1-right: 16px;
  --nj-item-deco-1-top: 50%;
  --nj-item-deco-1-transform: translateY(-50%);
  --nj-item-deco-1-font-size: 12px;
  --nj-item-deco-1-color: #8e8e93;
  --nj-item-deco-1-letter-spacing: -1px;
}

/* 夜间模式颜色自适应 */
[data-color-scheme="dark"] .nj-chat-item {
  --nj-item-deco-1-color: #636366;
}

/* 将时间戳整体向左推（可自行调整 -28px 的数值） */
.nj-chat-item-time {
  transform: translateX(-28px) !important;
}


/* ============================================================
   置顶态修复：纯净浅灰背景 + 浅灰云朵 + 强行隐藏原生针头
   ============================================================ */

/* 1. 强行彻底隐藏原生的红色置顶针图标 */
.nj-chat-item-pinned [class*="pin" i] {
  display: none !important;
}

/* 2. 置顶背景*/

.nj-chat-item[data-pinned="true"],
.nj-chat-item[data-top="true"],
.nj-chat-item.is-pinned,
.nj-chat-item.is-top {
  background-color: #F5F5F7 !important; /* 干净清爽的浅灰色 */
  background-image: none !important;
}

/* 修改名字与下方预览消息的距离 */

/* 1. 调整名字下方的间距 */
.nj-chat-item-title,
.nj-chat-item-name,
.nj-chat-item [class*="title" i],
.nj-chat-item [class*="name" i] {
  margin-bottom: 4px !important; /* ⬅️ 数值越大间距拉得越 */
}

/* 2. 调整预览消息上方的间距（备选控制） */
.nj-chat-item-preview,
.nj-chat-item-digest,
.nj-chat-item [class*="preview" i],
.nj-chat-item [class*="digest" i] {
  margin-top: 0px !important;    /* ⬅️ 若觉得间距太宽，可设为负数（如 -2px） */
}

/*  修改头像旁边的未读角标 */
.nj-chat-item-avatar {
  position: relative !important; /* 确保角标能以此容器定位 */
}

.nj-chat-item-avatar [class*="badge" i],
.nj-chat-item-avatar [class*="unread" i] {
  /* 1. 强制重置尺寸，覆盖头像给的 48px 巨型宽高 */
  width: auto !important;
  height: 18px !important;
  min-width: 18px !important;
  flex-basis: auto !important;
  padding: 0 5px !important;

  /* 2. 文字/数字完美居中 */
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  font-size: 11px !important;
  font-weight: bold !important;
  line-height: 1 !important;

  /* 3. 描边与颜色样式 */
  background-color: #ff3b30 !important;
  color: #ffffff !important;
  border-radius: 999px !important;      /* 椭圆/胶囊角标 */
  border: 1.5px solid #ffffff !important;
  box-sizing: border-box !important;

  /* 4. 定位到头像右上角 */
  position: absolute !important;
  top: -3px !important;
  right: -3px !important;
  z-index: 10 !important;
}



/* ============================================================
   六、底栏：晶莹玻璃质感悬浮底栏（图标点击前后一致 + 玻璃选中态）
   ============================================================ */

#messaging-bottom-shell {
  background: none !important;
  background-color: transparent !important;
  background-image: none !important;
  border: none !important;
  box-shadow: none !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
}

/* 1. 悬浮底栏大外壳（白色半透明柔和底座） */
.nj-tab-bottom-bar {
  position: fixed !important;
  left: 50% !important;
  transform: translateX(-50%) !important;
  bottom: calc(16px + env(safe-area-inset-bottom, 0px)) !important;
  width: min(92%, 350px) !important;
  height: 55px !important;
  display: flex !important;
  align-items: center !important;
  justify-content: space-around !important;
  margin: 0 !important;
  padding: 0 8px !important;
  background: rgba(255, 255, 255, 0.82) !important;
  border-radius: 32px !important;
  border: 1px solid rgba(255, 255, 255, 0.6) !important;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.08) !important;
  backdrop-filter: blur(25px) !important;
  -webkit-backdrop-filter: blur(25px) !important;
  z-index: 999 !important;
}

/* 2. 单个 Tab 图标基础容器 */
.nj-tab-bottom-icon {
  position: relative !important;
  width: 50px !important;
  height: 50px !important;
  border-radius: 50px !important;
  background: transparent !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  flex-shrink: 0 !important;
  transition: all 0.25s cubic-bezier(0.4, 0, 0.2, 1) !important;
}

.nj-tab-bottom-icon > *:not(.nj-tab-bottom-total-unread):not(.nj-tab-bottom-moments-dot) {
  opacity: 0 !important;
}

/* 3. 选中激活态：3D 液体/晶莹玻璃胶囊质感 */
.nj-tab-bottom-item-active .nj-tab-bottom-icon {
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.95) 0%, rgba(240, 240, 245, 0.5) 100%) !important;
  border: none !important;
  box-shadow: 
    inset 0 -2px 4px rgba(0, 0, 0, 0.04),       /* 底部边缘阴影 */
    0 6px 16px rgba(0, 0, 0, 0.08) !important;  /* 外悬浮柔和阴影 */
  backdrop-filter: blur(12px) !important;
  -webkit-backdrop-filter: blur(12px) !important;
  /* ⬇️ 加入 translateY(2px)，把整个选中胶囊往下拉 */
  transform: scale(1.02) translateY(2px) !important;
}


/* 图标通用尺寸定位 */
.nj-tab-bottom-icon::before {
  content: '' !important;
  position: absolute !important;
  left: 50% !important;
  top: 50% !important;
  transform: translate(-50%, -50%) !important;
  width: 24px !important;
  height: 24px !important;
  background-size: contain !important;
  background-position: center !important;
  background-repeat: no-repeat !important;
  z-index: 1 !important;
}

