/*⁣‌⁠⁠​⁠⁠⁠‌‍‍​​​⁠‍⁠‌‌​‍‍‍‌‌​‌⁠‍⁠⁠‍‌​⁠⁠‍⁠‌‍‌‍⁠​⁠⁠⁠⁠‍​⁠‍‍​​‌‍⁠‌⁠‍​​‌‍⁣ SOGAN粉 by 小e — nuojiji messaging app theme */

/* =========================================================
   SOGON / 소곤 · SOFT PINK by 小e
   Korean Social Messenger

   本主题仅允许修改以下 2 个图片链接：

   ⭐️⭐️⭐️ 01｜个人头像
   ⭐️⭐️⭐️ 02｜状态主图素材

   除上述两个 ⭐️⭐️⭐️ 标记项外，
   其余素材链接均为主题固定素材，不可更改。
   ========================================================= */


/* =========================================================
   01｜CHAT · 聊天页
   ========================================================= */

#messaging-chat-tab {

  /* ⭐️⭐️⭐️【可自行更换 01｜个人头像】⭐️⭐️⭐️ */
  --sogon-my-avatar:
    url('https://i.postimg.cc/HkD2ch7r/IMG-1323.jpg');


  /* ⭐️⭐️⭐️【可自行更换 02｜状态主图素材】⭐️⭐️⭐️ */
  --sogon-cover:
    url('https://i.postimg.cc/6pjvgC7D/IMG-1429.jpg');


  /* ---------- 固定装饰素材｜不可更改 ---------- */

  --sogon-frame:
    url('https://i.postimg.cc/43VcVfVP/IMG-1339.png');

  --sogon-header-action:
    url('https://i.postimg.cc/BQJC3wRs/IMG-1345.png');


  /* ---------- SOFT PINK 基础主题 ---------- */

  --nj-msg-chat-bg: #fff7fa;
  --nj-msg-bg: #fff7fa;

  --nj-msg-text: #3b3135;
  --nj-msg-text-muted: #a28f97;
  --nj-msg-text-time: #b9a6ad;
  --nj-msg-accent: #8f596d;

  --nj-msg-card-bg: transparent;
  --nj-msg-card-bg-pinned: #f8e9ee;

  --nj-msg-card-radius: 0;
  --nj-msg-card-border: none;
  --nj-msg-card-padding: 13px 16px;
  --nj-msg-card-gap: 12px;

  --nj-msg-avatar-radius: 13px;
  --nj-msg-avatar-shadow: none;

  --nj-msg-unread-bg: #8d566a;
  --nj-msg-unread-color: #ffffff;

  --nj-msg-chat-search-bg: #fffdfd;
  --nj-msg-chat-search-radius: 15px;

  --nj-msg-card-active-transform: scale(0.985);
  --nj-msg-card-hover-transform: none;

  --nj-msg-card-transition:
    transform 0.18s ease,
    background 0.18s ease;

  --nj-msg-fade-in-duration: 0.2s;

  background: #fff7fa !important;
}


/* ---------- Header ---------- */

.nj-chat-tab-header {
  position: relative !important;

  padding:
    calc(8px + var(--nuo-safe-top))
    18px
    22px
    18px !important;

  background:
    rgba(255, 247, 250, 0.94) !important;

  backdrop-filter: blur(20px) !important;
  -webkit-backdrop-filter: blur(20px) !important;

  border-bottom: none !important;
  box-shadow: none !important;

  overflow: visible !important;

  z-index: 60 !important;
}


/* 顶部韩语语录 */

.nj-chat-tab-header::before {
  content:
    '조금 느려도 괜찮아 ૮₍˶ᵔ ᵕ ᵔ˶₎ა' !important;

  position: absolute !important;

  top:
    calc(22px + var(--nuo-safe-top)) !important;

  left: 50% !important;

  transform:
    translateX(-50%) !important;

  color: #967f88 !important;

  font-size: 12px !important;
  font-weight: 600 !important;

  letter-spacing: -0.01em !important;
  line-height: 1 !important;

  white-space: nowrap !important;

  pointer-events: none !important;

  z-index: 30 !important;
}


/* ---------- 真正账号切换按钮 → MY 头像 ---------- */

.nj-chat-tab-header-title-btn {
  position: absolute !important;

  left: 35px !important;

  top:
    calc(100% + 1px) !important;

  width: 42px !important;
  height: 42px !important;

  min-width: 42px !important;
  min-height: 42px !important;

  padding: 0 !important;
  margin: 0 !important;

  background-image:
    var(--sogon-my-avatar) !important;

  background-size: cover !important;
  background-position: center !important;
  background-repeat: no-repeat !important;

  background-color: #f5e8ed !important;

  border:
    3px solid #fffdfd !important;

  border-radius: 14px !important;

  box-shadow:
    0 4px 15px rgba(120, 72, 90, 0.08) !important;

  color: transparent !important;

  font-size: 0 !important;
  line-height: 0 !important;

  overflow: visible !important;

  z-index: 100 !important;
}


.nj-chat-tab-header-title-btn > * {
  opacity: 0 !important;
  visibility: hidden !important;
}


/* MY 标签 */

.nj-chat-tab-header-title-btn::after {
  content: 'MY' !important;

  position: absolute !important;

  right: -8px !important;
  bottom: -5px !important;

  padding:
    3px 6px !important;

  background: #8d566a !important;
  color: #ffffff !important;

  border:
    2px solid #fff7fa !important;

  border-radius: 999px !important;

  font-size: 6.5px !important;
  font-weight: 750 !important;

  line-height: 1 !important;

  letter-spacing: 0.07em !important;

  box-shadow:
    0 2px 6px rgba(120, 72, 90, 0.08) !important;

  pointer-events: none !important;
}


.nj-chat-tab-header-title-btn:active {
  transform: scale(0.94) !important;

  transition:
    transform 0.12s ease !important;
}


/* ---------- 右上角固定素材按钮｜不可更改 ---------- */

.nj-chat-tab-header-edit {
  position: relative !important;

  width: 41px !important;
  height: 41px !important;

  padding: 0 !important;

  display: flex !important;

  align-items: center !important;
  justify-content: center !important;

  background-color: #fffdfd !important;

  background-image:
    var(--sogon-header-action) !important;

  background-size: 33px 33px !important;
  background-position: center !important;
  background-repeat: no-repeat !important;

  border:
    1px solid #f0dfe5 !important;

  border-radius: 14px !important;

  box-shadow:
    0 4px 14px rgba(120, 72, 90, 0.05) !important;

  overflow: hidden !important;
}


.nj-chat-tab-header-edit svg,
.nj-chat-tab-header-edit img,
.nj-chat-tab-header-edit > * {
  opacity: 0 !important;
  visibility: hidden !important;
}


.nj-chat-tab-header-edit:active {
  transform: scale(0.93) !important;

  transition:
    transform 0.12s ease !important;
}


/* ---------- 隐藏原便签 ---------- */

.nj-chat-tab-notes {
  display: none !important;
}


/* =========================================================
   CHAT · 搜索框
   ========================================================= */

.nj-chat-tab-search {
  position: relative !important;

  width: auto !important;

  height: 42px !important;
  min-height: 42px !important;

  margin:
    -8px
    22px
    11px
    88px !important;

  padding: 0 !important;

  display: flex !important;

  align-items: center !important;

  box-sizing: border-box !important;

  background: #fffdfd !important;

  border:
    1px solid #f0dfe5 !important;

  border-radius: 15px !important;

