/* 触发区锁死在左下角，防误触 */
.nook-buddy::before { 
  content: "" !important; position: absolute !important; bottom: 100% !important; 
  left: 0 !important; width: 30vw !important; height: 80px !important; 
}
.nook-buddy:hover, .nook-buddy:active, .nook-buddy:focus-within { transform: translateY(0) !important; opacity: 1 !important; }
.nook-buddy-bubble { background: rgba(248,249,250,0.9) !important; backdrop-filter: blur(10px) !important; border: 1px solid rgba(0,0,0,0.05) !important; box-shadow: 0 4px 15px rgba(0,0,0,0.05) !important; color: #333 !important; }

.nook-note, .nook-buddy-ask, .nook-note-ask, .nook-selbar, .nook-toc, .nook-set-sheet, .nook-buddy-panel, .nook-sheet, .nook-modal, .nook-jump { background: rgba(248, 249, 250, 0.92) !important; backdrop-filter: blur(20px) !important; border: 1px solid rgba(0, 0, 0, 0.05) !important; box-shadow: 0 10px 30px rgba(0,0,0,0.1) !important; }
.nook-note *, .nook-buddy-ask *, .nook-note-ask *, .nook-selbar *, .nook-toc *, .nook-set-sheet *, .nook-buddy-panel *, .nook-sheet *, .nook-modal *, .nook-jump * { color: #333333 !important; }
.nook-toc-head, .nook-modal-head { padding-right: 12px !important; }
.nook-toc-head .nook-modal-close, .nook-toc-head .nook-icon-btn, .nook-modal-close { margin-left: auto !important; }
.nook-toc-item.active, .nook-set-theme.active, .nook-set-font.active { background: rgba(0, 0, 0, 0.06) !important; color: #000000 !important; border-radius: 8px !important; }
.nook-sheet-cancel, .nook-modal-close { background: rgba(0, 0, 0, 0.04) !important; border-radius: 12px !important; }
.nook-note { border-left-color: rgba(0, 0, 0, 0.15) !important; }

