/*⁣‌⁠⁠​⁠⁠⁠‌‍‍​​​⁠‍⁠‌‌​‍‍‍‌‌​‌⁠‍⁠⁠‍‌​⁠⁠‍⁠‌‍‌‍⁠​⁠⁠⁠⁠‍​⁠‍‍​​‌‍⁠‌⁠‍​​‌‍⁣⁣​​‌​​​‍‌‍⁠​‌‍​​‍⁠‌​‌‍​​​‌⁠​‍​‌‌⁠​‌​⁠‌‌‌‍‌​‌‍‌‌‌‍⁠⁠⁠‌​⁠⁠‍‍​‍⁠‌‍‍⁠⁣ 名册与公开标签 */
.roster-app-container {
  color: var(--pc-ink) !important;
  background: var(--pc-paper) center / cover no-repeat !important;
}
/* 菜单存在时淡入全屏蒙罩，关闭后淡出。只覆盖视觉，保留应用点击逻辑。 */
.roster-app-container::after {
  content: "" !important;
  display: block !important;
  position: fixed !important;
  box-sizing: border-box !important;
  inset: 0 !important;
  width: auto !important;
  height: auto !important;
  margin: 0 !important;
  padding: 0 !important;
  border: 0 !important;
  border-radius: 0 !important;
  background: rgba(34,27,48,.38) !important;
  box-shadow: none !important;
  filter: none !important;
  transform: none !important;
  animation: none !important;
  opacity: 0 !important;
  visibility: hidden !important;
  pointer-events: none !important;
  transition: opacity .22s ease,visibility 0s linear .22s !important;
  z-index: 900 !important;
}
.roster-app-container:has(.fab-popup-text)::after {
  opacity: 1 !important;
  visibility: visible !important;
  transition-delay: 0s !important;
}
.roster-theme-guofeng > .roster-stardust {
  display: none !important;
}
.roster-title {
  color: var(--pc-ink) !important;
  font-family: var(--pc-font) !important;
  letter-spacing: .12em !important;
  text-shadow: 0 1px 0 #fff !important;
}
.category-pill {
  color: var(--pc-ink-2) !important;
  border-color: #d5bd9c !important;
  background: linear-gradient(140deg,#fffdf9,#f2ecef) !important;
  box-shadow: 0 2px 6px #5e3e6518 !important;
}
.category-pill.active {
  color: var(--pc-ink) !important;
  border-color: var(--pc-gold) !important;
  background: linear-gradient(140deg,#faf5ff,#dcd0ec) !important;
  box-shadow: inset 0 0 0 2px #ffffff80 !important;
}
.roster-search-bar {
  color: var(--pc-ink-2) !important;
  border-color: #d4c0a6 !important;
  background: #fffcf8e8 !important;
}
.rj-name span {
  color: var(--pc-ink) !important;
  font-family: var(--pc-font) !important;
  letter-spacing: .1em !important;
}
.rj-tassel,.rj-chain {
  display: none !important;
}
.rj-sway {
  animation: none !important;
}

/* 详情背景；保留原画卷镜头 */
.rs-overlay,.rg-hall,.roster-tarot-detail {
  color: var(--pc-ink) !important;
  background: var(--pc-paper) center / cover no-repeat !important;
}
.rs-world img {
  content: var(--pc-world) !important;
}
.rs-top {
  color: var(--pc-ink) !important;
}
.rs-ib,.rjs-act {
  color: var(--pc-ink) !important;
  border-color: #c6a06c !important;
  background: radial-gradient(circle at 35% 25%,#fffdfb,#ece2f1) !important;
  box-shadow: inset 0 0 0 2px #fff9ef99 !important;
}
.rs-nav {
  color: var(--pc-gold) !important;
}
.rs-hero,.rs-mini {
  border-color: #c6a06c !important;
  box-shadow: 0 4px 14px #3c2d491f !important;
}
.rs-name,.rg-title h2,.rjs-title h2 {
  color: var(--pc-ink) !important;
  font-family: var(--pc-font) !important;
