  fill: none !important;
  width: 24px !important;
  height: 24px !important;
  stroke-width: 1.8 !important;
}

/* 7. 按草稿顺序重排：编辑 → 档案 → 导出 → 简洁 */
.rs-top .rs-ib[title="编辑"]      { order: 1 !important; }
.rs-top .rs-ib[title="档案"]      { order: 2 !important; }
.rs-top .rs-ib[title="导出角色包"] { order: 3 !important; }
