.rs-stage:has(.rs-scene-facts.is-on) .rs-top > *:not([title="关闭"]),
.rs-stage:has(.rs-scene-persona.is-on) .rs-top > *:not([title="关闭"]),
.rs-stage:has(.rs-scene-world.is-on) .rs-top > *:not([title="关闭"]) {
  display: none !important;
}
