/* =====================================
   顶栏下移避开刘海 + 顶部填充同色块（不露背景图）
===================================== */

/* 极低饱和色盘 */
#this-moment-screen {
  --header-solid: #f7f2f4;           /* 顶栏实色粉白 */
  --bubble-glass: rgba(248, 242, 244, 0.28);
  --border-dim: rgba(180, 168, 174, 0.25);
  --text-main: #6b5e63;
  --text-dim: #97888e;
  --move-down: 28px;                  /* 顶栏下移距离，可调 */
}

/* 背景图清晰 */
.tm-bg-image {
  background-image: url("https://img.heliar.top/file/1781170638909_1040g3k031je6duca300g5n0kf4r1h51fne5oh9g!nd_dft_wlteh_jpg_3.jpeg") !important;
  background-size: cover !important;
  background-position: center !important;
  filter: none !important;
}

.tm-bg-overlay {
  background: rgba(242, 236, 238, 0.45) !important;
}

/* 定义下移距离 */
#this-moment-screen {
  --move-down: 28px;   /* 根据需要调整 */
}

/* 顶栏：整体下移 + 向上发射同色阴影遮住背景图 */
.tm-header {
  margin-top: var(--move-down) !important;
  background: #f7f2f4 !important;     /* 顶栏实色 */
  box-shadow: 0 calc(-1 * var(--move-down)) 0 0 #f7f2f4 !important;  /* 向上延伸色块 */
  border-bottom: 0.5px solid rgba(180, 168, 174, 0.25) !important;
  padding: 4px 12px !important;       /* 顶栏自身厚度保持不变 */
  min-height: auto !important;
  position: relative !important;
  /* 无需额外 z-index，无遮挡问题 */
}

/* 其余样式（气泡磨砂、低饱和等保持不变） */
.tm-para-char,
.tm-para-user {
  backdrop-filter: blur(20px) !important;
  -webkit-backdrop-filter: blur(20px) !important;
  background: var(--bubble-glass) !important;
  border: 0.5px solid var(--border-dim) !important;
  border-radius: 28px !important;
}

.tm-body-char,
.tm-body-user {
  color: var(--text-main) !important;
  font-size: 14px !important;
}

/* 压缩输入框整体区域 */
.tm-compose {
  padding: 6px 16px 12px !important;   /* 减少上下内边距，之前较大 */
}

/* 压缩输入框自身高度 */
.tm-input {
  padding: 6px 16px !important;        /* 垂直内边距减小，降低高度 */
  min-height: 36px !important;         /* 限制最小高度，不让它撑高 */
  font-size: 13px !important;          /* 文字稍微缩小（可选） */
}

/* 发送按钮也按比例缩小（可选） */
.tm-send-btn {
  width: 32px !important;
  height: 32px !important;
}

/* 工具栏按钮也稍微紧凑（可选） */
.tm-regen-btn,
.tm-suggestions-btn {
  padding: 2px 8px !important;
  font-size: 11px !important;
}

