/* ============================================
   思维链：我吃吃吃吃吃 感谢吃吃吃宝宝的代码
   ============================================ */

/* 取消之前容易引发拉撑的 ::after 伪元素 */
.tm-para-char::after, .tm-para-user::after {
  display: none !important;
}

/* ===== 1. 默认静态假装饰 ===== */
.tc-divider {
  grid-column: 2 !important;
  grid-row: 3 !important;
  margin-top: -12px !important; /* 控制"展开回复"字体的整体高度 */
  margin-bottom: 0 !important;
  padding-top: 6px !important;
  padding-bottom: 18px !important; /* 👈 核心：加大底部内边距，把分割线单独往下压 */
  border: none !important;
  border-bottom: 1px solid #e4e7ed !important; /* 日间版分割线颜色 */
  display: flex !important;
  justify-content: flex-start !important;
  align-items: center !important;
  background: transparent !important;
  width: 100% !important;
}

/* 强制覆盖基础代码里的隐藏规则，确保角色一输出立刻有线 */
.tm-para:last-child .tc-divider {
  border-bottom: 1px solid #e4e7ed !important;
}

.tc-divider-text {
  margin: 0 !important;
  padding: 0 !important;
  background: transparent !important;
  display: inline-block !important;
}

.tc-divider-text::before {
  content: "—— 展开回复 1225 >" !important;
  color: #6b7a8f !important; /* 网易云灰蓝 */
  font-size: 13px !important;
  font-weight: 500 !important;
  letter-spacing: 0.3px !important;
  line-height: 1.5 !important;
  opacity: 0.85 !important;
  pointer-events: none !important;
}

/* 用户消息不显示展开回复，但保留下方的短分割线 */
.tm-para-user .tc-divider-text::before { 
  display: none !important; 
}

/* ===== 2. 动态检测：当卡片内存在真实思维链时，隐藏静态假装饰 ===== */
.tm-para-char:has(.tm-thinking-wrapper) .tc-divider {
  display: none !important;
}

/* ===== 3. 真实思维链组件 ===== */
.tm-thinking-wrapper {
  grid-column: 2 !important;
  grid-row: 3 !important;
  margin-top: 4px !important; /* 开启思维链时的垂直位置 */
  margin-bottom: 0 !important;
  padding-top: 6px !important;
  padding-bottom: 18px !important; /* 👈 同样加大底部内边距，把线往下推 */
  border-bottom: 1px solid #e4e7ed !important; /* 同款日间分割线 */
  position: relative !important;
  z-index: 20 !important;
  pointer-events: auto !important;
  transform: translateZ(0) !important;
  will-change: height, opacity !important;
  contain: layout style !important;
}

/* 抹掉思维链默认胶囊外形 */
.tm-thinking-toggle {
  background: transparent !important;
  border: none !important;
  border-radius: 0 !important;
  padding: 2px 0 !important;
  display: inline-flex !important;
  align-items: center !important;
  gap: 4px !important;
  cursor: pointer !important;
  box-shadow: none !important;
  position: relative !important;
  z-index: 21 !important;
  pointer-events: auto !important;
  -webkit-tap-highlight-color: transparent !important;
  user-select: none !important;
}

/* 隐藏原生图标 */
.tm-thinking-icon,
.tm-thinking-caret {
  display: none !important;
}

/* 替换真实思维链的文字 */
.tm-thinking-label {
  font-size: 0 !important;
  pointer-events: none !important;
}

.tm-thinking-label::before {
  content: "—— 展开回复 1225 >" !important;
  color: #6b7a8f !important; /* 网易云灰蓝 */
  font-size: 13px !important;
  font-weight: 500 !important;
  letter-spacing: 0.3px !important;
  display: inline-block !important;
  transition: color 0.15s linear !important;
}

.tm-thinking-toggle:hover .tm-thinking-label::before {
  text-decoration: underline !important;
  color: #4a5a6f !important; /* 悬停加深 */
}

/* 展开状态的文字 */
.tm-thinking-wrapper.is-open .tm-thinking-label::before {
  content: "—— 收起回复 <" !important;
  color: #8895a8 !important; /* 日间版展开后的灰蓝 */
}

/* 展开后的二楼评论区内容面板 - 日间版 */
.tm-thinking-panel {
  background: #f5f7fa !important; /* 浅灰背景 */
  border: 1px solid #e4e7ed !important; /* 浅色边框 */
  border-left: 2px solid #6b7a8f !important; /* 灰蓝左边框 */
  border-radius: 8px !important;
  padding: 10px 12px !important;
  margin-top: 8px !important;
  color: #2c3e50 !important; /* 深灰文字 */
  font-size: 13.5px !important;
  line-height: 1.6 !important;
  box-shadow: 0 1px 4px rgba(0, 0, 0, 0.06) !important; /* 轻盈阴影 */
  position: relative !important;
  z-index: 20 !important;
  animation: tmThinkingFadeIn 0.2s cubic-bezier(0.25, 0.1, 0.25, 1) forwards !important;
  transform-origin: top center !important;
}

/* 面板内链接和强调文字 */
.tm-thinking-panel a {
  color: #6b7a8f !important;
}

.tm-thinking-panel strong {
  color: #1a2a3a !important;
}

@keyframes tmThinkingFadeIn {
  from {
    opacity: 0;
    transform: translateY(-4px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

