/* === 最终完整版：包含所有模块与细节修正 === */

:root {
  /* ☀️ 白天模式变量 */
  --bg-image: url('https://i.postimg.cc/bYTXRxFK/1040g3k831m9rj14dksdg5phb0pdguafeo1tdf90.jpg');
  --rain-heavy: rgba(255, 255, 255, 0.8);
  --rain-light: rgba(255, 255, 255, 0.4);
  --glass-bg: rgba(255, 255, 255, 0.35); 
  --glass-bar: rgba(255, 255, 255, 0.65);
  --glass-btn: rgba(255, 255, 255, 0.4);
  --glass-border: rgba(255, 255, 255, 0.7);
  --glass-inner: inset 0 1px 2px rgba(255, 255, 255, 0.8);
  --glass-shadow: 0 8px 32px rgba(31, 38, 135, 0.15);
  --text-main: #2c3e50;
  --text-mute: #5a6c7d;
  --text-glow: 0 1px 2px rgba(255, 255, 255, 0.5);
  --water-blue: #b3e5fc; 
}

@media (prefers-color-scheme: dark) {
  :root {
    /* 🌙 夜晚模式变量 */
    --bg-image: url('https://i.postimg.cc/Twg5rWM9/IMG-0890.jpg');
    --rain-heavy: rgba(255, 255, 255, 0.7);
    --rain-light: rgba(255, 255, 255, 0.3);
    --glass-bg: rgba(20, 25, 30, 0.4);
    --glass-bar: rgba(15, 20, 25, 0.65);
    --glass-btn: rgba(255, 255, 255, 0.1);
    --glass-border: rgba(255, 255, 255, 0.15); 
    --glass-inner: inset 0 1px 1px rgba(255, 255, 255, 0.1);
    --glass-shadow: 0 -4px 24px rgba(0, 0, 0, 0.5);
    --text-main: #e8eaed;
    --text-mute: #b0c4de;
    --text-glow: 0 1px 3px rgba(0, 0, 0, 0.8);
    --water-blue: #b3e5fc;
  }
}

/* 1. 壁纸引擎 */
#this-moment-screen { background: #000 !important; }
.tm-bg-image { display: none !important; } 
.tm-bg-overlay { background: var(--bg-image) center/cover no-repeat !important; opacity: 1 !important; transition: background 0.8s ease; }

/* 2. 错落有致的斜雨 (保留你指定的版本) */
.tm-bg-overlay::before, .tm-bg-overlay::after {
  content: '' !important; position: absolute !important; top: -50%; left: -50%; width: 200%; height: 200%; pointer-events: none !important; z-index: 1 !important; transform: rotate(15deg);
}
.tm-bg-overlay::before {
  background-image: radial-gradient(ellipse 1.5px 40px at 40px 20px, var(--rain-heavy) 0%, transparent 100%), radial-gradient(ellipse 2px 50px at 120px 80px, var(--rain-heavy) 0%, transparent 100%), radial-gradient(ellipse 1.5px 30px at 180px 40px, var(--rain-light) 0%, transparent 100%);
  background-size: 200px 200px; animation: rainFall 1.1s linear infinite;
}
.tm-bg-overlay::after {
  background-image: radial-gradient(ellipse 1px 25px at 20px 60px, var(--rain-light) 0%, transparent 100%), radial-gradient(ellipse 1.5px 35px at 90px 140px, var(--rain-light) 0%, transparent 100%), radial-gradient(ellipse 1px 45px at 150px 10px, var(--rain-heavy) 0%, transparent 100%);
  background-size: 170px 170px; animation: rainFall 1.6s linear infinite;
}
@keyframes rainFall { 0% { background-position-y: 0, 0, 0; } 100% { background-position-y: 100vh, 100vh, 100vh; } }

/* 3. 对话气泡与头像圆角 */
