}

/* =========================================
   🌟 9. 纯 CSS 绘制：擦亮黄铜打字机按键 + 字母图标
========================================= */

/* 🌟 拉开工具栏按钮间距，消除拥挤感 */
.tm-compose-toolbar {
  gap: 12px !important; 
}

/* 基础材质共用：全部换成“擦亮黄铜”质感 */
.tm-regen-btn, .tm-suggestions-btn, .tm-send-btn { 
  border-radius: 50% !important;
  background: radial-gradient(circle at 50% 20%, #a39579 0%, #6b5d45 40%, #362e20 100%) !important;
  border: 1px solid #0a0805 !important; 

  /* 核心 3D 金属光影 */
  box-shadow: 
    inset 0px 1px 1px rgba(255, 255, 255, 0.15), 
    inset 0px -3px 5px rgba(0, 0, 0, 0.8),       
    0px 3px 5px rgba(0, 0, 0, 0.6),              
    0px 1px 1px rgba(0, 0, 0, 0.9) !important;   

  transition: all 0.1s ease !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  position: relative !important;

  /* 🌟 核心：强制隐藏所有按钮自带的原生文字（如“建议回应”） */
  font-size: 0 !important;
  color: transparent !important;
}

/* 🌟 工具栏按钮：大幅缩小，增加精致感 */
.tm-regen-btn, .tm-suggestions-btn {
  width: 24px !important; 
  height: 24px !important;
  padding: 0 !important; /* 去除原本按钮自带的多余内边距 */
}

/* 🌟 发送按钮：保持较大尺寸作为主按键，并自由调整位置 */
.tm-send-btn {
  width: 34px !important; 
  height: 34px !important;

  /* 👇 新增：开启自由定位 */
  position: absolute !important;

  /* 👇 左右调整：数字越大越往左，改小（甚至负数）就往右 */
  right: 2px !important; 

  /* 👇 上下调整：数字越大越往上，改小（甚至负数）就往下 */
  bottom: 15px !important; 
}


/* 隐藏原本的 SVG 图标 */
.tm-regen-btn svg, .tm-suggestions-btn svg, .tm-send-btn svg {
  display: none !important;
}

/* 统一设置字母的样式 (雕刻感) */
.tm-regen-btn::before, .tm-suggestions-btn::before, .tm-send-btn::before {
  font-family: var(--typewriter-font) !important;
  color: #0d0b08 !important; /* 极深的刻痕颜色 */
  text-shadow: 0px 1px 0px rgba(255, 255, 255, 0.3) !important; 
  line-height: 1 !important;
  display: block !important;
}

/* 字母大小区分（重新单独给字母指定大小，不受按钮 font-size:0 影响） */
.tm-regen-btn::before, .tm-suggestions-btn::before { font-size: 12px !important; }
.tm-send-btn::before { font-size: 16px !important; }

/* 单独映射每个按钮的英文字母 */
.tm-compose-toolbar > .tm-regen-btn:nth-of-type(1)::before { content: 'R'; } /* Reroll 重投 */
.tm-compose-toolbar > .tm-regen-btn:nth-of-type(2)::before { content: 'C'; } /* Continue 继续 */
.tm-compose-toolbar > .tm-regen-btn:nth-of-type(3)::before { content: 'N'; } /* Noise 白噪音 */
.tm-compose-toolbar > .tm-regen-btn:nth-of-type(4)::before { content: 'P'; } /* Photo 拍照 */
.tm-compose-toolbar > .tm-regen-btn:nth-of-type(5)::before { content: 'F'; } /* Finish 完结 */
.tm-compose-toolbar > .tm-suggestions-btn::before { content: 'T'; }          /* Tips 建议 */
.tm-send-btn::before { content: 'S'; }                                       /* Send 发送 */

/* 按钮按下时的机械物理反馈 */
.tm-regen-btn:active, .tm-suggestions-btn:active, .tm-send-btn:active {
  transform: translateY(2px) !important;
  box-shadow: 
    inset 0px 2px 4px rgba(0, 0, 0, 0.8),
    0px 1px 1px rgba(0, 0, 0, 0.4) !important;
}

/* 发送按钮【未就绪】状态 (变暗沉，没有文字时显示) */
.tm-send-btn:not(.ready) {
  background: radial-gradient(circle at 50% 15%, #6e5f48 0%, #3d3426 50%, #1a1610 100%) !important;
}
.tm-send-btn:not(.ready)::before {
  text-shadow: 0px 1px 0px rgba(255, 255, 255, 0.15) !important;
}

/* 白噪音开启状态 (保持按下凹陷) */
.tm-regen-btn.active {
  transform: translateY(1px) !important;
  background: radial-gradient(circle at 50% 20%, #5c5243 0%, #362f25 40%, #17140f 100%) !important;
  box-shadow: inset 0px 2px 4px rgba(0, 0, 0, 0.8) !important;
}

/* =============================================
   纯黑推特评论区 + 双背景图气泡
   日夜自动跟随系统 · 去灰提纯版
   已适配安卓 + iOS 安全区
   🍔🍔 = 可修改内容（名称 / ID / 文案）
   ============================================= */

:root {
  /* 颜色 */
  --bg-primary: #000000;
  --bg-card: #000000;
  --bg-hover: #080808;
  --bg-input: #000000;
  --bg-btn: #000000;
