}

/* 输入区、建议区、加载文案跟系统字体 */
.tm-input,
.tm-suggestion-text,
.tm-suggestion-direction,
.tm-suggestion-reroll,
.tm-loading-text,
.tm-loading-text::before,
.tm-compose-row::before {
