.tm-compose-toolbar>.tm-regen-btn:nth-of-type(3)::before,
.tm-compose-toolbar>.tm-regen-btn:nth-of-type(4)::before,
.tm-compose-toolbar>.tm-regen-btn:nth-of-type(5)::before,
.tm-compose-toolbar>.tm-suggestions-btn::before,
.tm-send-btn::before,
.tm-header-right .tm-btn-icon:first-child::before,
.tm-header-right .tm-btn-icon:nth-child(2)::before {
