}

.tm-para-char .tc-avatar-area {
  display: grid !important;
  justify-items: center !important;
  align-content: start !important;
  width: 150px !important;
  min-width: 150px !important;
  margin: -26px 0 0 -22px !important;
  position: relative !important;
  z-index: 12 !important;
  overflow: visible !important;
}

.tm-para-char .tc-avatar-frame {
  position: relative !important;
  display: block !important;
  box-sizing: border-box !important;
  width: 150px !important;
  height: 150px !important;
  min-width: 150px !important;
  min-height: 150px !important;
  margin: 0 !important;
  padding: 0 !important;
  background: transparent !important;
  box-shadow: none !important;
  filter: drop-shadow(0 6px 12px rgba(0, 0, 0, 0.08)) !important;
  overflow: visible !important;
  z-index: 1 !important;
  transform: rotate(-3deg) !important;
}

.tm-para-char .tc-avatar-frame .tc-avatar-img {
  position: absolute !important;
  display: block !important;
  width: 70% !important;
  height: 70% !important;
  top: 50% !important;
  left: 50% !important;
  right: auto !important;
  bottom: auto !important;
  margin: 0 !important;
  padding: 0 !important;
  object-fit: cover !important;
  object-position: center !important;
  transform: translate(-50%, -50%) !important;
  background: transparent !important;
  box-shadow: none !important;
  z-index: 2 !important;
}

.tm-para-char .tc-avatar-frame::before {
  content: '' !important;
  position: absolute !important;
  inset: 0 !important;
  display: block !important;
  width: 100% !important;
  height: 100% !important;
  background-image: url('https://i.imgant.com/v2/amxJiee.png') !important;
