/* =========================================================
   11. 动态动画
   ========================================================= */

@keyframes tmStickerFloat {
  0%, 100% { transform: translateY(0) rotate(0deg); }
  50% { transform: translateY(-3px) rotate(2deg); }
}

@keyframes tmCharacterStickerFloat {
  0%, 100% { transform: translateY(0) rotate(0deg); }
  50% { transform: translateY(-3px) rotate(1deg); }
}

@keyframes tmUserStickerFloat {
  0%, 100% { transform: translateY(0) rotate(0deg); }
  50% { transform: translateY(-3px) rotate(-1deg); }
}

@keyframes tmWatermarkDrift {
  0% { background-position: 0 0; }
  50% { background-position: 18px 12px; }
  100% { background-position: 0 0; }
}

.tm-no-animations .tc-avatar-frame::before,
.tm-no-animations .tc-avatar-frame-user::before,
.tm-no-animations .tc-watermark,
.tm-no-animations .tc-deco-top::after,
.tm-no-animations .tc-deco-bottom::after {
  animation: none !important;
}

@media (prefers-reduced-motion: reduce) {
  .tm-para-char, .tm-para-user, .tm-send-btn { transition: none !important; }
  .tc-avatar-frame, .tc-avatar-frame-user, .tc-watermark,
  .tc-deco-top::after, .tc-deco-bottom::after {
    animation: none !important;
  }
}


/* =========================================================
   12. 细节与强调 (按人物分色：角色黄青 / 用户蓝灰)
   ========================================================= */

/* --- 基础对话块底色 --- */
.tm-quote-block {
  color: #4f5766 !important;
  background: rgba(255, 255, 255, 0.4) !important; 
  border: 1px dashed rgba(131, 184, 232, 0.6) !important;
