/* 角色和用户对话框左侧统一为嫩蓝色 */
.tm-para-char .tm-quote-block:nth-of-type(2n+1),
.tm-para-char .tm-quote-block:nth-of-type(2n),
.tm-para-user .tm-quote-block:nth-of-type(2n+1),
.tm-para-user .tm-quote-block:nth-of-type(2n) {
  border-left: 4px solid #9ccff0 !important;
