}


.tm-body-char::after {
  display: none !important;
}



@keyframes np-blink {
  0%, 100% { opacity: 1; }
  50% { opacity: 0; }
}

/* ═══════════════════════════════════
   §8 引号— 灰色荧光笔贴字
   ═══════════════════════════════════ */
.tm-quote-block {
