/* ═══════════════════════════════════════════
   🎬 YouTube Cinema Theme — 修正版2
   ═══════════════════════════════════════════ */

:root {
  --banner-img: url("https://i.postimg.cc/x8Ft0HQt/IMG-20260404-130037.jpg");
  --banner-h: 200px;
  --red: #FF0000;
  --bg1: #0f0f0f;
  --bg2: #181818;
  --bg3: #272727;
  --bg4: #3a3a3a;
  --t1: #f1f1f1;
  --t2: #aaaaaa;
  --t3: #717171;
  --border: #333;
  --blue: #3ea6ff;
  --sub-img: url("https://i.postimg.cc/SQvfQRKB/MEITU-20260404-191811248.jpg");
  --sub-h: 240px;
  --sub-top: -310px;       /* 上下移 */
  --sub-left: 0px;      /* 左右移 */
  --sub-pos: center center;
}

/* ═══ 根 ═══ */
#this-moment-screen {
  background: var(--bg1) !important;
  color: var(--t1) !important;
}

/* ═══ 隐藏原始装饰 ═══ */
.tm-bg-container,
.tm-bg-image,
.tm-bg-overlay,
.tc-deco-top,
.tc-deco-bottom,
.tc-deco-left,
.tc-deco-right,
.tc-deco-center,
.tc-watermark {
  display: none !important;
}

/* ═══════════════════════════════════════════
   🔝 顶部栏
   ═══════════════════════════════════════════ */
.tm-header {
  background: var(--bg1) !important;
  border-bottom: 1px solid var(--border) !important;
  padding: 8px 12px !important;
  z-index: 50 !important;
}

.tm-btn-icon {
  color: var(--t1) !important;
  background: transparent !important;
  border-radius: 50% !important;
  width: 40px !important;
  height: 40px !important;
}
.tm-btn-icon:hover {
  background: var(--bg3) !important;
}

.tm-top-drop-btn,
.tm-top-drop-btn-user {
  background: var(--bg3) !important;
  border: none !important;
  border-radius: 8px !important;
  padding: 6px 12px !important;
}

.tm-header-avatar {
  border: 2px solid var(--red) !important;
  border-radius: 50% !important;
  width: 32px !important;
  height: 32px !important;
}

.tm-header-name {
  color: var(--t1) !important;
  font-size: 14px !important;
  font-weight: 500 !important;
}

.tm-top-vs {
  color: var(--t3) !important;
  font-size: 12px !important;
}

/* ═══════════════════════════════════════════
   📖 故事区
   ═══════════════════════════════════════════ */
.tm-story {
  padding: 0 7px !important;
  background: var(--bg1) !important;
}

/* ═══════════════════════════════════════════
   📸 角色头部 = 横幅图片区
   ★ background-size: cover = 全覆盖
   ★ banner-h 改这个调图片高度
   ═══════════════════════════════════════════ */
.tc-header {
  position: relative !important;
  z-index: 10 !important;
  min-height: calc(var(--banner-h) + 80px) !important;
  padding: 0px !important;
  padding-top: var(--banner-h)- 0px）!important;
  padding-bottom: 12px !important;
  padding-left: 16px !important;
  padding-right: 16px !important;
  margin: 0  -7px!important;
  background-color: var(--bg1) !important;
  /* ★★★ 图片比例/覆盖方式改这里 ★★★ */
  background-size: cover !important;
  /* cover = 全覆盖裁切  |  contain = 完整显示  |  100% 200px = 指定宽高 */
  background-position: center top !important;
  /* center top / center center / center 30% 调图片显示位置 */
  background-repeat: no-repeat !important;
  overflow: visible !important;
}
/* ★★★ 用 ::after 做独立图片层，高度锁死 ★★★ */
.tc-header::after {
  content: '' !important;
  position: absolute !important;
  top: 0 !important;
  left: 0 !important;
  right: 0 !important;
  height: var(--banner-h) !important; 
  background-image: var(--banner-img) !important;
  background-size: cover !important;
  background-position: center top !important;
  background-repeat: no-repeat !important;
  z-index: 0 !important;
  pointer-events: none !important;
}
/* 底部渐变遮罩 — 让图片和头像区自然过渡 */
.tc-header::before {
  content: '' !important;
  position: absolute !important;
  top: 0 !important;
  left: 0 !important;
  right: 0 !important;
  height: calc(var(--banner-h) + 10px) !important;
  background: linear-gradient(
    to bottom,
    transparent 0%,
    transparent 40%,
    rgba(15, 15, 15, 0.5) 70%,
    var(--bg1) 100%
  ) !important;
  z-index: 1 !important;
  pointer-events: none !important;
}

/* ★★★ 红色横线已删除 — 不再有 ::after ★★★ */

.tc-header-main {
  position: relative !important;
  z-index: 5 !important;
  gap: 12px !important;
  align-items: flex-start !important;
  margin-top: 0 !important;
  padding-top: 340px !important;
}

.tc-avatar-frame {
  width: 40px !important;
  height: 40px !important;
  border-radius: 50% !important;
  border: 3px solid var(--bg1) !important;
