.tm-para-char .tm-voice-btn,
.tm-para-char .tm-rec-btn,
.tm-para-char .tm-lang-label,
.tm-para-char .tm-mic-btn,
.tm-voice-controls,
.tm-voice-icon,
.tm-voice-label {
  display: none !important;
}

/* .tm-body-char 必须是 static，让伪元素相对于 .tm-para-char 定位 */
.tm-body-char {
  position: static !important;
  overflow: visible !important;
}

/* 播放按钮 —— .tm-body-char::after */
.tm-body-char::after {
  content: "" !important;
  display: block !important;
  position: absolute !important;
  bottom: 12px !important;
  left: 16px !important;
