  content: "" !important;
  display: block !important;
  position: absolute !important;
  bottom: 12px !important;
  left: 60px !important;
  width: 36px !important;
  height: 36px !important;
  border-radius: 50% !important;
  border: var(--btn-border-width) solid var(--blue-main) !important;
