/* ==========================================================
   生命是一万次的春和景明 · 清透无黑主题
   ========================================================== */

/* ---------- 0. 设计变量（全局无黑色，纯绿阶） ---------- */
:root {
  --text-main:   #55705f; /* 正文：清透的灰绿 */
  --text-quote:  #2b4234; /* 对话：深邃的墨绿 */
  --text-bold:   #173c2c; /* 重点：深沉稳重的松绿色，不突兀但极有质感 */
  --text-mute:   #7c9686; /* 次要文字 */
}

/* ---------- 1. 背景层：自然透气的绿意 ---------- */
#this-moment-screen { background: #fcfdfc !important; }
.tm-bg-image { display: none !important; }

.tm-bg-overlay {
  background: url('https://user36150.cn.imgto.link/public/20260925/1783220875790.avif') center/cover no-repeat !important;
  filter: blur(7px) saturate(0.6) brightness(1.03) !important;
}

.tm-bg-overlay::after {
  content: '' !important;
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, rgba(255,255,255,0.5) 0%, rgba(255,255,255,0.3) 50%, rgba(255,255,255,0.55) 100%) !important;
  backdrop-filter: blur(2px) !important;
  -webkit-backdrop-filter: blur(2px) !important;
}

/* ---------- 2. 顶部导航栏：左上角文案，隐藏头像名字，保留原位功能键 ---------- */
.tm-header {
  position: relative !important;
  background: rgba(255, 255, 255, 0.12) !important;
  backdrop-filter: blur(20px) !important;
  -webkit-backdrop-filter: blur(20px) !important;
  border-bottom: 1px solid rgba(255, 255, 255, 0.35) !important;
  box-shadow: none !important;
  padding-top: max(10px, calc(10px + var(--nuo-safe-top, 0px))) !important;
}

.tm-header::before {
  content: '生命是一万次的春和景明' !important;
  position: absolute !important;
  left: 46px !important; 
  top: calc(var(--nuo-safe-top, 0px) + 14px) !important; 
  font-family: 'Zhi Mang Xing', 'KaiTi', cursive !important;
  font-size: 15px !important;
  color: #8a9f92 !important; /* 柔和的灰绿 */
  z-index: 10 !important;
  pointer-events: none !important;
  white-space: nowrap !important;
  line-height: 22px !important;
}

.tm-header::after {
  content: 'Life is a thousand spring days.' !important;
  position: absolute !important;
  left: 46px !important;
  top: calc(var(--nuo-safe-top, 0px) + 32px) !important; 
  font-size: 8px !important;
  font-family: Georgia, serif !important;
  color: #a3b5a9 !important; /* 极淡的雾绿 */
  letter-spacing: 0.5px !important;
  text-transform: uppercase !important;
  z-index: 10 !important;
  pointer-events: none !important;
  white-space: nowrap !important;
}

/* 3. 彻底隐藏原有头像和名字 */
.tm-header-avatar, 
.tm-header-avatar-wrap, 
.tm-header-avatar-fallback,
.tm-top-drop-btn .tm-header-name,
.tm-top-drop-btn-user .tm-header-name,
.tm-top-vs {
  display: none !important;
}

/* 4. 保留切换键的占位和点击区域，视觉上透明 */
.tm-top-drop-btn,
.tm-top-drop-btn-user {
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  min-width: 40px !important; 
  height: 30px !important;
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  opacity: 0 !important; /* 隐身但可点击 */
  pointer-events: auto !important; 
}

/* 顶栏右侧功能键颜色 */
.tm-header-right .tm-btn-icon { color: #4a6b56 !important; }

/* ---------- 3. 故事区 & 聊天框（铺满无边界） ---------- */
.tm-story { padding: 0 !important; -webkit-overflow-scrolling: touch !important; }

.tm-para-char, .tm-para-user {
  width: 100% !important;
  margin: 0 !important;
  border-radius: 0 !important;
  border: none !important;
  background: transparent !important;
  box-shadow: none !important;
  padding: 20px 16px !important;
}

.tm-para-user { background: rgba(255, 255, 255, 0.05) !important; }

.tm-body-char, .tm-body-user {
  color: var(--text-main) !important;
  font-size: 14.5px !important;
  font-weight: 300 !important;
  line-height: 1.95 !important;
  letter-spacing: 0.5px !important;
  text-shadow: 0 1px 2px rgba(255, 255, 255, 0.6) !important;
}

/* ---------- 4. 对话（引用框）：清透的绿色 ---------- */
.tm-quote-block {
  border-left: 3px solid #4a6b56 !important; 
  background: linear-gradient(to right, rgba(142, 186, 162, 0.18), rgba(142, 186, 162, 0.02)) !important;
  padding: 10px 14px !important;
  border-radius: 0 8px 8px 0 !important;
  margin: 14px 0 !important;
}

.tm-quote {
  color: var(--text-quote) !important;
  font-style: italic !important;
  font-weight: 400 !important;
}

/* ---------- 5. 重点文字：纯正松绿，加粗加深，绝对不突兀！ ---------- */
.tm-bold {
  color: var(--text-bold) !important; /* 👈 深邃松绿，彻底告别紫蓝和黑色 */
  font-weight: 700 !important;        /* 👈 加粗，确保重点突出 */
  background: rgba(23, 60, 44, 0.08) !important; /* 👈 极淡的松绿底色托底 */
  padding: 1px 5px !important;
  border-radius: 4px !important;
  /* 如果框架自带紫色高亮，这里强力覆盖 */
  -webkit-text-fill-color: var(--text-bold) !important;
  text-shadow: none !important;
}

.tm-action { color: #7c9686 !important; font-style: italic !important; }

/* ---------- 6. 消息内头部信息 ---------- */
.tc-header { padding: 0 0 10px 0 !important; }
.tc-avatar-frame {
  border-radius: 50% !important;
  border: 1px solid rgba(255, 255, 255, 0.6) !important;
  box-shadow: none !important;
  overflow: hidden;
}
.tc-meta-title { color: #4a6b56 !important; font-weight: 400 !important; font-size: 14px !important; }
.tc-stat {
  background: rgba(255, 255, 255, 0.25) !important;
  color: #7c9686 !important;
  border: 1px solid rgba(255, 255, 255, 0.4) !important;
  border-radius: 99px !important;
  font-size: 10px !important;
}
.tc-divider {
  border: none !important;
  height: 1px !important;
  background: linear-gradient(90deg, transparent, rgba(74, 107, 86, 0.1), transparent) !important;
}
.tc-divider-text::before { content: '✦' !important; color: rgba(74, 107, 86, 0.2) !important; }

/* ---------- 7. 底部输入区（彻底去除灰感，白玻璃） ---------- */
.tm-compose {
  background: rgba(255, 255, 255, 0.2) !important; 
  backdrop-filter: blur(24px) !important;
  -webkit-backdrop-filter: blur(24px) !important;
  border-top: 1px solid rgba(255, 255, 255, 0.5) !important;
  box-shadow: none !important;
  border-radius: 22px 22px 0 0 !important;
  padding-bottom: calc(12px + var(--nuo-safe-bottom, 0px)) !important;
}

.tm-input {
  background: rgba(255, 255, 255, 0.75) !important; 
  color: var(--text-main) !important;
  border: 1px solid rgba(255, 255, 255, 0.9) !important;
  border-radius: 16px !important;
  font-size: 15px !important;
  font-weight: 300 !important;
  box-shadow: 0 4px 16px rgba(255, 255, 255, 0.4) !important; 
}
.tm-input:focus {
  background: #ffffff !important;
  border-color: rgba(74, 107, 86, 0.5) !important;
}
.tm-input::placeholder { color: rgba(85, 112, 95, 0.4) !important; }

.tm-send-btn {
  border-radius: 50% !important;
  width: 40px !important;
  height: 40px !important;
  color: #4a6b56 !important;
  background: rgba(255, 255, 255, 0.75) !important;
  border: 1px solid rgba(255, 255, 255, 0.9) !important;
}
.tm-send-btn.ready { background: #6b8e7b !important; color: #fff !important; border-color: transparent !important; }

.tm-regen-btn { color: #7c9686 !important; }
.tm-regen-btn.active {
  background: rgba(142, 186, 162, 0.2) !important;
  color: #4a6b56 !important;
  border-color: rgba(142, 186, 162, 0.4) !important;
}
.tm-bond-btn { color: #a4c4b0 !important; }

.tm-story::-webkit-scrollbar { width: 2px !important; }
.tm-story::-webkit-scrollbar-thumb { background: rgba(85, 112, 95, 0.15) !important; border-radius: 2px !important; }

.tm-para-char, .tm-para-user, .tm-send-btn, .tm-btn-icon { -webkit-tap-highlight-color: transparent !important; }

/*
  此时此刻主题 · 雾灰低饱和版
  适用：此时此刻 → 经典主题 → 自定义 CSS
  配色：冷雾灰、微蓝灰；适合雪山与阴天背景
  背景：https://imgbed.heliar.top/i/PQR4pKeg2tkvhb5J_IMG_5772.jpg

  ==================== 位置调整总则 ====================
  top：   数值减小 = 往上；数值增大 = 往下
  left：  数值减小 = 往左；数值增大 = 往右
  right： 数值增大 = 往左；数值减小 = 往右
  bottom：数值增大 = 往上；数值减小 = 往下

  负数同样遵守上面的规则：
  top: -100px 比 top: -70px 更靠上；
  right: -240px 比 right: -180px 更靠右。

  width / height：数值增大 = 变大；数值减小 = 变小
  padding：增大 = 内容与边框距离增大
  margin：增大 = 元素与外部元素距离增大
  =====================================================
*/

/* ==================== 1. 主题变量与页面背景 ==================== */
:root {
  --water-base: #e2e4e7;
  --water-soft: rgba(226, 228, 231, 0.58);
  --water-pale: rgba(245, 246, 247, 0.50);
  --water-text: rgba(67, 72, 78, 0.98);
  --water-muted: rgba(99, 105, 111, 0.72);
  --water-line: rgba(127, 133, 139, 0.22);
  --water-white-line: rgba(250, 250, 251, 0.48);
  --water-blue: #9da4ab;
  --water-radius: 28px;

  --tm-fg: rgba(67, 72, 78, 0.98) !important;
  --tm-fg-muted: rgba(99, 105, 111, 0.72) !important;
  --tm-bg: #f1f2f4 !important;
  --tm-bg-soft: rgba(226, 228, 231, 0.72) !important;
  --tm-border: rgba(127, 133, 139, 0.22) !important;

  background: var(--water-base) !important;
  color: var(--water-text) !important;
}

.tm-bg-container {
  background: var(--water-base) !important;
}

.tm-bg-image {
  filter: blur(22px) saturate(0.35) brightness(1.03) !important;
  opacity: 0.48 !important;
}

.tm-bg-overlay {
  background:
    linear-gradient(180deg, rgba(226, 228, 231, 0.70) 0%, rgba(226, 228, 231, 0.94) 75%),
    var(--water-base) !important;
}

.tm-story {
  background: transparent !important;
  padding: 20px 14px !important;
}

/* ==================== 2. 消息卡片 ==================== */
.tm-para {
  position: relative !important;
  width: 95% !important;
  max-width: 650px !important;
  max-height: 820px !important;
  margin: 20px auto !important;
  padding: 0 !important;
  overflow: hidden !important;
  border-radius: var(--water-radius) !important;
  box-sizing: border-box !important;
}

.tm-para-char {
  position: relative !important;
  display: flex !important;
  flex-direction: column !important;
  width: 100% !important;
  max-width: none !important;
  min-height: 0 !important;
  margin: 0 !important;
  padding: 0 !important;
  overflow: hidden !important;
  border: 2px solid rgba(250, 250, 251, 0.72) !important;
  border-radius: var(--water-radius) !important;
  background: var(--water-soft) !important;
  box-shadow: 0 15px 35px rgba(77, 83, 90, 0.12) !important;
