  color: var(--water-text) !important;
}

.tm-translation-body,
.tm-collapsible-section-body {
  color: var(--water-text) !important;
}

.tm-no-animations * {
  animation: none !important;
  transition: none !important;
}

/* 简约宽屏线下聊天-byRABBIT^T*/

:root {
  --minimal-content-width: 860px;
  --minimal-avatar-size: 46px;
  --minimal-avatar-gap: 14px;
  --minimal-text: #303633;
  --minimal-muted: #9aa19b;
  --minimal-line: rgba(55, 70, 60, 0.12);
}

/* 消息流：不贴满屏，统一收进宽屏中轴 */
.tm-story {
  width: 100% !important;
  max-width: var(--minimal-content-width) !important;
  margin-inline: auto !important;
  padding-inline: 28px !important;
  box-sizing: border-box !important;
}

.tm-story > .tm-para {
  width: 100% !important;
  max-width: 760px !important;
  margin-inline: auto !important;
  box-sizing: border-box !important;
}

/* 角色 / 用户消息统一成同一条中轴，不做左右气泡 */
.tm-para-char,
.tm-para-user {
  width: 100% !important;
  max-width: 760px !important;
  margin-inline: auto !important;
  background: transparent !important;
  border: 0 !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  padding: 14px 0 !important;
  box-sizing: border-box !important;
  position: relative !important;
}

/* 去掉头像下方的角色名；用户消息保留 badge，把它移到头像旁作为名字位 */
.tc-avatar-badge {
  display: none !important;
}

.tc-avatar-badge-user {
  display: block !important;
  margin: 0 !important;
  padding: 1px 0 0 !important;
  color: var(--minimal-text) !important;
  font-size: 13px !important;
  line-height: 1.35 !important;
  font-weight: 650 !important;
  text-align: left !important;
}

/* 用户 header 补齐与 char 相同的三元素信息层 */
.tc-header-user {
  display: flex !important;
  align-items: flex-start !important;
  position: relative !important;
}

.tc-header-user .tc-avatar-area,
.tc-header-user .tc-avatar-frame-user {
  flex: 0 0 var(--minimal-avatar-size) !important;
}

.tc-header-user .tc-avatar-badge-user {
  position: absolute !important;
  left: calc(var(--minimal-avatar-size) + var(--minimal-avatar-gap)) !important;
  top: 1px !important;
  z-index: 1 !important;
}

.tc-header-user::after {
  content: 'USER / NOTE · LINE 01' !important;
  position: absolute !important;
  left: calc(var(--minimal-avatar-size) + var(--minimal-avatar-gap)) !important;
  top: 22px !important;
  color: var(--minimal-muted) !important;
  font-size: 10px !important;
  line-height: 1.4 !important;
  font-weight: 400 !important;
}

/* 头像缩小为规整方形 */
.tc-header-main,
.tc-header-user {
  align-items: flex-start !important;
  gap: var(--minimal-avatar-gap) !important;
}

.tc-avatar-frame,
.tc-avatar-frame-user {
  width: var(--minimal-avatar-size) !important;
  height: var(--minimal-avatar-size) !important;
  min-width: var(--minimal-avatar-size) !important;
  min-height: var(--minimal-avatar-size) !important;
  border-radius: 7px !important;
  padding: 0 !important;
  border: 1px solid var(--minimal-line) !important;
  box-shadow: none !important;
  overflow: hidden !important;
}

.tc-avatar-img,
.tc-avatar-frame-user img {
  width: 100% !important;
  height: 100% !important;
  object-fit: cover !important;
  border-radius: 6px !important;
}

/* 头像旁三元素信息：名字 / 身份 / 时间保持一行 */
.tc-meta-area {
  min-width: 0 !important;
  flex: 1 1 auto !important;
  padding-top: 1px !important;
}

.tc-meta-title {
  font-size: 13px !important;
  line-height: 1.35 !important;
  color: var(--minimal-text) !important;
  font-weight: 650 !important;
}

.tc-meta-subtitle,
.tc-meta-extra-1,
.tc-meta-extra-2,
.tc-meta-stats {
  font-size: 10px !important;
  line-height: 1.4 !important;
  color: var(--minimal-muted) !important;
}

.tc-meta-stats {
  gap: 8px !important;
  margin-top: 2px !important;
}

.tc-stat {
  padding: 0 !important;
  background: transparent !important;
  border: 0 !important;
  border-radius: 0 !important;
  color: var(--minimal-muted) !important;
}

/* 正文占满消息宽度，不再留下头像宽度的左侧空档 */
.tm-body-char,
.tm-body-user {
  display: block !important;
  width: 100% !important;
  max-width: 100% !important;
  margin: 8px 0 0 !important;
  padding: 0 !important;
  color: var(--minimal-text) !important;
  font-size: 14px !important;
  line-height: 1.8 !important;
  text-align: left !important;
  box-sizing: border-box !important;
}

.tm-para-char,
.tm-para-user {
  width: 100% !important;
  max-width: min(100%, 980px) !important;
}

/* 用户消息不再靠右，和 AI 使用相同的中轴 */
.tm-para-user .tm-body-user {
  color: var(--minimal-text) !important;
}

/* **文字** 格式化为红色，不改变普通正文 */
.tm-bold {
  color: #c84747 !important;
  background: transparent !important;
  text-shadow: none !important;
}

/* 底栏：隐藏原生图标文字，用 mask 承载形状、变量承载颜色 */
.tm-compose-toolbar .tm-regen-btn,
.tm-compose-toolbar .tm-suggestions-btn,
.tm-compose-row .tm-send-btn {
  position: relative !important;
  width: 34px !important;
  height: 34px !important;
  min-width: 34px !important;
  padding: 0 !important;
  background: transparent !important;
  border: 0 !important;
  box-shadow: none !important;
  color: transparent !important;
  font-size: 0 !important;
  opacity: 0.72 !important;
  overflow: hidden !important;
}

.tm-compose-toolbar .tm-regen-btn > *,
.tm-compose-toolbar .tm-suggestions-btn > *,
.tm-compose-row .tm-send-btn > * {
  display: none !important;
}

.tm-compose-toolbar .tm-regen-btn::before,
.tm-compose-toolbar .tm-suggestions-btn::before,
.tm-compose-row .tm-send-btn::before {
  content: '' !important;
  position: absolute !important;
  inset: 7px !important;
  display: block !important;
  background-color: var(--minimal-toolbar-icon, #717b73) !important;
  -webkit-mask: center / contain no-repeat !important;
