.tm-compose-toolbar .tm-regen-btn:hover,
.tm-compose-toolbar .tm-suggestions-btn:hover,
.tm-compose-row .tm-send-btn:hover {
  opacity: 1 !important;
  transform: translateY(-1px) !important;
}


/* 思维链：折叠标记视觉上放到头像下方 */
.tm-para-char:has(.tm-thinking-wrapper) {
  --thinking-left: 0px;
}

/* 思维链：使用正常文档流，按钮永远在头像/消息头之后，面板紧跟按钮 */
.tm-para-char:has(.tm-thinking-wrapper) {
  position: relative !important;
}

.tm-thinking-wrapper {
  position: relative !important;
  z-index: 4 !important;
  display: block !important;
  width: 100% !important;
  margin: 10px 0 0 !important;
  padding: 0 !important;
  pointer-events: auto !important;
}

.tm-thinking-toggle {
  position: relative !important;
  left: auto !important;
  top: auto !important;
  z-index: 6 !important;
  width: var(--minimal-avatar-size) !important;
  min-width: var(--minimal-avatar-size) !important;
  height: 24px !important;
  margin: 0 !important;
  padding: 0 2px !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  background: rgba(255, 255, 255, 0.86) !important;
  border: 1px solid var(--minimal-line) !important;
  border-radius: 3px !important;
  color: var(--minimal-muted) !important;
  font-size: 9px !important;
  line-height: 1 !important;
  white-space: nowrap !important;
  overflow: hidden !important;
  cursor: pointer !important;
  pointer-events: auto !important;
  -webkit-tap-highlight-color: transparent !important;
}

.tm-thinking-toggle .tm-thinking-caret {
  display: none !important;
}

.tm-thinking-toggle .tm-thinking-icon {
  display: none !important;
}

.tm-thinking-toggle .tm-thinking-label {
  display: block !important;
  max-width: 100% !important;
  overflow: hidden !important;
  text-overflow: ellipsis !important;
  color: var(--minimal-muted) !important;
  font-size: 9px !important;
}

.tm-thinking-toggle .tm-thinking-label::before {
  content: '静观其变' !important;
  font-size: 9px !important;
}

.tm-thinking-toggle .tm-thinking-label {
  font-size: 0 !important;
}

/* 展开的思维链仍然回到正文区域，不遮住头像和元信息 */
.tm-thinking-panel {
  position: relative !important;
  z-index: 1 !important;
  width: 100% !important;
  margin: 8px 0 0 !important;
  padding: 8px 12px !important;
  border-left: 2px solid var(--minimal-line) !important;
  background: transparent !important;
  color: var(--minimal-muted) !important;
  font-size: 12px !important;
  line-height: 1.7 !important;
}

/* 手机端保留左右呼吸感，同时继续使用安全区 */
@media (max-width: 640px) {
  .tm-story {
    max-width: 100% !important;
    padding-inline: 18px !important;
    padding-top: 12px !important;
    padding-bottom: 12px !important;
  }

  .tm-story > .tm-para,
  .tm-para-char,
  .tm-para-user {
    max-width: 100% !important;
  }

  .tm-body-char,
  .tm-body-user {
    font-size: 14px !important;
  }
}

/* iOS 安全区：按教程使用宿主暴露的变量 */
.tm-header {
  padding-top: max(10px, calc(10px + var(--nuo-safe-top, 0px))) !important;
}

.tm-compose {
  padding-bottom: calc(12px + var(--nuo-safe-bottom, 0px)) !important;
}

/* 减少低端手机滚动卡顿，保留 iOS 惯性滚动 */
.tm-story {
  -webkit-overflow-scrolling: touch !important;
}

.tm-compose-toolbar .tm-regen-btn:hover,
.tm-compose-toolbar .tm-suggestions-btn:hover,
.tm-compose-row .tm-send-btn:hover {
  opacity: 1 !important;
}


/* 最终布局兜底：消息头、思维链、正文必须按文档流垂直排列 */
.tm-para-char:has(.tm-thinking-wrapper) {
  display: flex !important;
  flex-direction: column !important;
  align-items: stretch !important;
  position: relative !important;
}

.tm-para-char:has(.tm-thinking-wrapper) > .tc-header-main,
.tm-para-char:has(.tm-thinking-wrapper) > .tc-header-user {
  order: 1 !important;
  flex: 0 0 auto !important;
}

.tm-para-char:has(.tm-thinking-wrapper) > .tm-thinking-wrapper {
  order: 2 !important;
  flex: 0 0 auto !important;
  align-self: stretch !important;
  margin: 10px 0 0 !important;
  transform: none !important;
}

.tm-para-char:has(.tm-thinking-wrapper) > .tm-body-char,
.tm-para-char:has(.tm-thinking-wrapper) > .tm-body-user {
  order: 3 !important;
  flex: 0 0 auto !important;
  position: relative !important;
  z-index: 2 !important;
  margin-top: 10px !important;
}

/* 按钮在头像列下方，展开面板占正文宽度并把正文自然推下去 */
.tm-para-char:has(.tm-thinking-wrapper) .tm-thinking-wrapper {
  display: block !important;
  height: auto !important;
  min-height: 24px !important;
  overflow: visible !important;
}

.tm-para-char:has(.tm-thinking-wrapper) .tm-thinking-toggle {
  display: flex !important;
  float: none !important;
  clear: both !important;
  inset: auto !important;
  transform: none !important;
}

.tm-para-char:has(.tm-thinking-wrapper) .tm-thinking-panel {
  display: block !important;
  position: relative !important;
  inset: auto !important;
  float: none !important;
  clear: both !important;
  box-sizing: border-box !important;
  max-height: none !important;
  overflow: visible !important;
  transform: none !important;
}

/* 重投按钮：取消裁切，确保环形箭头完整显示 */
.tm-compose-toolbar .tm-regen-btn {
  box-sizing: border-box !important;
  overflow: visible !important;
  flex: 0 0 34px !important;
  clip: auto !important;
  clip-path: none !important;
  contain: none !important;
}

.tm-compose-toolbar .tm-regen-btn::before {
  inset: 4px !important;
  width: auto !important;
  height: auto !important;
  transform: none !important;
  background-position: center !important;
  background-size: 100% 100% !important;
  background-repeat: no-repeat !important;
}

.tm-compose-toolbar .tm-regen-btn:first-of-type::before {
  background-size: contain !important;
}


/* *文字*：单星号强调文字使用独立的柔和绿色 */
.tm-body-char em,
.tm-body-user em,
.tm-body-char .tm-italic,
.tm-body-user .tm-italic,
.tm-body-char .tm-em,
.tm-body-user .tm-em,
.tm-body-char .italic,
.tm-body-user .italic {
  color: #5f8b73 !important;
  font-style: italic !important;
  text-shadow: none !important;
}

/* # 文字：一级标题放大并居中，兼容原生 h1 与常见解析类名 */
.tm-body-char h1,
.tm-body-user h1,
.tm-body-char .tm-heading-1,
.tm-body-user .tm-heading-1,
.tm-body-char .tm-h1,
.tm-body-user .tm-h1 {
  display: block !important;
  width: 100% !important;
  margin: 18px 0 14px !important;
  padding: 0 !important;
  color: var(--minimal-text) !important;
  font-size: 26px !important;
  font-weight: 700 !important;
  line-height: 1.35 !important;
  letter-spacing: 0 !important;
  text-align: center !important;
  text-shadow: none !important;
  background: transparent !important;
  border: 0 !important;
  box-shadow: none !important;
}

@media (max-width: 640px) {
  .tm-body-char h1,
  .tm-body-user h1,
  .tm-body-char .tm-heading-1,
  .tm-body-user .tm-heading-1,
  .tm-body-char .tm-h1,
  .tm-body-user .tm-h1 {
    font-size: 22px !important;
  }
}


/* 一级标题兼容：部分版本不会输出 h1，而是使用带 heading/title 的自定义节点 */
.tm-body-char > [class*="heading"],
.tm-body-user > [class*="heading"],
.tm-body-char > [class*="title"],
