}

.tm-compose-toolbar .tm-regen-btn:hover,
.tm-compose-toolbar .tm-suggestions-btn:hover,
.tm-compose-row .tm-send-btn:hover {
  opacity: 1 !important;
  transform: translateY(-1px) !important;
}


/* 思维链：折叠标记视觉上放到头像下方 */
.tm-para-char:has(.tm-thinking-wrapper) {
  --thinking-left: 0px;
}

/* 思维链：使用正常文档流，按钮永远在头像/消息头之后，面板紧跟按钮 */
.tm-para-char:has(.tm-thinking-wrapper) {
  position: relative !important;
}

.tm-thinking-wrapper {
  position: relative !important;
  z-index: 4 !important;
  display: block !important;
  width: 100% !important;
  margin: 10px 0 0 !important;
  padding: 0 !important;
  pointer-events: auto !important;
}

.tm-thinking-toggle {
  position: relative !important;
  left: auto !important;
  top: auto !important;
  z-index: 6 !important;
  width: var(--minimal-avatar-size) !important;
  min-width: var(--minimal-avatar-size) !important;
  height: 24px !important;
  margin: 0 !important;
  padding: 0 2px !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  background: rgba(255, 255, 255, 0.86) !important;
  border: 1px solid var(--minimal-line) !important;
  border-radius: 3px !important;
  color: var(--minimal-muted) !important;
  font-size: 9px !important;
  line-height: 1 !important;
  white-space: nowrap !important;
  overflow: hidden !important;
  cursor: pointer !important;
  pointer-events: auto !important;
  -webkit-tap-highlight-color: transparent !important;
}

.tm-thinking-toggle .tm-thinking-caret {
  display: none !important;
}

.tm-thinking-toggle .tm-thinking-icon {
  display: none !important;
}

.tm-thinking-toggle .tm-thinking-label {
  display: block !important;
  max-width: 100% !important;
  overflow: hidden !important;
  text-overflow: ellipsis !important;
  color: var(--minimal-muted) !important;
  font-size: 9px !important;
}

.tm-thinking-toggle .tm-thinking-label::before {
  content: '静观其变' !important;
  font-size: 9px !important;
}

.tm-thinking-toggle .tm-thinking-label {
  font-size: 0 !important;
}

/* 展开的思维链仍然回到正文区域，不遮住头像和元信息 */
.tm-thinking-panel {
  position: relative !important;
  z-index: 1 !important;
  width: 100% !important;
  margin: 8px 0 0 !important;
  padding: 8px 12px !important;
  border-left: 2px solid var(--minimal-line) !important;
  background: transparent !important;
  color: var(--minimal-muted) !important;
  font-size: 12px !important;
  line-height: 1.7 !important;
}

/* 手机端保留左右呼吸感，同时继续使用安全区 */
@media (max-width: 640px) {
  .tm-story {
    max-width: 100% !important;
    padding-inline: 18px !important;
    padding-top: 12px !important;
    padding-bottom: 12px !important;
  }

  .tm-story > .tm-para,
  .tm-para-char,
  .tm-para-user {
    max-width: 100% !important;
  }

  .tm-body-char,
  .tm-body-user {
    font-size: 14px !important;
  }
}

/* iOS 安全区：按教程使用宿主暴露的变量 */
.tm-header {
  padding-top: max(10px, calc(10px + var(--nuo-safe-top, 0px))) !important;
}

.tm-compose {
  padding-bottom: calc(12px + var(--nuo-safe-bottom, 0px)) !important;
}

/* 减少低端手机滚动卡顿，保留 iOS 惯性滚动 */
.tm-story {
  -webkit-overflow-scrolling: touch !important;
}

.tm-compose-toolbar .tm-regen-btn:hover,
.tm-compose-toolbar .tm-suggestions-btn:hover,
.tm-compose-row .tm-send-btn:hover {
  opacity: 1 !important;
}


/* 最终布局兜底：消息头、思维链、正文必须按文档流垂直排列 */
.tm-para-char:has(.tm-thinking-wrapper) {
  display: flex !important;
  flex-direction: column !important;
  align-items: stretch !important;
  position: relative !important;
}

.tm-para-char:has(.tm-thinking-wrapper) > .tc-header-main,
.tm-para-char:has(.tm-thinking-wrapper) > .tc-header-user {
  order: 1 !important;
  flex: 0 0 auto !important;
}

.tm-para-char:has(.tm-thinking-wrapper) > .tm-thinking-wrapper {
  order: 2 !important;
  flex: 0 0 auto !important;
  align-self: stretch !important;
