/* 米白主题：追加在 minimal-chat.css 末尾 */
:root {
  --minimal-text: #5b4c3c !important;
  --minimal-muted: #a3968a !important;
  --minimal-line: rgba(120, 101, 91, 0.18) !important;

  /* 主题色板：#D6CAC0 #FFFDF9 #FFFEE5 #78655B */
  --minimal-surface: #fffdf9;
  --minimal-accent: #9b6f59;   /* 强调：暖棕 */
  --minimal-contrast: #7c9270; /* 斜体：橄榄绿 */
  --minimal-header-icon: #78655b;
  --minimal-toolbar-icon: #8a7768;
  --minimal-send-icon: #9b6f59;
}

/* ===== 背景与面板：纯色统一 ===== */
#this-moment-screen,
.tm-bg-container,
.tm-bg-overlay,
.tm-story,
.tm-para-char,
.tm-para-user,
.tm-compose,
.tm-compose-toolbar,
.tm-compose-row,
.tm-input,
.tm-header {
  background: var(--minimal-surface) !important;
  background-image: none !important;
  color: #5b4c3c !important;
}

.tm-header,
.tm-compose,
.tm-compose-toolbar,
.tm-compose-row {
  border-color: rgba(120, 101, 91, 0.16) !important;
}

/* ===== 顶栏：纯色 + 棕色标题图标 ===== */
.tm-header {
  border: 0 !important;
  box-shadow: none !important;
  color: var(--minimal-header-icon) !important;
}

.tm-header .tm-header-name,
.tm-header .tm-btn-icon,
.tm-header button,
.tm-header a {
  color: var(--minimal-header-icon) !important;
  border-color: transparent !important;
}

.tm-header .tm-header-name { font-weight: 650 !important; }

/* ===== 正文文字 ===== */
.tm-meta-title,
.tc-meta-title,
.tc-avatar-badge-user,
.tm-body-char,
.tm-body-user,
.tm-suggestion-text,
.tm-suggestion-text-btn,
.tm-body-char h1,
.tm-body-user h1 {
  color: #5b4c3c !important;
}

.tm-meta-subtitle,
.tm-meta-extra-1,
.tm-meta-extra-2,
.tm-meta-stats,
.tm-stat,
.tm-thinking-panel,
.tm-loading-container,
.tm-loading-text::before,
.tm-loading-text::after,
.tc-header-user::after {
  color: #a3968a !important;
}

/* 对白引用：暖棕 */
.tm-quote,
.tm-body-char q,
.tm-body-user q,
.tm-body-char .quote,
.tm-body-user .quote,
.tm-body-char [data-format="quote"],
.tm-body-user [data-format="quote"] {
  color: var(--minimal-accent) !important;
  background: transparent !important;
  -webkit-text-fill-color: currentColor !important;
}

/* 粗体：赭红棕 */
.tm-bold {
  color: #a75c52 !important;
  background: transparent !important;
}

/* 斜体：橄榄绿，和对白区分 */
.tm-body-char em,
.tm-body-user em,
.tm-body-char .tm-italic,
.tm-body-user .tm-italic,
.tm-body-char .tm-em,
.tm-body-user .tm-em,
.tm-body-char .italic,
.tm-body-user .italic {
  color: var(--minimal-contrast) !important;
  -webkit-text-fill-color: currentColor !important;
}

.tm-body-char hr,
.tm-body-user hr,
.tm-para-block hr,
.tm-header-user::before {
  border-color: rgba(124, 108, 89, 0.38) !important;
}

/* ===== 输入区 ===== */
.tm-compose-row .tm-input {
  background-color: #fffef5 !important;
  color: #5b4c3c !important;
  border-color: rgba(120, 101, 91, 0.28) !important;
}

.tm-compose-row .tm-input::selection,
.tm-body-char ::selection,
.tm-body-user ::selection { background: rgba(214, 202, 192, 0.6) !important; }

.tm-compose-row:has(.tm-input:placeholder-shown)::before {
  content: '本质的东西，用眼睛是看不见的' !important;
  color: #a3968a !important;
}

/* ===== 思维链按钮：米白到奶黄渐变 ===== */
.tm-thinking-toggle,
.tm-suggestion-item {
  border-color: rgba(120, 101, 91, 0.28) !important;
}

.tm-thinking-toggle {
  background: linear-gradient(135deg, #fffdf9, #fffee5) !important;
  background-image: linear-gradient(135deg, #fffdf9, #fffee5) !important;
  border-color: rgba(120, 101, 91, 0.3) !important;
  color: var(--minimal-accent) !important;
}

.tm-suggestion-item {
  background-color: rgba(255, 253, 249, 0.9) !important;
}

.tm-thinking-toggle .tm-thinking-label::before {
  content: '慢慢想' !important;
  color: var(--minimal-accent) !important;
}

.tc-header-user::after {
  content: 'USER / LETTER · SOFT LIGHT' !important;
  color: #a18f83 !important;
}

.tc-header-user::before {
  border-top-color: rgba(120, 101, 91, 0.42) !important;
}

/* 简约线下聊天夜阑-by RABBIT^T */

:root {
  --minimal-content-width: 860px;
  --minimal-avatar-size: 46px;
  --minimal-avatar-gap: 14px;
  --minimal-text: #303633;
  --minimal-muted: #9aa19b;
  --minimal-line: rgba(55, 70, 60, 0.12);
}

/* 消息流：不贴满屏，统一收进宽屏中轴 */
.tm-story {
  width: 100% !important;
  max-width: var(--minimal-content-width) !important;
  margin-inline: auto !important;
  padding-inline: 28px !important;
  box-sizing: border-box !important;
}

.tm-story > .tm-para {
  width: 100% !important;
  max-width: 760px !important;
  margin-inline: auto !important;
  box-sizing: border-box !important;
}

/* 角色 / 用户消息统一成同一条中轴，不做左右气泡 */
.tm-para-char,
.tm-para-user {
  width: 100% !important;
  max-width: 760px !important;
  margin-inline: auto !important;
  background: transparent !important;
  border: 0 !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  padding: 14px 0 !important;
  box-sizing: border-box !important;
  position: relative !important;
}

/* 去掉头像下方的角色名；用户消息保留 badge，把它移到头像旁作为名字位 */
.tc-avatar-badge {
  display: none !important;
}

.tc-avatar-badge-user {
  display: block !important;
  margin: 0 !important;
  padding: 1px 0 0 !important;
  color: var(--minimal-text) !important;
  font-size: 13px !important;
  line-height: 1.35 !important;
  font-weight: 650 !important;
  text-align: left !important;
}

/* 用户 header 补齐与 char 相同的三元素信息层 */
.tc-header-user {
  display: flex !important;
  align-items: flex-start !important;
  position: relative !important;
}

.tc-header-user .tc-avatar-area,
.tc-header-user .tc-avatar-frame-user {
  flex: 0 0 var(--minimal-avatar-size) !important;
}

.tc-header-user .tc-avatar-badge-user {
  position: absolute !important;
  left: calc(var(--minimal-avatar-size) + var(--minimal-avatar-gap)) !important;
  top: 1px !important;
  z-index: 1 !important;
}

.tc-header-user::after {
  content: 'USER / NOTE · LINE 01' !important;
  position: absolute !important;
  left: calc(var(--minimal-avatar-size) + var(--minimal-avatar-gap)) !important;
  top: 22px !important;
  color: var(--minimal-muted) !important;
  font-size: 10px !important;
  line-height: 1.4 !important;
  font-weight: 400 !important;
}

/* 头像缩小为规整方形 */
.tc-header-main,
.tc-header-user {
  align-items: flex-start !important;
  gap: var(--minimal-avatar-gap) !important;
}

.tc-avatar-frame,
.tc-avatar-frame-user {
  width: var(--minimal-avatar-size) !important;
  height: var(--minimal-avatar-size) !important;
  min-width: var(--minimal-avatar-size) !important;
  min-height: var(--minimal-avatar-size) !important;
  border-radius: 7px !important;
  padding: 0 !important;
  border: 1px solid var(--minimal-line) !important;
  box-shadow: none !important;
  overflow: hidden !important;
}

.tc-avatar-img,
.tc-avatar-frame-user img {
  width: 100% !important;
  height: 100% !important;
  object-fit: cover !important;
  border-radius: 6px !important;
}

/* 头像旁三元素信息：名字 / 身份 / 时间保持一行 */
.tc-meta-area {
  min-width: 0 !important;
  flex: 1 1 auto !important;
  padding-top: 1px !important;
}

.tc-meta-title {
  font-size: 13px !important;
  line-height: 1.35 !important;
  color: var(--minimal-text) !important;
  font-weight: 650 !important;
}

.tc-meta-subtitle,
.tc-meta-extra-1,
.tc-meta-extra-2,
.tc-meta-stats {
