  -webkit-overflow-scrolling: touch !important;
}

.tm-compose-toolbar .tm-regen-btn:hover,
.tm-compose-toolbar .tm-suggestions-btn:hover,
.tm-compose-row .tm-send-btn:hover {
  opacity: 1 !important;
}


/* 最终布局兜底：消息头、思维链、正文必须按文档流垂直排列 */
.tm-para-char:has(.tm-thinking-wrapper) {
  display: flex !important;
  flex-direction: column !important;
  align-items: stretch !important;
  position: relative !important;
}

.tm-para-char:has(.tm-thinking-wrapper) > .tc-header-main,
.tm-para-char:has(.tm-thinking-wrapper) > .tc-header-user {
  order: 1 !important;
  flex: 0 0 auto !important;
}

.tm-para-char:has(.tm-thinking-wrapper) > .tm-thinking-wrapper {
  order: 2 !important;
  flex: 0 0 auto !important;
  align-self: stretch !important;
  margin: 10px 0 0 !important;
  transform: none !important;
}

.tm-para-char:has(.tm-thinking-wrapper) > .tm-body-char,
.tm-para-char:has(.tm-thinking-wrapper) > .tm-body-user {
  order: 3 !important;
  flex: 0 0 auto !important;
  position: relative !important;
  z-index: 2 !important;
  margin-top: 10px !important;
}

