  width: 100% !important;
  margin: 10px 0 0 !important;
  padding: 0 !important;
  pointer-events: auto !important;
}

.tm-thinking-toggle {
  position: relative !important;
  left: auto !important;
  top: auto !important;
  z-index: 6 !important;
