}
.tm-para { width: min(100%, 740px) !important; margin: 0 auto 34px !important; padding: 0 !important; }
.tm-para-char, .tm-para-user {
  position: relative !important; display: block !important; height: auto !important;
  min-width: 0 !important; padding: 0 0 8px !important; margin: 0 !important;
