}
.tm-para-char .tc-header, .tc-header-user {
  position: relative !important; display: block !important; padding: 0 !important; margin: 0 !important;
  background: transparent !important; border: 0 !important; border-radius: 0 !important; overflow: visible !important;
}
.tm-para-char .tc-header-deco-top {
