  border: 0 !important; border-radius: 21px !important;
  box-shadow: 0 4px 14px rgb(0 0 0 / .10) !important; pointer-events: none !important;
}
.tm-para-char .tc-header-deco-top::after {
  content: "「全世界最喜歡」\A我對你來說是一顆星嗎" !important;
  position: absolute !important; top: 22px !important; left: 72px !important; right: 52px !important;
  color: #222 !important; font-family: var(--ab-font) !important;
  font-size: 12px !important; font-weight: 500 !important; line-height: 1.65 !important;
  white-space: pre-line !important; pointer-events: none !important;
}
.tm-para-char .tc-header-main {
  position: relative !important; z-index: 2 !important;
  display: grid !important; grid-template-columns: var(--ab-avatar) minmax(0, 1fr) !important;
