  width: var(--ab-avatar) !important; height: var(--ab-avatar) !important; box-sizing: border-box !important;
  padding: 3px !important; margin: 0 !important; overflow: visible !important;
  background: #fff !important; border: 3px solid #c7c7c7 !important;
  border-radius: 50% !important; box-shadow: 0 3px 12px rgb(0 0 0 / .09) !important;
}
/* 浅灰外圈、白色内圈与右下角爱心徽章；不裁掉外伸徽章。 */
.tm-para-char .tc-avatar-frame::after, .tm-para-user .tc-avatar-frame::after {
