/* 7. ★ 正文重点语句：发光白 + 下方横线 ★ */
.tm-para-char .tm-body-char .tm-bold,
.tm-para-user .tm-body-user .tm-bold,
.tm-para-char .tm-body-char strong,
.tm-para-user .tm-body-user strong,
.tm-para-char .tm-body-char b,
.tm-para-user .tm-body-user b {
  color: #ffffff !important;
  -webkit-text-fill-color: #ffffff !important;
  font-weight: 700 !important;
  text-shadow:
    0 0 4px #ffffff,
    0 0 8px rgba(255, 255, 255, 0.8),
    0 0 16px rgba(255, 255, 255, 0.5) !important;
  border-bottom: 1px solid rgba(255, 255, 255, 0.9) !important;
  box-shadow: 0 2px 6px rgba(255, 255, 255, 0.5) !important;
  background: transparent !important;
  padding-bottom: 1px !important;
}

/* 8. 用户消息：隐藏头像 + 靠右 + 横线随内容 */
.tm-para-user .tc-header,
.tm-para-user .tc-header-user,
.tm-para-user .tc-avatar-area,
.tm-para-user .tc-avatar-frame,
.tm-para-user .tc-avatar-frame-user,
.tm-para-user .tc-avatar-img,
.tm-para-user .tc-avatar-badge,
.tm-para-user .tc-avatar-badge-user {
  display: none !important;
}
.tm-para-user {
  text-align: right !important;
}
.tm-para-user .tm-body-user {
  display: inline-block !important;
  text-align: right !important;
  padding-right: 8px !important;
  max-width: 100% !important;
  vertical-align: top !important;
}
.tm-para-user .tm-body-user::after {
  content: "" !important;
  display: block !important;
  width: 100% !important;
  height: 1px !important;
  margin: 8px 0 0 0 !important;
  background: linear-gradient(90deg, transparent, rgba(255,255,255,0.7), transparent) !important;
}

/* 9. 底部"生成中…" */
.tm-loading-text {
  font-size: 0 !important;
}
.tm-loading-text::after {
  content: "初雪が降り続いています..." !important;
  display: inline-block !important;
  font-size: 11px !important;
  color: rgba(255, 255, 255, 0.8) !important;
  letter-spacing: 0.5px !important;
  white-space: nowrap !important;
  line-height: 1.4 !important;
}

/* 10. ★ 输入区 ★ */
.tm-compose {
  background: transparent !important;
  border-top: none !important;
  padding-left: 0 !important;
  padding-right: 0 !important;
  margin-top: 0 !important;
  padding-top: 0 !important;
  padding-bottom: calc(2px + var(--nuo-safe-bottom, 0px)) !important;
}
.tm-compose-toolbar {
  border-color: transparent !important;
  padding-left: 8px !important;
  padding-right: 8px !important;
}
.tm-compose-row {
  padding-left: 8px !important;
  padding-right: 8px !important;
}

/* 11. 输入框 */
.tm-input {
  width: 90% !important;
  max-width: 90% !important;
  margin: 0 auto !important;
  background: rgba(255, 255, 255, 0.25) !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  border: 1px solid rgba(255, 255, 255, 0.35) !important;
  border-radius: 18px !important;
  color: #fff !important;
  box-shadow: none !important;
  display: flex !important;
  align-items: center !important;
  padding-top: 0 !important;
  padding-bottom: 0 !important;
  padding-left: 14px !important;
  padding-right: 14px !important;
  height: 40px !important;
  min-height: 40px !important;
  max-height: 40px !important;
  line-height: 1.4 !important;
  box-sizing: border-box !important;
}
.tm-input::placeholder {
  color: rgba(255, 255, 255, 0.7) !important;
}

/* 12. 发送按钮 */
.tm-send-btn {
  background: url("https://img2.tofaka.com/autoupload/f/yzy5y/20261015/09yJ/2048X2048/%E6%97%A0%E6%A0%87%E9%A2%98646_20261015222516.png") center/contain no-repeat !important;
  background-color: transparent !important;
  border: none !important;
  box-shadow: none !important;
  color: transparent !important;
  width: 40px !important;
  height: 40px !important;
}
.tm-send-btn.ready {
  background: url("https://img2.tofaka.com/autoupload/f/yzy5y/20261015/09yJ/2048X2048/%E6%97%A0%E6%A0%87%E9%A2%98646_20261015222516.png") center/contain no-repeat !important;
  background-color: transparent !important;
  border: none !important;
  box-shadow: none !important;
  color: transparent !important;
}
.tm-send-btn svg {
  display: none !important;
}

/* 13. ★ 提亮底部所有按钮和面板（修复灰黑色） ★ */
.tm-compose-toolbar .tm-btn-icon,
.tm-compose-toolbar .tm-regen-btn,
.tm-compose-toolbar .tm-bond-btn,
.tm-suggestions-btn,
.tm-compose-more-btn,
