  vertical-align: baseline !important;
  animation: minimal-writing-dots 1.15s steps(3, end) infinite !important;
}

/* 流式输出末尾光标也换成细短线，和“落笔”状态保持一致 */
.tm-stream-cursor {
  display: inline-block !important;
