  background: #76827a !important;
  animation: minimal-cursor-blink 0.9s steps(1, end) infinite !important;
}

@keyframes minimal-writing-text {
  0%, 100% { opacity: 0.42; transform: translateY(0); }
  50% { opacity: 0.95; transform: translateY(-1px); }
}

@keyframes minimal-writing-dots {
  0% { opacity: 0.2; transform: translateX(-3px); }
  50% { opacity: 0.65; transform: translateX(0); }
  100% { opacity: 1; transform: translateX(3px); }
}

@keyframes minimal-cursor-blink {
  0%, 48% { opacity: 1; }
  49%, 100% { opacity: 0; }
}

