@media (max-width: 420px) {
  .tm-header { gap: 3px !important; padding-inline: 7px !important; }
  .tm-header > .tm-btn-icon:first-child,
  .tm-header-right > .tm-btn-icon { flex-basis: 32px !important; width: 32px !important; height: 32px !important; min-width: 32px !important; }
  .tm-header-center { gap: 2px !important; }
  .tm-header-center > .tm-top-drop-btn,
  .tm-header-center > .tm-top-drop-btn-user { gap: 3px !important; padding-inline: 2px !important; }
  .tm-header-center .tm-header-avatar { width: 18px !important; height: 18px !important; flex-basis: 18px !important; }
