/* ===== 第二轮：真实动态组件兼容 ===== */

/* 分割线：兼容解析器生成的 hr、段落块内 hr，以及独立分隔节点 */
.tm-body-char hr,
.tm-body-user hr,
.tm-body-char .tm-para-block hr,
.tm-body-user .tm-para-block hr,
.tm-para-block hr,
.tm-body-char [class*="divider"],
.tm-body-user [class*="divider"],
.tm-body-char [class*="separator"],
.tm-body-user [class*="separator"] {
