/* ===== 第二轮：真实动态组件兼容 ===== */

/* 分割线：兼容解析器生成的 hr、段落块内 hr，以及独立分隔节点 */
.tm-body-char hr,
.tm-body-user hr,
.tm-body-char .tm-para-block hr,
.tm-body-user .tm-para-block hr,
.tm-para-block hr,
.tm-body-char [class*="divider"],
.tm-body-user [class*="divider"],
.tm-body-char [class*="separator"],
.tm-body-user [class*="separator"] {
  display: block !important;
  width: 100% !important;
  height: 1px !important;
  min-height: 1px !important;
  margin: 18px 0 !important;
  padding: 0 !important;
  border: 0 !important;
  border-top: 1px dashed rgba(86, 96, 90, 0.48) !important;
  background: transparent !important;
  background-image: none !important;
  box-shadow: none !important;
  opacity: 1 !important;
}

/* 某些版本把 --- 保留成单独的分隔段，不让它继续显示原始横线文字 */
.tm-body-char .tm-divider,
.tm-body-user .tm-divider,
.tm-body-char .tm-separator,
.tm-body-user .tm-separator {
  font-size: 0 !important;
  color: transparent !important;
}

/* 真实生成状态：把“生成中”替换成带点状流动的短句 */
.tm-loading-container {
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  gap: 7px !important;
  min-height: 22px !important;
  color: var(--minimal-muted) !important;
}

.tm-loading-text {
  position: relative !important;
  display: inline-block !important;
  min-width: 5.5em !important;
  color: transparent !important;
  font-size: 0 !important;
  line-height: 1.5 !important;
  text-shadow: none !important;
}

.tm-loading-text::before {
  content: '正在落笔' !important;
  color: var(--minimal-muted) !important;
  font-size: 11px !important;
  letter-spacing: 0 !important;
  animation: minimal-writing-text 1.8s ease-in-out infinite !important;
}

.tm-loading-text::after {
  content: '···' !important;
  display: inline-block !important;
  width: 1.4em !important;
  margin-left: 2px !important;
  color: var(--minimal-muted) !important;
  font-size: 12px !important;
  letter-spacing: 2px !important;
  vertical-align: baseline !important;
  animation: minimal-writing-dots 1.15s steps(3, end) infinite !important;
}

/* 流式输出末尾光标也换成细短线，和“落笔”状态保持一致 */
.tm-stream-cursor {
  display: inline-block !important;
  width: 1px !important;
  height: 1em !important;
  margin-left: 3px !important;
  vertical-align: -0.12em !important;
  background: #76827a !important;
  animation: minimal-cursor-blink 0.9s steps(1, end) infinite !important;
}

@keyframes minimal-writing-text {
  0%, 100% { opacity: 0.42; transform: translateY(0); }
  50% { opacity: 0.95; transform: translateY(-1px); }
}

@keyframes minimal-writing-dots {
  0% { opacity: 0.2; transform: translateX(-3px); }
  50% { opacity: 0.65; transform: translateX(0); }
  100% { opacity: 1; transform: translateX(3px); }
}

@keyframes minimal-cursor-blink {
  0%, 48% { opacity: 1; }
  49%, 100% { opacity: 0; }
}

/* 建议回复面板：轻量行卡片 */
.tm-suggestions-panel {
  display: flex !important;
  flex-direction: column !important;
  gap: 6px !important;
  padding: 8px 0 !important;
