value.customCss:
/* 引入了宋体、Cinzel 衬线体，以及超级帅的哥特字体 UnifrakturMaguntia */
@import url('https://fonts.googleapis.com/css2?family=Cinzel:wght@400;600&family=Noto+Serif+SC:wght@300;400;600&family=UnifrakturMaguntia&display=swap');

.xt-root {
  /* 极致暗黑配色 */
  --xt-bg: #050505;
  --xt-text: #e0e0e0;
  --xt-text-sub: #a0a0a0;
  --xt-text-muted: #666666;
  --xt-accent: #ffffff;
  --xt-border: #1f1f1f;
  --xt-radius: 0px; 
  --xt-font: 'Noto Serif SC', 'Cinzel', serif !important;
  box-shadow: 0 10px 40px rgba(0,0,0,0.5);
  border: 1px solid #111111;
  padding: 30px 20px 20px;
  position: relative;
}

/* ==================== ✨ 核心魔法：真·翻页系统 ==================== */
.xt-content > .xt-card { background: transparent; border: none; padding: 0; box-shadow: none; margin: 0; position: relative; }
.xt-content > .xt-card .xt-card-title { display: none; } 

.xt-content > .xt-card:nth-of-type(1) { display: block; animation: xt-fadeIn 0.6s ease-out; }
.xt-content > .xt-card:nth-of-type(2) { display: none; }

#xt-t1:checked ~ .xt-content > .xt-card:nth-of-type(1) { display: none; }
#xt-t1:checked ~ .xt-content > .xt-card:nth-of-type(2) { display: block; animation: xt-fadeIn 0.6s ease-out; }

/* 翻页按钮 */
.xt-action-1 {
  display: block; width: max-content; margin: 16px 0 0 auto;
  font-family: 'Cinzel', serif !important; font-size: 9px; letter-spacing: 2px;
  color: var(--xt-text-muted); cursor: pointer; transition: all 0.3s;
  background: transparent; padding: 4px; border-bottom: 1px solid transparent;
}
.xt-action-1:hover { color: var(--xt-text); border-color: var(--xt-text); }
.xt-action-1::after { content: "NEXT ➔"; }
#xt-t1:checked ~ .xt-content .xt-action-1::after { content: "⬅ PREV"; }

/* ==================== 1. 顶部海报区 ==================== */
.xt-text-referenceTitle { text-align: center; color: var(--xt-text); font-size: 12px; letter-spacing: 4px; margin-bottom: 20px; }
.xt-text-referenceTitle::before { content: "/ "; color: var(--xt-text-muted); }
.xt-text-referenceTitle::after { content: " /"; color: var(--xt-text-muted); }

.xt-text-moodWord {
  /* 👇 填入第 1 张大图 👇 */
  background-image: 
    linear-gradient(rgba(0,0,0,0.2), rgba(0,0,0,0.2)), 
    url('https://nos.netease.com/ysf/06685d13336de4a86c0de7e695e3a6b7.png'); 
  background-size: cover; background-position: center;
  height: 120px; border-radius: 0px; 
  display: flex; align-items: center; justify-content: center;
  color: #ffffff; font-family: 'Cinzel', serif !important; font-size: 20px; letter-spacing: 6px;
  margin-bottom: 24px;
}
.xt-text-moodWord::before { content: "|"; margin-right: 12px; font-weight: 300; opacity: 0.6; }
.xt-text-moodWord::after { content: "|"; margin-left: 6px; font-weight: 300; opacity: 0.6; }

.xt-text-quote { text-align: center; font-size: 12px; color: var(--xt-text); margin-bottom: 8px; line-height: 1.8; letter-spacing: 1px; }
.xt-text-quoteEng { text-align: center; font-size: 9px; font-family: 'Cinzel', serif !important; color: var(--xt-text-sub); letter-spacing: 1px; }

/* ==================== 2. 核心数据 & 意象 ==================== */
.xt-grid-stat { padding: 12px 0 4px; border: none; background: transparent; }
.xt-grid-stat-label { font-family: 'Cinzel', serif !important; font-size: 9px; color: var(--xt-text-muted); letter-spacing: 2px; margin-bottom: 6px; }
.xt-grid-stat-value { font-size: 12px; color: var(--xt-text); }

.xt-tags { justify-content: center; margin-top: 8px; display: flex; align-items: center; }
.xt-tags::before, .xt-tags::after { content: "✦"; font-size: 10px; color: var(--xt-border); margin: 0 16px; }
.xt-tag { background: transparent; border: 1px solid var(--xt-border); color: var(--xt-text-sub); border-radius: 0px; font-size: 10px; padding: 3px 10px; letter-spacing: 1px; }

.xt-text-imageryDef { text-align: center; font-size: 10px; color: var(--xt-text-muted); margin-top: 8px; font-style: italic; letter-spacing: 1px; }

/* ==================== 3. 第一页图文并排 (带胶带) ==================== */
.xt-card:nth-of-type(1) .xt-row { 
  display: grid !important; 
  grid-template-columns: 95px 1fr !important; 
  gap: 16px !important; 
  align-items: start;
}

.xt-text-pic2 {
  /* 👇 填入第 2 张小图 👇 */
  background-image: url('https://nos.netease.com/ysf/d995baed486279f2382c89781e0033a6.png');
  background-size: cover; background-position: center;
  width: 100%; height: 125px; 
  border-radius: 0px; color: transparent; 
  position: relative; /* 必须保留，胶带定位用 */
  filter: grayscale(100%) contrast(1.2); 
}
/* 恢复胶带魔法 */
.xt-text-pic2::before {
  content: ""; position: absolute; top: -8px; left: 50%; transform: translateX(-50%) rotate(-3deg);
  width: 40px; height: 12px; 
  background: rgba(255, 255, 255, 0.25); backdrop-filter: blur(4px); /* 半透明磨砂质感 */
  border: 1px solid rgba(255,255,255,0.15); box-shadow: 0 2px 6px rgba(0,0,0,0.6);
  z-index: 10;
}

.xt-section-title { font-family: 'Cinzel', serif !important; font-size: 11px; color: var(--xt-text); border-bottom: 1px solid var(--xt-border); display: inline-block; padding-bottom: 4px; margin-bottom: 10px; letter-spacing: 1px; }
.xt-section-body { background: transparent; border: none; padding: 0; font-size: 11px; line-height: 2; color: var(--xt-text-sub); }

/* ==================== 4. 第二页顶部双图切割排版 ==================== */
.xt-card:nth-of-type(2) .xt-row {
  display: grid !important;
  grid-template-columns: 1fr 60px !important; 
  gap: 12px !important;
  margin-top: -10px; 
}

.xt-text-pic3 {
  /* 👇 填入第 3 张横幅长图 👇 */
  background-image: url('https://nos.netease.com/ysf/9f29738ab26c1ceddc8462ef0a83a6b5.png');
  background-size: cover; background-position: center;
  width: 100%; height: 60px; border-radius: 0px; color: transparent; overflow: hidden;
  filter: grayscale(100%); 
}

.xt-text-pic4 {
  /* 👇 填入第 4 张正方形图 👇 */
  background-image: url('https://nos.netease.com/ysf/0cd3291d65e6b14c69338720f311452e.png');
  background-size: cover; background-position: center;
  width: 100%; height: 60px; border-radius: 0px; color: transparent; overflow: hidden;
  filter: grayscale(100%) contrast(1.2); 
}

/* ==================== 5. 幻梦碎片 ==================== */
.xt-text-whatIf {
  font-style: italic; color: var(--xt-text-sub);
  background: transparent; 
  padding: 0 0 0 16px; 
  border-left: 1px solid var(--xt-border);
  text-align: left; font-size: 11px; line-height: 2;
}
.xt-text-whatIf::before {
  content: "R E V E R I E"; display: block;
  font-style: normal; font-family: 'Cinzel', serif !important;
  font-size: 10px; color: var(--xt-text-muted); letter-spacing: 4px;
  margin-bottom: 12px; margin-left: -16px; 
  text-align: center;
}

/* ==================== 6. 谎言与真实 ==================== */
.xt-text-sideA { 
  background: transparent; border-left: 1px solid var(--xt-border); 
  padding: 0 0 0 12px; text-align: left; margin-bottom: 24px; font-size: 11px; color: var(--xt-text-sub); line-height: 1.8; 
}
.xt-text-sideA::before { content: "S I D E . A  |  谎 言"; display: block; font-family: 'Cinzel', serif !important; font-size: 9px; color: var(--xt-text-muted); margin-bottom: 8px; letter-spacing: 2px; }

.xt-text-sideB { 
  background: transparent; border-right: 1px solid var(--xt-text); 
  padding: 0 12px 0 0; text-align: right; font-size: 11px; color: var(--xt-text); line-height: 1.8; 
}
.xt-text-sideB::before { content: "S I D E . B  |  真 心"; display: block; font-family: 'Cinzel', serif !important; font-size: 9px; color: var(--xt-text-muted); margin-bottom: 8px; letter-spacing: 2px; }

/* ==================== 7. 高级专访气泡 ==================== */
.xt-bubbles { background: transparent; padding: 0; gap: 20px; display: flex; flex-direction: column; }
.xt-bubbles::before {
  content: "D I A L O G U E"; display: block;
  font-family: 'Cinzel', serif !important; font-size: 11px; color: var(--xt-text-muted);
  letter-spacing: 4px; text-align: center; margin-bottom: 12px;
}
.xt-bubble-body { 
  font-size: 11px; line-height: 2; 
  background: transparent !important; 
  padding: 0; border-radius: 0px; max-width: 90%; 
}

/* 提问者 (左) + 哥特式 Q */
.xt-bubble-left { align-items: flex-start; }
.xt-bubble-left .xt-bubble-body { 
  color: var(--xt-text-sub); 
  border-left: 2px solid var(--xt-border); 
  padding-left: 16px; 
}
.xt-bubble-left .xt-bubble-body::before {
  content: "Q. ";
  font-family: 'UnifrakturMaguntia', serif; 
  font-size: 16px; 
  color: var(--xt-text-muted);
  margin-right: 6px;
}

/* 回答者 (右) + 哥特式 A */
.xt-bubble-right { align-items: flex-end; }
.xt-bubble-right .xt-bubble-body { 
  color: var(--xt-text); 
  border-right: 2px solid var(--xt-text); 
  text-align: left; 
  padding-right: 16px; 
}
.xt-bubble-right .xt-bubble-body::before {
  content: "A. ";
  font-family: 'UnifrakturMaguntia', serif; 
  font-size: 16px;
  color: var(--xt-text);
  margin-right: 6px;
}

/* ==================== 8. 旁白音轨 ==================== */
.xt-quote { background: transparent; border: none; border-top: 1px solid var(--xt-border); border-bottom: 1px solid var(--xt-border); border-radius: 0; padding: 16px 12px; font-size: 11px; text-align: center; color: var(--xt-text-sub); font-style: normal; line-height: 2; margin-top: 16px; }
.xt-quote::before, .xt-quote::after { display: none; }
.xt-quote-inner::before { content: "N A R R A T O R"; display: block; font-family: 'Cinzel', serif !important; font-size: 9px; color: var(--xt-text-muted); margin-bottom: 8px; letter-spacing: 4px; }

value.layout:
# ================= PAGE 01 =================
@card "P1"
@text referenceTitle .fadeInDown
@text moodWord .fadeIn.delay100
@text quote .fadeInUp.delay200
@text quoteEng .fadeInUp.delay300

@spacer 24

@grid 1 .stagger
  bgm:stat "NOW PLAYING"

@tags .fadeIn.delay400
  imagery
  "FRAGMENT"

@text imageryDef .fadeInUp.delay450

@spacer 32

@row 2
@text pic2 .fadeInUp.delay500
@section chapterTitle .fadeInUp.delay600
  chapterContent
@endrow
@endcard

# ================= PAGE 02 =================
@card "P2"

# 扁长图 + 正方形图 并排
@row 2
@text pic3 .fadeInDown
@text pic4 .fadeInDown.delay100
@endrow

@spacer 16

@text whatIf .fadeInUp

@spacer 32

@text sideA .fadeInUp.delay100
@text sideB .fadeInUp.delay200

@spacer 32

@bubbles .stagger
  q1:left
  a1:right
  q2:left
  a2:right

@spacer 24

@quote narrator .fadeInUp.delay400
@endcard

@toggle 1

