value.customCss:
@import url('https://fonts.googleapis.com/css2?family=Noto+Serif+SC:wght@300;400;600&display=swap');

.xt-root {
  --xt-bg: #ffffff;
  --xt-text: #111111;
  --xt-text-sub: #555555;
  --xt-text-muted: #999999;
  --xt-accent: #222222;
  --xt-accent-bg: rgba(0, 0, 0, 0.03);
  --xt-border: #cccccc;
  --xt-radius: 0px;
  --xt-radius-sm: 0px;
  --xt-font: 'Noto Serif SC', 'PingFang SC', serif;

  background: var(--xt-bg);
  padding: 24px 20px 12px 20px;
  box-shadow: 0 2px 20px rgba(0, 0, 0, 0.06);
  display: block;
  max-height: 520px;
  overflow-y: auto;
  position: relative;
  border-left: 2px dashed #cccccc;
  border-right: 2px dashed #cccccc;
}

/* 🎫 齿孔装饰 */
.xt-root::before {
  content: '';
  position: absolute;
  left: 0;
  right: 0;
  top: -6px;
  height: 12px;
  background-image: radial-gradient(circle at 50%, #aaaaaa 2.5px, transparent 2.5px);
  background-size: 18px 12px;
  background-repeat: repeat-x;
  opacity: 0.3;
}
.xt-root::after {
  content: '';
  position: absolute;
  left: 0;
  right: 0;
  bottom: -6px;
  height: 12px;
  background-image: radial-gradient(circle at 50%, #aaaaaa 2.5px, transparent 2.5px);
  background-size: 18px 12px;
  background-repeat: repeat-x;
  opacity: 0.3;
}

.xt-root::-webkit-scrollbar {
  width: 3px;
}
.xt-root::-webkit-scrollbar-track {
  background: #f0f0f0;
}
.xt-root::-webkit-scrollbar-thumb {
  background: #bbbbbb;
}

/* ——— 头部 ——— */
.xt-header {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 12px;
  padding-bottom: 10px;
  border-bottom: 1px solid #dddddd;
}

.xt-avatar {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  border: 2px solid #222222;
  object-fit: cover;
  flex-shrink: 0;
  filter: grayscale(100%) contrast(1.2);
}

.xt-name {
  font-size: 16px;
  font-weight: 600;
  color: #111111;
  letter-spacing: 3px;
}

.xt-name::after {
  content: ' · 票根';
  font-weight: 300;
  color: #999999;
  font-size: 11px;
  letter-spacing: 2px;
  margin-left: 4px;
}

/* ——— 电影信息行 ——— */
.xt-row {
  display: flex;
  justify-content: space-between;
  gap: 8px;
  margin: 0 0 14px 0;
  padding: 8px 4px;
  border-top: 1px solid #dddddd;
  border-bottom: 1px solid #dddddd;
  font-size: 10px;
  color: #555555;
  letter-spacing: 1.5px;
}
.xt-row > * {
  flex: 1;
  text-align: center;
}
.xt-row .xt-text-movieTitle {
  font-weight: 600;
  color: #111111;
  font-size: 13px;
  letter-spacing: 3px;
}
.xt-row .xt-text-showtime {
  color: #555555;
}
.xt-row .xt-text-seat {
  color: #555555;
}

/* ——— 区块 ——— */
.xt-section {
  margin: 4px 0;
}

.xt-section-title {
  font-size: 8px;
  font-weight: 400;
  color: #999999;
  letter-spacing: 5px;
  margin: 8px 0 2px 0;
  text-transform: uppercase;
}

.xt-section-body {
  font-size: 14px;
  line-height: 2;
  color: #111111;
  padding: 2px 0 4px 0;
  font-weight: 300;
}

/* ——— 画面定格（斜体批注感） ——— */
.xt-section:first-of-type .xt-section-body {
  font-style: italic;
  color: #333333;
  font-size: 14px;
  padding: 4px 0 4px 14px;
  border-left: 2px solid #cccccc;
}

/* ——— 某帧触动（加粗突出） ——— */
.xt-section:nth-of-type(2) .xt-section-body {
  font-weight: 500;
  color: #111111;
  font-size: 15px;
}

/* ——— 引用（联想过程 + 评分理由） ——— */
.xt-quote {
  background: rgba(0, 0, 0, 0.02);
  border-left: 2px solid #222222;
  border-radius: 0;
  padding: 10px 16px;
  font-size: 13.5px;
  line-height: 2.1;
  color: #222222;
  font-style: italic;
  margin: 2px 0 8px 0;
}

.xt-quote::before {
  content: '— ';
  color: #999999;
  opacity: 0.6;
  font-size: 14px;
  font-style: normal;
}
.xt-quote::after {
  content: '';
}

/* ——— 散场后 ——— */
.xt-section:last-of-type .xt-section-body {
  font-size: 15px;
  font-weight: 300;
  color: #111111;
  padding: 6px 0 4px 0;
  letter-spacing: 0.5px;
}

/* ——— 评分徽章 ——— */
.xt-badge {
  display: inline-block;
  background: transparent;
  border: 1px solid #222222;
  border-radius: 0;
  padding: 2px 18px;
  font-size: 18px;
  color: #111111;
  margin: 10px 0 4px 0;
  letter-spacing: 3px;
  font-weight: 400;
}

/* ——— footer ——— */
.xt-footer {
  font-size: 8px;
  color: #999999;
  letter-spacing: 5px;
  text-align: center;
  padding: 10px 0 2px 0;
  border-top: 1px solid #dddddd;
  margin-top: 6px;
  text-transform: uppercase;
}

/* ——— 星星粒子纯灰 ——— */
.xt-particles-stars .xt-particle {
  background: #aaaaaa;
  opacity: 0.1;
  box-shadow: 0 0 4px rgba(0, 0, 0, 0.05);
}

