    font-weight: normal;
    font-style: normal;
    font-display: swap;
}

/* ================= 1. 彻底清空系统的默认设定 ================= */
.xt-root {
    background: transparent !important;
    padding: 0 !important;
    box-shadow: none !important;
    filter: none !important;
    border: none !important;
    margin: -10px -20px !important; 
    width: calc(100% + 40px) !important;
}
.xt-text, .xt-card, .xt-content {
    background: transparent !important;
    border: none !important;
    box-shadow: none !important;
    border-radius: 0 !important;
    margin: 0 !important;
    padding: 0 !important;
    box-sizing: border-box !important;
}
.xt-card-title { display: none !important; }

/* ================= 2. 主容器 ================= */
.xt-row {
    position: relative !important;
    width: 100% !important;
    aspect-ratio: 1.06 / 1 !important; 
    perspective: 1200px !important; 
    transition: transform 1s cubic-bezier(0.2, 0.8, 0.2, 1) !important; 
    transform-style: preserve-3d !important;
    gap: 0 !important;
    container-type: inline-size !important; 
}
#xt-t1:checked ~ .xt-content .xt-row {
    transform: rotateY(-180deg) scale(0.96) !important; 
}
.xt-row > .xt-card {
    position: absolute !important;
    top: 0 !important; left: 0 !important; width: 100% !important; height: 100% !important;
    backface-visibility: hidden !important;
    background-repeat: no-repeat !important;
    filter: hue-rotate(145deg) saturate(1.1) brightness(1.02) !important; 
}

/* ================= 3. 第一面 ================= */
.xt-row > .xt-card:nth-child(1) {
    transform: rotateY(0deg);
    background-image: 
        url("https://i.postimg.cc/VNF0rLJc/IMG-20260716-125810.png"), 
        url("https://i.postimg.cc/02y5tyMK/IMG-20260716-112733.png"), 
        url("https://i.postimg.cc/c1zZmyYG/IMG-20260716-124223.png"), 
        url("https://i.postimg.cc/SxwyNLZx/IMG-20260716-112757.png"), 
        url("https://i.postimg.cc/0j2vHVNd/IMG-20260716-112828.png"), 
        url("https://i.postimg.cc/zXfsS9D5/quality-restoration-20260714185522580.png"), 
        url("https://i.postimg.cc/s28xspnR/quality-restoration-20260714185640924.png"), 
        url("https://i.postimg.cc/25vLmM7y/IMG-20260714-174946.png"), 
        url("https://i.postimg.cc/43hZvj5g/quality-restoration-20260714185554012.png"), 
        url("https://i.postimg.cc/FKYQxwh2/quality-restoration-20260714193907074.png") !important; 

    background-position: 
        35% 82%,  
        16% 87%,  
        98% 72%,  
        15% 85%,  
        78% 85%,  
        80% 70%,  
        90% 28%,  
        22% 26%,  
        15% 85%,  
        center center !important;

    background-size: 
        14% auto,  
        5% auto,   
        22% auto,  
        9% auto,   
        24% auto,  
        36% auto, 
        44% auto, 
        22% auto, 
        44% auto, 
        100% 100% !important; 
}

/* ✨ 修复：头像颜色直接修改为纯正的 #FFEAE5（甜美蜜桃粉） */
.xt-row::before {
    content: "";
    position: absolute;
    left: 60.5%; top: 29.8%; 
    width: 11.5%; height: 15%; 
    background-color: #FFFAf7 !important; /* 极其柔和温润的米粉白底色 */
    background-image: 
        radial-gradient(circle at 50% 100%, #FFEAE5 48%, transparent 49%), /* ✨ 纯正的主题蜜桃粉 身体 */
        radial-gradient(circle at 50% 35%, #FFEAE5 28%, transparent 29%),  /* ✨ 纯正的主题蜜桃粉 头部 */
        radial-gradient(circle, #FFF0EC 1.5px, transparent 2px) !important; /* 背景温暖浅粉小波点 */
    background-size: 100% 100%, 100% 100%, 8px 8px !important;
    background-position: 0 0, 0 0, 0 0 !important;
    border-radius: 4px !important;
    z-index: 100 !important; 
    opacity: 0.95 !important;
    backface-visibility: hidden !important; 
    transform-style: preserve-3d !important;
    transform: translateZ(1px) !important; 
    pointer-events: none !important;
}

/* 保持文字颜色不受全局滤镜干扰 */
