    color: #321a28 !important; 
    font-family: "XiaoMaoHeNi", sans-serif !important; 
    font-weight: normal !important; 
    letter-spacing: 1px !important;
    overflow-y: hidden !important; 
    font-size: clamp(14px, 3.8cqw, 22px) !important;      
    line-height: 2.2 !important; 
}

/* ================= 5. ✨ 修复：翻页按钮同步修改为完美的 #FFEAE5 蜜桃粉色 ================= */
.xt-action-1 {
    display: block !important; 
    width: 28px !important; 
    height: 28px !important; 
    line-height: 24px !important;
    text-align: center !important; 
    padding: 0 !important; 
    background: #FFEAE5 !important; /* ✨ 修改为完美的 FFEAE5 */
    color: #321a28 !important; 
    border: 2px solid #e5c4be !important; /* 搭配蜜桃粉的温和质感边框 */
    border-radius: 50% !important; 
    font-family: "XiaoMaoHeNi", sans-serif !important;
    font-size: 14px !important; 
    font-weight: bold !important;
    box-shadow: 0 3px 6px rgba(229, 196, 190, 0.35) !important; 
    transition: all 0.3s cubic-bezier(0.2, 0.8, 0.2, 1) !important; 
    position: absolute !important; 
    left: 50% !important;
    transform: translateX(-50%) !important; 
    bottom: 5px !important; 
    z-index: 999 !important;
    cursor: pointer !important;
}

/* 封面状态 */
.xt-action-1::after { 
    content: "v" !important; 
}

/* 翻开状态 */
#xt-t1:checked ~ .xt-content .xt-action-1 { 
    background: #FFF5F2 !important; /* 翻开后为淡蜜桃粉白，超级温柔 */
    border-color: #FFEAE5 !important;
    box-shadow: none !important;
    transform: translateX(-50%) scale(0.95) !important; 
}
#xt-t1:checked ~ .xt-content .xt-action-1::after { 
    content: "^" !important; 
}

/* 悬停效果 */
.xt-action-1:hover {
    background: #f4d0cb !important;
    transform: translateX(-50%) translateY(-2px) scale(1.05) !important;
}

