.xt-root {
    width: 300px !important;
    height: auto;
    box-sizing: border-box;
    padding: 10px 0;
    background: transparent;
    box-shadow: none;
    border: none;
    --xt-bg: transparent;
    --xt-accent-bg: transparent;
}

.xt-marquee {
    overflow: visible !important;
    margin: 6px 0;
}

.xt-marquee-inner {
    display: inline-block;
    background: #ffffff;
    color: #000000;
    font-size: 14px;
    padding: 4px 14px;
    border-radius: 999px;
    border: 1px solid #aaaaaa;
    white-space: nowrap;
    animation-duration: 7s !important;
    animation-timing-function: linear;
    animation-iteration-count: infinite;
}

/* 第三条为重点内心，浅粉色底色突出 */
.xt-marquee:nth-child(3) .xt-marquee-inner {
    background: #fff0f6;
    color: #000000;
}

/* 按住暂停滚动 */
.xt-root:active .xt-marquee-inner {
    animation-play-state: paused !important;
}

.xt-marquee:nth-child(odd) .xt-marquee-inner {
    transform: translateX(320px);
    animation-name: scrollLeft;
}
.xt-marquee:nth-child(even) .xt-marquee-inner {
    transform: translateX(-320px);
    animation-name: scrollRight;
}

/* 末尾渐变透明淡出，无突兀消失 */
@keyframes scrollLeft {
    0% { transform: translateX(320px); opacity: 1; }
    85% { transform: translateX(-80px); opacity: 1; }
    100% { transform: translateX(-180px); opacity: 0; }
}
@keyframes scrollRight {
    0% { transform: translateX(-320px); opacity: 1; }
    85% { transform: translateX(400px); opacity: 1; }
    100% { transform: translateX(500px); opacity: 0; }
}

