  --xt-text: #1a1a1a;
  --xt-text-sub: #444;
  --xt-text-muted: #999;
  --xt-accent: #c0392b;
  --xt-accent-bg: rgba(192, 57, 43, 0.06);
  --xt-border: #bbb;
  --xt-radius: 0px;
  --xt-radius-sm: 0px;
  --xt-font: 'LXGW WenKai', 'Kaiti', 'STKaiti', serif;
  --xt-anim-duration: 0.5s;
  --xt-anim-easing: ease-out;
  --xt-stagger-delay: 100ms;

  background: var(--xt-bg);
  border: 2px solid #222;
  box-shadow: none;
  position: relative;
  overflow: hidden;
}

/* ── 试卷纸纹横线 ── */
.xt-root::before {
  content: '';
  position: absolute;
  inset: 0;
  background-image: repeating-linear-gradient(
    180deg,
    transparent,
    transparent 31px,
    rgba(0,0,0,0.06) 31px,
    rgba(0,0,0,0.06) 32px
  );
  pointer-events: none;
  z-index: 0;
}

/* ── 左侧装订线 ── */
.xt-root::after {
  content: '';
  position: absolute;
  left: 28px;
  top: 0;
  bottom: 0;
  width: 1px;
  border-left: 2px dashed rgba(192, 57, 43, 0.25);
  pointer-events: none;
  z-index: 0;
}

.xt-content {
  position: relative;
  z-index: 1;
  padding-left: 20px;
  max-height: 65vh;
  overflow-y: auto;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: thin;
  scrollbar-color: rgba(192,57,43,0.25) transparent;
}

/* ── 滚动条美化（Webkit） ── */
.xt-content::-webkit-scrollbar {
  width: 4px;
}

.xt-content::-webkit-scrollbar-track {
  background: transparent;
}

.xt-content::-webkit-scrollbar-thumb {
  background: rgba(192, 57, 43, 0.2);
  border-radius: 2px;
}

.xt-content::-webkit-scrollbar-thumb:hover {
  background: rgba(192, 57, 43, 0.4);
}

/* ── 头部：考生信息 ── */
.xt-header {
  border-bottom: 2px solid #222;
  padding-bottom: 12px;
  margin-bottom: 8px;
}

.xt-avatar {
  border: 2px solid #222;
  border-radius: 0;
  width: 40px;
  height: 40px;
}

.xt-name {
  color: #111;
  font-size: 14px;
  font-weight: 700;
  letter-spacing: 4px;
  font-family: 'LXGW WenKai', 'Kaiti', serif;
}

/* ── 标题区：绝密★启用前 ── */
.xt-section:first-of-type .xt-section-title {
  text-align: center;
  font-size: 11px;
  letter-spacing: 6px;
  color: #111;
  border: 1.5px solid #111;
  display: inline-block;
  padding: 2px 12px;
  margin: 0 auto 8px auto;
}

/* ── 考试科目副标题 ── */
.xt-text:first-of-type {
  text-align: center;
  font-size: 20px;
  font-weight: 900;
  letter-spacing: 8px;
  color: #000;
  font-family: 'LXGW WenKai', 'Kaiti', serif;
  margin-bottom: 4px;
}

/* ── 题号区块标题 ── */
.xt-section-title {
  color: #111;
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 1px;
  font-family: 'LXGW WenKai', 'Kaiti', serif;
  border-bottom: 1px solid #ccc;
  padding-bottom: 4px;
  margin-bottom: 8px;
}

/* ── 题目正文（AI 出的题） ── */
.xt-section-body {
  background: transparent;
  border-left: none;
  color: #222;
  font-size: 14px;
  line-height: 2;
  font-family: 'LXGW WenKai', 'Kaiti', serif;
  padding: 4px 0 4px 4px;
}

/* ── 答案区（红笔批改） ── */
.xt-text {
  color: #c0392b;
  font-family: 'Ma Shan Zheng', 'LXGW WenKai', cursive;
  font-size: 15px;
  line-height: 1.8;
  padding: 2px 8px;
  background: transparent;
  border-radius: 0;
  position: relative;
  font-style: normal;
}

/* ── 题目字段恢复黑色（覆盖红笔样式） ── */
.xt-text-fillBlank2,
.xt-text-fillBlank3,
.xt-text-judgeQ2,
.xt-text-judgeQ3 {
  color: #222 !important;
  font-family: 'LXGW WenKai', 'Kaiti', serif !important;
  font-size: 14px !important;
}

/* 题目字段不需要红圈标记 */
.xt-text-fillBlank2::before,
.xt-text-fillBlank3::before,
.xt-text-judgeQ2::before,
.xt-text-judgeQ3::before {
  display: none;
}

/* ── 红圈标记效果（答案前的圈） ── */
.xt-text::before {
  content: '';
  position: absolute;
  left: -6px;
  top: 50%;
  transform: translateY(-50%);
  width: 22px;
  height: 22px;
  border: 2px solid rgba(192, 57, 43, 0.55);
  border-radius: 50%;
  pointer-events: none;
}

/* ── 分隔线 = 虚线 ── */
.xt-divider {
  border-top: 1.5px dashed #aaa;
  background: none;
  height: auto;
  margin: 12px 0;
}

/* ── 论述题引用块 = 红笔作文 ── */
.xt-quote {
  background: rgba(0,0,0,0.02);
  border: 1px solid #ddd;
  border-radius: 0;
  padding: 16px 20px;
  font-family: 'Ma Shan Zheng', 'LXGW WenKai', cursive;
  font-size: 15px;
  line-height: 2.2;
  color: #c0392b;
  position: relative;
}

/* 红色引号改为红笔勾 */
.xt-quote::before {
  content: '\2713';
  color: #c0392b;
  font-size: 32px;
  font-weight: 700;
  top: -4px;
  left: -8px;
  font-family: 'Ma Shan Zheng', cursive;
}

.xt-quote::after {
  content: '\2713';
  color: #c0392b;
  font-size: 28px;
  font-weight: 700;
  bottom: -4px;
  right: -4px;
  font-family: 'Ma Shan Zheng', cursive;
}

/* ── 底部评分区 ── */
.xt-grid {
  border: 2px solid #222;
  border-radius: 0;
  padding: 8px;
}

.xt-grid-stat {
  background: transparent;
  border: 1px solid #ccc;
  border-radius: 0;
  padding: 8px;
}

.xt-grid-stat-value {
  color: #c0392b;
  font-size: 28px;
  font-weight: 900;
  font-family: 'Ma Shan Zheng', cursive;
}

.xt-grid-stat-label {
  color: #666;
  font-size: 10px;
  letter-spacing: 2px;
  font-family: 'LXGW WenKai', 'Kaiti', serif;
}

/* ── 阅卷教师批语 ── */
.xt-content > .xt-text:last-of-type {
  color: #c0392b;
  font-family: 'Ma Shan Zheng', cursive;
  font-size: 16px;
  font-style: italic;
  border-top: 1px solid #c0392b;
  padding-top: 8px;
  margin-top: 4px;
}

/* ── 页脚 ── */
.xt-footer {
  color: #aaa;
  font-size: 9px;
  letter-spacing: 3px;
  border-top: 2px solid #222;
  padding-top: 8px;
  font-family: 'LXGW WenKai', 'Kaiti', serif;
}

/* ── 徽章（如果用到） ── */
.xt-badge {
  background: transparent;
  color: #c0392b;
  border: 1.5px solid #c0392b;
  border-radius: 0;
  font-family: 'Ma Shan Zheng', cursive;
  font-size: 13px;
}

#CSS_END

