value.customCss:
/*css字体 */
@import url('https://fontsapi.zeoseven.com/253/main/result.css');

/* ttf  */
@font-face {
    font-family: 'MyTTF';
    src: url('https://s3plus.meituan.net/opapisdk/op_ticket_885190757_1756918024345_qdqqd_q8rd3y.ttf') format('truetype');
}

.xt-root {
    /* ===== 封面 ===== */
    --cover-bg-image: url('https://img.baibai.cv/f/LPqMcg/IMG_6637.png');

    /* ===== 左页（纸张背景层） ===== */
    --left-bg-image: url('https://img.baibai.cv/f/wpkmfv/IMG_6641.png');       /* 左页背景纹理，留空则显示纯色 */
    --left-bg-color: #f5ede4;       /* 左页纯色（图为空时显示） */

    /* ===== 右页 ===== */
    --right-bg-image: url('https://img.baibai.cv/f/52wWHz/IMG_6641.jpeg');      /* 右页背景纹理，留空则显示纯色 */
    --right-bg-color: #f5ede4;      /* 右页纯色（图为空时显示） */

    /* ===== 左页居中照片===== */
    --left-photo-image: url('https://img.baibai.cv/f/V5RnC4/IMG_6642.jpeg');    /* 照片图片链接 */

    /* ===== 书页边缘装饰 ===== */
    --page-edge-decor: url('');

    /* ===== 颜色 ===== */
    --cover-color: #F5F5F7;/*按钮*/
    --cover-text: #B8B8BD;/*标题文字*/
    --cover-border: #F5F5F7;/*框色*/
    --ink-color: #3d3935;
    --muted-ink: #8a827d;
    --tag-bg: rgba(232, 184, 199, 0.18);
    --tag-text: #b36b84;

/* ===== 字体（更换需自行写名字在最前方）===== */
    --diary-font:'MyTTF', 'JasonHandwriting1',  serif;
    --title-font: 'MyTTF','JasonHandwriting1',serif;

    max-width: 620px;
    margin: 0 auto;
    padding: 20px 10px 68px;
    background: transparent !important;
    box-shadow: none !important;
}
/* 清除所有卡片自带背景 */
.xt-card {
    background: transparent !important;
    border: none !important;
    box-shadow: none !important;
    padding: 0 !important;
}
.xt-card-title { display: none; }

/* 主容器相对定位 */
.xt-root > .xt-content > .xt-card {
    position: relative;
    width: 100%;
    min-height: 340px;
    perspective: 2000px;
    background: transparent !important;
}

/*封面样式 */
.xt-text-coverTitle {
    position: relative;
    z-index: 12;
    width: 260px;
    height: 320px;
    margin: 0 auto;
    box-sizing: border-box;
    border-radius: 22px;
    background: var(--cover-bg-image) center / cover no-repeat,
                linear-gradient(135deg, rgba(255,255,255,0.18), transparent 48%),
                var(--cover-color);
    border: 3px solid var(--cover-border);
    box-shadow: 0 18px 28px rgba(100, 80, 60, 0.22), inset 0 1px 0 rgba(255,255,255,0.35);
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 28px;
    white-space: nowrap;
    padding: 50px 30px 66px;
    text-align: center;
    font-family: var(--title-font);
    font-size: 30px;
    color: var(--cover-text);
    transform-origin: center center;
    backface-visibility: hidden;
    transition: transform 0.75s cubic-bezier(.34,1.56,.64,1), opacity 0.45s ease;
}
.xt-text-coverTitle::before {
    content: "";
    position: absolute;
    left: 0;
    top: 0;
    width: 14px;
    height: 100%;
    background: linear-gradient(180deg, rgba(0,0,0,0.06), rgba(255,255,255,0.18), rgba(0,0,0,0.08));
}
.xt-text-coverTitle::after {
    content: "PRIVATE DIARY";
    position: absolute;
    left: 46px;
    right: 46px;
    bottom: 50px;
    padding: 5px 0;
    border-radius: 999px;
    border: 1px solid rgba(255,255,255,0.5);
    font-family: Georgia, serif;
    font-size: 9px;
    color: rgba(255,255,255,0.88);
}
.xt-text-coverSubtitle {
    position: absolute;
    z-index: 14;
    left: 50%;
    top: 226px;
    transform: translateX(-50%);
    text-align: center;
    font-family: var(--title-font);
    font-size: 15px;
    color: rgba(255,255,255,0.92);
    pointer-events: none;
    white-space: nowrap;
}
.xt-image-coverImage { display: none !important; }

/* 翻开按钮 */
.xt-action-1 {
    position: absolute;
    z-index: 24;
    left: 50%;
    bottom: 20px;
    transform: translateX(-50%);
    min-width: 100px;
    height: 30px;
    border-radius: 999px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    background: rgba(255,255,255,0.96);
    color: #815e4e;
    font-size: 12px;
    box-shadow: 0 8px 14px rgba(100,80,60,0.18);
    cursor: pointer;
    transition: all 0.3s ease;
}
.xt-action-1::after { content: "翻开"; }

/*  内页*/
.xt-root .xt-row {
    position: absolute !important;
    top: 0 !important;
    left: 0 !important;
    width: 100% !important;
    height: 340px !important;
    margin: 0 !important;
    display: flex !important;
    gap: 0 !important;
    transform-style: preserve-3d;
    perspective: 2000px;
    opacity: 0;
    pointer-events: none;
    transition: opacity 0.5s ease 0.2s;
    background: transparent !important;
    box-shadow: none !important;
    border-radius: 0 !important;
}

/* 封面翻开后显示 */
#xt-t1:checked ~ .xt-content .xt-row {
    opacity: 1;
    pointer-events: auto;
}

/*  左右内页（纸张背景）*/
.xt-root .xt-row > .xt-card {
    height: 100% !important;
    border-radius: 22px 8px 8px 22px !important;
    flex: 1 !important;
    min-height: unset !important;
    padding: 12px 14px !important;
    overflow: hidden;
    position: relative;
    box-shadow: -4px 8px 14px rgba(100, 80, 60, 0.08) !important;
}

/* 右页 */
.xt-root .xt-row > .xt-card:nth-child(2) {
    background: var(--right-bg-image) center/cover no-repeat,
                var(--right-bg-color) !important;
    border-radius: 8px 22px 22px 8px !important;
    flex: 1.14 !important;
    box-shadow: 4px 8px 14px rgba(100, 80, 60, 0.08) !important;
    overflow-y: auto;
    scrollbar-width: thin;
}

/* 左页（纸张背景 + 居中照片） */
.xt-row > .xt-card:nth-child(1) {
    background: var(--left-bg-image) center/cover no-repeat,
                var(--left-bg-color) !important;
    position: relative;
    overflow: hidden;
}

.xt-row > .xt-card:nth-child(1)::after {
    content: "";
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%) rotate(-2deg);
    width: 100%;
    height: 100%;
    background: var(--left-photo-image) center/contain no-repeat;
    border: 8px solid rgba(255,255,255,0.72);
    border-bottom-width: 20px;
    border-radius: 10px;
    box-shadow: 0 8px 22px rgba(0,0,0,0.14);
    pointer-events: none;
    z-index: 2;
}
/* 滚动条 */
.xt-row > .xt-card:nth-child(2)::-webkit-scrollbar { width: 3px; }
.xt-row > .xt-card:nth-child(2)::-webkit-scrollbar-thumb { background: rgba(100,80,60,0.15); border-radius: 3px; }

/* 装饰边缘 */
.xt-row > .xt-card::before {
    content: "";
    position: absolute;
    top: 0;
    bottom: 0;
    width: 40px;
    background: var(--page-edge-decor) center / contain repeat-y;
    z-index: 10;
    pointer-events: none;
}
.xt-row > .xt-card:nth-child(1)::before { left: 0; }
.xt-row > .xt-card:nth-child(2)::before { right: 0; }

/* 高光 */
.xt-row > .xt-card::after {
    content: "";
    position: absolute;
    inset: 0;
    background: radial-gradient(circle at 12% 8%, rgba(255,255,255,0.12), transparent 24%);
    pointer-events: none;
    z-index: 1;
}

/*   文字排版*/
.xt-text-diaryMeta {
    font-family: var(--title-font);
    font-size: 10px;
    color: var(--muted-ink);
    margin: 0 0 6px 0;
    line-height: 1.1;
    background: transparent !important;
    padding: 0 !important;
    display: block;
}
.xt-text-diaryText {
    font-family: var(--diary-font);
    font-size: 15px;
    line-height: 1.5;
    letter-spacing: 0.7px;
    color: var(--ink-color);
    white-space: pre-wrap;
    background: transparent !important;
    padding: 0 !important;
}

/* 上锁隐藏元数据 */
.xt-text-diaryText:has(+ .xt-text-lockCover),
.xt-row:has(.xt-text-lockCover) .xt-text-diaryMeta {
    display: none !important;
}

/*  锁区 */
.xt-text-lockCover {
    margin-top: 12px;
    text-align: center;
    font-family: var(--title-font);
    font-size: 20px;
    color: var(--ink-color);
    background: transparent !important;
    padding: 0 !important;
}
.xt-text-lockCover::before {
    content: "🔒";
    display: block;
    font-size: 26px;
    margin-bottom: 6px;
}
.xt-text-lockReasonLine {
    margin-top: 10px;
    padding: 6px 0;
    background: transparent !important;
    color: #705240;
    font-size: 11px;
    text-align: center;
}
.xt-text-lockReasonLine::before {
    content: "💭 ";
    display: inline;
    color: #b36b84;
    font-size: 10px;
}
.xt-text-unlockAtText {
    margin-top: 4px;
    padding: 4px 0;
    background: transparent !important;
    color: #705240;
    font-size: 11px;
    text-align: center;
}
.xt-text-unlockAtText::before {
    content: "🔓 ";
    display: inline;
    color: #b36b84;
    font-size: 10px;
}
.xt-text-lockHint {
    margin-top: 8px;
    text-align: center;
    color: #927b68;
    font-size: 10px;
    background: transparent !important;
    padding: 0 !important;
}

/* 彩蛋内容*/
.xt-section {
    background: transparent !important;
    border-radius: 0 !important;
    padding: 0 !important;
    margin: 12px 0 0 0 !important;
}
.xt-section-title {
    font-size: 10px;
    color: #D94C8A; /* 玫红色 */
    font-family: var(--title-font);
    margin-bottom: 4px;
}
.xt-section-body {
    font-family: var(--diary-font);
    font-size: 14px;
    line-height: 1.5;
    color: var(--ink-color);
    white-space: pre-wrap;
    background: transparent !important;
    padding: 0 !important;
}

/* 封面翻开后 */
#xt-t1:checked ~ .xt-content .xt-text-coverTitle {
    opacity: 0;
    transform: rotateY(-130deg) scale(0.88);
}
#xt-t1:checked ~ .xt-content .xt-text-coverSubtitle {
    opacity: 0;
}
#xt-t1:checked ~ .xt-content .xt-action-1 {
    bottom: -44px;
    background: var(--cover-color);
    color: var(--cover-text);
}
#xt-t1:checked ~ .xt-content .xt-action-1::after {
    content: "合上";
}

/* 隐藏辅助字段 */
.XS-field-pendingSealedDiary,
.XS-field-pendingLockId,
.XS-field-pendingUnlockAt,
.XS-field-pendingLockReasonLine,
.XS-field-pendingCreatedAt,
.XS-field-lastDiaryMood,
.XS-field-lastDiarySummary,
.XS-field-coverImage,
.XS-field-diaryImage,
.XS-field-diaryMeta,
.XS-field-diaryText,
.xt-tags,
.xt-tag {
    display: none !important;
}

/* 响应式 */
@media (max-width: 540px) {
    .xt-root { max-width: 340px; }
    .xt-text-coverTitle { width: 240px; height: 300px; font-size: 28px; }
    .xt-root .xt-row { height: 290px !important; }
    .xt-text-diaryText { font-size: 14px; }
    .xt-row > .xt-card:nth-child(1)::after {
        width: 70%;
        height: 70%;
    }
}

value.layout:
# 翻开的日记本

@card ""
  @text coverTitle
  @text coverSubtitle
  @toggle 1

  @row 2
    @card "左页"
    @endcard
    @card "右页"
      @text diaryMeta
      @text diaryText

      @if lockState = locked
        @text lockCover
        @text lockReasonLine
        @text unlockAtText
        @text lockHint
      @endif

      @if unlockBonusState = unlocked
        @section 之前解锁的一页
          unlockBonusText
      @endif
    @endcard
  @endrow
@endcard

