value.customCss:
/*══════════════════════════════════════════════
   暗夜塔罗 · 最终完整版
══════════════════════════════════════════════*/

@import url('https://fonts.googleapis.com/css2?family=Noto+Serif+SC:wght@400;600;700&display=swap');
@import url('https://fonts.googleapis.com/css2?family=Alex+Brush&display=swap');

.xt-root {
  --xt-font: 'Alex Brush', 'Noto Serif SC', serif;
  --xt-bg: #0B0512;
  --xt-text: #f6f0ff;
  --xt-text-sub: #c8bddf;
  --xt-text-muted: #7b6699;
  --xt-accent: #d9ba71;
  --xt-accent-bg: rgba(217, 186, 113, 0.08);
  --xt-border: rgba(217, 186, 113, 0.35);
  --xt-radius: 16px;
  --xt-radius-sm: 10px;

  background: #0B0512 !important;
  color: var(--xt-text);
  padding: 0 !important;
  font-size: 13px;
  position: relative;
  overflow-x: hidden;
}

.xt-content {
  padding: 0 40px 30px 40px !important;
  position: relative !important;
  z-index: 3 !important;
}

/* ═══════════════════════════════════════════
   头部 — 头像名字名言整体下移20px
═══════════════════════════════════════════ */

.xt-header {
  position: relative !important;
  overflow: hidden !important;
  padding: 40px 40px 0 40px !important;
  margin: 0 -40px 0 -40px !important;
  min-height: 280px !important;
  display: flex !important;
  flex-direction: row !important;
  align-items: center !important;
  justify-content: flex-start !important;
  z-index: 1 !important;
  border-bottom: none !important;
}

/* 头图背景 */
.xt-header::before {
  content: "" !important;
  position: absolute !important;
  top: 0 !important;
  left: 0 !important;
  width: 100% !important;
  height: 100% !important;
  z-index: 0 !important;
  background-image: url("https://bee-reg-ab.imagency.cn/p/01b9154fc56d9949ab1d452f77568995.png") !important;
  background-size: cover !important;
  background-position: center top !important;
  background-repeat: no-repeat !important;
  pointer-events: none !important;
}

/* 透明渐变 — 从 40% 开始完全透明 */
.xt-header::after {
  content: "" !important;
  position: absolute !important;
  top: 0 !important;
  left: 0 !important;
  width: 100% !important;
  height: 100% !important;
  z-index: 1 !important;
  background: linear-gradient(
    to bottom,
    rgba(11, 5, 18, 0) 0%,
    rgba(11, 5, 18, 0.2) 40%,
    rgba(11, 5, 18, 0.35) 55%,
    rgba(11, 5, 18, 0.55) 65%,
    rgba(11, 5, 18, 1) 95%
  ) !important;
  pointer-events: none !important;
}

/* ═══ 头像 ═══ */
.xt-header .xt-avatar {
  position: relative !important;
  z-index: 2 !important;
  border: 0.5px solid rgba(217, 186, 113, 0.9) !important;
  box-shadow: 0 0 0 3px rgba(217, 186, 113, 0.6), 0 8px 24px rgba(0,0,0,0.7) !important;
  width: 75px !important;
  height: 75px !important;
  flex-shrink: 0 !important;
  margin-right: 16px !important;
  margin-bottom: 0 !important;
}

/* ═══ 名字 ═══ */
.xt-header .xt-name {
  position: relative !important;
  z-index: 2 !important;
  font-size: 22px !important;
  font-weight: 600 !important;
  color: #fef7ed !important;
  letter-spacing: 1.5px !important;
  text-shadow: 0 2px 12px rgba(0,0,0,0.9), 0 0 30px rgba(0,0,0,0.5) !important;
  line-height: 1.2 !important;
  text-align: left !important;
  margin-bottom: 0 !important;
  display: flex !important;
  flex-direction: column !important;
}

.xt-header .xt-name + .xt-name {
  display: none !important;
}

/* ═══════════════════════════════════════════
   名言 — 在头像右边、名字正下方
   用 margin-top 负值上拉，不用绝对定位
═══════════════════════════════════════════ */

.xt-text-sentence {
  /* 清除所有系统默认样式 */
  all: initial !important;
  /* 重新设置 */
  display: block !important;
  position: relative !important;
  z-index: 2 !important;
  font-family: 'Alex Brush', cursive !important;
  font-size: 28px !important;
  font-weight: 400 !important;
  color: rgba(255, 255, 255, 0.9) !important;
  letter-spacing: 1.5px !important;
  text-shadow: 0 0 30px rgba(217, 186, 113, 0.12), 0 2px 8px rgba(0, 0, 0, 0.6) !important;
  line-height: 1.3 !important;
  text-align: left !important;
  background: transparent !important;
  border: none !important;
  padding: 0 !important;
  margin: -100px 0 0 96px !important;  /* 左移96px（头像80px+16px间距），上拉30px紧贴名字 */
  width: auto !important;
  min-height: auto !important;
  pointer-events: none !important;
}

/* 默认名言（AI没返回时） */
.xt-text-sentence:empty::before {
  content: "The stars incline us, they do not bind us." !important;
  color: rgba(255, 255, 255, 0.35) !important;
  font-size: 20px !important;
}

/* ═══ 今日问题 — 上移消除与头部的间距 ═══ */
.xt-content .xt-section:first-of-type {
  position: relative !important;
  z-index: 10 !important;
  padding-top: 0 !important;
  margin-top: -50px !important;  /* 保留上移，但层级提高 */
}

/* ═══ 星尘背景 ═══ */
.xt-root::before {
  content: "" !important;
  position: fixed !important;
  inset: 0 !important;
  pointer-events: none !important;
  z-index: 0 !important;
  background:
    radial-gradient(circle at 12% 20%, rgba(255, 240, 200, 0.08) 1px, transparent 2px),
    radial-gradient(circle at 78% 30%, rgba(255, 240, 200, 0.06) 1px, transparent 2px),
    radial-gradient(circle at 40% 70%, rgba(255, 240, 200, 0.07) 1px, transparent 2px),
    radial-gradient(circle at 85% 80%, rgba(255, 240, 200, 0.05) 1px, transparent 2px),
    radial-gradient(circle at 25% 90%, rgba(255, 240, 200, 0.04) 1px, transparent 2px) !important;
  background-size: 200px 200px, 260px 260px, 320px 320px, 400px 400px, 500px 500px !important;
  opacity: 0.5 !important;
  animation: xtStarDrift 120s linear infinite !important;
}

@keyframes xtStarDrift {
  from { transform: translateY(0); }
  to { transform: translateY(-180px); }
}

/* ═══ 区块标题 ═══ */
.xt-section-title {
  text-align: center !important;
  font-size: 17px !important;
  letter-spacing: 4px !important;
  text-transform: uppercase !important;
  color: #f8e2aa !important;
  font-weight: 400 !important;
  text-shadow: 0 0 10px rgba(255, 220, 150, 0.18), 0 0 24px rgba(255, 220, 150, 0.05) !important;
  margin-bottom: 12px !important;
}

/* ═══ 卡片标题 ═══ */
.xt-card-title {
  text-align: center !important;
  font-size: 11px !important;
  color: rgba(217, 186, 113, 0.7) !important;
  letter-spacing: 2px !important;
  text-transform: uppercase !important;
  font-weight: 400 !important;
  margin-top: 3px !important;
  background: transparent !important;
  padding: 0 !important;
  text-shadow: 0 0 8px rgba(217, 186, 113, 0.2) !important;
}

/* ═══ 今日问题 ═══ */
.xt-text-question {
  display: block !important;
  background: transparent !important;
  border: none !important;
  padding: 12px 0 !important;
