/* === 整个大框架：极简冷调黛灰白 === */
.xt-root {
  --xt-bg: #f5f5f5; /* 极其干净素雅的冷雾灰白色 */
  --xt-text: #444444; /* 沉静高雅的主字灰 */
  --xt-text-sub: #888888; /* 柔和莫兰迪冷中灰 */
