  margin-bottom: 10px;
  border-bottom: 1px solid rgba(255,255,255,0.08);
  border-left: 3px solid #c9a86a;
}

/* 发帖头部：@header charImage userinfo（真实头像 + 名字@账号时间） */
.xt-header {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 4px 0 10px;
}
.xt-avatar {
  width: 44px; height: 44px;
  border-radius: 50%;
