  border-top: 2px solid rgba(201,168,106,0.4);
  margin-top: 8px;
}
/* ===== 第7段 · 内心区 ===== */
.xt-text-pollq {
  padding: 10px 14px 10px 16px;
  background: #1e1e22;
  border: 1px solid rgba(255,255,255,0.07);
  border-left: 3px solid #c9a86a;
  border-radius: 12px;
  font-size: 15px; font-weight: 700;
  color: #f5f5f3;
}
.xt-text-pollopt {
  position: relative;
  padding: 10px 14px 10px 34px;
  background: #1e1e22;
  border: 1px solid rgba(255,255,255,0.07);
  border-left: 3px solid #c9a86a;
  border-radius: 12px;
  font-size: 14px; line-height: 2.2;
  color: rgba(245,245,243,0.75);
}
.xt-text-pollopt::before {
  content: "";
  position: absolute;
  left: 14px; top: 50%;
  transform: translateY(-50%);
  width: 12px; height: 12px;
  border-radius: 50%;
  border: 2px solid rgba(201,168,106,0.5);
  background: radial-gradient(circle, #c9a86a 0 40%, transparent 45%);
}
.xt-text-pollopt::first-line { color: #f5f5f3; font-weight: 700; }
.xt-text-pollinfo {
  padding: 8px 14px;
  background: #1b1b1f;
  border-radius: 10px;
  font-size: 12px;
  color: rgba(245,245,243,0.5);
}
.xt-text-trends_hot {
  padding: 12px 14px 12px 16px;
  background: linear-gradient(180deg, #201f1c, #1a1916);
  border: 1px solid rgba(201,168,106,0.12);
  border-left: 3px solid #c9a86a;
  border-radius: 12px;
  font-size: 13.5px; line-height: 2.3;
  color: rgba(245,245,243,0.8);
}
.xt-text-history {
  position: relative;
  padding: 12px 14px 12px 36px;
  background: #1c1c20;
  border: 1px solid rgba(255,255,255,0.07);
  border-left: 2px dotted rgba(201,168,106,0.6);
  border-radius: 12px;
  font-size: 13px; line-height: 2.1;
  color: rgba(245,245,243,0.55);
}
.xt-text-history::before {
  content: "";
  position: absolute;
  left: 13px; top: 50%;
  transform: translateY(-50%);
  width: 10px; height: 10px;
  border: 1.5px solid rgba(245,245,243,0.4);
  border-radius: 50%;
}
.xt-text-history::after {
  content: "";
  position: absolute;
  left: 22px; top: calc(50% + 4px);
  width: 6px; height: 1.5px;
  background: rgba(245,245,243,0.4);
  transform: rotate(45deg);
}
.xt-quote {
  position: relative;
  padding: 14px 16px 14px 22px;
  background: linear-gradient(135deg, #232018, #1f1c16);
  border: 1px solid rgba(201,168,106,0.22);
  border-radius: 12px;
  font-size: 14px; line-height: 1.9;
  color: #f5f5f3;
  font-style: italic;
}
.xt-text-recommend_reminder {
  padding: 10px 14px 10px 16px;
  background: #1e1e22;
  border: 1px solid rgba(255,255,255,0.07);
  border-left: 3px solid #c9a86a;
  border-radius: 12px;
  font-size: 13.5px; line-height: 2.1;
  color: rgba(245,245,243,0.75);
}
.xt-text-reading {
  padding: 14px 16px;
  background: linear-gradient(135deg, #0f1f18, #12161a);
  border: 1px solid rgba(46,175,79,0.25);
  border-left: 3px solid #2eaf4f;
  border-radius: 14px;
  font-size: 13.5px; line-height: 1.95;
  color: rgba(245,245,243,0.85);
}
.xt-text-reading::first-line { color: #4ade80; font-weight: 700; }
.xt-text-letter {
  position: relative;
  padding: 46px 18px 32px;
  background-color: #fbf7ec;
  background-image:
    linear-gradient(180deg, rgba(255,255,255,0.6), transparent 30%),
    linear-gradient(180deg, transparent, rgba(210,190,150,0.15));
  border: 1px solid rgba(200,180,140,0.5);
  border-radius: 18px;
  box-shadow:
    0 14px 36px rgba(0,0,0,0.55),
    inset 0 1px 0 rgba(255,255,255,0.8),
    inset 0 0 60px rgba(230,215,180,0.2);
  font-family: -apple-system, BlinkMacSystemFont, "PingFang SC", sans-serif;
  font-size: 15px;
  line-height: 1.9;
  letter-spacing: 0.3px;
  color: #3a3428;
  white-space: pre-wrap;
}
.xt-text-letter::before {
  content: "";
  position: absolute;
  top: 0; left: 0; right: 0;
  height: 32px;
  background:
    radial-gradient(circle 3px at 16px 16px, rgba(120,100,70,0.35), transparent),
    radial-gradient(circle 3px at 28px 16px, rgba(120,100,70,0.35), transparent),
    radial-gradient(circle 3px at 40px 16px, rgba(120,100,70,0.35), transparent),
    linear-gradient(180deg, #f0e9d6, #e4dbc2);
  border-radius: 18px 18px 0 0;
  border-bottom: 1px solid rgba(200,180,140,0.35);
}
.xt-text-letter::after {
  content: "";
  position: absolute;
  left: 18px; right: 18px; bottom: 14px;
  height: 1px;
  background: linear-gradient(90deg, rgba(180,160,120,0.5), transparent 70%);
}
/* ===== 第8段 · 系统区 ===== */
.xt-text-screentime {
  padding: 12px 14px;
  background: #1c1e22;
  border: 1px solid rgba(255,255,255,0.07);
  border-left: 3px solid #c9a86a;
  border-radius: 12px;
  font-size: 13.5px; line-height: 2.1;
  color: rgba(245,245,243,0.8);
}
.xt-text-sms {
  position: relative;
  padding: 14px 16px;
  background: #1b1b1f;
  border: 1px solid rgba(255,255,255,0.08);
  border-left: 3px solid #4a9eff;
  border-radius: 14px;
  font-size: 13.5px; line-height: 1.9;
  color: rgba(245,245,243,0.85);
}
.xt-text-sms::before {
  content: "信息";
  display: block;
  font-size: 10px; font-weight: 700;
  letter-spacing: 2.4px;
  color: #4a9eff;
  margin-bottom: 8px;
}
.xt-text-sms::first-line {
  color: #4a9eff;
  font-weight: 700;
}
.xt-text-notify {
  position: relative;
  padding: 12px 14px 12px 20px;
  background: #1d2023;
  border: 1px solid rgba(255,255,255,0.07);
  border-left: 3px solid #9fb2c0;
  border-radius: 12px;
  font-size: 13.5px; line-height: 2.1;
  color: rgba(245,245,243,0.8);
}
.xt-text-quickpanel {
  padding: 12px 16px;
  background: #1d2023;
  border: 1px solid rgba(255,255,255,0.07);
  border-left: 3px solid #9fb2c0;
  border-radius: 12px;
  font-size: 13.5px; line-height: 2.4;
  color: rgba(245,245,243,0.75);
  text-align: center;
  letter-spacing: 0.5px;
}
.xt-text-weather_stamp {
  padding: 12px 16px;
  background: linear-gradient(120deg, #0e2238, #0d1a26);
  border: 1px solid rgba(74,158,255,0.4);
  border-left: 3px solid #4a9eff;
  border-radius: 14px;
  font-size: 13px; letter-spacing: 1px;
  color: #f5f5f3;
  text-align: center;
}
.xt-text-bottomnav {
  padding: 12px 0;
  margin-top: 8px;
  background: #1e1e22;
  border: 1px solid rgba(255,255,255,0.09);
  border-radius: 16px;
  font-size: 13px; letter-spacing: 6px;
  text-align: center;
  color: rgba(245,245,243,0.75);
}
/* ===== 第9段 · 品牌装饰 ===== */
.xt-text-phonebar::before {
  content: "" !important;
  position: absolute !important;
  left: 55% !important; top: 50% !important;
  transform: translate(-50%, -50%) !important;
  width: 76px !important; height: 26px !important;
  border-radius: 13px !important;
  background: #000 !important;
  display: block !important;
  box-shadow: 0 0 0 1.5px rgba(255,255,255,0.25), inset 0 0 6px rgba(255,255,255,0.06) !important;
}
.xt-text-phonebar::after {
  content: "" !important;
  position: absolute !important;
  right: 18px !important; top: 50% !important;
  transform: translateY(-50%) !important;
  width: 24px !important; height: 12px !important;
  border: 1px solid rgba(245,245,243,0.65) !important;
  border-radius: 3px !important;
  background: linear-gradient(90deg, #c9a86a 0 70%, rgba(255,255,255,0.12) 70% 100%) !important;
  display: block !important;
}
.xt-text-douyin::after {
  content: "";
  position: absolute;
  right: 16px; bottom: 14px;
  border-left: 10px solid #25f4ee;
  border-top: 7px solid transparent;
  border-bottom: 7px solid transparent;
  opacity: 0.85;
}
.xt-text-zhihu::before {
  content: "";
  position: absolute;
  top: 0; left: 0; right: 0;
  height: 4px;
  background: linear-gradient(90deg, #0084ff, rgba(0,132,255,0.15));
  border-radius: 12px 12px 0 0;
}
.xt-text-zhihu::after {
  content: "";
  position: absolute;
  left: 16px; right: 16px; bottom: 8px;
  height: 1px;
  background: rgba(0,132,255,0.25);
}
.xt-text-game::after {
  content: "";
  position: absolute;
  left: 16px; right: 16px; bottom: 10px;
  height: 5px;
  border-radius: 3px;
  background: linear-gradient(90deg, #8b7cf0 0 70%, rgba(255,255,255,0.08) 70% 100%);
}
.xt-text-delivery::after {
  content: "";
  display: block;
  height: 4px;
  border-radius: 2px;
  margin-top: 10px;
  background: linear-gradient(90deg, #ff6600 0 65%, rgba(255,255,255,0.1) 65% 100%);
}
.xt-text-wallet_app::before {
  content: "";
  position: absolute;
  left: 16px; top: 16px;
  width: 30px; height: 22px;
  border-radius: 4px;
  background: linear-gradient(135deg, rgba(255,255,255,0.85), rgba(255,255,255,0.3));
  box-shadow: inset 0 0 4px rgba(0,0,0,0.3);
}
.xt-text-location::before {
  content: "";
  position: absolute;
  left: 13px; top: 50%;
  transform: translateY(-50%) rotate(45deg);
  width: 9px; height: 9px;
  border: 2px solid #10b981;
  border-radius: 50% 50% 50% 0;
}
.xt-text-cmt_all::before {
  content: "评论";
  display: block;
  font-size: 10px; font-weight: 700;
  letter-spacing: 2.6px;
  color: #c9a86a;
  margin-bottom: 10px;
}
.xt-text-notify::before {
  content: "";
  position: absolute;
  left: 6px; top: 18px;
  width: 6px; height: 6px;
  border-radius: 50%;
  background: #c9a86a;
  box-shadow: 0 0 0 3px rgba(201,168,106,0.18);
}
.xt-quote::before {
  content: "“";
  position: absolute;
  left: 7px; top: 0;
  font-family: Georgia, serif;
  font-size: 38px; line-height: 1;
  color: #c9a86a;
  opacity: 0.55;
}

