value.layout:
# 顶部豆包导航栏
@text headerTitle

# 系统当前时间
@text currentTime

# 豆包聊天气泡
@bubbles
  charQuestion:right .slideInRight
  doubaoAnswer:left .slideInLeft.delay100

# 并排滑动导航栏 (缩减为3列)
@row 3
  @toggle 1
  @toggle 2
  @toggle 3
@endrow

# 板块1：快速点评 (第5个子元素)
@card "快速"
  @text comment1
  @text comment2
  @text comment3
  @toggle 1
@endcard

# 板块2：角色心声 (第6个子元素)
@card "帮我写作"
  @text dateHeader
  @text charInnerVoice
  @toggle 2
@endcard

# 板块3：豆包吐槽 (第7个子元素)
@card "AI创作"
  @text doubaoTaunt
  @toggle 3
@endcard

# 底部语音输入框
@text bottomBar

