/* =========================================================
   冬日旧日书信 · Vintage Winter Letter
   长文本可滚动 + 细腻入场动画
   ========================================================= */

.xt-root {
    --xt-bg: #f3ead8;
    --xt-text: #40372d;
    --xt-text-sub: #806f5b;
    --xt-text-muted: #a99a84;
    --xt-accent: #725b43;
    --xt-accent-bg: rgba(114, 91, 67, 0.06);
    --xt-border: rgba(92, 73, 52, 0.22);

    --xt-radius: 4px;
    --xt-radius-sm: 2px;

    --xt-font: "STKaiti", "Kaiti", "KaiTi", serif;

    --xt-shadow-sm: 0 2px 8px rgba(60, 45, 30, 0.08);
    --xt-shadow-md: 0 8px 25px rgba(60, 45, 30, 0.12);

    --xt-anim-duration: 0.55s;
    --xt-anim-easing: ease-out;

    position: relative;

    width: 100%;
    max-width: 100%;

    box-sizing: border-box;

    /* =========================
       核心：固定信纸高度
       ========================= */

    height: 620px !important;
    max-height: 78vh !important;
    min-height: 420px !important;

    /* =========================
       核心：信纸内部滚动
       ========================= */

    overflow-y: auto !important;
    overflow-x: hidden !important;

    -webkit-overflow-scrolling: touch;
    overscroll-behavior: contain;

    scrollbar-width: thin;
    scrollbar-color: rgba(92, 73, 52, 0.35) transparent;

    color: var(--xt-text);
    font-family: var(--xt-font);
    line-height: 1.9;

    background:
        linear-gradient(
            rgba(255,255,255,0.12),
            rgba(255,255,255,0.12)
        ),
        #f3ead8;

    border: 1px solid rgba(92, 73, 52, 0.18);
    border-radius: var(--xt-radius);

    box-shadow:
        0 8px 25px rgba(60, 45, 30, 0.12),
        inset 0 0 45px rgba(100, 75, 40, 0.04);

    overflow-wrap: break-word;
    word-break: break-word;

    animation: letterAppear 0.7s ease-out both;
}


/* =========================================================
   信纸滚动条
   ========================================================= */

.xt-root::-webkit-scrollbar {
    width: 5px;
}

.xt-root::-webkit-scrollbar-track {
    background: transparent;
}

.xt-root::-webkit-scrollbar-thumb {
    background: rgba(92, 73, 52, 0.30);
    border-radius: 10px;
}

.xt-root::-webkit-scrollbar-thumb:hover {
    background: rgba(92, 73, 52, 0.45);
}


/* =========================================================
   内容区域
   ========================================================= */

.xt-content {
    width: 100%;
    box-sizing: border-box;

    height: auto !important;
    min-height: 0 !important;

    overflow: visible !important;

    padding: 28px 24px 30px;
}


/* =========================================================
   顶部
   ========================================================= */

.xt-header {
    display: flex;
    align-items: center;
    gap: 12px;

    margin-bottom: 20px;

    animation: letterFadeDown 0.6s ease-out 0.08s both;
}

.xt-avatar {
    width: 46px;
    height: 46px;

    object-fit: cover;

    border-radius: 50%;
    border: 2px solid rgba(92, 73, 52, 0.45);

    filter: sepia(0.15);

    animation: portraitBreathe 4s ease-in-out 0.8s infinite;
}

.xt-name {
    color: #5d4b38;

    font-size: 17px;
    font-weight: 600;

    letter-spacing: 1px;
}


/* =========================================================
   标题
   ========================================================= */

.xt-text-title {
    display: block;

    margin-bottom: 6px;

    color: #4c3d2d;

    font-size: 20px;
    font-weight: 600;

    letter-spacing: 1px;

    animation: inkAppear 0.7s ease-out 0.18s both;
}


/* =========================================================
   日期
   ========================================================= */

.xt-text-date {
    display: block;

    margin-bottom: 22px;

    color: #9b896f;

    font-size: 12px;
    letter-spacing: 1px;

    text-align: right;

    animation: inkAppear 0.7s ease-out 0.28s both;
}


/* =========================================================
   称呼
   ========================================================= */

.xt-text-greeting {
    margin-bottom: 16px;

    color: #4d4032;

    font-size: 16px;
    font-weight: 600;

    animation: letterSlide 0.65s ease-out 0.36s both;
}


/* =========================================================
   正文
   ========================================================= */

.xt-quote {
    position: relative;

    width: 100%;
    box-sizing: border-box;

    margin: 0 0 22px;
    padding: 4px 4px 4px 20px;

    background: transparent;

    border: 0;

    color: #40372d;

    font-family: var(--xt-font);

    font-size: 16px;
    line-height: 2.05;

    white-space: pre-wrap;

    overflow: visible !important;

    animation: letterBodyAppear 0.9s ease-out 0.45s both;
}


/* =========================================================
   左侧旧信纸装饰线
   ========================================================= */

.xt-quote::before {
    content: "";

    position: absolute;

    left: 0;
    top: 5px;
    bottom: 5px;

    width: 1px;

    background: rgba(114, 91, 67, 0.35);

    transform-origin: top;

    animation: letterLine 0.9s ease-out 0.55s both;
}


/* =========================================================
   正文段落
   ========================================================= */

.xt-quote p {
    margin: 0 0 1em;
}


/* =========================================================
   结尾
   ========================================================= */

.xt-text-ending {
    margin-top: 18px;
    margin-bottom: 26px;

    color: #514536;

    font-size: 15px;
    line-height: 2;

    white-space: pre-wrap;

    animation: letterFade 0.8s ease-out 0.65s both;
}


/* =========================================================
   署名
   ========================================================= */

.xt-text-signature {
    margin-top: 8px;

    color: #514536;

    font-size: 16px;

    text-align: right;

    font-style: italic;

    animation: signatureAppear 0.9s ease-out 0.78s both;
}


/* =========================================================
   分隔线
   ========================================================= */

.xt-divider {
    height: 1px;

    margin: 18px 0;

    border: 0;

    background: rgba(92, 73, 52, 0.16);

    transform-origin: left center;

    animation: dividerAppear 0.7s ease-out 0.55s both;
}


/* =========================================================
   底部
   ========================================================= */

.xt-footer {
    margin-top: 25px;
    padding-top: 12px;

    color: #ad9c84;

    font-size: 9px;

    letter-spacing: 3px;

    text-align: center;

    border-top: 1px solid rgba(92, 73, 52, 0.12);

    animation: letterFade 0.8s ease-out 0.9s both;
}


/* =========================================================
   徽章
   ========================================================= */

.xt-badge {
    display: inline-flex;
    align-items: center;

    padding: 4px 9px;

    background: rgba(114, 91, 67, 0.07);

    border: 1px solid rgba(114, 91, 67, 0.16);
    border-radius: 3px;

    color: #725b43;

    font-size: 12px;
}


/* =========================================================
   所有文本统一允许换行
   ========================================================= */

.xt-text,
.xt-section-body,
.xt-list-item,
.xt-bubble-body,
.xt-card,
.xt-collapse-body {
    max-width: 100%;
    box-sizing: border-box;

    white-space: pre-wrap;
    overflow-wrap: break-word;
    word-break: break-word;
}


/* =========================================================
   防止动画导致长内容容器异常
   ========================================================= */

.xt-anim-fadeIn,
.xt-anim-fadeInUp,
.xt-anim-fadeInDown,
.xt-anim-scaleIn,
.xt-anim-blurIn {
    max-height: none !important;
}


/* =========================================================
   动画：整张信纸
   ========================================================= */

@keyframes letterAppear {
    from {
        opacity: 0;
        transform: translateY(8px);
    }

    to {
        opacity: 1;
        transform: translateY(0);
    }
}


/* =========================================================
   动画：顶部
   ========================================================= */

@keyframes letterFadeDown {
    from {
        opacity: 0;
        transform: translateY(-7px);
    }

    to {
        opacity: 1;
        transform: translateY(0);
    }
}


/* =========================================================
   动画：头像轻微呼吸
   ========================================================= */

@keyframes portraitBreathe {
    0%,
    100% {
        transform: scale(1);
    }

    50% {
        transform: scale(1.025);
    }
}


/* =========================================================
   动画：墨迹显现
   ========================================================= */

@keyframes inkAppear {
    from {
        opacity: 0;
        filter: blur(2px);
        transform: translateY(4px);
    }

    to {
        opacity: 1;
        filter: blur(0);
        transform: translateY(0);
    }
}


/* =========================================================
   动画：称呼
   ========================================================= */

@keyframes letterSlide {
    from {
        opacity: 0;
        transform: translateX(-7px);
    }

    to {
        opacity: 1;
        transform: translateX(0);
    }
}


/* =========================================================
   动画：正文
   ========================================================= */

@keyframes letterBodyAppear {
    from {
        opacity: 0;
        transform: translateY(6px);
    }

    to {
        opacity: 1;
        transform: translateY(0);
    }
}


/* =========================================================
   动画：信纸竖线
   ========================================================= */

@keyframes letterLine {
    from {
        opacity: 0;
        transform: scaleY(0);
    }

    to {
        opacity: 1;
        transform: scaleY(1);
    }
}


/* =========================================================
   动画：淡入
   ========================================================= */

@keyframes letterFade {
    from {
        opacity: 0;
    }

    to {
        opacity: 1;
    }
}


/* =========================================================
   动画：署名
   ========================================================= */

@keyframes signatureAppear {
    from {
        opacity: 0;
        transform: translateX(8px);
    }

    to {
        opacity: 1;
        transform: translateX(0);
    }
}


/* =========================================================
   动画：分隔线
   ========================================================= */

@keyframes dividerAppear {
    from {
        opacity: 0;
        transform: scaleX(0);
    }

    to {
        opacity: 1;
        transform: scaleX(1);
    }
}


/* =========================================================
   手机屏幕适配
