    --xt-border: rgba(83,101,109,.22);

    --xt-radius: 5px;
    --xt-radius-sm: 3px;

    --xt-font:
        "Times New Roman",
        "Noto Serif SC",
        serif;

    position: relative;

    max-height: 720px;

    overflow-y: auto;
    overflow-x: hidden;

    box-sizing: border-box;

    padding: 0;

    color: var(--xt-text);

    font-family: var(--xt-font);

    background:
        linear-gradient(
            rgba(255,255,255,.42),
            rgba(255,255,255,.42)
        ),
        #eeeae3;

    border:
        1px solid rgba(75,90,97,.2);

    border-radius: 6px;

    box-shadow:
        0 10px 28px rgba(45,55,60,.13),
        0 2px 5px rgba(45,55,60,.06);
}


/* =========================================================
   SCROLLBAR
   ========================================================= */

.xt-root::-webkit-scrollbar {
    width: 5px;
}

.xt-root::-webkit-scrollbar-track {
    background: transparent;
}

.xt-root::-webkit-scrollbar-thumb {
    background: rgba(80,100,108,.25);
    border-radius: 10px;
}

.xt-root {
    scrollbar-width: thin;
    scrollbar-color:
        rgba(80,100,108,.25)
        transparent;
}


/* =========================================================
   CONTENT
   ========================================================= */

.xt-content {
    position: relative;

    z-index: 2;

    min-width: 0;

    padding:
        17px
        16px
        20px;

    box-sizing: border-box;
}


/* =========================================================
   所有文字允许正常换行
   ========================================================= */

.xt-root,
.xt-content,
.xt-card,
.xt-section,
.xt-section-body,
.xt-text,
.xt-quote,
.xt-footer {

    min-width: 0;

    max-width: 100%;

    box-sizing: border-box;

    white-space: normal !important;

    word-break: normal !important;

    overflow-wrap: anywhere !important;
}


/* =========================================================
   纸张纹理
   ========================================================= */

.xt-root::before {

    content: "";

    position: absolute;

    inset: 0;

    pointer-events: none;

    z-index: 0;

    opacity: .28;

    background-image:
        radial-gradient(
            rgba(70,80,84,.14) .45px,
            transparent .55px
        );

    background-size: 5px 5px;
}


/* =========================================================
   ❄️ 车票
   ========================================================= */

.xt-card {

    position: relative;

    display: block;

    width: 100%;

    margin:
        0
        0
        23px;

    padding:
        15px
        15px
        17px;

    background:
        linear-gradient(
            135deg,
            rgba(255,255,255,.72),
            rgba(222,229,231,.45)
        );

    border:
        1px solid rgba(78,96,104,.3);

    border-radius: 4px;

    box-shadow:
        0 3px 10px rgba(50,60,65,.08);

    overflow: hidden;
}


/* =========================================================
   车票顶部
   ========================================================= */

.xt-card::before {

    content:
        "WINTER MAIL     ✦     EXPRESS";

    display: block;

    width: 100%;

    padding-bottom: 8px;

    margin-bottom: 10px;

    border-bottom:
        1px solid
        rgba(85,103,110,.25);

    color: #788991;

    font-family:
        "Times New Roman",
        serif;

    font-size: 8px;

    letter-spacing: 2px;

    text-align: center;
}


/* =========================================================
   车票底部虚线
   ========================================================= */

.xt-card::after {

    content: "";

    position: absolute;

    left: 0;
    right: 0;

    bottom: 8px;

    border-bottom:
        1px dashed
        rgba(80,98,106,.28);
}


/* =========================================================
   车票标题
   ========================================================= */

.xt-card .xt-text:nth-child(1) {

    display: block;

    width: 100%;

    padding: 2px 5px 4px;

    margin: 0;

    background: transparent;

    border: 0;

    color: #52666f;

    font-family:
        "Times New Roman",
        "Noto Serif SC",
        serif;

    font-size: 15px !important;

    line-height: 1.4;

    letter-spacing: 1px;

    text-align: center;

    white-space: normal !important;

    overflow-wrap: anywhere !important;
}


/* =========================================================
   日期
   ========================================================= */

.xt-card .xt-text:nth-child(2) {

    display: block;

    padding: 2px;

    margin: 0;

    background: transparent;

    border: 0;

    color: #89969a;

    font-size: 9px !important;

    line-height: 1.6;

    letter-spacing: 1.5px;

    text-align: center;
}


/* =========================================================
   出发地 / 目的地
   ========================================================= */

.xt-card .xt-text:nth-child(3),
.xt-card .xt-text:nth-child(4) {

    display: inline-block;

    width: 48%;

    vertical-align: top;

    box-sizing: border-box;

    padding:
        7px
        5px
        5px;

    margin-top: 8px;

    background:
        rgba(255,255,255,.35);

    border-top:
        1px solid
        rgba(90,108,115,.12);

    color: #65757b;

    font-size: 10px !important;

    line-height: 1.5;

    text-align: center;
}


/* =========================================================
   收件人
   ========================================================= */

.xt-card .xt-text:nth-child(5) {

    display: block;

    padding-top: 7px;

    margin-top: 7px;

    background: transparent;

    border: 0;

    color: #69797e;

    font-size: 9px !important;

    letter-spacing: 1px;

    text-align: right;
}


/* =========================================================
   车票齿孔
   ========================================================= */

.xt-card {

    border-left:
        1px solid
        rgba(78,96,104,.3);

    border-right:
        1px solid
        rgba(78,96,104,.3);
}


/* 左侧齿孔 */

.xt-card .xt-card-title::before {
    content: "";
}


/* 用伪元素制造左右打孔 */

.xt-card {
    --hole:
        radial-gradient(
            circle,
            #eeeae3 0 3px,
            transparent 3.5px
        );
}


/* =========================================================
   LETTER 标题
   ========================================================= */

.xt-section-title {

    margin:
        5px
        0
        8px;

    color: #8a989c;

    font-family:
        "Times New Roman",
        serif;

    font-size: 8px;

    letter-spacing: 3px;

    text-transform: uppercase;

    text-align: center;
}


/* =========================================================
   长篇正文
   ========================================================= */

.xt-section-body {

    display: block;

    width: 100%;

    box-sizing: border-box;

    padding:
        17px
        17px
        18px;

    margin:
        0
        0
        17px;

    background:
        rgba(255,255,255,.42);

    border:
        1px solid
        rgba(90,106,113,.15);

    border-left:
        2px solid
        rgba(113,137,149,.4);

    border-radius: 3px;

    color: #414b4f;

    font-size: 14px;

    line-height: 2;

    letter-spacing: .15px;

    white-space: pre-wrap !important;

    word-break: normal !important;

    overflow-wrap: anywhere !important;

    text-align: left;

    box-shadow:
        inset 0 0 20px
        rgba(255,255,255,.25);
}


/* =========================================================
   正文中的换行
   ========================================================= */

.xt-section-body br {

    display: block;

    content: "";

    margin-bottom: .8em;
}


/* =========================================================
   段落首字装饰
   ========================================================= */

.xt-section-body::first-letter {

    font-size: 23px;

    color: #708893;
}


/* =========================================================
   结尾
   ========================================================= */

.xt-content > .xt-text {

    display: block;

    width: 100%;

    box-sizing: border-box;

    padding: 6px 4px;

    margin:
        7px
        0;

    background: transparent;

    border: 0;

    color: #68777c;

    font-size: 13px;

    line-height: 1.9;

    white-space: pre-wrap !important;

    overflow-wrap: anywhere !important;
}


/* =========================================================
   落款
   ========================================================= */

.xt-content > .xt-text:last-of-type {

    margin-top: 12px;

    padding-right: 13px;

    text-align: right;

    color: #65747a;

    font-family:
        "Times New Roman",
        "Noto Serif SC",
        serif;

    font-style: italic;

    font-size: 13px;
}


/* =========================================================
   FOOTER
   ========================================================= */

.xt-footer {

    margin-top: 17px;

    padding-top: 10px;

    border-top:
        1px solid
        rgba(90,106,113,.16);

    color: #9aa3a6;

    font-family:
        "Times New Roman",
        serif;

    font-size: 8px;

    letter-spacing: 2px;

    text-align: center;

    font-style: italic;
}


/* =========================================================
   动画
   ========================================================= */

@keyframes winterLetterIn {

    from {
        opacity: 0;
        transform:
            translateY(7px);
    }

    to {
        opacity: 1;
        transform:
            translateY(0);
    }
}

.xt-content > * {

    animation:
        winterLetterIn
        .55s
        ease-out
        both;
}

.xt-content > *:nth-child(2) {
    animation-delay: .08s;
}

.xt-content > *:nth-child(3) {
    animation-delay: .16s;
}

.xt-content > *:nth-child(4) {
    animation-delay: .24s;
}

.xt-content > *:nth-child(5) {
    animation-delay: .32s;
}


/* =========================================================
   微弱雪光
   ========================================================= */

@keyframes snowDust {

    0%,100% {
        opacity: .18;
    }

    50% {
        opacity: .4;
    }
}

.xt-root::after {

    content:
        "·   ˚   ·      ˚   ·   ˚";

    position: absolute;

    z-index: 1;

    top: 7px;

    right: 12px;

    color:
        rgba(113,137,149,.32);

    font-size: 12px;

    letter-spacing: 6px;

    pointer-events: none;

    animation:
        snowDust
        4s
        ease-in-out
        infinite;
}

value.layout:
@card
  @text ticketTitle
  @text date
  @text departure
  @text destination
  @text passenger
@endcard

@section LETTER
  body

@text ending

@text signature

@footer WINTER MAIL · EXPRESS POST

