/* ==========================================================
   Ⅳ · 碎纸心声
   撕碎的私人记录 / 情绪碎片
   ========================================================== */

.xt-root {
    --xt-bg: #eee9df;
    --xt-text: #272421;
    --xt-text-sub: #777069;
    --xt-text-muted: #aaa29a;
