    --xt-radius: 2px;
    --xt-radius-sm: 1px;

    --xt-font: Georgia, "Songti SC", "Noto Serif SC", serif;

    --xt-shadow-sm:
        0 2px 5px rgba(45, 35, 30, 0.08);

    --xt-shadow-md:
        3px 7px 18px rgba(45, 35, 30, 0.13);

    background:
        linear-gradient(
            rgba(255,255,255,0.25),
            rgba(255,255,255,0.25)
        ),
        #eee9df;

    color: var(--xt-text);

    padding: 18px 14px 16px;

    position: relative;

    overflow-x: hidden;
}


/* ==========================================================
   顶部日期
   ========================================================== */

.xt-text-date {
    font-family: Georgia, "Songti SC", serif;

    font-size: 10px;
    letter-spacing: 2px;

    color: #9b9188;

    text-align: right;

    margin-bottom: 2px;

    transform: rotate(-1deg);
}


/* ==========================================================
   名字
   ========================================================== */

.xt-text-signature {
    font-family: Georgia, "Songti SC", serif;

    font-size: 12px;

    color: #665d58;

    margin-bottom: 15px;

    transform: rotate(1deg);
}


/* ==========================================================
   碎纸片
   ========================================================== */

.xt-card {
    position: relative;

    margin: 12px 4px;

    padding: 18px 17px;

    background:
        linear-gradient(
            90deg,
            rgba(80,60,40,0.025) 1px,
            transparent 1px
        ),
        #faf8f2;

    background-size: 8px 100%;

    border: none;

    border-radius: 1px;

    box-shadow:
        2px 4px 10px rgba(45,35,30,0.10);

    transition:
        transform 0.35s ease,
        box-shadow 0.35s ease;
}


/* 第一张 */

.xt-card:nth-of-type(3) {
    transform: rotate(-1.3deg);
}

/* 第二张 */

.xt-card:nth-of-type(4) {
    transform: rotate(1.7deg);

    margin-left: 10px;
    margin-right: 0;
}

/* 第三张 */

.xt-card:nth-of-type(5) {
    transform: rotate(-0.7deg);

    margin-left: 1px;
}

/* 第四张 */

.xt-card:nth-of-type(6) {
    transform: rotate(1.2deg);

    margin-left: 8px;
}


/* ==========================================================
   碎纸边缘
   ========================================================== */

.xt-card::before {
    content: "";

    position: absolute;

    left: 0;
    right: 0;
    top: -3px;

    height: 6px;

    background:
        repeating-linear-gradient(
            90deg,
            transparent 0px,
            transparent 5px,
            rgba(60,45,35,0.10) 6px,
            transparent 7px
        );

    opacity: 0.5;
}


/* ==========================================================
   碎片文字
   ========================================================== */

.xt-text {
    display: block;

    font-family:
        Georgia,
        "Songti SC",
        "Noto Serif SC",
        serif;

    font-size: 15px;

    line-height: 1.9;

    color: #302b28;

    margin: 4px 0;

    white-space: normal;

    overflow-wrap: anywhere;

    word-break: break-word;
}


/* 每一句稍微有一点自己的状态 */

.xt-text-fragment1 {
    transform: rotate(-0.3deg);
}

.xt-text-fragment2 {
    color: #77706a;

    transform: translateX(7px);
}

.xt-text-fragment3 {
    font-size: 16px;

    transform: rotate(0.5deg);
}

.xt-text-fragment4 {
    font-size: 12px;

    color: #99908a;

    margin-top: 13px;

    transform: rotate(-1deg);
}

.xt-text-fragment5 {
    font-size: 17px;

    font-weight: 600;

    transform: translateX(-2px);
}

.xt-text-fragment6 {
    color: #655d58;

    transform: translateX(9px);
}

.xt-text-fragment7 {
    color: #514944;

    transform: rotate(-0.8deg);
}

.xt-text-fragment8 {
    color: #aaa19a;

    font-size: 11px;

    letter-spacing: 2px;

    margin-top: 15px;
}


/* ==========================================================
   手写划线效果
   ========================================================== */

.xt-text-fragment5 {
    position: relative;
}


/* 模拟被划掉 */

.xt-text-fragment5::after {
    content: "";

    position: absolute;

    left: -3px;
    right: -3px;

    top: 52%;

    height: 1px;

    background: rgba(75,55,48,0.75);

    transform:
        rotate(-2deg)
        scaleX(0.98);

    transform-origin: center;
}


/* 第二道更短的划痕 */

.xt-text-fragment7::after {
    content: "";

    position: absolute;

    left: 0;
    right: 18%;

    top: 54%;

    height: 1px;

    background: rgba(75,55,48,0.55);

    transform: rotate(1.5deg);
}


/* ==========================================================
   让部分文字像被重新写过
   ========================================================== */

.xt-text-fragment3::before {
    content: "";

    position: absolute;

    width: 30px;
    height: 1px;

    background: rgba(90,70,60,0.18);

    right: 5px;
    top: 4px;

    transform: rotate(-4deg);
}


/* ==========================================================
   底部
   ========================================================== */

.xt-footer {
    margin-top: 18px;

    padding-top: 8px;

    border-top:
        1px solid
        rgba(70,55,45,0.12);

    color: #aaa19a;

    font-family:
        Georgia,
        serif;

    font-size: 8px;

    letter-spacing: 3px;

    text-align: center;
}


/* ==========================================================
   入场动画
   ========================================================== */

@keyframes tornPaperIn {

    from {
        opacity: 0;

        transform:
            translateY(12px)
            rotate(-3deg);
    }

    to {
        opacity: 1;
    }

}

.xt-card {
    animation:
        tornPaperIn
        0.55s
        ease-out
        both;
}

.xt-card:nth-of-type(4) {
    animation-delay: 0.08s;
}

.xt-card:nth-of-type(5) {
    animation-delay: 0.16s;
}

.xt-card:nth-of-type(6) {
    animation-delay: 0.24s;
}


/* ==========================================================
   轻微悬浮
   ========================================================== */

.xt-card:hover {
    transform:
        translateY(-2px)
        rotate(0deg);

    box-shadow:
        4px 9px 22px rgba(45,35,30,0.16);
}


/* ==========================================================
   防止内容撑爆
   ========================================================== */

.xt-content {
    width: 100%;

    max-width: 100%;

    box-sizing: border-box;

    overflow: visible;
}

.xt-card,
.xt-text {
    max-width: 100%;
    box-sizing: border-box;
}

