    transparent 100%
  );
  animation: vcr-band 8s linear infinite;
  pointer-events: none;
  z-index: 10;
}

@keyframes vcr-band {
  0% { transform: translateY(-100%); }
  100% { transform: translateY(100%); }
}

/* ── RGB 色差 ── */
@keyframes rgb-split {
  0%, 95% { text-shadow: -1px 0 #ff0000, 1px 0 #00ccff; }
  96% { text-shadow: -2px 0 #ff0000, 2px 0 #00ccff, 0 1px #00ff66; }
  97% { text-shadow: -1px 0 #ff0000, 1px 0 #00ccff; }
  98% { text-shadow: 2px 0 #ff0000, -2px 0 #00ccff, 0 -1px #00ff66; }
  100% { text-shadow: -1px 0 #ff0000, 1px 0 #00ccff; }
}

/* ── 画面抖动 ── */
@keyframes vcr-glitch {
  0%, 94% { transform: translate(0, 0); }
  95% { transform: translate(-2px, 1px); }
  96% { transform: translate(1px, -1px); }
  97% { transform: translate(-1px, 0); }
  98% { transform: translate(2px, 1px); }
  99% { transform: translate(0, -1px); }
  100% { transform: translate(0, 0); }
}

/* ── REC 闪烁 ── */
@keyframes rec-blink {
  0%, 50% { opacity: 1; }
  51%, 100% { opacity: 0; }
}

/* ── 内容区 ── */
.xt-content {
  animation: vcr-glitch 10s steps(1) infinite;
  position: relative;
}

