}

.xt-action-2 + .xt-section .xt-section-title {
    position: absolute !important; top: 45% !important; right: 12% !important; left: auto !important;
    font-family: 'Zhi Mang Xing', 'Kaiti', serif !important; font-size: 120px !important;
    color: #fff !important; z-index: 2 !important; margin: 0 !important; padding: 0 !important;
    line-height: 1 !important; text-shadow: -2px 4px 15px rgba(0,0,0,0.9) !important;
}

/* 固定文案：毛笔字 + 开经偈同款发光 */
.xt-action-2 + .xt-section::after {
    content: "心中刺，爱生恨\A怒火中烧，怨气难消";
    white-space: pre-wrap !important; writing-mode: vertical-rl !important; 
    position: absolute !important; top: 12% !important; left: 12% !important;
    font-family: 'Zhi Mang Xing', 'Kaiti', serif !important;
