    z-index: 2 !important; 
    text-shadow: 0 0 12px rgba(255, 255, 255, 0.6), 0 2px 8px #000 !important;
}


/* ================= 8. 第四页：痴 (Delusion) ================= */
.xt-action-3 + .xt-section::before {
    content: ""; position: absolute !important;
    top: 6% !important;           
    left: 0% !important;          
    width: 100% !important;        
    height: 80% !important;       
    background: url('https://nos.netease.com/ysf/dfff5136b5d4788f663ff53f06775c39.png') center/contain no-repeat !important; 
    z-index: 1 !important;
}

.xt-action-3 + .xt-section .xt-section-title {
    position: absolute !important; top: 50% !important; left: 10% !important; right: auto !important;
    font-family: 'Zhi Mang Xing', 'Kaiti', serif !important; font-size: 120px !important;
    color: #fff !important; z-index: 2 !important; margin: 0 !important; padding: 0 !important;
    line-height: 1 !important; text-shadow: -2px 4px 15px rgba(0,0,0,0.9) !important;
}

/* 固定文案：毛笔字 + 开经偈同款发光 */
.xt-action-3 + .xt-section::after {
    content: "想不通，看不破\A执迷为悟，不辨明暗";
    white-space: pre-wrap !important; writing-mode: vertical-rl !important; 
    position: absolute !important; top: 15% !important; right: 15% !important; left: auto !important;
    font-family: 'Zhi Mang Xing', 'Kaiti', serif !important;
    font-size: 24px !important;
    color: #ffffff !important; letter-spacing: 6px !important; line-height: 1.8 !important;
    z-index: 2 !important; 
    text-shadow: 0 0 12px rgba(255, 255, 255, 0.6), 0 2px 8px #000 !important;
}


/* ================= 9. 第五页：慢 (Pride) ================= */
.xt-action-4 + .xt-section::before {
    content: ""; position: absolute !important;
    top: -15% !important;          
    left: -15px !important;         
    width: 120% !important;        
    height: 100% !important;       
    background: url('https://nos.netease.com/ysf/9eb9f41bacbc82e4d1d8befc36969b3a.png') center/contain no-repeat !important; 
