    line-height: 1 !important; text-shadow: -2px 4px 15px rgba(0,0,0,0.9) !important;
}

/* 固定文案：毛笔字 + 开经偈同款发光 */
.xt-action-4 + .xt-section::after {
    content: "高筑墙，轻于人\A不知天外，己身最重";
    white-space: pre-wrap !important; 
    position: absolute !important; top: 57% !important; left: 0 !important; width: 100% !important;
    text-align: center !important; 
    font-family: 'Zhi Mang Xing', 'Kaiti', serif !important;
    font-size: 22px !important;
