    z-index: 2 !important; 
    text-shadow: 0 0 12px rgba(255, 255, 255, 0.6), 0 2px 8px #000 !important;
}


/* ================= 10. 第六页：疑 (Doubt) ================= */
.xt-action-5 + .xt-section::before {
    content: ""; position: absolute !important;
    top: 0% !important; 
    left: -10% !important;           
    width: 120% !important;         
    height: 80% !important;        
    background: url('https://nos.netease.com/ysf/e46dedeb142c9dc943fc3697d957aa3b.png') center/contain no-repeat !important; 
    z-index: 1 !important;
}

.xt-action-5 + .xt-section .xt-section-title {
    position: absolute !important; top: 50% !important; left: 8% !important; right: auto !important;
    font-family: 'Zhi Mang Xing', 'Kaiti', serif !important; font-size: 120px !important;
    color: #fff !important; z-index: 2 !important; margin: 0 !important; padding: 0 !important;
    line-height: 1 !important; text-shadow: -2px 4px 15px rgba(0,0,0,0.9) !important;
}

/* 固定文案：毛笔字 + 开经偈同款发光 */
.xt-action-5 + .xt-section::after {
    content: "心如摆，信如沙\A暗夜行路，自缚作茧";
    white-space: pre-wrap !important; writing-mode: vertical-rl !important; 
    position: absolute !important; top: 20% !important; right: 15% !important; left: auto !important;
    font-family: 'Zhi Mang Xing', 'Kaiti', serif !important;
    font-size: 24px !important;
    color: #ffffff !important; letter-spacing: 6px !important; line-height: 1.8 !important;
    z-index: 2 !important; 
    text-shadow: 0 0 12px rgba(255, 255, 255, 0.6), 0 2px 8px #000 !important;
}


/* ================= 11. 共用的动态内心独白样式 ================= */
.xt-section-body {
    position: absolute !important; top: 70% !important; left: 10% !important; width: 80% !important;
    text-align: center !important; font-family: var(--xt-font) !important; font-size: 18px !important;
    color: #fff !important; line-height: 1.8 !important; letter-spacing: 2px !important;
    z-index: 2 !important; background: transparent !important; border: none !important;
    padding: 0 !important; margin: 0 !important;
    text-shadow: 0 2px 10px #000, 0 0 10px #000, 0 0 5px #000 !important;
}
.xt-section-body::before { content: "“"; font-family: serif; margin-right: 4px; }
.xt-section-body::after { content: "”"; font-family: serif; margin-left: 4px; }

