/* 引入复古宋体(背景) 和 毛笔行书(大字与固定文字) */
@import url('https://fonts.googleapis.com/css2?family=Noto+Serif+SC:wght@400;700;900&family=Zhi+Mang+Xing&display=swap');

/* ================= 1. 卡片基础重塑 ================= */
.xt-root {
    --xt-bg: #050505;
    --xt-text: #e8c4c4;
    --xt-font: "Songti SC", "STSong", "SimSun", "Noto Serif SC", serif;
    aspect-ratio: 3 / 4 !important;
    height: 75vh !important;
    max-height: 800px !important;
    border-radius: 2px !important;
    padding: 0 !important;
    overflow: hidden !important;
    position: relative;
    border: 1px solid #1a1a1a !important;
    box-shadow: 0 20px 50px rgba(0,0,0,0.9) !important;
    background: var(--xt-bg) !important;
}

.xt-section { display: none !important; }

/* ================= 2. 第一页：主标题 (左下角横排) ================= */
.xt-text-mainQuote, .xt-text-subQuote {
    position: absolute !important;
    z-index: 10 !important;
    color: #fff !important; 
    font-family: 'Zhi Mang Xing', 'Kaiti', serif !important; 
