    transition: all 1s ease !important;
}

.xt-text-mainQuote {
    top: 65% !important; 
    left: 10% !important;
}

.xt-text-subQuote {
    top: calc(65% + 60px) !important;  
    left: 10% !important;
}

/* ================= 2.5 右上角开经偈 ================= */
.xt-badge {
    display: block !important;
    position: absolute !important;
    top: 20% !important;
    right: 8% !important;
    width: auto !important;
    height: auto !important;
    background: transparent !important;
    border: none !important;
    padding: 0 !important;
    margin: 0 !important;
    z-index: 30 !important;
    pointer-events: none !important;
    transition: all 1s ease !important;
    writing-mode: vertical-rl !important;
}

.xt-badge::before {
    content: "无上甚深微妙法\A百千万劫难遭遇\A我今见闻得受持\A愿解如来真实义" !important;
    white-space: pre !important;              
    writing-mode: vertical-rl !important;     
    display: block !important;
    font-family: 'Zhi Mang Xing', 'Kaiti', serif !important;
    font-size: 26px !important;
    color: #ffffff !important;
    letter-spacing: 6px !important;
    line-height: 1.5 !important;              
    text-shadow: 0 0 12px rgba(255, 255, 255, 0.6), 0 2px 8px #000 !important;
}

.xt-badge-value, .xt-badge-suffix { 
    display: none !important; 
    font-size: 0 !important;
}

/* ================= 3. 全局背景：丝滑文字流 (稳定物理遮挡版) ================= */
:root {
    --sutra-text: "觀自在菩薩行深般若波羅蜜多時照見五蘊皆空度一切苦厄舍利子色不異空空不異色色即是空空即是色受想行識亦復如是舍利子是諸法空相不生不滅不垢不淨不增不減是故空中無色無受想行識無眼耳鼻舌身意無色聲香味觸法無眼界乃至無意識界無無明亦無無明盡乃至無老死亦無老死盡無苦集滅道無智亦無得以無所得故菩提薩埵依般若波羅蜜多故心無掛礙無掛礙故無有恐怖遠離顛倒夢想究竟涅槃三世諸佛依般若波羅蜜多故得阿耨多羅三藐三菩提故知般若波羅蜜多是大神咒是大明咒是無上咒是無等等咒能除一切苦真實不虛故說般若波羅蜜多咒即說咒曰揭諦揭諦波羅揭諦波羅僧揭谛菩提薩婆訶觀自在菩薩行深般若波羅蜜多時照見五蘊皆空度一切苦厄舍利子色不異空空不異色色即是空空即是色受想行識亦復如是舍利子是諸法空相不生不滅不垢不淨不增不減是故空中無色無受想行識無眼耳鼻舌身意無色聲香味觸法無眼界乃至無意識界無無明亦無無明盡乃至無老死亦無老死尽無苦集滅道無智亦無得以無所得故菩提薩埵依般若波羅蜜多故心無掛礙無掛礙故無有恐怖遠離顛倒夢想究竟涅槃三世諸佛依般若波羅蜜多故得阿耨多羅三藐三菩提故知般若波羅蜜多是大神咒是大明咒是無上咒是無等等咒能除一切苦真實不虛故說般若波羅蜜多咒即說咒曰揭諦揭諦波羅揭諦波羅僧揭谛菩提薩婆訶";
}

@keyframes scroll-down {
    0% { transform: translateY(-50%) translateZ(0); }
    100% { transform: translateY(0) translateZ(0); }
}

/* 区域 ①：左侧红框位置的文字块 */
.xt-content::before {
    content: var(--sutra-text);
    position: absolute; top: 0; left: 10%; width: 45%; height: 200%;
    writing-mode: vertical-rl; font-family: var(--xt-font);
    color: rgba(255, 255, 255, 0.25); font-size: 14px;
    letter-spacing: 4px; line-height: 2.2; z-index: 1;
    pointer-events: none; animation: scroll-down 40s linear infinite; will-change: transform;
}

/* 区域 ②：最右侧的一列文字流 */
.xt-root::after {
    content: var(--sutra-text);
    position: absolute; top: 0; right: 8%; width: 1.2em; height: 200%;
    writing-mode: vertical-rl; font-family: var(--xt-font);
    color: rgba(255, 255, 255, 0.15); font-size: 14px;
    letter-spacing: 6px; line-height: 2; z-index: 1;
    pointer-events: none; animation: scroll-down 30s linear infinite; will-change: transform;
}

/* 物理遮挡层：切断左侧文字流的上半部 */
.xt-content::after {
    content: ""; position: absolute; top: 0; left: 0; width: 60%; height: 50%;
    background: #050505; z-index: 2; pointer-events: none; box-shadow: 0 20px 20px #050505;
}

/* ================= 3.5 第一页：佛手插图 ================= */
.xt-divider {
    position: absolute !important;
    top: -8% !important; 
    left: -40% !important; 
    width: 180% !important; 
    height: 140% !important;
    background: url('https://nos.netease.com/ysf/8a28eb544454c0d1ed46d5eaaadec009.png') center/contain no-repeat !important;
    border: none !important;
    margin: 0 !important;
    z-index: 3 !important; 
    pointer-events: none !important;
    transition: all 1s ease !important;
}


/* ================= 4. 翻页导航系统 (全屏隐形左右分屏翻页) ================= */
.xt-action-1, .xt-action-2, .xt-action-3, .xt-action-4, .xt-action-5 { 
    display: none !important; 
    border: none !important;
    background: transparent !important;
    color: transparent !important;
    font-size: 0 !important;
    margin: 0 !important;
    padding: 0 !important;
    opacity: 0 !important;
    cursor: pointer !important;
    -webkit-tap-highlight-color: transparent !important;
}
.xt-action-1::after, .xt-action-2::after, .xt-action-3::after, .xt-action-4::after, .xt-action-5::after { 
    content: none !important; 
}

/* 【状态0：封面】全屏点击任意位置 ➔ 进入“贪” */
.xt-action-1 {
    display: block !important;
    position: absolute !important;
    inset: 0 !important;
    width: 100% !important;
    height: 100% !important;
    z-index: 50 !important;
}

/* 【状态1：贪】 */
#xt-t1:checked ~ .xt-content .xt-action-1 {
    display: block !important;
    top: 0 !important; bottom: 0 !important; left: 0 !important; right: auto !important;
    width: 50% !important; height: 100% !important;
    z-index: 100 !important;
}

#xt-t1:checked ~ .xt-content .xt-action-2 {
    display: block !important;
    position: absolute !important;
    top: 0 !important; bottom: 0 !important; right: 0 !important; left: auto !important;
    width: 50% !important; height: 100% !important;
    z-index: 100 !important;
}

/* 【状态2：嗔】 */
#xt-t2:checked ~ .xt-content .xt-action-1 { display: none !important; }
#xt-t2:checked ~ .xt-content .xt-action-2 {
    left: 0 !important; right: auto !important;
    width: 50% !important; height: 100% !important;
}
#xt-t2:checked ~ .xt-content .xt-action-3 {
    display: block !important;
    position: absolute !important;
    top: 0 !important; bottom: 0 !important; right: 0 !important; left: auto !important;
    width: 50% !important; height: 100% !important;
    z-index: 100 !important;
}

/* 【状态3：痴】 */
#xt-t3:checked ~ .xt-content .xt-action-2 { display: none !important; }
#xt-t3:checked ~ .xt-content .xt-action-3 {
    left: 0 !important; right: auto !important;
    width: 50% !important; height: 100% !important;
}
#xt-t3:checked ~ .xt-content .xt-action-4 {
    display: block !important;
    position: absolute !important;
    top: 0 !important; bottom: 0 !important; right: 0 !important; left: auto !important;
    width: 50% !important; height: 100% !important;
    z-index: 100 !important;
}

/* 【状态4：慢】 */
#xt-t4:checked ~ .xt-content .xt-action-3 { display: none !important; }
#xt-t4:checked ~ .xt-content .xt-action-4 {
    left: 0 !important; right: auto !important;
    width: 50% !important; height: 100% !important;
}
#xt-t4:checked ~ .xt-content .xt-action-5 {
    display: block !important;
    position: absolute !important;
    top: 0 !important; bottom: 0 !important; right: 0 !important; left: auto !important;
    width: 50% !important; height: 100% !important;
    z-index: 100 !important;
}

/* 【状态5：疑】(终章：只能往回退) */
#xt-t5:checked ~ .xt-content .xt-action-4 { display: none !important; }
#xt-t5:checked ~ .xt-content .xt-action-5 {
    left: 0 !important; right: auto !important;
    width: 50% !important; height: 100% !important;
}


/* ================= 5. 页面显隐与转场动画 ================= */
#xt-t1:checked ~ .xt-content .xt-text-mainQuote,
#xt-t1:checked ~ .xt-content .xt-text-subQuote,
#xt-t1:checked ~ .xt-content .xt-divider,
#xt-t1:checked ~ .xt-content .xt-badge {
    opacity: 0 !important; transform: scale(1.05) translateY(-20px) !important; pointer-events: none;
}

/* 核心修复：把所有 .xt-section 的 z-index 提升到 200 (压过翻页的100) */
/* 并加上 pointer-events: none，让空白处点击能穿透下去翻页 */
#xt-t1:checked ~ .xt-content .xt-action-1 + .xt-section {
    display: block !important; position: absolute !important; inset: 0 !important;
    background: transparent !important; 
    z-index: 200 !important; 
    pointer-events: none !important; 
    animation: fadeIn 1.5s forwards; opacity: 0;
}
#xt-t2:checked ~ .xt-content .xt-action-1 + .xt-section { display: none !important; }

#xt-t2:checked ~ .xt-content .xt-action-2 + .xt-section {
    display: block !important; position: absolute !important; inset: 0 !important;
    background: transparent !important; 
    z-index: 200 !important; 
    pointer-events: none !important; 
    animation: fadeIn 1.5s forwards; opacity: 0;
}
#xt-t3:checked ~ .xt-content .xt-action-2 + .xt-section { display: none !important; }

#xt-t3:checked ~ .xt-content .xt-action-3 + .xt-section {
    display: block !important; position: absolute !important; inset: 0 !important;
    background: transparent !important; 
    z-index: 200 !important; 
    pointer-events: none !important; 
    animation: fadeIn 1.5s forwards; opacity: 0;
}
#xt-t4:checked ~ .xt-content .xt-action-3 + .xt-section { display: none !important; }

#xt-t4:checked ~ .xt-content .xt-action-4 + .xt-section {
    display: block !important; position: absolute !important; inset: 0 !important;
    background: transparent !important; 
    z-index: 200 !important; 
    pointer-events: none !important; 
    animation: fadeIn 1.5s forwards; opacity: 0;
}
#xt-t5:checked ~ .xt-content .xt-action-4 + .xt-section { display: none !important; }

#xt-t5:checked ~ .xt-content .xt-action-5 + .xt-section {
    display: block !important; position: absolute !important; inset: 0 !important;
    background: transparent !important; 
    z-index: 200 !important; 
    pointer-events: none !important; 
    animation: fadeIn 1.5s forwards; opacity: 0;
}

/* ================= 6. 第二页：贪 (Greed) ================= */
.xt-action-1 + .xt-section::before {
    content: ""; position: absolute !important;
    top: 10% !important;          
    right: 5% !important;         
    width: 80% !important;        
    height: 60% !important;       
    background: url('https://nos.netease.com/ysf/27557eec670feff7153c5fe747853f09.png') center/contain no-repeat !important; 
    z-index: 1 !important;
}

.xt-action-1 + .xt-section .xt-section-title {
    position: absolute !important; 
    top: 30% !important;          
    left: 5% !important;         
    font-family: 'Zhi Mang Xing', 'Kaiti', serif !important; 
    font-size: 120px !important;
    color: #fff !important; 
    z-index: 2 !important; 
    margin: 0 !important; padding: 0 !important;
    line-height: 1 !important; 
    text-shadow: -2px 4px 15px rgba(0,0,0,0.9) !important;
}

/* 固定文案：毛笔字 + 开经偈同款发光 */
.xt-action-1 + .xt-section::after {
    content: "放不下，离不开\A求而不得，得而复失"; 
    white-space: pre-wrap !important;            
    position: absolute !important; 
    top: 57% !important;                        
    left: 0 !important; 
    width: 100% !important;
    text-align: center !important; 
    font-family: 'Zhi Mang Xing', 'Kaiti', serif !important;
    font-size: 22px !important;                 
    color: #ffffff !important; 
    letter-spacing: 4px !important;              
    line-height: 1.6 !important;                 
    z-index: 2 !important;
    text-shadow: 0 0 12px rgba(255, 255, 255, 0.6), 0 2px 8px #000 !important;
}


/* ================= 7. 第三页：嗔 (Anger) ================= */
.xt-action-2 + .xt-section::before {
    content: ""; position: absolute !important;
    top: 12% !important;          
    right: 8% !important;         
    width: 100% !important;        
    height: 60% !important;       
    background: url('https://nos.netease.com/ysf/862abb21bdd990fedf6915046303d575.png') center/contain no-repeat !important; 
    z-index: 1 !important;
}

.xt-action-2 + .xt-section .xt-section-title {
    position: absolute !important; top: 45% !important; right: 12% !important; left: auto !important;
    font-family: 'Zhi Mang Xing', 'Kaiti', serif !important; font-size: 120px !important;
    color: #fff !important; z-index: 2 !important; margin: 0 !important; padding: 0 !important;
    line-height: 1 !important; text-shadow: -2px 4px 15px rgba(0,0,0,0.9) !important;
}

/* 固定文案：毛笔字 + 开经偈同款发光 */
.xt-action-2 + .xt-section::after {
    content: "心中刺，爱生恨\A怒火中烧，怨气难消";
    white-space: pre-wrap !important; writing-mode: vertical-rl !important; 
    position: absolute !important; top: 12% !important; left: 12% !important;
    font-family: 'Zhi Mang Xing', 'Kaiti', serif !important;
    font-size: 24px !important;
    color: #ffffff !important; letter-spacing: 6px !important; line-height: 1.8 !important;
    z-index: 2 !important; 
    text-shadow: 0 0 12px rgba(255, 255, 255, 0.6), 0 2px 8px #000 !important;
}


/* ================= 8. 第四页：痴 (Delusion) ================= */
.xt-action-3 + .xt-section::before {
    content: ""; position: absolute !important;
    top: 6% !important;           
    left: 0% !important;          
    width: 100% !important;        
    height: 80% !important;       
    background: url('https://nos.netease.com/ysf/dfff5136b5d4788f663ff53f06775c39.png') center/contain no-repeat !important; 
    z-index: 1 !important;
}

.xt-action-3 + .xt-section .xt-section-title {
    position: absolute !important; top: 50% !important; left: 10% !important; right: auto !important;
    font-family: 'Zhi Mang Xing', 'Kaiti', serif !important; font-size: 120px !important;
    color: #fff !important; z-index: 2 !important; margin: 0 !important; padding: 0 !important;
    line-height: 1 !important; text-shadow: -2px 4px 15px rgba(0,0,0,0.9) !important;
}

/* 固定文案：毛笔字 + 开经偈同款发光 */
.xt-action-3 + .xt-section::after {
    content: "想不通，看不破\A执迷为悟，不辨明暗";
    white-space: pre-wrap !important; writing-mode: vertical-rl !important; 
    position: absolute !important; top: 15% !important; right: 15% !important; left: auto !important;
    font-family: 'Zhi Mang Xing', 'Kaiti', serif !important;
    font-size: 24px !important;
    color: #ffffff !important; letter-spacing: 6px !important; line-height: 1.8 !important;
    z-index: 2 !important; 
    text-shadow: 0 0 12px rgba(255, 255, 255, 0.6), 0 2px 8px #000 !important;
}


/* ================= 9. 第五页：慢 (Pride) ================= */
.xt-action-4 + .xt-section::before {
    content: ""; position: absolute !important;
    top: -15% !important;          
    left: -15px !important;         
    width: 120% !important;        
    height: 100% !important;       
    background: url('https://nos.netease.com/ysf/9eb9f41bacbc82e4d1d8befc36969b3a.png') center/contain no-repeat !important; 
    z-index: 1 !important;
}

.xt-action-4 + .xt-section .xt-section-title {
    position: absolute !important; top: 22% !important; right: 12% !important; left: auto !important;
    font-family: 'Zhi Mang Xing', 'Kaiti', serif !important; font-size: 120px !important;
    color: #fff !important; z-index: 2 !important; margin: 0 !important; padding: 0 !important;
    line-height: 1 !important; text-shadow: -2px 4px 15px rgba(0,0,0,0.9) !important;
}

/* 固定文案：毛笔字 + 开经偈同款发光 */
.xt-action-4 + .xt-section::after {
    content: "高筑墙，轻于人\A不知天外，己身最重";
    white-space: pre-wrap !important; 
    position: absolute !important; top: 57% !important; left: 0 !important; width: 100% !important;
    text-align: center !important; 
    font-family: 'Zhi Mang Xing', 'Kaiti', serif !important;
    font-size: 22px !important;
    color: #ffffff !important; letter-spacing: 4px !important; line-height: 1.6 !important;
    z-index: 2 !important; 
    text-shadow: 0 0 12px rgba(255, 255, 255, 0.6), 0 2px 8px #000 !important;
}


/* ================= 10. 第六页：疑 (Doubt) ================= */
.xt-action-5 + .xt-section::before {
    content: ""; position: absolute !important;
    top: 0% !important; 
    left: -10% !important;           
    width: 120% !important;         
    height: 80% !important;        
    background: url('https://nos.netease.com/ysf/e46dedeb142c9dc943fc3697d957aa3b.png') center/contain no-repeat !important; 
    z-index: 1 !important;
}

.xt-action-5 + .xt-section .xt-section-title {
    position: absolute !important; top: 50% !important; left: 8% !important; right: auto !important;
    font-family: 'Zhi Mang Xing', 'Kaiti', serif !important; font-size: 120px !important;
    color: #fff !important; z-index: 2 !important; margin: 0 !important; padding: 0 !important;
    line-height: 1 !important; text-shadow: -2px 4px 15px rgba(0,0,0,0.9) !important;
}

/* 固定文案：毛笔字 + 开经偈同款发光 */
.xt-action-5 + .xt-section::after {
    content: "心如摆，信如沙\A暗夜行路，自缚作茧";
    white-space: pre-wrap !important; writing-mode: vertical-rl !important; 
    position: absolute !important; top: 20% !important; right: 15% !important; left: auto !important;
    font-family: 'Zhi Mang Xing', 'Kaiti', serif !important;
    font-size: 24px !important;
    color: #ffffff !important; letter-spacing: 6px !important; line-height: 1.8 !important;
    z-index: 2 !important; 
    text-shadow: 0 0 12px rgba(255, 255, 255, 0.6), 0 2px 8px #000 !important;
}

/* ================= 11. 共用的动态内心独白样式 (完美滚动版) ================= */
.xt-section-body {
    position: absolute !important;
    top: 70% !important;              /* 绝对保留原始位置 */
    left: 8% !important;              /* 绝对保留原始边距 */
    width: 84% !important;

    /* 锁定 6 行高度 */
    height: 30% !important;         
    max-height: 30% !important;

    /* 开启原生滚动 */
    overflow-y: auto !important;
    overflow-x: hidden !important;
    -webkit-overflow-scrolling: touch !important; 
    touch-action: pan-y !important;   

    /* 核心修复：整个页面只有这里设为 auto，成为唯一能抓住手指滑动的实体！ */
    pointer-events: auto !important;  
    z-index: 300 !important;          

    /* 保持原样排版 */
    text-align: center !important;
    font-family: var(--xt-font) !important;
    font-size: 15px !important;       
    color: #f2f2f2 !important;
    line-height: 1.75 !important;      
    letter-spacing: 1.5px !important;
    background: transparent !important;
    border: none !important;
    margin: 0 !important;

    /* 底部留白，滑到底不切字 */
    padding: 0 4px 30px 4px !important;
    box-sizing: border-box !important;

    text-shadow: 
        0 2px 8px #000, 
        0 0 12px #000, 
        0 0 4px #000 !important;

    scrollbar-width: none !important;
    -ms-overflow-style: none !important;
}

/* 隐藏滚动条 */
.xt-section-body::-webkit-scrollbar {
    display: none !important;
    width: 0 !important;
    height: 0 !important;
}

.xt-section-body::before { 
    content: "“"; 
    font-family: serif; 
    margin-right: 4px;
    opacity: 0.8;
}
.xt-section-body::after { 
    content: "”"; 
    font-family: serif; 
    margin-left: 4px;
    opacity: 0.8;
}

