.xt-root {
    --xt-bg: #f7f7f5;
    --xt-text: #2a2622;
    --xt-text-sub: #5f5b56;
    --xt-text-muted: #9a968f;
    --xt-accent: #2a2622;
    --xt-border: #e2e1dc;
    --xt-radius: 8px;
    --xt-radius-sm: 4px;
    --xt-font: "KingHwa_OldSong", "Songti SC", serif;
    --my-avatar: url("https://s3.bmp.ovh/2026/09/28/ET4f2e7j.jpg");
    --author-avatar: url("https://s3.bmp.ovh/2026/09/28/d5IDLbDN.jpg");
    --reader1: url("https://s3.bmp.ovh/2026/09/28/WmlBKN6S.jpg");
    --reader2: url("https://s3.bmp.ovh/2026/09/28/IPjFsOHF.jpg");
    --reader3: url("https://s3.bmp.ovh/2026/09/28/WT1MuALL.jpg");
    --sea: url("https://s3.bmp.ovh/2026/09/28/5KTkAfQA.jpg");
    background: #f7f7f5;
    border-radius: 8px !important;
    padding: 0 !important;
    box-shadow: 0 6px 24px rgba(20, 30, 45, 0.14);
    max-height: 70vh;
    overflow-x: hidden;
    overflow-y: auto;
    -webkit-overflow-scrolling: touch;
    overscroll-behavior: contain;
    scrollbar-width: none;
}

.xt-root::-webkit-scrollbar {
    display: none;
}

/* ===== 翻页容器：三列 = 三页，横向吸附 ===== */
.xt-content {
    display: grid !important;
    grid-template-columns: repeat(3, 100%);
    grid-template-rows: repeat(6, auto) 1fr;
    padding: 0 !important;
    gap: 0 !important;
    overflow-x: auto;
    overflow-y: hidden;
    scroll-snap-type: x mandatory;
    -webkit-overflow-scrolling: touch;
    overscroll-behavior-x: contain;
    scrollbar-width: none;
}

.xt-content::-webkit-scrollbar {
    display: none;
}

.xt-content > * {
    min-width: 0;
    box-sizing: border-box;
}

.xt-row {
    margin: 0 !important;
    gap: 0 !important;
    border-radius: 0 !important;
    box-sizing: border-box;
}

/* 吸附点 */
.xt-content > .xt-row:first-child,
.xt-footer + .xt-row,
.xt-footer + .xt-row + .xt-row {
    scroll-snap-align: start;
    scroll-snap-stop: always;
}

/* ===== 第一页：海面封面 ===== */
.xt-content > .xt-row:first-child {
    grid-column: 1;
    grid-row: 1;
    position: relative;
    height: 260px;
    padding: 36px 32px !important;
    display: flex !important;
    flex-direction: row !important;
    justify-content: flex-start !important;
    align-items: flex-start !important;
    background:
        linear-gradient(180deg, rgba(30,40,55,0.10) 0%, rgba(0,0,0,0) 45%, rgba(20,30,45,0.22) 100%),
        linear-gradient(rgba(120,130,140,0.14), rgba(120,130,140,0.14)),
        var(--sea) center 65% / cover no-repeat,
        linear-gradient(180deg,
            #2f5b93 0%,
            #4f7bb2 25%,
            #9fb6d3 46%,
            #c4cfdd 54%,
            #6f8fb8 58%,
            #5a7fab 72%,
            #34598a 100%);
}

.xt-content > .xt-row:first-child > * {
    flex: none !important;
    width: auto !important;
    text-align: left !important;
}

.xt-content > .xt-row:first-child .xt-text-bookTitle,
.xt-content > .xt-row:first-child .xt-text-charName {
