    position: static;
    flex: none;
    height: 28px;
}

.xt-footer + .xt-row + .xt-row > * {
    flex: none !important;
    width: auto !important;
    text-align: left !important;
    margin: 0 !important;
    padding: 0 !important;
    background: none !important;
    border: none !important;
