    font-size: 12px;
    letter-spacing: 1px;
    color: #a8a49d;
}

.xt-footer + .xt-row + .xt-row > .xt-text-quoteFrom::before {
    content: "——";
    margin-right: 4px;
    font-family: -apple-system, "PingFang SC", sans-serif;
    letter-spacing: 0;
}

/* 昵称行 + 头像 */
.xt-footer + .xt-row + .xt-row > .xt-text-c1Name,
.xt-footer + .xt-row + .xt-row > .xt-text-c2Name,
.xt-footer + .xt-row + .xt-row > .xt-text-charName,
.xt-footer + .xt-row + .xt-row > .xt-text-rName {
