.xt-footer + .xt-row + .xt-row > .xt-text-c1Name::before,
.xt-footer + .xt-row + .xt-row > .xt-text-c2Name::before,
.xt-footer + .xt-row + .xt-row > .xt-text-charName::before,
.xt-footer + .xt-row + .xt-row > .xt-text-rName::before {
    content: "";
    position: absolute;
    left: 0;
    top: 16px;
