value.customCss:
/* ===== 日记 · 主题 CSS ===== */

@import url('https://fonts.googleapis.com/css2?family=Noto+Serif+SC:wght@300;400&display=swap');

/* ---------- 根容器 ---------- */
.xt-root {
  --xt-bg: #ffffff;
  --xt-text: #333333;
  --xt-text-sub: #666666;
  --xt-text-muted: #999999;
  --xt-accent: #555555;
  --xt-accent-bg: rgba(85, 85, 85, 0.06);
  --xt-border: #eeeeee;
  --xt-radius: 18px;
  --xt-radius-sm: 9px;
  --xt-font: 'Noto Serif SC', "Songti SC", "STSong", Georgia, serif;
  --xt-anim-duration: 0.5s;
  --xt-anim-easing: cubic-bezier(0.25, 0.8, 0.35, 1);
  --xt-shadow-md: 0 6px 24px rgba(0, 0, 0, 0.04);
  --xt-glow-color: rgba(85, 85, 85, 0.15);

  position: relative;
  background: var(--xt-bg);
  box-shadow: var(--xt-shadow-md);
  padding-top: 46px !important;
  overflow: hidden;
}

.xt-root::after {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 1;
  background-image: repeating-linear-gradient(
    0deg,
    rgba(0, 0, 0, 0.008) 0 1px,
    transparent 1px 3px
  );
}

/* ---------- 顶部栏 ---------- */
.xt-root::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 34px;
  z-index: 6;
  background: #fafafa;
  border-bottom: 1px solid #eeeeee;
  pointer-events: none;
}

/* ---------- 顶栏英文论文标题 ---------- */
.xt-text-reflectionTitleEN {
  position: absolute !important;
  top: -46px !important;
  left: 0 !important;
  right: 0 !important;
  width: 100% !important;
  height: 46px !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  z-index: 10 !important;
  font-family: "Times New Roman", Georgia, "Songti SC", serif !important;
  font-size: 12px !important;
  font-weight: 500 !important;
  letter-spacing: 2.5px !important;
  color: #555555 !important;
  white-space: nowrap !important;
  background: none !important;
  border: none !important;
  box-shadow: none !important;
  margin: 0 !important;
  padding: 0 !important;
  pointer-events: none !important;
  text-rendering: optimizeLegibility !important;
  font-variant: small-caps !important;
}

/* ---------- 内容层 ---------- */
.xt-content {
  position: relative;
  z-index: 20;
}

/* ---------- 左上角头像区 ---------- */
.xt-header {
  display: flex;
  flex-direction: row;
  align-items: center;
  gap: 8px;
  margin: 0 0 16px 0;
  justify-content: flex-start;
}

.xt-header .xt-avatar {
  order: 0;
  flex: none;
  width: 40px;
  height: 40px;
  border-radius: 50%;
  border: 2px solid #ffffff;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.06);
  background-size: cover;
  background-position: center;
  filter: saturate(0.85) contrast(0.98);
}

.xt-header .xt-name {
  order: 1;
  font-family: -apple-system, "PingFang SC", "Microsoft YaHei", sans-serif;
  font-size: 12px;
  font-weight: 500;
  letter-spacing: 0.4px;
  color: #333333;
  line-height: 1.4;
}

.xt-header .xt-name::before {
  content: "@";
  margin-right: 2px;
  color: #999999;
  font-weight: 400;
}

.xt-header .xt-name::after {
  content: "骤雨初晴";
  display: block;
