  background: rgba(255, 255, 255, 0.96) !important;
  border: 1px solid #2b557a !important;
}
.xt-row > *:last-child .xt-card:nth-of-type(1) .xt-card-title {
  color: #2b557a !important;
  border-bottom: 1px dotted #a0b8cc !important;
}
.xt-row > *:last-child .xt-card:nth-of-type(1) .xt-text {
  color: #1a1a1a !important;
  font-size: 9.5px !important;
  line-height: 1.4 !important;
}

/* ==========================================
   【右栏 2】脱罪借口：浅米白 + 浅橙红框
========================================== */
.xt-row > *:last-child .xt-card:nth-of-type(2) {
  background: #fffdf5 !important;
  border: 1px solid #f2c7a5 !important;
}
.xt-row > *:last-child .xt-card:nth-of-type(2) .xt-card-title {
  color: #c94b28 !important;
  border-bottom: 1px dotted #f2c7a5 !important;
}
.xt-row > *:last-child .xt-card:nth-of-type(2) .xt-text {
  color: #8a3b20 !important;
}

/* ==========================================
   【右栏 3】抓包对策：淡粉色 + 浅粉红框
========================================== */
.xt-row > *:last-child .xt-card:nth-of-type(3) {
  background: #fdf3f5 !important;
  border: 1px solid #f0ccd2 !important;
}
.xt-row > *:last-child .xt-card:nth-of-type(3) .xt-card-title {
  color: #c93236 !important;
  border-bottom: 1px dotted #f0ccd2 !important;
}
.xt-row > *:last-child .xt-card:nth-of-type(3) .xt-text {
  color: #7a2b38 !important;
}

/* ===== 底部：倒计时与进度条 ===== */
.xt-text:last-of-type {
  display: block;
  background: #f4f8f1 !important;
  border: 1px solid #bed8b2 !important;
  color: #3b5a2e !important;
  text-align: center;
  margin-top: 6px;
}

.xt-footer { display: none; }
/* 内容区整体上移，贴近顶部 */
.xt-row {
  margin-top: -30px !important;
}
/* 暗中侦测：拉高 */
.xt-row > *:first-child .xt-card:nth-of-type(3) {
  min-height: 200px !important;
}
/* 暗中侦测：整体 +1 */
.xt-row > *:first-child .xt-card:nth-of-type(3) .xt-text:nth-child(2) {
  color: #c93236 !important;
  font-weight: bold !important;
}
.xt-row > *:first-child .xt-card:nth-of-type(3) .xt-text:nth-child(2)::before { content: '' !important; }
.xt-row > *:first-child .xt-card:nth-of-type(3) .xt-text:nth-child(3)::before { content: '心率：'; font-weight: bold; }
.xt-row > *:first-child .xt-card:nth-of-type(3) .xt-text:nth-child(4)::before { content: '防线：'; font-weight: bold; }
.xt-row > *:first-child .xt-card:nth-of-type(3) .xt-text:nth-child(5)::before { content: '战况：'; font-weight: bold; }
.xt-row > *:first-child .xt-card:nth-of-type(3) .xt-text:nth-child(6)::before { content: '⚠ 状态：'; font-weight: bold; }
/* 倒计时 + 进度条：并排一行，共用一个框 */
.xt-content > .xt-text:nth-last-of-type(2),
.xt-content > .xt-text:last-of-type {
  display: inline-block !important;
  border-radius: 0 !important;
  background: transparent !important;
  font-size: 9px !important;
  padding: 2px 6px !important;
  margin: 0 !important;
  vertical-align: middle !important;
}

/* 倒计时：左边，只留右边框 */
.xt-content > .xt-text:nth-last-of-type(2) {
  border: 1px solid #bed8b2 !important;
  border-right: none !important;
  color: #3b5a2e !important;
}

/* 进度条：右边，只留左边框 */
.xt-content > .xt-text:last-of-type {
  border: 1px solid #bed8b2 !important;
  border-left: none !important;
  color: #3b5a2e !important;
}
/* 倒计时+进度条：整体拉长铺满 */
.xt-content > .xt-text:nth-last-of-type(2),
.xt-content > .xt-text:last-of-type {
  width: 50% !important;
  box-sizing: border-box !important;
  text-align: center !important;
}
/* 破防倒计时：前面加标签 */
.xt-content > .xt-text:nth-last-of-type(2)::before {
  content: '破防倒计时：';
  color: #3b5a2e;
  font-weight: bold;
  margin-right: 2px;
}
/* 进度条：文字和方块变红 */
.xt-content > .xt-text:last-of-type {
  color: #c93236 !important;
  font-weight: bold !important;
}
/* 暗中侦测底部：加"正在连接"进度点 */
.xt-row > *:first-child .xt-card:nth-of-type(3)::after {
  content: '正在连接 BuddyBuddy…… ●●●○○○';
  display: block;
  font-size: 8.5px;
  color: #2b6e1b;
  margin-top: 6px;
  padding-top: 4px;
  border-top: 1px dotted #b8dab0;
  text-align: center;
  letter-spacing: 0.5px;
}
/* 正在连接：往下移 */
.xt-row > *:first-child .xt-card:nth-of-type(3)::after {
  margin-top: 30px !important;
}
/* 傲娇军规卡：固定高度 + 超出滚动 */
.xt-row > *:first-child .xt-card:nth-of-type(2) {
  height: 60px !important;
  overflow-y: auto !important;
  overflow-x: hidden !important;
  scrollbar-width: none !important;
}
.xt-row > *:first-child .xt-card:nth-of-type(2)::-webkit-scrollbar {
  display: none !important;
}
/* 暗中侦测：flex 布局 + 内容均匀分布 + 正在连接贴底 */
.xt-row > *:first-child .xt-card:nth-of-type(3) {
  display: flex !important;
  flex-direction: column !important;
  justify-content: space-between !important;
}
.xt-row > *:first-child .xt-card:nth-of-type(3)::after {
  margin-top: auto !important;
}
/* 暗中侦测里的数据行：拉开间距 */
.xt-row > *:first-child .xt-card:nth-of-type(3) .xt-text {
  margin-bottom: 8px !important;
}

