value.customCss:
/* ============================================================
   一样的月光 · 心声配套 CSS v22（完整最终版）
   朋友圈封面头 + 板块独立细边框 + 评论每条下方细线
   头像：70×70 / 方角 / 封面右下角下移
   ============================================================ */

.xt-root {
  --xt-bg: #ffffff;
  --xt-text: #7a8296;
  --xt-text-sub: #aab2c4;
  --xt-text-muted: #c8d0de;
  --xt-accent: #8a92a6;
  --xt-accent-bg: rgba(180, 195, 225, 0.10);
  --xt-border: rgba(150, 165, 195, 0.35);
  --xt-radius: 0px;
  --xt-radius-sm: 0px;
  --xt-font: "Songti SC", "STSong", "Noto Serif SC", serif;

  --xt-anim-duration: 0.6s;
  --xt-anim-easing: ease-out;
  --xt-stagger-delay: 100ms;
  --xt-glow-color: rgba(180, 195, 225, 0.55);

  --xt-shadow-sm: 0 0 10px rgba(180, 195, 225, 0.10);
  --xt-shadow-md: 0 2px 12px rgba(180, 195, 225, 0.08);
  --xt-shadow-lg: 0 8px 32px rgba(180, 195, 225, 0.12);

  background: var(--xt-bg);
  border: 0.5px solid rgba(150, 165, 195, 0.55);
  box-shadow: var(--xt-shadow-md);
  position: relative;

  max-height: 78vh;
  overflow-y: auto;
  overflow-x: hidden;
  -webkit-overflow-scrolling: touch;

  padding: 0;
}

.xt-root::before {
  content: "";
  position: absolute;
  top: 140px;
  left: 0;
  right: 0;
  bottom: 0;
  pointer-events: none;
  background: radial-gradient(
    ellipse 130% 55% at 50% 0%,
    rgba(205, 218, 245, 0.20) 0%,
    rgba(255, 255, 255, 0) 65%
  );
  z-index: 0;
}

.xt-root * {
  background-color: transparent !important;
}
.xt-particles .xt-particle {
  background-color: #cdd8ee !important;
}

/* ============================================================
   ⭐ 头部 · 朋友圈封面
   ============================================================ */

.xt-header {
  display: block !important;
  position: relative !important;
  height: 140px !important;
  padding: 0 !important;
  margin: 0 !important;
  background:
    linear-gradient(
      180deg,
      rgba(205, 218, 245, 0.55) 0%,
      rgba(180, 195, 225, 0.30) 100%
    ),
    linear-gradient(
      135deg,
      #d4dcf0 0%,
      #e6edf9 60%,
      #f2f6fc 100%
    ) !important;
  overflow: visible !important;
  z-index: 1;
}

.xt-header::before {
  content: "☾";
  position: absolute;
  top: 16px;
  left: 26px;
  font-size: 52px;
  color: #a8b5d0;
  opacity: 0.55;
  line-height: 1;
  pointer-events: none;
}

.xt-header::after {
  content: "✦  ✦  ✦";
  position: absolute;
  top: 32px;
  right: 28px;
  color: #b8c5dd;
  font-size: 11px;
  letter-spacing: 10px;
  opacity: 0.75;
  pointer-events: none;
}

.xt-name {
  position: absolute !important;
  right: 100px !important;
  bottom: 26px !important;
  color: #ffffff !important;
  font-size: 16px !important;
  font-weight: 500 !important;
  font-style: normal !important;
  letter-spacing: 0.08em !important;
  text-shadow: 0 1px 8px rgba(90, 110, 150, 0.55) !important;
  line-height: 1.2 !important;
  z-index: 3 !important;
}
.xt-name::after {
  content: none !important;
}

/* ============================================================
   ⭐ 头像 · 70×70 / 方角 / 封面右下角下移
   ============================================================ */

.xt-header .xt-avatar,
.xt-header [class*="avatar"],
.xt-avatar {
  position: absolute !important;
  right: 20px !important;
  bottom: -34px !important;
  top: auto !important;

  width: 70px !important;
  height: 70px !important;
  min-width: 70px !important;
  min-height: 70px !important;

  border-radius: 0 !important;
  border: 1px solid rgba(150, 165, 195, 0.85) !important;
  box-shadow: 0 4px 12px rgba(150, 165, 195, 0.22) !important;
  box-sizing: border-box !important;
  display: block !important;
  visibility: visible !important;
  opacity: 1 !important;
  z-index: 9 !important;

  background-image: url("https://img-reg-ab.imagency.cn/a/269/26/6abf608c03125.jpeg") !important;
  background-size: cover !important;
  background-position: center !important;
  background-repeat: no-repeat !important;
  background-color: transparent !important;

  font-size: 0 !important;
  color: transparent !important;
  text-indent: -9999px !important;
  overflow: hidden !important;
  line-height: 0 !important;
  object-fit: cover !important;
}

.xt-header img.xt-avatar,
.xt-header img[class*="avatar"],
img.xt-avatar {
  content: url("https://img-reg-ab.imagency.cn/a/269/26/6abf608c03125.jpeg") !important;
}

.xt-header .xt-avatar > *,
.xt-header [class*="avatar"] > *,
.xt-avatar > * {
  display: none !important;
  visibility: hidden !important;
  opacity: 0 !important;
  width: 0 !important;
  height: 0 !important;
}

/* ============================================================
   ⭐ @id 行
   ============================================================ */

.xt-header + .xt-text {
  position: relative !important;
  margin: 0 !important;
  padding: 16px 18px 6px 18px !important;
  color: #aab2c4 !important;
  font-size: 12px !important;
  font-style: normal !important;
  letter-spacing: 0.05em !important;
  line-height: 1.5 !important;
  display: block !important;
  z-index: 1;
}
.xt-header + .xt-text::before {
  content: "@";
  color: #c8d0de;
  margin-right: 1px;
}
.xt-header + .xt-text::after {
  content: " · 沉浸月光之下";
  color: #b8c0d0;
  font-style: italic;
  letter-spacing: 0.08em;
}

.xt-divider {
  height: 1px !important;
  border: none !important;
  background: linear-gradient(
    to right,
    transparent 0%,
    rgba(150, 165, 195, 0.5) 25%,
    rgba(150, 165, 195, 0.5) 75%,
    transparent 100%
  ) !important;
  margin: 10px 18px 4px !important;
}

/* ============================================================
   ⭐ 板块（此刻 / 书摘 / 日记 / 单曲循环）
   ============================================================ */

.xt-section {
  margin: 12px 16px !important;
  padding: 16px 18px !important;
  background: transparent !important;
  border: 0.5px solid rgba(150, 165, 195, 0.55) !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  position: relative;
  z-index: 1;
}

.xt-section + .xt-section::before,
.xt-list + .xt-section::before {
  content: none !important;
}

.xt-section-title {
  display: flex;
  align-items: center;
  gap: 7px;
  color: #8a92a6;
  font-size: 11px;
  letter-spacing: 0.22em;
  font-weight: 500;
  font-style: normal;
  margin-bottom: 10px;
  text-transform: uppercase;
}

.xt-section-title::before {
  content: "";
  display: inline-block;
  width: 13px;
  height: 13px;
  flex-shrink: 0;
  background: currentColor;
  -webkit-mask-position: center;
          mask-position: center;
  -webkit-mask-size: contain;
          mask-size: contain;
  -webkit-mask-repeat: no-repeat;
          mask-repeat: no-repeat;
  vertical-align: -2px;
}

/* 一 · 弯月 */
.xt-section:nth-of-type(1) .xt-section-title::before {
  -webkit-mask-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='black' stroke-width='1.8' stroke-linecap='round' stroke-linejoin='round'><path d='M21 12.79A9 9 0 1 1 11.21 3 7 7 0 0 0 21 12.79z'/></svg>");
          mask-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='black' stroke-width='1.8' stroke-linecap='round' stroke-linejoin='round'><path d='M21 12.79A9 9 0 1 1 11.21 3 7 7 0 0 0 21 12.79z'/></svg>");
}
/* 二 · 书 */
.xt-section:nth-of-type(2) .xt-section-title::before {
  -webkit-mask-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='black' stroke-width='1.8' stroke-linecap='round' stroke-linejoin='round'><path d='M2 4h6a4 4 0 0 1 4 4v13a3 3 0 0 0-3-3H2z'/><path d='M22 4h-6a4 4 0 0 0-4 4v13a3 3 0 0 1 3-3h7z'/></svg>");
          mask-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='black' stroke-width='1.8' stroke-linecap='round' stroke-linejoin='round'><path d='M2 4h6a4 4 0 0 1 4 4v13a3 3 0 0 0-3-3H2z'/><path d='M22 4h-6a4 4 0 0 0-4 4v13a3 3 0 0 1 3-3h7z'/></svg>");
}
/* 三 · 笔记本 */
.xt-section:nth-of-type(3) .xt-section-title::before {
  -webkit-mask-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='black' stroke-width='1.8' stroke-linecap='round' stroke-linejoin='round'><path d='M6 3h11a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2H6z'/><path d='M6 3a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2'/><path d='M10 8h6'/><path d='M10 12h6'/><path d='M10 16h4'/></svg>");
          mask-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='black' stroke-width='1.8' stroke-linecap='round' stroke-linejoin='round'><path d='M6 3h11a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2H6z'/><path d='M6 3a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2'/><path d='M10 8h6'/><path d='M10 12h6'/><path d='M10 16h4'/></svg>");
}
/* 四 · 音符 */
.xt-section:nth-of-type(4) .xt-section-title::before {
  -webkit-mask-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='black' stroke-width='1.8' stroke-linecap='round' stroke-linejoin='round'><path d='M9 18V5l12-2v13'/><circle cx='6' cy='18' r='3'/><circle cx='18' cy='16' r='3'/></svg>");
          mask-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='black' stroke-width='1.8' stroke-linecap='round' stroke-linejoin='round'><path d='M9 18V5l12-2v13'/><circle cx='6' cy='18' r='3'/><circle cx='18' cy='16' r='3'/></svg>");
}

.xt-section-body,
.xt-section-body * {
  background: transparent !important;
  background-color: transparent !important;
  border: none !important;
  border-left: none !important;
  box-shadow: none !important;
}

.xt-section-body {
  padding: 0 !important;
  color: #7a8296;
  font-size: 13.5px;
  line-height: 1.9;
  font-style: italic;
  font-weight: 300;
  letter-spacing: 0.03em;
}

.xt-section-body > *:not(:first-child) {
  display: block;
  color: #aab2c4;
  font-size: 12px;
  font-weight: 300;
  letter-spacing: 0.08em;
  margin-top: 6px;
}

.xt-section:nth-of-type(1) .xt-section-body {
  font-size: 14px;
  line-height: 1.9;
}

.xt-section:nth-of-type(2) .xt-section-body {
  position: relative;
  padding-left: 22px !important;
  font-size: 13px;
}
.xt-section:nth-of-type(2) .xt-section-body::before {
  content: "❝";
  position: absolute;
  left: 0;
  top: -2px;
  color: #c8d0de;
  font-size: 16px;
  opacity: 0.85;
  font-style: normal;
}

.xt-section:nth-of-type(3) .xt-section-body {
  font-size: 13px !important;
  line-height: 2 !important;
  color: #8a92a6 !important;
  white-space: normal !important;
  font-style: italic !important;
  font-weight: 300 !important;
}

.xt-section:nth-of-type(4) .xt-section-body > *:first-child {
  display: block !important;
  font-size: 14px !important;
  color: #4a5266 !important;
  font-style: italic !important;
  font-weight: 400 !important;
  letter-spacing: 0.05em !important;
  line-height: 1.7 !important;
  white-space: normal !important;
}

/* ============================================================
   ⭐ 书摘来源
   ============================================================ */

.xt-text-bookSource {
  display: block !important;
  margin: -4px 16px 12px !important;
  padding: 0 34px !important;
  color: #aab2c4 !important;
  font-size: 12px !important;
  font-style: italic !important;
  font-weight: 300 !important;
  letter-spacing: 0.08em !important;
  line-height: 1.6 !important;
  text-align: right !important;
  background: transparent !important;
}

/* ============================================================
   ⭐ 单曲循环 · 歌手 + 歌名
   ============================================================ */

.xt-text-songArtist {
  display: inline-block !important;
  margin: -4px 0 0 0 !important;
  padding: 0 !important;
  color: #aab2c4 !important;
  font-size: 12px !important;
  font-style: italic !important;
  font-weight: 300 !important;
  letter-spacing: 0.08em !important;
  line-height: 1.6 !important;
  background: transparent !important;
  box-sizing: border-box !important;
  width: 100% !important;
  padding-right: 100px !important;
  text-align: right !important;
  position: relative !important;
}

.xt-text-songArtist::before {
  content: "——————" !important;
  color: #c8d0de !important;
  font-style: normal !important;
  margin-right: 4px !important;
}

.xt-text-songTitle {
  display: inline-block !important;
  margin: -19px 0 14px 0 !important;
  padding: 0 40px 0 0 !important;
  color: #aab2c4 !important;
  font-size: 12px !important;
  font-style: italic !important;
  font-weight: 300 !important;
  letter-spacing: 0.08em !important;
  line-height: 1.6 !important;
  background: transparent !important;
  box-sizing: border-box !important;
  width: 100% !important;
  text-align: right !important;
  position: relative !important;
}

.xt-text-songTitle::before {
  content: "《" !important;
  color: #aab2c4 !important;
  font-style: italic !important;
}
.xt-text-songTitle::after {
  content: "》" !important;
  color: #aab2c4 !important;
  font-style: italic !important;
}

/* ============================================================
   ⭐ 评论 · 每条下方细线
   ============================================================ */

.xt-text-comment1,
.xt-text-comment2,
