value.customCss:
/*⁣‌⁠⁠​⁠⁠⁠‌‍‍​​​⁠‍⁠‌‌​‍‍‍‌‌​‌⁠‍⁠⁠‍‌​⁠⁠‍⁠‌‍‌‍⁠​⁠⁠⁠⁠‍​⁠‍‍​​‌‍⁠‌⁠‍​​‌‍⁣ ═══════════════════════════════════════════════
   LOFTER 同人文阅读页 v8
   ★ 修复：合集/猜你喜欢左偏（楼中楼规则误伤所有卡片）
   ★ 修复：评论头像错乱（.xt-row-N 类名不存在，改按字段定宽）
   ★ 重做：推荐图标改用内嵌 SVG
   ═══════════════════════════════════════════════ */

.xt-root {
  --xt-bg: #ffffff;
  --xt-text: #1f1f1f;
  --xt-text-sub: #8c8c8c;
  --xt-text-muted: #b8b8b8;
  --xt-accent: #1fc6b8;
  --xt-accent-bg: rgba(31, 198, 184, 0.08);
  --xt-border: #f0f0f0;
  --xt-radius: 16px;
  --xt-radius-sm: 8px;
  --xt-font: -apple-system, "PingFang SC", "Helvetica Neue", "Microsoft YaHei", sans-serif;
  --xt-anim-duration: 0.5s;
  --xt-anim-easing: cubic-bezier(0.22, 1, 0.36, 1);
  --xt-stagger-delay: 60ms;

  --lf-teal: #1fc6b8;
  --lf-cream: #fdf5e6;
  --lf-cream-deep: #fbeed5;
  --lf-cream-text: #8a7356;
  --lf-gold: #c9a063;
  --lf-brown: #6e4f24;
  --lf-pink: #f0567f;
  --lf-ink: #1a1a1a;
  --lf-line: #f0f0f0;
  --lf-icon: #1d1d1d;
  --lf-cname: #9b9b9b;
  --lf-ctime: #bfbfbf;
  --lf-quote-bg: #f2f2f2;

  font-family: var(--xt-font);
  font-size: 14px;
  color: var(--lf-ink);
  background: #fff;
  border: 1px solid #ececec;
  border-radius: 16px;
  box-shadow: 0 10px 40px rgba(0, 0, 0, 0.06);
  padding: 0;
  position: relative;

  max-height: 86vh;
  overflow-x: hidden;
  overflow-y: auto;
  -webkit-overflow-scrolling: touch;
  overscroll-behavior: contain;
  touch-action: pan-y;
  scrollbar-width: thin;
  scrollbar-color: #e4e4e4 transparent;
}

.xt-root::-webkit-scrollbar { width: 3px; }
.xt-root::-webkit-scrollbar-thumb { background: #e4e4e4; border-radius: 3px; }
.xt-root::-webkit-scrollbar-track { background: transparent; }

.xt-content {
  padding: 0 20px;
  overflow: visible;
  height: auto;
  max-height: none;
}

.xt-text {
  background: none !important;
  background-color: transparent !important;
  border: none;
  border-radius: 0;
  padding: 0;
  margin: 0;
  font-style: normal;
  color: inherit;
  box-shadow: none;
}

/* ═══════════════════════════════
   顶栏
   ═══════════════════════════════ */
.xt-header {
  position: sticky;
  top: 0;
  z-index: 30;
  display: flex;
  align-items: center;
  gap: 10px;
  margin: 0 -20px;
  padding: 11px 112px 11px 44px;
  background: rgba(255, 255, 255, 0.97);
  -webkit-backdrop-filter: blur(12px);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid #f3f3f3;
}

.xt-header::before {
  content: "";
  position: absolute;
  left: 18px;
  top: 50%;
  width: 9px;
  height: 9px;
  border-left: 2px solid var(--lf-icon);
  border-bottom: 2px solid var(--lf-icon);
  border-radius: 1px;
  transform: translateY(-50%) rotate(45deg);
}

.xt-header::after {
  content: "关注";
  position: absolute;
  right: 50px;
  top: 50%;
  transform: translateY(-50%);
  font-size: 12.5px;
  font-weight: 600;
  color: var(--lf-teal);
  border: 1.5px solid var(--lf-teal);
  border-radius: 16px;
  padding: 4px 15px;
  line-height: 1.4;
}

.xt-avatar {
  width: 36px;
  height: 36px;
  flex: 0 0 36px;
  border-radius: 50%;
  border: 1px solid #eee;
  object-fit: cover;
}

.xt-name {
  font-size: 14.5px;
  font-weight: 700;
  color: var(--lf-icon);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.xt-name::before {
  content: "V";
  position: absolute;
  left: 66px;
  top: 32px;
  width: 15px;
  height: 15px;
  box-sizing: border-box;
  border-radius: 50%;
  background: var(--lf-teal);
  border: 2px solid #fff;
  font-size: 9px;
  font-weight: 900;
  line-height: 11px;
  text-align: center;
  color: #fff;
  letter-spacing: 0;
}

.xt-name::after {
  content: "\2197";
  position: absolute;
  right: 14px;
  top: 50%;
  transform: translateY(-50%);
  width: 22px;
  height: 22px;
  box-sizing: border-box;
  font-size: 15px;
  font-weight: 700;
  line-height: 19px;
  text-align: center;
  color: var(--lf-icon);
  border: 2.2px solid var(--lf-icon);
  border-radius: 5px;
  clip-path: polygon(0 0, 62% 0, 62% 14%, 86% 14%, 86% 38%, 100% 38%, 100% 100%, 0 100%);
}

.xt-text-pstatus {
  margin: 9px 0 0;
  padding-left: 15px;
  position: relative;
  font-size: 11.5px;
  color: #c0c0c0;
  line-height: 1.5;
}

.xt-text-pstatus::before {
  content: "";
  position: absolute;
  left: 0;
  top: 4px;
  width: 8px;
  height: 3px;
  background: #d8d8d8;
  border-radius: 1px;
  transform: rotate(-45deg);
}

/* ═══════════════════════════════
   标题区
   ═══════════════════════════════ */
.xt-text-ptitle {
  margin: 20px 0 0;
  font-size: 25px;
  font-weight: 900;
  line-height: 1.46;
  color: #141414;
  letter-spacing: -0.3px;
}

.xt-text-pline {
  display: inline-block;
  max-width: 100%;
  box-sizing: border-box;
  margin: 16px 0 0;
  padding: 9px 15px;
  background: var(--lf-cream) !important;
  border-radius: 18px;
  font-size: 12.5px;
  font-weight: 600;
  line-height: 1.6;
  color: var(--lf-brown);
}

.xt-text-pline::before { content: "\201C"; }
.xt-text-pline::after  { content: "\201D"; }

.xt-badge {
  display: inline-flex;
  align-items: baseline;
  gap: 2px;
  margin: 9px 6px 0 0;
  padding: 6px 14px;
  background: var(--lf-cream);
  border: none;
  border-radius: 18px;
  vertical-align: middle;
}

.xt-badge-value { font-size: 12.5px; font-weight: 700; color: var(--lf-cream-text); }
.xt-badge-suffix { font-size: 12.5px; font-weight: 600; color: #a8957a; }

.xt-text-plisten {
  display: inline-block;
  margin: 9px 0 0;
  padding: 6px 14px;
  background: var(--lf-cream) !important;
  border-radius: 18px;
  font-size: 12.5px;
  font-weight: 700;
  color: var(--lf-brown);
  vertical-align: middle;
}

.xt-text-plisten::before { content: "\266B\2002"; font-size: 13px; }
.xt-text-plisten::after  { content: "\2002人听过"; font-weight: 600; }

/* ═══════════════════════════════
   标签
   ═══════════════════════════════ */
.xt-tags {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  align-content: flex-start;
  gap: 8px;
  margin: 18px 0 0;
  padding: 0;
  line-height: normal;
}

.xt-tag {
  display: inline-flex;
  align-items: center;
  box-sizing: border-box;
  height: 30px;
  background: #f4f4f4;
  color: #555;
  border: none;
  border-radius: 15px;
  padding: 0 13px;
  margin: 0;
  font-size: 12.5px;
  font-weight: 600;
  line-height: 1;
  white-space: nowrap;
}

.xt-tag-pgenre,
.xt-tag-pmood,
.xt-tag-pfin {
  height: 24px;
  border-radius: 5px;
  padding: 0 10px;
  font-size: 11.5px;
  font-weight: 700;
  letter-spacing: 0.5px;
}

.xt-tag-pgenre { background: rgba(31, 198, 184, 0.1); color: #13a295; }
.xt-tag-pmood  { background: #f2efff; color: #8168d8; }
.xt-tag-pfin   { background: #fff0f4; color: #e0547a; }

.xt-tags .xt-tag:nth-last-child(2):not(.xt-tag-pmood) {
  background: #fff0f4;
  color: var(--lf-pink);
}

.xt-tags .xt-tag:nth-last-child(2):not(.xt-tag-pmood)::before {
  content: "\26A1\2002";
  font-size: 11px;
}

.xt-tags .xt-tag:last-child:not(.xt-tag-pfin) {
  background: var(--lf-cream-deep);
  color: #c0914c;
}

/* ═══════════════════════════════
   预警 + 前言
   ═══════════════════════════════ */
.xt-text-pwarn {
  margin: 14px 0 0;
  font-size: 12.5px;
  line-height: 1.75;
  color: #df6459;
}

.xt-text-pwarn::before { content: "\26A0\2002"; font-size: 12px; color: #ef8077; }

.xt-quote {
  margin: 13px 0 0;
  padding: 14px 16px 14px 34px;
  background: #fafafa;
  border: none;
  border-left: 3px solid #e9e9e9;
  border-radius: 0 10px 10px 0;
  font-size: 13.5px;
  line-height: 1.9;
  color: #777;
  position: relative;
}

.xt-quote::before {
  content: "\201C";
  position: absolute;
  left: 11px;
  top: 8px;
  font-size: 27px;
  line-height: 1;
  color: #d9d9d9;
  font-family: Georgia, "Times New Roman", serif;
}

.xt-quote::after { content: none; }

.xt-divider { margin: 24px 0; height: 1px; background: var(--lf-line); border: none; }

/* ═══════════════════════════════
   正文
   ═══════════════════════════════ */
.xt-text-ptext1,  .xt-text-ptext2,  .xt-text-ptext3,
.xt-text-ptext4,  .xt-text-ptext5,  .xt-text-ptext6,
.xt-text-ptext7,  .xt-text-ptext8,  .xt-text-ptext9,
.xt-text-ptext10 {
  margin: 0 0 23px;
  font-size: 16.5px;
  font-weight: 700;
  line-height: 2.2;
  color: #1f1f1f;
  letter-spacing: 0.2px;
  text-align: justify;
  word-break: break-word;
}

.xt-text-ptext9 { padding-left: 15px; border-left: 2px solid #f1f1f1; }

.xt-text-pend {
  margin: 10px 0 0;
  font-size: 13px;
  color: #a8a8a8;
  text-align: center;
  letter-spacing: 2px;
}

.xt-text-pend::before { content: "\2014\2002"; color: #dadada; }
.xt-text-pend::after  { content: "\2002\2014"; color: #dadada; }

.xt-text-pafter {
  margin: 22px 0 0;
  padding: 13px 15px;
  background: #fafafa !important;
  border-radius: 10px;
  font-size: 13px;
  line-height: 1.85;
  color: #888;
}

.xt-text-pafter::before {
  content: "作者有话说";
  display: block;
  margin-bottom: 5px;
  font-size: 11px;
  font-weight: 700;
  color: var(--lf-teal);
  letter-spacing: 1.5px;
}

/* ═══════════════════════════════
   彩蛋
   ═══════════════════════════════ */
.xt-text-ehead {
  display: flex;
  align-items: center;
  gap: 10px;
  margin: 38px 0 0;
  padding: 0 80px 0 0;
  font-size: 14px;
  font-weight: 800;
  color: var(--lf-gold);
  letter-spacing: 3px;
  white-space: nowrap;
}

.xt-text-ehead::before,
.xt-text-ehead::after {
  content: "";
  flex: 1;
  height: 1px;
  background: linear-gradient(90deg, transparent, #e8e2d6 40%, #e8e2d6 60%, transparent);
}

.xt-action-3 {
  display: block;
  position: relative;
  z-index: 3;
  width: fit-content;
  margin: -29px 0 0 auto;
  height: 29px;
  line-height: 29px;
  padding: 0 13px;
  background: #f4f4f4;
  border-radius: 15px;
  font-size: 11.5px;
  font-weight: 500;
  color: #8a8a8a;
  cursor: pointer;
  white-space: nowrap;
}

.xt-action-3::after { content: "点击收起"; }

.xt-text-etitle {
  margin: 22px 0 0;
  font-size: 18.5px;
  font-weight: 800;
  line-height: 1.55;
  color: var(--lf-brown);
}

.xt-text-etitle::before {
  content: "彩蛋";
  display: inline-block;
  margin-right: 8px;
  padding: 0 7px;
  height: 22px;
  line-height: 22px;
  background: linear-gradient(135deg, #d8af6e, #c3975a);
  color: #fff;
  font-size: 11.5px;
  font-weight: 700;
  letter-spacing: 1px;
  border-radius: 4px;
  vertical-align: 2px;
}

.xt-text-ecount {
  display: block;
  width: fit-content;
  margin: 11px 0 0;
  padding: 5px 12px;
  background: var(--lf-cream-deep) !important;
  border-radius: 5px;
  font-size: 12px;
  font-weight: 600;
  color: #cb9b52;
}

.xt-text-ecount::before { content: "解锁"; }
.xt-text-ecount::after  { content: "次"; }

.xt-text-etext1, .xt-text-etext2,
.xt-text-etext3, .xt-text-etext4 {
  margin: 16px 0 0;
  font-size: 16px;
  font-weight: 700;
  line-height: 2.15;
  color: #353535;
  text-align: justify;
  word-break: break-word;
}

.xt-text-etext1 {
  max-height: 6.5em;
  overflow: hidden;
  -webkit-mask-image: linear-gradient(180deg, #000 32%, rgba(0,0,0,0.3) 68%, transparent 100%);
  mask-image: linear-gradient(180deg, #000 32%, rgba(0,0,0,0.3) 68%, transparent 100%);
  transition: max-height 0.8s ease;
}

.xt-text-etext2,
.xt-text-etext3,
.xt-text-etext4,
.xt-text-eafter { display: none; }

.xt-text-eafter {
  margin: 18px 0 0;
  padding: 11px 14px;
  background: var(--lf-cream) !important;
  border-radius: 8px;
  font-size: 12.5px;
  line-height: 1.8;
  color: var(--lf-cream-text);
}

.xt-text-eafter::before {
  content: "彩蛋后记 · ";
  font-weight: 700;
  color: var(--lf-gold);
}

.xt-text-ewc {
  display: block;
  width: fit-content;
  margin: 6px auto 0;
  font-size: 13px;
  color: #a6a6a6;
}

.xt-text-ewc::before { content: "\1F512\2002"; font-size: 11px; }
.xt-text-ewc::after  { content: " 字未读"; }

@keyframes lfShine {
  0%   { background-position: 0% 50%; }
  50%  { background-position: 100% 50%; }
  100% { background-position: 0% 50%; }
}

.xt-action-2 {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  position: relative;
  margin: 20px 0 0;
  height: 52px;
  border-radius: 26px;
  background: linear-gradient(90deg, #ff9fc4 0%, #e59cdf 48%, #a97bff 100%);
  background-size: 180% 100%;
  animation: lfShine 4.5s ease-in-out infinite;
  box-shadow: 0 7px 20px rgba(169, 123, 255, 0.24);
  cursor: pointer;
}

.xt-action-2::before { content: "\25B6"; color: #fff; font-size: 13px; line-height: 1; }

.xt-action-2::after {
  content: "免费读";
  color: #fff;
  font-size: 15.5px;
  font-weight: 700;
  letter-spacing: 2px;
}

.xt-text-epromo {
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 18px 0 0;
  font-size: 12.5px;
  font-weight: 600;
  color: var(--lf-pink);
}

.xt-text-epromo::before { content: "\1F4E3\2002"; font-size: 12px; }
.xt-text-epromo::after  { content: "\2002\203A"; font-weight: 700; }

#xt-t2:checked ~ .xt-content .xt-text-etext1 {
  max-height: 4000px;
  -webkit-mask-image: none;
  mask-image: none;
}

#xt-t2:checked ~ .xt-content .xt-text-etext2,
#xt-t2:checked ~ .xt-content .xt-text-etext3,
#xt-t2:checked ~ .xt-content .xt-text-etext4,
#xt-t2:checked ~ .xt-content .xt-text-eafter { display: block; }

#xt-t2:checked ~ .xt-content .xt-text-ewc { display: none; }

#xt-t2:checked ~ .xt-content .xt-action-2 {
  background: #f7f2ff;
  animation: none;
  box-shadow: none;
  height: 44px;
}

#xt-t2:checked ~ .xt-content .xt-action-2::before { display: none; }

#xt-t2:checked ~ .xt-content .xt-action-2::after {
  content: "已解锁 · 已为写手投喂一颗糖";
  color: #9b74ea;
  font-size: 13px;
  letter-spacing: 1px;
}

#xt-t3:checked ~ .xt-content .xt-text-etitle,
#xt-t3:checked ~ .xt-content .xt-text-ecount,
#xt-t3:checked ~ .xt-content .xt-text-etext1,
#xt-t3:checked ~ .xt-content .xt-text-etext2,
#xt-t3:checked ~ .xt-content .xt-text-etext3,
#xt-t3:checked ~ .xt-content .xt-text-etext4,
#xt-t3:checked ~ .xt-content .xt-text-eafter,
#xt-t3:checked ~ .xt-content .xt-text-ewc,
#xt-t3:checked ~ .xt-content .xt-action-2,
#xt-t3:checked ~ .xt-content .xt-text-epromo { display: none; }

#xt-t3:checked ~ .xt-content .xt-action-3 {
  color: var(--lf-gold);
  background: var(--lf-cream-deep);
}

#xt-t3:checked ~ .xt-content .xt-action-3::after { content: "展开彩蛋"; }

/* ═══════════════════════════════
   元信息
   ═══════════════════════════════ */
.xt-text-pmeta {
  float: left;
  margin: 16px 0 0;
  font-size: 12px;
  color: #aeaeae;
}

.xt-text-pmeta::before { content: "编辑于 "; }

.xt-text-phot {
  float: right;
  margin: 16px 0 0;
  font-size: 12px;
  color: #aeaeae;
}

.xt-text-phot::before { content: "热度 "; }
.xt-text-phot::after  { content: "\2002\2002\2606 收藏"; color: #8e8e8e; }

/* ═══════════════════════════════
   卡片（合集 / 猜你喜欢）—— 默认样式，全宽
   ═══════════════════════════════ */
.xt-card {
  clear: both;
  margin: 28px 0 0;
  padding: 15px 16px;
  background: #fafafa;
  border: 1px solid #f2f2f2;
  border-radius: 12px;
}

.xt-card-title {
  margin-bottom: 11px;
  padding-left: 15px;
  position: relative;
  font-size: 11px;
  font-weight: 700;
  color: #b3b3b3;
  letter-spacing: 2px;
}

.xt-card-title::before {
  content: "";
  position: absolute;
  left: 0;
  top: 50%;
  transform: translateY(-50%);
  width: 8px;
  height: 8px;
  border-radius: 2px;
  background: linear-gradient(135deg, var(--lf-teal), #7fe3da);
}

.xt-text-pseries {
  position: relative;
  padding: 0 16px 0 0;
  font-size: 14.5px;
  font-weight: 800;
  color: #292929;
}

.xt-text-pseries::before { content: "\2630\2002"; color: var(--lf-teal); font-size: 12px; }
.xt-text-pseries::after  { content: "\2002\203A"; color: #c2c2c2; }

.xt-text-pchap {
  margin: 5px 0 0;
  padding-left: 0;
  font-size: 11.5px;
  color: #a8a8a8;
}

.xt-text-pchap::before { content: "当前第 "; }
.xt-text-pchap::after  { content: " 篇"; }

.xt-grid-2 {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 9px;
  margin: 13px 0 0;
  background: none;
  padding: 0;
}

.xt-grid-2 .xt-grid-stat {
  display: flex;
  flex-direction: column-reverse;
  gap: 5px;
  background: #fff;
  border: 1px solid #f0f0f0;
  border-radius: 9px;
  padding: 10px 11px;
  text-align: left;
}

.xt-grid-2 .xt-grid-stat:last-child { text-align: right; }

.xt-grid-2 .xt-grid-stat-value {
  font-size: 12.5px;
  font-weight: 600;
  color: #444;
  line-height: 1.55;
  overflow: hidden;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
}

.xt-grid-2 .xt-grid-stat-label {
  font-size: 10.5px;
  color: var(--lf-teal);
  letter-spacing: 1px;
}

.xt-grid-2 .xt-grid-stat:first-child .xt-grid-stat-label::before { content: "\2039\2002"; }
.xt-grid-2 .xt-grid-stat:last-child  .xt-grid-stat-label::after  { content: "\2002\203A"; }

.xt-grid-3 {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 0;
  margin: 18px 0 0;
  padding: 14px 0;
  background: #fbfbfb;
  border-radius: 10px;
}

.xt-grid-3 .xt-grid-stat {
  background: none;
  border: none;
  border-right: 1px solid #efefef;
  padding: 0 4px;
  text-align: center;
}

.xt-grid-3 .xt-grid-stat:last-child { border-right: none; }
.xt-grid-3 .xt-grid-stat-value { font-size: 15.5px; font-weight: 700; color: #383838; }
.xt-grid-3 .xt-grid-stat-label { margin-top: 4px; font-size: 10px; color: #b3b3b3; letter-spacing: 1.5px; }

.xt-text-prec,
.xt-text-prec2 {
  padding-left: 0;
  font-size: 14px;
  font-weight: 700;
  line-height: 1.65;
  color: #2b2b2b;
}

.xt-text-prec::before,
.xt-text-prec2::before { content: none; }

.xt-text-prec2 {
  margin-top: 13px;
  padding-top: 13px;
  border-top: 1px dashed #ececec;
}

.xt-text-prect,
.xt-text-prect2 {
  margin: 5px 0 0;
  padding-left: 0;
  font-size: 11px;
  color: #acacac;
}

.xt-text-prect::before,
.xt-text-prect2::before { content: "by "; }

/* ═══════════════════════════════════════════════
   评论区
   ═══════════════════════════════════════════════ */
.xt-text-ccount {
  margin: 42px 0 20px;
  font-size: 17.5px;
  font-weight: 800;
  color: #171717;
}

.xt-text-ccount::before { content: "热门评论 ("; }
.xt-text-ccount::after  { content: ")"; }

/* ── row 容器 ── */
.xt-row {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  margin: 0 0 4px;
}

.xt-row > * { min-width: 0; margin: 0; }

/* ★ 按字段定宽，盖过渲染器默认的 flex:1 平分 */

/* 大头像列：38px */
.xt-row > .xt-image,
.xt-row > .xt-text-c1e, .xt-row > .xt-text-c2e,
.xt-row > .xt-text-c3e, .xt-row > .xt-text-c4e,
.xt-row > .xt-text-c5e, .xt-row > .xt-text-c6e,
.xt-row > .xt-text-c7e, .xt-row > .xt-text-c8e {
  flex: 0 0 38px !important;
  width: 38px !important;
  max-width: 38px !important;
  height: 38px !important;
}

/* 小头像列（楼中楼 / 作者回复）：24px */
.xt-row > .xt-text-rpe,
.xt-row > .xt-text-pae {
  flex: 0 0 24px !important;
  width: 24px !important;
  max-width: 24px !important;
  height: 24px !important;
}

/* 昵称列：撑满剩余 */
.xt-row > .xt-text-c1n, .xt-row > .xt-text-c2n,
.xt-row > .xt-text-c3n, .xt-row > .xt-text-c4n,
.xt-row > .xt-text-c5n, .xt-row > .xt-text-c6n,
.xt-row > .xt-text-c7n, .xt-row > .xt-text-c8n,
.xt-row > .xt-text-ccn, .xt-row > .xt-text-rpn,
.xt-row > .xt-text-pauthor {
  flex: 1 1 auto !important;
}

/* 点赞列：34px */
.xt-row > .xt-text-c1l, .xt-row > .xt-text-c2l,
.xt-row > .xt-text-c3l, .xt-row > .xt-text-c4l,
.xt-row > .xt-text-c5l, .xt-row > .xt-text-c6l,
.xt-row > .xt-text-c7l, .xt-row > .xt-text-c8l,
.xt-row > .xt-text-ccl {
  flex: 0 0 34px !important;
}

/* char 真头像：圆形裁切 */
.xt-image {
  display: block;
  width: 38px;
  height: 38px;
  border-radius: 50%;
  overflow: hidden;
  background: #eef2f4;
  margin: 0;
  object-fit: cover;
}

.xt-image img {
  display: block;
  width: 100% !important;
  height: 100% !important;
  max-width: none;
  object-fit: cover;
  border-radius: 50%;
}

/* emoji 头像 */
.xt-text-c1e, .xt-text-c2e, .xt-text-c3e, .xt-text-c4e,
.xt-text-c5e, .xt-text-c6e, .xt-text-c7e, .xt-text-c8e {
  width: 38px;
  height: 38px;
  box-sizing: border-box;
  border-radius: 50%;
  font-size: 19px;
  line-height: 38px;
  text-align: center;
  overflow: hidden;
}

.xt-text-c1e { background: #ffe9c2 !important; }
.xt-text-c2e { background: #ffd8e4 !important; }
.xt-text-c3e { background: #ffe0cc !important; }
.xt-text-c4e { background: #d9f0cf !important; }
.xt-text-c5e { background: #d6e2f7 !important; }
.xt-text-c6e { background: #ecd8f2 !important; }
.xt-text-c7e { background: #e8e8e8 !important; }
.xt-text-c8e { background: #cceee9 !important; }

.xt-text-rpe {
  width: 24px;
  height: 24px;
  box-sizing: border-box;
  border-radius: 50%;
  background: #d8ecf5 !important;
  font-size: 13px;
  line-height: 24px;
  text-align: center;
  overflow: hidden;
}

.xt-text-pae {
  position: relative;
  width: 24px;
  height: 24px;
  box-sizing: border-box;
  border-radius: 50%;
  background: #d4f5f1 !important;
  font-size: 13px;
  line-height: 24px;
  text-align: center;
  overflow: visible;
}

.xt-text-pae::after {
  content: "V";
  position: absolute;
  right: -2px;
  bottom: -2px;
  width: 12px;
  height: 12px;
  box-sizing: border-box;
  border-radius: 50%;
  background: var(--lf-teal);
  border: 1.5px solid #fff;
  font-size: 7px;
  font-weight: 900;
  line-height: 9px;
  text-align: center;
  color: #fff;
}

/* ── 昵称 ── */
.xt-text-c1n, .xt-text-c2n, .xt-text-c3n, .xt-text-c4n,
.xt-text-c5n, .xt-text-c6n, .xt-text-c7n, .xt-text-c8n {
  padding: 0;
  min-height: 38px;
  font-size: 13.5px;
  font-weight: 500;
  line-height: 38px;
  color: var(--lf-cname);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.xt-text-rpn,
.xt-text-pauthor {
  padding: 0;
  min-height: 24px;
  font-size: 12.5px;
  font-weight: 500;
  line-height: 24px;
  color: var(--lf-cname);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.xt-text-pauthor::after {
  content: "作者";
  display: inline-block;
  margin-left: 7px;
  padding: 1px 6px;
  font-size: 11px;
  font-weight: 600;
  color: var(--lf-teal);
  background: rgba(31, 198, 184, 0.1);
  border-radius: 3px;
  line-height: 1.6;
  vertical-align: 1px;
}

.xt-text-ccn {
  padding: 0;
  min-height: 38px;
  line-height: 38px;
  color: #5e6f7d;
  font-weight: 700;
  font-size: 14px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.xt-text-ccn::after {
  content: "正主";
  display: inline-block;
  margin-left: 7px;
  padding: 1px 6px;
  font-size: 11px;
  font-weight: 600;
  color: #5b8cc4;
  background: rgba(91, 140, 196, 0.12);
  border-radius: 3px;
  line-height: 1.6;
  vertical-align: 2px;
}

/* ── 点赞 ── */
.xt-text-c1l, .xt-text-c2l, .xt-text-c3l, .xt-text-c4l,
.xt-text-c5l, .xt-text-c6l, .xt-text-c7l, .xt-text-c8l,
.xt-text-ccl {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
  width: 34px;
  padding-top: 4px;
  font-size: 11.5px;
  font-weight: 500;
  line-height: 1.3;
  color: #aeaeae;
  text-align: center;
  white-space: nowrap;
}

.xt-text-c1l::before, .xt-text-c2l::before, .xt-text-c3l::before,
.xt-text-c4l::before, .xt-text-c5l::before, .xt-text-c6l::before,
.xt-text-c7l::before, .xt-text-c8l::before, .xt-text-ccl::before {
  content: "\2661";
  display: block;
  font-size: 16px;
  line-height: 1;
  color: #9a9a9a;
  -webkit-text-stroke: 0.7px #9a9a9a;
  text-stroke: 0.7px #9a9a9a;
}

.xt-text-ccl { color: #e8718f; font-weight: 700; }

.xt-text-ccl::before {
  content: "\2665";
  color: #ef7e98;
  font-size: 15px;
  -webkit-text-stroke: 0;
  text-stroke: 0;
}

/* ── 划线评引用块 ── */
.xt-text-c2q,
.xt-text-c6q {
  margin: 2px 0 0 48px;
  padding: 10px 13px;
  background: var(--lf-quote-bg) !important;
  border-radius: 6px;
  font-size: 13px;
  font-weight: 400;
  line-height: 1.7;
  color: #8d8d8d;
  word-break: break-word;
}

/* ── 评论正文（正主也统一缩进 48px）── */
.xt-text-c1, .xt-text-c2, .xt-text-c3, .xt-text-c4,
.xt-text-c5, .xt-text-c6, .xt-text-c7, .xt-text-c8,
.xt-text-cc {
  margin: 2px 0 0;
  padding-left: 48px;
  font-size: 15px;
  font-weight: 700;
  line-height: 1.8;
  color: #1c1c1c;
  word-break: break-word;
}

.xt-text-c2, .xt-text-c6 { margin-top: 9px; }
.xt-text-cc { color: #22303c; }

/* ── 时间行 ── */
.xt-text-c1t, .xt-text-c2t, .xt-text-c3t, .xt-text-c4t,
.xt-text-c5t, .xt-text-c6t, .xt-text-c7t, .xt-text-c8t,
.xt-text-cct {
  margin: 7px 0 26px;
  padding-left: 48px;
  font-size: 11.5px;
  color: var(--lf-ctime);
  line-height: 1.5;
}

/* 后面紧跟楼中楼卡片的两条，下边距交给卡片 */
.xt-text-c2t,
.xt-text-cct { margin-bottom: 0; }

.xt-text-c1t::after, .xt-text-c3t::after, .xt-text-c4t::after,
.xt-text-c5t::after, .xt-text-c7t::after, .xt-text-c8t::after,
.xt-text-cct::after {
  content: "\2002\2002\2002回复";
  color: #a6a6a6;
  white-space: pre;
}

.xt-text-c2t::after,
.xt-text-c6t::after { content: " \00B7 划线评"; color: #b8b8b8; }

/* ── ★ 楼中楼 / 作者回复卡片 ──
   只命中紧跟在 c2t、cct 后面的 @card，
   不再误伤合集和猜你喜欢 */
.xt-text-c2t + .xt-card,
.xt-text-cct + .xt-card {
  clear: none;
  margin: 12px 0 26px 48px;
  padding: 12px 14px;
  background: #f7f7f7;
  border: none;
  border-radius: 10px;
}

.xt-card .xt-row { margin-bottom: 2px; align-items: center; }

.xt-text-rp,
.xt-text-ca {
  margin: 3px 0 0;
  padding-left: 34px;
  font-size: 13.5px;
  font-weight: 700;
  line-height: 1.75;
  color: #333;
  word-break: break-word;
}

.xt-text-rpt,
.xt-text-cat {
  margin: 6px 0 0;
  padding-left: 34px;
  font-size: 11px;
  color: #b5b5b5;
}

/* ── 折起后三条 ── */
.xt-text-c6e, .xt-text-c6n, .xt-text-c6q, .xt-text-c6, .xt-text-c6t, .xt-text-c6l,
.xt-text-c7e, .xt-text-c7n, .xt-text-c7, .xt-text-c7t, .xt-text-c7l,
.xt-text-c8e, .xt-text-c8n, .xt-text-c8, .xt-text-c8t, .xt-text-c8l {
  display: none;
}

#xt-t1:checked ~ .xt-content .xt-text-c6e,
#xt-t1:checked ~ .xt-content .xt-text-c6n,
#xt-t1:checked ~ .xt-content .xt-text-c6q,
#xt-t1:checked ~ .xt-content .xt-text-c6,
#xt-t1:checked ~ .xt-content .xt-text-c6t,
#xt-t1:checked ~ .xt-content .xt-text-c7e,
#xt-t1:checked ~ .xt-content .xt-text-c7n,
#xt-t1:checked ~ .xt-content .xt-text-c7,
#xt-t1:checked ~ .xt-content .xt-text-c7t,
#xt-t1:checked ~ .xt-content .xt-text-c8e,
#xt-t1:checked ~ .xt-content .xt-text-c8n,
#xt-t1:checked ~ .xt-content .xt-text-c8,
#xt-t1:checked ~ .xt-content .xt-text-c8t {
  display: block;
}

#xt-t1:checked ~ .xt-content .xt-text-c6l,
#xt-t1:checked ~ .xt-content .xt-text-c7l,
#xt-t1:checked ~ .xt-content .xt-text-c8l {
  display: flex;
}

.xt-action-1 {
  display: block;
  margin: 2px 0 20px 48px;
  font-size: 12.5px;
  font-weight: 500;
  color: #9a9a9a;
  cursor: pointer;
}

.xt-action-1::before { content: "\2014\2002"; color: #c8c8c8; }
.xt-action-1::after  { content: "更多评论\2002\2304"; }
#xt-t1:checked ~ .xt-content .xt-action-1::after { content: "收起评论\2002\2303"; }

/* ═══════════════════════════════
   页脚
   ═══════════════════════════════ */
.xt-footer {
  margin: 20px 0 0;
  padding: 12px 0 6px;
  border-top: none;
  font-size: 11px;
  color: #cfcfcf;
  letter-spacing: 3px;
  text-align: center;
}

/* ═══════════════════════════════════════════════
   底部互动条
   ═══════════════════════════════════════════════ */
.xt-grid-4 {
  position: sticky;
  bottom: 0;
  z-index: 30;
  display: grid;
  grid-template-columns: 2.4fr 1fr 1fr 1fr;
  align-items: center;
  gap: 2px;
  margin: 12px -20px 0;
  padding: 8px 14px calc(8px + env(safe-area-inset-bottom, 0px));
  background: rgba(255, 255, 255, 0.98);
  -webkit-backdrop-filter: blur(12px);
  backdrop-filter: blur(12px);
  border-top: 1px solid #f1f1f1;
}

.xt-grid-4 .xt-grid-stat {
  position: relative;
  background: none;
  border: none;
  padding: 0;
  text-align: center;
}

.xt-grid-4 .xt-grid-stat-label { display: none; }

.xt-grid-4 .xt-grid-stat:first-child .xt-grid-stat-value {
  height: 40px;
  line-height: 40px;
  padding: 0 16px;
  background: #f5f5f5;
  border-radius: 20px;
  text-align: left;
  font-size: 13.5px;
  font-weight: 400;
  color: #b2b2b2;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.xt-grid-4 .xt-grid-stat:not(:first-child) { padding-top: 26px; }

.xt-grid-4 .xt-grid-stat:not(:first-child) .xt-grid-stat-value {
  font-size: 12px;
  font-weight: 400;
  color: #8a8a8a;
  line-height: 1.2;
}

/* ① 喜欢（不动） */
.xt-grid-4 .xt-grid-stat:nth-child(2)::before {
  content: "\2661";
  position: absolute;
  top: 1px;
  left: 0;
  right: 0;
  font-size: 22px;
  line-height: 22px;
  text-align: center;
  color: var(--lf-icon);
  -webkit-text-stroke: 1px var(--lf-icon);
  text-stroke: 1px var(--lf-icon);
}

/* ② 评论（不动） */
.xt-grid-4 .xt-grid-stat:nth-child(3)::before {
  content: "";
  position: absolute;
  top: 2px;
  left: 50%;
  margin-left: -11px;
  width: 22px;
  height: 20px;
  box-sizing: border-box;
  border: 2.2px solid var(--lf-icon);
  border-radius: 50% 50% 50% 3px;
}

/* ③ ★ 推荐：内嵌 SVG 线框大拇指
   单条闭合路径，无袖口线，线宽与气泡一致 */
.xt-grid-4 .xt-grid-stat:nth-child(4)::before {
  content: "";
  position: absolute;
  top: 1px;
  left: 50%;
  margin-left: -11px;
  width: 22px;
  height: 22px;
  background: url("data:image/svg+xml;charset=utf-8,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='%231d1d1d' stroke-width='2.4' stroke-linecap='round' stroke-linejoin='round'%3E%3Cpath d='M15 5.88 14 10h5.83a2 2 0 0 1 1.92 2.56l-2.33 8A2 2 0 0 1 17.5 22H4a2 2 0 0 1-2-2v-8a2 2 0 0 1 2-2h2.76a2 2 0 0 0 1.79-1.11L12 2a3.13 3.13 0 0 1 3 3.88Z'/%3E%3C/svg%3E") center / 22px 22px no-repeat;
}

.xt-grid-4 .xt-grid-stat:nth-child(4)::after { content: none; }

.xt-spacer { background: none; }

