.xt-text-visibility::before {
  content: "谁可以看";
  background-image: url("data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' width='16' height='16' viewBox='0 0 24 24' fill='none' stroke='%231a1a1a' stroke-width='2' stroke-linecap='round' stroke-linejoin='round'><circle cx='12' cy='8' r='3.4'/><path d='M5 20c0-4 3.4-6.2 7-6.2s7 2.2 7 6.2'/></svg>");
}
.xt-text-location::after,
.xt-text-mention::after,
.xt-text-visibility::after {
  content: "›";
  margin-left: 6px;
  font-size: 18px; font-weight: 300;
  color: #c8c8c8;
}

/* ==================================================================
   热区
   ================================================================== */
.xt-action-1, .xt-action-2, .xt-action-3 {
  display: block;
