value.customCss:
.xt-root {
    --xt-bg: #ececec; 
    --xt-border: #b5b5b5;
    --xt-font: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;

    position: relative;
    padding-top: 60px; 
    background: var(--xt-bg);
    border: 1px solid #999;
    border-radius: 8px;
    box-shadow: 0 10px 30px rgba(0,0,0,0.25), inset 0 1px 0 rgba(255,255,255,0.8);
}

/*⁣‌⁠⁠​⁠⁠⁠‌‍‍​​​⁠‍⁠‌‌​‍‍‍‌‌​‌⁠‍⁠⁠‍‌​⁠⁠‍⁠‌‍‌‍⁠​⁠⁠⁠⁠‍​⁠‍‍​​‌‍⁠‌⁠‍​​‌‍⁣ 1. 顶部 Mac 标题栏 MiMi */
.xt-root::before {
    content: "MiMi";
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 32px;
    background: linear-gradient(to bottom, #f2f2f2, #dcdcdc);
    border-bottom: 1px solid #b5b5b5;
    border-radius: 8px 8px 0 0;
    text-align: center;
    line-height: 32px;
    font-size: 13px;
    color: #333;
    font-weight: bold;
    text-shadow: 0 1px 0 rgba(255,255,255,0.7);
    letter-spacing: 0.5px;
}

/* 2. 左上角红黄绿控制按钮 */
.xt-root::after {
    content: "";
    position: absolute;
    top: 10px; left: 14px;
    width: 12px; height: 12px;
    border-radius: 50%;
    background: #ff5f56;
    box-shadow: 18px 0 0 #ffbd2e, 36px 0 0 #27c93f, 0 1px 1px rgba(0,0,0,0.3);
}

/* 3. 下方工具栏：名言滚动（@marquee famousQuote） */
.xt-marquee {
    position: absolute !important;
    top: 32px; left: 0; right: 0;
    height: 28px;
    margin: 0 !important; padding: 0 !important;
    background: linear-gradient(to bottom, #eaeaea, #dfdfdf) !important;
    border: none !important;
    border-bottom: 1px solid #b5b5b5 !important;
    border-radius: 0 !important;
    box-shadow: none !important;
    overflow: hidden;
    pointer-events: none;
    z-index: 1;
}
.xt-marquee-inner {
    line-height: 28px;
    font-size: 11px;
    color: #444;
    text-shadow: 0 1px 0 rgba(255,255,255,0.6);
    animation-duration: 16s;
}

.xt-card { background: transparent !important; border: none !important; box-shadow: none !important; padding: 0 !important; margin: 0 !important; border-radius: 0 !important; }

/* ============ 分栏与错落照片墙 ============ */
.xt-row { 
    align-items: stretch !important; 
    margin-bottom: 16px !important;
}
.xt-row > *:first-child { 
    flex: 1.1; 
    display: flex; 
    flex-direction: column; 
    padding: 8px 12px 8px 0;
}
.xt-row > *:last-child { 
    flex: 2.2; 
    padding: 8px 0 8px 16px; 
    border-left: none !important; 
    border-radius: 0 !important;
    display: flex;
    flex-direction: column;
    justify-content: center; 
}

.xt-image { 
    background: #fff !important; 
    padding: 6px !important; 
    border: 1px solid #bbb !important; 
    border-radius: 3px !important;
    box-shadow: 0 3px 8px rgba(0,0,0,0.15) !important;
    margin: 0 !important;
}
.xt-row > *:first-child .xt-image:first-child {
    transform: rotate(-4deg);
    z-index: 1;
    position: relative;
}
.xt-row > *:first-child .xt-image:last-child {
    width: 78%; 
    align-self: flex-end; 
    margin-top: -38px !important; 
    margin-right: -2px !important; 
    transform: rotate(6deg);
    z-index: 2;
    position: relative;
    box-shadow: -4px 6px 14px rgba(0,0,0,0.2) !important;
}

/* ============ 右侧昵称、签名、标签 ============ */
.xt-text-nickname {
    text-align: center !important;
    letter-spacing: 1px !important;
    font-size: 22px !important;
    font-weight: bold !important;
    color: #222 !important;
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif !important;
    margin-bottom: 8px !important;
    background: transparent !important;
    padding: 0 !important;
    text-shadow: 0 1px 0 rgba(255,255,255,0.8);
}

.xt-text-signature {
    font-size: 12px !important;
    color: #444 !important;
    background: #e4e4e4 !important; 
    padding: 8px 12px !important;
    border-radius: 5px !important;
    margin-bottom: 14px !important;
    line-height: 1.4 !important;
    border: 1px solid #b5b5b5 !important;
    box-shadow: inset 0 1px 3px rgba(0,0,0,0.15), 0 1px 0 rgba(255,255,255,0.7) !important;
}
.xt-text-signature:empty { display: none !important; }

.xt-tags { 
    display: flex; 
    flex-wrap: nowrap !important;
    gap: 6px !important; 
}
.xt-tag {
    background: linear-gradient(to bottom, #ffffff, #e6e6e6) !important;
    border: 1px solid #adadad !important;
    color: #333 !important;
    font-size: 10.5px !important;
    padding: 4px 8px !important;
    border-radius: 12px !important; 
    box-shadow: 0 1px 2px rgba(0,0,0,0.1), inset 0 1px 0 rgba(255,255,255,0.8) !important;
    font-weight: bold !important;
    white-space: nowrap !important;
    flex: 1;
    text-align: center;
}

/* ============ 正文标题区 ============ */
