value.customCss:
.xt-root {
  --c-bg: #f7f7f7;
  --c-card: #ffffff;
  --c-black: #111111;
  --c-dark: #333333;
  --c-gray: #888888;
  --c-light: #d4d4d4;
  --c-line: #e8e8e8;

  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", "PingFang SC", "Microsoft YaHei", sans-serif;
  max-width: 360px;
  height: auto !important;
  min-height: 240px;
  margin: 10px auto;
  background: var(--c-card);
  border-radius: 14px;
  border: 1px solid var(--c-line);
  overflow: visible;
  position: relative;
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.05);
  display: flex;
  flex-direction: column;
}

.xt-content {
  flex: 1;
  padding: 20px;
  display: flex !important;
  flex-direction: column;
  overflow: visible !important;
}

/*⁣‌⁠⁠​⁠⁠⁠‌‍‍​​​⁠‍⁠‌‌​‍‍‍‌‌​‌⁠‍⁠⁠‍‌​⁠⁠‍⁠‌‍‌‍⁠​⁠⁠⁠⁠‍​⁠‍‍​​‌‍⁠‌⁠‍​​‌‍⁣ ═══ 清除底色 ═══ */
.xt-row, .xt-text-line, .xt-text-心境, .xt-text-状态 {
  background: transparent !important;
  box-shadow: none !important;
  border: none !important;
}

/* ═══ ① 顶部栏 ═══ */
.xt-row:first-of-type {
  display: flex !important;
  justify-content: space-between !important;
  align-items: center !important;
  margin-bottom: 16px;
  flex-shrink: 0;
}

.xt-row:first-of-type .xt-image,
.xt-row:first-of-type img {
  width: 36px !important;
  height: 36px !important;
  max-width: 36px !important;
  border-radius: 50% !important;
  object-fit: cover;
  filter: grayscale(100%);
  background: var(--c-bg);
  margin: 0 !important;
}

.xt-text-wifi {
  font-size: 0 !important;
  color: transparent !important;
  position: relative;
  width: 22px;
  height: 18px;
  display: block;
  flex: 0 0 auto;
}

.xt-text-wifi::before {
  content: '';
  position: absolute;
  bottom: 2px; left: 0;
  width: 22px; height: 16px;
  background: 
    linear-gradient(var(--c-gray), var(--c-gray)) 0 10px / 4px 6px no-repeat,
    linear-gradient(var(--c-light), var(--c-light)) 9px 5px / 4px 11px no-repeat,
    linear-gradient(var(--c-light), var(--c-light)) 18px 0px / 4px 16px no-repeat;
  border-radius: 1px;
}

.xt-text-wifi::after {
  content: '';
  position: absolute;
  top: -3px; left: 1px;
  width: 16px; height: 8px;
  border: 1.5px solid var(--c-light);
  border-bottom: none;
  border-radius: 50% 50% 0 0;
  opacity: 0.5;
}

/* ═══ ② 假心话（去掉双引号版） ═══ */
.xt-text-假心话 {
  flex-grow: 1;
  display: flex !important;
  justify-content: center;
  align-items: center;
  text-align: center;
  font-family: "Songti SC", "SimSun", "Times New Roman", serif;
  font-weight: 300;
  font-size: 14px; 
  color: #333333;
  line-height: 1.8;
  letter-spacing: 1px;
  padding: 10px 5px;
  word-break: break-word;
  margin-bottom: 20px; 
}

/* 删掉了原本的 ::before 和 ::after 引号 */

/* ═══ ③ 隐藏加号和线 ═══ */
.xt-text-line {
  display: none !important;
}

/* ═══ ④ 心境：严格靠右下，文字绝对居中 ═══ */
.xt-text-心境 {
  display: flex;
  align-self: flex-end !important; 
  justify-content: center !important;
  text-align: center !important; 
  width: fit-content !important;
  margin: 0 0 8px 0 !important;
  padding: 0 0 6px 0 !important; 
  font-size: 12px;
  color: var(--c-gray); 
  letter-spacing: 1px;
  position: relative;
}

.xt-text-心境::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0; right: 0;
  height: 1px;
  background: var(--c-light);
}

/* ═══ ⑤ 状态：严格靠右下，文字绝对居中 ═══ */
.xt-text-状态 {
  display: flex;
  align-self: flex-end !important; 
  justify-content: center !important;
  text-align: center !important;
  width: fit-content !important;
  margin: 0 !important;
  padding: 0 !important; 
  font-size: 9px;
  color: #b3b3b3 !important; 
  letter-spacing: 2px;
}

