value.customCss:
/*⁣‌⁠⁠​⁠⁠⁠‌‍‍​​​⁠‍⁠‌‌​‍‍‍‌‌​‌⁠‍⁠⁠‍‌​⁠⁠‍⁠‌‍‌‍⁠​⁠⁠⁠⁠‍​⁠‍‍​​‌‍⁠‌⁠‍​​‌‍⁣ ╔════════════════════════════════════════════╗
   ║   构成 · 拓本摘抄 v2    四主题合集             ║
   ║   ★【可改】= 可以放心改的地方，Ctrl+F 搜「★」   ║
   ║   ★ 切换主题：删掉想用那套开头的 .off           ║
   ║     其余几套保留 .off（只开一套）               ║
   ║   画幅 3:4，字号随卡片宽度自动缩放              ║
   ╚════════════════════════════════════════════╝ */

@import url('https://fonts.googleapis.com/css2?family=Noto+Serif+SC:wght@500;700;900&family=Noto+Serif:ital,wght@0,700;1,500&display=swap');

/* ★【可改】自备刻本/油墨宋字体：去掉注释，填入你自己的 woff2 链接 */
/*
@font-face {
  font-family: "MyInkSong";
  src: url("https://你的字体链接.woff2") format("woff2");
  font-display: swap;
}
*/

/* ═════════════════════════════════════════════
   主题区 ★【可改】只留一套没有 .off
   变量说明：
   --c-bg       底色
   --c-white    主字色（碎句/语录/诗句/随笔/结尾）
   --c-title    大标题颜色
   --c-black    对比字色（外文引用/副标题）
   --c-gray     弱字色（右上碎句/竖排2/落款/按钮）
   --c-ghost    背景淡化大字
   --c-stamp    印章
   --c-tag-bg / --c-tag-text  标签底色/字色
   --c-shadow   字影
   --c-grain / --c-grain2 / --c-vignette  纸纹颗粒/暗角
   --c-snow / --c-snow-glow  雪花粒子颜色/光晕
   ═════════════════════════════════════════════ */

/* ████ 主题 1 · 粉樱白雪 ████（默认开启） */
.off.xt-root {
  --c-bg:        #f6e4e6;
  --c-white:     #a8324c;
  --c-title:     #a8324c;
  --c-black:     #3a2a2e;
  --c-gray:      #9a7a82;
  --c-ghost:     rgba(200, 90, 110, 0.16);
  --c-stamp:     #c8405a;
  --c-tag-bg:    #a8324c;
  --c-tag-text:  #fff6f7;
  --c-shadow:    rgba(168, 50, 76, 0.12);
  --c-grain:     rgba(120, 40, 60, 0.08);
  --c-grain2:    rgba(255, 255, 255, 0.5);
  --c-vignette:  rgba(190, 100, 120, 0.22);
  --c-snow:      #ffffff;
  --c-snow-glow: rgba(200, 90, 110, 0.55);
}

/* ████ 主题 2 · 黑白暗色 ████ */
.off.xt-root {
  --c-bg:        #121212;
  --c-white:     #ece8e1;
  --c-title:     #ece8e1;
  --c-black:     #a9a49c;
  --c-gray:      #6e6a66;
  --c-ghost:     rgba(255, 255, 255, 0.07);
  --c-stamp:     #ece8e1;   /* ★想留一点红可改 #b3221e */
  --c-tag-bg:    #ece8e1;
  --c-tag-text:  #121212;
  --c-shadow:    rgba(0, 0, 0, 0.6);
  --c-grain:     rgba(255, 255, 255, 0.05);
  --c-grain2:    rgba(0, 0, 0, 0.3);
  --c-vignette:  rgba(0, 0, 0, 0.6);
  --c-snow:      #ece8e1;
  --c-snow-glow: rgba(255, 255, 255, 0.35);
}

/* ████ 主题 3 · 克莱因蓝 + 艾绿 ████ */
.xt-root {
  --c-bg:        #002fa7;   /* 克莱因蓝 */
  --c-white:     #eef2ea;   /* 米白主字 */
  --c-title:     #eef2ea;   /* ★想让标题也用艾绿可改 #a4cab6 */
  --c-black:     #a4cab6;   /* 艾绿 */
  --c-gray:      #8fa3dc;   /* 雾蓝 */
  --c-ghost:     rgba(0, 10, 60, 0.35);
  --c-stamp:     #a4cab6;
  --c-tag-bg:    #a4cab6;
  --c-tag-text:  #002fa7;
  --c-shadow:    rgba(0, 10, 50, 0.35);
  --c-grain:     rgba(0, 0, 40, 0.18);
  --c-grain2:    rgba(220, 235, 255, 0.07);
  --c-vignette:  rgba(0, 10, 60, 0.45);
  --c-snow:      #eef2ea;
  --c-snow-glow: rgba(164, 202, 182, 0.5);
}

/* ████ 主题 4 · 雾蓝灰（#738CB8 #B0CCD7 #CDDFE9 #899593）████ */
.off.xt-root {
  --c-bg:        #cddfe9;
  --c-white:     #4f6690;   /* #738CB8 压暗一档，保证小字看得清 */
  --c-title:     #738cb8;
  --c-black:     #5c6866;   /* #899593 压暗一档 */
  --c-gray:      #899593;
  --c-ghost:     #b0ccd7;
  --c-stamp:     #738cb8;
  --c-tag-bg:    #738cb8;
  --c-tag-text:  #f4f8fb;
  --c-shadow:    rgba(60, 80, 110, 0.12);
  --c-grain:     rgba(60, 80, 110, 0.08);
  --c-grain2:    rgba(255, 255, 255, 0.45);
  --c-vignette:  rgba(115, 140, 184, 0.28);
  --c-snow:      #ffffff;
  --c-snow-glow: rgba(115, 140, 184, 0.6);
}

/* ═════════════════════════════════════════════
   以下为通用结构，换主题不用动
   ═════════════════════════════════════════════ */

.xt-root {
  /* ████████ ★【可改】字体（前面优先，没有就往后退） ████████ */
  --f-song: "MyInkSong", "南西油墨宋", "方正刻本仿宋", "Noto Serif SC",
            "Source Han Serif SC", "Songti SC", "SimSun", serif;
  --f-latin: "Noto Serif", "Times New Roman", var(--f-song);

  /* ████████ ★【可改】动画节奏 ████████ */
  --t-ink: 1.1s;   /* 渐显时长 */
  --t-pop: 0.75s;  /* 跳出时长 */
  --gap: 0.18s;    /* 每层出场间隔，调大=整体更慢 */

  /* 对接系统变量 */
  --xt-bg: var(--c-bg);
  --xt-text: var(--c-white);
  --xt-font: var(--f-song);

  position: relative;
  width: 100%;
  height: auto;
  aspect-ratio: 3 / 4;               /* ★【可改】画幅比例 */
  padding: 0 !important;
  overflow: hidden;
  background: var(--c-bg);
  border: none;
  border-radius: 4px;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.25);
  container-type: inline-size;
  font-family: var(--f-song);
}

/* 纸纹 + 拓印颗粒 + 四角暗角 */
.xt-root::after {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 5;
  pointer-events: none;
  background:
    radial-gradient(circle at 30% 40%, var(--c-grain) 0 0.6px, transparent 1.1px) 0 0 / 6px 6px,
    radial-gradient(circle at 70% 70%, var(--c-grain2) 0 0.6px, transparent 1.1px) 0 0 / 9px 9px,
    radial-gradient(120% 90% at 50% 45%, transparent 55%, var(--c-vignette) 100%);
}

/* 内容层铺满整张卡 */
.xt-content {
  position: absolute !important;
  inset: 0;
  display: block !important;
  margin: 0 !important;
  padding: 0 !important;
  font-size: 16px;   /* 旧浏览器兜底 */
  font-size: 4cqw;
}

/* 所有文字的公共样式 */
.xt-content .xt-text,
.xt-content .xt-tags {
  position: absolute;
  z-index: 2;
  margin: 0;
  padding: 0;
  background: none;
  border: 0;
  border-radius: 0;
  box-shadow: none;
  font-family: var(--f-song);
  font-weight: 700;
  line-height: 1.45;
  white-space: pre-line;
  text-shadow: 0 0 0.6px currentColor, 0.04em 0.04em 0 var(--c-shadow);
  animation: inkIn var(--t-ink) cubic-bezier(0.2, 0.7, 0.2, 1) both;
}

.xt-spacer, .xt-divider, .xt-footer { display: none; }

/* 雪花粒子（布局里加 @particles snow 20 才会出现） */
.xt-particles-snow .xt-particle {
  background: var(--c-snow);
  box-shadow: 0 0 4px var(--c-snow-glow);
}

/* ═════════ 底层：背景淡化大字 ═════════ */

/* ★【可改】右上竖排大字 */
.xt-content .xt-text-bgWord1 {
  top: -2%;
  right: -1%;
  z-index: 0;
  writing-mode: vertical-rl;
  font-size: 6.2em;
  font-weight: 900;
  line-height: 1;
  letter-spacing: -0.04em;
  color: var(--c-ghost);
  text-shadow: none;
  animation-name: ghostIn;
  animation-duration: 2.4s;
}

/* ★【可改】左下横排大字 */
.xt-content .xt-text-bgWord2 {
  bottom: 12%;
  left: -3%;
  z-index: 0;
  font-size: 5.2em;
  font-weight: 900;
  line-height: 1;
  white-space: nowrap;
  color: var(--c-ghost);
  text-shadow: none;
  animation-name: ghostIn;
  animation-duration: 2.4s;
  animation-delay: calc(var(--gap) * 2);
}

/* ═════════ 上部 ═════════ */

/* ★【可改】左上碎句 */
.xt-content .xt-text-fragA {
  top: 4%;
  left: 5%;
  width: 54%;
  font-size: 0.82em;
  color: var(--c-white);
  display: -webkit-box;
  -webkit-line-clamp: 4;
  -webkit-box-orient: vertical;
  overflow: hidden;
  animation-delay: calc(var(--gap) * 3);
}

/* ★【可改】右上碎句（弱色，右对齐） */
.xt-content .xt-text-fragB {
  top: 4.5%;
  right: 5%;
  width: 34%;
  text-align: right;
  font-size: 0.76em;
  font-weight: 500;
  color: var(--c-gray);
  animation-delay: calc(var(--gap) * 4);
}

/* ★【可改】标签 */
.xt-content .xt-tags {
  top: 18.5%;
  left: 5%;
  display: flex;
  flex-wrap: wrap;
  gap: 0.4em;
  animation: none;
}
.xt-content .xt-tag {
  margin: 0;
  padding: 0.12em 0.5em;
  border: 0;
  border-radius: 0;
  background: var(--c-tag-bg);
  color: var(--c-tag-text);
  font-family: var(--f-song);
  font-size: 0.62em;
  font-weight: 700;
  letter-spacing: 0.1em;
  animation: popIn var(--t-pop) cubic-bezier(0.3, 1.4, 0.5, 1) both;
}
.xt-content .xt-tag::before { content: "# "; opacity: 0.6; }  /* ★【可改】标签前缀 */
.xt-content .xt-tag:nth-child(1) { animation-delay: calc(var(--gap) * 5); }
.xt-content .xt-tag:nth-child(2) { animation-delay: calc(var(--gap) * 5.6); }
.xt-content .xt-tag:nth-child(3) { animation-delay: calc(var(--gap) * 6.2); }

/* ═════════ 中部 ═════════ */

/* ★【可改】外文引用（斜体，从左往右印出） */
.xt-content .xt-text-quoteForeign {
  top: 23.5%;
  left: 5%;
  width: 66%;
  font-family: var(--f-latin);
  font-style: italic;
  font-weight: 500;
  font-size: 0.86em;
  color: var(--c-black);
  text-shadow: none;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
  animation-name: typeIn;
  animation-duration: 1.6s;
  animation-delay: calc(var(--gap) * 6);
}

/* ★【可改】char 语录 */
.xt-content .xt-text-charLine {
  top: 31.5%;
  right: 5%;
  max-width: 72%;
  text-align: right;
  font-size: 1.15em;
  color: var(--c-white);
  animation-delay: calc(var(--gap) * 7.5);
}
.xt-content .xt-text-charLine::before { content: "“"; }  /* ★【可改】引号 */
.xt-content .xt-text-charLine::after  { content: "”"; }

/* ★【可改】大标题 */
.xt-content .xt-text-title {
  top: 37.5%;
  left: 3%;
  right: 3%;
  text-align: center;
  font-size: 2.7em;
  font-weight: 900;
  line-height: 1.15;
  letter-spacing: 0.06em;
  color: var(--c-title);
  text-shadow: 0 0 1px currentColor, 0.05em 0.06em 0 var(--c-shadow);
  animation-name: popIn;
  animation-duration: var(--t-pop);
  animation-timing-function: cubic-bezier(0.3, 1.4, 0.5, 1);
  animation-delay: calc(var(--gap) * 9);
}
.xt-content .xt-text-title::before { content: "“"; }  /* ★【可改】换成「」也行 */
.xt-content .xt-text-title::after  { content: "”"; }

/* ★【可改】副标题 */
.xt-content .xt-text-subtitle {
  top: 48%;
  left: 4%;
  right: 4%;
  text-align: center;
  font-size: 1.45em;
  font-weight: 900;
  color: var(--c-black);
  text-shadow: 0 0 0.6px currentColor;
  animation-name: popIn;
  animation-duration: var(--t-pop);
  animation-delay: calc(var(--gap) * 10.5);
}

/* ═════════ 下部 ═════════ */

/* ★【可改】中文诗句/名言 */
.xt-content .xt-text-quoteCn {
  top: 54.5%;
  left: 5%;
  width: 66%;
  font-size: 0.86em;
  line-height: 1.4;
  color: var(--c-white);
  display: -webkit-box;
  -webkit-line-clamp: 2;       /* 最多两行，绝不往下撞 */
  -webkit-box-orient: vertical;
  overflow: hidden;
  animation-delay: calc(var(--gap) * 11.5);
}


/* ★【可改】竖排句 1 */
.xt-content .xt-text-vert1 {
  top: 54%;
  right: 5%;
  height: 28%;
  writing-mode: vertical-rl;
  font-size: 1.05em;
  letter-spacing: 0.12em;
  color: var(--c-white);
  animation-name: vertIn;
  animation-duration: 1.4s;
  animation-delay: calc(var(--gap) * 12.5);
}

/* ★【可改】竖排句 2（弱色） */
.xt-content .xt-text-vert2 {
  top: 56.5%;
  right: 13%;
  height: 26%;
  writing-mode: vertical-rl;
  font-size: 1.05em;
  letter-spacing: 0.12em;
  color: var(--c-gray);
  animation-name: vertIn;
  animation-duration: 1.4s;
  animation-delay: calc(var(--gap) * 13.5);
}

/* ★【可改】user 语录 */
.xt-content .xt-text-userLine {
  top: 64%;
  left: 5%;
  width: 64%;
  font-size: 1.25em;
  font-weight: 900;
  color: var(--c-white);
  animation-name: popIn;
  animation-duration: var(--t-pop);
  animation-delay: calc(var(--gap) * 14.5);
}
.xt-content .xt-text-userLine::before { content: "“"; }
.xt-content .xt-text-userLine::after  { content: "”"; }

/* ★【可改】随笔小段 */
.xt-content .xt-text-prose {
  top: 70.5%;
  left: 5%;
  width: 64%;
  font-size: 0.76em;
  font-weight: 500;
  line-height: 1.75;
  color: var(--c-white);
  opacity: 0.92;
  display: -webkit-box;
  -webkit-line-clamp: 4;
  -webkit-box-orient: vertical;
  overflow: hidden;
  animation-delay: calc(var(--gap) * 15.5);
}

/* ★【可改】结尾大句 */
.xt-content .xt-text-ending {
  bottom: 7.5%;
  left: 5%;
  right: 22%;
  font-size: 1.2em;
  font-weight: 900;
  color: var(--c-white);
  animation-delay: calc(var(--gap) * 17);
}

/* ★【可改】落款 */
.xt-content .xt-text-seal {
  bottom: 2.6%;
  left: 5%;
  max-width: 55%;
  font-size: 0.56em;
  font-weight: 500;
  letter-spacing: 0.08em;
  color: var(--c-gray);
  text-shadow: none;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  animation-delay: calc(var(--gap) * 18);
}
.xt-content .xt-text-seal::before { content: "⊕ "; }  /* ★【可改】落款前缀 */

/* ★【可改】印章 */
.xt-content .xt-text-stamp {
  bottom: 4%;
  right: 5%;
  z-index: 3;
  writing-mode: vertical-rl;
  padding: 0.3em 0.18em;
  border: 0.12em solid var(--c-stamp);
  font-size: 0.9em;
  font-weight: 900;
  line-height: 1.1;
  letter-spacing: 0.05em;
  color: var(--c-stamp);
  rotate: -6deg;                       /* ★【可改】印章歪斜角度 */
  animation-name: stampIn;
  animation-duration: 0.55s;
  animation-timing-function: cubic-bezier(0.5, 0, 0.6, 1.4);
  animation-delay: calc(var(--gap) * 19.5);
}

/* ═════════ 「再翻一页」按钮 ═════════ */
.xt-content .xt-action-1 {
  display: block;
  position: absolute;
  bottom: 2.2%;
  right: 17%;
  z-index: 6;
  padding: 0.1em 0.2em;
  font-family: var(--f-song);
  font-size: 0.56em;
  color: var(--c-gray);
  border-bottom: 1px solid var(--c-gray);
  background: none;
  cursor: pointer;
}
.xt-content .xt-action-1::after { content: "↻ 再翻一页"; }  /* ★【可改】按钮文字 */
.xt-content .xt-action-1:focus-visible { outline: 2px solid var(--c-white); outline-offset: 2px; }

/* 点击后切换到同款“副本”动画，重新播放一遍 */
#xt-t1:checked ~ .xt-content .xt-text                 { animation-name: inkIn2; }
#xt-t1:checked ~ .xt-content .xt-tag                  { animation-name: popIn2; }
#xt-t1:checked ~ .xt-content .xt-text-bgWord1,
#xt-t1:checked ~ .xt-content .xt-text-bgWord2         { animation-name: ghostIn2; }
#xt-t1:checked ~ .xt-content .xt-text-quoteForeign    { animation-name: typeIn2; }
#xt-t1:checked ~ .xt-content .xt-text-title,
#xt-t1:checked ~ .xt-content .xt-text-subtitle,
#xt-t1:checked ~ .xt-content .xt-text-userLine        { animation-name: popIn2; }
#xt-t1:checked ~ .xt-content .xt-text-vert1,
#xt-t1:checked ~ .xt-content .xt-text-vert2           { animation-name: vertIn2; }
#xt-t1:checked ~ .xt-content .xt-text-stamp           { animation-name: stampIn2; }

/* ═════════ 动画 ═════════ */
@keyframes inkIn  { from { opacity: 0; filter: blur(0.25em); } 60% { opacity: 0.85; } to { opacity: 1; filter: blur(0); } }
@keyframes inkIn2 { from { opacity: 0; filter: blur(0.25em); } 60% { opacity: 0.85; } to { opacity: 1; filter: blur(0); } }

@keyframes popIn  { 0% { opacity: 0; transform: scale(1.5); filter: blur(0.2em); } 55% { opacity: 1; transform: scale(0.94); filter: blur(0); } 78% { transform: scale(1.03); } 100% { opacity: 1; transform: scale(1); } }
@keyframes popIn2 { 0% { opacity: 0; transform: scale(1.5); filter: blur(0.2em); } 55% { opacity: 1; transform: scale(0.94); filter: blur(0); } 78% { transform: scale(1.03); } 100% { opacity: 1; transform: scale(1); } }

@keyframes ghostIn  { from { opacity: 0; transform: translateY(0.04em); } to { opacity: 1; transform: none; } }
@keyframes ghostIn2 { from { opacity: 0; transform: translateY(0.04em); } to { opacity: 1; transform: none; } }

@keyframes vertIn  { from { opacity: 0.3; clip-path: inset(0 0 100% 0); } to { opacity: 1; clip-path: inset(0 0 0 0); } }
@keyframes vertIn2 { from { opacity: 0.3; clip-path: inset(0 0 100% 0); } to { opacity: 1; clip-path: inset(0 0 0 0); } }

@keyframes typeIn  { from { clip-path: inset(0 100% 0 0); } to { clip-path: inset(0 0 0 0); } }
@keyframes typeIn2 { from { clip-path: inset(0 100% 0 0); } to { clip-path: inset(0 0 0 0); } }

@keyframes stampIn  { 0% { opacity: 0; transform: scale(2.2); } 60% { opacity: 1; transform: scale(0.92); } 100% { opacity: 1; transform: scale(1); } }
@keyframes stampIn2 { 0% { opacity: 0; transform: scale(2.2); } 60% { opacity: 1; transform: scale(0.92); } 100% { opacity: 1; transform: scale(1); } }

/* 系统开了“减少动态效果”时直接显示 */
@media (prefers-reduced-motion: reduce) {
  .xt-content .xt-text,
  .xt-content .xt-tag { animation: none !important; }
}

value.layout:
# ═══════════════════════════════════════
#  构成 · 朱砂拓本  v1
#  ★ 每个元素的位置/大小/颜色都在 CSS 里改
#  ★ 越往下写的元素，图层越靠上
# ═══════════════════════════════════════

# ── 底层：淡化背景大字 ──
@text bgWord1
@text bgWord2

# ── 上部碎句 + 标签 ──
@text fragA
⁣‌⁠⁠​⁠⁠⁠‌‍‍​​​⁠‍⁠‌‌​‍‍‍‌‌​‌⁠‍⁠⁠‍‌​⁠⁠‍⁠‌‍‌‍⁠​⁠⁠⁠⁠‍​⁠‍‍​​‌‍⁠‌⁠‍​​‌‍⁣@text fragB
@tags
  tag1
  tag2
  tag3

# ── 中部：外文引用 / char语录 / 大标题 ──
@text quoteForeign
@text charLine
@text title
@text subtitle

# ── 下部：诗句 / 竖排 / user语录 / 随笔 ──
@text quoteCn
@text vert1
@text vert2
@text userLine
@text prose

# ── 落款 + 印章 ──
@text ending
@text seal
@text stamp

# ── 「再翻一页」按钮：点一下全部重新浮现 ──
@toggle 1

value.customCss:
@import url('https://fonts.googleapis.com/css2?family=Noto+Serif+SC:wght@400;600;700&display=swap');

.xt-root {
    --xt-bg: #fff;
    --xt-text: #625a55;
    --xt-text-sub: #928781;
    --xt-text-muted: #b8aea8;
    --xt-accent: #c94a50;
    --xt-border: #eee4df;
    --xt-font: 'Noto Serif SC', serif;

    position: relative;
    isolation: isolate;
    max-height: 560px;
    padding: 0;
    overflow: hidden;
    border: 1px solid #f3eeeb;
    border-radius: 28px;
    background: #fff;
    box-shadow: 0 14px 36px rgba(112, 82, 70, 0.13);
}

/*⁣‌⁠⁠​⁠⁠⁠‌‍‍​​​⁠‍⁠‌‌​‍‍‍‌‌​‌⁠‍⁠⁠‍‌​⁠⁠‍⁠‌‍‌‍⁠​⁠⁠⁠⁠‍​⁠‍‍​​‌‍⁠‌⁠‍​​‌‍⁣ 厚实、连续、不规则的屋檐积雪 */
.xt-root::before {
    content: "";
    position: absolute;
    z-index: 8;
    top: 0;
    left: 0;
    right: 0;
    height: 44px;
    pointer-events: none;
    background:
        radial-gradient(ellipse 44px 25px at 0 9px, #fff 98%, transparent 100%),
        radial-gradient(ellipse 52px 29px at 8% 11px, #fff 98%, transparent 100%),
        radial-gradient(ellipse 64px 31px at 25% 8px, #fff 98%, transparent 100%),
        radial-gradient(ellipse 48px 27px at 43% 12px, #fff 98%, transparent 100%),
        radial-gradient(ellipse 62px 30px at 61% 9px, #fff 98%, transparent 100%),
        radial-gradient(ellipse 53px 28px at 79% 12px, #fff 98%, transparent 100%),
        radial-gradient(ellipse 64px 31px at 96% 8px, #fff 98%, transparent 100%),
        radial-gradient(ellipse 42px 24px at 100% 10px, #fff 98%, transparent 100%),
        linear-gradient(#fff 0 13px, transparent 14px);
    filter:
        drop-shadow(0 2px 1px rgba(255, 255, 255, 0.95))
        drop-shadow(0 6px 4px rgba(116, 91, 79, 0.2));
}

.xt-root::after {
    content: none;
}

/* 内容区域：隐藏滚动条但保留滚动 */
.xt-content {
    position: relative;
    z-index: 1;
    max-height: 560px;
    overflow-y: auto;
    padding: 46px 26px 22px;
    scrollbar-width: none;
    -ms-overflow-style: none;
}

.xt-content::-webkit-scrollbar {
    display: none;
    width: 0;
    height: 0;
}

.xt-text {
    background: transparent;
}

/* 角色头部 */
.xt-header {
    gap: 11px;
    margin-bottom: 22px;
}

.xt-avatar {
    border: 3px solid #fff;
    box-shadow:
        0 0 0 2px rgba(201, 74, 80, 0.3),
        0 5px 14px rgba(112, 82, 70, 0.14);
}

.xt-name {
    color: #574c47;
    font-weight: 600;
}

/* 社媒说说 */
.xt-quote {
    position: relative;
    padding: 8px 20px;
    color: #514944;
    background: transparent;
    font-size: 21px;
    font-weight: 600;
    line-height: 1.75;
    text-align: center;
}

.xt-quote::before,
.xt-quote::after {
    position: absolute;
    color: rgba(201, 74, 80, 0.4);
    font-size: 44px;
    line-height: 1;
}

.xt-quote::before {
    content: "“";
    top: -12px;
    left: 0;
}

.xt-quote::after {
    content: "”";
    right: 0;
    bottom: -22px;
}

/* 雪点分隔线 */
.xt-divider {
    position: relative;
    height: 22px;
    margin: 9px 0;
    border: 0;
    background:
        radial-gradient(
            circle,
            rgba(190, 174, 166, 0.55) 1.3px,
            transparent 1.8px
        )
        center / 14px 14px repeat-x;
}

.xt-divider::after {
    content: "❄";
    position: absolute;
    top: 50%;
    left: 50%;
    padding: 0 9px;
    color: #c94a50;
    background: #fff;
    font-size: 13px;
    transform: translate(-50%, -50%);
}

/* 日语天气 */
.xt-text-weatherJp {
    padding: 2px 10px 5px;
    color: #514944;
    font-size: 15px;
    font-weight: 600;
    line-height: 1.7;
    text-align: center;
}

.xt-text-weatherJp::before {
    content: "今日の天気";
    display: block;
    margin-bottom: 4px;
    color: #b85c5d;
    font-size: 10px;
    font-weight: 400;
}

/* 读完回复后的体感 */
.xt-text-bodyFeelLabel {
    padding: 5px 0 0;
    color: #aa625e;
    font-size: 10px;
    text-align: center;
}

.xt-text-bodyFeel {
    padding: 2px 14px 4px;
    color: #766c66;
    font-size: 14px;
    font-style: italic;
    line-height: 1.8;
    text-align: center;
}

/* 正在收听 */
.xt-text-nowLabel {
    padding: 0;
    color: #b85c5d;
    font-size: 11px;
    text-align: center;
}

.xt-text-nowLabel::before {
    content: "♪ ";
}

.xt-text-nowPlaying {
    padding: 4px 0 2px;
    color: #514944;
    font-size: 16px;
    font-weight: 600;
    text-align: center;
}

.xt-marquee {
    margin-top: 2px;
    background: transparent;
}

.xt-marquee-inner {
    color: #b85c5d;
    font-size: 14px;
    font-style: italic;
}

/* 冬日邀约 */
.xt-text-winterPlanLabel {
    padding: 0;
    color: #aa625e;
    font-size: 10px;
    text-align: center;
}

.xt-text-winterPlan {
    padding: 5px 12px;
    color: #625852;
    font-size: 14px;
    line-height: 1.9;
    text-align: center;
}

.xt-text-winterPlan::before {
    content: "❄ ";
    color: #c94a50;
}

/* 悄悄话 */
.xt-text-whisperLabel {
    padding: 0;
    color: #a39790;
    font-size: 11px;
    text-align: center;
}

.xt-text-whisperLabel::before {
    content: "— ";
}

.xt-text-whisperLabel::after {
    content: " —";
}

.xt-text-secretWhisper {
    padding: 4px 16px 0;
    color: #6e625c;
    font-size: 14px;
    font-style: italic;
    line-height: 1.9;
    text-align: center;
}

/* 折叠模块基础 */
.xt-collapse {
    position: relative;
    margin: 14px 0;
    overflow: hidden;
    border: 1px solid #eee3dd;
    border-radius: 12px;
    background: #fffdfb;
    box-shadow: 0 4px 11px rgba(112, 82, 70, 0.07);
}

/* 顶栏保留为点击区域 */
.xt-collapse-header {
    position: relative;
    display: block;
    box-sizing: border-box;
    min-height: 42px;
    padding: 0;
    overflow: hidden;
    border: 0;
    color: transparent;
    background: #fffaf7;
    font-size: 0;
    line-height: 0;
}

.xt-collapse-header * {
    visibility: hidden;
}

/* 童话：横向书脊 */
.xt-collapse-1 {
    border-color: #eadbd5;
    background: #fffaf7;
}

.xt-collapse-1 .xt-collapse-header {
    height: 46px;
    background:
        linear-gradient(
            145deg,
            transparent 49.4%,
            #f0e2dc 50%
        ) left bottom / 50% 19px no-repeat,
        linear-gradient(
            215deg,
            transparent 49.4%,
            #f0e2dc 50%
        ) right bottom / 50% 19px no-repeat,
        linear-gradient(#fffaf7, #fffaf7);
}

.xt-collapse-1 .xt-collapse-header::after {
    content: "";
    position: absolute;
    z-index: 2;
    left: 50%;
    bottom: 7px;
    width: 7px;
    height: 7px;
    border: 1px solid #d8aaa0;
    border-radius: 50%;
    background: #fffaf7;
    transform: translateX(-50%);
}

/* 食谱：暖白托盘 */
.xt-collapse-2 {
    border-color: #eadbd1;
    background: #fff9f3;
    box-shadow:
        0 4px 11px rgba(112, 82, 70, 0.07),
        inset 0 0 0 3px rgba(255, 255, 255, 0.75);
}

.xt-collapse-2 .xt-collapse-header {
    height: 48px;
    margin: 4px;
    border: 1px solid #ead6ca;
    border-radius: 8px;
    background: linear-gradient(180deg, #fffaf5, #f8eee6);
    box-shadow: inset 0 1px 0 #fff;
}

.xt-collapse-2 .xt-collapse-header::after {
    content: "";
    position: absolute;
    left: 50%;
    bottom: 8px;
    width: 25px;
    height: 3px;
    border-radius: 999px;
    background: #c9917b;
    transform: translateX(-50%);
}
/* 关闭时隐藏正文，保留折叠栏 */
.xt-collapse-body {
    box-sizing: border-box;
    max-height: 0 !important;
    margin: 0 !important;
    padding-top: 0 !important;
    padding-bottom: 0 !important;
    overflow: hidden !important;
    visibility: hidden;
    opacity: 0;
    border-top: 0 !important;
    transition:
        max-height 0.35s ease,
        opacity 0.25s ease,
        padding 0.25s ease;
}

/* 展开童话正文 */
#xt-t1:checked ~ .xt-content .xt-collapse-1 .xt-collapse-body {
    max-height: 600px !important;
    margin: 0 !important;
    padding: 15px 18px 17px !important;
    overflow: visible !important;
    visibility: visible;
    opacity: 1;
    border-top: 1px solid #f0e3dd !important;
}

/* 展开食谱正文 */
#xt-t2:checked ~ .xt-content .xt-collapse-2 .xt-collapse-body {
    max-height: 600px !important;
    margin: 0 9px 9px !important;
    padding: 14px 13px !important;
    overflow: visible !important;
    visibility: visible;
    opacity: 1;
}

/* 童话正文：暖白故事页 */
.xt-collapse-1 .xt-collapse-body {
    background:
        linear-gradient(90deg, #f6e9e5 0 3px, transparent 3px),
        #fffdfb;
}

.xt-collapse-1 .xt-collapse-body::before {
    content: "冬夜故事  /  WINTER STORY";
    display: block;
    margin-bottom: 11px;
    padding-bottom: 7px;
    border-bottom: 1px solid #f0e6e1;
    color: #b16b67;
    font-size: 10px;
    letter-spacing: 2px;
    line-height: 1.6;
    text-align: center;
}

.xt-text-taleTitle {
    padding: 3px 8px 4px;
    color: #73514d;
    background: transparent;
    font-size: 16px;
    font-weight: 600;
    line-height: 1.8;
    text-align: center;
}

.xt-text-taleTitle::before {
    content: "「";
    color: #c27670;
}

.xt-text-taleTitle::after {
    content: "」";
    color: #c27670;
}

.xt-text-taleSource {
    padding: 0 0 11px;
    color: #a39790;
    background: transparent;
    font-size: 11px;
    text-align: center;
}

.xt-text-taleExcerpt {
    margin: 0;
    padding: 8px 3px 4px;
    border: 0;
    color: #625852;
    background: transparent;
    font-size: 13px;
    line-height: 2;
}

/* 食谱正文：暖色配方纸 */
.xt-collapse-2 .xt-collapse-body {
    border: 1px solid #efdfd4;
    border-radius: 7px;
    background:
        repeating-linear-gradient(
            to bottom,
            transparent 0 28px,
            rgba(204, 151, 126, 0.1) 28px 29px
        ),
        #fffdf9;
}

.xt-collapse-2 .xt-collapse-body::before {
    content: "冬日点心配方";
    display: block;
    width: fit-content;
    margin: 0 auto 10px;
    padding: 4px 12px;
    border: 1px solid #ead2c8;
    border-radius: 999px;
    color: #a7655d;
    background: #fff;
    font-size: 10px;
    letter-spacing: 2px;
    line-height: 1.6;
}

.xt-text-recipeTitle {
    margin: 0 2px 10px;
    padding: 3px 8px 9px;
    border-bottom: 1px solid #eeded6;
    color: #73514d;
    background: transparent;
    font-size: 16px;
    font-weight: 600;
    line-height: 1.7;
    text-align: center;
}

.xt-text-recipeIngredients,
.xt-text-recipeSteps {
    padding: 5px 8px;
    color: #625852;
    background: transparent;
    font-size: 13px;
    line-height: 1.95;
    white-space: pre-line;
}

.xt-text-recipeIngredients::before {
    content: "材料与用量";
    display: block;
    margin: 0 0 5px;
    padding-bottom: 4px;
    border-bottom: 1px dotted #dfb9ac;
    color: #ad625b;
    font-size: 11px;
    letter-spacing: 1px;
}

.xt-text-recipeSteps::before {
    content: "一起动手";
    display: block;
    margin: 9px 0 5px;
    padding-bottom: 4px;
    border-bottom: 1px dotted #dfb9ac;
    color: #ad625b;
    font-size: 11px;
    letter-spacing: 1px;
}

/* 雪花粒子 */
.xt-particles-snow .xt-particle {
    background: #fff;
    box-shadow: 0 0 5px rgba(255, 255, 255, 0.95);
}

/* 底部 */
.xt-footer {
    padding: 10px 0 4px;
    color: #b8aea8;
    font-size: 10px;
}
/* 童话：完整的横向书脊 */
.xt-collapse-1 .xt-collapse-header {
    height: 60px;
    min-height: 60px;
    margin: 0;
    padding: 0;
    border: 0;
    border-radius: 10px;
    background:
        linear-gradient(
            90deg,
            #c98b80 0 5px,
            #f6e7e1 5px 8px,
            transparent 8px calc(100% - 8px),
            #f6e7e1 calc(100% - 8px) calc(100% - 5px),
            #c98b80 calc(100% - 5px)
        ),
        linear-gradient(#d4a198, #d4a198) 13px 9px / calc(100% - 26px) 1px no-repeat,
        linear-gradient(#d4a198, #d4a198) 13px calc(100% - 9px) / calc(100% - 26px) 1px no-repeat,
        linear-gradient(180deg, #fffaf7, #f1e1db);
    box-shadow:
        inset 0 2px 0 rgba(255, 255, 255, 0.95),
        inset 0 -4px 0 rgba(177, 122, 110, 0.12);
}

.xt-collapse-1 .xt-collapse-header::before {
    content: "";
    position: absolute;
    inset: 14px 24px;
    border: 1px solid rgba(181, 123, 111, 0.38);
    border-radius: 4px;
    box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.75);
    pointer-events: none;
}

.xt-collapse-1 .xt-collapse-header::after {
    content: "";
    position: absolute;
    top: 50%;
    left: 50%;
    width: 14px;
    height: 14px;
    border: 1px solid rgba(181, 123, 111, 0.4);
    border-radius: 50%;
    background: #fffaf7;
    box-shadow: 0 0 0 4px rgba(255, 250, 247, 0.55);
    transform: translate(-50%, -50%);
    pointer-events: none;
}

/* 食谱：放着三块饼干的暖白托盘 */
.xt-collapse-2 .xt-collapse-header {
    position: relative;
    height: 68px;
    min-height: 68px;
    margin: 0;
    padding: 0;
    border: 0;
    border-radius: 10px;
    background:
        linear-gradient(#ead8cb, #ead8cb) 9px 8px / calc(100% - 18px) 1px no-repeat,
        linear-gradient(#ead8cb, #ead8cb) 9px calc(100% - 8px) / calc(100% - 18px) 1px no-repeat,
        linear-gradient(90deg, #ead8cb, #ead8cb) 9px 8px / 1px calc(100% - 16px) no-repeat,
        linear-gradient(90deg, #ead8cb, #ead8cb) calc(100% - 9px) 8px / 1px calc(100% - 16px) no-repeat,
        linear-gradient(180deg, #fffdf9, #f8eee5);
    box-shadow:
        inset 0 2px 0 rgba(255, 255, 255, 0.95),
        inset 0 -3px 0 rgba(205, 158, 135, 0.12);
}

/* 三块独立圆饼干与烘焙色外圈 */
.xt-collapse-2 .xt-collapse-header::before {
    content: "";
    position: absolute;
    top: 50%;
    left: 50%;
    width: 78px;
    height: 32px;
    background:
        radial-gradient(circle at 15% 36%, #82513e 0 1px, transparent 1.5px),
        radial-gradient(circle at 27% 66%, #82513e 0 1px, transparent 1.5px),
        radial-gradient(circle at 51% 30%, #82513e 0 1px, transparent 1.5px),
        radial-gradient(circle at 62% 68%, #82513e 0 1px, transparent 1.5px),
        radial-gradient(circle at 82% 38%, #82513e 0 1px, transparent 1.5px),
        radial-gradient(circle at 92% 65%, #82513e 0 1px, transparent 1.5px),
        radial-gradient(circle at 17% 50%, #e9c19f 0 9px, #c58b69 9.5px 11px, transparent 11.5px),
        radial-gradient(circle at 50% 50%, #efd0af 0 9px, #c58b69 9.5px 11px, transparent 11.5px),
        radial-gradient(circle at 83% 50%, #e9c19f 0 9px, #c58b69 9.5px 11px, transparent 11.5px);
    filter: drop-shadow(0 2px 1px rgba(145, 98, 73, 0.2));
    transform: translate(-50%, -50%);
    pointer-events: none;
}

.xt-collapse-2 .xt-collapse-header::after {
    content: "";
    position: absolute;
    left: 50%;
    bottom: 7px;
    width: 26px;
    height: 3px;
    border-radius: 999px;
    background: #c9917b;
    transform: translateX(-50%);
    pointer-events: none;
}

