value.customCss:
/*⁣‌⁠⁠​⁠⁠⁠‌‍‍​​​⁠‍⁠‌‌​‍‍‍‌‌​‌⁠‍⁠⁠‍‌​⁠⁠‍⁠‌‍‌‍⁠​⁠⁠⁠⁠‍​⁠‍‍​​‌‍⁠‌⁠‍​​‌‍⁣ ╔════════════════════════════════════════════╗
   ║   构成 · 白灰底图版（轻雾淡墨修订版）          ║
   ║   去掉死黑与重描边，整体改为冷淡铅灰调          ║
   ║   ★【可改】= Ctrl+F 搜「★」即可找到可改项     ║
   ╚════════════════════════════════════════════╝ */

@import url('https://fonts.googleapis.com/css2?family=Noto+Serif+SC:wght@300;400;500;700&family=Noto+Serif:ital,wght@0,400;1,400&display=swap');

.xt-root {
  /* ████████ ★【可改】轻雾淡墨配色（想更淡可把前三个色号再往 #888 靠） ████████ */
  --bg-img:      url("https://a1.boltp.com/2026/10/28/6ae1c3a93ca66.jpg");
  --c-bg:        #eaeced;
  --c-white:     #555b65;                  /* 主字色：淡铅笔灰（原为纯黑） */
  --c-title:     #3e434c;                  /* 大标题：深雾灰，唯一稍微压得住场的一处 */
  --c-black:     #767d88;                  /* 对比字色：冷雾灰（副标题/外文） */
  --c-gray:      #939aa5;                  /* 弱字色：淡银灰（右上碎句/竖排2/落款） */
  --c-ghost:     rgba(90, 100, 115, 0.065);/* 背景大字：极淡水印 */
  --c-stamp:     rgba(110, 118, 130, 0.65);/* 印章：半透淡灰印 */
  --c-tag-bg:    rgba(120, 128, 140, 0.13);/* 标签：磨砂浅灰底（不再是黑块） */
  --c-tag-text:  #636a75;                  /* 标签字色 */
  --c-shadow:    rgba(255, 255, 255, 0.75);/* 柔和白光托底，隔开水滴纹理 */

  /* ████████ ★【可改】字体 ████████ */
  --f-song: "MyInkSong", "Noto Serif SC", "Source Han Serif SC", "Songti SC", "SimSun", serif;
  --f-latin: "Noto Serif", "Times New Roman", var(--f-song);

  /* ████████ ★【可改】动画节奏 ████████ */
  --t-ink: 1.25s;
  --t-pop: 0.9s;
  --gap: 0.18s;

  --xt-bg: var(--c-bg);
  --xt-text: var(--c-white);
  --xt-font: var(--f-song);

  position: relative;
  width: 100%;
  height: auto;
  aspect-ratio: 3 / 4;
  padding: 0 !important;
  overflow: hidden;
  background:
    linear-gradient(180deg, rgba(250,251,252,0.38) 0%, rgba(242,244,247,0.52) 100%),
    var(--bg-img) center / cover no-repeat,
    var(--c-bg);
  border: none;
  border-radius: 4px;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.1);
  container-type: inline-size;
  font-family: var(--f-song);
}

/* 去掉了显得脏的深色麻点网格，只留一圈极轻的雾白柔光边 */
.xt-root::after {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 5;
  pointer-events: none;
  background: radial-gradient(120% 95% at 50% 48%, transparent 62%, rgba(160, 168, 178, 0.16) 100%);
}

.xt-content {
  position: absolute !important;
  inset: 0;
  display: block !important;
  margin: 0 !important;
  padding: 0 !important;
  font-size: 16px;
  font-size: 4cqw;
}

/* 公共文字样式：字重降为 400，去掉加粗描边 */
.xt-content .xt-text,
.xt-content .xt-tags {
  position: absolute;
  z-index: 2;
  margin: 0;
  padding: 0;
  background: none;
  border: 0;
  border-radius: 0;
  box-shadow: none;
  font-family: var(--f-song);
  font-weight: 400;
  line-height: 1.5;
  white-space: pre-line;
  text-shadow: 0 1px 6px var(--c-shadow);
  animation: inkIn var(--t-ink) cubic-bezier(0.2, 0.7, 0.2, 1) both;
}

.xt-spacer, .xt-divider, .xt-footer { display: none; }

/* ═════════ 底层：背景淡化大字 ═════════ */
.xt-content .xt-text-bgWord1 {
  top: -2%;
  right: -1%;
  z-index: 0;
  writing-mode: vertical-rl;
  font-size: 6.2em;
  font-weight: 700;
  line-height: 1;
  letter-spacing: -0.04em;
  color: var(--c-ghost);
  text-shadow: none;
  animation-name: ghostIn;
  animation-duration: 2.4s;
}

.xt-content .xt-text-bgWord2 {
  bottom: 12%;
  left: -3%;
  z-index: 0;
  font-size: 5.2em;
  font-weight: 700;
  line-height: 1;
  white-space: nowrap;
  color: var(--c-ghost);
  text-shadow: none;
  animation-name: ghostIn;
  animation-duration: 2.4s;
  animation-delay: calc(var(--gap) * 2);
}

/* ═════════ 上部 ═════════ */
.xt-content .xt-text-fragA {
  top: 4%;
  left: 5%;
  width: 54%;
  font-size: 0.8em;
  font-weight: 400;
  letter-spacing: 0.03em;
  color: var(--c-white);
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
  animation-delay: calc(var(--gap) * 3);
}

.xt-content .xt-text-fragB {
  top: 4.5%;
  right: 5%;
  width: 34%;
  text-align: right;
  font-size: 0.75em;
  font-weight: 300;
  letter-spacing: 0.03em;
  color: var(--c-gray);
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
  animation-delay: calc(var(--gap) * 4);
}

/* 标签：半透明雾灰底 + 细边框 */
.xt-content .xt-tags {
  top: 18%;
  left: 5%;
  display: flex;
  flex-wrap: wrap;
  gap: 0.4em;
  animation: none;
}
.xt-content .xt-tag {
  margin: 0;
  padding: 0.12em 0.55em;
  border: 0.5px solid rgba(110, 118, 130, 0.25);
  border-radius: 2px;
  background: var(--c-tag-bg);
  backdrop-filter: blur(3px);
  color: var(--c-tag-text);
  font-family: var(--f-song);
  font-size: 0.6em;
  font-weight: 400;
  letter-spacing: 0.1em;
  text-shadow: none;
  animation: popIn var(--t-pop) cubic-bezier(0.25, 1, 0.5, 1) both;
}
.xt-content .xt-tag::before { content: "# "; opacity: 0.5; }
.xt-content .xt-tag:nth-child(1) { animation-delay: calc(var(--gap) * 5); }
.xt-content .xt-tag:nth-child(2) { animation-delay: calc(var(--gap) * 5.6); }
.xt-content .xt-tag:nth-child(3) { animation-delay: calc(var(--gap) * 6.2); }

/* ═════════ 中部 ═════════ */
.xt-content .xt-text-quoteForeign {
  top: 23%;
  left: 5%;
  width: 68%;
  font-family: var(--f-latin);
  font-style: italic;
  font-weight: 400;
  font-size: 0.84em;
  color: var(--c-black);
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
  animation-name: typeIn;
  animation-duration: 1.6s;
  animation-delay: calc(var(--gap) * 6);
}

.xt-content .xt-text-charLine {
  top: 31%;
  right: 5%;
  max-width: 75%;
  text-align: right;
  font-size: 1.08em;
  font-weight: 500;
  letter-spacing: 0.04em;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  color: var(--c-white);
  animation-delay: calc(var(--gap) * 7.5);
}
.xt-content .xt-text-charLine::before { content: "“"; opacity: 0.65; }
.xt-content .xt-text-charLine::after  { content: "”"; opacity: 0.65; }

/* 大标题：700 适中字重，不再死黑粗重 */
.xt-content .xt-text-title {
  top: 37%;
  left: 3%;
  right: 3%;
  text-align: center;
  font-size: 2.55em;
  font-weight: 700;
  line-height: 1.15;
  letter-spacing: 0.08em;
  white-space: nowrap;
  color: var(--c-title);
  text-shadow: 0 2px 12px var(--c-shadow);
  animation-name: popIn;
  animation-duration: var(--t-pop);
  animation-timing-function: cubic-bezier(0.25, 1, 0.5, 1);
  animation-delay: calc(var(--gap) * 9);
}
.xt-content .xt-text-title::before { content: "“"; font-weight: 400; opacity: 0.55; }
.xt-content .xt-text-title::after  { content: "”"; font-weight: 400; opacity: 0.55; }

.xt-content .xt-text-subtitle {
  top: 47.5%;
  left: 4%;
  right: 4%;
  text-align: center;
  font-size: 1.28em;
  font-weight: 500;
  letter-spacing: 0.08em;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  color: var(--c-black);
  animation-name: popIn;
  animation-duration: var(--t-pop);
  animation-delay: calc(var(--gap) * 10.5);
}

/* ═════════ 下部 ═════════ */
.xt-content .xt-text-quoteCn {
  top: 54.5%;
  left: 5%;
  width: 66%;
  font-size: 0.84em;
  font-weight: 400;
  line-height: 1.45;
  color: var(--c-black);
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
  animation-delay: calc(var(--gap) * 11.5);
}

.xt-content .xt-text-vert1 {
  top: 54%;
  right: 5%;
  height: 28%;
  writing-mode: vertical-rl;
  font-size: 1.02em;
  font-weight: 500;
  letter-spacing: 0.14em;
  color: var(--c-white);
  animation-name: vertIn;
  animation-duration: 1.4s;
  animation-delay: calc(var(--gap) * 12.5);
}

.xt-content .xt-text-vert2 {
  top: 56.5%;
  right: 13%;
  height: 26%;
  writing-mode: vertical-rl;
  font-size: 1.02em;
  font-weight: 300;
  letter-spacing: 0.14em;
  color: var(--c-gray);
  animation-name: vertIn;
  animation-duration: 1.4s;
  animation-delay: calc(var(--gap) * 13.5);
}

.xt-content .xt-text-userLine {
  top: 63.8%;
  left: 5%;
  width: 66%;
  font-size: 1.15em;
  font-weight: 500;
  letter-spacing: 0.04em;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  color: var(--c-white);
  animation-name: popIn;
  animation-duration: var(--t-pop);
  animation-delay: calc(var(--gap) * 14.5);
}
.xt-content .xt-text-userLine::before { content: "“"; opacity: 0.65; }
.xt-content .xt-text-userLine::after  { content: "”"; opacity: 0.65; }

.xt-content .xt-text-prose {
  top: 70.2%;
  left: 5%;
  width: 64%;
  font-size: 0.74em;
  font-weight: 300;
  line-height: 1.75;
  letter-spacing: 0.03em;
  color: var(--c-white);
  opacity: 0.88;
  display: -webkit-box;
  -webkit-line-clamp: 4;
  -webkit-box-orient: vertical;
  overflow: hidden;
  animation-delay: calc(var(--gap) * 15.5);
}

.xt-content .xt-text-ending {
  bottom: 7.5%;
  left: 5%;
  right: 22%;
  font-size: 1.12em;
  font-weight: 500;
  letter-spacing: 0.06em;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  color: var(--c-title);
  animation-delay: calc(var(--gap) * 17);
}

.xt-content .xt-text-seal {
  bottom: 2.6%;
  left: 5%;
  max-width: 55%;
  font-size: 0.55em;
  font-weight: 300;
  letter-spacing: 0.08em;
  color: var(--c-gray);
  text-shadow: none;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  animation-delay: calc(var(--gap) * 18);
}
.xt-content .xt-text-seal::before { content: "⊕ "; }

.xt-content .xt-text-stamp {
  bottom: 4%;
  right: 5%;
  z-index: 3;
  writing-mode: vertical-rl;
  padding: 0.3em 0.18em;
  border: 0.08em solid var(--c-stamp);
  font-size: 0.86em;
  font-weight: 500;
  line-height: 1.1;
  letter-spacing: 0.08em;
  color: var(--c-stamp);
  rotate: -6deg;
  animation-name: stampIn;
  animation-duration: 0.55s;
  animation-timing-function: cubic-bezier(0.5, 0, 0.6, 1.4);
  animation-delay: calc(var(--gap) * 19.5);
}

.xt-content .xt-action-1 {
  display: block;
  position: absolute;
  bottom: 2.2%;
  right: 17%;
  z-index: 6;
  padding: 0.1em 0.2em;
  font-family: var(--f-song);
  font-size: 0.54em;
  color: var(--c-gray);
  border-bottom: 0.5px solid var(--c-gray);
  background: none;
  cursor: pointer;
}
.xt-content .xt-action-1::after { content: "↻ 再翻一页"; }

#xt-t1:checked ~ .xt-content .xt-text                 { animation-name: inkIn2; }
#xt-t1:checked ~ .xt-content .xt-tag                  { animation-name: popIn2; }
#xt-t1:checked ~ .xt-content .xt-text-bgWord1,
#xt-t1:checked ~ .xt-content .xt-text-bgWord2         { animation-name: ghostIn2; }
#xt-t1:checked ~ .xt-content .xt-text-quoteForeign    { animation-name: typeIn2; }
#xt-t1:checked ~ .xt-content .xt-text-title,
#xt-t1:checked ~ .xt-content .xt-text-subtitle,
#xt-t1:checked ~ .xt-content .xt-text-userLine        { animation-name: popIn2; }
#xt-t1:checked ~ .xt-content .xt-text-vert1,
#xt-t1:checked ~ .xt-content .xt-text-vert2           { animation-name: vertIn2; }
#xt-t1:checked ~ .xt-content .xt-text-stamp           { animation-name: stampIn2; }

@keyframes inkIn  { from { opacity: 0; filter: blur(0.22em); } 60% { opacity: 0.85; } to { opacity: 1; filter: blur(0); } }
@keyframes inkIn2 { from { opacity: 0; filter: blur(0.22em); } 60% { opacity: 0.85; } to { opacity: 1; filter: blur(0); } }
@keyframes popIn  { 0% { opacity: 0; transform: scale(1.18); filter: blur(0.18em); } 100% { opacity: 1; transform: scale(1); filter: blur(0); } }
@keyframes popIn2 { 0% { opacity: 0; transform: scale(1.18); filter: blur(0.18em); } 100% { opacity: 1; transform: scale(1); filter: blur(0); } }
@keyframes ghostIn  { from { opacity: 0; transform: translateY(0.04em); } to { opacity: 1; transform: none; } }
@keyframes ghostIn2 { from { opacity: 0; transform: translateY(0.04em); } to { opacity: 1; transform: none; } }
@keyframes vertIn  { from { opacity: 0.3; clip-path: inset(0 0 100% 0); } to { opacity: 1; clip-path: inset(0 0 0 0); } }
@keyframes vertIn2 { from { opacity: 0.3; clip-path: inset(0 0 100% 0); } to { opacity: 1; clip-path: inset(0 0 0 0); } }
@keyframes typeIn  { from { clip-path: inset(0 100% 0 0); } to { clip-path: inset(0 0 0 0); } }
@keyframes typeIn2 { from { clip-path: inset(0 100% 0 0); } to { clip-path: inset(0 0 0 0); } }
@keyframes stampIn  { 0% { opacity: 0; transform: scale(1.8); } 100% { opacity: 1; transform: scale(1); } }
@keyframes stampIn2 { 0% { opacity: 0; transform: scale(1.8); } 100% { opacity: 1; transform: scale(1); } }

@media (prefers-reduced-motion: reduce) {
  .xt-content .xt-text,
  .xt-content .xt-tag { animation: none !important; }
}

