/* ==========================================
   6. 图片翻转：单击沿对角线翻转，双版文字
========================================== */

/* 保险：干掉旧版写死的 ::after 文字 */
.xt-card:first-of-type::after {
    content: none !important;
    display: none !important;
}

/* 卡片开启透视，不改尺寸 */
.xt-card:first-of-type {
    perspective: 1200px;
    -webkit-perspective: 1200px;
}

/* 正面：原图 */
.xt-card:first-of-type .xt-image {
    transform: rotate3d(1, 1, 0, 0deg);
    transform-origin: center center;
    backface-visibility: hidden;
    -webkit-backface-visibility: hidden;
    transition: transform 0.85s cubic-bezier(0.45, 0.05, 0.25, 1);
    will-change: transform;
    position: relative;
    z-index: 3;
}

/* 深蓝背景层：默认（循环模式）深蓝渐变 */
.xt-card:first-of-type::before {
    content: "" !important;
    display: block !important;
    position: absolute !important;
    top: 20px !important;
    left: 20px !important;
    right: 20px !important;
    aspect-ratio: 1 / 1 !important;
    height: auto !important;
    background: linear-gradient(160deg, #0d2352 0%, #071430 100%) !important;
    border-radius: 12px !important;
    transform: rotate3d(1, 1, 0, 180deg);
    transform-origin: center center;
    backface-visibility: hidden;
    -webkit-backface-visibility: hidden;
    transition: transform 0.85s cubic-bezier(0.45, 0.05, 0.25, 1);
    pointer-events: none;
    z-index: 1;
}

