value.customCss:
/*⁣‌⁠⁠​⁠⁠⁠‌‍‍​​​⁠‍⁠‌‌​‍‍‍‌‌​‌⁠‍⁠⁠‍‌​⁠⁠‍⁠‌‍‌‍⁠​⁠⁠⁠⁠‍​⁠‍‍​​‌‍⁠‌⁠‍​​‌‍⁣ =========================================
匿来我往 · QQ 蓝白磨砂最终版
保留背景图、顶部留白、四组问答与独立折叠
========================================= */

.xt-root {
--qq-background-image: url("https://i.postimg.cc/8CKGf5Xh/IMG-9883.jpg");
--qq-title-space: 190px;

--xt-bg: #eaf3ff;
--xt-text: #293b52;
--xt-text-sub: #6482a8;
--xt-text-muted: #91a4be;
--xt-accent: #438fe9;
--xt-accent-bg: rgba(67,143,233,.10);
--xt-border: rgba(67,143,233,.18);

position: relative;
box-sizing: border-box;
color: var(--xt-text);
background-color: #438fe9 !important;
background-image:
linear-gradient(
to bottom,
rgba(67,143,233,.04),
rgba(67,143,233,.14)
),
var(--qq-background-image) !important;
background-position: center top, center top !important;
background-size: 100% 100%, 100% auto !important;
background-repeat: no-repeat !important;
padding-top: var(--qq-title-space) !important;
}

.xt-root *,
.xt-root *::before,
.xt-root *::after {
box-sizing: border-box;
}

/* 内容区域 */

.xt-content {
position: relative;
z-index: 1;
padding: 0 10px 12px !important;
}

/* 卡片：半透明白色磨砂 */

.xt-card {
position: relative;
background: rgba(255,255,255,.94) !important;
border: 1px solid rgba(255,255,255,.88) !important;
border-radius: 20px !important;
box-shadow: 0 5px 18px rgba(26,73,130,.10) !important;
overflow: hidden;
margin: 0 0 10px !important;
backdrop-filter: blur(10px);
-webkit-backdrop-filter: blur(10px);
}

/* 卡片标题 */

.xt-card-title {
color: #4c86ce !important;
font-size: 14px;
font-weight: 750;
line-height: 1.4;
padding: 9px 12px 4px;
overflow-wrap: anywhere;
}

/* 正文 */

.xt-text {
min-width: 0;
color: #293b52 !important;
line-height: 1.5;
overflow-wrap: anywhere;
word-break: break-word;
}

/* 横向布局：头像与文字并排 */

.xt-row {
display: flex !important;
flex-direction: row !important;
align-items: center !important;
gap: 9px;
padding: 7px 11px;
min-width: 0;
}

.xt-row > * {
min-width: 0;
}

.xt-row .xt-image {
flex: 0 0 32px;
width: 32px;
height: 32px;
margin: 0 !important;
}

.xt-row .xt-text {
flex: 1 1 0;
}

/* 所有图片基础样式 */

.xt-image {
display: block;
width: 34px;
height: 34px;
margin: 6px 10px;
overflow: hidden;
flex-shrink: 0;
}

.xt-image img {
display: block;
width: 100%;
height: 100%;
object-fit: cover;
border-radius: 50%;
border: 2px solid #fff;
box-shadow: 0 2px 8px rgba(52,100,160,.14);
}

/* 角色头像：小尺寸圆形 */

.xt-row .xt-image img {
width: 32px;
height: 32px;
border-radius: 50%;
object-fit: cover;
}

/* 分区标题 */

.xt-section-title {
color: #7198ce !important;
font-size: 12px;
font-weight: 700;
line-height: 1.4;
margin: 6px 11px 3px;
}

/* 引用与心声 */

.xt-quote {
background: #f4f7fc !important;
color: #536d8d !important;
border: 1px solid #e7eef8 !important;
border-radius: 13px;
padding: 8px 10px;
margin: 6px 10px 8px;
line-height: 1.5;
overflow-wrap: anywhere;
word-break: break-word;
}

/* 折叠容器 */

.xt-collapse {
border: 1px solid #d8e8ff !important;
border-radius: 13px;
overflow: hidden;
background: #f2f7ff !important;
margin: 6px 10px 8px;
padding: 0;
}

/* 折叠标题 */

.xt-collapse-header {
display: flex;
align-items: center;
min-height: 0;
margin: 0;
color: #4388df !important;
background: linear-gradient(135deg,#edf5ff,#fff) !important;
padding: 7px 10px;
line-height: 1.4;
font-size: 12px;
font-weight: 650;
}

.xt-collapse-arrow {
color: #438fe9 !important;
}

/* 默认收起心声，避免内容提前露出 */

.xt-collapse-body {
display: block;
box-sizing: border-box;
max-height: 0 !important;
height: auto;
padding: 0 9px !important;
margin: 0;
border: 0;
overflow: hidden !important;
opacity: 0;
transition:
max-height .28s ease,
opacity .2s ease,
padding .2s ease;
}

/* 四个折叠栏分别由对应编号控制 */

#xt-t1:checked ~ .xt-content .xt-collapse-1 .xt-collapse-body,
#xt-t2:checked ~ .xt-content .xt-collapse-2 .xt-collapse-body,
#xt-t3:checked ~ .xt-content .xt-collapse-3 .xt-collapse-body,
#xt-t4:checked ~ .xt-content .xt-collapse-4 .xt-collapse-body {
max-height: 600px !important;
padding: 8px 9px !important;
border-top: 1px solid #e5effc;
opacity: 1;
}

/* 页脚 */

.xt-footer {
color: #fff !important;
text-align: center;
font-size: 10px;
letter-spacing: 2px;
opacity: .95;
padding: 8px 0 12px;
}

/* 手机端 */

@media (max-width: 480px) {
.xt-root {
--qq-title-space: 190px;
}

.xt-card {
border-radius: 18px !important;
margin-bottom: 9px !important;
}

.xt-card-title {
padding: 8px 11px 3px;
}

.xt-content {
padding-left: 9px !important;
padding-right: 9px !important;
}

.xt-row {
gap: 8px;
padding: 6px 10px;
}

.xt-row .xt-image,
.xt-row .xt-image img {
width: 30px;
height: 30px;
}

.xt-section-title {
margin-left: 10px;
margin-right: 10px;
}

.xt-collapse {
border-radius: 12px;
margin: 5px 9px 7px;
}

.xt-collapse-header {
padding: 7px 9px;
}
}

/* =====================================
   匿名问答气泡布局 · 左侧提问 / 右侧回答
===================================== */

/* 气泡整体 */
.xt-bubbles {
  display: flex !important;
  flex-direction: column !important;
  gap: 22px !important;
  width: 100% !important;
  margin: 12px 0 18px !important;
}

/* 左侧：匿名提问 */
.xt-bubble-left {
  position: relative !important;
  display: flex !important;
  align-items: center !important;
  align-self: flex-start !important;
  width: 100% !important;
  max-width: 100% !important;
  padding-left: 48px !important;
  box-sizing: border-box !important;
}

/* 提问者圆形头像 */
.xt-bubble-left::before {
  content: "" !important;
  position: absolute !important;
  left: 0 !important;
  top: 50% !important;
  transform: translateY(-50%) !important;
  width: 38px !important;
  height: 38px !important;
  border-radius: 50% !important;
  background-image: url("https://i.postimg.cc/Y9fgkCcW/IMG-9985(20261029-181623).png") !important;
  background-size: cover !important;
  background-position: center !important;
  background-repeat: no-repeat !important;
  border: 2px solid rgba(255,255,255,.95) !important;
  box-shadow: 0 3px 10px rgba(50,100,160,.16) !important;
  flex-shrink: 0 !important;
}

/* 右侧：TA 的回答 */
.xt-bubble-right {
  display: flex !important;
  align-self: flex-end !important;
  justify-content: flex-end !important;
  width: 100% !important;
  max-width: 88% !important;
  margin-left: auto !important;
  box-sizing: border-box !important;
}

/* 气泡内容 */
.xt-bubble-body {
  min-width: 0 !important;
  max-width: 100% !important;
  padding: 12px 16px !important;
  border-radius: 17px !important;
  line-height: 1.7 !important;
  overflow-wrap: anywhere !important;
  box-sizing: border-box !important;
}

/* 提问气泡 */
.xt-bubble-left .xt-bubble-body {
  width: 100% !important;
  background: rgba(239,245,253,.96) !important;
  color: #293d56 !important;
  border: 1px solid rgba(216,230,249,.9) !important;
  border-top-left-radius: 5px !important;
}

/* 回答气泡 */
.xt-bubble-right .xt-bubble-body {
  background: rgba(239,245,253,.96) !important;
  color: #293d56 !important;
  border: 1px solid rgba(216,230,249,.9) !important;
  border-top-right-radius: 5px !important;
}

/* 左右气泡的小标签 */
.xt-bubble-left .xt-bubble-body::before {
  content: "匿名提问" !important;
  display: block !important;
  color: #7198ce !important;
  font-size: 11px !important;
  font-weight: 700 !important;
  letter-spacing: 1px !important;
  margin-bottom: 5px !important;
}

.xt-bubble-right .xt-bubble-body::before {
  content: "TA 的回答" !important;
  display: block !important;
  color: #4c86ce !important;
  font-size: 11px !important;
  font-weight: 700 !important;
  letter-spacing: 1px !important;
  margin-bottom: 5px !important;
}

/* 手机端 */
@media (max-width: 480px) {
  .xt-bubbles {
    gap: 18px !important;
  }

  .xt-bubble-left {
    padding-left: 44px !important;
  }

  .xt-bubble-left::before {
    width: 35px !important;
    height: 35px !important;
  }

  .xt-bubble-body {
    padding: 10px 13px !important;
    font-size: 14px !important;
  }

  .xt-bubble-right {
    max-width: 88% !important;
  }
}


/* =================================
   右侧回答 + 角色头像并排布局
================================= */

/* 回答气泡整体左移，给头像留出位置 */
.xt-bubble-right {
  width: calc(100% - 58px) !important;
  max-width: 88% !important;
  margin-left: 0 !important;
  margin-right: auto !important;
  transform: translateX(-8px) !important;
}

/* 角色头像区块：向上移动到回答气泡旁边 */
.xt-header {
  display: flex !important;
  flex-direction: row-reverse !important;
  justify-content: flex-start !important;
  align-items: center !important;
  width: auto !important;
  margin-left: auto !important;
  margin-right: 12px !important;
  margin-top: -90px !important;
  margin-bottom: 35px !important;
  position: relative !important;
  z-index: 3 !important;
  gap: 8px !important;
}

/* 角色圆形头像 */
.xt-header .xt-avatar {
  width: 38px !important;
  height: 38px !important;
  min-width: 38px !important;
  border-radius: 50% !important;
  object-fit: cover !important;
  border: 2px solid #ffffff !important;
  box-shadow: 0 3px 12px rgba(52,100,160,.18) !important;
}


/* 手机端微调 */
@media (max-width: 480px) {
  .xt-bubble-right {
    width: calc(100% - 58px) !important;
    max-width: 88% !important;
  }

  .xt-header .xt-avatar {
    width: 38px !important;
    height: 38px !important;
    min-width: 38px !important;
  }
}
/* 隐藏角色名字，只保留角色头像 */
.xt-header .xt-name {
    display: none !important;
}

/* =========================================
   QQ 匿名问答箱 · 系统日夜间自动切换
   日间：原版蓝白磨砂
   夜间：深海军蓝 + 白字 + 浅蓝标题
========================================= */

@media (prefers-color-scheme: dark) {

  /* 主背景：深蓝色，保留原背景图 */
  .xt-root {
    --xt-bg: #101d32;
    --xt-text: #f1f5fc;
    --xt-text-sub: #b4c9e8;
    --xt-text-muted: #91a9ca;
    --xt-accent: #9bc8ff;
    --xt-accent-bg: rgba(126,177,239,.14);
    --xt-border: rgba(155,198,248,.22);

    color: #f1f5fc !important;
    background-color: #142541 !important;
    background-image:
      linear-gradient(
        to bottom,
        rgba(9,20,39,.70),
        rgba(13,30,55,.84)
      ),
      var(--qq-background-image) !important;
    background-position: center top, center top !important;
    background-size: 100% 100%, 100% auto !important;
    background-repeat: no-repeat !important;
  }

  /* 卡片：深蓝磨砂 */
  .xt-card {
    background: rgba(20,36,60,.95) !important;
    border: 1px solid rgba(160,195,235,.22) !important;
    box-shadow: 0 5px 20px rgba(0,0,0,.22) !important;
  }

  /* 卡片标题：浅蓝色 */
  .xt-card-title {
    color: #a9ceff !important;
  }

  /* 所有正文 */
  .xt-text {
    color: #edf4ff !important;
  }

  /* 分区标题 */
  .xt-section-title {
    color: #a9ceff !important;
  }

  /* 引用与心声 */
  .xt-quote {
    background: rgba(42,62,91,.78) !important;
    color: #d4e3f8 !important;
    border: 1px solid rgba(147,184,229,.20) !important;
  }

  /* 折叠容器 */
  .xt-collapse {
    background: rgba(25,44,72,.96) !important;
    border: 1px solid rgba(143,183,232,.30) !important;
  }

  /* 折叠标题 */
  .xt-collapse-header {
    color: #b7d6ff !important;
    background: linear-gradient(
      135deg,
      #203957,
      #172b47
    ) !important;
  }

  .xt-collapse-arrow {
    color: #a9ceff !important;
  }

  /* 展开的心声内容 */
  .xt-collapse-body {
    color: #edf4ff !important;
    border-color: rgba(143,183,232,.22) !important;
  }

  .xt-collapse-body .xt-text,
  .xt-collapse-body .xt-quote {
