/* ══════════════════════════════════════════
   完美切换动画（权重碾压·指哪打哪版）
   ══════════════════════════════════════════ */

/* 1. 初始隐藏偶数卡片 */
.xt-card:nth-of-type(2), 
.xt-card:nth-of-type(4), 
.xt-card:nth-of-type(6) {
  display: none !important;
}

/* 2. 强制卡片作为定位基准 */
.xt-card {
  position: relative !important;
}

/* 3. 暴力穿透：让卡片里的所有文字、图标都不拦截鼠标 */
.xt-card * {
  pointer-events: none !important;
}

/* 4. 用完全相同的权重把开关抢回来，并设为透明最高层 */
.xt-root .xt-action-1, 
.xt-root .xt-action-2, 
.xt-root .xt-action-3 {
  display: block !important; 
  position: absolute !important;
  z-index: 9999999 !important; 
  cursor: pointer !important;
  opacity: 0 !important; 
  margin: 0 !important; 
  padding: 0 !important;
  pointer-events: auto !important; 
}

/* ==========================================
   5. 精准定位：蓝圈和红圈
   ========================================== */
/* 备忘录：覆盖底部工具栏区域（蓝圈） */
.xt-card:nth-of-type(1) .xt-action-1, 
.xt-card:nth-of-type(2) .xt-action-1 {
  bottom: 0 !important; 
  left: 0 !important;
  width: 100% !important; 
  height: 90px !important; 
}

/* 微信：覆盖顶部标题栏（红圈） */
.xt-card:nth-of-type(3) .xt-action-2, 
.xt-card:nth-of-type(4) .xt-action-2 {
  top: 0 !important; 
  left: 0 !important;
  width: 100% !important; 
  height: 60px !important; 
}

/* 论坛：覆盖顶部标题栏 */
.xt-card:nth-of-type(5) .xt-action-3, 
.xt-card:nth-of-type(6) .xt-action-3 {
  top: 0 !important; 
  left: 0 !important;
  width: 100% !important; 
  height: 55px !important;
}

/* ══════════════════════════════════════════
   切换逻辑绑定
   ══════════════════════════════════════════ */
#xt-t1:checked ~ .xt-content .xt-card:nth-of-type(1) { display: none !important; }
#xt-t1:checked ~ .xt-content .xt-card:nth-of-type(2) { display: block !important; animation: switchAnim 0.35s ease-out !important; }

#xt-t2:checked ~ .xt-content .xt-card:nth-of-type(3) { display: none !important; }
#xt-t2:checked ~ .xt-content .xt-card:nth-of-type(4) { display: block !important; animation: switchAnim 0.35s ease-out !important; }

#xt-t3:checked ~ .xt-content .xt-card:nth-of-type(5) { display: none !important; }
#xt-t3:checked ~ .xt-content .xt-card:nth-of-type(6) { display: block !important; animation: switchAnim 0.35s ease-out !important; }

@keyframes switchAnim {
  0% { opacity: 0; transform: translateY(10px) scale(0.99); }
  100% { opacity: 1; transform: translateY(0) scale(1); }
}

/* ══════════════════════════════════════════
   自适应系统日夜模式 (恢复完美宽度版)
   ══════════════════════════════════════════ */

/* 丝滑过渡动画 */
.xt-card, .xt-text, .xt-root, .xt-content, .xt-text-wx1_header, .xt-text-wx2_header,
