      url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='%238e8e93' stroke-width='1.5' stroke-linecap='round' stroke-linejoin='round'><path d='M19 21l-7-5-7 5V5a2 2 0 0 1 2-2h10a2 2 0 0 1 2 2z'/><line x1='12' y1='7' x2='12' y2='11'/><line x1='10' y1='9' x2='14' y2='9'/></svg>"),
      url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='%238e8e93' stroke-width='1.5' stroke-linecap='round' stroke-linejoin='round'><path d='M4 12v8a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2v-8'/><polyline points='16 6 12 2 8 6'/><line x1='12' y1='2' x2='12' y2='15'/></svg>"),
      url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='%238e8e93'><circle cx='5' cy='12' r='2'/><circle cx='12' cy='12' r='2'/><circle cx='19' cy='12' r='2'/></svg>") !important;
  }

  .xt-card:nth-of-type(5) .xt-row, .xt-card:nth-of-type(6) .xt-row {
    border-top: 1px solid #2c2c2e !important; 
  }
  .xt-card:nth-of-type(5) .xt-row .xt-name, .xt-card:nth-of-type(6) .xt-row .xt-name { color: #f2f2f7 !important; }

  /* 评论正文提亮 */
  .xt-text-icity1_c1_text, .xt-text-icity1_c2_text, .xt-text-icity1_c3_text, .xt-text-icity1_c4_text, .xt-text-icity1_c5_text,
  .xt-text-icity2_c1_text, .xt-text-icity2_c2_text, .xt-text-icity2_c3_text, .xt-text-icity2_c4_text, .xt-text-icity2_c5_text {
    color: #d1d1d6 !important; 
  }

  /* 楼主回复气泡 */
  .xt-text-icity1_reply1, .xt-text-icity1_reply2, .xt-text-icity1_reply3, .xt-text-icity1_reply4, .xt-text-icity1_reply5,
  .xt-text-icity2_reply1, .xt-text-icity2_reply2, .xt-text-icity2_reply3, .xt-text-icity2_reply4, .xt-text-icity2_reply5 {
    background: #2c2c2e !important; color: #f2f2f7 !important;
  }

  /* 论坛底栏 */
  .xt-text-icity1_bottom, .xt-text-icity2_bottom {
    background: #1c1c1e !important; border-top-color: #333 !important;
    color: transparent !important; font-size: 0 !important;
  }
  .xt-text-icity1_bottom::before, .xt-text-icity2_bottom::before {
    background: #2c2c2e !important; border-color: #333 !important; color: #666 !important;
  }
  .xt-text-icity1_bottom::after, .xt-text-icity2_bottom::after {
    background-color: #07c160 !important;
  }
}

/* ══════════════════════════════════════════
   微信动态顶栏 (暴力修复版)
   ══════════════════════════════════════════ */

/* 1. 白天模式：强制画成微信顶栏 */
.xt-root .xt-text-wx1_header, 
.xt-root .xt-text-wx2_header {
  display: block !important;
  background: #ededed !important; 
  background-color: #ededed !important;
  text-align: center !important; 
  padding: 16px !important;
  font-size: 16px !important; 
  font-weight: 500 !important; 
  border-bottom: 1px solid #dcdcdc !important;
  color: #111 !important; 
  border-radius: 16px 16px 0 0 !important;
  margin: -16px -16px 16px -16px !important; /* 撑满卡片 */
  position: relative !important;
  line-height: 1.2 !important;
}

/* 左侧返回图标 */
.xt-root .xt-text-wx1_header::before,
.xt-root .xt-text-wx2_header::before {
  content: "" !important; 
  position: absolute !important; left: 16px !important; top: 17px !important; 
  width: 20px !important; height: 20px !important;
  background: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='%23000' stroke-width='2.5' stroke-linecap='round' stroke-linejoin='round'><polyline points='15 18 9 12 15 6'/></svg>") no-repeat center/contain !important;
}

/* 右侧三点图标 */
.xt-root .xt-text-wx1_header::after,
.xt-root .xt-text-wx2_header::after {
  content: "" !important; 
  position: absolute !important; right: 16px !important; top: 17px !important; 
  width: 20px !important; height: 20px !important;
  background: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='%23000'><circle cx='5' cy='12' r='2'/><circle cx='12' cy='12' r='2'/><circle cx='19' cy='12' r='2'/></svg>") no-repeat center/contain !important;
}

/* ══════════════════════════════════════════
   微信动态顶栏夜间模式适配 (权重碾压)
   ══════════════════════════════════════════ */
@media (prefers-color-scheme: dark) {
  .xt-root .xt-text-wx1_header, 
  .xt-root .xt-text-wx2_header {
    background: #1c1c1e !important;
    background-color: #1c1c1e !important;
    border-bottom-color: #333 !important;
    color: #f2f2f7 !important;
  }

  /* 左右图标反白 */
  .xt-root .xt-text-wx1_header::before,
  .xt-root .xt-text-wx2_header::before,
  .xt-root .xt-text-wx1_header::after,
  .xt-root .xt-text-wx2_header::after {
    filter: invert(1) !important;
  }
}

/* ══════════════════════════════════════════
   论坛夜间模式：名字高亮修复补丁
   ══════════════════════════════════════════ */
@media (prefers-color-scheme: dark) {
  /* 1. 强制发帖人名字变白 */
  .xt-root .xt-card:nth-of-type(5) .xt-name,
  .xt-root .xt-card:nth-of-type(6) .xt-name {
    color: #ffffff !important;
  }

