  animation: xgSpin 30s linear infinite;
}
/* ── 漂浮装饰 2：右侧竖向细线 + 小字（贯穿 02 → 03）
   v3：挪到 .xt-root::after，把 .xt-content::after 让给最前面的雨雪层 ── */
.xt-root::after {
  content: "the true proposition of fog" !important;
  display: block !important;
  position: absolute;
  font-size: 10px;
  font-size: clamp(8.6px, 2.73cqw, 11.7px);
  top: calc(22px + 18em); right: 1px;
  height: 15em;
  z-index: 6;
  pointer-events: none;
  writing-mode: vertical-rl;
  padding-left: 3px;
  font-family: var(--f-en);
  font-style: italic;
  letter-spacing: .1em;
  white-space: nowrap;
  color: var(--slate);
  border-left: 1px solid var(--steel);
  background: none !important;
}

/* ═══════════ 最前面的一层：很慢很稀的小雪（不挡点击） ═══════════
   v4：去掉雨丝，只留三层稀疏的雪，一个循环 90 秒，几乎是"悬着"往下落
   ★【可改】--snow：雪的颜色，设成 transparent 就关掉
   ★【可改】--fx-a：整层浓度（0 关闭，1 最浓）
   ★【可改】--fx-s：一个循环的秒数，越大越慢 */
/* v5 性能：原来是对整张卡大小的层做 background-position 动画，每一帧都要整层重绘；
   现在层本身加高 --fx-h，只做 transform 平移（交给 GPU 合成，不重绘）。
   --fx-y 是一个循环走的距离，必须是每层图案高度的整数倍，才能无缝衔接。
   .xt-content 用 overflow:clip 把加高的部分裁掉，不会把卡片撑出滚动条。 */
.xt-content {
  overflow: hidden !important;
  overflow: clip !important;
  overflow-clip-margin: 26px;
  --fx-h: 720px;
  --fx-y: 720px;
  --snow: #FFFFFF;
  --snow-edge: rgba(var(--slate-rgb), .26);
  --fx-a: .85;
  --fx-s: 90s;
}
.xt-content::after {
  content: "";
  position: absolute;
  /* 只朝运动方向加高：往下落就加在上面，往上飘就加在下面 */
  top: calc(-22px - max(var(--fx-y), 0px));
  bottom: calc(-16px - max(var(--fx-y) * -1, 0px));
  left: -26px; right: -16px;
  z-index: 30;
  will-change: transform;
  pointer-events: none;
  opacity: var(--fx-a);
  background-image:
    radial-gradient(circle at 20% 30%, var(--snow) 0 2px, var(--snow-edge) 2.5px, transparent 3.2px),
    radial-gradient(circle at 70% 60%, var(--snow) 0 1.5px, var(--snow-edge) 1.9px, transparent 2.5px),
    radial-gradient(circle at 40% 80%, var(--snow) 0 1px, transparent 1.7px) !important;
  background-size: 190px 240px, 140px 180px, 100px 120px !important;
  background-repeat: repeat !important;
  animation: xgFx var(--fx-s) linear infinite !important;
}
@keyframes xgFx {
  from { transform: translate3d(0, 0, 0); }
  to   { transform: translate3d(0, var(--fx-y), 0); }
}

/* ═══════════ 动画 ═══════════ */
@keyframes xgIn {
  from { opacity: 0; filter: blur(6px); transform: translateY(8px); }
  to   { opacity: 1; filter: none; transform: none; }
}
@keyframes xgHalo {
  from { opacity: .86; }
  to   { opacity: 1; }
}
@keyframes xgBlink { 50% { opacity: .25; } }
@keyframes xgProgress { from { width: 0; } to { width: calc(100% - 6.2em); } }
@keyframes xgSpin { to { rotate: 360deg; } }

/* 系统「减少动态效果」打开时：保留显影，去掉循环动画 */
@media (prefers-reduced-motion: reduce) {
  .xt-content *, .xt-content *::before, .xt-content *::after,
  .xt-content::before, .xt-root::after {
    animation: none !important;
  }
  .xt-content::after { animation: none !important; opacity: calc(var(--fx-a) * .6); }
}


/* ╔══════════════════════════════════════════════╗
   ║  主题 ①  水色 · MIZUIRO DREAMCORE               ║
   ║  忧郁的蓝白日系水色：洇开的水彩、水面光纹、        ║
   ║  背景里一圈一圈慢慢散开的涟漪                     ║
   ╚══════════════════════════════════════════════╝ */
.xt-root {
