  writing-mode: vertical-rl;
  white-space: nowrap !important;
  padding-top: .4em !important;
  font-family: var(--f-script);
  font-size: 1.45em;
  line-height: 1;
  color: var(--ink-3);
  z-index: 2;
}
.xt-content .xt-text-vertEn::before {
  content: "\2014\2014  ";
  font-family: var(--f-mono);
  font-size: .5em;
  color: var(--steel);
}

/* ═══════════ 01 · 絮语 —— 雾窗，点击擦开 ═══════════ */
.xt-content .xt-text-murmur,
.xt-content .xt-action-1 { grid-area: 4 / 2 / 5 / 13; }

.xt-content .xt-text-murmur {
  min-height: 7.6em;
  padding: 1.5em 1.4em 1.9em 1.5em !important;
  font-size: 1em;
  line-height: 1.95;
  letter-spacing: .07em;
  color: var(--ink-2);
}
.xt-content .xt-text-murmur::before {
  content: "MURMUR \00B7  01";
  display: block;
  margin-bottom: .3em;
  font-family: var(--f-mono);
  font-size: .68em;
  letter-spacing: .26em;
  color: var(--slate);
}
.xt-content .xt-action-1 {
  clip-path: var(--cut-a);
  background-color: rgba(var(--mist-rgb), .74) !important;
  /* 小水珠 + 斜向雾纹 */
  background-image:
    radial-gradient(circle at 18% 30%, rgb(var(--hl)) 0 1.4px, transparent 2.4px),
    radial-gradient(circle at 64% 22%, rgb(var(--hl)) 0 1px, transparent 2px),
    radial-gradient(circle at 82% 68%, rgb(var(--hl)) 0 1.8px, transparent 2.8px),
    repeating-linear-gradient(118deg, rgba(var(--hl), .55) 0 1px, transparent 1px 7px),
    linear-gradient(170deg, rgba(var(--hl), .85), rgba(var(--tint), .55)) !important;
  background-size: 64px 52px, 46px 58px, 72px 66px, 100% 100%, 100% 100% !important;
  /* v5：去掉 backdrop-filter（下面有动画层时每帧都要重新模糊，手机上最卡的就是它），底色加浓补回来 */
}
/* 封面：大号空心「呵」+ 小字说明
   v5：常规字重 + text-fill-color 透明，手机上粗体字描边会糊成实心 */
.xt-content .xt-action-1::before {
  content: "\5475";
  position: absolute;
  left: .2em; top: 50%;
  translate: 0 -55%;
  font-size: 3.3em;
  font-weight: 400 !important;
  font-synthesis: none;
  line-height: 1;
  color: transparent !important;
  -webkit-text-fill-color: transparent !important;
  -webkit-text-stroke: 1px var(--ink-3);
  transition: opacity .45s ease, translate .6s var(--ease);
}
@supports not (-webkit-text-stroke: 1px black) {
  .xt-content .xt-action-1::before { color: var(--ink-4) !important; -webkit-text-fill-color: currentColor !important; opacity: .35; }
}
.xt-content .xt-action-1::after {
  content: "01 \2014  MURMUR\A \7D6E\8BED \00B7  \5475\4E00\53E3\6C14\A tap to wipe the fog";
  white-space: pre;
  position: absolute;
  left: 6.3em; top: 50%;
  translate: 0 -50%;
  padding-left: .9em;
  border-left: 1px solid var(--ink-3);
  font-family: var(--f-mono);
  font-size: .9em;
  line-height: 1.7;
  letter-spacing: .14em;
  color: var(--ink-3);
  transition: opacity .45s ease;
}
#xt-t1:checked ~ .xt-content .xt-action-1 {
  background-color: rgba(var(--hl), .82) !important;
}
#xt-t1:checked ~ .xt-content .xt-action-1::before { opacity: 0; translate: -1em -55%; }
#xt-t1:checked ~ .xt-content .xt-action-1::after {
  content: "\21BA  FOG";
  top: .7em; left: auto; right: 2.2em;
  translate: none;
  border: 0; padding: 0;
  font-size: .66em;
  opacity: .6;
}
#xt-t1:checked ~ .xt-content .xt-text-murmur { opacity: 1; filter: none; transition-delay: .12s; }

/* ═══════════ 装饰位 A（@spacer）：准星 + 编号 + 错位半透明色块 ═══════════ */
.xt-content .xt-spacer {
  grid-area: 5 / 2 / 7 / 4;
  position: relative;
  align-self: stretch !important;
  height: auto !important;
  min-height: 6em;
  z-index: 1;
  pointer-events: none;
  background: none !important;
}
.xt-content .xt-spacer::before {          /* 两块错位叠放的雾蓝方块 */
  content: "";
  position: absolute;
  left: 18%; top: 14%;
