  background:
    linear-gradient(var(--ink-4), var(--ink-4)) calc(100% - 1.4em) 1.1em / 2.4em 1px no-repeat,
    linear-gradient(var(--ink-4), var(--ink-4)) calc(100% - 2.6em) .5em / 1px 1.3em no-repeat,
    repeating-linear-gradient(0deg, rgba(var(--hl), .05) 0 1px, transparent 1px 3px),
