}

/* ═══════════ 03 · 想和她一起的 —— 旋转八角 CD，点击「播放」 ═══════════ */
.xt-content .xt-action-3      { grid-area: 7 / 1 / 10 / 10; }
.xt-content .xt-text-giftType { grid-area: 7 / 1 / 8 / 10; }
.xt-content .xt-text-giftName { grid-area: 8 / 1 / 9 / 10; }
.xt-content .xt-text-giftNote { grid-area: 9 / 1 / 10 / 10; }

.xt-content .xt-action-3 {
