  --xt-bg: transparent !important;
  --xt-text: #4A332D !important;
  --xt-font: 'Mali', 'Gaegu', 'Patrick Hand', "Yuanti SC", "YouYuan", "ZCOOL KuaiLe", "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", sans-serif !important;

  width: 100% !important;
  max-width: 438px !important;
  margin: 30px auto 20px !important;
  background: transparent !important;
  color: var(--ink-main) !important;
  font-family: var(--xt-font) !important;
  font-weight: 400 !important;
  padding: 22px 28px 22px 28px !important;
  position: relative !important;
  overflow: visible !important;
  display: flex !important;
  flex-direction: column !important;
  filter: drop-shadow(0 5px 10px rgba(92, 64, 56, 0.14)) !important;
}

/* 顶部皇冠 */
.xt-root::before {
  content: "" !important;
  display: block !important;
  position: absolute !important;
  top: -32px !important;
  left: 50% !important;
  transform: translateX(-50%) !important;
  width: 164px !important;
  height: 46px !important;
  background: var(--svg-bunny-crown) no-repeat center bottom / contain !important;
  animation: crownSway 3.6s ease-in-out infinite !important;
  transform-origin: center bottom !important;
  pointer-events: none !important;
  z-index: 10 !important;
}
.xt-root::after {
  display: none !important;
}

.xt-content {
  display: flex !important;
  flex-direction: column !important;
  width: 100% !important;
  background: transparent !important;
  overflow: visible !important;
  padding: 0 !important;
}

/* 外壳 */
.xt-content::before {
  content: "" !important;
  display: block !important;
  position: absolute !important;
  inset: -6px -4px -2px -4px !important;
  background: var(--mochi-shell-p1) no-repeat center / 100% 100% !important;
  pointer-events: none !important;
  z-index: -1 !important;
}
#xt-t1:checked ~ .xt-content::before {
  background-image: var(--mochi-shell-p2) !important;
}

/* ── 3. 页面容器 ── */
.xt-collapse {
  width: 100% !important;
  background: transparent !important;
  border: none !important;
}

.xt-collapse-body,
.xt-collapse.collapsed .xt-collapse-body,
.xt-collapse.is-collapsed .xt-collapse-body,
.xt-collapse.closed .xt-collapse-body,
.xt-collapse[aria-expanded="false"] .xt-collapse-body,
.xt-collapse[data-collapsed="true"] .xt-collapse-body,
.xt-collapse-body[hidden],
.xt-collapse-body[aria-hidden="true"] {
  display: block !important;
  visibility: visible !important;
  opacity: 1 !important;
  height: 445px !important;
  max-height: 445px !important;
  overflow-y: auto !important;
  overflow-x: hidden !important;
  scrollbar-width: none !important;
  -ms-overflow-style: none !important;
  padding: 4px 8px 20px 8px !important;
  background: transparent !important;
  border: none !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  transform: none !important;
  transition: none !important;
}
.xt-collapse-body::-webkit-scrollbar {
  display: none !important;
  width: 0 !important;
}

.xt-collapse-1 { display: block !important; animation: jellyPop 0.25s ease-out; }
.xt-collapse-2, .xt-collapse-3 { display: none !important; }

#xt-t1:checked ~ .xt-content .xt-collapse-1,
#xt-t1:checked ~ .xt-content .xt-collapse-3 { display: none !important; }
#xt-t1:checked ~ .xt-content .xt-collapse-2 { display: block !important; animation: jellyPop 0.25s ease-out; }

#xt-t2:checked ~ .xt-content .xt-collapse-1,
#xt-t2:checked ~ .xt-content .xt-collapse-2,
#xt-t2:checked ~ .xt-content .xt-action-1 { display: none !important; }
#xt-t2:checked ~ .xt-content .xt-collapse-3 { display: block !important; animation: jellyPop 0.25s ease-out; }

/* ── 4. 展开交互 ── */
.xt-text-sub1Parse, .xt-text-sub2Parse,
.xt-text-pick1Note, .xt-text-pick2Note,
.xt-text-podScript, .xt-text-podHeartAlert {
  display: none !important;
}
#xt-t4:checked ~ .xt-content .xt-text-sub1Parse { display: block !important; animation: jellyPop 0.2s; }
#xt-t5:checked ~ .xt-content .xt-text-sub2Parse { display: block !important; animation: jellyPop 0.2s; }
#xt-t6:checked ~ .xt-content .xt-text-pick1Note { display: block !important; animation: jellyPop 0.2s; }
#xt-t7:checked ~ .xt-content .xt-text-pick2Note { display: block !important; animation: jellyPop 0.2s; }
#xt-t8:checked ~ .xt-content .xt-text-podScript,
#xt-t8:checked ~ .xt-content .xt-text-podHeartAlert { display: block !important; animation: jellyPop 0.2s; }

/* ── 5. 状态栏 ── */
.xt-text {
  padding: 0 2px !important;
  font-style: normal !important;
  font-weight: 400 !important;
  color: var(--ink-main) !important;
}

.xt-text-currentTime {
  flex-shrink: 0 !important;
  width: calc(100% - 8px) !important;
  margin: 0 auto 6px auto !important;
