value.customCss:
@import url('https://fonts.googleapis.com/css2?family=Shippori+Mincho:wght@400;600;800&family=Zen+Old+Mincho:wght@400;700;900&family=Hina+Mincho&display=swap');

/*⁣‌⁠⁠​⁠⁠⁠‌‍‍​​​⁠‍⁠‌‌​‍‍‍‌‌​‌⁠‍⁠⁠‍‌​⁠⁠‍⁠‌‍‌‍⁠​⁠⁠⁠⁠‍​⁠‍‍​​‌‍⁠‌⁠‍​​‌‍⁣ ═════════════════════════════════════════════
   赤い糸 · 結び札  v3   —— 命运，丝线，我和你
   白雾底 / 一根红线从左上绕结后横贯到右 / 四张细长纸札垂挂
   ★ = 可改项（Ctrl+F 搜 ★）
   结构：所有元素都平铺在 .xt-content 里，统一 absolute + 百分比定位
   ═════════════════════════════════════════════ */

.xt-root {
  /* ★ 配色 */
  --ito: #b8282e;            /* 红线 / 朱 */
  --sumi: #1a1a1a;           /* 墨 */
  --sumi-2: #4a4542;
  --sumi-3: #8f8780;
  --washi: #fdfbf6;          /* 札纸 */
  /* （札面线框 / 朱印的颜色写在 deco.py 里：金茶 #a8834a、木色 #8a6a44、樱粉 #c4606e） */
  /* ★ 字体（Google Fonts 免费明朝体，加载失败时回退系统衬线） */
  --f-title: 'Zen Old Mincho', 'Shippori Mincho', 'Songti SC', serif;
  --f-body: 'Shippori Mincho', 'Zen Old Mincho', 'Songti SC', serif;
  --f-soft: 'Hina Mincho', 'Shippori Mincho', serif;
  /* ★ 缓动曲线（札垂落、标题浮现都用它） */
  --ease: cubic-bezier(.22, .8, .24, 1);
  /* ★ 纸纹（SVG 噪点） */
  --paper-noise: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='160' height='160'><filter id='n'><feTurbulence type='fractalNoise' baseFrequency='.9' numOctaves='3' stitchTiles='stitch'/><feColorMatrix values='0 0 0 0 .45  0 0 0 0 .38  0 0 0 0 .3  0 0 0 .16 0'/></filter><rect width='160' height='160' filter='url(%23n)'/></svg>");
  --paper-fiber: repeating-linear-gradient(97deg, rgba(120, 100, 80, .035) 0 1px, transparent 1px 9px),
                 repeating-linear-gradient(3deg, rgba(120, 100, 80, .03) 0 1px, transparent 1px 13px);

  /* 教程里的系统变量全部对齐到本主题：
     系统自带的勾选框、进度条、动画修饰符等都会跟着变成白底墨字朱红 */
  --xt-bg: #fff;
  --xt-text: var(--sumi);
  --xt-text-sub: var(--sumi-2);
  --xt-text-muted: var(--sumi-3);
  --xt-accent: var(--ito);
  --xt-accent-bg: rgba(184, 40, 46, .08);
  --xt-border: rgba(184, 40, 46, .22);
  --xt-radius: 0px;
  --xt-radius-sm: 2px;
  --xt-font: var(--f-body);
  --xt-anim-duration: .7s;
  --xt-anim-easing: var(--ease);
  --xt-stagger-delay: 120ms;
  --xt-glow-color: rgba(184, 40, 46, .3);
  --xt-shadow-sm: 0 1px 3px rgba(60, 40, 30, .10);
  --xt-shadow-md: .8cqw 2.6cqw 3cqw -1cqw rgba(60, 40, 30, .22);
  --xt-shadow-lg: 0 4cqw 8cqw -2cqw rgba(60, 40, 30, .25);

  position: relative;
  isolation: isolate;
  width: 100%;
  aspect-ratio: 100 / 147;
  height: auto;
  padding: 0 !important;
  overflow: hidden;
  background: #fff !important;
  border: 0 !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  container-type: inline-size;
  font-family: var(--f-body);
  color: var(--sumi);
  /* 四边羽化：没有硬边框，白雾直接散进聊天背景 */
  -webkit-mask-image: linear-gradient(to right, transparent, #000 5%, #000 95%, transparent), linear-gradient(to bottom, transparent, #000 3.5%, #000 96.5%, transparent);
  -webkit-mask-composite: source-in;
  mask-image: linear-gradient(to right, transparent, #000 5%, #000 95%, transparent), linear-gradient(to bottom, transparent, #000 3.5%, #000 96.5%, transparent);
  mask-composite: intersect;
}
/* ── 雾：三团极淡的灰粉雾气缓慢漂移（transform 动画，手机上不卡） ── */
.xt-root::before {
  content: "";
  position: absolute;
  inset: -25%;
  z-index: 0;
  pointer-events: none;
  background:
    radial-gradient(38% 30% at 26% 30%, rgba(214, 196, 190, .38), transparent 70%),
    radial-gradient(34% 28% at 74% 62%, rgba(236, 200, 206, .32), transparent 70%),
    radial-gradient(42% 26% at 50% 88%, rgba(205, 205, 212, .30), transparent 72%),
    radial-gradient(30% 22% at 82% 18%, rgba(240, 222, 214, .35), transparent 70%);
  animation: itoMist 28s ease-in-out infinite alternate;
}
/* 左边缘：一列极淡的竖排小字，代替边框 */
.xt-root::after {
  content: "えにし・むすび・いと・ちぎり・ねがい・えにし・むすび・いと・ちぎり・ねがい・えにし・むすび";
  position: absolute;
  left: 2.2%; top: 3%; bottom: 3%;
  z-index: 3;
  pointer-events: none;
  writing-mode: vertical-rl;
  overflow: hidden;
  font-family: var(--f-soft);
  font-size: 2.1cqw;
  letter-spacing: .55em;
  color: rgba(26, 26, 26, .16);
}

/* ── 内容层：所有元素平铺、绝对定位 ── */
.xt-content {
  position: absolute !important;
  inset: 0;
  z-index: 2;
  display: block !important;
  margin: 0 !important;
  padding: 0 !important;
  gap: 0 !important;
  background: none !important;
  font-size: 4cqw;
  line-height: 1.6;
}
.xt-content > * { margin: 0 !important; }

/* ── 红线：左上入，打一个结，垂成弧线横贯到右 ──
   路径坐标 = root 宽高百分比；四张札的顶端就挂在这条曲线上 */
.xt-content::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 4;
  pointer-events: none;
  background: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 100 147' preserveAspectRatio='none'><path stroke-dasharray='100' stroke-dashoffset='100' pathLength='100' d='M -4 8.23 C 8 6.76 21 14.11 20.4 29.99 C 19.4 43.22 7.4 44.69 8.4 32.93 C 9.4 22.64 23.4 27.34 24.4 44.69 C 34.4 88.79 70 89.08 104 56.74' fill='none' stroke='rgb(184,40,46)' stroke-opacity='.28' stroke-width='.28'><animate attributeName='stroke-dashoffset' from='100' to='0' dur='2.6s' begin='.35s' fill='freeze' calcMode='spline' keyTimes='0;1' keySplines='.45 .05 .3 1'/></path><path stroke-dasharray='100' stroke-dashoffset='100' pathLength='100' d='M -4 7.35 C 8 5.88 21 13.23 20 29.4 C 19 42.63 7 44.1 8 32.34 C 9 22.05 23 26.46 24 44.1 C 34 88.2 70 88.2 104 55.86' fill='none' stroke='rgb(184,40,46)' stroke-width='.48' stroke-linecap='round'><animate attributeName='stroke-dashoffset' from='100' to='0' dur='2.4s' begin='.2s' fill='freeze' calcMode='spline' keyTimes='0;1' keySplines='.45 .05 .3 1'/></path></svg>") 0 0 / 100% 100% no-repeat;
  filter: drop-shadow(0 1.5px 1.5px rgba(120, 20, 24, .22));
  transition: opacity .5s ease;
}
/* 右边缘：竖排英文细字，和左边那列一起形成「看不见的边」 */
.xt-content::after {
  content: "THE RED THREAD OF FATE  ·  CAN WE STAY ENTANGLED FOREVER  ·  運命の赤い糸";
  position: absolute;
  right: 2.2%; top: 4%; bottom: 4%;
  z-index: 3;
  pointer-events: none;
  writing-mode: vertical-rl;
  overflow: hidden;
  white-space: nowrap;
  font-family: var(--f-body);
  font-size: 1.7cqw;
  letter-spacing: .42em;
  color: rgba(184, 40, 46, .22);
}

.xt-content .xt-spacer, .xt-content .xt-divider { display: none !important; }
.xt-content .xt-footer {
  position: absolute;
  left: 0; right: 0; bottom: 2.4%;
  z-index: 5;
  padding: 0 !important;
  border: 0 !important;
  background: none !important;
  text-align: center;
  font-family: var(--f-title);
  font-size: 2.6cqw !important;
  letter-spacing: .6em;
  line-height: 1.5;
  white-space: pre;
  color: var(--sumi-3) !important;
  opacity: 0;
  animation: itoFade 1.2s ease 3.4s forwards;
}
.xt-content .xt-footer::after {
  content: "\A— 轻触札面 · 翻开 —";
  font-family: var(--f-soft);
  font-size: .8em;
  letter-spacing: .35em;
  color: var(--ito);
  opacity: .6;
}
/* ── 花瓣：把默认 🌸 换成 CSS 画的樱瓣 ──
   兼容两种渲染方式（emoji 写在文字里 / 写在伪元素里）：字号归零 + 伪元素清空 */
.xt-particles {
  position: absolute !important;
  inset: 0 !important;
  z-index: 1 !important;
  pointer-events: none !important;
  overflow: hidden;
}
.xt-particles-sakura .xt-particle {
  position: absolute !important;
  font-size: 0 !important;
  line-height: 0 !important;
  color: transparent !important;
  width: 2.3cqw !important;
  height: 2.8cqw !important;
  top: -4% !important;
  border-radius: 100% 0 100% 0 / 100% 0 100% 0 !important;
  background: linear-gradient(135deg, #fff1f3 0%, #f7c6cf 55%, #ec9fae 100%) !important;
  box-shadow: inset -1px -1px 2px rgba(200, 90, 110, .25) !important;
  opacity: .82;
  animation-name: itoPetal !important;
  animation-timing-function: linear !important;
  animation-iteration-count: infinite !important;
  animation-duration: 13s;
}
.xt-particles-sakura .xt-particle::before,
.xt-particles-sakura .xt-particle::after { content: none !important; display: none !important; }
/* 三层景深：远（小·虚·淡·最慢）/ 中 / 近（大·实·清晰）
   时长和延迟都加 !important，压过系统给粒子写的行内速度 */
.xt-particles-sakura .xt-particle {
  animation-duration: 26s !important;
  filter: blur(.4px);
  opacity: .72;
}
/* 远景：3、9、12、15、18 */
.xt-particles-sakura .xt-particle:nth-child(3n) {
  width: 1.3cqw !important; height: 1.6cqw !important;
  background: linear-gradient(135deg, #fff, #f6d6dc 70%) !important;
  box-shadow: none !important;
  filter: blur(1.6px);
  opacity: .38;
  animation-duration: 36s !important;
}
/* 近景：1、6、11、16 */
.xt-particles-sakura .xt-particle:nth-child(5n+1) {
  width: 3.7cqw !important; height: 4.3cqw !important;
  background: linear-gradient(135deg, #fff4f6 0%, #f4b5c2 50%, #e48a9c 100%) !important;
  box-shadow: inset -1px -1px 3px rgba(190, 70, 95, .35), .4cqw .8cqw 1.2cqw rgba(180, 80, 100, .18) !important;
  filter: none;
  opacity: .95;
  animation-duration: 20s !important;
}
.xt-particles-sakura .xt-particle:nth-child(6n+1) { left: 6%;  animation-delay: -2s !important; }
.xt-particles-sakura .xt-particle:nth-child(6n+2) { left: 24%; animation-delay: -15s !important; }
.xt-particles-sakura .xt-particle:nth-child(6n+3) { left: 41%; animation-delay: -27s !important; }
.xt-particles-sakura .xt-particle:nth-child(6n+4) { left: 58%; animation-delay: -9s !important; }
.xt-particles-sakura .xt-particle:nth-child(6n+5) { left: 74%; animation-delay: -21s !important; }
.xt-particles-sakura .xt-particle:nth-child(6n)   { left: 90%; animation-delay: -32s !important; }
.xt-particles-sakura .xt-particle:nth-child(n+7)  { margin-left: -9% !important; }
.xt-particles-sakura .xt-particle:nth-child(n+13) { margin-left: 5% !important; }

/* ── 第 1 组 @tags：背景浮动大字 ── */
.xt-content .xt-tags {
  position: absolute;
  z-index: 0;
  padding: 0 !important;
  margin: 0 !important;
  background: none !important;
  border: 0 !important;
  gap: 0 !important;
  pointer-events: none;
}
.xt-content .xt-tag {
  position: absolute;
  margin: 0 !important;
  padding: 0 !important;
  background: none !important;
  border: 0 !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  line-height: 1 !important;
  white-space: nowrap;
  font-family: var(--f-title);
