.xt-content .xt-tag::before, .xt-content .xt-tag::after { content: none; }

.xt-content .xt-tags:not(.xt-tags ~ .xt-tags) { inset: 0; }
.xt-content .xt-tags:not(.xt-tags ~ .xt-tags) .xt-tag {
