}
.xt-content .xt-tags:not(.xt-tags ~ .xt-tags) .xt-tag:nth-child(1)  { left: 58%; top: 6%;  animation-duration: 21s; }
.xt-content .xt-tags:not(.xt-tags ~ .xt-tags) .xt-tag:nth-child(2)  { left: 4%;  top: 44%; font-size: 26cqw !important; color: transparent !important; -webkit-text-stroke: .5px rgba(184, 40, 46, .16); animation-duration: 24s; }
.xt-content .xt-tags:not(.xt-tags ~ .xt-tags) .xt-tag:nth-child(3)  { left: 70%; top: 72%; animation-duration: 19s; animation-delay: -6s; }
.xt-content .xt-tags:not(.xt-tags ~ .xt-tags) .xt-tag:nth-child(4)  { left: 34%; top: 82%; font-size: 14cqw !important; filter: blur(2px); color: rgba(26, 26, 26, .06) !important; }
.xt-content .xt-tags:not(.xt-tags ~ .xt-tags) .xt-tag:nth-child(5)  { left: 80%; top: 34%; font-size: 13cqw !important; color: transparent !important; -webkit-text-stroke: .5px rgba(26, 26, 26, .14); animation-duration: 26s; }
.xt-content .xt-tags:not(.xt-tags ~ .xt-tags) .xt-tag:nth-child(6)  { left: 40%; top: 20%; font-size: 11cqw !important; filter: blur(1.5px); animation-delay: -9s; }
.xt-content .xt-tags:not(.xt-tags ~ .xt-tags) .xt-tag:nth-child(7)  { left: 12%; top: 66%; font-size: 12cqw !important; color: rgba(184, 40, 46, .05) !important; animation-duration: 23s; }
.xt-content .xt-tags:not(.xt-tags ~ .xt-tags) .xt-tag:nth-child(8)  { left: 55%; top: 50%; font-size: 30cqw !important; color: rgba(26, 26, 26, .03) !important; animation-duration: 30s; animation-delay: -12s; }
.xt-content .xt-tags:not(.xt-tags ~ .xt-tags) .xt-tag:nth-child(9)  { left: 86%; top: 88%; font-size: 9cqw !important; filter: blur(1px); }
.xt-content .xt-tags:not(.xt-tags ~ .xt-tags) .xt-tag:nth-child(10) { left: 24%; top: 4%;  font-size: 10cqw !important; color: transparent !important; -webkit-text-stroke: .5px rgba(26, 26, 26, .12); animation-delay: -4s; }
/* ── 第 2 组 @tags：右上角的标题拼贴，每个字一种效果 ── */
.xt-content .xt-tags ~ .xt-tags { inset: 0; z-index: 3; }
/* 标题区的细线装饰层：角框、编号、连线、星点（SVG 由 deco.py 生成，写在文件末尾） */
.xt-content .xt-tags ~ .xt-tags::before {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  opacity: 0;
  animation: itoFade 1.4s ease 1.7s forwards;
  transition: opacity .4s ease;
}
.xt-root input:checked ~ .xt-content .xt-tags ~ .xt-tags::before { opacity: 0 !important; animation: none; }
.xt-content .xt-tags ~ .xt-tags .xt-tag {
  color: var(--sumi) !important;
  opacity: 0;
  animation: itoPop .9s var(--ease) forwards;
  transition: opacity .5s ease;
}
/* 命：实心大字，压阵 */
.xt-content .xt-tags ~ .xt-tags .xt-tag:nth-child(1) {
  left: 33%; top: 5.5%;
  font-size: 21cqw !important; font-weight: 900 !important;
  letter-spacing: -.04em;
  animation-delay: .5s;
}
/* 運：空心朱字，略低 */
.xt-content .xt-tags ~ .xt-tags .xt-tag:nth-child(2) {
  left: 52%; top: 10.5%;
  font-size: 15cqw !important; font-weight: 400 !important;
  color: transparent !important;
