}
/* の：红底白字圆印 */
.xt-content .xt-tags ~ .xt-tags .xt-tag:nth-child(3) {
  left: 67.5%; top: 6.5%;
  width: 8.4cqw; height: 8.4cqw;
  display: grid !important; place-items: center;
  border-radius: 50% !important;
  background: var(--ito) !important;
  color: #fff !important;
  font-family: var(--f-soft);
  font-size: 5.4cqw !important;
  animation-delay: .74s;
}
/* 糸：朱色渐变填充 + 竖排细线 */
.xt-content .xt-tags ~ .xt-tags .xt-tag:nth-child(4) {
  left: 72%; top: 7.5%;
  font-size: 21cqw !important; font-weight: 700 !important;
  background: linear-gradient(170deg, #d23a40 10%, #7d1418 60%, #2a0a0b) !important;
  -webkit-background-clip: text !important; background-clip: text !important;
  color: transparent !important; -webkit-text-fill-color: transparent;
  rotate: 4deg;
  animation-delay: .86s;
}
/* ずっと、絡まっていられる？：细小的一行，带朱色下划线 */
.xt-content .xt-tags ~ .xt-tags .xt-tag:nth-child(5) {
  left: 35%; top: 22.6%;
  font-family: var(--f-soft);
  font-size: 3.4cqw !important;
