}
/* 我：角框 */
.xt-content .xt-tags ~ .xt-tags .xt-tag:nth-child(6) {
  left: 41%; top: 27.2%;
  padding: .12em !important;
  font-size: 9cqw !important; font-weight: 600 !important;
  background:
    linear-gradient(var(--sumi), var(--sumi)) 0 0 / 1.8cqw 1px no-repeat,
    linear-gradient(var(--sumi), var(--sumi)) 0 0 / 1px 1.8cqw no-repeat,
    linear-gradient(var(--sumi), var(--sumi)) 100% 100% / 1.8cqw 1px no-repeat,
    linear-gradient(var(--sumi), var(--sumi)) 100% 100% / 1px 1.8cqw no-repeat !important;
  animation-delay: 1.2s;
}
/* 與：小、灰、虚 */
.xt-content .xt-tags ~ .xt-tags .xt-tag:nth-child(7) {
  left: 55%; top: 30.4%;
  font-size: 5cqw !important;
  color: var(--sumi-3) !important;
  filter: blur(.5px);
  animation-delay: 1.32s;
}
/* 你：底下一道朱色马克笔 */
.xt-content .xt-tags ~ .xt-tags .xt-tag:nth-child(8) {
  left: 63%; top: 27%;
  padding: 0 .08em !important;
  font-size: 10cqw !important; font-weight: 700 !important;
  background: linear-gradient(transparent 62%, rgba(184, 40, 46, .28) 62%, rgba(184, 40, 46, .28) 90%, transparent 90%) !important;
  rotate: 3deg;
  animation-delay: 1.44s;
}
/* 英文细字 */
.xt-content .xt-tags ~ .xt-tags .xt-tag:nth-child(9) {
  left: 41%; top: 35.6%;
  font-family: var(--f-body);
  font-size: 1.75cqw !important;
  letter-spacing: .26em;
  color: var(--ito) !important;
  opacity: 0;
  animation-delay: 1.6s;
}
/* ═════════ 札（label）：细长纸条，从红线上垂挂 ═════════
   挂点（root 百分比）：① x29 y40 ② x48.5 y52.6 ③ x68 y52.8 ④ x87.5 y46.9
   root 高 = 1.47 × 宽，所以 1% 高 ≈ 1.47cqw */
.xt-content [class*="xt-action-"] {
  --w: 12.5%;
  --rope: 5cqw;                  /* 挂绳长度 */
  display: block !important;
  position: absolute !important;
  z-index: 5;
  width: var(--w) !important;
  height: 31% !important;
  min-height: 0 !important;
  margin: 0 !important;
  padding: 0 !important;
  border: 0 !important;
  border-radius: 1.2cqw 1.2cqw 2px 2px !important;
  cursor: pointer;
  overflow: visible !important;
  font-size: 0 !important;
  color: transparent !important;
  -webkit-tap-highlight-color: transparent;
  user-select: none;
  background:
    var(--deco) 0 0 / 100% 100% no-repeat,
    var(--knot) 50% 2.6% / 6.4cqw auto no-repeat,
    radial-gradient(circle at 50% 4.2%, rgba(60, 40, 30, .55) 0 .55cqw, transparent .7cqw),
    linear-gradient(var(--ito), var(--ito)) 0 0 / 100% 2.2% no-repeat,
    var(--paper-fiber),
    var(--paper-noise),
    linear-gradient(176deg, #fffdf9 0%, var(--washi) 55%, #f2ece2 100%) !important;
  box-shadow:
    0 1px 1px rgba(60, 40, 30, .10),
    .8cqw 2.6cqw 3cqw -1cqw rgba(60, 40, 30, .22),
    inset 0 0 0 1px rgba(140, 120, 100, .10),
    inset -.6cqw 0 1.2cqw -.6cqw rgba(120, 100, 80, .10) !important;
  transform-origin: 50% calc(-1 * var(--rope));
  opacity: 0;
  translate: 0 -12cqw;
  animation:
    itoHang 1.1s var(--ease) var(--d, 2.4s) forwards,
    itoSwing var(--sw, 5s) ease-in-out calc(var(--d, 2.4s) + 1.1s) infinite alternate;
  transition: left .6s var(--ease), top .6s var(--ease), width .6s var(--ease), height .6s var(--ease),
              opacity .45s ease, border-radius .6s ease, scale .25s ease;
}
.xt-content [class*="xt-action-"] > * { display: none !important; }
/* 按下去时札微微一沉，手指有「碰到纸」的反馈 */
.xt-content [class*="xt-action-"]:active { scale: .965; transition: scale .12s ease; }
.xt-content [class*="xt-action-"]::before,
.xt-content [class*="xt-action-"]::after { box-sizing: border-box; pointer-events: none; }

/* 挂绳：从札顶的小孔一直连到红线 */
.xt-content [class*="xt-action-"]::before {
  content: "";
  position: absolute;
  left: 50%; top: calc(-1 * var(--rope));
  width: 1.5px; height: calc(var(--rope) + 1.3cqw);
  translate: -50% 0;
  background: linear-gradient(var(--ito), #8e1c21);
  border-radius: 1px;
}
/* 札面：竖排标题 + 读音 */
.xt-content [class*="xt-action-"]::after {
  position: absolute;
  left: 20%; right: 0; top: 12%;
  writing-mode: vertical-rl;
  margin: 0 auto;
  white-space: pre;
  font-family: var(--f-title);
  font-size: 5.6cqw;
  font-weight: 700;
  line-height: 1.25;
  letter-spacing: .18em;
  color: var(--sumi);
  text-shadow: .25cqw .3cqw 0 rgba(184, 40, 46, .16), 0 .5cqw .9cqw rgba(60, 40, 30, .22);
  text-align: start;
  display: flex;
  justify-content: center;
  transition: opacity .3s ease;
}
.xt-content .xt-action-1 { --d: 2.0s; --sw: 4.6s; left: 22.75%; top: 43.4%; }
.xt-content .xt-action-2 { --d: 2.25s; --sw: 5.4s; left: 42.25%; top: 56%; }
.xt-content .xt-action-3 { --d: 2.5s; --sw: 5s; left: 61.75%; top: 56.2%; }
.xt-content .xt-action-4 { --d: 2.75s; --sw: 5.8s; left: 81.25%; top: 50.3%; }
.xt-content .xt-action-1::after { content: "心音"; }
.xt-content .xt-action-2::after { content: "御神籤"; }
.xt-content .xt-action-3::after { content: "絵馬"; }
.xt-content .xt-action-4::after { content: "花筏"; }
/* 读音那一列用细字：靠 ::first-line 做不到竖排分级，这里整体降一点字重即可 */
/* 每张札一个小小的不同：①朱印 ②金茶边 ③木色 ④淡粉 */
.xt-content .xt-action-3 {
  background:
    var(--deco) 0 0 / 100% 100% no-repeat,
    var(--knot) 50% 2.6% / 6.4cqw auto no-repeat,
    radial-gradient(circle at 50% 4.2%, rgba(60, 40, 30, .55) 0 .55cqw, transparent .7cqw),
    repeating-linear-gradient(91deg, rgba(140, 100, 60, .07) 0 1px, transparent 1px 5px),
    var(--paper-noise),
    linear-gradient(176deg, #f6ead6, #ead8bb) !important;
}
.xt-content .xt-action-4 {
  background:
    var(--deco) 0 0 / 100% 100% no-repeat,
    var(--knot) 50% 2.6% / 6.4cqw auto no-repeat,
    radial-gradient(circle at 50% 4.2%, rgba(60, 40, 30, .55) 0 .55cqw, transparent .7cqw),
    linear-gradient(var(--ito), var(--ito)) 0 0 / 100% 2.2% no-repeat,
    var(--paper-fiber),
    var(--paper-noise),
    linear-gradient(176deg, #fffafa, #f9eef0) !important;
}
/* ═════════ 打开：札翻转放大，铺满画面 ═════════ */
.xt-root input:checked ~ .xt-content::before { opacity: .18; }
.xt-root input:checked ~ .xt-content .xt-tags ~ .xt-tags .xt-tag { opacity: 0 !important; transition-delay: 0s; }
.xt-root input:checked ~ .xt-content .xt-footer { opacity: 0 !important; transition: opacity .3s; }

#xt-t1:checked ~ .xt-content [class*="xt-action-"]:not(.xt-action-1),
#xt-t2:checked ~ .xt-content [class*="xt-action-"]:not(.xt-action-2),
#xt-t3:checked ~ .xt-content [class*="xt-action-"]:not(.xt-action-3),
#xt-t4:checked ~ .xt-content [class*="xt-action-"]:not(.xt-action-4) {
  visibility: hidden;
  pointer-events: none;
}

#xt-t1:checked ~ .xt-content .xt-action-1,
#xt-t2:checked ~ .xt-content .xt-action-2,
#xt-t3:checked ~ .xt-content .xt-action-3,
#xt-t4:checked ~ .xt-content .xt-action-4 {
  --deco: none; --knot: none;
  scale: 1 !important;
  z-index: 8;
  left: 7% !important; top: 5% !important;
  width: 86% !important; height: 88% !important;
  border-radius: 1.6cqw !important;
  opacity: 1;
  translate: 0 0;
  rotate: 0deg;
  /* 保留 itoHang（同名动画不会重播），去掉摆动，加一次翻转 */
  animation: itoHang 1.1s var(--ease) var(--d, 2.4s) forwards, itoFlip .75s var(--ease);
}
#xt-t1:checked ~ .xt-content .xt-action-1::before,
#xt-t2:checked ~ .xt-content .xt-action-2::before,
#xt-t3:checked ~ .xt-content .xt-action-3::before,
#xt-t4:checked ~ .xt-content .xt-action-4::before { opacity: 0; }
/* ✕ 关闭（整张札都可点，点哪里都能合上） */
#xt-t1:checked ~ .xt-content .xt-action-1::after,
#xt-t2:checked ~ .xt-content .xt-action-2::after,
#xt-t3:checked ~ .xt-content .xt-action-3::after,
#xt-t4:checked ~ .xt-content .xt-action-4::after {
  content: "✕  閉じる";
  writing-mode: horizontal-tb;
  left: auto; right: 3.5cqw; top: 3cqw;
  display: block;
  padding: .3em .7em;
  border: 1px solid rgba(184, 40, 46, .5);
  border-radius: 2em;
  font-family: var(--f-body);
  font-size: 2.6cqw;
  font-weight: 400;
  letter-spacing: .2em;
  color: var(--ito);
  text-shadow: none;
  background: rgba(255, 255, 255, .7);
}
/* 打开后的绘马：五角形木牌 */
#xt-t3:checked ~ .xt-content .xt-action-3 {
  top: 9% !important; height: 80% !important;
  border-radius: 0 !important;
  clip-path: polygon(50% 0, 100% 13%, 100% 100%, 0 100%, 0 13%);
}
/* 五角形会裁掉右上角，绘马的关闭键挪到底部居中 */
#xt-t3:checked ~ .xt-content .xt-action-3::after { top: auto; bottom: 3cqw; right: 50%; translate: 50% 0; }

/* ═════════ 札里的内容：默认藏起来，打开后浮现 ═════════ */
.xt-content .xt-text,
.xt-content .xt-grid,
.xt-content .xt-list {
  position: absolute !important;
  z-index: 9;
  margin: 0 !important;
  padding: 0 !important;
