  opacity: 0;
  visibility: hidden;
  filter: blur(6px);
  animation: none !important;
  transition: opacity .6s ease, filter .6s ease, visibility 0s .6s;
}
#xt-t1:checked ~ .xt-content [class*="xt-text-kokoro"],
#xt-t2:checked ~ .xt-content [class*="xt-text-kuji"],
#xt-t2:checked ~ .xt-content .xt-grid,
