.xt-content .xt-text-kujiNo::before { content: "御神籤  "; color: var(--ito); font-weight: 700; }
.xt-content .xt-text-kujiRank {
  right: 13%; top: 12.5%;
  width: 13cqw; height: 13cqw;
  display: grid !important; place-items: center;
  border: 2px solid var(--ito) !important;
  outline: 1px solid var(--ito); outline-offset: 3px;
  font-family: var(--f-title);
  font-size: 5.6cqw; font-weight: 900; letter-spacing: 0;
  color: var(--ito);
  white-space: nowrap;
}
.xt-content .xt-text-kujiPoem {
  right: 13%; top: 23.5%;
  height: 25%;
  writing-mode: vertical-rl;
  font-family: var(--f-title);
  font-size: 3.8cqw; line-height: 1.8; letter-spacing: .1em;
}
.xt-content .xt-text-kujiPoemNote {
  left: 13%; top: 23.5%;
  width: 38%;
  font-size: 3.1cqw; line-height: 1.85;
  color: var(--sumi-2);
}
.xt-content .xt-text-kujiPoemNote::before {
  content: "解 説";
  display: block; margin-bottom: .5em;
  font-size: .8em; letter-spacing: .4em; color: var(--ito);
}
.xt-content .xt-grid {
  left: 12%; right: 12%;
  display: grid !important;
  gap: 0 !important;
}
.xt-content .xt-grid-2 {
  top: 51%;
  grid-template-columns: 1fr 1fr !important;
  border-top: 1.5px solid var(--sumi) !important;
}
.xt-content .xt-grid-3 {
  top: 81%;
  grid-template-columns: repeat(3, 1fr) !important;
  border-top: 1px solid rgba(184, 40, 46, .4) !important;
  border-bottom: 1px solid rgba(184, 40, 46, .4) !important;
}
.xt-content .xt-grid-stat {
  display: flex !important;
  flex-direction: row-reverse !important;
  align-items: baseline !important;
  justify-content: flex-end !important;
  gap: .7em;
  padding: .55em .3em !important;
  margin: 0 !important;
  background: none !important;
  border: 0 !important;
  border-bottom: 1px dashed rgba(26, 26, 26, .16) !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  text-align: left !important;
}
.xt-content .xt-grid-stat-label {
  flex: none;
  font-family: var(--f-title);
  font-size: 3cqw !important; font-weight: 700;
  letter-spacing: .1em;
  color: var(--ito) !important;
  opacity: 1 !important;
  text-transform: none !important;
}
.xt-content .xt-grid-stat-value {
  font-family: var(--f-body);
  font-size: 2.75cqw !important; font-weight: 400 !important;
  line-height: 1.5;
  color: var(--sumi) !important;
}
.xt-content .xt-grid-3 .xt-grid-stat { flex-direction: column-reverse !important; align-items: center !important; gap: .25em; border: 0 !important; }
.xt-content .xt-grid-3 .xt-grid-stat-label { font-size: 2.3cqw !important; font-weight: 400; color: var(--sumi-3) !important; }
.xt-content .xt-grid-3 .xt-grid-stat-value { font-family: var(--f-title); font-size: 3.6cqw !important; font-weight: 700 !important; }
/* ── ③ 絵馬：五角木牌 + 计划表，做到的被红线划掉 ── */
.xt-content .xt-text-emaWish {
  left: 12%; right: 12%; top: 21%;
  text-align: center;
  font-family: var(--f-title);
  font-size: 6cqw; font-weight: 700; line-height: 1.5; letter-spacing: .1em;
}
.xt-content .xt-text-emaWish::before {
  content: "奉 納";
  display: block;
  margin-bottom: .5em;
  font-size: .5em; font-weight: 400; letter-spacing: .6em;
  color: var(--ito);
}
.xt-content .xt-list {
  left: 15%; right: 15%; top: 39%;
  display: flex !important; flex-direction: column; gap: 0 !important;
  list-style: none;
}
.xt-content .xt-list-item {
  display: flex !important; align-items: baseline; gap: .8em;
  padding: .75em 0 !important;
  margin: 0 !important;
  background: none !important;
  border: 0 !important;
  border-bottom: 1px solid rgba(110, 80, 40, .2) !important;
  border-radius: 0 !important;
  font-size: 3.4cqw;
  line-height: 1.5;
}
.xt-content .xt-list-check {
  flex: none;
  width: 2.6cqw !important; height: 2.6cqw !important;
  border: 1px solid var(--sumi-3) !important;
  border-radius: 50% !important;
  background: none !important;
  font-size: 0 !important;
}
.xt-content .xt-list-check::before, .xt-content .xt-list-check::after { content: none !important; }
.xt-content .xt-list-text { position: relative; font-family: var(--f-body); color: var(--sumi) !important; text-decoration: none !important; opacity: 1 !important; }
.xt-content .xt-list-item-on .xt-list-check { background: var(--ito) !important; border-color: var(--ito) !important; box-shadow: inset 0 0 0 2px #f2e4cc; }
.xt-content .xt-list-item-on .xt-list-text { color: var(--sumi-3) !important; }
/* 一根歪歪的红线划掉 */
.xt-content .xt-list-item-on .xt-list-text::after {
  content: "";
  position: absolute;
  left: -.2em; right: -.3em; top: 52%;
  height: 2px;
  background: var(--ito);
  border-radius: 2px;
  rotate: -1.5deg;
  transform-origin: left;
  scale: 0 1;
  transition: scale .6s var(--ease) .9s;
}
#xt-t3:checked ~ .xt-content .xt-list-item-on .xt-list-text::after { scale: 1 1; }

/* ── ④ 花筏：词条卡 ── */
.xt-content .xt-text-hanaSeason {
  left: 13%; top: 11%;
  font-size: 2.7cqw; letter-spacing: .3em;
  color: var(--ito);
}
.xt-content .xt-text-hanaTerm {
  right: 14%; top: 13.5%;
  writing-mode: vertical-rl;
  font-family: var(--f-title);
  font-size: 15cqw; font-weight: 900; line-height: 1; letter-spacing: .05em;
}
.xt-content .xt-text-hanaReading {
  right: 33%; top: 14%;
  writing-mode: vertical-rl;
  font-family: var(--f-soft);
  font-size: 3cqw; letter-spacing: .25em;
  color: var(--sumi-3);
}
.xt-content .xt-text-hanaBody {
  left: 13%; top: 19%;
  width: 46%;
  font-size: 3.1cqw; line-height: 2;
  color: var(--sumi-2);
  text-align: justify;
}
.xt-content .xt-text-hanaBody::first-letter { font-family: var(--f-title); font-size: 2.2em; float: left; line-height: 1; margin: .05em .12em 0 0; color: var(--ito); }
.xt-content .xt-text-hanaWhisper {
  left: 13%; right: 13%; bottom: 12%;
  padding: 1em 0 0 !important;
  border-top: 1px solid rgba(184, 40, 46, .35) !important;
  font-family: var(--f-soft);
  font-size: 3.5cqw; line-height: 1.8;
  color: var(--sumi);
}
.xt-content .xt-text-hanaWhisper::before { content: "── "; color: var(--ito); }

/* ═════════ 长文本适配（v4） ═════════ */
/* 心音：字号缩小、一列能放 13~14 个字，整块水平居中，左右留白对称 */
.xt-content .xt-text-kokoro {
  left: 0; right: 0; top: 18%;
  margin: 0 auto !important;
  width: fit-content;
  height: 47%;
  max-width: 76%;
  font-size: 4.6cqw;
  line-height: 2.1;
  letter-spacing: .1em;
}
.xt-content .xt-text-kokoro::first-letter { font-size: 1.45em; }
/* 御神籤：运势表超出时在框内上下滑动，不再压到下面那一栏 */
.xt-content .xt-grid-2 {
  max-height: 28.5%;
  overflow-y: auto;
  overscroll-behavior: contain;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
  -webkit-mask-image: linear-gradient(#000 calc(100% - 3cqw), transparent);
  mask-image: linear-gradient(#000 calc(100% - 3cqw), transparent);
  padding-bottom: 2.4cqw !important;
}
.xt-content .xt-grid-2::-webkit-scrollbar { display: none; }
#xt-t2:checked ~ .xt-content .xt-grid-2 { pointer-events: auto !important; touch-action: pan-y; }
.xt-content .xt-grid-2 .xt-grid-stat-value { font-size: 2.6cqw !important; }
.xt-content .xt-grid-3 { top: 80.5%; }
.xt-content .xt-grid-3 .xt-grid-stat-value { font-size: 3cqw !important; line-height: 1.35; text-align: center; }

/* ═════════ 动画 ═════════ */
@keyframes itoMist   { from { transform: translate(-3%, -2%) scale(1); } to { transform: translate(4%, 3%) scale(1.08); } }
@keyframes itoFade   { to { opacity: 1; } }
@keyframes itoPop    { from { opacity: 0; translate: 0 1.5cqw; filter: blur(4px); } to { opacity: 1; translate: 0 0; filter: blur(0); } }
@keyframes itoDrift  { from { translate: 0 0; rotate: -2deg; } to { translate: 3cqw -4cqw; rotate: 3deg; } }
@keyframes itoHang   { 0% { opacity: 0; translate: 0 -12cqw; } 60% { opacity: 1; translate: 0 1.2cqw; } 100% { opacity: 1; translate: 0 0; } }
@keyframes itoSwing  { from { rotate: -2.2deg; } to { rotate: 2.2deg; } }
@keyframes itoFlip   { from { transform: perspective(900px) rotateY(-90deg) scale(.6); } to { transform: perspective(900px) rotateY(0) scale(1); } }
@keyframes itoPetal  {
  0%   { transform: translate(0, 0) rotate(0deg) rotateX(0deg); }
  25%  { transform: translate(6cqw, 38cqw) rotate(90deg) rotateX(60deg); }
  50%  { transform: translate(-3cqw, 76cqw) rotate(180deg) rotateX(0deg); }
  75%  { transform: translate(8cqw, 114cqw) rotate(270deg) rotateX(60deg); }
  100% { transform: translate(2cqw, 155cqw) rotate(360deg) rotateX(0deg); }
}

/* 系统「减少动态效果」时：直接显示终态 */
@media (prefers-reduced-motion: reduce) {
  .xt-root::before, .xt-content .xt-tag, .xt-particles-sakura .xt-particle { animation: none !important; }
  .xt-content .xt-tags ~ .xt-tags .xt-tag, .xt-content .xt-footer { opacity: 1; }
  .xt-content [class*="xt-action-"] { animation: none !important; opacity: 1; translate: 0 0; }
}

