@import url('https://fonts.googleapis.com/css2?family=Shippori+Mincho:wght@400;600;800&family=Zen+Old+Mincho:wght@400;700;900&family=Hina+Mincho&display=swap');

/*⁣‌⁠⁠​⁠⁠⁠‌‍‍​​​⁠‍⁠‌‌​‍‍‍‌‌​‌⁠‍⁠⁠‍‌​⁠⁠‍⁠‌‍‌‍⁠​⁠⁠⁠⁠‍​⁠‍‍​​‌‍⁠‌⁠‍​​‌‍⁣ ═════════════════════════════════════════════
   闇い糸 · 病み札  yami   —— 命运，丝线，我和你（解不开了）
   白雾底 / 一根红线从左上绕结后横贯到右 / 四张细长纸札垂挂
   ★ = 可改项（Ctrl+F 搜 ★）
   结构：所有元素都平铺在 .xt-content 里，统一 absolute + 百分比定位
   ═════════════════════════════════════════════ */

.xt-root {
  /* ★ 配色 */
  --ito: #b8282e;            /* 红线 / 朱 */
  --sumi: #1a1a1a;           /* 墨 */
  --sumi-2: #4a4542;
  --sumi-3: #8f8780;
  --washi: #fdfbf6;          /* 札纸 */
  /* （札面线框 / 朱印的颜色写在 deco.py 里：金茶 #a8834a、木色 #8a6a44、樱粉 #c4606e） */
  /* ★ 字体（Google Fonts 免费明朝体，加载失败时回退系统衬线） */
  --f-title: 'Zen Old Mincho', 'Shippori Mincho', 'Songti SC', serif;
  --f-body: 'Shippori Mincho', 'Zen Old Mincho', 'Songti SC', serif;
  --f-soft: 'Hina Mincho', 'Shippori Mincho', serif;
  /* ★ 缓动曲线（札垂落、标题浮现都用它） */
  --ease: cubic-bezier(.22, .8, .24, 1);
  /* ★ 纸纹（SVG 噪点） */
  --paper-noise: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='160' height='160'><filter id='n'><feTurbulence type='fractalNoise' baseFrequency='.9' numOctaves='3' stitchTiles='stitch'/><feColorMatrix values='0 0 0 0 .45  0 0 0 0 .38  0 0 0 0 .3  0 0 0 .16 0'/></filter><rect width='160' height='160' filter='url(%23n)'/></svg>");
  --paper-fiber: repeating-linear-gradient(97deg, rgba(120, 100, 80, .035) 0 1px, transparent 1px 9px),
                 repeating-linear-gradient(3deg, rgba(120, 100, 80, .03) 0 1px, transparent 1px 13px);

  /* 教程里的系统变量全部对齐到本主题：
     系统自带的勾选框、进度条、动画修饰符等都会跟着变成白底墨字朱红 */
  --xt-bg: #fff;
  --xt-text: var(--sumi);
  --xt-text-sub: var(--sumi-2);
  --xt-text-muted: var(--sumi-3);
  --xt-accent: var(--ito);
  --xt-accent-bg: rgba(184, 40, 46, .08);
  --xt-border: rgba(184, 40, 46, .22);
  --xt-radius: 0px;
  --xt-radius-sm: 2px;
  --xt-font: var(--f-body);
  --xt-anim-duration: .7s;
  --xt-anim-easing: var(--ease);
  --xt-stagger-delay: 120ms;
  --xt-glow-color: rgba(184, 40, 46, .3);
  --xt-shadow-sm: 0 1px 3px rgba(60, 40, 30, .10);
  --xt-shadow-md: .8cqw 2.6cqw 3cqw -1cqw rgba(60, 40, 30, .22);
  --xt-shadow-lg: 0 4cqw 8cqw -2cqw rgba(60, 40, 30, .25);

  position: relative;
  isolation: isolate;
  width: 100%;
  aspect-ratio: 100 / 147;
  height: auto;
  padding: 0 !important;
  overflow: hidden;
  background: #fff !important;
  border: 0 !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  container-type: inline-size;
  font-family: var(--f-body);
  color: var(--sumi);
  /* 四边羽化：没有硬边框，白雾直接散进聊天背景 */
  -webkit-mask-image: linear-gradient(to right, transparent, #000 5%, #000 95%, transparent), linear-gradient(to bottom, transparent, #000 3.5%, #000 96.5%, transparent);
  -webkit-mask-composite: source-in;
  mask-image: linear-gradient(to right, transparent, #000 5%, #000 95%, transparent), linear-gradient(to bottom, transparent, #000 3.5%, #000 96.5%, transparent);
  mask-composite: intersect;
}
/* ── 雾：三团极淡的灰粉雾气缓慢漂移（transform 动画，手机上不卡） ── */
.xt-root::before {
  content: "";
  position: absolute;
  inset: -25%;
  z-index: 0;
  pointer-events: none;
  background:
    radial-gradient(38% 30% at 26% 30%, rgba(214, 196, 190, .38), transparent 70%),
