    radial-gradient(42% 26% at 50% 88%, rgba(205, 205, 212, .30), transparent 72%),
    radial-gradient(30% 22% at 82% 18%, rgba(240, 222, 214, .35), transparent 70%);
  animation: itoMist 28s ease-in-out infinite alternate;
}
/* 左边缘：一列极淡的竖排小字，代替边框 */
.xt-root::after {
  content: "しゅう・しばり・くさり・とわ・にがさない・しゅう・しばり・くさり・とわ・にがさない・しゅう";
