  font-size: 2.6cqw;
  font-weight: 400;
  letter-spacing: .2em;
  color: var(--ito);
  text-shadow: none;
  background: rgba(255, 255, 255, .7);
}
/* 打开后的绘马：五角形木牌 */
#xt-t3:checked ~ .xt-content .xt-action-3 {
