.xt-content .xt-list-check::before, .xt-content .xt-list-check::after { content: none !important; }
.xt-content .xt-list-text { position: relative; font-family: var(--f-body); color: var(--sumi) !important; text-decoration: none !important; opacity: 1 !important; }
.xt-content .xt-list-item-on .xt-list-check { background: var(--ito) !important; border-color: var(--ito) !important; box-shadow: inset 0 0 0 2px #f2e4cc; }
.xt-content .xt-list-item-on .xt-list-text { color: var(--sumi-3) !important; }
/* 一根歪歪的红线划掉 */
.xt-content .xt-list-item-on .xt-list-text::after {
  content: "";
  position: absolute;
  left: -.2em; right: -.3em; top: 52%;
  height: 2px;
  background: var(--ito);
  border-radius: 2px;
  rotate: -1.5deg;
  transform-origin: left;
  scale: 0 1;
  transition: scale .6s var(--ease) .9s;
}
#xt-t3:checked ~ .xt-content .xt-list-item-on .xt-list-text::after { scale: 1 1; }

/* ── ④ 花筏：词条卡 ── */
.xt-content .xt-text-hanaSeason {
  left: 13%; top: 11%;
  font-size: 2.7cqw; letter-spacing: .3em;
  color: var(--ito);
}
.xt-content .xt-text-hanaTerm {
  right: 14%; top: 13.5%;
  writing-mode: vertical-rl;
  font-family: var(--f-title);
  font-size: 15cqw; font-weight: 900; line-height: 1; letter-spacing: .05em;
}
.xt-content .xt-text-hanaReading {
  right: 33%; top: 14%;
  writing-mode: vertical-rl;
  font-family: var(--f-soft);
  font-size: 3cqw; letter-spacing: .25em;
  color: var(--sumi-3);
}
.xt-content .xt-text-hanaBody {
  left: 13%; top: 19%;
  width: 46%;
  font-size: 3.1cqw; line-height: 2;
  color: var(--sumi-2);
  text-align: justify;
}
.xt-content .xt-text-hanaBody::first-letter { font-family: var(--f-title); font-size: 2.2em; float: left; line-height: 1; margin: .05em .12em 0 0; color: var(--ito); }
.xt-content .xt-text-hanaWhisper {
  left: 13%; right: 13%; bottom: 12%;
  padding: 1em 0 0 !important;
  border-top: 1px solid rgba(184, 40, 46, .35) !important;
  font-family: var(--f-soft);
  font-size: 3.5cqw; line-height: 1.8;
  color: var(--sumi);
}
.xt-content .xt-text-hanaWhisper::before { content: "── "; color: var(--ito); }

/* ═════════ 长文本适配（v4） ═════════ */
/* 心音：字号缩小、一列能放 13~14 个字，整块水平居中，左右留白对称 */
.xt-content .xt-text-kokoro {
  left: 0; right: 0; top: 18%;
  margin: 0 auto !important;
  width: fit-content;
  height: 47%;
  max-width: 76%;
  font-size: 4.6cqw;
  line-height: 2.1;
  letter-spacing: .1em;
}
.xt-content .xt-text-kokoro::first-letter { font-size: 1.45em; }
/* 御神籤：运势表超出时在框内上下滑动，不再压到下面那一栏 */
.xt-content .xt-grid-2 {
  max-height: 28.5%;
  overflow-y: auto;
  overscroll-behavior: contain;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
  -webkit-mask-image: linear-gradient(#000 calc(100% - 3cqw), transparent);
  mask-image: linear-gradient(#000 calc(100% - 3cqw), transparent);
  padding-bottom: 2.4cqw !important;
}
.xt-content .xt-grid-2::-webkit-scrollbar { display: none; }
#xt-t2:checked ~ .xt-content .xt-grid-2 { pointer-events: auto !important; touch-action: pan-y; }
.xt-content .xt-grid-2 .xt-grid-stat-value { font-size: 2.6cqw !important; }
.xt-content .xt-grid-3 { top: 80.5%; }
.xt-content .xt-grid-3 .xt-grid-stat-value { font-size: 3cqw !important; line-height: 1.35; text-align: center; }

/* ═════════ 动画 ═════════ */
@keyframes itoMist   { from { transform: translate(-3%, -2%) scale(1); } to { transform: translate(4%, 3%) scale(1.08); } }
@keyframes itoFade   { to { opacity: 1; } }
@keyframes itoPop    { from { opacity: 0; translate: 0 1.5cqw; filter: blur(4px); } to { opacity: 1; translate: 0 0; filter: blur(0); } }
@keyframes itoDrift  { from { translate: 0 0; rotate: -2deg; } to { translate: 3cqw -4cqw; rotate: 3deg; } }
@keyframes itoHang   { 0% { opacity: 0; translate: 0 -12cqw; } 60% { opacity: 1; translate: 0 1.2cqw; } 100% { opacity: 1; translate: 0 0; } }
@keyframes itoSwing  { from { rotate: -2.2deg; } to { rotate: 2.2deg; } }
@keyframes itoFlip   { from { transform: perspective(900px) rotateY(-90deg) scale(.6); } to { transform: perspective(900px) rotateY(0) scale(1); } }
@keyframes itoPetal  {
  0%   { transform: translate(0, 0) rotate(0deg) rotateX(0deg); }
  25%  { transform: translate(6cqw, 38cqw) rotate(90deg) rotateX(60deg); }
  50%  { transform: translate(-3cqw, 76cqw) rotate(180deg) rotateX(0deg); }
  75%  { transform: translate(8cqw, 114cqw) rotate(270deg) rotateX(60deg); }
  100% { transform: translate(2cqw, 155cqw) rotate(360deg) rotateX(0deg); }
}

/* 系统「减少动态效果」时：直接显示终态 */
@media (prefers-reduced-motion: reduce) {
  .xt-root::before, .xt-content .xt-tag, .xt-particles-sakura .xt-particle { animation: none !important; }
  .xt-content .xt-tags ~ .xt-tags .xt-tag, .xt-content .xt-footer { opacity: 1; }
  .xt-content [class*="xt-action-"] { animation: none !important; opacity: 1; translate: 0 0; }
}

/* ═════════════════════════════════════════════
   闇 · 暗色覆盖层   —— もう、ほどかせない。
   墨黑底 / 暗红雾 / 心跳般搏动的红线 / 血与灰的花瓣 / 黑纸札
   以下规则覆盖上面亮色版的同名规则；★ = 可改项
   ═════════════════════════════════════════════ */
.xt-root {
  /* ★ 配色：暗色版里「墨」变成骨白，「纸」变成墨 */
  --ito: #c8202c;            /* 红线 / 血 */
  --sumi: #ece3df;           /* 骨白（正文） */
  --sumi-2: #b5aaa6;
  --sumi-3: #776c69;
  --washi: #171213;          /* 黑札纸 */
  --yoru: #0c090a;           /* 夜 */
  /* 纸纹在黑纸上改成极淡的浅色噪点 */
  --paper-noise: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='160' height='160'><filter id='n'><feTurbulence type='fractalNoise' baseFrequency='.9' numOctaves='3' stitchTiles='stitch'/><feColorMatrix values='0 0 0 0 .95  0 0 0 0 .88  0 0 0 0 .85  0 0 0 .07 0'/></filter><rect width='160' height='160' filter='url(%23n)'/></svg>");
  --paper-fiber: repeating-linear-gradient(97deg, rgba(255, 235, 225, .025) 0 1px, transparent 1px 9px),
                 repeating-linear-gradient(3deg, rgba(255, 235, 225, .02) 0 1px, transparent 1px 13px);

  --xt-bg: var(--yoru);
  --xt-accent-bg: rgba(200, 32, 44, .12);
  --xt-border: rgba(200, 32, 44, .3);
  --xt-glow-color: rgba(220, 30, 44, .5);
  --xt-shadow-sm: 0 1px 3px rgba(0, 0, 0, .5);
  --xt-shadow-md: .8cqw 2.6cqw 3.4cqw -1cqw rgba(0, 0, 0, .85);
  --xt-shadow-lg: 0 4cqw 8cqw -2cqw rgba(0, 0, 0, .9);

  background: radial-gradient(120% 75% at 45% 0%, #1c1012 0%, #0c090a 55%, #060405 100%) !important;
}
/* 雾：暗红与灰黑交错 */
.xt-root::before {
  background:
    radial-gradient(38% 30% at 22% 26%, rgba(120, 14, 24, .34), transparent 70%),
    radial-gradient(34% 28% at 76% 60%, rgba(90, 8, 18, .30), transparent 70%),
    radial-gradient(42% 26% at 50% 90%, rgba(40, 32, 36, .55), transparent 72%),
    radial-gradient(30% 22% at 84% 16%, rgba(70, 20, 28, .35), transparent 70%);
}
.xt-root::after { color: rgba(236, 227, 223, .2); }
.xt-content::after { color: rgba(220, 40, 52, .4); }

/* 红线：发光 + 心跳（咚、咚……停顿） */
.xt-content::before {
  filter: drop-shadow(0 0 1px rgba(255, 60, 70, .55)) drop-shadow(0 0 3px rgba(200, 20, 35, .35));
  animation: yamiBeat 3.6s ease-in-out 3s infinite;
}
.xt-content .xt-footer { color: var(--sumi-3) !important; }

/* ── 花瓣：血色（近）/ 暗红（中）/ 灰烬（远） ── */
.xt-particles-sakura .xt-particle {
  background: linear-gradient(135deg, #9a1622 0%, #5c0a12 60%, #2a0407 100%) !important;
  box-shadow: inset 1px 1px 2px rgba(255, 90, 100, .22) !important;
  opacity: .72;
}
.xt-particles-sakura .xt-particle:nth-child(3n) {
  background: linear-gradient(135deg, #5d5052 0%, #2c2426 80%) !important;
  box-shadow: none !important;
}
.xt-particles-sakura .xt-particle:nth-child(5n+1) {
  background: linear-gradient(135deg, #e8343f 0%, #a3121d 45%, #4a050b 100%) !important;
  box-shadow: inset 1px 1px 3px rgba(255, 150, 160, .35), 0 0 1.4cqw rgba(220, 30, 44, .4) !important;
}

/* ── 背景浮动字：骨白 / 血红的极淡字 ── */
.xt-content .xt-tags:not(.xt-tags ~ .xt-tags) .xt-tag { color: rgba(236, 227, 223, .11) !important; }
.xt-content .xt-tags:not(.xt-tags ~ .xt-tags) .xt-tag:nth-child(2)  { color: transparent !important; -webkit-text-stroke: .7px rgba(230, 50, 62, .5); }
.xt-content .xt-tags:not(.xt-tags ~ .xt-tags) .xt-tag:nth-child(4)  { color: rgba(236, 227, 223, .14) !important; }
.xt-content .xt-tags:not(.xt-tags ~ .xt-tags) .xt-tag:nth-child(5)  { color: transparent !important; -webkit-text-stroke: .7px rgba(236, 227, 223, .32); }
.xt-content .xt-tags:not(.xt-tags ~ .xt-tags) .xt-tag:nth-child(7)  { color: rgba(210, 36, 48, .24) !important; }
.xt-content .xt-tags:not(.xt-tags ~ .xt-tags) .xt-tag:nth-child(8)  { color: rgba(210, 36, 48, .12) !important; }
.xt-content .xt-tags:not(.xt-tags ~ .xt-tags) .xt-tag:nth-child(10) { color: transparent !important; -webkit-text-stroke: .7px rgba(236, 227, 223, .28); }

/* ── 标题拼贴 ── */
/* 命：骨白大字 + 错位的血色残影 */
.xt-content .xt-tags ~ .xt-tags .xt-tag:nth-child(1) { text-shadow: .7cqw .5cqw 0 rgba(200, 32, 44, .42); }
/* 運：空心字发一点红光 */
.xt-content .xt-tags ~ .xt-tags .xt-tag:nth-child(2) { -webkit-text-stroke: .9px #e0303c; filter: drop-shadow(0 0 1.2cqw rgba(220, 30, 44, .35)); }
/* の：血红圆印，黑字 */
.xt-content .xt-tags ~ .xt-tags .xt-tag:nth-child(3) { color: var(--yoru) !important; box-shadow: 0 0 2.4cqw rgba(220, 30, 44, .5) !important; }
/* 糸：亮红渐变 + 辉光 */
.xt-content .xt-tags ~ .xt-tags .xt-tag:nth-child(4) {
  background: linear-gradient(170deg, #ff5560 5%, #c0182a 50%, #50060d 100%) !important;
  -webkit-background-clip: text !important; background-clip: text !important;
  filter: drop-shadow(0 0 1.6cqw rgba(220, 30, 44, .45));
}
/* もう、ほどかせない。：字数变少，拉开字距 */
.xt-content .xt-tags ~ .xt-tags .xt-tag:nth-child(5) { letter-spacing: .6em; }
/* 縛：暗红、虚 */
.xt-content .xt-tags ~ .xt-tags .xt-tag:nth-child(7) { color: #8a1c26 !important; filter: blur(.4px) drop-shadow(0 0 1cqw rgba(200, 32, 44, .5)); }
/* 你：马克笔更浓 */
.xt-content .xt-tags ~ .xt-tags .xt-tag:nth-child(8) {
  background: linear-gradient(transparent 62%, rgba(200, 32, 44, .55) 62%, rgba(200, 32, 44, .55) 90%, transparent 90%) !important;
}
.xt-content .xt-tags ~ .xt-tags .xt-tag:nth-child(9) { color: #e0303c !important; }

/* ═════════ 札：黑纸 ═════════ */
.xt-content [class*="xt-action-"] {
  background:
    var(--deco) 0 0 / 100% 100% no-repeat,
    var(--knot) 50% 2.6% / 6.4cqw auto no-repeat,
    linear-gradient(var(--ito), var(--ito)) 0 0 / 100% 2.2% no-repeat,
    var(--paper-fiber),
    var(--paper-noise),
    linear-gradient(176deg, #211a1b 0%, #161112 55%, #0e0a0b 100%) !important;
  box-shadow:
    0 1px 1px rgba(0, 0, 0, .6),
    .8cqw 2.6cqw 3.4cqw -1cqw rgba(0, 0, 0, .85),
    0 0 3.4cqw -1.4cqw rgba(200, 30, 44, .4),
    inset 0 0 0 1px rgba(236, 227, 223, .07),
    inset -.6cqw 0 1.2cqw -.6cqw rgba(0, 0, 0, .45) !important;
}
/* 縁切：焦黑木牌 */
.xt-content .xt-action-3 {
  background:
    var(--deco) 0 0 / 100% 100% no-repeat,
    var(--knot) 50% 2.6% / 6.4cqw auto no-repeat,
    repeating-linear-gradient(91deg, rgba(255, 220, 190, .035) 0 1px, transparent 1px 5px),
    var(--paper-noise),
    linear-gradient(176deg, #2a1d17, #170f0c) !important;
}
/* 彼岸花：暗紫红 */
.xt-content .xt-action-4 {
  background:
    var(--deco) 0 0 / 100% 100% no-repeat,
    var(--knot) 50% 2.6% / 6.4cqw auto no-repeat,
    linear-gradient(var(--ito), var(--ito)) 0 0 / 100% 2.2% no-repeat,
    var(--paper-fiber),
    var(--paper-noise),
    linear-gradient(176deg, #241216, #140a0c) !important;
}
/* 札面标题：骨白字 + 血色辉光 */
.xt-content [class*="xt-action-"]::after {
  text-shadow: .25cqw .3cqw 0 rgba(200, 32, 44, .45), 0 0 1.6cqw rgba(220, 30, 44, .45);
}
/* ✕ 关闭键 → 「逃げてみる？」（试着逃跑看看？） */
#xt-t1:checked ~ .xt-content .xt-action-1::after,
#xt-t2:checked ~ .xt-content .xt-action-2::after,
#xt-t3:checked ~ .xt-content .xt-action-3::after,
#xt-t4:checked ~ .xt-content .xt-action-4::after {
  content: "✕  逃げてみる？";
  background: rgba(12, 9, 10, .75);
  border-color: rgba(220, 40, 52, .6);
  color: #e0303c;
}

/* ═════════ 札内内容的细节色 ═════════ */
.xt-content .xt-text-kokoro::first-letter { text-shadow: 0 0 1.4cqw rgba(220, 30, 44, .55); }
.xt-content .xt-text-kokoroJa { border-top-color: rgba(236, 227, 223, .14) !important; }
.xt-content .xt-text-kujiRank { box-shadow: 0 0 2.4cqw -.4cqw rgba(220, 30, 44, .55) !important; text-shadow: 0 0 1.2cqw rgba(220, 30, 44, .5); }
.xt-content .xt-grid-stat { border-bottom-color: rgba(236, 227, 223, .12) !important; }
.xt-content .xt-text-emaWish::before { content: "縁 切 祈 願"; }
.xt-content .xt-list-item { border-bottom-color: rgba(236, 227, 223, .12) !important; }
.xt-content .xt-list-item-on .xt-list-check { box-shadow: inset 0 0 0 2px #1b1415; }
.xt-content .xt-list-item-on .xt-list-text::after { box-shadow: 0 0 .8cqw rgba(220, 30, 44, .6); }
.xt-content .xt-text-hanaTerm { text-shadow: .5cqw .4cqw 0 rgba(200, 32, 44, .4); }

@keyframes yamiBeat {
  0%, 30%, 100% { filter: drop-shadow(0 0 1px rgba(255, 60, 70, .55)) drop-shadow(0 0 3px rgba(200, 20, 35, .35)); }
  8%            { filter: drop-shadow(0 0 1.6px rgba(255, 70, 80, .9)) drop-shadow(0 0 7px rgba(220, 20, 35, .7)); }
  16%           { filter: drop-shadow(0 0 1px rgba(255, 60, 70, .6)) drop-shadow(0 0 3.5px rgba(200, 20, 35, .4)); }
  22%           { filter: drop-shadow(0 0 1.4px rgba(255, 70, 80, .8)) drop-shadow(0 0 5.5px rgba(220, 20, 35, .6)); }
}
@media (prefers-reduced-motion: reduce) {
  .xt-content::before { animation: none !important; }
}

