value.layout:
# ═══ 闇い糸 · 病み札  yami ═══
# 结构说明：所有指令都写在顶层（@toggle 放进 @card 里会点不开）
# 第 1 组 @tags = 背景浮动字；第 2 组 @tags = 标题拼贴字
# 札 1 本音 / 2 凶籤 / 3 縛り絵馬 / 4 彼岸花，每张札 = @toggle N + 它的内容

@particles sakura 18

@tags
  "執"
  "縛"
  "囚"
  "糸"
  "鎖"
  "独"
  "渇"
  "蝕"
  "狂"
  "永"

@tags
  "命"
  "運"
  "の"
  "糸"
  "もう、ほどかせない。"
  "我"
  "縛"
  "你"
  "UNMEI · ITO · NIGASANAI"

@toggle 1
  @divider
⁣‌⁠⁠​⁠⁠⁠‌‍‍​​​⁠‍⁠‌‌​‍‍‍‌‌​‌⁠‍⁠⁠‍‌​⁠⁠‍⁠‌‍‌‍⁠​⁠⁠⁠⁠‍​⁠‍‍​​‌‍⁠‌⁠‍​​‌‍⁣@text kokoroAuthor
@text kokoro
@text kokoroJa

@toggle 2
  @divider
@text kujiNo
@text kujiRank
@text kujiPoem
@text kujiPoemNote
@grid 2
  kujiWish:stat "願望"
  kujiWait:stat "待人"
  kujiLost:stat "失物"
  kujiLove:stat "恋愛"
  kujiEn:stat "縁談"
  kujiTravel:stat "旅行"
  kujiStudy:stat "学問"
  kujiHealth:stat "病気"
@grid 3
  luckyItem:stat "呪いの品"
  luckyColor:stat "宿命の色"
  luckyDir:stat "逃げ道"

@toggle 3
  @divider
@text emaWish
@list
  ema1
  ema2
  ema3
  ema4
  ema5

@toggle 4
  @divider
@text hanaTerm
@text hanaReading
@text hanaSeason
@text hanaBody
@text hanaWhisper

@footer 執 · 絲 · 縛

