  width: 100% !important;
  max-width: 390px !important;
  margin: 8px auto !important;
  background: var(--bg-main) !important;
  color: var(--tx-main) !important;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif !important;
  border-radius: 0px !important;
  border: 1px solid var(--bd-line) !important;
  position: relative !important;
  overflow: hidden !important;
}

/* ── 4. 自动跟随 iOS 系统深色模式 ── */
@media (prefers-color-scheme: dark) {
  .xt-root {
    --bg-main: #1C1C1E;
    --bg-sub: #2C2C2E;
    --bg-pin: #252528;
    --bg-sub-btn: #FFFFFF;
    --tx-main: #F2F2F7;
    --tx-sub: #98989D;
    --tx-desc: #D1D1D6;
    --bd-line: #2C2C2E;
    --bd-soft: #262629;
    --th-border: 1.5px solid rgba(255, 255, 255, 0.88);
    --svg-filter: invert(0.95) hue-rotate(180deg);
  }
}

.xt-content {
  display: flex !important;
  flex-direction: column !important;
  width: 100% !important;
  padding-top: 38px !important;
  background: var(--bg-main) !important;
  color: var(--tx-main) !important;
  position: relative !important;
}

/* ── 5. 顶部固定状态栏（底色与机身一致，只对纯图标层反色，绝不穿模） ── */
.xt-content::before {
  content: "" !important;
  display: block !important;
  position: absolute !important;
  top: 0 !important;
  left: 0 !important;
  width: 100% !important;
  height: 38px !important;
  background-color: transparent !important;
  background-image: var(--svg-back), var(--svg-top-right) !important;
  background-repeat: no-repeat, no-repeat !important;
  background-size: 19px 19px, 54px 19px !important;
  background-position: 12px center, right 12px center !important;
  filter: var(--svg-filter) !important;
  pointer-events: none !important;
  z-index: 15 !important;
}

/* ── 6. 页面滚动容器 ── */
.xt-collapse {
  width: 100% !important;
  margin: 0 !important;
  padding: 0 !important;
  background: var(--bg-main) !important;
  border-top: 1px solid var(--bd-line) !important;
}
.xt-collapse-body,
.xt-collapse.collapsed .xt-collapse-body,
.xt-collapse.is-collapsed .xt-collapse-body,
.xt-collapse.closed .xt-collapse-body,
.xt-collapse[aria-expanded="false"] .xt-collapse-body,
.xt-collapse[data-collapsed="true"] .xt-collapse-body,
.xt-collapse-body[hidden],
.xt-collapse-body[aria-hidden="true"] {
  display: block !important;
  visibility: visible !important;
  opacity: 1 !important;
  width: 100% !important;
  height: 496px !important;
  max-height: 496px !important;
  overflow-y: auto !important;
  overflow-x: hidden !important;
  -webkit-overflow-scrolling: touch !important;
  scrollbar-width: none !important;
  background-color: var(--bg-main) !important;
  padding: 0 0 36px 0 !important;
  margin: 0 !important;
  transform: none !important;
  transition: none !important;
}
.xt-collapse-body::-webkit-scrollbar {
  display: none !important;
  width: 0 !important;
}

.xt-collapse-5 { display: block !important; }
.xt-collapse-1, .xt-collapse-2, .xt-collapse-3, .xt-collapse-4 { display: none !important; }

#xt-t1:checked ~ .xt-content .xt-collapse-5,
#xt-t2:checked ~ .xt-content .xt-collapse-5,
#xt-t3:checked ~ .xt-content .xt-collapse-5,
#xt-t4:checked ~ .xt-content .xt-collapse-5 { display: none !important; }

#xt-t1:checked ~ .xt-content .xt-collapse-1 { display: block !important; }
#xt-t2:checked ~ .xt-content .xt-collapse-2 { display: block !important; }
#xt-t3:checked ~ .xt-content .xt-collapse-3 { display: block !important; }
#xt-t4:checked ~ .xt-content .xt-collapse-4 { display: block !important; }

/* ── 7. 频道主页：横幅与个人信息 ── */
.xt-collapse-5 .xt-collapse-body::before {
  content: "" !important;
  display: block !important;
  width: calc(100% - 16px) !important;
  height: 80px !important;
  margin: 8px 8px 0 8px !important;
  background-position: center !important;
  background-size: cover !important;
  background-repeat: no-repeat !important;
  border-radius: 10px !important;
}

.xt-collapse-5 .xt-header {
  display: flex !important;
  gap: 10px !important;
  align-items: flex-start !important;
  padding: 10px 12px 0 12px !important;
}
.xt-collapse-5 .xt-avatar {
  width: 50px !important;
  height: 50px !important;
  border-radius: 50% !important;
  object-fit: cover !important;
  flex-shrink: 0 !important;
  border: 1px solid var(--bd-line) !important;
}
.xt-collapse-5 .xt-name {
  display: inline-flex !important;
  align-items: center !important;
  gap: 4px !important;
  font-size: 15px !important;
  font-weight: 800 !important;
  color: var(--tx-main) !important;
  line-height: 1.2 !important;
  margin-top: 2px !important;
}
.xt-collapse-5 .xt-name::after {
  content: "" !important;
  display: inline-block !important;
  width: 12px !important;
  height: 12px !important;
  flex-shrink: 0 !important;
  background: var(--svg-vf) no-repeat center / 12px 12px !important;
  filter: var(--svg-filter) !important;
}

.xt-text-chDesc {
  display: block !important;
  padding: 4px 12px 0 12px !important;
  font-size: 11px !important;
  font-weight: 600 !important;
  color: var(--tx-desc) !important;
  line-height: 1.45 !important;
}
.xt-text-chDesc::before {
  content: "@private_channel\A 9.9M subscribers · 4 videos" !important;
  white-space: pre !important;
  display: block !important;
  margin-top: -32px !important;
  margin-left: 60px !important;
  margin-bottom: 10px !important;
  font-size: 10px !important;
  font-weight: 700 !important;
  color: var(--tx-sub) !important;
  line-height: 1.35 !important;
}

/* 外链独立成行，绝不与下方胶囊挤压 */
.xt-text-chLink {
  display: block !important;
  margin: 4px 12px 6px 12px !important;
  padding-left: 14px !important;
  font-size: 10px !important;
  font-weight: 700 !important;
  line-height: 1.3 !important;
  color: var(--tx-sub) !important;
  background: var(--svg-link) no-repeat left center / 10px 10px !important;
}

/* ── 8. 频道主页：订阅条（::before 独立不反色）与分类栏（::after 独立反色） ── */
.xt-collapse-5 .xt-divider {
  display: block !important;
  width: 100% !important;
  height: 98px !important;
  margin: 4px 0 4px 0 !important;
  position: relative !important;
  background: none !important;
}

/* Subscribed 胶囊：日间浅灰底黑字，夜间纯白底黑字黑UI，绝不与上方链接挤在一起！ */
.xt-collapse-5 .xt-divider::before {
  content: "Subscribed" !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  margin: 0 12px !important;
  height: 30px !important;
  background-color: var(--bg-sub-btn) !important;
  background-image: var(--img-sub-bell), var(--img-sub-arr) !important;
  background-repeat: no-repeat, no-repeat !important;
  background-size: 14px 14px, 10px 10px !important;
  background-position: calc(50% - 44px) center, calc(50% + 44px) center !important;
  border-radius: 16px !important;
  font-size: 12px !important;
  font-weight: 800 !important;
  color: #000000 !important;
}

/* 分类栏与排序胶囊：独立放在 ::after 上，夜间正常反色 */
.xt-collapse-5 .xt-divider::after {
  content: "" !important;
  display: block !important;
  width: 100% !important;
  height: 62px !important;
  margin-top: 6px !important;
  background-color: transparent !important;
  background-image: var(--svg-tabs-and-sort) !important;
  background-repeat: no-repeat !important;
  background-position: left bottom !important;
  background-size: 380px 62px !important;
  filter: var(--svg-filter) !important;
}

/* ── 9. 频道主页：视频列表 ── */
.xt-collapse-5 .xt-text-v1Title,
.xt-collapse-5 .xt-text-v2Title,
.xt-collapse-5 .xt-text-v3Title,
.xt-collapse-5 .xt-text-v4Title {
  display: block !important;
  position: relative !important;
  padding: 2px 12px 0 142px !important;
  min-height: 22px !important;
